@app.post("/api/pantry/commission")
async def pantry_commission_api(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """#893: MAKE ANOTHER ONE OF THESE — {"kind": "manager", "count": 1}.

    Named by ROAD rather than by an entry of the hour, because the
    operator was clicking the PREPARED, BY KIND counts: "I see some of
    these are empty and I want to have some actually made for those".
    Same road, same window, same spare engine slot as the keeper's own
    work — it takes its turn and the live round never waits on it.

    Comes back at once with a ticket; poll
    GET /api/schedule/segment/generate/{job}."""
    require_auth(authorization)
    payload = await request.json()
    if not isinstance(payload, dict):
        raise HTTPException(status_code=400, detail="Expected an object")
    kind = str(payload.get("kind") or "").strip()[:24]
    # Deliberately NOT `if not alt_prep_road(kind)`: that call BUILDS the
    # coroutine, and testing it for truthiness and dropping it leaves an
    # un-awaited coroutine behind on every refused request.
    if kind not in ALT_PREP_KINDS:
        raise HTTPException(
            status_code=400,
            detail=(f"there is no preparing road for {kind!r} — "
                    + (CANNOT_PREPARE.get(kind)
                       or "nothing on the board writes that ahead")))
    try:
        count = max(1, min(ALT_GEN_MOST, int(payload.get("count") or 1)))
    except (TypeError, ValueError):
        count = 1
    job = uuid.uuid4().hex[:12]
    alt_job_put(job, kind=kind, count=count, state="queued", made=0,
                new=[], why="")
    asyncio.create_task(alt_generate_job(job, kind, count))
    note_action(f"🗓 another {SHELF_LABEL.get(kind, kind)} was "
                "commissioned from the pantry (#893)")
    return {"job": job, "kind": kind, "count": count,
            "label": SHELF_LABEL.get(kind, kind),
            "watch": f"/api/schedule/segment/generate/{job}"}


@app.get("/api/schedule/segment")
async def schedule_segment_api(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """#926: EVERYTHING STACKED UP BEHIND ONE ENTRY OF THE HOUR.

        ?kind=<kind>&hour=YYYY-MM-DDTHH&slot=<slot id>

    Name the entry (hour + slot) and this answers with every prepared
    candidate that entry could air: a stable id, a preview of the script,
    how many lines it is, how much finished audio it already has, when it
    was written, and which one is PINNED. `kind` alone answers for a road
    without naming an entry; hour defaults to the one on air.

    The list comes back IN AIR ORDER — pinned, then priority, then oldest
    — which is the order shelf_take() itself will consider them in."""
    require_read_auth(authorization)
    query = request.query_params
    return alt_segment_view(
        str(query.get("hour") or query.get("key") or ""),
        str(query.get("slot") or query.get("slot_id") or ""),
        str(query.get("kind") or ""))


@app.post("/api/schedule/segment/pin")
async def schedule_segment_pin_api(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """#926: CHOOSE which prepared candidate this entry airs.

    {"hour": "2026-08-19T22", "slot": "hour-03", "shelf_id": "gallery-…"}

    The hour is materialised as its own orders in the same breath, the
    way scripting an entry's prompt does — a pin is that hour's business
    and nobody else's. Send "shelf_id": null to unpin.

    A pin is a PREFERENCE, not a promise: if that candidate has burned,
    been taken, or had its audio pruned by the time the entry comes
    round, the ordinary take runs and the segment airs anyway."""
    require_auth(authorization)
    payload = await request.json()
    if not isinstance(payload, dict):
        raise HTTPException(status_code=400, detail="Expected an object")
    key = str(payload.get("hour") or payload.get("key")
              or "").strip() or _sched_hour_key()
    if not _sched_is_hour_key(key):
        raise HTTPException(
            status_code=400,
            detail="hour must be a local hour like 2026-08-19T22")
    slot_id = str(payload.get("slot") or payload.get("slot_id")
                  or "").strip()[:48]
    if not slot_id:
        raise HTTPException(status_code=400, detail="slot is required")
    raw = payload.get("shelf_id", payload.get("id"))
    want = "" if raw in (None, "", False) else str(raw).strip()[:64]
    with _SCHEDULE_LOCK:
        store = schedule_read()
        rows, at = alt_slot_of(store, key, slot_id)
        if at is None:
            raise HTTPException(
                status_code=404,
                detail=f"No entry {slot_id!r} in the hour {key}")
        prep = alt_prep_kind(str(rows[at].get("kind") or ""))
        if want:
            if not prep:
                raise HTTPException(
                    status_code=400,
                    detail=alt_refusal(str(rows[at].get("kind") or "")))
            found = next((r for r in alt_candidates(prep)
                          if alt_sid(prep, r) == want), None)
            if found is None:
                raise HTTPException(
                    status_code=404,
                    detail=f"No prepared {SHELF_LABEL.get(prep, prep)} "
                           f"called {want!r} — it may have aired, been "
                           "discarded, or burned off the shelf")
        rows[at]["pinned_id"] = want or None
        alt_hour_write(store, key, rows)
    alt_pin_forget()                    # the air road re-reads at once
    label = str(rows[at].get("label") or prep or slot_id)
    note_action("🗓 " + (f"alternate pinned: {label[:40]} — {key}"
                         if want else
                         f"alternate unpinned: {label[:40]} — {key}")
                + " (#926)")
    pipeline_log("lookahead",
                 (f"{label[:40]} at {key[11:13]}:00 will air the alternate "
                  f"{want} — unless it has burned by then, in which case "
                  "the best prepared one goes out (#926)")
                 if want else
                 f"{label[:40]} at {key[11:13]}:00 is back on the ordinary "
                 "take (#926)")
    return alt_segment_view(key, slot_id)


@app.post("/api/schedule/segment/generate")
async def schedule_segment_generate_api(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """#926: WRITE MORE CANDIDATES for this entry, right now.

    {"hour": "2026-08-19T22", "slot": "hour-03", "count": 1..3}

    Comes back AT ONCE with a ticket, because writing and recording a
    painting round is minutes of work and the live round may never wait
    on it. Poll GET /api/schedule/segment/generate/{job}, or just re-read
    /api/schedule/segment and watch the candidates arrive.

    It uses the very prep road the keeper uses, inside the same building
    window, taking only the spare engine slot — so the show never queues
    behind it. Entries with no preparing road at all (a record, the
    recap, the deep dig) are refused with the reason."""
    require_auth(authorization)
    payload = await request.json()
    if not isinstance(payload, dict):
        raise HTTPException(status_code=400, detail="Expected an object")
    key = str(payload.get("hour") or payload.get("key")
              or "").strip() or _sched_hour_key()
    if not _sched_is_hour_key(key):
        raise HTTPException(
            status_code=400,
            detail="hour must be a local hour like 2026-08-19T22")
    slot_id = str(payload.get("slot") or payload.get("slot_id")
                  or "").strip()[:48]
    try:
        count = max(1, min(ALT_GEN_MOST, int(payload.get("count") or 1)))
    except (TypeError, ValueError):
        count = 1
    store = schedule_read()
    rows, at = alt_slot_of(store, key, slot_id)
    slot_kind = str(payload.get("kind") or "")
    if at is not None:
        slot_kind = str(rows[at].get("kind") or "")
    elif slot_id:
        raise HTTPException(status_code=404,
                            detail=f"No entry {slot_id!r} in the hour {key}")
    why = alt_refusal(slot_kind)
    kind = alt_prep_kind(slot_kind)
    if why or not kind:
        raise HTTPException(
            status_code=400,
            detail=(why or "there is nothing that can be prepared ahead "
                           "for that entry"))
    live = sum(1 for j in _ALT_JOBS.values()
               if str(j.get("state") or "") in ("queued", "waiting",
                                                "writing"))
    if live >= ALT_GEN_LIVE:
        raise HTTPException(
            status_code=409,
            detail=f"{live} lots of alternates are already being written — "
                   "let those land first, so the writing room is not the "
                   "thing holding the show up")
    job = "alt_" + uuid.uuid4().hex[:10]
    # #897: "modify and edit what the system prompt is that we're using
    # for generating that prompt. So I can send it back up, have it
    # written, and make that the new stand-in for what will be in that
    # position for the hour as the first slot."
    #
    # The edited words are dressed exactly as the entry's own standing
    # instruction would be dressed — same clause, same rules about naming
    # the segment on air — and handed to THIS ticket alone. timed=False
    # because what the operator has just typed must not be swapped for a
    # timed application while he is looking at it (#906).
    brief_raw = str(payload.get("prompt") or payload.get("brief") or "")[:4000]
    brief = ""
    if brief_raw.strip():
        try:
            preset, _hrows, _hon = schedule_hour_slots(store, key)
            brief = _schedule_clause(
                str(preset),
                rows[at] if at is not None else {"kind": slot_kind},
                brief_raw, timed=False)
        except Exception:  # noqa: BLE001
            brief = brief_raw       # undressed is still better than nothing
        # A brief worth writing with once is worth having again (#909).
        try:
            keep = str(payload.get("save_as") or "").strip()[:80]
            if keep:
                prompt_book_put({"name": keep, "kind": slot_kind,
                                 "text": brief_raw,
                                 "scenario": f"written to order for {key}"})
        except Exception:  # noqa: BLE001
            pass
    # And what comes back STANDS IN, unless told otherwise: the operator
    # asked for the new one to be what that position airs, not to join the
    # back of the queue behind whatever was already stacked. Send
    # "pin": false to write one without touching the running order.
    pin = None
    if slot_id and bool(payload.get("pin", True)):
        pin = {"hour": key, "slot": slot_id,
               "label": (str(rows[at].get("label") or slot_kind)
                         if at is not None else slot_kind)}
    row = alt_job_put(job, state="queued", hour=key, slot=slot_id,
                      kind=kind, slot_kind=slot_kind,
                      label=SHELF_LABEL.get(kind, kind), count=count,
                      made=0, refused=0, new=[], why="",
                      brief=bool(brief), stands_in=bool(pin),
                      full=bool(shelf_full(kind)))

    async def _more() -> None:
        try:
            await alt_generate_job(job, kind, count, brief=brief, pin=pin)
        except Exception as exc:  # noqa: BLE001
            pipeline_log("drop", f"the alternates task died: {exc}"[:200])

    asyncio.create_task(_more())
    note_action(f"🗓 writing {count} alternate(s): "
                + SHELF_LABEL.get(kind, kind) + f" — {key} (#926)")
    pipeline_log("lookahead",
                 f"{count} alternate {SHELF_LABEL.get(kind, kind)}(s) "
                 "asked for — they are written in the next quiet stretch, "
                 "on the spare engine slot, so the live round never waits "
                 "(#926)")
    return dict(row)


@app.get("/api/schedule/segment/generate/{job}")
async def schedule_segment_generate_state(
    job: str,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """#926: where that lot of alternates got to — queued, waiting for a
    quiet stretch, writing, done, gave up or failed, with the ids of the
    candidates that landed."""
    require_read_auth(authorization)
    row = _ALT_JOBS.get(str(job))
    if not row:
        raise HTTPException(status_code=404,
                            detail="No such request — it may have aged off")
    return dict(row)


@app.post("/api/schedule/segment/priority")
async def schedule_segment_priority_api(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """#926: REPRIORITISE or DEPRIORITISE one prepared candidate.

    {"shelf_id": "ad-1a2b3c4d5e", "priority": 3}

    -9 to 9, zero being untouched. With nothing pinned, the take prefers
    the highest priority and then the oldest — so this is how the owner
    says "that one next" without nailing it to a particular hour."""
    require_auth(authorization)
    payload = await request.json()
    if not isinstance(payload, dict):
        raise HTTPException(status_code=400, detail="Expected an object")
    want = str(payload.get("shelf_id") or payload.get("id") or "").strip()
    kind, row = alt_find(want)
    if row is None:
        raise HTTPException(
            status_code=404,
            detail=f"No prepared item called {want!r} — it may have aired "
                   "or burned off the shelf")
    try:
        priority = max(-9, min(9, int(payload.get("priority") or 0)))
    except (TypeError, ValueError):
        raise HTTPException(status_code=400,
                            detail="priority must be a whole number")
    row["priority"] = priority
    try:
        if kind == "banter":
            _larder_save()
        else:
            _pantry_save(True)
    except Exception:  # noqa: BLE001
        pass
    note_action(f"🗓 {SHELF_LABEL.get(kind, kind)} priority {priority:+d} "
                "(#926)")
    return {"ok": True, "id": want, "kind": kind, "priority": priority,
            "candidate": alt_row_view(kind, row, alt_pinned_id(kind))}


@app.delete("/api/schedule/segment/{shelf_id}")
async def schedule_segment_discard_api(
    shelf_id: str,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """#926: DISCARD one prepared candidate — a pitch the owner does not
    want in the running.

    ONLY the shelf row goes. THE AUDIO IS NOT DELETED: the media pruner
    owns the files and it is the one that knows what is still queued to
    play (_protected_media_keys) — a preparer unlinking a clip out from
    under a queued line is exactly the fault #467 exists to prevent. The
    clip stays in the pantry, keyed by its own text, and any other road
    that says those words still gets it for free.

    Any hour that had pinned this one is quietly unpinned, so nothing is
    left pointing at material that has gone."""
    require_auth(authorization)
    want = str(shelf_id or "").strip()[:64]
    kind, row = alt_find(want)
    if row is None:
        raise HTTPException(
            status_code=404,
            detail=f"No prepared item called {want!r} — it may have aired "
                   "or burned off the shelf already")
    left = 0
    try:
        shelf = _LARDER if kind == "banter" else shelf_rows(kind)
        shelf[:] = [r for r in shelf if r is not row]
        left = len(shelf)
        if kind == "banter":
            _larder_save()
        else:
            _pantry_save(True)
    except Exception:  # noqa: BLE001
        pass
    unpinned: list[str] = []
    try:
        with _SCHEDULE_LOCK:
            store = schedule_read()
            hours = dict(store.get("hours") or {})
            for hkey, blob in list(hours.items()):
                for slot in ((blob or {}).get("slots") or []):
                    if str((slot or {}).get("pinned_id") or "") == want:
                        slot["pinned_id"] = None
                        unpinned.append(str(hkey))
            if unpinned:
                store["hours"] = hours
                schedule_write(store)
        alt_pin_forget()
    except Exception:  # noqa: BLE001
        pass
    note_action(f"🗓 {SHELF_LABEL.get(kind, kind)} discarded — the shelf "
                "row only, the audio is the pruner's (#926)")
    pipeline_log("lookahead",
                 f"one prepared {SHELF_LABEL.get(kind, kind)} was discarded "
                 f"by hand — {left} left on that shelf, and the recording "
                 "is left where it is for the media prune (#926)")
    return {"ok": True, "id": want, "kind": kind, "left": left,
            "unpinned": unpinned}


def schedule_segment_prompt(hour: str = "", slot_id: str = "",
                            kind: str = "") -> dict[str, Any]:
    """#909/#897: what ONE entry writes with, and everything it could.

    Everything the editor popup needs in a single read: the words this
    entry actually goes on air with and WHERE they came from, the whole
    variant shelf for its kind, every prompt in the book that suits it,
    any timed application currently holding it, and the dressed clause
    exactly as the writing room receives it — so what the operator edits
    is what goes out, not a guess at it."""
    key = str(hour or "").strip()
    if not _sched_is_hour_key(key):
        key = _sched_hour_key()
    store: dict[str, Any] = {}
    rows: list[dict[str, Any]] = []
    preset = ""
    try:
        store = schedule_read()
        preset, raw, _on = schedule_hour_slots(store, key)
        rows = [_sched_slot(s) for s in raw]
    except Exception:                          # noqa: BLE001
        store, rows, preset = schedule_defaults(), [], ""
    want = str(slot_id or "").strip()[:48]
    slot: dict[str, Any] = {}
    if want:
        slot = next((s for s in rows
                     if str(s.get("id") or "") == want), {})
    slot_kind = str(slot.get("kind") or kind or "banter")
    if not slot:
        # Asked by KIND without naming an entry — the picker still wants
        # to see the shelf, so answer for a bare one of that kind.
        slot = {"id": want, "kind": slot_kind, "label": slot_kind,
                "notes": "", "prompt_id": None}
    blob = (store.get("prompts") or {}).get(slot_kind) or {}
    variants = [dict(v) for v in (blob.get("variants") or [])
                if isinstance(v, dict)]
    try:
        active = (int(blob.get("active") or 0) % len(variants)) \
            if variants else 0
    except (TypeError, ValueError):
        active = 0
    pinned = next((v for v in variants
                   if str(v.get("id") or "")
                   == str(slot.get("prompt_id") or "")), None) \
        if slot.get("prompt_id") else None
    armed = variants[active] if variants else None
    using = pinned or armed or {}
    source = ("this entry is pinned to it" if pinned is not None else
              f"it is the variant armed for every {slot_kind} entry"
              if armed is not None else
              "there is nothing on the shelf for this kind yet")
    text = str(using.get("text") or "")
    window = (prompt_windows_view() or {}).get(slot_kind)
    if window:
        # #906: a timed application is what this entry is REALLY writing
        # with, so that is what the box shows.
        text = str(window.get("text") or text)
        source = ("a timed prompt owns every " + slot_kind + " entry — "
                  + str(window.get("says") or ""))
    try:
        clause = _schedule_clause(str(preset), slot, text, timed=False)
    except Exception:                          # noqa: BLE001
        clause = ""
    return {
        "hour": key,
        "preset": preset,
        "slot_id": want or None,
        "slot": slot or None,
        "kind": slot_kind,
        "label": str(slot.get("label") or slot_kind),
        "notes": str(slot.get("notes") or ""),
        "text": text,
        "source": source,
        "variant": ({"id": using.get("id"), "name": using.get("name")}
                    if using else None),
        "variants": variants,
        "active": active,
        "window": window or None,
        "windows": prompt_windows_view(),
        "book": (prompt_book_view(slot_kind) or {}).get("prompts") or [],
        "seed": SCHEDULE_PROMPT_SEED.get(slot_kind, ""),
        "blurb": next((str(k.get("blurb") or "") for k in SCHEDULE_KINDS
                       if k.get("kind") == slot_kind), ""),
        "clause": clause,
        "preparable": bool(alt_prep_kind(slot_kind))
                      and not alt_refusal(slot_kind),
        "why": alt_refusal(slot_kind),
        "scopes": dict(PROMPT_SCOPE_SAYS),
    }


@app.get("/api/schedule/segment/prompt")
async def schedule_segment_prompt_api(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """#909/#897: THE SYSTEM PROMPT BEHIND ONE ENTRY, OPENED OUT.

        ?hour=YYYY-MM-DDTHH&slot=<slot id>&kind=<kind>

    The hour defaults to the one on air. Naming a kind without an entry
    answers for that kind in general, which is how the picker can be
    opened from anywhere."""
    require_read_auth(authorization)
    query = request.query_params
    return schedule_segment_prompt(
        str(query.get("hour") or query.get("key") or ""),
        str(query.get("slot") or query.get("slot_id") or ""),
        str(query.get("kind") or ""))


@app.get("/api/schedule/promptbook")
async def prompt_book_list_api(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """#909: THE PROMPT BOOK — every system prompt the operator has saved,
    newest first, with whatever is running on a timer beside it.

        ?kind=<segment kind>

    narrows it to the prompts written for that kind. Prompts saved for no
    particular kind always come back: they were written to suit anything,
    and hiding them would make the shelf lie."""
    require_read_auth(authorization)
    return prompt_book_view(str(request.query_params.get("kind") or ""))


@app.post("/api/schedule/promptbook")
async def prompt_book_save_api(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """#909: SAVE ONE PROMPT UNDER A NAME, or rewrite one already saved.

    {"name": "Gallery — the hard sell", "kind": "gallery",
     "scenario": "when the wall is full and nothing has sold tonight",
     "text": "…", "id": "pb-…"}

    Send an `id` to rewrite that one; leave it out and a new one is
    minted. `kind` is the segment kind it was written for and may be
    empty, which means "this suits anything". Saving changes NOTHING on
    air — the book is the library, and putting one to work is
    /api/schedule/promptbook/apply."""
    require_auth(authorization)
    payload = await request.json()
    if not isinstance(payload, dict):
        raise HTTPException(status_code=400, detail="Expected an object")
    if not str(payload.get("text") or "").strip():
        raise HTTPException(
            status_code=400,
            detail="There is nothing to save — send `text`")
    row = prompt_book_put(payload)
    if not row:
        raise HTTPException(status_code=400,
                            detail="That prompt could not be read")
    note_action(f"📝 saved to the prompt book: {row.get('name')} (#909)")
    return {"ok": True, "prompt": row,
            "book": prompt_book_view(str(row.get("kind") or ""))}


@app.delete("/api/schedule/promptbook/window/{kind}")
async def prompt_window_stop_api(
    kind: str,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """#906: STOP a timed application early — "all" stops every one.

    Those entries are back on their own standing instruction on the very
    next round. There is nothing to put back, because a window never
    edited the running order in the first place."""
    require_auth(authorization)
    want = str(kind or "").strip().lower()[:40]
    gone = prompt_window_clear("" if want in ("", "all") else want,
                               "the operator stopped it")
    if not gone:
        raise HTTPException(
            status_code=404,
            detail="Nothing is running on a timer there")
    note_action("📝 timed prompt stopped: " + ", ".join(gone) + " (#906)")
    return {"ok": True, "stopped": gone, "windows": prompt_windows_view()}


@app.delete("/api/schedule/promptbook/{pid}")
async def prompt_book_delete_api(
    pid: str,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """#909: take one saved prompt out of the book.

    Nothing on air changes. An entry already pinned to a variant made
    from this prompt keeps that variant — the book is the library, never
    the shelf the writing room reads."""
    require_auth(authorization)
    want = str(pid or "").strip()[:64]
    row = prompt_book_find(want)
    if not row:
        raise HTTPException(status_code=404,
                            detail=f"No saved prompt called {want!r}")
    prompt_book_drop(want)
    note_action(f"📝 dropped from the prompt book: {row.get('name')} (#909)")
    return {"ok": True, "id": want, "prompt": dict(row),
            "book": prompt_book_view()}


@app.post("/api/schedule/promptbook/apply")
async def prompt_book_apply_api(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """#909/#906: PUT A PROMPT TO WORK — one road, four scopes.

    {"text": "…"            the words, or "id": "pb-…" to take them
                            straight off the book,
     "scope": "default" | "next_segment" | "next_30" | "next_hour",
     "hour": "2026-08-20T22", "slot": "hour-03", "kind": "gallery",
     "minutes": 30, "name": "…"}

      default       this entry writes with it FROM NOW ON. The words go
                    onto the entry's kind as a named variant and the entry
                    in the RUNNING ORDER is pinned to it, which is a
                    permanent change to the plan — that is what "set as
                    default" means. Name no entry and it arms the variant
                    for every entry of that kind instead.
      next_segment  the very next segment of that kind, then it lets go by
                    itself. The segment already on air is not "the next"
                    one and never claims it.
      next_30       the next thirty minutes.
      next_hour     the next hour — which the operator said plainly means
                    both thirty-minute halves, so it is sixty minutes and
                    every entry of that kind inside them.

    THE THREE TIMED SCOPES CHANGE NOTHING IN THE RUNNING ORDER. They are a
    note held beside it that the entry reads while it is there and stops
    reading when it is not, so there is never anything to undo. Scripting
    one entry for one particular hour is a different job and stays where
    it was: POST /api/schedule/hours/{key}/prompt."""
    require_auth(authorization)
    payload = await request.json()
    if not isinstance(payload, dict):
        raise HTTPException(status_code=400, detail="Expected an object")
    scope = str(payload.get("scope") or "").strip().lower()[:20]
    if scope not in ("default",) + PROMPT_SCOPES:
        raise HTTPException(
            status_code=400,
            detail="scope must be one of: default, next_segment, next_30, "
                   "next_hour")
    text = str(payload.get("text") or "")[:4000]
    name = str(payload.get("name") or "").strip()[:80]
    saved = prompt_book_find(str(payload.get("id") or "").strip()[:64])
    if saved and not text.strip():
        text = str(saved.get("text") or "")
        name = name or str(saved.get("name") or "")
    if not text.strip():
        raise HTTPException(
            status_code=400,
            detail="There is no prompt here to apply — send `text`, or the "
                   "`id` of one saved in the book")
    key = str(payload.get("hour") or payload.get("key")
              or "").strip() or _sched_hour_key()
    if not _sched_is_hour_key(key):
        raise HTTPException(
            status_code=400,
            detail="hour must be a local hour like 2026-08-20T22")
    slot_id = str(payload.get("slot") or payload.get("slot_id")
                  or "").strip()[:48]
    kind = str(payload.get("kind") or "").strip().lower()[:40]
    label = ""
    store = schedule_read()
    rows, at = alt_slot_of(store, key, slot_id) if slot_id else ([], None)
    if slot_id and at is None:
        raise HTTPException(status_code=404,
                            detail=f"No entry {slot_id!r} in the hour {key}")
    if at is not None:
        kind = str(rows[at].get("kind") or kind)
        label = str(rows[at].get("label") or kind)
    if kind not in SCHEDULE_KIND_NAMES:
        raise HTTPException(
            status_code=400,
            detail="Which kind of segment is this prompt for? Name an entry "
                   "with `slot`, or send `kind`")
    name = name or f"{label or kind} · saved"
    if saved:
        prompt_book_used(str(saved.get("id") or ""))
    if scope == "default":
        # A stable variant id per saved prompt, so re-applying the same
        # one rewrites its variant instead of piling up a new one.
        vid = ("bk-" + (str(saved.get("id") or "") if saved
                        else uuid.uuid4().hex[:10]))[:64]
        armed = 0
        with _SCHEDULE_LOCK:
            store = schedule_read()
            prompt_variant_put(store, kind, vid, name, text)
            if slot_id:
                # The entry itself, everywhere it stands in the plan —
                # "the default for that entry from now on".
                for _pname, prows in (store.get("presets") or {}).items():
                    for prow in (prows or []):
                        if str((prow or {}).get("id") or "") == slot_id:
                            prow["prompt_id"] = vid
                            armed += 1
            else:
                # No entry named: arm it for the KIND, which is what the
                # prompt desk's own cycle does.
                blob = dict((store.get("prompts") or {}).get(kind) or {})
                ids = [str(v.get("id") or "")
                       for v in (blob.get("variants") or [])]
                if vid in ids:
                    blob["active"] = ids.index(vid)
                    store["prompts"][kind] = blob
                    armed = 1
            schedule_write(store)
        _RADIO["sched_prompt"] = ""
        note_action("📝 default prompt set: "
                    + (label or kind) + f" — {name[:40]} (#906)")
        pipeline_log(
            "lookahead",
            "\u201c" + name + "\u201d is now the standing instruction for "
            + (f"the {label} entry" if slot_id else f"every {kind} entry")
            + " — it is in the running order itself, so it survives a "
              "restart and every hour from here (#906)")
        return {"ok": True, "scope": scope, "kind": kind, "name": name,
                "variant": vid, "entries": armed,
                "says": "the standing instruction from now on",
                "windows": prompt_windows_view()}
    row = prompt_window_put(kind, scope, text, name=name,
                            minutes=payload.get("minutes") or 30,
                            slot_id=slot_id, label=label)
    if not row:
        raise HTTPException(
            status_code=400,
            detail="That window could not be armed — check the scope and "
                   "that there are actually words in it")
    return {"ok": True, "scope": scope, "kind": kind, "name": name,
            "window": dict(row),
            "says": PROMPT_SCOPE_SAYS.get(scope, scope),
            "windows": prompt_windows_view()}


@app.get("/api/schedule/prompts")
async def schedule_prompts_get_api(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """The per-kind system prompt shelves and which variant is armed."""
    require_read_auth(authorization)
    return schedule_read().get("prompts") or {}


@app.post("/api/schedule/prompts")
async def schedule_prompts_save_api(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Store, cycle and vary the per-kind prompts. Used IMMEDIATELY: the
    entry on air re-reads its prompt on the very next round, not at the
    next restart."""
    require_auth(authorization)
    payload = await request.json()
    if not isinstance(payload, dict):
        raise HTTPException(status_code=400, detail="Expected an object")
    with _SCHEDULE_LOCK:
        store = schedule_read()
        prompts = dict(store.get("prompts") or {})
        for kind, blob in payload.items():
            cleaned = _sched_prompt_blob(blob)
            if cleaned:
                prompts[str(kind)[:40]] = cleaned
            else:
                prompts.pop(str(kind)[:40], None)
        store["prompts"] = prompts
        schedule_write(store)
    _RADIO["sched_prompt"] = ""
    note_action("🗓 schedule prompts saved (#843)")
    return prompts


# --- The plotline desk: hand-written storylines the pair play out on air ---
# You structure a plot in acts; while it is ACTIVE the booth weaves the
# current act into its rounds — in character, never announced as a script —
# until the story lands. One plot active at a time.
PLOTLINES_PATH = data_path("plotlines.json")
_PLOT_LOCK = RLock()


def plot_read() -> list[dict[str, Any]]:
    try:
        rows = json.loads(PLOTLINES_PATH.read_text())
        return [r for r in rows if isinstance(r, dict)]
    except Exception:
        return []


def plot_write(rows: list[dict[str, Any]]) -> None:
    with _PLOT_LOCK:
        PLOTLINES_PATH.parent.mkdir(parents=True, exist_ok=True)
        tmp = PLOTLINES_PATH.with_suffix(".tmp")
        tmp.write_text(json.dumps(rows[-60:], indent=1))
        tmp.replace(PLOTLINES_PATH)


def plot_advance() -> str:
    """The next beat of the active plotline as a round angle — paced so a
    story breathes across the show rather than burning up in ten minutes.
    Advances the act pointer when it fires; marks the plot done after the
    final act."""
    with _PLOT_LOCK:
        rows = plot_read()
        row = next((r for r in rows
                    if r.get("active") and not r.get("done")), None)
        # #907: while the plot owns the HALF HOUR, plot_clause() is
        # already carrying it into every prompt the station builds, so
        # this road stands down rather than ALSO spending an act on one
        # round's angle. Two engines advancing one story is how a
        # five-act plot reaches its ending ten minutes in.
        if plot_owns_air():
            return ""
        # #1157: ...and for a plot that carries a SPAN, whether or not
        # it owns the air this instant. A span plot is `active` and not
        # `done` in two ordinary states where plot_owns_air() is empty -
        # armed for the top of the next hour, and the seconds between a
        # restart and the first coordinator tick - and in both of them
        # this road would spend the acts of a story that has not
        # started or is running perfectly well elsewhere. Measured: a
        # five-act plot armed at 22:41 for 23:00 reached act five and
        # was marked played out before it went on the air. The span is
        # the clock; nothing else may move the pointer.
        if row and plotline_span_seconds(row) > 0:
            return ""
        if not row or random.random() > 0.45:
            return ""
        acts = [str(a) for a in (row.get("acts") or []) if str(a).strip()]
        i = int(row.get("act_idx") or 0)
        if i >= len(acts):
            row["done"], row["active"] = True, False
            plot_write(rows)
            return ""
        act = acts[i]
        row["act_idx"] = i + 1
        final = i + 1 >= len(acts)
        if final:
            row["done"], row["active"] = True, False
        plot_write(rows)
    pipeline_log("model", f"plotline \"{str(row.get('title') or '')[:40]}\" "
                          f"— act {i + 1}/{len(acts)} takes the round")
    return (
        f"STORYLINE, act {i + 1} of {len(acts)} — the booth is living a "
        f"plot tonight: \"{row.get('title') or 'untitled'}\". What happens "
        f"in THIS act: {act} Play it out NATURALLY inside the round — the "
        "plot colours the conversation, in character, never announced as a "
        "script — and refer back to earlier acts as shared memory."
        + (" This is the FINAL act — land the ending tonight."
           if final else ""))


def _plot_half_key(when: float | None = None) -> str:
    """The HALF-HOUR key for a moment (#907).

    The schedule already keys its per-hour overrides this way
    (_sched_hour_key); a plotline is asked to colour a HALF hour, so it
    takes the same shape of key with the half stamped on the end."""
    try:
        at = when if when is not None else time.time()
        local = time.localtime(at)
        return (time.strftime("%Y-%m-%dT%H:", local)
                + ("30" if local.tm_min >= 30 else "00"))
    except Exception:  # noqa: BLE001
        return ""


def plot_half_bounds(key: str) -> tuple[float, float]:
    """Start and end of a half-hour key, in epoch seconds."""
    try:
        began = time.mktime(time.strptime(str(key), "%Y-%m-%dT%H:%M"))
        return began, began + 1800.0
    except Exception:  # noqa: BLE001
        return 0.0, 0.0


# The answer is asked for by every prompt the station builds, and
# plot_read() has no cache of its own (themes_read does). Two seconds is
# far shorter than a half hour and far longer than a round.
_PLOT_AIR: dict[str, Any] = {"at": 0.0, "row": {}}


def plot_owns_air() -> dict[str, Any]:
    """The plotline colouring THIS half hour, or {} (#907).

    Modelled on theme_owns_air() rather than on plot_advance(): a thing
    that is simply TRUE for a stretch of the running order and that any
    road may ask about, instead of a pointer somebody burns a beat off.
    A plot that is merely `active` and has not claimed a half hour is
    NOT this — it keeps the old behaviour exactly."""
    try:
        if time.time() - float(_PLOT_AIR["at"] or 0) < 2.0:
            return dict(_PLOT_AIR["row"] or {})
    except Exception:  # noqa: BLE001
        pass
    row: dict[str, Any] = {}
    try:
        want = _plot_half_key()
        for one in plot_read():
            if not (one.get("active") and not one.get("done")):
                continue
            # #1157: a plot with a real SPAN owns the air on its own
            # clock - air seconds against the minutes the operator
            # asked for, which is the only thing that can express
            # "an hour or several hours". A plot without one keeps
            # the half-hour road below, unchanged, exactly as #907
            # left it.
            if plotline_span_seconds(one) > 0:
                if plotline_live(one):
                    row = dict(one)
                    break
                continue
            held = str(one.get("half_hour") or "")
            if not held:
                continue            # on air, but not claiming the half hour
            until = float(one.get("half_hour_until") or 0)
            if until:
                if time.time() >= until:
                    continue        # its half hours have run out
            elif held != want:
                continue
            row = dict(one)
            break
    except Exception:  # noqa: BLE001
        row = {}
    _PLOT_AIR.update({"at": time.time(), "row": row})
    return dict(row)


def plot_act_now(row: dict[str, Any]) -> tuple[str, int, int]:
    """Which act is due right now, BY THE CLOCK (#907).

    The claimed stretch is divided evenly between the acts, so the story
    walks across the segments of the running order — the opening act
    under the first segments, the ending under the last. That is what
    "executing the plotline across all the segments" asks for, and it is
    the thing plot_advance()'s pointer cannot do: burning an act per
    ROUND spends a five-act story in ten minutes of busy banter and
    never reaches the ending on a quiet half hour."""
    acts = [str(a) for a in (row.get("acts") or []) if str(a).strip()]
    if not acts:
        return "", 0, 0
    # #1157: the same division, over the span the operator named and
    # measured in AIR seconds rather than wall clock, so a pause does
    # not spend an act on silence (#1150). plot_act_now stays THE
    # answer to "which act is due"; only the ruler changed.
    if plotline_span_seconds(row) > 0:
        _span_at = plotline_act_index(row, len(acts))
        return acts[_span_at], _span_at + 1, len(acts)
    at = 0
    try:
        began, _end = plot_half_bounds(str(row.get("half_hour") or ""))
        until = float(row.get("half_hour_until") or 0) or (began + 1800.0)
        span = max(1.0, until - began)
        gone = max(0.0, min(span - 0.001, time.time() - began))
        at = int(gone / span * len(acts))
    except Exception:  # noqa: BLE001
        at = int(row.get("act_idx") or 0)
    at = max(0, min(len(acts) - 1, at))
    return acts[at], at + 1, len(acts)


def plot_clause() -> str:
    """The storyline, as every writing road needs to hear it (#907).

    Deliberately shaped like crystal_clause() and not like
    plot_advance(): ADDITIVE text that rides alongside whatever the
    round was already about, rather than an `angle` that replaces it.
    That distinction is the whole of this request — an angle is
    mutually exclusive with every road that has an angle of its own,
    which is the callers, the memos, the adverts and the gallery.

    Never raises. A storyline is colour; colour may not take the
    station off the air."""
    try:
        row = plot_owns_air()
        if not row:
            return ""
        act, at, of = plot_act_now(row)
        if not act:
            return ""
        title = str(row.get("title") or "untitled")[:120]
        return (
            "\n\nTHE AIR IS UNDER A STORYLINE (#907/#1157) — \""
            + title + "\". This is act " + str(at) + " of " + str(of)
            + ", and what happens in it is: " + str(act)[:600]
            + " EVERY segment of this stretch of the show is inside that "
            "story and "
            "is coloured by it — the booth talk, the calls that come in, "
            "the memo from upstairs, the advert reads, the gallery, all "
            "of it. Whatever this particular round is nominally about, it "
            "is happening WHILE this is going on and the people in it "
            "know that. Work it into what you were going to say anyway, "
            "stay in character, and never announce it as a script or read "
            "this instruction out loud. Treat what earlier acts "
            "established as shared memory."
            + (" This is the FINAL act — land the ending before the "
               "story's time is out." if at >= of else "")
            + plotline_run_clause(row)
            # #1157: and everything #907 had no way to say - how long
            # the story runs, how far through it is, what has ACTUALLY
            # happened so far, and the standing order to track it out
            # loud as it develops. Additive, like the rest of this.
            + plotline_extra_clause(row, at, of)
            + "\n")
    except Exception:  # noqa: BLE001
        return ""


# --- #1157: THE PLOTLINE, ON A REAL SPAN ---------------------------------
#
# "Make sure the system is adherent to the plot line system where the plot
#  lines take place and unfold over the course of either an hour or several
#  hours, depending on how long it's specified, where all of the acts take
#  place distinctly in the form of their content that's being expressed by
#  the people who call in and the DJs who are tracking the story in real
#  time and describing everything that's happening with the story as it's
#  developing as a plot line."
#
# #907 built the good bone: plot_act_now() divides a claimed stretch evenly
# between the acts, so the story WALKS across the running order instead of
# burning an act per round.  What it lacked was everything around that bone.
# The stretch was a `half_hours` integer buried in an activate payload, so
# the operator could not say "three hours"; there was no timetable, so
# nobody could see which act was due when; nothing recorded what actually
# aired under an act, so the pair had no shared memory to refer back to;
# and no caller ever rang in ABOUT the story, so the acts were colour on
# the booth's own conversation rather than events in a world.
#
# This module supplies the missing half:
#
#   span_minutes        the operator's own units, first class and persisted
#   plotline_elapsed    the story's clock, measured in AIR seconds
#   plotline_timetable  which act is live between which clock times
#   plot_beats.jsonl    what actually aired under each act
#   plotline_so_far     a running account, rewritten at each act boundary
#   plotline_call_draw  a share of the calls come out of the current act
#
# THE CLOCK IS PAUSE-HONEST, on purpose and to match #1150.  Every other
# clock in this station freezes off air; a story clock that kept running
# would spend its acts on silence and land its ending on a dead speaker.
# So `air_elapsed` only accrues while the station is actually on, and the
# clock times the timetable reports are PROJECTIONS at the current pause
# state: a pause pushes every remaining act later by the length of it.
#
# Nothing here may take the station off the air.  A storyline is colour;
# a malformed one (no acts, one blank act, a span of zero) is inert.
PLOT_BEATS_PATH = data_path("plot_beats.jsonl")
PLOT_BEATS_KEPT = 4000                  # rows kept in the ledger
PLOT_BEAT_FLOOR = 30                    # a beat has to be a sentence
PLOT_SPAN_MOST = 2880                   # forty-eight hours, the old ceiling
PLOT_TICK_WRITE = 30.0                  # seconds between ordinary saves
PLOT_BANK_FLOOR = 900                   # story left before a call is banked
PLOT_TIGHT_ACT = 240                    # an act shorter than this is a blur
PLOT_SO_FAR_CAP = 900

# What plotline_tick() published on its last pass.  Every hot path reads
# THIS rather than the file: air_remember() runs on every aired line and
# may not touch the disk (#1142/#1156).
_PLOT_NOW: dict[str, Any] = {}
_PLOT_BEATS: list[dict[str, Any]] = []          # waiting to be written
_PLOT_BEATS_LOCK = RLock()
_PLOT_TICK = {"at": 0.0, "wrote": 0.0, "compacted": 0.0}
_PLOT_SO_FAR_BUSY = [False]


# #1159: the most runs a number may ask for. Saying "forever" takes -1,
# which is a decision rather than a slip of the keyboard.
PLOT_LOOPS_MOST = 999


def plotline_acts(row: Any) -> list[str]:
    """The acts of a plot, blank ones dropped - the one place that decides
    what counts as an act, so a malformed plot is short rather than fatal."""
    try:
        return [str(a).strip() for a in (row or {}).get("acts") or []
                if str(a).strip()]
    except Exception:  # noqa: BLE001
        return []


def plotline_span_seconds(row: Any) -> float:
    """The operator's span in seconds, or 0.0 when he never named one."""
    try:
        return max(0.0, min(float(PLOT_SPAN_MOST),
                            float((row or {}).get("span_minutes") or 0))) * 60.0
    except Exception:  # noqa: BLE001
        return 0.0


def plotline_loops(row: Any) -> int:
    """How many MORE times this story runs after the one it is on.

    0 is what every plot written before this does and keeps doing: play
    once and land. A positive number is that many more runs. -1 is the
    operator saying "until I stop it", which is the one this was asked
    for - a serial that holds the world open for as long as he wants it
    open."""
    try:
        got = int((row or {}).get("loops") or 0)
    except Exception:  # noqa: BLE001
        return 0
    return -1 if got < 0 else min(got, PLOT_LOOPS_MOST)


def plotline_run(row: Any) -> int:
    """Which time round this is, counting from one."""
    try:
        return max(1, int((row or {}).get("run") or 1))
    except Exception:  # noqa: BLE001
        return 1


def plotline_frozen(row: Any = None) -> bool:
    """Is the story's clock standing still? Off air, or held by hand."""
    try:
        if bool((row or {}).get("held")):
            return True
    except Exception:  # noqa: BLE001
        pass
    try:
        return bool(radio_paused())
    except Exception:  # noqa: BLE001
        return False


def plotline_elapsed(row: Any) -> float:
    """How much AIR the story has had, in seconds.

    Pure arithmetic off two stamps the tick maintains - `air_elapsed`
    (banked) and `ticked_at` (when it was last banked) - so this may be
    asked on any path, including a poll, without touching the disk."""
    try:
        began = float((row or {}).get("started_at") or 0)
        if began <= 0:
            return 0.0
        base = max(0.0, float(row.get("air_elapsed") or 0.0))
        tick = max(float(row.get("ticked_at") or began), began)
        if not plotline_frozen(row):
            # #1157: the same clamp the tick applies when it BANKS.
            # `ticked_at` is refreshed every fifteen seconds while this
            # process lives, so a gap far larger than that is the
            # process having been away - and the outage is not air.
            # Without this the reader and the tick disagreed for the
            # seconds between a restart and the first tick: a story an
            # hour into a three-hour span read as seven hours gone, so
            # every road was told it was over, on its final act, off
            # the air - and plot_advance was free to burn it.
            ran = float(_PLOT_TICK.get("at") or 0)
            room = max(120.0, (time.time() - ran) * 4.0) if ran else 0.0
            base += min(max(0.0, time.time() - tick), room)
        return base
    except Exception:  # noqa: BLE001
        return 0.0


def plotline_remaining(row: Any) -> float:
    """Air seconds left before the story lands."""
    return max(0.0, plotline_span_seconds(row) - plotline_elapsed(row))


def plotline_live(row: Any) -> bool:
    """Is this plot COLOURING THE AIR right now?

    A plot only owns the air once it has a span, an act, a start that has
    arrived, and time left on the clock. Everything else is a draft."""
    try:
        if not (row and row.get("active") and not row.get("done")):
            return False
        span = plotline_span_seconds(row)
        if span <= 0 or not plotline_acts(row):
            return False
        began = float(row.get("started_at") or 0)
        if began <= 0 or time.time() < began:
            return False               # armed for later, not on yet
        return plotline_elapsed(row) < span
    except Exception:  # noqa: BLE001
        return False


def plotline_act_index(row: Any, count: int = 0) -> int:
    """Which act is due by the clock - 0-based, clamped.

    The mechanism is #907's: the claimed stretch divided evenly between
    the acts. The only change is WHICH stretch - air seconds against the
    operator's span, rather than wall-clock against a half-hour key."""
    acts = count or len(plotline_acts(row))
    if acts <= 0:
        return 0
    span = plotline_span_seconds(row)
    if span <= 0:
        return max(0, min(acts - 1, int((row or {}).get("act_idx") or 0)))
    gone = min(span - 0.001, plotline_elapsed(row))
    return max(0, min(acts - 1, int(gone / span * acts)))


def plotline_act_marks(row: Any) -> dict[str, float]:
    """When each act actually came up, as the tick saw it happen."""
    try:
        marks = (row or {}).get("act_marks") or {}
        return {str(k): float(v or 0) for k, v in marks.items()}
    except Exception:  # noqa: BLE001
        return {}


def plotline_timetable(row: Any) -> list[dict[str, Any]]:
    """WHICH ACT IS LIVE BETWEEN WHICH CLOCK TIMES.

    Offsets are exact (air seconds off the span); the clock times are
    projections at the current pause state, and an act that has already
    come up reports the moment it really did. A story with no acts or no
    span has no timetable, which is how a malformed plot stays inert."""
    acts = plotline_acts(row)
    span = plotline_span_seconds(row)
    if not acts or span <= 0:
        return []
    each = span / len(acts)
    gone = plotline_elapsed(row)
    now = time.time()
    marks = plotline_act_marks(row)
    began = float((row or {}).get("started_at") or 0)
    out: list[dict[str, Any]] = []
    for i, text in enumerate(acts):
        frm, to = each * i, each * (i + 1)
        real = marks.get(str(i + 1)) or 0.0
        out.append({
            "act": i + 1, "of": len(acts), "text": text[:600],
            "from_s": round(frm, 1), "to_s": round(to, 1),
            "seconds": round(each, 1),
            "from_at": round(real or (now + (frm - gone))) if began else 0,
            "to_at": round(now + (to - gone)) if began else 0,
            "started": bool(began and gone >= frm),
            "live": bool(began and frm <= gone < to),
            "done": bool(began and gone >= to),
        })
    return out


def plotline_progress(row: Any) -> dict[str, Any]:
    """Where the story stands: which act, how far through, how long left."""
    acts = plotline_acts(row)
    span = plotline_span_seconds(row)
    gone = plotline_elapsed(row)
    at = plotline_act_index(row, len(acts)) if acts else 0
    each = (span / len(acts)) if (acts and span > 0) else 0.0
    return {
        "id": str((row or {}).get("id") or ""),
        "title": str((row or {}).get("title") or "")[:120],
        "live": plotline_live(row),
        "held": bool((row or {}).get("held")),
        "frozen": plotline_frozen(row),
        "span_minutes": round(span / 60.0, 2),
        "span_seconds": round(span, 1),
        "started_at": float((row or {}).get("started_at") or 0),
        "elapsed": round(gone, 1),
        "remaining": round(max(0.0, span - gone), 1),
        "through": round(min(1.0, gone / span), 4) if span > 0 else 0.0,
        "act": at + 1 if acts else 0,
        "of": len(acts),
        "acts_left": max(0, len(acts) - (at + 1)) if acts else 0,
        "act_seconds": round(each, 1),
        # #1157: five acts over ten minutes is arithmetically perfect
        # and inaudible - with a round landing every three minutes the
        # show says acts 2, 4 and 5 and never mentions 1 or 3. The
        # engine cannot refuse it (the operator may want a blur), so it
        # says so on the desk instead.
        "tight": bool(each and each < PLOT_TIGHT_ACT),
        "act_left": round(max(0.0, each * (at + 1) - gone), 1) if each else 0.0,
        "act_text": acts[at][:600] if acts else "",
    }


def plotline_meta(row: Any) -> dict[str, Any]:
    """The small stamp a caller, a call ledger row or a beat carries."""
    acts = plotline_acts(row)
    at = plotline_act_index(row, len(acts)) if acts else 0
    return {"id": str((row or {}).get("id") or ""),
            "title": str((row or {}).get("title") or "")[:120],
            "act": at + 1 if acts else 0, "of": len(acts)}


def plotline_now() -> dict[str, Any]:
    """What the tick last published - free to ask on any hot path."""
    try:
        return dict(_PLOT_NOW)
    except Exception:  # noqa: BLE001
        return {}


def plotline_start_at(start: str = "now") -> float:
    """"Now", or the top of the next hour - the operator's two choices."""
    now = time.time()
    if str(start or "").strip().lower() in ("hour", "next_hour", "top"):
        try:
            local = time.localtime(now)
            top = time.mktime((local.tm_year, local.tm_mon, local.tm_mday,
                               local.tm_hour, 0, 0, 0, 0, local.tm_isdst))
            return top + 3600.0
        except Exception:  # noqa: BLE001
            return now
    return now


def plotline_arm(row: dict[str, Any], span_minutes: float,
                 start: str = "now", restart: bool = True) -> dict[str, Any]:
    """Put a real span on a plot row and start its clock.

    The half-hour keys #907 wrote are still filled in so every reader
    written before this - plot_owns_air's old road, the panel's shelf
    label - keeps saying something true; the span is the truth."""
    span = max(1.0, min(float(PLOT_SPAN_MOST), float(span_minutes or 0)))
    began = plotline_start_at(start)
    row["span_minutes"] = round(span, 2)
    row["started_at"] = began
    row["ticked_at"] = began
    row["held"] = False
    row["done"] = False
    if restart or not row.get("air_elapsed"):
        row["run"] = 1                       # #1159: a fresh serial
        row["air_elapsed"] = 0.0
        row["act_idx"] = 0
        row["act_live"] = 0
        row["act_marks"] = {}
        row["so_far"] = ""
        row["so_far_act"] = 0
        row["so_far_at"] = 0.0
    # Back-compat (#907): the old half-hour claim, derived from the span.
    try:
        row["half_hour"] = _plot_half_key(began)
        row["half_hour_until"] = began + span * 60.0
    except Exception:  # noqa: BLE001
        pass
    return row


# --- The beats ledger ------------------------------------------------------
#
# What ACTUALLY aired under each act. It is what the story so far is built
# from, it is what lets the Gazette's serial section and the screenplay
# cover a plot as it unfolds, and it is the operator's proof that an act
# happened rather than merely being due.
#
# Bounded and off the loop: lines are buffered in memory by air_remember
# (which runs on every aired line and must never touch the disk), and the
# coordinator's tick appends the buffer in a worker thread.
def plotline_beat_note(text: str, who: str = "", kind: str = "") -> None:
    """One aired line offered to the ledger. Cheap enough for air_remember:
    a dict read and a length test, no disk, no lock contention worth the
    name, and nothing at all unless a plot is on."""
    try:
        now = _PLOT_NOW
        if not now.get("id"):
            return
        said = " ".join(str(text or "").split())
        if len(said) < PLOT_BEAT_FLOOR:
            return
        seat = str(who or "")
        if seat in ("host", "board", "") or str(kind or "") in ("chat",
                                                                "marker"):
            return
        row = {"at": round(time.time(), 1), "plot": str(now.get("id") or ""),
               "act": int(now.get("act") or 0), "of": int(now.get("of") or 0),
               "title": str(now.get("title") or "")[:120],
               "who": seat, "kind": str(kind or "")[:24],
               "round": str(_RADIO.get("last_round_kind") or "")[:24],
               "name": "", "call": "", "text": said[:400]}
        try:
            if seat in ("caller", "caller2"):
                row["name"] = str(_CALL_LIVE.get("who") or "")[:60]
                row["call"] = str(_CALL_LIVE.get("id") or "")[:24]
        except Exception:  # noqa: BLE001
            pass
        with _PLOT_BEATS_LOCK:
            if len(_PLOT_BEATS) < 400:
                _PLOT_BEATS.append(row)
    except Exception:  # noqa: BLE001
        pass                    # a storyline never interrupts an aired line


def _plotline_beats_append_blocking(rows: list[dict[str, Any]]) -> None:
    """Append beats, and compact the ledger at most hourly (both in a
    worker thread - never a whole-file rewrite per event, #1142)."""
    try:
        PLOT_BEATS_PATH.parent.mkdir(parents=True, exist_ok=True)
        with open(PLOT_BEATS_PATH, "a", encoding="utf-8", newline="\n") as fh:
            for row in rows:
                fh.write(json.dumps(row, separators=(",", ":")) + "\n")
    except Exception:  # noqa: BLE001
        return
    try:
        if time.time() - float(_PLOT_TICK.get("compacted") or 0) < 3600:
            return
        _PLOT_TICK["compacted"] = time.time()
        lines = PLOT_BEATS_PATH.read_text(encoding="utf-8").splitlines()
        if len(lines) <= PLOT_BEATS_KEPT + 500:
            return
        tmp = PLOT_BEATS_PATH.with_suffix(".tmp")
        with open(tmp, "w", encoding="utf-8", newline="\n") as fh:
            fh.write("\n".join(lines[-PLOT_BEATS_KEPT:]) + "\n")
        tmp.replace(PLOT_BEATS_PATH)
    except Exception:  # noqa: BLE001
        pass


def _plotline_beats_read_blocking(plot_id: str = "", act: int = 0,
                                  most: int = 40) -> list[dict[str, Any]]:
    """The tail of the ledger, filtered. Reads the file, so callers on the
    event loop go through asyncio.to_thread."""
    out: list[dict[str, Any]] = []
    try:
        lines = PLOT_BEATS_PATH.read_text(
            encoding="utf-8").splitlines()[-PLOT_BEATS_KEPT:]
    except Exception:  # noqa: BLE001
        lines = []
    for line in lines:
        try:
            row = json.loads(line)
        except Exception:  # noqa: BLE001
            continue
        if not isinstance(row, dict):
            continue
        if plot_id and str(row.get("plot") or "") != str(plot_id):
            continue
        if act and int(row.get("act") or 0) != int(act):
            continue
        out.append(row)
    try:
        with _PLOT_BEATS_LOCK:
            for row in _PLOT_BEATS:
                if plot_id and str(row.get("plot") or "") != str(plot_id):
                    continue
                if act and int(row.get("act") or 0) != int(act):
                    continue
                out.append(dict(row))
    except Exception:  # noqa: BLE001
        pass
    return out[-max(1, int(most)):]


async def plotline_beats(plot_id: str = "", act: int = 0,
                         most: int = 40) -> list[dict[str, Any]]:
    """The beats, off the loop."""
    try:
        return await asyncio.to_thread(
            _plotline_beats_read_blocking, plot_id, act, most)
    except Exception:  # noqa: BLE001
        return []


# --- The story so far ------------------------------------------------------
#
# The half the operator says is missing: "the DJs who are tracking the story
# in real time and describing everything that's happening with the story as
# it's developing".  The static act text cannot do that - it is what is
# SUPPOSED to happen, written before the show.  This is a running account of
# what DID: what has happened, who is involved, where it stands, what is
# expected next, built out of the beats that actually aired.
#
# One model visit at an ACT BOUNDARY, never per round, never on a poll.
def plotline_so_far(row: Any) -> str:
    """The running account, or "" - read freely, it is a stored string."""
    try:
        return str((row or {}).get("so_far") or "")[:PLOT_SO_FAR_CAP]
    except Exception:  # noqa: BLE001
        return ""


def _plotline_so_far_parse(raw: str) -> str:
    """Fold the labelled answer back into three or four plain sentences.

    ask_model collapses whitespace, so the writer is asked for LABELS and
    the labels are what is parsed - the same shape #1039's story writer
    uses for the same reason."""
    said = re.sub(r"<think>.*?</think>", " ", str(raw or ""),
                  flags=re.S | re.I)
    said = " ".join(said.split())
    if not said:
        return ""
    parts: dict[str, str] = {}
    keys = ("HAPPENED", "WHO", "STANDS", "NEXT")
    for i, key in enumerate(keys):
        rest = "|".join(keys[i + 1:])
        tail = rf"(?=\s(?:{rest})\s*:|$)" if rest else r"(?=$)"
        hit = re.search(rf"{key}\s*:\s*(.+?){tail}", said, flags=re.I)
        if hit:
            parts[key] = " ".join(hit.group(1).split())[:320]
    if not parts:
        return said[:PLOT_SO_FAR_CAP]
    out = []
    if parts.get("HAPPENED"):
        out.append("What has happened: " + parts["HAPPENED"])
    if parts.get("WHO"):
        out.append("Who is in it: " + parts["WHO"])
    if parts.get("STANDS"):
        out.append("Where it stands: " + parts["STANDS"])
    if parts.get("NEXT"):
        out.append("What is expected next: " + parts["NEXT"])
    return " ".join(out)[:PLOT_SO_FAR_CAP]


async def plotline_so_far_write(plot_id: str) -> str:
    """Rewrite the running account from what actually aired.

    Called only at an act boundary and only through fire_and_forget, so a
    slow model never delays the tick, the round or the air."""
    if _PLOT_SO_FAR_BUSY[0]:
        return ""
    _PLOT_SO_FAR_BUSY[0] = True
    try:
        with _PLOT_LOCK:
            found = next((r for r in plot_read()
                          if r.get("id") == plot_id), None)
            row = dict(found) if found else {}
        if not row:
            return ""
        acts = plotline_acts(row)
        if not acts:
            return ""
        at = plotline_act_index(row, len(acts))
        beats = await plotline_beats(plot_id, 0, 60)
        heard = [f"[act {int(b.get('act') or 0)}] "
                 f"{b.get('name') or b.get('who')}: {str(b.get('text'))[:200]}"
                 for b in beats[-24:]]
        if not heard:
            return ""
        prompt = (
            "You keep the continuity notes for a live radio serial. The "
            f"story is \"{str(row.get('title') or 'untitled')[:120]}\". Its "
            "acts, as they were written down beforehand, are:\n- "
            + "\n- ".join(a[:220] for a in acts[:12])
            + f"\n\nIt is now act {at + 1} of {len(acts)}.\n\nWhat has "
            "ACTUALLY gone out on air so far, in order:\n- "
            + "\n- ".join(heard)
            + "\n\nWrite the running account of this story from what "
            "actually aired - not from the plan. Go by these four labels, "
            "on one line, in this order, each one or two plain sentences "
            "and no more:\nHAPPENED: <the events so far, concretely>\n"
            "WHO: <the people in it, by name, and what each of them did>\n"
            "STANDS: <where the story stands at this moment>\n"
            "NEXT: <what everybody is expecting to happen next>\n"
            "No preamble, no markdown, no commentary about radio.")
        raw = await ask_model(prompt, limit=900, spice=0.2,
                              mark={"kind": "plot so far",
                                    "for": "the running account of the "
                                           "storyline on air"})
        said = _plotline_so_far_parse(str(raw or ""))
        if len(said) < 40:
            return ""
        with _PLOT_LOCK:
            rows = plot_read()
            live = next((r for r in rows if r.get("id") == plot_id), None)
            if not live:
                return ""
            live["so_far"] = said
            live["so_far_act"] = at + 1
            live["so_far_at"] = time.time()
            plot_write(rows)
        _PLOT_AIR.update({"at": 0.0, "row": {}})
        pipeline_log("model", "the storyline's running account was rewritten "
                     f"off what aired - act {at + 1}/{len(acts)} of "
                     f"\"{str(row.get('title') or '')[:40]}\" (#1157)")
        return said
    except Exception as exc:  # noqa: BLE001
        pipeline_log("drop", "the storyline's running account failed",
                     extra=f"{type(exc).__name__}: {exc}"[:300])
        return ""
    finally:
        _PLOT_SO_FAR_BUSY[0] = False


# --- The clause the writers get -------------------------------------------
def _plotline_say_span(seconds: Any) -> str:
    """"three hours", "forty minutes" - the operator's own units, spoken."""
    try:
        mins = int(round(max(0.0, float(seconds or 0)) / 60.0))
    except Exception:  # noqa: BLE001
        return "a while"
    if mins <= 0:
        return "less than a minute"
    if mins < 90:
        return f"{mins} minute" + ("s" if mins != 1 else "")
    hours = mins / 60.0
    if abs(hours - round(hours)) < 0.05:
        whole = int(round(hours))
        return f"{whole} hour" + ("s" if whole != 1 else "")
    return f"{hours:.1f} hours"


def plotline_tint_clause(cap: int = 340) -> str:
    """#1159: the live act, said short, for a road that is TREATING a line
    rather than writing a round.

    The full plot clause is six hundred words of standing orders about
    staying in character and tracking the story out loud, which is
    exactly right for a writer and swamps a rhymer whose whole job is one
    line. This is the same fact in one sentence: here is the world, put
    the line inside it."""
    try:
        row = plot_owns_air()
        if not row:
            return ""
        act, at, of = plot_act_now(row)
        if not act:
            return ""
        title = str(row.get("title") or "untitled")[:70]
        say = ("AND THIS IS HAPPENING IN THE WORLD RIGHT NOW: \"" + title
               + "\", act " + str(at) + " of " + str(of) + " - "
               + str(act)[:cap]
               + " The line you are treating is being said BY someone "
               "inside that, so let it know: an image, a name, a turn of "
               "phrase out of the story is worth more than a general one. "
               "Never explain the story and never announce it.")
        return say
    except Exception:  # noqa: BLE001
        return ""


def plotline_run_clause(row: Any) -> str:
    """#1159: what to say when the same story is running again.

    Never pretend a repeat is a first time. The acts are the same shape
    and the world is the same world, but this is a NEW pass through it
    with different people, different calls and a different ending, and
    saying so out loud is what makes a serial a serial rather than a
    tape loop."""
    try:
        run = plotline_run(row)
        if run <= 1:
            return ""
        left = plotline_loops(row)
        return (
            " THIS STORY HAS COME ROUND AGAIN — it is pass number "
            + str(run) + " through the same acts"
            + (", and it keeps going until the operator stops it"
               if left < 0 else
               (" with " + str(left) + " more to come" if left > 0
                else ", and this is the last pass"))
            + ". The world and the acts are the same; WHAT HAPPENS IN THEM "
            "IS NOT. Different people, different calls, a different turn "
            "and a different ending. The booth may say the thing is "
            "happening AGAIN — that is the joke and it is allowed — but "
            "never repeat a line, a name or a gag from an earlier pass.")
    except Exception:  # noqa: BLE001
        return ""


def plotline_extra_clause(row: Any, at: int = 0, of: int = 0) -> str:
    """What plot_clause() could not say before: the SPAN, the position on
    the clock, the running account, and the order to track it OUT LOUD.

    Additive, like the rest of plot_clause and like crystal_clause: it
    rides beside whatever the round was already about. Never raises."""
    try:
        span = plotline_span_seconds(row)
        if span <= 0:
            return ""
        prog = plotline_progress(row)
        at = at or int(prog.get("act") or 0)
        said = (
            " THE STORY'S OWN CLOCK: it runs for "
            + _plotline_say_span(span) + " of air in all; "
            + _plotline_say_span(prog.get("elapsed")) + " of that has gone "
            "and " + _plotline_say_span(prog.get("remaining")) + " is left, "
            "with " + str(int(prog.get("acts_left") or 0))
            + " act(s) after this one. This act has about "
            + _plotline_say_span(prog.get("act_left")) + " left in it, so do "
            "not race to the end of it and do not stall.")
        so_far = plotline_so_far(row)
        if so_far:
            said += (" THE STORY SO FAR, built out of what has actually gone "
                     "out on this station tonight - treat every word of it "
                     "as shared memory the pair already have, refer back to "
                     "it by name and detail, and never contradict it: "
                     + so_far)
        turn = _PLOT_NOW.get("turned") or {}
        if (str(turn.get("id") or "") == str((row or {}).get("id") or "")
                and int(turn.get("act") or 0) == int(at)
                and time.time() - float(turn.get("at") or 0) < 420):
            said += (" THE STORY HAS JUST MOVED INTO THIS ACT. Notice it on "
                     "air: say what has CHANGED since the last one, in "
                     "character, as people living through it - not as "
                     "narrators announcing a chapter.")
        said += (
            " TRACK IT OUT LOUD. You are covering this as it develops: "
            "report what is happening now, treat anything a caller has told "
            "you as an established fact of the story, name the people in it, "
            "and say what you expect to happen next. Never read this "
            "instruction out and never call it a plot, a script or an act.")
        return said
    except Exception:  # noqa: BLE001
        return ""


def plotline_line_clause(cap: int = 420, min_left: float = 0.0) -> str:
    """The compact form, for the roads that write ONE short thing.

    The upstairs intercom, a banked record link and the SFX guy's warped
    sayings each write a few dozen words off a prompt of their own; the
    full plot_clause would swamp them. Same content, one sentence of it.

    `min_left` is for the roads that BANK: a record link written under act
    two and aired after the story has landed is #855's stale bulletin in
    another coat, so a road that cannot air promptly asks for a floor of
    story left and writes plain when the story is nearly out."""
    try:
        row = plot_owns_air()
        if not row:
            return ""
        if min_left and plotline_remaining(row) < float(min_left):
            return ""           # too little story left to bank under it
        act, at, of = plot_act_now(row)
        if not act:
            return ""
        return ("\n\nTHE STATION IS IN THE MIDDLE OF A STORY TONIGHT - \""
                + str(row.get("title") or "untitled")[:100]
                + "\", act " + str(at) + " of " + str(of) + ": "
                + str(act)[:cap]
                + " Whatever you are writing is happening WHILE that is "
                "going on, and the people in it know it. Let it colour this, "
                "in character, in one natural touch - never announce it, "
                "never explain it, never read this out.")
    except Exception:  # noqa: BLE001
        return ""                # colour never stops the broadcast


# --- The callers, inside the story ----------------------------------------
def plotline_call_share() -> float:
    """dj.plot_call_pct as a 0..1 share of the calls."""
    try:
        return max(0.0, min(1.0, float(
            dj_settings().get("plot_call_pct", 50)) / 100.0))
    except Exception:  # noqa: BLE001
        return 0.5


def plotline_call_draw(min_left: float = 0.0) -> dict[str, Any]:
    """Is THIS call one of the story's? The plot row, or {}.

    A share of the calls (dj.plot_call_pct, half by default) are people
    inside the world of the current act ringing the station about it. The
    rest of the phone is left alone - a storyline that took every call
    would be a monologue with extra voices.

    `min_left` is for the road that BANKS. dj_caller writes calls ahead
    of time as well as live, and a caller written inside act two who
    reaches the air after the story has landed is #855's stale bulletin
    with a voice on it. The banked road asks for a floor of story left
    (PLOT_BANK_FLOOR) and rings an ordinary caller when there is less.
    It BOUNDS the staleness rather than ending it: a shelved call may
    still sit past the floor, and only an air-time check could catch
    that - which would mean burning an unaired row, and #1151 settled
    that argument."""
    try:
        row = plot_owns_air()
        if not row or not plotline_acts(row):
            return {}
        if min_left and plotline_remaining(row) < float(min_left):
            return {}
        if random.random() >= plotline_call_share():
            return {}
        return row
    except Exception:  # noqa: BLE001
        return {}


def plotline_call_want(row: Any) -> str:
    """The premise the caller rings in with, out of the CURRENT act."""
    try:
        act, at, of = plot_act_now(row)
        if not act:
            return ""
        return (f"what is going on out there right now - {str(act)[:400]}"
                f" (act {at} of {of} of "
                f"\"{str((row or {}).get('title') or '')[:80]}\")")[:600]
    except Exception:  # noqa: BLE001
        return ""


def plotline_call_reason(name: str, row: Any) -> str:
    """The sentence that replaces "one of the listener's own past requests"
    on the request line when the caller is somebody inside the story."""
    try:
        act, _at, _of = plot_act_now(row)
        return (f"What got {name} on the air is what is happening out there "
                f"tonight: {str(act)[:320]} They are ringing because it has "
                "reached THEM.")
    except Exception:  # noqa: BLE001
        return ""


def plotline_caller_angle(row: Any) -> str:
    """The caller's brief: an ordinary person inside the current act.

    Additive, and deliberately NOT a repeat: successive callers carry the
    story FORWARD - each brings a new piece of it - rather than each
    restating the premise, which is the failure a serial dies of."""
    try:
        act, at, of = plot_act_now(row)
        if not act:
            return ""
        title = str((row or {}).get("title") or "untitled")[:120]
        said = (
            "\n\nTHIS CALLER IS INSIDE THE STORY (#1157). The station is "
            f"living through \"{title}\", and this is act {at} of {of}: "
            f"{str(act)[:600]} The person on the line is an ORDINARY MEMBER "
            "OF THE PUBLIC caught up in that - not a narrator, not a "
            "reporter, not somebody who has merely heard about it. They ring "
            "the station because it has happened TO them, or in front of "
            "them, tonight. Their reason for calling, everything they "
            "describe and everything they want is out of THIS act and "
            "nowhere else. They give ONE concrete new development - "
            "something specific they saw, lost, found, were told or did - "
            "that nobody has reported yet, and they never merely restate "
            "what is already known. The hosts take it as NEWS of the story: "
            "they react to it, ask what happened next, and treat it as "
            "established fact from here on.")
        so_far = plotline_so_far(row)
        if so_far:
            said += (" What the station already knows, and must not be told "
                     "again: " + so_far)
        if at >= of:
            said += (" This is the FINAL act - what this caller brings is "
                     "part of how it ENDS.")
        return said
    except Exception:  # noqa: BLE001
        return ""


# --- The tick --------------------------------------------------------------
def plotline_publish(row: Any) -> None:
    """Publish the hot-path view of the story (see _PLOT_NOW)."""
    try:
        keep = dict(_PLOT_NOW.get("turned") or {})
        _PLOT_NOW.clear()
        if row:
            _PLOT_NOW.update(plotline_meta(row))
            _PLOT_NOW["at"] = time.time()
        if keep:
            _PLOT_NOW["turned"] = keep
    except Exception:  # noqa: BLE001
        pass


async def plotline_tick() -> None:
    """The story's own clock, once every coordinator tick.

    Everything expensive is off this path: the beats are appended in a
    worker thread, the plot file is written at most every thirty seconds
    (and at a boundary), and the running account is a fire-and-forget
    model visit at an act boundary only. It never awaits the model and
    never raises into the coordinator."""
    now = time.time()
    # `ran` is 0.0 on the FIRST pass of a process. A story that was on air
    # when the box was restarted has a `ticked_at` from before the outage,
    # and the outage is not air: the clamp below charges it one tick.
    ran = float(_PLOT_TICK.get("at") or 0)
    since = (now - ran) if ran else 0.0
    _PLOT_TICK["at"] = now
    dirty = False
    save = False
    rows: list[dict[str, Any]] = []
    landed = ""
    turned: dict[str, Any] = {}
    live_row: dict[str, Any] = {}
    try:
        with _PLOT_LOCK:
            rows = plot_read()
            for row in rows:
                if plotline_span_seconds(row) <= 0:
                    continue
                if not (row.get("active") and not row.get("done")):
                    continue
                began = float(row.get("started_at") or 0)
                if began <= 0 or now < began:
                    continue            # armed for the top of the hour
                # Bank the air this pass bought. A gap far longer than the
                # tick is the process having been away - the show was not
                # on during it, so the story is not charged for it.
                if not plotline_frozen(row):
                    tick = max(float(row.get("ticked_at") or began), began)
                    gap = max(0.0, now - tick)
                    if not ran or gap > max(120.0, since * 4):
                        gap = min(gap, max(15.0, since))
                    row["air_elapsed"] = round(
                        float(row.get("air_elapsed") or 0.0) + gap, 2)
                row["ticked_at"] = now
                dirty = True
                acts = plotline_acts(row)
                span = plotline_span_seconds(row)
                gone = float(row.get("air_elapsed") or 0.0)
                if not acts or gone >= span:
                    # #1159: another run on it? Then this is not an ending,
                    # it is a curtain. The act marks and the story-so-far
                    # are cleared so act one opens on a clean clock; the
                    # BEATS ledger is left alone, because what aired
                    # actually aired and the serial column reads from it.
                    _left = plotline_loops(row) if acts else 0
                    if _left:
                        if _left > 0:
                            row["loops"] = _left - 1
                        row["run"] = plotline_run(row) + 1
                        row["air_elapsed"] = 0.0
                        row["started_at"] = now
                        row["ticked_at"] = now
                        row["act_idx"] = 0
                        row["act_live"] = 0
                        row["act_marks"] = {}
                        row["so_far"] = ""
                        row["so_far_act"] = 0
                        row["so_far_at"] = 0.0
                        row["half_hour_until"] = now + span
                        try:
                            row["half_hour"] = _plot_half_key(now)
                        except Exception:  # noqa: BLE001
                            pass
                        turned = {"id": str(row.get("id") or ""),
                                  "act": 1, "of": len(acts), "at": now,
                                  "run": row["run"]}
                        pipeline_log(
                            "air", "the storyline \"%s\" has come round "
                            "again - run %d, act 1 of %d, %s"
                            % (str(row.get("title") or "")[:50],
                               row["run"], len(acts),
                               "until it is stopped"
                               if plotline_loops(row) < 0
                               else "%d more run(s) after this"
                                    % plotline_loops(row)))
                        if not live_row and plotline_live(row):
                            live_row = dict(row)
                        continue
                    row["done"], row["active"] = True, False
                    row["act_idx"] = max(0, len(acts) - 1)
                    landed = str(row.get("title") or "")[:60]
                    continue
                at = plotline_act_index(row, len(acts))
                row["act_idx"] = at
                if int(row.get("act_live") or 0) != at + 1:
                    row["act_live"] = at + 1
                    marks = dict(row.get("act_marks") or {})
                    marks[str(at + 1)] = now
                    row["act_marks"] = marks
                    # #907's readers stay honest through a pause.
                    row["half_hour_until"] = now + max(0.0, span - gone)
                    turned = {"id": str(row.get("id") or ""),
                              "act": at + 1, "of": len(acts), "at": now}
                # #1157: the FIRST live row, which is the one
                # plot_owns_air() returns. This took the last one, so
                # with two plots switched on the air was coloured by
                # one story while every beat was filed under the other.
                if not live_row and plotline_live(row):
                    live_row = dict(row)
            save = bool(dirty and (turned or landed
                                   or now - float(_PLOT_TICK.get("wrote") or 0)
                                   >= PLOT_TICK_WRITE))
            if save:
                _PLOT_TICK["wrote"] = now
                _PLOT_AIR.update({"at": 0.0, "row": {}})
        if save:
            # Off the loop, and outside the lock plot_write takes itself.
            await asyncio.to_thread(plot_write, rows)
    except Exception:  # noqa: BLE001
        live_row = {}
    try:
        plotline_publish(live_row if plotline_live(live_row) else {})
        if turned:
            _PLOT_NOW["turned"] = turned
    except Exception:  # noqa: BLE001
        pass
    # The beats, written in a thread.
    try:
        with _PLOT_BEATS_LOCK:
            pending = list(_PLOT_BEATS)
            del _PLOT_BEATS[:]
        if pending:
            await asyncio.to_thread(_plotline_beats_append_blocking, pending)
    except Exception:  # noqa: BLE001
        pass
    if landed:
        try:
            pipeline_log("air", f"the storyline \"{landed}\" has played out "
                                "- its span is spent (#1157)")
        except Exception:  # noqa: BLE001
            pass
    if turned and int(turned.get("act") or 0) > 1:
        # A few lines of model work at an act boundary is fine; per round
        # is not. This is the only model call the storyline engine makes.
        try:
            fire_and_forget(plotline_so_far_write(str(turned.get("id") or "")))
            pipeline_log("air", "the storyline has moved into act "
                         f"{turned.get('act')}/{turned.get('of')} - the pair "
                         "will notice it on air (#1157)")
        except Exception:  # noqa: BLE001
            pass


async def plotline_state(row: dict[str, Any],
                         ledger: list[dict[str, Any]] | None = None
                         ) -> dict[str, Any]:
    """One plot, dressed for the desk: timetable, progress, beats.

    `ledger` is the whole beats tail, read ONCE by a caller dressing several
    plots — a desk listing sixty of them must not read the file sixty
    times."""
    out = dict(row)
    try:
        out["timetable"] = plotline_timetable(row)
        out["progress"] = plotline_progress(row)
        out["owns_air"] = plotline_live(row)
        if ledger is None:
            beats = await plotline_beats(str(row.get("id") or ""), 0, 120)
        else:
            beats = [b for b in ledger
                     if str(b.get("plot") or "") == str(row.get("id") or "")
                     ][-120:]
        by_act: dict[str, list[dict[str, Any]]] = {}
        for beat in beats:
            by_act.setdefault(str(int(beat.get("act") or 0)), []).append(
                {"at": beat.get("at"), "who": beat.get("who"),
                 "name": beat.get("name"), "round": beat.get("round"),
                 "text": str(beat.get("text") or "")[:240]})
        out["beats"] = {k: v[-8:] for k, v in by_act.items()}
        out["beats_count"] = len(beats)
    except Exception:  # noqa: BLE001
        out.setdefault("timetable", [])
        out.setdefault("progress", {})
        out.setdefault("beats", {})
    return out


@app.get("/api/dj/plots")
async def dj_plots_list(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """The shelf, and for each plot what #1157 added: the TIMETABLE
    (which act is live between which clock times), the live progress
    and the beats that actually aired under each act.

    The beats come off a JSONL tail read in a worker thread, so the
    desk polling this never stalls the loop (#1142/#1156)."""
    require_read_auth(authorization)
    rows = plot_read()
    try:
        ledger = await plotline_beats("", 0, PLOT_BEATS_KEPT)
    except Exception:  # noqa: BLE001
        ledger = []
    out: list[dict[str, Any]] = []
    for row in rows:
        try:
            out.append(await plotline_state(row, ledger))
        except Exception:  # noqa: BLE001
            out.append(dict(row))   # a broken plot is still listed
    return {"plots": out, "now": plotline_now(),
            "call_share": plotline_call_share(),
            "paused": bool(radio_paused())}


@app.post("/api/dj/plots")
async def dj_plots_save(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Write or rewrite a plotline: a title plus acts (a list, or one text
    split on blank lines / single lines)."""
    require_auth(authorization)
    payload = await request.json()
    title = str(payload.get("title") or "").strip()[:120]
    acts = payload.get("acts")
    if not isinstance(acts, list):
        raw = str(payload.get("text") or "")
        acts = [a.strip() for a in re.split(r"\n\s*\n|\n", raw) if a.strip()]
    acts = [str(a)[:600] for a in acts][:24]
    if not title or not acts:
        raise HTTPException(status_code=400,
                            detail="A plot needs a title and at least one act")
    with _PLOT_LOCK:
        rows = plot_read()
        pid = str(payload.get("id") or "")
        row = next((r for r in rows if r.get("id") == pid), None)
        # #1157: HOW LONG THE STORY RUNS, in the operator's own units
        # and kept with the plot rather than buried in an activate
        # payload. Minutes on the wire; the desk offers minutes or
        # hours. Absent means "leave it as it was" for an edit, and
        # one hour for a new plot, which is the commonest ask.
        _span = payload.get("span_minutes", payload.get("span"))
        try:
            _span = (max(1.0, min(float(PLOT_SPAN_MOST), float(_span)))
                     if _span not in (None, "") else 0.0)
        except Exception:  # noqa: BLE001
            _span = 0.0
        # #1159: and HOW MANY TIMES. -1 is "until I stop it"; absent
        # leaves an edited plot as it was and a new one playing once.
        _loops = payload.get("loops", None)
        try:
            _loops = (max(-1, min(PLOT_LOOPS_MOST, int(_loops)))
                      if _loops not in (None, "") else None)
        except Exception:  # noqa: BLE001
            _loops = None
        if row:
            row.update({"title": title, "acts": acts})
            if _span:
                row["span_minutes"] = round(_span, 2)
            if _loops is not None:
                row["loops"] = _loops
            if row.get("act_idx", 0) > len(acts):
                row["act_idx"] = 0
        else:
            row = {"id": uuid.uuid4().hex[:12], "title": title, "acts": acts,
                   "act_idx": 0, "active": False, "done": False,
                   "span_minutes": round(_span or 60.0, 2),
                   "loops": int(_loops or 0), "run": 1,
                   "ts": int(time.time())}
            rows.append(row)
        plot_write(rows)
    note_action(f"📖 plotline saved: {title[:50]}")
    return row


@app.post("/api/dj/plots/{plot_id}/activate")
async def dj_plots_activate(
    plot_id: str,
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Put a plotline on the air (deactivating any other) — or take it off.
    {on: bool, restart: bool}."""
    require_auth(authorization)
    payload = await request.json()
    on = bool(payload.get("on", True))
    with _PLOT_LOCK:
        rows = plot_read()
        row = next((r for r in rows if r.get("id") == plot_id), None)
        if not row:
            raise HTTPException(status_code=404, detail="No such plotline")
        for r in rows:
            r["active"] = False
        if on:
            row["active"] = True
            if payload.get("restart") or row.get("done"):
                row["act_idx"], row["done"] = 0, False
            # #1157: THE SPAN, FIRST CLASS. `span_minutes` (or the
            # plot's own stored span) starts a real clock: air
            # seconds against the minutes asked for, divided evenly
            # between the acts by plot_act_now. `start` is "now" or
            # "hour" (the top of the next one). The half_hours road
            # below is untouched for anything that still sends it.
            _mins = payload.get("span_minutes", payload.get("span"))
            try:
                _mins = float(_mins) if _mins not in (None, "") else 0.0
            except Exception:  # noqa: BLE001
                _mins = 0.0
            if not _mins and not payload.get("half_hour") \
                    and not payload.get("half_hours"):
                _mins = float(row.get("span_minutes") or 0)
            if _mins:
                plotline_arm(
                    row, _mins, str(payload.get("start") or "now"),
                    restart=bool(payload.get("restart", True)
                                 or not row.get("started_at")))
                plot_write(rows)
                _PLOT_AIR.update({"at": 0.0, "row": {}})
                note_action("📖 plotline ON AIR for "
                            + _plotline_say_span(_mins * 60.0) + ": "
                            + str(row.get("title") or "")[:50])
                fire_and_forget(plotline_tick())
                return row
            # #907: "have it color the entire half hour whenever a plot
            # line is active." A plot may now CLAIM the half hour it is
            # switched on in, and optionally the ones after it. While it
            # holds one, plot_clause() colours every segment's dialogue
            # and the acts walk across the stretch on the clock. Without
            # the flag a plot behaves exactly as it did before this
            # shipped, which is what keeps the old button honest.
            _halves = max(0, min(48, int(payload.get("half_hours") or 0)))
            if payload.get("half_hour") or _halves:
                _halves = _halves or 1
                row["half_hour"] = _plot_half_key()
                _began, _ = plot_half_bounds(str(row["half_hour"]))
                row["half_hour_until"] = (_began + 1800.0 * _halves
                                          if _began else 0.0)
                row["act_idx"] = 0
            else:
                row["half_hour"], row["half_hour_until"] = "", 0.0
        else:
            row["half_hour"], row["half_hour_until"] = "", 0.0
        plot_write(rows)
        # #907: the dial takes the air NOW — the two-second memo would
        # otherwise leave a freshly claimed half hour uncoloured for a
        # round, and #819/#820 already settled that argument.
        _PLOT_AIR.update({"at": 0.0, "row": {}})
    if on:
        note_action(f"📖 plotline ON AIR: {row.get('title', '')[:50]}")
    return row


@app.post("/api/dj/plots/{plot_id}/control")
async def dj_plots_control(
    plot_id: str,
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """The four things an operator wants mid-story (#1157).

    {do: "hold"}   stop the story's clock without losing its place
    {do: "resume"} start it again from exactly where it stopped
    {do: "next"}   jump to the next act now
    {do: "end"}    land it early: the span is spent, the plot is done

    A hold is the story's own pause and is honoured the same way the
    station's is: the clock stops, so the acts are not spent while
    nothing is happening (#1150)."""
    require_auth(authorization)
    payload = await request.json()
    do = str(payload.get("do") or "").strip().lower()
    if do not in ("hold", "resume", "next", "end"):
        raise HTTPException(
            status_code=400,
            detail="do must be hold, resume, next or end")
    with _PLOT_LOCK:
        rows = plot_read()
        row = next((r for r in rows if r.get("id") == plot_id), None)
        if not row:
            raise HTTPException(status_code=404, detail="No such plotline")
        # Bank the air bought so far BEFORE changing anything, or a
        # hold would keep the seconds it was holding against.
        row["air_elapsed"] = round(plotline_elapsed(row), 2)
        row["ticked_at"] = time.time()
        acts = plotline_acts(row)
        span = plotline_span_seconds(row)
        if do == "hold":
            row["held"] = True
        elif do == "resume":
            row["held"] = False
            # #1157: and it takes the air off every other plot, exactly
            # as the activate route does. This was the one door that
            # could leave two storylines on at once, and two storylines
            # on at once is two stories the pair are living in.
            for _other in rows:
                if _other is not row:
                    _other["active"] = False
            row["active"], row["done"] = True, False
        elif do == "next" and acts and span > 0:
            each = span / len(acts)
            at = plotline_act_index(row, len(acts))
            row["air_elapsed"] = round(min(span, each * (at + 1)) + 0.5, 2)
            if row["air_elapsed"] >= span:
                row["done"], row["active"] = True, False
        elif do == "end":
            row["air_elapsed"] = round(span, 2) if span > 0 else 0.0
            row["done"], row["active"], row["held"] = True, False, False
        plot_write(rows)
        _PLOT_AIR.update({"at": 0.0, "row": {}})
        out = dict(row)
    note_action("📖 plotline " + do + ": "
                + str(out.get("title") or "")[:50])
    fire_and_forget(plotline_tick())
    return await plotline_state(out)


@app.delete("/api/dj/plots/{plot_id}")
async def dj_plots_delete(
    plot_id: str,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    require_auth(authorization)
    with _PLOT_LOCK:
        plot_write([r for r in plot_read() if r.get("id") != plot_id])
    return {"ok": True}


# The machines that make the show, introduced as sponsors (#362).
SPONSOR_SERVICES = ("ollama", "xtts", "voice-lab", "comfyui",
                    "wyoming-piper", "wyoming-whisper")


async def service_sponsor_facts(name: str) -> list[str]:
    """Live numbers for tonight's sponsor (#362) — real probes of the
    actual service, never invented."""
    facts: list[str] = []
    try:
        async with httpx.AsyncClient(timeout=6) as client:
            if name == "ollama":
                ps = (await client.get(f"{OLLAMA_URL}/api/ps")).json() or {}
                for m in ps.get("models", []):
                    size = (m.get("size_vram") or m.get("size") or 0) / 1e9
                    facts.append(
                        f"model {m.get('name')} resident in {size:.1f} GB "
                        f"of VRAM with a context window of "
                        f"{m.get('context_length') or 'many'} tokens")
                tags = (await client.get(
                    f"{OLLAMA_URL}/api/tags")).json() or {}
                facts.append(f"{len(tags.get('models') or [])} models "
                             "installed and ready to swap in")
                facts.append("every word the presenters say is written "
                             "through it")
            elif name == "xtts":
                health = await xtts_health()
                if health.get("ready"):
                    facts.append("the voice-cloning server is up and "
                                 "answering — every cloned voice on this "
                                 "show renders through it, a few seconds "
                                 "a line, latents cached per voice")
                else:
                    facts.append("the voice-cloning server is resting "
                                 "between shifts")
            elif name == "voice-lab":
                r = await client.get(f"{VOICE_LAB_URL}/health")
                facts.append(
                    "the voice laboratory is "
                    + ("open" if r.status_code == 200 else "closed")
                    + " — it dissects whole videos into voices: "
                    "transcription, speaker separation on the GPU, pitch "
                    "and cadence analysis, a reference voice at the end")
            elif name == "comfyui":
                r = (await client.get(
                    f"{COMFYUI_URL}/system_stats")).json() or {}
                dev = (r.get("devices") or [{}])[0]
                vram = (dev.get("vram_total") or 0) / 1e9
                facts.append(
                    "the painting machine runs on "
                    + str(dev.get("name") or "the GPU")[:44]
                    + (f" with {vram:.0f} GB at its disposal" if vram
                       else "")
                    + " — every canvas in the station gallery came out "
                    "of it")
            elif name in ("wyoming-piper", "wyoming-whisper"):
                port = 10200 if name == "wyoming-piper" else 10300
                _r, writer = await asyncio.wait_for(
                    asyncio.open_connection("127.0.0.1", port), 4)
                writer.close()
                facts.append(
                    ("the piper voice engine" if port == 10200
                     else "the whisper transcriber")
                    + f" is answering on port {port}, on duty around "
                    "the clock")
    except Exception:
        pass
    return facts


async def dj_service_ad() -> list[str]:
    """Tonight's sponsor is one of the machines (#362): a real service
    running on the DGX Spark, introduced like a product, its live
    numbers read on air."""
    name = unrepeated(list(SPONSOR_SERVICES), "sponsor-service")
    facts = await service_sponsor_facts(name)
    stats = spoken_units("; ".join(facts) if facts
                         else "its numbers are a trade secret tonight")
    _spot_at = time.time()                                        # #892
    _spot = await dj_banter(None, lines=4, angle=(
        f"A SPONSOR SPOT for tonight's sponsor: {name.upper()}, one of "
        "the actual services running on the DGX Spark this station lives "
        "on. The TWO of you sell it TOGETHER, trading it back and forth — "
        "one rattles off a number like a luxury product, the OTHER reacts, "
        "tops it, or is flat-out incredulous; keep alternating, never a "
        "monologue. Its live numbers, real, off the wire this second — use "
        f"several verbatim between you: {stats}. One of you notes, with mild "
        "vertigo, that this very ad was written by the machinery being "
        "advertised, and the other has to sit with that."))
    # #892: this IS an advert — a sponsor sold on air — and it went out as
    # ordinary banter with nothing in the booth saying a spot had run. The
    # read itself stays where it is, in the pair's own lines; this is the
    # LISTING above it, so the log shows an ad aired here.
    if _spot:
        ad_booth_row("\U0001f4e3 sponsor spot \u2014 " + name.upper(),
                     product=name, air_at=_spot_at)
    return _spot


async def dj_engineering_ad() -> list[str]:
    """The station engineering report (#354): the DGX Spark's own live
    numbers — temperature, GPU, memory, load — read on air as though the
    machine itself were the sponsor."""
    stats = spoken_units(await asyncio.to_thread(system_stats))
    _spot_at = time.time()                                        # #892
    _spot = await dj_banter(None, lines=4, angle=(
        "The STATION ENGINEERING REPORT as a sponsor spot — the sponsor is "
        "the DGX Spark, the machine this very station runs on. The TWO of "
        "you deliver it TOGETHER, trading it back and forth: one reads a "
        "figure off like a press officer, the OTHER reacts — gloats about "
        "the good ones, spins the bad ones, tops the last brag. Keep "
        "alternating, never a monologue. These are its live numbers, real, "
        f"straight off the sensors this second: {stats} Use several of them "
        "verbatim between you and sell the machine like a luxury product."))
    # #892: the engineering report is sold as a sponsor spot, so it is an
    # ad, so it is listed — same as every other road.
    if _spot:
        ad_booth_row("\U0001f4e3 sponsor spot \u2014 the DGX Spark itself",
                     product="the DGX Spark", air_at=_spot_at)
    return _spot


async def dj_ad(product: str, remember: bool = True,
                custom: bool = False,
                script: str = "") -> dict[str, Any]:
    """Write, speak and keep an ad read. A CUSTOM ad (one the DJs make on
    demand) always gets a sound effect mixed in and is kept a week (#464)."""
    # What is being SOLD right now (#668), so the booth can hold it up the
    # way it already holds up the paintings.
    ad_now_set(product)                                   # #900
    # #842: `script` is a read WRITTEN AHEAD — and already rendered into
    # the pantry — so it is handed to dj_speak as the line itself: spoken
    # word for word, with its audio found rather than made. Empty means
    # the read is written here and now, exactly as it always was.
    line = await dj_speak("ad", _RADIO.get("now"), extra=product,
                          line=script, sting=not custom)
    # Custom ads always punch in an SFX (#464) — forced past the rate gate,
    # dropped off the end of the read where a second announce is safe.
    if custom and line and (_RADIO.get("voice_to") or "box") in ("box", "both"):
        try:
            await dj_sting(to_box=True, who="dj", force=True)
        except Exception:
            pass
    entry = (ad_save(product, line, kind="custom" if custom else "sponsor")
             if (remember and line) else None)
    if entry:
        ad_line_mark(entry.get("id", ""), product)
        ad_aired(entry, _RADIO.get("voice_to") or "box")             # #743
    elif line:
        ad_aired({"product": product, "text": line},
                 _RADIO.get("voice_to") or "box")
    back = ""
    if _RADIO["on"] and _RADIO.get("now"):
        back = await dj_speak(
            "interject", _RADIO["now"],
            # #901: drawn, not hardcoded — see AD_HANDOFFS.
            line=_dj_fill(unrepeated(
                list(AD_HANDOFFS), "ad_handoff",
                keep=max(1, len(AD_HANDOFFS) - 2))))
    return {"ad": line, "back": back, "product": product,
            "id": (entry or {}).get("id", "")}


def ad_line_mark(ad_id: str, product: str, audio: str = "") -> None:
    """Stamp the ad that just aired onto its own line in the booth (#701).

    An ad went out as an ordinary DJ line — same shape, same colour, no way
    to tell it from banter and nothing to click. Everything needed to make
    it an entry exists by the time ad_save() returns; it just was not put
    anywhere. The line is found by walking back for the most recent ad line
    that has not been claimed, which is the one we have just spoken."""
    for entry in reversed(_RADIO.get("chat") or []):
        if entry.get("kind") == "ad" and not entry.get("ad_id"):
            entry["ad_id"] = str(ad_id or "")
            entry["product"] = str(product or "")[:160]
            # #783: "for every listed entry that is part of an ad ... I want
            # an option to be able to download that entry". A spot read live
            # arrives here with no `audio` because nothing was produced for
            # it as a file — but the produced cut often exists already under
            # its id, and without this the tile drew no play and no download
            # at all. Look before giving up.
            if not audio and ad_id:
                _made = PRODUCED_ADS_DIR / f"{ad_id}.mp3"
                if _made.is_file():
                    audio = f"{ad_id}.mp3"
            if audio:
                entry["ad_audio"] = str(audio)
                # #733: /ads-audio is signed exactly like /media, and
                # a plain <a download> cannot send a bearer header. The
                # signature never rode along on the booth line, so the
                # "keep it" link on every ad answered 401.
                entry["ad_sig"] = media_sign(str(audio))
            return
        # Only look back over the handful of lines an ad can span.
        if entry.get("kind") not in ("ad", "sfx"):
            return


def ad_booth_row(text: str, product: str = "", who: str = "dj",
                 name: str = "the desk", ad_id: str = "", audio: str = "",
                 media: str = "", sig: str = "", voice: str = "",
                 aired: str = "", air_at: float = 0.0) -> dict[str, Any]:
    """#892: "If an ad is ran, be sure to list it in the booth."

    One listing, one shape, for every road an advert can air on. The shape
    is the one dj_speak already writes — who, kind, text, air_at, an id —
    so the booth sorts it with everything else, the delivery mark lands on
    it, and the ad tile finds its clip.

    `aired` is only ever one of the values the panel's ladder actually
    knows: airing / held / published / never / box / stream. Left empty it is
    read off the DJ-VOICE routing, which is what decides where an ad goes:
    the box (or both) means the speaker had it, the page means the browser
    feed awaiting a browser ACK, and muted output means nobody heard it — "never",
    not a quiet lie about having aired.

    `audio` names a durable spot under /ads-audio; `media` is a served clip
    key or path under /media (a music-bedded spot is mixed fresh and lives
    there). Either gives the tile its play and its download. Never raises:
    a booth listing is not worth taking the show off air for."""
    try:
        to = str(_RADIO.get("voice_to") or "box")
        if not aired:
            aired = ("box" if to in ("box", "both")
                     else "published" if to == "here" else "never")
        if aired not in ("airing", "held", "published", "never", "box", "stream"):
            aired = "box"
        row: dict[str, Any] = {
            "id": uuid.uuid4().hex[:6],
            "ts": int(time.time()),
            "air_at": float(air_at or time.time()),
            "who": str(who or "dj"),
            "kind": "ad",
            "name": booth_actor_name(who, name),
            "text": str(text or "")[:1200],
            "product": str(product or "")[:160],
            "voice": str(voice or ""),
            "aired": aired,
        }
        # #1005: "the only thing that would make this ad even better for
        # this painting ad would be to actually see the painting on the
        # side in the chat in the booth dialogue window."
        #
        # The gallery ROUND already hangs its picture on the lines that
        # discuss it (#702/#991) - the ad road never did, and a spot whose
        # whole job is selling a painting is the place it is most wanted.
        # ad_now_set has already resolved the file (from the stamp, or by
        # reading the title back out of the read itself), so this is the
        # same picture the marquee is holding up, on the line that is
        # selling it. Empty when the spot is not selling a picture, which
        # is no thumbnail rather than the wrong one.
        try:
            _sell = _RADIO.get("ad_now") or {}
            _pic = str(_sell.get("image") or "")
            if _pic and time.time() - float(_sell.get("at") or 0) < 300:
                row["images"] = [_pic]
                if _sell.get("title"):
                    row["sold_title"] = str(_sell.get("title"))[:160]
                if _sell.get("price"):
                    row["sold_price"] = int(_sell.get("price") or 0)
        except Exception:  # noqa: BLE001
            pass
        if ad_id:
            row["ad_id"] = str(ad_id)
        if audio:
            row["ad_audio"] = str(audio)
            try:
                row["ad_sig"] = media_sign(str(audio))
            except Exception:  # noqa: BLE001
                pass
        if media:
            # A path or a bare key, both accepted — the booth wants the key.
            key = str(media).rsplit("/", 1)[-1].split("?")[0]
            if key:
                row["media"] = key
                row["sig"] = str(sig or "")
        _RADIO["chat"].append(row)
        del _RADIO["chat"][:-240]
        return row
    except Exception:  # noqa: BLE001
        return {}


def _store_media(audio: bytes, ext: str = "wav") -> dict[str, Any]:
    """Write finished audio bytes as a served clip — the same mint-key-write
    -prune the synth path uses, factored out so mixed clips (music-bed ads)
    can be served too."""
    key = uuid.uuid4().hex + "." + (ext if ext in MEDIA_TYPES else "wav")
    VOICE_MEDIA_DIR.mkdir(parents=True, exist_ok=True)
    (VOICE_MEDIA_DIR / key).write_bytes(audio)
    _media_prune()
    # #999: the earliest instant this audio exists. If anyone is
    # listening on a metered link, their copy starts encoding now - long
    # before the page is ever told the clip exists. Costs nothing when
    # every listener is on the original.
    low_ready_soon(key)
    return {"path": f"/media/{key}", "sig": media_sign(key), "bytes": len(audio)}


def _media_file(path: str) -> Path | None:
    """#993: the FILE behind a served clip path.

    _store_media hands back {"path": "/media/<key>"} - a URL for the
    page, not a filename - and several roads have to hand that audio to
    ffmpeg or read its bytes. Written out longhand at each of them it was
    got wrong at least once (see the note in voice_render_any), so it
    lives here once. Returns None when the clip is not one of ours or is
    no longer on disk, which every caller must treat as "no audio"."""
    name = str(path or "").rsplit("/", 1)[-1].strip()
    if not name or "\\" in name or name in (".", ".."):
        return None
    try:
        fp = VOICE_MEDIA_DIR / name
        return fp if fp.is_file() else None
    except Exception:  # noqa: BLE001
        return None


def _siren_sample() -> str | None:
    """A real siren off the sample shelf if the library has one; otherwise
    the mix synthesises its own (#636)."""
    try:
        want = re.compile(r"siren|police|emergency|ambulance|alarm", re.I)
        pool = [p for p in sfx_all() if want.search(p.stem)]
    except Exception:
        pool = []
    return str(random.choice(pool)) if pool else None


def _police_mix_blocking(voice_path: Path, seconds: float,
                         siren_path: str | None = None) -> bytes | None:
    """Somebody outside on a bullhorn (#636).

    The read band-limited and slammed the way a megaphone slams, thrown back
    off the buildings opposite, with a siren wailing somewhere behind it.
    One filter_complex — an -af chain splits on the commas. Returns None on
    any failure so the caller can fall back to the dry vocoded read.
    """
    import subprocess

    import imageio_ffmpeg
    exe = imageio_ffmpeg.get_ffmpeg_exe()
    lead, tail = 1.6, 2.4
    total = lead + max(1.0, seconds) + tail
    lead_ms = int(lead * 1000)
    # A wail is one tone frequency-modulated by a slow sine. No commas in the
    # expression, so it survives every quoting layer between here and ffmpeg.
    lavfi = (f"aevalsrc=0.55*sin(2*PI*(720*t+260*sin(2*PI*0.33*t)))"
             f":s=24000:d={total:.2f}")
    graph = (
        # THE MEGAPHONE: telephone band, hard compression, a shove of gain,
        # then the street — two slapbacks off the buildings opposite.
        "[0:a]aresample=24000,aformat=sample_fmts=s16:channel_layouts=mono,"
        "highpass=f=450,lowpass=f=3000,"
        "acompressor=threshold=-18dB:ratio=9:attack=5:release=120:makeup=8dB,"
        "volume=5dB,alimiter=limit=0.9,"
        "aecho=0.8:0.88:150|380:0.32|0.16,"
        f"adelay={lead_ms}|{lead_ms},apad=pad_dur={tail:.2f}[cop];"
        # THE SIRENS: distant, so the top and the bottom are gone and it is
        # quiet, swelling in and away with a long reflection behind it.
        "[1:a]aformat=sample_fmts=s16:channel_layouts=mono,"
        f"atrim=0:{total:.2f},asetpts=PTS-STARTPTS,"
        "highpass=f=500,lowpass=f=2400,volume=0.11,"
        f"afade=t=in:st=0:d=1.4,afade=t=out:st={max(0.0, total - 1.8):.2f}"
        ":d=1.8,aecho=0.7:0.7:520:0.3[siren];"
        "[cop][siren]amix=inputs=2:duration=first:normalize=0,"
        "alimiter=limit=0.95[out]"
    )
    ins = (["-i", str(voice_path)]
           + (["-i", siren_path] if siren_path
              else ["-f", "lavfi", "-i", lavfi]))
    try:
        out = subprocess.run(
            [exe, "-nostdin", "-hide_banner", "-loglevel", "error", *ins,
             "-filter_complex", graph, "-map", "[out]",
             "-ac", "1", "-ar", "24000", "-sample_fmt", "s16",
             "-f", "wav", "pipe:1"],
            capture_output=True, timeout=90)
        blob = out.stdout
    except Exception:
        return None
    return blob if len(blob) > 2000 else None


async def dj_police_outside(text: str) -> None:
    """The megaphone outside the window (#636).

    A random vocoder character off the same rack the callers use, then the
    megaphone and the sirens, then straight onto the air as a clip — no booth
    voice speaks this, which is the point: it comes from OUTSIDE.
    """
    voices = await session_voices()
    names = [c for c in sorted(VOCODER_CHARACTERS)
             if c not in ("plain", "autotune", "choir")]
    character = random.choice(names) if names else "plain"
    try:
        voice = caller_voice_for(
            "the officer outside",
            {voices.get("dj", ""), voices.get("cohost", "")},
            await voice_allowlist(),
            clones=await voicepolicy_clone_pool_async()) or ""   # #1021
    except Exception:
        voice = ""
    engine = voice_engine_for(voice)
    # #746: BOTH cloning engines. This probed XTTS only, so an
    # F5 voice with :8772 down raised out of voice_generate
    # instead of falling back to Piper like everything else.
    if engine in ("xtts", "f5") \
            and not await clone_engine_ready(engine):
        engine, voice = await voicepolicy_preempt(engine, voice, "police")  # #1021
    try:
        clip = await voice_generate(
            spoken_text(text), voice, engine,
            fx={"vocode": character,
                "pitch": VOCODER_DEFAULT_PITCH.get(
                    character, random.randint(-4, 4))})
    except Exception:
        clip = None
    if not clip:
        return
    key = clip["path"].rsplit("/", 1)[-1].split("?")[0]
    wav = await asyncio.to_thread(
        _police_mix_blocking, VOICE_MEDIA_DIR / key,
        _clip_seconds(clip["path"]) or 6.0,
        await asyncio.to_thread(_siren_sample))
    play = _store_media(wav, "wav") if wav else clip
    label = "🚨 someone outside, on a megaphone"
    to = _RADIO.get("voice_to") or "box"
    if to in ("box", "both"):
        await _play_on_box(play["path"], play["sig"])
    if to in ("here", "both") or not box_talk_ok():
        page_feed_append({              # #1147: honest broadcast stamp
            "url": f"{play['path']}?t={play['sig']}",
            "text": label, "voice": voice})
    _episode_stage(f"{play['path']}?t={play['sig']}", label)
    pipeline_log("air", f"megaphone outside — {character} vocode, "
                        f"sirens behind (#636)")
    # And the pair have to deal with it.
    asyncio.create_task(dj_banter(
        _RADIO.get("now"), lines=3,
        angle=("Someone is OUTSIDE the studio window with a megaphone and "
               "you both just heard it come through the glass, sirens "
               "somewhere behind them. What they shouted, as best you could "
               f"make it out, was: \"{text}\". React live — look out of the "
               "window, describe what you can see, decide whether to keep "
               "broadcasting.")))


# --- The manager upstairs (#749) --------------------------------------------
#
# There has always been a manager — dj_manager_note reads the system prompt
# out as a memo, dj_manager_call puts him on the booth phone — but he was
# never a VOICE you hear. He was the pair describing having heard something.
#
# This is the intercom: a page written against whatever is actually
# happening on air, spoken by one of the station's own cloned voices with a
# vocoder over it, PLAYED as its own clip, and then dealt with live. Roughly
# three an hour, on its own clock, and it is allowed to land in the middle
# of a phone call because that is the whole comedy of it.
#
# Every page is kept, because the operator asked to proofread them: they are
# a book like the ad book, editable and downloadable from the same modal.
UPSTAIRS_PATH = data_path("upstairs_pages.json")
_UPSTAIRS_LOCK = RLock()
UPSTAIRS_AUDIO_DIR = data_path("upstairs_audio")
UPSTAIRS_AUDIO_SHAPE = re.compile(r"^[a-f0-9]{6,32}\.mp3\Z")
UPSTAIRS_KEEP = 300

# The register, not the script. The model is told to top these, the way
# HEAT_SO_HOT is used — a fixed list of gripes read out verbatim would be
# the repetition #752 is about.
UPSTAIRS_GRIPES = (
    "spin more records and talk less",
    "get back to work — the request line is not answering itself",
    "the lunch breaks are out of hand and everybody upstairs knows it",
    "neither of you is worth what this station is paying",
    "the callers are being handled far too slowly",
    "who set the studio on fire, and why did nobody file anything",
    "the turntable is being sold and people are coming for it this week",
    "the equipment budget is gone and it is going to be somebody's fault",
    "there have been complaints, and they are not going to be shared",
    "somebody has been in the building after hours and it will come out",
    "the coffee order has been cancelled, permanently, as a lesson",
    "a consultant is coming in and neither of you will enjoy it",
)


# #1162: how often a round gets interrupted from upstairs. One in five is
# enough to be a running feature of the station and rare enough that it is
# still an interruption when it happens - at one in two it stops being one.
MANAGER_CUT_IN_PCT = 20
# #1173: and how often the memo entry itself is a personal gripe.
MANAGER_GRIPE_PCT = 65

# The ways it arrives. Rolled per interruption, because a memo slid under
# the door and a phone light blinking are different scenes even when the
# complaint is identical - the same lesson as #1161's deck.
MANAGER_CUT_INS: tuple[str, ...] = (
    "the intercom crackles and the manager's voice comes through the wall",
    "a memo comes down and is slid under the booth door",
    "the studio phone light starts blinking and will not stop",
    "a runner puts a folded note on the desk without a word and leaves",
    "the manager knocks on the glass and mouths it, and it has to be "
    "guessed at",
    "an email lands and the screen is right there in front of them",
)

# What the pair do about it. Also rolled: a memo that is always read out
# in the same tone is a jingle.
MANAGER_CUT_REACTS: tuple[str, ...] = (
    "One of them reads it out loud, flatly, and the other has an opinion "
    "about it immediately.",
    "Neither of them wants to be the one to read it, and they argue about "
    "that first.",
    "They read it, agree it is outrageous, and then quietly do what it "
    "says anyway.",
    "One of them takes it personally - it is clearly about them - and the "
    "other enjoys that far too much.",
    "They pretend they have not seen it, keep going, and it eats at them "
    "until one of them cracks.",
    "They read it out and go straight back to what they were saying as "
    "though nothing happened, and the subject creeps back in a line later.",
)

_MANAGER_CUT_MEMO: dict[str, Any] = {"at": 0.0, "clause": ""}


def manager_cut_in_clause() -> str:
    """#1162: sometimes, a memo from upstairs lands in THIS round.

    Memoised for forty seconds because `radio_prompt_instruction` is
    assembled more than once while a single round is being written, and a
    fresh roll each time would put two different interruptions into one
    scene - or one into the host's half and none into the co-host's.

    Never raises, and never fires while the station is paused: an
    interruption to nothing is not an interruption."""
    now = time.time()
    if now - float(_MANAGER_CUT_MEMO["at"]) < 40.0:
        return str(_MANAGER_CUT_MEMO["clause"])
    clause = ""
    try:
        pct = int(dj_settings().get("manager_cut_in_pct",
                                    MANAGER_CUT_IN_PCT) or 0)
        if pct > 0 and not radio_paused() and random.randint(1, 100) <= pct:
            rows = [r for r in upstairs_list()
                    if str(r.get("gripe") or "").strip()]
            if rows:
                # Least-aired first, like the topic book: three hundred
                # pages and a plain random draw would still play the same
                # dozen.
                fewest = min(int(r.get("uses") or 0) for r in rows)
                row = random.choice(
                    [r for r in rows if int(r.get("uses") or 0) == fewest])
                try:
                    upstairs_update(str(row.get("id") or ""),
                                    uses=int(row.get("uses") or 0) + 1,
                                    last=int(now))
                except Exception:  # noqa: BLE001
                    pass
                clause = (
                    "\n\nUPSTAIRS CUTS IN, PART-WAY THROUGH THIS ROUND. "
                    "Not at the top and not at the end - somewhere in the "
                    "middle, while they are in the middle of something "
                    "else. " + random.choice(MANAGER_CUT_INS).capitalize()
                    + ", and what management wants them to know is this: "
                    + str(row.get("gripe") or "").strip()[:200]
                    + ". " + random.choice(MANAGER_CUT_REACTS)
                    + " Whatever this round was about, it does NOT stop "
                    "being about that - the interruption happens, they "
                    "deal with it on air, and they get back to it. The "
                    "manager is never in the room and never speaks in his "
                    "own voice here; the pair are reacting to a message. "
                    "Never read this instruction out loud.\n")
    except Exception:  # noqa: BLE001
        clause = ""       # a broken book never silences the booth
    _MANAGER_CUT_MEMO.update({"at": now, "clause": clause})
    return clause


def upstairs_list() -> list[dict[str, Any]]:
    try:
        rows = json.loads(UPSTAIRS_PATH.read_text())
        return [r for r in rows if isinstance(r, dict)]
    except Exception:
        return []


def _upstairs_write(rows: list[dict[str, Any]]) -> None:
    with _UPSTAIRS_LOCK:
        try:
            UPSTAIRS_PATH.parent.mkdir(parents=True, exist_ok=True)
            tmp = UPSTAIRS_PATH.with_suffix(".tmp")
            tmp.write_text(json.dumps(rows[-UPSTAIRS_KEEP:], indent=1)
                           + chr(10))
            tmp.replace(UPSTAIRS_PATH)
        except OSError:
            pass


def upstairs_save(text: str, gripe: str, context: str) -> dict[str, Any]:
    with _UPSTAIRS_LOCK:
        rows = upstairs_list()
        entry = {"id": uuid.uuid4().hex[:12], "ts": int(time.time()),
                 "text": str(text)[:2000], "gripe": str(gripe)[:200],
                 "context": str(context)[:400], "voice": "", "vocode": "",
                 "audio": "", "uses": 0, "last": 0}
        rows.append(entry)
        _upstairs_write(rows)
        return entry


def upstairs_update(page_id: str, **fields: Any) -> dict[str, Any] | None:
    with _UPSTAIRS_LOCK:
        rows = upstairs_list()
        for row in rows:
            if row.get("id") != page_id:
                continue
            for key, value in fields.items():
                if key in ("text", "gripe", "context", "voice", "vocode",
                           "audio"):
                    row[key] = str(value)[:2000]
                elif key in ("uses", "last"):
                    row[key] = int(value)
            _upstairs_write(rows)
            return row
    return None


def upstairs_delete(page_id: str) -> None:
    with _UPSTAIRS_LOCK:
        rows = upstairs_list()
        gone = next((r for r in rows if r.get("id") == page_id), None)
        if gone and gone.get("audio"):
            try:
                (UPSTAIRS_AUDIO_DIR / str(gone["audio"])).unlink(
                    missing_ok=True)
            except OSError:
                pass
        _upstairs_write([r for r in rows if r.get("id") != page_id])


# #1146: THE MEMO BOOK. The operator reads the manager's memos for fun and
# asked for them "stored en masse" - so every memo the quota road writes or
# airs is kept here for good, the way the intercom keeps its pages (#749).
# The shelf stays working inventory (it is consumed, recast and burned);
# this is the archive that road never had: banked memos land at write time,
# live ones as they air, and airing a banked one stamps the original's
# ledger instead of writing a twin.
MANAGER_MEMOS_PATH = data_path("manager_memos.json")
_MANAGER_MEMOS_LOCK = RLock()
MANAGER_MEMOS_KEEP = 1000


def _manager_memo_print(text: str) -> str:
    """Marker/punctuation-insensitive identity for one memo's dialogue.

    A banked script says "A: ..."; the same memo aired live says
    "dj: ..." - both label shapes are shed so the aired twin stamps the
    banked original's ledger instead of writing a second row."""
    flat = re.sub(r"^[a-z0-9_' ]{1,20}:\s*", "",
                  str(text or "").lower(), flags=re.M)
    flat = re.sub(r"[^a-z0-9']+", " ", flat)
    return hashlib.sha1(
        " ".join(flat.split()).encode("utf-8", "ignore")).hexdigest()


def _manager_memos_read() -> list[dict[str, Any]] | None:
    """The book, or None when it EXISTS but cannot be read right now.

    Review: this path lives on a slow SMB share. A transient read fault
    answered [] used to feed the next save, which then rewrote the whole
    book as one row - the permanent archive wiped by a hiccup. None is
    the writers' signal to stand down rather than clobber."""
    try:
        if not MANAGER_MEMOS_PATH.exists():
            return []
        rows = json.loads(MANAGER_MEMOS_PATH.read_text())
        return [r for r in rows if isinstance(r, dict)]
    except Exception:  # noqa: BLE001
        return None


def manager_memos_list() -> list[dict[str, Any]]:
    return _manager_memos_read() or []


def _manager_memos_write(rows: list[dict[str, Any]]) -> None:
    with _MANAGER_MEMOS_LOCK:
        try:
            MANAGER_MEMOS_PATH.parent.mkdir(parents=True, exist_ok=True)
            tmp = MANAGER_MEMOS_PATH.with_suffix(".tmp")
            tmp.write_text(json.dumps(rows[-MANAGER_MEMOS_KEEP:], indent=1)
                           + chr(10))
            tmp.replace(MANAGER_MEMOS_PATH)
        except OSError:
            pass


def manager_memo_save(text: str, how: str = "",
                      aired: bool = False,
                      memo_id: str = "") -> dict[str, Any] | None:
    """Keep one memo, once - a twin only stamps the original's ledger.

    `memo_id` is the banked row's claim on its own book entry: a memo
    banked plain and tinted later airs with DIFFERENT words, so the
    print alone would file the aired version as a second memo. The
    shelf row carries the id it was booked under, and airing it updates
    that one row - words and ledger together."""
    script = str(text or "").strip()
    if not script:
        return None
    with _MANAGER_MEMOS_LOCK:
        rows = _manager_memos_read()
        if rows is None:
            return None                 # never clobber an unreadable book
        print_ = _manager_memo_print(script)
        if memo_id:
            for row in rows:
                if str(row.get("id") or "") == str(memo_id):
                    row["text"] = script[:6000]
                    row["print"] = print_
                    if aired:
                        row["uses"] = int(row.get("uses") or 0) + 1
                        row["last"] = int(time.time())
                    _manager_memos_write(rows)
                    return row
        for row in rows:
            if str(row.get("print") or "") == print_:
                if aired:
                    row["uses"] = int(row.get("uses") or 0) + 1
                    row["last"] = int(time.time())
                    _manager_memos_write(rows)
                return row
        entry = {"id": uuid.uuid4().hex[:12], "ts": int(time.time()),
                 "text": script[:6000], "print": print_,
                 "how": str(how)[:40],
                 "uses": 1 if aired else 0,
                 "last": int(time.time()) if aired else 0}
        rows.append(entry)
        _manager_memos_write(rows)
        return entry


def manager_memo_delete(memo_id: str) -> int | None:
    """Remove one memo. None = book unreadable, -1 = no such memo."""
    with _MANAGER_MEMOS_LOCK:
        rows = _manager_memos_read()
        if rows is None:
            return None
        kept = [r for r in rows if str(r.get("id")) != str(memo_id)]
        if len(kept) == len(rows):
            return -1
        _manager_memos_write(kept)
        return len(kept)


def upstairs_context() -> str:
    """What is happening on air RIGHT NOW, in one line.

    The manager complains about whatever is actually going on — that is the
    difference between an intercom and a random insult generator. Every
    source here already exists; none of it is new telemetry."""
    bits: list[str] = []
    now = _RADIO.get("now") or {}
    if now.get("title"):
        bits.append(f"the record playing is {now['title']}"
                    + (f" by {now['artist']}" if now.get("artist") else ""))
    said = [str(c.get("text") or "") for c in (_RADIO.get("chat") or [])
            if c.get("who") in ("dj", "cohost", "third", "caller")
            and c.get("text")][-3:]
    if said:
        bits.append("what they have been saying: "
                    + " / ".join(s[:160] for s in said))
    ad = _RADIO.get("ad_now") or {}
    if ad.get("product") and time.time() - float(ad.get("at") or 0) < 240:
        bits.append(f"they are in the middle of selling {ad['product']}")
    try:
        heat = booth_hot()
        if heat and heat >= 55:
            bits.append(f"the machine under the floor is at {heat:.0f}C and "
                        "the whole building knows it")
    except Exception:
        pass
    stats = _RADIO.get("session_stats") or {}
    if stats.get("calls"):
        bits.append(f"{int(stats['calls'])} calls have been taken tonight")
    return "; ".join(bits)[:600]


async def dj_upstairs_write() -> dict[str, Any]:
    """Write one page from upstairs, steered by the speakbox and by what is
    actually on air."""
    context = upstairs_context()
    gripe = unrepeated(list(UPSTAIRS_GRIPES), "upstairs-gripe")
    seed: dict[str, Any] = {}
    try:
        seed = await speakbox_semantic_seed(context or gripe,
                                            who="manager") or {}
        if not seed.get("text"):
            seed = await speakbox_quote(most=4, cap=420) or {}
    except Exception:
        seed = {}
    prompt = (
        "You are the STATION MANAGER, upstairs, paging the booth over the "
        "intercom. You are not on the air and you do not care that they "
        "are. You speak in ONE voice — no speaker labels, no dialogue, no "
        "stage directions — straight at the two of them, and you do not "
        "wait for an answer.\n\n"
        f"What you are on about this time: {gripe}.\n"
        + (f"What is happening down there right now: {context}.\n"
           if context else "")
        + (f"Work THIS material in — bend it into your own grievance, do "
           f"not quote it as a passage: \"{str(seed.get('text'))[:420]}\"\n"
           if seed.get("text") else "")
        + "\nBe specific, petty, and completely certain you are right. "
        "Reference the actual thing happening downstairs. Escalate to some "
        "threat that is out of all proportion — equipment being removed, "
        "somebody being replaced, a policy nobody has heard of. Four to "
        "seven sentences. No markdown, no emoji, no lists."
        # #1157: ...and the STORYLINE. Upstairs is in the same town as
        # everybody else: while a plot owns the air his grievance is
        # about it, or lands in the middle of it. He writes his own
        # prompt, so the host layer never reached him.
        + plotline_line_clause(320)
        # #1027: the manager's MEMO road is tinted and his own voice was
        # not - the same man talking two different ways depending on
        # which road wrote him. Upstairs has fallen into it like the rest
        # of the town.
        + crystal_tint_note())
    try:
        text = spoken_text(await ask_model(prompt, limit=700))
    except Exception:
        text = ""
    if not text:
        return {}
    # #1038: banked as a memo and read out later, so it can be built
    # sentence by sentence.
    text = await crystal_line(text, "the manager's own voice", 5)
    row = upstairs_save(text, gripe, context)
    if seed:
        speakbox_remember(seed)
    return row


async def dj_upstairs_render(row: dict[str, Any]) -> dict[str, Any] | None:
    """The manager's actual voice: one of the station's own cloned voices
    with a vocoder over it and the tannoy colour on top, kept as a durable
    mp3 so the page can be replayed and downloaded."""
    text = str(row.get("text") or "")
    if not text:
        return None
    voices = await session_voices()
    names = [c for c in sorted(VOCODER_CHARACTERS)
             if c not in ("plain", "autotune", "choir")]
    character = str(row.get("vocode") or "") or (
        unrepeated(names, "upstairs-vocode") if names else "megaphone")
    try:
        voice = caller_voice_for(
            "the manager upstairs",
            {voices.get("dj", ""), voices.get("cohost", "")},
            await voice_allowlist(),
            clones=caller_clone_pool()) or ""
    except Exception:
        voice = ""
    engine = voice_engine_for(voice)
    if engine in ("xtts", "f5") and not await clone_engine_ready(engine):
        engine, voice = await voicepolicy_preempt(engine, voice, "manager")  # #1021
    try:
        clip = await voice_generate(
            text, voice, engine,
            fx={"vocode": character,
                "pitch": VOCODER_DEFAULT_PITCH.get(character, -2),
                "strip": "am_radio"})
    except Exception:
        clip = None
    if not clip:
        return None
    key = clip["path"].rsplit("/", 1)[-1].split("?")[0]
    try:
        wav = (VOICE_MEDIA_DIR / key).read_bytes()
    except OSError:
        return None
    name = await asyncio.to_thread(_upstairs_audio_write, wav, row["id"])
    if not name:
        return None
    upstairs_update(row["id"], audio=name, voice=voice, vocode=character)
    return {**row, "audio": name, "voice": voice, "vocode": character}


def _upstairs_audio_write(wav_bytes: bytes, page_id: str) -> str | None:
    """The page kept as a durable mp3 — /media is pruned, and the operator
    asked to be able to download these."""
    try:
        import subprocess

        import imageio_ffmpeg
        UPSTAIRS_AUDIO_DIR.mkdir(parents=True, exist_ok=True)
        name = f"{page_id}.mp3"
        exe = imageio_ffmpeg.get_ffmpeg_exe()
        subprocess.run(
            [exe, "-nostdin", "-hide_banner", "-loglevel", "error", "-y",
             "-f", "wav", "-i", "pipe:0",
             "-codec:a", "libmp3lame", "-b:a", "128k",
             str(UPSTAIRS_AUDIO_DIR / name)],
            input=wav_bytes, capture_output=True, timeout=120)
        return name if (UPSTAIRS_AUDIO_DIR / name).is_file() else None
    except Exception:
        return None


async def dj_upstairs_page(row: dict[str, Any] | None = None) -> bool:
    """The whole beat: the pair notice the intercom, it PLAYS, they deal
    with it."""
    made = row or await dj_upstairs_write()
    if not made:
        return False
    if not made.get("audio"):
        made = await dj_upstairs_render(made) or {}
    name = str(made.get("audio") or "")
    if not name or not (UPSTAIRS_AUDIO_DIR / name).is_file():
        return False
    path, sig = f"/upstairs-audio/{name}", media_sign(name)
    label = "📟 a page from upstairs"
    # (a) the pair hear the intercom light up and say so — through banter so
    # the near-duplicate drop in dj_speak cannot eat a fixed phrase.
    try:
        await dj_banter(_RADIO.get("now"), lines=2, angle=(
            "The INTERCOM from upstairs has just lit up in the booth. One of "
            "you notices it out loud — 'hold on, that is upstairs', 'the "
            "manager is paging us again', 'oh, here we go' — and the other "
            "reacts to being paged, briefly. TWO lines, no more: the message "
            "itself is about to play and you must not talk over it."))
    except Exception:
        pass
    # (b) it is a noise the desk made, so it belongs in the booth list.
    _desk_sound(label, _clip_seconds(path) or 0.0)
    _RADIO["chat"].append({
        "ts": int(time.time()), "who": "board", "kind": "upstairs",
        "name": "upstairs", "text": str(made.get("text") or ""),
        "gripe": str(made.get("gripe") or ""),
        "page_id": str(made.get("id") or ""),
        "page_audio": name, "page_sig": sig,
    })
    del _RADIO["chat"][:-240]
    # (c) PLAY IT — the point of the whole request is that you hear him.
    to = _RADIO.get("voice_to") or "box"
    if to in ("box", "both"):
        await _play_on_box(path, sig)
    if to in ("here", "both") or not box_talk_ok():
        page_feed_append({              # #1147: honest broadcast stamp
            "url": f"{path}?t={sig}", "text": label,
            "voice": str(made.get("voice") or "")})
    _episode_stage(f"{path}?t={sig}", label)
    upstairs_update(str(made.get("id") or ""),
                    uses=int(made.get("uses") or 0) + 1,
                    last=int(time.time()))
    pipeline_log("air", "a page from upstairs went out — "
                        f"{made.get('vocode') or 'vocoded'} (#749)")
    # (d) and they have to process it, on air.
    try:
        await dj_banter(_RADIO.get("now"), lines=4, angle=(
            "You have both just been made to listen to a page from the "
            "MANAGER UPSTAIRS over the studio intercom. What he said, word "
            f"for word, was: \"{str(made.get('text') or '')[:900]}\" "
            "Deal with it, live, in front of everybody: one of you takes it "
            "personally and the other one finds it funny, or you both go "
            "quiet and then start arguing about which of you he meant. Do "
            "NOT repeat his message back — react to it. He cannot hear you, "
            "which does not stop either of you answering him."))
    except Exception:
        pass
    return True


async def upstairs_clock() -> None:
    """Roughly N pages an hour, on their own clock, jittered — and quite
    deliberately not checking whether a call is in progress, because "it can
    land mid-phone-call" is the ask."""
    first = True
    while _RADIO.get("on"):
        rate = float(dj_settings().get("upstairs_per_hour") or 0)
        if rate <= 0:
            await asyncio.sleep(300)
            continue
        gap = max(120.0, 3600.0 / rate)
        # The first page of a fresh show comes early, so the feature is
        # visible without waiting twenty minutes for it.
        wait = random.uniform(90.0, 200.0) if first else \
            random.uniform(gap * 0.6, gap * 1.4)
        first = False
        await asyncio.sleep(wait)
        if not _RADIO.get("on"):
            return
        if float(dj_settings().get("upstairs_per_hour") or 0) <= 0:
            continue
        # #951: upstairs rings during the memo entry, not over a call.
        if not clock_may_air("manager"):
            continue
        try:
            await dj_upstairs_page()
        except Exception as exc:            # noqa: BLE001
            pipeline_log("drop", f"a page from upstairs died: {exc}"[:200])


# --- The radio cache (#548): finished phone calls kept as compressed mp3 +
# transcript for focused replay, unpruned, in data/radio_cache/calls.
RADIO_CACHE = data_path("radio_cache")

# WHICH record was playing WHEN (#633). The recorder only ever caught talk
# and stings — music is a URL the page or the box streams, so nothing here
# ever heard a note of it. The full mix is rebuilt from this log, which is
# why it has to exist separately: played.json de-dupes for the "recently
# played" list (#203) and therefore cannot say when anything ran.
MUSIC_LOG_PATH = RADIO_CACHE / "music_log.jsonl"
_MUSIC_LOG_LOCK = RLock()

# THE FULL-MIX SHELF (#667). The talk/sfx shelf collects itself as the show
# runs; the full mix — the broadcast as it SOUNDED, records mixed back in and
# ducked — was a button you had to press, which is the one thing that never
# gets pressed at the moment worth keeping. So every sealed episode gets a
# mixed twin rendered behind it and shelved here, and the tab that lists them
# is the same tab as the talk one: a player, an mp3, a transcript, per row.
BROADCASTS_DIR = RADIO_CACHE / "broadcasts"
MIX_LEVELS_PATH = RADIO_CACHE / "mix_levels.json"
BROADCASTS_KEPT = 120
# Only one full mix at a time: every second of the span is decoded and
# re-encoded, and two of them racing would fight over ffmpeg and the disk.
_MIX_GATE: list[Any] = []


def _cache_folder(kind: str) -> Path:
    """Which shelf a kind names. Three of them now (#667)."""
    if kind == "calls":
        return RADIO_CACHE / "calls"
    if kind == "broadcasts":
        return BROADCASTS_DIR
    return RADIO_CACHE / "episodes"


def mix_levels() -> dict[str, float]:
    """The levels the collected mixes are rendered at (#667) — the same
    three the browser's own mixer offers, kept server-side because the
    collector runs whether or not a browser is open."""
    # #701: music at 30% of the dialogue by default — it was 100% of
    # whatever the record was mastered at, which is overbearing by
    # construction.
    out = {"music": 30.0, "duck": 70.0, "voice": 100.0}
    try:
        saved = json.loads(MIX_LEVELS_PATH.read_text())
        for key in out:
            if isinstance(saved.get(key), (int, float)):
                out[key] = float(saved[key])
    except Exception:
        pass
    out["music"] = max(0.0, min(200.0, out["music"]))
    out["duck"] = max(0.0, min(90.0, out["duck"]))
    out["voice"] = max(25.0, min(200.0, out["voice"]))
    return out


def mix_levels_save(music: float, duck: float, voice: float) -> dict[str,
                                                                    float]:
    levels = {"music": max(0.0, min(200.0, float(music))),
              "duck": max(0.0, min(90.0, float(duck))),
              "voice": max(25.0, min(200.0, float(voice)))}
    try:
        RADIO_CACHE.mkdir(parents=True, exist_ok=True)
        MIX_LEVELS_PATH.write_text(json.dumps(levels))
    except OSError:
        pass
    return levels


def station_slug() -> str:
    """The station's name, fit for a filename (#648)."""
    try:
        name = str(dj_settings().get("station_name") or "").strip()
    except Exception:
        name = ""
    slug = re.sub(r"[^A-Za-z0-9]+", "-", name).strip("-").lower()
    return slug[:48] or "episode"


def _music_log_append(track: dict[str, Any] | None,
                      stop: bool = False) -> None:
    """One line per record going on air. Best effort, always."""
    try:
        with _MUSIC_LOG_LOCK:
            RADIO_CACHE.mkdir(parents=True, exist_ok=True)
            if stop:
                row: dict[str, Any] = {"at": time.time(), "stop": True}
            else:
                if not track:
                    return
                row = {
                    "at": time.time(),
                    "id": str(track.get("id") or ""),
                    "title": str(track.get("title") or "")[:120],
                    "artist": str(track.get("artist") or "")[:80],
                    "seconds": float(track.get("seconds") or 0),
                    "path": str(track.get("path") or ""),
                    "tape": bool(track.get("tape")),
                    "to": _RADIO.get("music_to") or "here",
                }
            with MUSIC_LOG_PATH.open("a") as handle:
                handle.write(json.dumps(row) + "\n")
            if MUSIC_LOG_PATH.stat().st_size > 1_000_000:
                keep = MUSIC_LOG_PATH.read_text().splitlines()[-4000:]
                MUSIC_LOG_PATH.write_text("\n".join(keep) + "\n")
    except Exception:
        pass


def _music_log_rows(lo: float, hi: float) -> list[dict[str, Any]]:
    """Records overlapping the window, each with a real end: a track that
    was skipped ends when the next one started, not when its tags say."""
    try:
        lines = MUSIC_LOG_PATH.read_text().splitlines()
    except Exception:
        return []
    rows: list[dict[str, Any]] = []
    for line in lines:
        try:
            rows.append(json.loads(line))
        except Exception:
            continue
    rows.sort(key=lambda r: float(r.get("at") or 0))
    out: list[dict[str, Any]] = []
    for at, row in enumerate(rows):
        if row.get("stop") or not row.get("id"):
            continue
        began = float(row.get("at") or 0)
        ends = began + float(row.get("seconds") or 0)
        for later in rows[at + 1:]:
            when = float(later.get("at") or 0)
            if when > began:
                ends = min(ends, when)      # cut short by the next record
                break
        if ends > lo and began < hi and (row.get("to") or "here") != "off":
            out.append({**row, "began": began, "ends": ends})
    return out


def _cache_call_recording(wav_bytes: bytes,
                          transcript: list[Any],
                          name: str,
                          call_id: str = "") -> None:
    """Keep a finished call as an mp3 + transcript for focused replay (#548).
    Best effort — a failed cache never affects the on-air call."""
    try:
        import subprocess

        calls = RADIO_CACHE / "calls"
        calls.mkdir(parents=True, exist_ok=True)
        stamp = time.strftime("%Y-%m-%d_%H%M%S")
        safe = re.sub(r"[^\w-]+", "_", name or "caller")[:40]
        unique = re.sub(r"[^a-zA-Z0-9]+", "", str(call_id or ""))[:12] \
            or uuid.uuid4().hex[:8]
        base = calls / f"{stamp}_{safe}_{unique}"
        (Path(str(base) + ".md")).write_text(
            f"# Phone call — {name or 'a caller'} — {stamp}\n\n"
            + f"Call ID: `{unique}`\n\n"
            + "\n\n".join(
                f"**{str(row.get('name') or row.get('who') or 'Caller')}:** "
                f"{str(row.get('text') or '')}"
                if isinstance(row, dict) else
                f"**{str(row[0])}:** {str(row[1])}"
                for row in transcript
                if ((isinstance(row, dict) and row.get('text'))
                    or (isinstance(row, (list, tuple)) and len(row) >= 2))),
            encoding="utf-8")
        # Transcript durability does not depend on the encoder. If ffmpeg is
        # temporarily unavailable the database still keeps the conversation;
        # audio failure remains best-effort as promised by this function.
        try:
            import imageio_ffmpeg
            exe = imageio_ffmpeg.get_ffmpeg_exe()
            subprocess.run(
                [exe, "-nostdin", "-hide_banner", "-loglevel", "error", "-y",
                 "-f", "wav", "-i", "pipe:0", "-codec:a", "libmp3lame",
                 "-b:a", "96k", str(base) + ".mp3"], input=wav_bytes,
                capture_output=True, timeout=120)
        except Exception:
            pass
        # Bounded: keep the newest ~200 calls.
        keep = sorted(calls.glob("*.mp3"), key=lambda p: p.stat().st_mtime)
        for old in keep[:-5000]:
            for ext in (".mp3", ".md"):
                try:
                    old.with_suffix(ext).unlink()
                except OSError:
                    pass
    except Exception:
        pass


def _cache_call_recording_parts(parts: list[str], transcript: list[Any],
                                name: str, call_id: str = "") -> None:
    """Archive one complete call assembled from streamed playout bursts."""
    try:
        files = [str(p) for p in parts if p and Path(str(p)).is_file()]
        if not files:
            return
        if len(files) == 1:
            blob = Path(files[0]).read_bytes()
        else:
            blob = _call_concat_blocking(
                files, False, [0.02 for _ in files]) or b""
        if blob:
            _cache_call_recording(blob, transcript, name, call_id)
    except Exception:
        pass


# --- The rolling episode recorder (#548): every aired clip is staged as a
# cheap hardlink (survives the /media prune) into the current episode; a clock
# finalizes a ~15-minute compressed mp3 + transcript for offline replay.
_EPISODE_STAGE = RADIO_CACHE / "_staging"


def _episode_stage(media_path: str, text: str,
                   src_path: str | Path | None = None) -> None:
    """Stage one aired clip into the current episode (#548). Best effort — a
    failed stage never touches the show. `src_path` overrides where the audio
    lives for things served from outside /media — stings live in the SFX store,
    not VOICE_MEDIA_DIR, and #560 wants the episode to catch EVERYTHING aired."""
    try:
        key = media_path.rsplit("/", 1)[-1].split("?")[0]
        src = Path(src_path) if src_path else VOICE_MEDIA_DIR / key
        if not src.is_file():
            return
        ep = _RADIO.setdefault("episode", {"started": time.time(), "items": []})
        if not ep.get("started"):
            ep["started"] = time.time()
        _EPISODE_STAGE.mkdir(parents=True, exist_ok=True)
        dst = _EPISODE_STAGE / f"{len(ep['items']):05d}_{key}"
        try:
            os.link(str(src), str(dst))       # hardlink: no data copy
        except OSError:
            import shutil
            shutil.copyfile(str(src), str(dst))
        # Aired-at, not written-at: a sting hardlinks a sample file whose
        # mtime is the day it was made, and the tail cut wants air time (#630).
        ep["items"].append({"file": str(dst), "text": text[:200],
                            "t": time.time()})
    except Exception:
        pass


def _episode_finalize() -> dict[str, Any] | None:
    """Concat the staged clips into ONE compressed mp3 episode + a transcript,
    then clear the staging and start a fresh episode (#548).

    Returns what it sealed — the base path and the wall-clock window it
    covers — so the full-mix collector can render the mixed twin of exactly
    that stretch (#667). None means nothing was sealed."""
    ep = _RADIO.get("episode") or {}
    items = [it for it in (ep.get("items") or [])
             if Path(it.get("file", "")).is_file()]
    _RADIO["episode"] = {"started": time.time(), "items": []}
    if len(items) < 2:
        for it in (ep.get("items") or []):
            try:
                Path(it["file"]).unlink()
            except OSError:
                pass
        return None
    sealed: dict[str, Any] | None = None
    try:
        import subprocess

        import imageio_ffmpeg
        eps = RADIO_CACHE / "episodes"
        eps.mkdir(parents=True, exist_ok=True)
        stamp = time.strftime("%Y-%m-%d_%H%M%S")
        # Named after the station it came off (#648): rename the station and
        # the next cut carries the new name, so a shelf of episodes reads as
        # the eras it actually is.
        base = eps / f"{station_slug()}_{stamp}"
        files = [it["file"] for it in items]
        exe = imageio_ffmpeg.get_ffmpeg_exe()
        ins: list[str] = []
        for f in files:
            ins += ["-i", f]
        pre = "".join(
            f"[{i}:a]aresample=24000,aformat=sample_fmts=s16:"
            f"channel_layouts=mono[a{i}];" for i in range(len(files)))
        chain = "".join(f"[a{i}]" for i in range(len(files)))
        graph = f"{pre}{chain}concat=n={len(files)}:v=0:a=1[out]"
        subprocess.run(
            [exe, "-nostdin", "-hide_banner", "-loglevel", "error", "-y",
             *ins, "-filter_complex", graph, "-map", "[out]",
             "-codec:a", "libmp3lame", "-b:a", "96k", str(base) + ".mp3"],
            capture_output=True, timeout=420)
        # REAL per-line timestamps: each staged clip's duration is knowable,
        # so every transcript entry gets its true offset into the sealed mp3
        # — the transcript reader seeks EXACTLY there instead of guessing by
        # line position.
        offset = 0.0
        stamped: list[str] = []
        # The same walk also writes a machine-readable sidecar (#633): where
        # each line sits inside this mp3 AND the wall-clock moment it aired,
        # which is what lets the full mix line talk up against the records.
        marks: list[dict[str, Any]] = []
        for it in items:
            _m, _s = divmod(int(offset), 60)
            _h, _m = divmod(_m, 60)
            tag = f"[{_h}:{_m:02d}:{_s:02d}]" if _h else f"[{_m}:{_s:02d}]"
            stamped.append(f"{tag} {it['text']}")
            began = offset
            try:
                import mutagen
                _info = mutagen.File(str(it["file"]))
                offset += float(getattr(_info.info, "length", 0) or 0)
            except Exception:
                offset += 4.0           # a typical line keeps stamps sane
            marks.append({"off": round(began, 2),
                          "dur": round(offset - began, 2),
                          "t": float(it.get("t") or 0),
                          "text": it["text"][:200]})
        Path(str(base) + ".md").write_text(
            f"# Pine Box FM — episode {stamp}\n\n"
            + "\n\n".join(stamped), encoding="utf-8")
        try:
            Path(str(base) + ".json").write_text(json.dumps(marks))
        except Exception:
            pass
        keep = sorted(eps.glob("*.mp3"), key=lambda p: p.stat().st_mtime)
        for old in keep[:-120]:
            for ext in (".mp3", ".md", ".json"):
                try:
                    old.with_suffix(ext).unlink()
                except OSError:
                    pass
        # The window this episode covers, in wall-clock: from the first clip
        # aired (or the moment the episode opened, whichever is earlier) to
        # the end of the last one. That is what the full mix is cut to.
        firsts = [float(it.get("t") or 0) for it in items if it.get("t")]
        lo = min([float(ep.get("started") or 0) or min(firsts)] + firsts) \
            if firsts else float(ep.get("started") or time.time())
        sealed = {"base": str(base), "stem": base.name,
                  "lo": lo, "hi": time.time()}
    except Exception:
        pass
    finally:
        for it in items:
            try:
                Path(it["file"]).unlink()      # drop the staging hardlinks
            except OSError:
                pass
    return sealed


def _broadcast_collect(sealed: dict[str, Any]) -> Path | None:
    """Render the mixed twin of a just-sealed episode and shelve it (#667).

    The talk shelf collects itself; the full mix used to be a button. A
    broadcast you have to remember to render is a broadcast you do not
    have, and this is the one people replay — the records ARE the show.
    So every seal gets its mix rendered behind it at the saved levels and
    filed beside the transcript it came with. Best effort throughout: a
    failed mix must never cost the episode it was made from."""
    try:
        base = Path(str(sealed.get("base") or ""))
        lo = float(sealed.get("lo") or 0)
        hi = float(sealed.get("hi") or 0)
        if not base.name or hi - lo < 20:
            return None
        levels = mix_levels()
        mixed = _broadcast_mix(
            lo, hi,
            max(0.0, min(2.0, levels["music"] / 100)),
            max(0.0, min(0.9, levels["duck"] / 100)),
            max(0.25, min(2.0, levels["voice"] / 100)),
            tag="_collect")
        if not mixed:
            return None
        BROADCASTS_DIR.mkdir(parents=True, exist_ok=True)
        out = BROADCASTS_DIR / f"{base.name}_fullmix.mp3"
        mixed.replace(out)
        # The transcript comes across too, so a mixed row reads the same as
        # a talk row — same player, same ⬇, same 📄.
        src_md = Path(str(base) + ".md")
        if src_md.is_file():
            try:
                out.with_suffix(".md").write_text(
                    src_md.read_text(encoding="utf-8", errors="replace"),
                    encoding="utf-8")
            except OSError:
                pass
        # #701: the window it covers, kept beside it, so the set can be
        # rebuilt at different levels later without guessing which stretch
        # of the night it was.
        try:
            out.with_suffix(".json").write_text(json.dumps(
                {"lo": lo, "hi": hi, "levels": levels}))
        except OSError:
            pass
        keep = sorted(BROADCASTS_DIR.glob("*.mp3"),
                      key=lambda p: p.stat().st_mtime)
        for old in keep[:-BROADCASTS_KEPT]:
            for ext in (".mp3", ".md", ".json"):
                try:
                    old.with_suffix(ext).unlink()
                except OSError:
                    pass
        pipeline_log("air", f"full mix collected — {out.name} "
                            f"({int(hi - lo)}s, records mixed back in) (#667)")
        return out
    except Exception:
        return None


async def broadcast_collect(sealed: dict[str, Any] | None) -> None:
    """One full mix at a time, off the show's own thread (#667)."""
    if not sealed or _MIX_GATE:
        return
    _MIX_GATE.append(1)
    try:
        await asyncio.to_thread(_broadcast_collect, sealed)
    except Exception:
        pass
    finally:
        _MIX_GATE.clear()


async def episode_clock() -> None:
    """Finalize the running episode every episode_minutes (#548), and cap it
    by clip count so a very chatty stretch does not grow unbounded."""
    while _RADIO.get("on"):
        await asyncio.sleep(60)
        try:
            mins = int(dj_settings().get("episode_minutes") or 0)
        except Exception:
            mins = 15
        if not mins:
            continue
        ep = _RADIO.get("episode") or {}
        items = ep.get("items") or []
        elapsed = time.time() - float(ep.get("started") or time.time())
        if items and (elapsed >= mins * 60 or len(items) >= 220):
            sealed = await asyncio.to_thread(_episode_finalize)
            # #667: the mixed twin, collected as the show runs rather than
            # rendered on demand hours later.
            asyncio.create_task(broadcast_collect(sealed))


def _music_bed_track() -> dict[str, Any] | None:
    """A song to swell under an ad (#463). Rides the songs HE has favourited
    (thumbs-up) most of the time, so the ads are bedded on his own music
    (#526); falls back to any long track when nothing is loved yet."""
    try:
        pool = [t for t in music_index()
                if t.get("path") and not t.get("tape")
                and float(t.get("seconds") or 0) > 40]
    except Exception:
        pool = []
    if not pool:
        return None
    try:
        loved = loved_ids()
        faves = [t for t in pool if str(t.get("id")) in loved]
    except Exception:
        faves = []
    # #683: of the favourites, the ones whose thumbs-up remembers WHERE it
    # was pressed come first — those are the beds that can open on the hook
    # instead of twenty seconds in from the top.
    try:
        marked = [t for t in faves
                  if loved_moment(str(t.get("id") or "")) is not None]
    except Exception:
        marked = []
    if marked and random.random() < 0.85:
        return random.choice(marked)
    if faves and random.random() < 0.8:
        return random.choice(faves)
    return random.choice(pool)


def _ad_bed_share() -> float:
    """How loud the music sits under an ad read (#700), as a share of the
    voice. A flat 0.85 of the record's own master was the fault: a hot master
    came out over the top of the read. Settable, because "how loud is the
    bed" is a taste."""
    try:
        return max(2, min(100, int(dj_settings().get("ad_bed_pct", 30)))) / 100
    except Exception:
        return 0.30


def _music_ad_mix_blocking(voice_path: Path, music_path: str,
                           voice_seconds: float, start: float,
                           sfx_path: str | None = None,
                           bed_pct: float | None = None,
                           bed_len: float | None = None) -> bytes | None:
    """Mix an ad voice over a bed of real music (#463): the music swells in
    alone, ducks under the read (sidechained to the voice) and swells back
    out — one clip, 24k mono. When `sfx_path` is given, a sound effect is
    punched into the opening swell so the produced spot has a sting mixed IN,
    not announced after (#618). ffmpeg does the whole graph so nothing has to
    match formats by hand. Returns None on any failure so the ad still airs
    dry."""
    import subprocess

    import imageio_ffmpeg
    exe = imageio_ffmpeg.get_ffmpeg_exe()
    lead, tail = 2.3, 3.0
    total = lead + max(1.0, voice_seconds) + tail
    lead_ms = int(lead * 1000)
    # #700: the bed is NORMALIZED and then held at a fixed share of the read.
    #
    # It used to be a flat volume=0.85 on whatever the record's own master
    # happened to be — so a loud master came out louder than the voice and
    # the ad blasted. Two different faults in one number: no reference level,
    # and a share nobody could set. loudnorm gives both tracks a known
    # loudness, and the bed then sits at ad_bed_pct of the read (30% by
    # default) BEFORE the sidechain ducks it further under the words.
    bed_share = max(0.02, min(1.0,
                              (bed_pct / 100.0) if bed_pct is not None
                              else _ad_bed_share()))
    graph = (
        f"[1:a]atrim=0:{total:.2f},asetpts=PTS-STARTPTS,"
        # #734: a hand-set cue OUT can make the bed shorter than the read.
        # amix takes its length from the first input, which is the ducked
        # BED — so without this the ad itself was cut off at the cue point.
        # Pad the bed out to the full length and the read always finishes.
        f"apad=whole_dur={total:.2f},"
        # Same reference as the read (below), so "30%" is 30% OF THE
        # VOICE and not of some other yardstick.
        "loudnorm=I=-16:LRA=11:TP=-2.0,"
        f"afade=t=in:st=0:d={lead:.2f},"
        f"afade=t=out:st={total - tail:.2f}:d={tail:.2f},"
        f"volume={bed_share:.3f}[bed];"
        # THE BUG THAT KEPT EVERY AD DRY: a filter_complex pad may be
        # consumed exactly ONCE, and [vox] was fed to BOTH the sidechain and
        # the final amix — ffmpeg rejected the whole graph, the mixer
        # returned nothing, and the ad silently fell back to the dry read.
        # Split the voice first.
        f"[0:a]loudnorm=I=-16:LRA=11:TP=-1.5,"
        f"adelay={lead_ms}|{lead_ms},apad=pad_dur={tail:.2f},"
        "asplit=2[voxduck][voxmix];"
        "[bed][voxduck]sidechaincompress=threshold=0.03:ratio=12:attack=15:"
        "release=350[duck];"
    )
    # #734: the cue window the studio set on the bed, if it set one. Never
    # longer than the spot needs — apad above covers a window that is shorter.
    grab = total + 2
    if bed_len and bed_len > 0.5:
        grab = min(grab, float(bed_len))
    ins = ["-i", str(voice_path),
           "-ss", f"{max(0.0, start):.2f}", "-t", f"{grab:.2f}",
           "-i", music_path]
    if sfx_path:
        # The sting rides the intro swell (input 2), a touch under the bed.
        ins += ["-i", sfx_path]
        graph += (
            "[2:a]aresample=24000,aformat=sample_fmts=s16:channel_layouts=mono,"
            "atrim=0:2.2,loudnorm=I=-20:LRA=11:TP=-2.0,"
            f"volume={bed_share * 0.9:.3f}[stg];"
            "[duck][voxmix]amix=inputs=2:duration=first:normalize=0[body];"
            "[body][stg]amix=inputs=2:duration=first:normalize=0,"
            "alimiter=limit=0.95[out]"
        )
    else:
        graph += ("[duck][voxmix]amix=inputs=2:duration=first:normalize=0,"
                  "alimiter=limit=0.95[out]")
    try:
        out = subprocess.run(
            [exe, "-nostdin", "-hide_banner", "-loglevel", "error",
             *ins,
             "-filter_complex", graph, "-map", "[out]",
             "-ac", "1", "-ar", "24000", "-sample_fmt", "s16",
             "-f", "wav", "pipe:1"],
            capture_output=True, timeout=90)
        blob = out.stdout
    except Exception:
        return None
    return blob if len(blob) > 2000 else None


async def dj_music_ad(product: str, remember: bool = True) -> dict[str, Any]:
    """A special ad (#463): the DJ pitches the product over a bed of the
    station's own music — swelling in, ducking for the read, swelling out.
    Renders the voice, mixes it with a random track, plays the one mixed
    clip. Any failure falls back to a plain read so an ad always airs."""
    ad_now_set(product)                                   # #900
    _ad_at = time.time()                                          # #892
    # #916b/c: THE BEDDED SPOT WAS WRITTEN OFF NOTHING AND REMEMBERED BY
    # NOBODY. dj_line draws a speakbox swath only when it is handed a
    # `seed` dict; this road passed none, so the spot that sounds most
    # like a real commercial was the one with the least material behind
    # it. ad_write_fresh() draws the swath outright and holds the result
    # against every advert already on the books; a refusal falls straight
    # back to the plain write this road has always had.
    _mk: dict[str, Any] = {}
    try:
        _mk = await ad_write_fresh(product, tries=2)
    except Exception:  # noqa: BLE001
        _mk = {}
    line = spoken_text(str(_mk.get("text") or "")) or spoken_text(
        await dj_line("ad", _RADIO.get("now"), extra=product))
    if not line:
        return {"ad": "", "product": product, "id": ""}
    forced = (await session_voices()).get("dj") or None
    engine = voice_engine_for(forced or "")
    # #746: BOTH cloning engines. This probed XTTS only, so an
    # F5 voice with :8772 down raised out of voice_generate
    # instead of falling back to Piper like everything else.
    if engine in ("xtts", "f5") \
            and not await clone_engine_ready(engine):
        engine, forced = await voicepolicy_preempt(engine, forced or "", "ad")  # #1021
    # A produced spot is VOCODED (#618): the read gets the classic half-dry,
    # phase-locked autotune sheen so the voice sits on the bed like a real
    # radio ad. Stays intelligible where a full robot would not.
    try:
        clip = await voice_generate(line, forced or "", engine,
                                    fx={"vocode": "autotune"})
    except Exception:
        clip = None
    if not clip:
        return await dj_ad(product, remember=remember)  # dry fallback
    play = clip
    track = _music_bed_track()
    if track:
        secs = float(track.get("seconds") or 0)
        # #683: bed the ad on the MOMENT he liked, not a random 20 seconds
        # in. The thumbs-up carries where in the record it was pressed, and
        # that spot is the hook — start the swell a few seconds ahead of it
        # so the read lands on the part he reached for the button for.
        loved = loved_moment(str(track.get("id") or ""))
        if loved is not None:
            start = max(0.0, loved - 4.0)
            if secs > 10:
                start = min(start, max(0.0, secs - 12.0))
            pipeline_log(
                "air", "ad bedded on the moment he liked — "
                f"{int(loved // 60)}:{int(loved % 60):02d} into "
                f"{track.get('title') or 'a track'} (#683)")
        else:
            start = random.uniform(20.0, max(21.0, min(70.0, secs - 25.0))) \
                if secs > 50 else 15.0
        voice_key = clip["path"].rsplit("/", 1)[-1]
        # A sound effect punched into the opening swell (#618) — mixed IN, not
        # announced after. Best effort: no sample to hand → the ad airs without.
        sfx = await asyncio.to_thread(_sfx_any)
        mixed = await asyncio.to_thread(
            _music_ad_mix_blocking, VOICE_MEDIA_DIR / voice_key,
            str(track["path"]), _clip_seconds(clip["path"]) or 8.0, start,
            str(sfx) if sfx else None)
        if mixed:
            play = _store_media(mixed, "wav")
            pipeline_log("air", "music-bed ad mixed — voice over "
                                f"{track.get('title') or 'a track'} (#463)")
    # An ad is a DJ-voice segment, so it obeys the DJ VOICE routing (#524):
    # with the voice set to the page it must not come out of the box, and
    # vice-versa. Off mutes it.
    ad_to = _RADIO.get("voice_to") or "box"
    if ad_to in ("box", "both"):
        await _play_on_box(play["path"], play["sig"])
    if page_carries_live(ad_to, ad_to in ("box", "both")):     # #1118
        page_feed_append({              # #1147: honest broadcast stamp
            "url": f"{play['path']}?t={play['sig']}",
            "text": line, "engine": engine, "voice": forced or ""})
    entry = ad_save(product, line, kind="music") if remember else None
    # #892: THE ROAD THAT LEFT NO TRACE. A music-bedded spot never goes
    # through dj_speak, so nothing ever wrote it a booth row — and the
    # ad_line_mark() this road used to call exists to STAMP the row
    # dj_speak leaves behind, so here it walked back over lines that were
    # not ads and marked nothing at all. The spot swelled up over the
    # record, sold something, was kept on the shelf, and the booth had
    # no sign at all that it had
    # happened; the airings ledger never saw it either. It files its own
    # listing now, the same shape as every other ad, carrying the mixed
    # clip so the tile can play it and keep it.
    ad_booth_row(line, product,
                 ad_id=str((entry or {}).get("id") or ""),
                 media=str((play or {}).get("path") or ""),
                 sig=str((play or {}).get("sig") or ""),
                 voice=forced or "", air_at=_ad_at)
    try:
        ad_aired(entry or {"product": product, "text": line},
                 _RADIO.get("voice_to") or "box")                  # #743
    except Exception:  # noqa: BLE001
        pass
    # #916b: it went out, so the books get it — said_lines for the prompt's
    # do-not-reuse list, line_prints and phrase_prints for the gates. This
    # road never went through dj_speak, so none of that had ever happened
    # for a bedded spot and the next one had nothing to avoid.
    ad_remember(line)
    # ...and the document it was built from is credited now that it has
    # actually aired, the same way a banter round credits its swath.
    try:
        if (_mk.get("seed") or {}).get("text"):
            speakbox_remember(_mk["seed"])
    except Exception:  # noqa: BLE001
        pass
    return {"ad": line, "product": product, "id": (entry or {}).get("id", "")}


async def dj_ad_break(zero_work_only: bool = False, on_handoff: Any = None) -> str:
    """The between-tracks ad. Reuses a stored read most of the time so the
    station repeats itself the way real ones do; otherwise writes a new one
    about one of your paintings."""
    if not zero_work_only:
        _RADIO["last_ad"] = time.time()    # live roads still share this clock
    dj = dj_settings()
    stored = ad_pick()

    async def handoff_produced(entry: dict[str, Any], shelf_row: Any = None) -> str:
        committed = False

        def commit() -> None:
            nonlocal committed
            if committed:
                return
            committed = True
            _RADIO["last_ad"] = time.time()
            if callable(on_handoff):
                on_handoff()
            if shelf_row is not None:
                _SHELF["ad"] = [r for r in (_SHELF.get("ad") or [])
                                if r is not shelf_row]
            try:
                ad_update(str(entry.get("id") or ""),
                          uses=int(entry.get("uses") or 0) + 1)
            except Exception:  # noqa: BLE001
                pass

        try:
            if not await _air_produced_ad(entry, on_handoff=commit):
                return ""
            commit()
            return str(entry.get("text") or entry.get("product") or "a produced spot")
        finally:
            # shelf_take removed this row before the player had a verdict.
            # A cancelled/refused handoff must put the same row back.
            if (shelf_row is not None and not committed
                    and not any(r is shelf_row for r in (_SHELF.get("ad") or []))):
                _SHELF.setdefault("ad", []).insert(0, shelf_row)

    # At 100% talk, the scheduler has promised that nothing on this live road
    # waits for writing or TTS.  A produced commercial is already one audio
    # object, so prefer it outright; if that cupboard is empty the caller lets
    # a finished booth round cover instead of commissioning copy on air.
    if zero_work_only:
        try:
            _cupboard = [r for r in ad_list() if r.get("audio")
                         and (PRODUCED_ADS_DIR / str(r["audio"])).is_file()]
            if _cupboard:
                _few = min(int(r.get("uses") or 0) for r in _cupboard)
                _spot = random.choice([r for r in _cupboard
                                       if int(r.get("uses") or 0) == _few])
                said = await handoff_produced(_spot)
                if not said:
                    return ""
                pipeline_log("air", "100% talk took a zero-work produced "
                             f"spot - {len(_cupboard)} on the shelf")
                return said
        except Exception:  # noqa: BLE001
            pass
        return ""

    # #1136: THE PRODUCED CUPBOARD GETS A REAL SHARE OF THE BREAKS. The
    # shelf's prepared dry reads used to be consumed first on every
    # single break, so a book of 131 finished spots - voice, bed, vocode
    # and sting already mixed - aired five times in a day while the
    # station read fresh dry copy over them. Half the breaks now go to
    # the least-used produced spot outright; the dry read keeps its slot
    # on the other half, and it stays on the shelf meanwhile, so nothing
    # prepared is wasted. Costs this break nothing at all: the audio is
    # already cut.
    try:
        if random.random() < AD_PRODUCED_BREAK_SHARE:
            _cupboard = [r for r in ad_list() if r.get("audio")
                         and (PRODUCED_ADS_DIR / str(r["audio"])).is_file()]
            if _cupboard:
                _few = min(int(r.get("uses") or 0) for r in _cupboard)
                _spot = random.choice([r for r in _cupboard
                                       if int(r.get("uses") or 0) == _few])
                said = await handoff_produced(_spot)
                if not said:
                    return ""
                pipeline_log("air", "the break went to the produced "
                             "cupboard - least-used spot first, "
                             f"{len(_cupboard)} on the shelf (#1136)")
                return said
    except Exception:  # noqa: BLE001
        pass                           # the ordinary roads below still run

    # #842: a spot WRITTEN AND READ during an earlier record. The words
    # and the audio both exist already, so this break costs the model and
    # the voice engine nothing at all — which is the whole point of the
    # backlog. An empty shelf falls straight through to the road below.
    try:
        _prep_ad = shelf_take("ad")
    except Exception:  # noqa: BLE001
        _prep_ad = None
    # #916a: a PRODUCED spot off the shelf — finished audio with its bed,
    # its vocode and its sting already mixed in. It is PLAYED, not read:
    # handing its script to dj_ad() would have the host recite a
    # commercial that already exists as a file, which is both a wasted
    # render and the wrong sound. The row carries the id of the entry in
    # the ad book; a spot whose audio has been swept falls through to the
    # ordinary road below.
    if _prep_ad and str(_prep_ad.get("produced") or ""):
        try:
            _made = next((r for r in ad_list()
                          if r.get("id") == str(_prep_ad.get("produced"))),
                         None)
            if _made and _made.get("audio"):
                said = await handoff_produced(_made, shelf_row=_prep_ad)
                if not said:
                    return ""
                pipeline_log("air", "the break took a PRODUCED spot off the "
                             "shelf - it was written, voiced and mixed "
                             "during an earlier record and cost this break "
                             "nothing at all (#916)")
                return said
        except Exception:  # noqa: BLE001
            pass                       # fall through to the read below
    if _prep_ad and str(_prep_ad.get("text") or ""):
        try:
            _prep_said = (await dj_ad(
                str(_prep_ad.get("product") or "our sponsor"),
                script=str(_prep_ad.get("text") or "")))["ad"]
            if _prep_said:
                return _prep_said
        except Exception:  # noqa: BLE001
            pass                       # fall through and write one live

    # The between-tracks ad over a swell of the station's own music (#463).
    # Most of them now (#643): a spot bedded in music is the thing that
    # actually sounds like a commercial break, and the shelf it fills is
    # what lets one or two an hour rerun without repeating themselves.
    music_ad = (_RADIO.get("on") and random.random() < 0.75
                and _music_bed_track() is not None)

    # Rerun less often while the shelf of PRODUCED spots is still thin —
    # a new bedded one is worth more than a fourth airing of a dry read.
    produced = [r for r in ad_list() if r.get("audio")]
    rerun = 0.6 if len(produced) >= 8 else 0.3
    if stored and random.random() < rerun:
        # A produced spot reruns its FINISHED audio verbatim (#618) — the
        # voice, bed, vocode and SFX exactly as they were built.
        if stored.get("audio"):
            return await handoff_produced(stored)
        ad_update(stored["id"], uses=stored.get("uses", 0) + 1)
        # #892: a stored DRY read reruns through dj_speak, which files its
        # own kind="ad" row — but nothing stamped the spot onto it, so the
        # booth listed an ad with no product on it, no play and no keep,
        # and the airings ledger never counted the rerun. Same spot: say
        # which one it was.
        _rerun = await dj_speak("ad", _RADIO.get("now"), line=stored["text"])
        if _rerun:
            try:
                ad_line_mark(str(stored.get("id") or ""),
                             str(stored.get("product") or ""))
                ad_aired(stored, _RADIO.get("voice_to") or "box")
            except Exception:  # noqa: BLE001
                pass
        return _rerun

    product = ""
    # The art-hawking governor: a painting pitch at most every ~15 minutes;
    # otherwise the slot falls through to sponsors / stored reads.
    if dj["gallery_ads"] and art_sell_due():
        # A painting for sale is a painting SEEN (#403): the vision model
        # looks at the actual pixels and the ad sells what is in them.
        try:
            name, desc = await describe_gallery_image()
        except Exception:
            name, desc = "", ""
        if desc:
            art_sell_mark()
            price = random.randint(dj["ad_price_low"], dj["ad_price_high"])
            product = (f'the original painting "{name}" — in it: {desc} '
                       f"— from the Pine Box gallery, {price} dollars, "
                       "first caller takes it")
            # #900: the vision model has just LOOKED at this exact file -
            # hold on to which one it was, so the glass shows the picture
            # the read is describing and not the last one the wall drew.
            ad_item_stamp(image=name, title=name, price=price)
        else:
            product = gallery_product()
            if product:
                art_sell_mark()
    if not product and dj["sponsors"]:
        product = random.choice(dj["sponsors"])
    if not product and stored:
        if stored.get("audio"):
            return await handoff_produced(stored)
        ad_update(stored["id"], uses=stored.get("uses", 0) + 1)
        # #892: a stored DRY read reruns through dj_speak, which files its
        # own kind="ad" row — but nothing stamped the spot onto it, so the
        # booth listed an ad with no product on it, no play and no keep,
        # and the airings ledger never counted the rerun. Same spot: say
        # which one it was.
        _rerun = await dj_speak("ad", _RADIO.get("now"), line=stored["text"])
        if _rerun:
            try:
                ad_line_mark(str(stored.get("id") or ""),
                             str(stored.get("product") or ""))
                ad_aired(stored, _RADIO.get("voice_to") or "box")
            except Exception:  # noqa: BLE001
                pass
        return _rerun
    if not product:
        return ""
    # A produced (music-bed) ad sometimes sells a SERVICE running on the DGX
    # Spark itself — his own systems, pitched excitedly over one of his own
    # favourite songs, then stored and rerun like any other read (#526).
    if music_ad and random.random() < 0.3:
        svc = unrepeated(list(SPONSOR_SERVICES), "sponsor-service")
        facts = await service_sponsor_facts(svc)
        product = (f"{svc.upper()}, one of the live services running on this "
                   "station's own DGX Spark — "
                   + ("; ".join(facts[:2]) if facts
                      else "its live numbers a trade secret tonight")
                   + ", sold like a luxury product")
    if music_ad:
        return (await dj_music_ad(product))["ad"]
    return (await dj_ad(product))["ad"]


def _produced_ad_write(wav_bytes: bytes, ad_id: str) -> str | None:
    """Store a produced ad's finished audio as a durable mp3 (#618) and return
    its filename. Best effort — None means the ad has no reusable clip."""
    try:
        import subprocess

        import imageio_ffmpeg
        PRODUCED_ADS_DIR.mkdir(parents=True, exist_ok=True)
        name = f"{ad_id}.mp3"
        exe = imageio_ffmpeg.get_ffmpeg_exe()
        subprocess.run(
            [exe, "-nostdin", "-hide_banner", "-loglevel", "error", "-y",
             "-f", "wav", "-i", "pipe:0",
             "-codec:a", "libmp3lame", "-b:a", "128k",
             str(PRODUCED_ADS_DIR / name)],
            input=wav_bytes, capture_output=True, timeout=120)
        return name if (PRODUCED_ADS_DIR / name).is_file() else None
    except Exception:
        return None


def _produced_ad_ack(entry: dict[str, Any], where: str) -> None:
    """Credit a finished spot only after an audible transport receipt."""
    ad_aired(entry, where)
    ad_remember(str(entry.get("text") or ""))
    try:
        if entry.get("seed_file") and entry.get("seed_text"):
            speakbox_remember({"file": str(entry.get("seed_file") or ""),
                               "text": str(entry.get("seed_text") or ""),
                               "lines": [str(entry.get("seed_text") or "")],
                               "mind": str(entry.get("seed_mind") or "")})
    except Exception:  # noqa: BLE001
        pass


async def _air_produced_ad(entry: dict[str, Any], on_handoff: Any = None) -> bool:
    """Play a stored produced ad's finished audio on the DJ-VOICE routing
    (#618) — box, page, or both — mirroring to the page when the box is down,
    and staged into the rolling episode. True means accepted for handoff;
    page publication is distinct from the audible receipt that credits it."""
    name = str(entry.get("audio") or "")
    if not name or not (PRODUCED_ADS_DIR / name).is_file():
        return False
    _air_at = time.time()                                         # #892
    path, sig = f"/ads-audio/{name}", media_sign(name)
    label = "📣 " + (entry.get("product") or "a produced spot")
    # #731: what is being SOLD right now, so the booth can light the tile of
    # the spot actually on air. A stored rerun never set this, which is why a
    # produced spot played silently past its own entry in the log.
    old_ad_now = _RADIO.get("ad_now")
    ad_now_set(str(entry.get("product") or ""))            # #900
    this_ad_now = _RADIO.get("ad_now")
    ad_to = _RADIO.get("voice_to") or "box"
    box_down = (time.time() < float(_BOX_DOWN.get("until") or 0)
                or len(_BOX_HOLD) >= 6)
    # #701: a stored spot never went through dj_speak, so it made a noise and
    # left no trace in the booth. It gets its own entry like any other ad.
    # #892: the same listing every other ad road writes now — and with the
    # two fields this hand-rolled copy was missing, an `id` to jump to and
    # the `air_at` the booth sorts on, so a stored spot no longer sorts to
    # the moment its playback FINISHED.
    booth_row = ad_booth_row(
        label, str(entry.get("product") or ""),
        ad_id=str(entry.get("id") or ""), audio=name,
        voice=str(entry.get("voice") or ""),
        aired="held",
        air_at=_air_at)
    # Bind the real booth ID before publishing. A fast page receipt must not
    # credit a temporary label identity and then credit the row again later.
    page_delivery = ""
    box_played = False
    try:
        if page_carries_live(ad_to, ad_to in ("box", "both"), box_down):
            page_delivery = page_feed_append({
                "url": f"{path}?t={sig}", "text": label,
                "voice": entry.get("voice") or "", "speech": True,
                "who": "dj", "kind": "ad", "row_id": str(booth_row.get("id") or ""),
                "remember_text": str(entry.get("text") or label),
                "produced_ad": copy.deepcopy(entry)})
            if page_delivery and callable(on_handoff):
                on_handoff()
        if ad_to in ("box", "both"):
            box_played = bool(await _play_on_box(path, sig))
            if box_played and not page_delivery and callable(on_handoff):
                on_handoff()
    finally:
        if not (page_delivery or box_played) and _RADIO.get("ad_now") is this_ad_now:
            if old_ad_now is None:
                _RADIO.pop("ad_now", None)
            else:
                _RADIO["ad_now"] = old_ad_now
    booth_row["aired"] = "box" if box_played else "published" if page_delivery else "held"
    if page_delivery:
        clip_row = (_PAGE_DELIVERIES.get(page_delivery) or {}).get("clip") or {}
        clip_row["row_id"] = str(booth_row.get("id") or "")
        page_delivery_apply(booth_row, page_delivery)
    if not (box_played or page_delivery):
        return False
    _episode_stage(f"{path}?t={sig}", label)
    # #916b: EVERY road that airs a produced spot funnels through here, so
    # this is the one place worth remembering it from. A produced spot
    # never touched dj_speak, so its words were invisible to
    # said_lines.json, line_prints.json and phrase_prints.json — and
    # therefore to avoid_reruns(), which is what the writer is shown when
    # it sits down to write the next one. `also_said` is on: the read is
    # the pair's own speech even though a file played it.
    if box_played and str(booth_row.get("id") or "") not in _PAGE_ACKED_LINES:
        _produced_ad_ack(entry, "box")
        air_remember(str(entry.get("text") or label), "dj", "ad")
        _PAGE_ACKED_LINES.add(str(booth_row.get("id") or ""))
        talk_said_now("box", str(sig), 1.0)
    # #1136: ...AND THE HOUR CONTRACT IS CREDITED. Every SPOKEN ad rides
    # air_remember -> coord_air_note and counts toward the ad road's
    # hourly target, but a produced spot plays as a file and touched
    # neither - so the more the operator heard the produced cupboard,
    # the worse the scorecard said the ad road was doing, and the
    # closed-loop controller would have "corrected" a road that was
    # delivering. The spot's text is the same estimate every spoken
    # line is credited by.
    # The speakbox document a stacked spot was written off is credited at
    # the moment it airs rather than at the moment it was cut, so a swath
    # sitting unheard on the shelf is not retired early (#916c).
    return True


async def ad_produce(product: str, script: str, voice: str,
                     track_id: str, remember: bool = True,
                     air: bool = True,
                     bed_pct: float | None = None,
                     bed_in: float | None = None,
                     bed_out: float | None = None,
                     ad_id: str = "") -> dict[str, Any]:
    """Build one ad by hand (#618): a chosen (or written) read, in a chosen
    voice, vocoded and mixed over a chosen song with a sound effect punched in,
    saved with its finished audio so the DJs can rerun it between tracks, after
    calls and on commercial breaks. Falls back gracefully at each step so it
    never breaks the show."""
    # #916c: a read WRITTEN HERE is written off the documents. This
    # passed no `seed` to dj_line, and dj_line only draws a swath when it
    # is handed one — so every hand-produced spot with no script was
    # built out of nothing but the product name. The swath rides the
    # `direct` channel (the same one the performance directive uses) so
    # the task itself is untouched, and the do-not-repeat list of adverts
    # already run rides with it.
    _mk: dict[str, Any] = {}
    if not script.strip():
        try:
            _mk = await ad_write_fresh(product, tries=2)
        except Exception:  # noqa: BLE001
            _mk = {}
    line = spoken_text(script) if script.strip() else (
        spoken_text(str(_mk.get("text") or ""))
        or spoken_text(await dj_line("ad", _RADIO.get("now"), extra=product)))
    if not line:
        return {"error": "Nothing to say — give a prompt or a script."}
    v = voice or (await session_voices()).get("dj") or ""
    engine = voice_engine_for(v)
    # #746: BOTH cloning engines. This probed XTTS only, so an
    # F5 voice with :8772 down raised out of voice_generate
    # instead of falling back to Piper like everything else.
    if engine in ("xtts", "f5") \
            and not await clone_engine_ready(engine):
        engine, v = await voicepolicy_preempt(engine, v, "ad")   # #1021
    try:
        clip = await voice_generate(line, v, engine, fx={"vocode": "autotune"})
    except Exception:
        clip = None
    if not clip:
        return {"error": "The voice engine gave nothing back."}
    # The bed: the song the maker chose, else a random one off the shelf.
    # track_id "mx" (or a 35% roll when nothing was chosen) beds the read on
    # a random MX MIXTAPE instead — fading in and out under the read, the
    # permission question left entirely open.
    track: dict[str, Any] | None = None
    if track_id == "mx" or (not track_id and random.random() < 0.35):
        try:
            tapes = mixtape_files()
        except Exception:
            tapes = []
        if tapes:
            _tp = random.choice(tapes)
            track = {"path": str(_tp),
                     "title": f"the MX tape \"{mixtape_title(_tp)}\"",
                     "seconds": tape_duration(_tp)}
    if not track:
        track = ((music_track(track_id)
                  if track_id and track_id != "mx" else None)
                 or _music_bed_track())
    bed_title = ""
    wav: bytes | None = None
    if track and track.get("path"):
        bed_title = str(track.get("title") or "a track")
        secs = float(track.get("seconds") or 0)
        loved = loved_moment(str(track.get("id") or ""))     # #683
        # #734: a cue point set by hand in the studio outranks both the
        # "loved moment" and the random drop-in — you picked the bar the
        # read should sit over, so that is the bar it sits over.
        bed_len: float | None = None
        if bed_in is not None and bed_in >= 0:
            start = float(bed_in)
            if bed_out is not None and bed_out > bed_in:
                bed_len = float(bed_out) - float(bed_in)
        elif loved is not None:
            start = max(0.0, loved - 4.0)
            if secs > 10:
                start = min(start, max(0.0, secs - 12.0))
        else:
            start = (random.uniform(20.0, max(21.0, min(70.0, secs - 25.0)))
                     if secs > 50 else 15.0)
        voice_key = clip["path"].rsplit("/", 1)[-1]
        sfx = await asyncio.to_thread(_sfx_any)
        wav = await asyncio.to_thread(
            _music_ad_mix_blocking, VOICE_MEDIA_DIR / voice_key,
            str(track["path"]), _clip_seconds(clip["path"]) or 8.0, start,
            str(sfx) if sfx else None, bed_pct, bed_len)
    if not wav:
        # No bed (or the mix failed): keep the dry vocoded read as the ad —
        # and say so honestly rather than naming a bed that is not in it.
        bed_title = ""
        try:
            wav = (VOICE_MEDIA_DIR
                   / clip["path"].rsplit("/", 1)[-1]).read_bytes()
        except Exception:
            wav = None
    if not wav:
        return {"error": "Could not render the ad audio."}
    # #743: re-cutting a spot you have EDITED keeps it the same spot — same
    # id, same place in the book, its audio replaced. Making a second entry
    # every time you fixed a word was how the book filled with near-copies.
    existing = (next((r for r in ad_list() if r.get("id") == ad_id), None)
                if ad_id else None)
    if existing:
        ad_update(existing["id"], product=product or existing.get("product")
                  or line[:40], text=line)
        entry = dict(existing)
        entry["text"] = line
        entry["product"] = product or existing.get("product") or line[:40]
    else:
        entry = ad_save(product or line[:40], line, kind="produced")
    name = await asyncio.to_thread(_produced_ad_write, wav, entry["id"])
    if not name:
        if not existing:
            ad_delete(entry["id"])
        return {"error": "Could not store the ad audio."}
    ad_update(entry["id"], audio=name, voice=v, bed=bed_title)
    entry.update({"audio": name, "voice": v, "bed": bed_title})
    # #916: how long the finished spot actually RUNS. A stacked spot is
    # shelved material like any other, and hour_needs() adds shelves up in
    # seconds — a produced spot with no length on it reads to the
    # coordinator as nothing at all, so the ad road would go on being
    # called bare with a cupboard full of finished audio in it. Measured
    # in a thread; a failure is 0.0 and costs nothing but the arithmetic.
    _secs = 0.0
    try:
        _secs = float(await asyncio.to_thread(
            sfx_seconds, PRODUCED_ADS_DIR / name) or 0.0)
    except Exception:  # noqa: BLE001
        _secs = 0.0
    accepted = False
    if air:
        accepted = bool(await _air_produced_ad(entry))
    return {"id": entry["id"], "text": line, "bed": bed_title,
            "audio": name, "seconds": round(_secs, 1),
            "url": f"/ads-audio/{name}?t={media_sign(name)}",
            "playback_requested": bool(air), "accepted": accepted,
            "delivery": ("handoff_accepted" if accepted else
                         "not_accepted" if air else "not_requested")}


# --- What people say about the track (#121) --------------------------------


def _notes_read() -> dict[str, Any]:
    try:
        data = json.loads(NOTES_PATH.read_text())
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def _notes_write(notes: dict[str, Any]) -> None:
    try:
        NOTES_PATH.parent.mkdir(parents=True, exist_ok=True)
        temporary = NOTES_PATH.with_suffix(".tmp")
        # Bounded: the newest 400 tracks are plenty for one station.
        trimmed = dict(sorted(notes.items(),
                              key=lambda kv: kv[1].get("ts", 0))[-400:])
        temporary.write_text(json.dumps(trimmed))
        temporary.replace(NOTES_PATH)
    except Exception:
        pass


LYRICS_PATH = data_path("track_lyrics.json")
_LYRICS_LOCK = RLock()


def _lyrics_read() -> dict[str, Any]:
    try:
        data = json.loads(LYRICS_PATH.read_text())
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def _lyrics_transcribe_blocking(path: str, seconds: float) -> str:
    """Extract a middle snippet of the song and Whisper it (#451). Music
    is not speech so this is imperfect — the clearer the vocal, the better
    — but it is real words from the actual track, cached per song."""
    import subprocess
    import imageio_ffmpeg
    exe = imageio_ffmpeg.get_ffmpeg_exe()
    start = max(0.0, seconds * 0.35)     # into the first verse/chorus
    try:
        out = subprocess.run(
            [exe, "-nostdin", "-hide_banner", "-loglevel", "error",
             "-ss", str(start), "-t", "45", "-i", path,
             "-ac", "1", "-ar", "16000", "-f", "s16le", "-"],
            capture_output=True, timeout=90)
        pcm = out.stdout
    except Exception:
        return ""
    if len(pcm) < 32000:
        return ""
    try:
        return wyoming_transcribe(pcm, rate=16000)[:600]
    except Exception:
        return ""


async def track_lyrics(track: dict[str, Any]) -> str:
    """Whisper a snippet of the song so the pair can talk about the words
    themselves (#451). Cached per track; empty when nothing usable came
    back (an instrumental, or vocals whisper could not make out)."""
    if not track or not track.get("path") or track.get("tape"):
        return ""
    key = str(track["id"])
    cached = _lyrics_read()
    if key in cached:
        return str(cached[key].get("text") or "")
    text = await asyncio.to_thread(
        _lyrics_transcribe_blocking, str(track["path"]),
        float(track.get("seconds") or 210))
    # A line of real words, not just noise: needs a few plausible words.
    words = re.findall(r"[a-z']{3,}", (text or "").lower())
    keep = text if len(words) >= 6 else ""
    with _LYRICS_LOCK:
        cached = _lyrics_read()
        cached[key] = {"text": keep, "at": int(time.time())}
        try:
            LYRICS_PATH.parent.mkdir(parents=True, exist_ok=True)
            keys = list(cached)
            for old in keys[:-400]:      # bounded
                cached.pop(old, None)
            LYRICS_PATH.write_text(json.dumps(cached))
        except OSError:
            pass
    if keep:
        pipeline_log("model", f"heard the lyrics of {track.get('title')}"
                              f" — {len(words)} words for the pair")
    return keep


async def track_notes(track: dict[str, Any]) -> str:
    """One or two lines on how this song lands with people. Cached per track:
    researching the same song every rotation is wasted network and a slower
    show. Empty string when nothing useful came back — the DJ then just
    introduces the track normally rather than inventing a reception."""
    if not track:
        return ""
    key = track["id"]
    notes = _notes_read()
    if key in notes:
        return str(notes[key].get("text") or "")

    who = f" {track['artist']}" if track.get("artist") else ""
    query = f'"{track["title"]}"{who} song reception review what people think'
    try:
        results = await _tv_search_angle(query)
    except Exception:
        results = []

    lines = []
    for result in results[:5]:
        title = str(result.get("title") or "").strip()
        body = " ".join(str(
            result.get("snippet") or result.get("content") or "").split())
        if title or body:
            lines.append(f"- {title}: {body[:400]}")

    text = ""
    # #808: the PROCESS is part of the result — the prompt, the model and
    # the clock ride with the note so the booth chip can open a dossier.
    _prompt = (
        "From these search results, say in ONE or TWO sentences how "
        "people actually receive this song — loved, divisive, a "
        "sleeper, whatever the sources support. Attribute it as what "
        "listeners say. If the results are clearly about a different "
        "song, reply with exactly: NONE\n\n"
        f"Song: {track['title']}{who}\n\n" + "\n".join(lines))
    _t0 = time.monotonic()
    if lines:
        try:
            text = await ask_model(_prompt, limit=320, result_contract="track_reception")
        except Exception:
            text = ""
    if text.strip().upper().startswith("NONE"):
        text = ""

    # #834: the dictionary sense of the title, if these same results
    # happen to carry one. Kept beside the reception note so a round can
    # read it without another search - and so a title whose page was
    # "clearly about a different song" (answered NONE above) still leaves
    # the pair something true to talk about.
    define = ""
    try:
        define = title_definition(str(track.get("title") or ""), results)
    except Exception:  # noqa: BLE001
        define = ""
    if define:
        pipeline_log("model", "the title turns out to be a word - "
                     f"{track.get('title')}: {define[:90]} (#834)")
    notes[key] = {"text": text, "ts": int(time.time()),
                  "model": str(load_settings().get("model") or ""),
                  "ms": int((time.monotonic() - _t0) * 1000),
                  "define": define,
                  "prompt": _prompt[:2400], "query": query}
    _notes_write(notes)
    return text


def song_analysis_ready(track: dict[str, Any], analysis: str) -> None:
    """Put the completed LLM reading of the current record in the booth.

    It is an analysis event, never an on-air speaker turn: the live marker
    remains reserved for the one voice actually coming through the station.
    """
    track_id = str(track.get("id") or "")
    text = " ".join(str(analysis or "").split())[:1600]
    if not (track_id and text):
        return
    if _RADIO.get("song_analysis_id") == track_id:
        return
    _RADIO["song_analysis_id"] = track_id
    _proc = _notes_read().get(track_id) or {}
    _RADIO["chat"].append({
        "id": uuid.uuid4().hex[:6], "ts": int(time.time()),
        "air_at": time.time(), "who": "analysis", "kind": "song_analysis",
        "text": f"Song analysis complete: {track.get('title') or track_id}",
        "analysis": text,
        "track_id": track_id,
        "artist": str(track.get("artist") or ""),
        "model": str(_proc.get("model") or ""),
        "ms": int(_proc.get("ms") or 0),
        "prompt": str(_proc.get("prompt") or ""),
        "query": str(_proc.get("query") or ""),
        "aired": "analysis",
    })
    del _RADIO["chat"][:-240]
    pipeline_log("model", "song analysis ready — "
                 f"{track.get('title') or track_id}")



# --- Two in the booth (#133) -----------------------------------------------


def banter_material(limit: int = 12) -> str:
    """What the pair have to work with: the things you have actually asked
    for. Requests on air first, then what you have been asking the Pine Box
    generally — that is where the running jokes come from."""
    bits: list[str] = []

    # What he has told us outright that he loves, which is the closest thing
    # the pair have to a standing request (#181).
    for row in loved_tracks(3):
        bits.append(
            f"he loves {row.get('title')}"
            + (f" by {row.get('artist')}" if row.get("artist") else "")
            + " and asked us to play it more")

    # What he keeps coming back to, across every show there has ever been.
    #
    # #888: WITHOUT THE NUMBER. This line is the one that put "he has asked
    # for blue monday by Flunk 12 times now" into the writing prompt under
    # "Things he keeps asking for", and the co-host read the count back to
    # him on air as a fact about him. It was not a fact: most of those
    # twelve were his own library clicks landing on the same counter.
    #
    # The ledger is honest now, but an ambient tally is still the station
    # asserting an arithmetic nobody asked it to keep. The pair are told
    # WHAT he comes back to - which is the useful part and the part that is
    # true - and the count is left to request_brief, which fires at the
    # moment he actually asks for a repeat and is a number he would
    # recognise.
    try:
        for row in request_history()["top"][:4]:
            times = int(row.get("count") or 0)
            if row.get("asked"):
                times = min(times, request_evidenced(row))
            if times > 1:
                bits.append(
                    f'he keeps coming back to "{row.get("title")}"'
                    + (f' by {row.get("artist")}' if row.get("artist") else "")
                    + " - do not put a number on it")
    except Exception:
        pass

    for line in reversed(_RADIO.get("chat") or []):
        if line.get("kind") == "request" and line.get("who") == "host":
            bits.append(str(line.get("text") or ""))
        if len(bits) >= 5:
            break

    try:
        # A wide random sample, not the newest forty (#399, #400): recent
        # history is whatever run dominated the evening — one Dracula
        # session and the pair talked about nothing else for a week.
        turns = [" ".join(str(t.get("user") or "").split())
                 for t in read_history(limit=240)]
        turns = [t for t in turns if len(t) > 12]
        random.shuffle(turns)
        for text in turns:
            bits.append(text[:160])
            if len(bits) >= limit:
                break
    except Exception:
        pass

    try:
        for memory in read_memories(limit=6):
            note = " ".join(str(memory.get("text") or "").split())
            if note:
                bits.append("he once told us: " + note[:140])
    except Exception:
        pass

    return "\n".join(f"- {b}" for b in bits[:limit])


# Whose story it is. The frame is domestic and dull on purpose — the joke is
# the thing being wanted, not the telling (#191, #192).
DOMESTIC_WHO = (
    "my wife", "my husband", "my eldest", "my kid", "the wife's mother",
    "my neighbour", "my brother-in-law", "the lad next door", "my mother",
    "my flatmate", "my sister", "the woman who does my garden",
)


def _generation_files(gen: dict[str, Any]) -> list[str]:
    """The generation log stores its file list as a repr, so read the names
    back out of it either way."""
    raw = gen.get("files")
    if isinstance(raw, list):
        return [str(x) for x in raw]
    return re.findall(r"[\w\-. ]+\.(?:png|jpg|jpeg|webp)", str(raw or ""),
                      re.I)


def banter_pool(limit: int = 40) -> list[str]:
    """Everything of his the pair can build a story out of, shuffled.

    What he has asked for on air, what he has asked the box generally, the
    pictures he had us make, the words he used to ask for them, and the names
    those pictures were saved under — a file name is often the shortest
    description of the thing in it. Recombined fresh every round, so the same
    three anecdotes do not come round all night (#191, #192)."""
    bits: list[str] = []
    try:
        for row in request_history()["top"][:8]:
            if row.get("title"):
                bits.append(
                    str(row["title"])
                    + (f" by {row['artist']}" if row.get("artist") else ""))
    except Exception:
        pass
    try:
        for gen in read_generations(40):
            for field in ("request", "tags"):
                text = " ".join(str(gen.get(field) or "").split())
                if len(text) > 10:
                    bits.append(text[:150])
            for name in _generation_files(gen):
                stem = re.sub(r"[_\-]+", " ", Path(name).stem)
                stem = " ".join(re.sub(r"\b\d{3,}\b", " ", stem).split())
                if len(stem) > 3:
                    bits.append(f"a picture of ours called {stem}")
    except Exception:
        pass
    try:
        for turn in read_history(limit=40):
            text = " ".join(str(turn.get("user") or "").split())
            if len(text) > 12:
                bits.append(text[:150])
    except Exception:
        pass

    seen: set[str] = set()
    out: list[str] = []
    for bit in bits:
        if bit.lower() not in seen:
            seen.add(bit.lower())
            out.append(bit)
    random.shuffle(out)
    return out[:limit]


def domestic_angles(count: int = 3) -> list[str]:
    """"My wife came to me the other day wanting …" — the thing wanted is
    always something of his (#192)."""
    return [
        f"one of you tells the other a small domestic story: "
        f"{random.choice(DOMESTIC_WHO)} came to you the other day wanting "
        f"{item}. Tell it completely flat, as the most ordinary request in "
        "the world, and let the other one react to it"
        for item in banter_pool(count)
    ]


def callback_angles(count: int = 2) -> list[str]:
    """Remember-that-time material: adverts they have actually read and calls
    they have actually taken, so the show has a past (#190)."""
    out: list[str] = []
    for ad in ad_list()[-10:]:
        if ad.get("product"):
            out.append(
                "reminisce on air about the advert you had to read for "
                f"{ad['product']} — 'do you remember that one' — and how it "
                "went down at the time")
    for line in reversed(_RADIO.get("chat") or []):
        if line.get("kind") in ("request", "played") and line.get("text"):
            out.append(
                f"bring up something from earlier in the show — {line['text']}"
                " — as though it had already become a station legend")
            break
    # Lines out of his documents that have already been on air. Said once
    # they were a stray thought; said again they are something the pair have
    # between them, which is how the material becomes theirs.
    for row in speakbox_heard()[:8]:
        if row.get("text"):
            out.append(
                "one of you brings back something the two of you have said on "
                f"this show before — \"{row['text']}\" — as a bit you both "
                "know by now, and the other one runs with it")
    random.shuffle(out)
    return out[:count]


COMFY_OUTPUT = Path("/comfy-output")

# #831: where a picture actually LIVES under the mounted output tree.
#
# Every corner of the panel addresses art by bare filename, and all of it was
# served by proxying ComfyUI's own /view. Two ways that breaks, and the
# caller's licence hit both: /view only ever resolves the output ROOT, so
# anything sitting in a subfolder (_contact_sheets/, smut/, video/) came back
# 404 — and when ComfyUI itself is not up, which is often on a box that wants
# its VRAM for the voices, EVERY image on the page fails at once. The folder
# is bind-mounted at /comfy-output. Read it.
_COMFY_FOUND: dict[str, Path] = {}

_IMAGE_TYPES = {".png": "image/png", ".jpg": "image/jpeg",
                ".jpeg": "image/jpeg", ".webp": "image/webp",
                ".gif": "image/gif", ".bmp": "image/bmp",
                ".mp4": "video/mp4", ".webm": "video/webm"}

# A contact sheet is a 3x3 grid of thumbnails and the video/audio folders are
# not pictures at all — nothing in either is anybody's face.
_FACE_SKIP_DIRS = ("_contact_sheets", "video", "audio",
                   "_output_images_will_be_put_here",
                   "_gazette")   # G3 #1020: the Gazette's snapshots


def comfy_output_find(filename: str) -> Path | None:
    """The file behind a bare gallery filename, subfolders included (#831)."""
    name = str(filename or "").strip()
    if not name or "/" in name or ".." in name:
        return None
    try:
        held = _COMFY_FOUND.get(name)
        if held is not None and held.is_file():
            return held
        direct = COMFY_OUTPUT / name
        if direct.is_file():
            _COMFY_FOUND[name] = direct
            return direct
        for found in COMFY_OUTPUT.rglob("*"):
            if found.name == name and found.is_file():
                if len(_COMFY_FOUND) > 600:
                    _COMFY_FOUND.clear()
                _COMFY_FOUND[name] = found
                return found
    except OSError:
        return None
    return None


def comfy_output_bytes(filename: str) -> tuple[bytes, str] | None:
    """A picture straight off the mount, with its content type (#831)."""
    found = comfy_output_find(filename)
    if found is None:
        return None
    try:
        blob = found.read_bytes()
    except OSError:
        return None
    return blob, _IMAGE_TYPES.get(found.suffix.lower(), "image/png")


def face_candidate(path: Path) -> bool:
    """Is this picture fit to be somebody's licence photo (#831)?"""
    try:
        if any(part in _FACE_SKIP_DIRS for part in path.parts):
            return False
        return "contact_sheet" not in path.name.lower()
    except Exception:
        return False


GALLERY_TYPES = (".png", ".jpg", ".jpeg", ".webp")
_GALLERY_CACHE: dict[str, Any] = {"at": 0.0, "rows": []}


def gallery_files(most: int = 600) -> list[Path]:
    """#847: every picture the wall may show, newest first.

    THE one list. Non-art folders are skipped and duplicate basenames
    are dropped keeping the newest, because the panel addresses art by
    bare filename — two files sharing a name means the wall and the
    server can disagree about which one it is, and a hole appears.
    Whatever survives is pinned into the resolver cache, so a listed
    name is servable by construction rather than by luck."""
    now = time.time()
    if _GALLERY_CACHE["rows"] and now - float(_GALLERY_CACHE["at"]) < 30:
        return list(_GALLERY_CACHE["rows"])
    try:
        found = [q for q in COMFY_OUTPUT.rglob("*")
                 if q.is_file() and q.suffix.lower() in GALLERY_TYPES
                 and not any(part in _FACE_SKIP_DIRS for part in q.parts)]
        found.sort(key=lambda q: q.stat().st_mtime, reverse=True)
    except OSError:
        return list(_GALLERY_CACHE["rows"])
    rows: list[Path] = []
    seen: set[str] = set()
    for q in found:
        if q.name in seen:
            continue                    # newest wins; the older twin is
        seen.add(q.name)                # unreachable by bare name anyway
        rows.append(q)
        _COMFY_FOUND[q.name] = q        # what we list is what resolves
        if len(rows) >= most:
            break
    _GALLERY_CACHE["at"] = now
    _GALLERY_CACHE["rows"] = rows
    return list(rows)


def gallery_sample(limit: int = 8) -> list[str]:
    """A random handful out of the WHOLE ComfyUI output — thirteen hundred
    images, not just the ones this agent ordered (#261). A filename is often
    the shortest description of the thing in it; the workflow prefix says
    what kind of machine painted it."""
    found = gallery_files()                                   # #847
    picks = random.sample(found, min(limit, len(found))) if found else []
    out = []
    for path in picks:
        stem = re.sub(r"[_\-]+", " ", path.stem)
        stem = " ".join(re.sub(r"\b\d{4,}\b", "", stem).split())
        if stem:
            out.append(stem[:80])
    return out


async def describe_gallery_image(want: str = "",
                                 prompt: str = "") -> tuple[str, str]:
    """A picture off the render machine, actually LOOKED AT (#341): the
    resident model is multimodal, so the description comes from the pixels,
    not from the prompt that made them. `want` names ONE picture — that is
    how a piece you chose off the wall gets hawked (#719/#723) rather than
    whatever the draw came up with. Returns (filename, description) or
    ("", "")."""
    try:
        # #847: the same list the wall shows, so the pair can never be
        # handed a picture the room cannot see.
        pool = [q for q in (await asyncio.to_thread(gallery_files))
                if q.stat().st_size < 24_000_000]
        if not pool:
            return "", ""
        picked = None
        if want:
            picked = next((p for p in pool if p.name == want), None)
            if picked is None:
                return "", ""
        if picked is None:
            # Fresh walls (#343): pictures already shown wait until the rest
            # of the gallery has had its turn.
            unseen = [p for p in pool
                      if p.name not in _RADIO.setdefault("gallery_shown", [])]
            picked = random.choice(unseen or pool)
        shown = _RADIO.setdefault("gallery_shown", [])
        shown.append(picked.name)
        del shown[:-60]
        image_b64 = base64.b64encode(picked.read_bytes()).decode()
        settings = load_settings()
        # #860: `prompt` is the operator looking again through something
        # they just wrote. Empty means the station's own armed prompt,
        # which is every ordinary round.
        _look = str(prompt or "").strip() or vision_prompt_active()
        _vt0 = time.monotonic()
        async with _OLLAMA_GATE, httpx.AsyncClient(timeout=120) as client:
            response = await client.post(
                f"{OLLAMA_URL}/api/chat",
                json={
                    # A model that can actually SEE (#441).
                    "model": VISION_MODEL,
                    "messages": [{
                        "role": "user",
                        "content": (
                            # #878: the looking prompt is the operator's now — see
                            # vision_prompt_active(). This literal remains
                            # the CLASSIC, and reverting comes back here.
                            # #646: when they DO look, they look properly —
                            # atomic detail, and visibly affected by it.
                            _look),
                        "images": [image_b64],
                    }],
                    "stream": False,
                    "think": False,
                    "keep_alive": "30m",
                    # #1079: THE SAME CONTEXT THE WRITER USES. This
                    # call sent no num_ctx, so ollama loaded the shared
                    # gemma4:e2b runner at its daemon default of 32768
                    # and the next writing call rebuilt it at 65536 -
                    # measured, 1,420 runner starts in a day with the
                    # two sizes EXACTLY PAIRED per hour, at 6.85s a
                    # rebuild. #1045 pinned the context and this one
                    # line unpinned it.
                    # #901: a seed, and a jittered temperature. What
                    # this call writes is the SEED of the gallery round
                    # — the pair talk about what it says — and with a
                    # fixed temperature and no seed at all the same
                    # picture came back described in the same words,
                    # which is a repeat manufactured upstream of every
                    # gate the station has.
                    # #1070: one options dict. Two "options" keys in this
                    # literal meant the later one won and the #1079
                    # num_ctx pin was silently dropped.
                    "options": {
                        "num_ctx": model_ctx(),
                        "temperature": round(random.uniform(0.75, 0.95), 3),
                        "num_predict": 460,
                        "seed": random.randint(1, 2_000_000_000),
                    },
                },
            )
            response.raise_for_status()
            said = ((response.json().get("message") or {})
                    .get("content") or "").strip()
        said = re.sub(r"<think>.*?</think>", " ", said, flags=re.S)
        said = " ".join(said.split())[:1200]     # room for the detail (#646)
        if said:
            pipeline_log("model", f"looked at {picked.name} — "
                                  f"{len(said)} chars of description")
            image_analysis_ready(
                picked.name, said, model=VISION_MODEL,
                ms=int((time.monotonic() - _vt0) * 1000),
                prompt=_look)
            # Any time a gallery picture is looked at and talked about, the
            # booth holds up its thumbnail (#506, #523) — not only during the
            # dedicated gallery round.
            _RADIO["gallery_now"] = {
                "at": time.time(),
                "images": [{"name": picked.name, "desc": said}],
            }
        return picked.name, said
    except Exception:
        return "", ""                   # a model without eyes riffs blind


VISION_PROMPTS_PATH = data_path("vision_prompts.json")

# #878: the classic — the #646 atomic-detail contract. Entry one of the
# library, never deletable, and what "revert" comes back to.
VISION_PROMPT_CLASSIC = (
    "You are a radio host holding this picture up for listeners who "
    "cannot see it, and it has got under your skin. Describe it in "
    "FIVE or SIX spoken sentences, in lurid, atomic detail: the exact "
    "colours and where they sit, the light and what it is doing, every "
    "figure or object and its posture and expression, the texture of "
    "the paint or the grain of the photograph, what is happening in "
    "the corners and the background that a careless eye would miss. "
    "Then say plainly what it DOES to you — be unsettled, disturbed, "
    "moved, unable to leave it alone. Speak it aloud; no markdown, no "
    "preamble, no list.")


_VISION_LOCK = RLock()


def vision_prompts() -> dict[str, Any]:
    """The library (#878, opened up in #860).

    Every looking prompt the station owns, in order, with the classic
    always at the head: it is entry one, it cannot be deleted or
    overwritten, and it is what "revert to default" comes back to. One
    of them is ACTIVE - that is the one pictures are read through.

    `prefs` is the standing preferences (#860: "additional preferences
    that we're using for going through and analyzing these images") -
    one shelf of house rules that ride on top of whichever variant is
    armed, so they do not have to be re-typed into every prompt."""
    rows: list[dict[str, Any]] = []
    active = "classic"
    prefs = ""
    try:
        got = json.loads(VISION_PROMPTS_PATH.read_text())
        for raw in (got.get("prompts") or []):
            if not isinstance(raw, dict):
                continue
            pid = str(raw.get("id") or "").strip()
            if not pid or pid == "classic":
                continue
            rows.append({
                "id": pid[:40],
                "name": str(raw.get("name") or "untitled")[:60],
                "text": str(raw.get("text") or "")[:4000],
                "notes": str(raw.get("notes") or "")[:1200],
                "at": int(raw.get("at") or 0),
                "builtin": False,
            })
        active = str(got.get("active") or "classic")
        prefs = str(got.get("prefs") or "")[:1200]
    except Exception:  # noqa: BLE001
        pass
    rows.insert(0, {"id": "classic", "name": "the classic (#646)",
                    "text": VISION_PROMPT_CLASSIC, "builtin": True,
                    "notes": "", "at": 0})
    if active not in {str(r.get("id")) for r in rows}:
        active = "classic"
    return {"prompts": rows, "active": active, "prefs": prefs,
            "default_id": "classic",
            "default_text": VISION_PROMPT_CLASSIC}


def vision_prompts_save(rows: list[dict[str, Any]], active: str,
                        prefs: str | None = None) -> None:
    """Write the library down whole - .tmp then .replace, under the
    lock, so a half-written library can never be what the station wakes
    up to. `prefs` left None keeps whatever is already on disk, so an
    older two-argument caller cannot quietly wipe the house rules."""
    with _VISION_LOCK:
        try:
            keep_prefs = str(
                prefs if prefs is not None
                else (vision_prompts().get("prefs") or ""))[:1200]
        except Exception:  # noqa: BLE001
            keep_prefs = ""
        try:
            VISION_PROMPTS_PATH.parent.mkdir(parents=True, exist_ok=True)
            keep = [{"id": str(r.get("id") or "")[:40],
                     "name": str(r.get("name") or "untitled")[:60],
                     "text": str(r.get("text") or "")[:4000],
                     "notes": str(r.get("notes") or "")[:1200],
                     "at": int(r.get("at") or 0) or int(time.time())}
                    for r in rows if str(r.get("id") or "") != "classic"
                    and str(r.get("text") or "").strip()][:24]
            tmp = VISION_PROMPTS_PATH.with_suffix(".tmp")
            tmp.write_text(json.dumps(
                {"prompts": keep, "active": active, "prefs": keep_prefs}))
            tmp.replace(VISION_PROMPTS_PATH)
        except OSError:
            pass


def vision_prompt_compose(text: str, prefs: str = "") -> str:
    """One prompt as the model actually receives it: the variant's own
    words, then the standing preferences underneath (#860). Composing in
    ONE place means the prompt that is sent is byte for byte the prompt
    the dossier shows you afterwards."""
    body = str(text or "").strip() or VISION_PROMPT_CLASSIC
    extra = " ".join(str(prefs or "").split())[:1200]
    if extra:
        body += ("\n\nSTANDING PREFERENCES for looking at pictures at "
                 "this station, which apply on top of everything above: "
                 + extra)
    return body


def vision_prompt_row(pid: str = "") -> dict[str, Any]:
    """One variant by id - or the active one when `pid` is empty. Never
    raises and never comes back empty: the classic is the floor."""
    try:
        lib = vision_prompts()
        want = str(pid or "").strip() or str(lib["active"])
        for row in lib["prompts"]:
            if str(row.get("id")) == want:
                return dict(row)
        return dict(lib["prompts"][0])
    except Exception:  # noqa: BLE001
        return {"id": "classic", "name": "the classic (#646)",
                "text": VISION_PROMPT_CLASSIC, "builtin": True}


def vision_prompt_for(pid: str = "") -> str:
    """What the station would look through if it used that variant -
    the variant's text with the house rules already folded in."""
    try:
        lib = vision_prompts()
        want = str(pid or "").strip() or str(lib["active"])
        text = ""
        for row in lib["prompts"]:
            if str(row.get("id")) == want:
                text = str(row.get("text") or "")
                break
        return vision_prompt_compose(text, str(lib.get("prefs") or ""))
    except Exception:  # noqa: BLE001
        return VISION_PROMPT_CLASSIC


def vision_prompt_active() -> str:
    """What the station looks through right now (#878)."""
    return vision_prompt_for("")


def image_analysis_ready(name: str, analysis: str, model: str = "",
                         ms: int = 0, prompt: str = "") -> None:
    """Record a completed vision pass as a quiet booth event."""
    text = " ".join(str(analysis or "").split())[:1600]
    if not (name and text):
        return
    key = f"{name}:{hashlib.sha1(text.encode()).hexdigest()[:10]}"
    if _RADIO.get("image_analysis_id") == key:
        return
    _RADIO["image_analysis_id"] = key
    _RADIO["chat"].append({
        "id": uuid.uuid4().hex[:6], "ts": int(time.time()),
        "air_at": time.time(), "who": "analysis", "kind": "image_analysis",
        "text": f"Image analysis complete: {name}", "analysis": text,
        "image": name, "model": model, "ms": int(ms or 0),
        "prompt": str(prompt or ""), "aired": "analysis",
    })
    del _RADIO["chat"][:-240]


async def dj_gallery_round(bank_to: list[dict[str, Any]] | None = None,
                           shelf_only: bool = False
                           ) -> list[str]:
    """The gallery press (#346): several paintings in one round, each
    described from its pixels (#341, #343), argued over, priced absurdly
    and hawked to the listeners — speakbox rhetoric stitched through."""
    if shelf_only or (bank_to is None and talk_is_incessant()):
        return await _ready_shelf_air("gallery", None)
    # #855: a painting round WRITTEN AND VOICED during an earlier record
    # goes straight out - no vision pass, no model call, no render, no
    # wait. `bank_to` is the other side of the same door dj_manager_note
    # and dj_caller already have: the preparer calls THIS function to
    # write one and is handed the round back instead of it airing. An
    # empty shelf falls straight through to the live road below.
    if bank_to is None:
        try:
            _prep_art = shelf_take("gallery")
        except Exception:  # noqa: BLE001
            _prep_art = None
        if _prep_art:
            _prep_entry = _prep_art.get("entry") or {}
            # THE PICTURES RODE WITH IT. A prepared round still knows
            # exactly what it is about because the chosen paintings and
            # the descriptions they were written from were banked ON the
            # entry - so the booth holds up the very image being hawked
            # (#506) and #702 can hang it on the lines, an hour later.
            _prep_pics = [p for p in (_prep_entry.get("prep_gallery") or [])
                          if isinstance(p, dict) and p.get("name")]
            if _prep_pics:
                _RADIO["gallery_now"] = {
                    "at": time.time(),
                    "images": [{"name": str(p.get("name") or ""),
                                "desc": str(p.get("desc") or "")}
                               for p in _prep_pics[:3]],
                }
                # #1005: and the lines of THIS round take them as each one
                # is written - see gallery_pending_set. Bound to the round
                # that is about them, so the next round's phone call does
                # not inherit the painting.
                try:
                    _gp = _RADIO["gallery_now"]["images"]
                    gallery_pending_set(
                        [str((x or {}).get("name") or "") for x in _gp],
                        [str((x or {}).get("desc") or "") for x in _gp])
                except Exception:  # noqa: BLE001
                    pass
            _prep_began = time.time()
            try:
                _prep_said = await _banter_air(_prep_entry, None)
            except Exception:  # noqa: BLE001
                _prep_said = []
            if _prep_said:
                try:
                    # #991: the prepared round banked the descriptions
                    # with the pictures, so the match is available here
                    # too - and this is the road most rounds now take.
                    gallery_line_mark(
                        [str(p.get("name") or "") for p in _prep_pics],
                        _prep_began,
                        [str(p.get("desc") or "") for p in _prep_pics])
                except Exception:  # noqa: BLE001
                    pass
                pipeline_log("air", "a painting round goes straight to air "
                             "- it was written and recorded during an "
                             "earlier record, and the pictures it is about "
                             "came with it (#855)")
                return _prep_said
            # Nothing came out of it: fall through and write a fresh one,
            # which is the road this segment has always had.
    pieces: list[tuple[str, str]] = []
    for _ in range(4):
        # #872: the vision model is the dearest thing on this road. On
        # the PREPARING road only, stand down between pictures the
        # instant the live show wants the room - one painting is enough
        # to write a round about, and the rest come on a later pass.
        if bank_to is not None and pieces and prep_should_stop():
            break
        name, desc = await describe_gallery_image()
        if desc and all(desc != held for _, held in pieces):
            pieces.append((name, desc))
        if len(pieces) >= 3:
            break
    if not pieces:
        return []
    # Show the booth what they're selling (#506): the paintings of this round,
    # so the side panel can hold up the very image being hawked on air. Fresh
    # for the length of the segment; dj_state ages it out.
    # #855: NOT on the preparing road. This round is not airing yet, and
    # holding a painting up beside whatever IS on air would be a lie. It
    # goes up at the moment the prepared round actually airs, off the
    # pictures banked on the entry - see the shelf road above.
    if bank_to is None:
        _RADIO["gallery_now"] = {
            "at": time.time(),
            "images": [{"name": n, "desc": d} for n, d in pieces],
        }
        # #1005: and the lines of THIS round take them as each one
        # is written - see gallery_pending_set. Bound to the round
        # that is about them, so the next round's phone call does
        # not inherit the painting.
        try:
            _gp = _RADIO["gallery_now"]["images"]
            gallery_pending_set(
                [str((x or {}).get("name") or "") for x in _gp],
                [str((x or {}).get("desc") or "") for x in _gp])
        except Exception:  # noqa: BLE001
            pass
    seed = await speakbox_quote(most=5, cap=450)
    listing = " ".join(
        f"PAINTING {i + 1}: \"{desc}\""
        for i, (_, desc) in enumerate(pieces))
    angle = (
        f"The pair go through the station gallery ON AIR — {len(pieces)} "
        f"paintings, one after another, none skipped. {listing} Describe "
        "and react to EACH in turn — argue about what it means. "
        # #1173: THE SALE, as plainly as the title. Measured on the shelf:
        # 31 of 53 rounds proposed a better title and only 11 named a
        # price, because the title had three sentences of exact
        # instruction and the sale had four words inside a list.
        "FOR EACH PAINTING one of you must NAME A PRICE OUT LOUD, in "
        "dollars, and hawk it - say the number, say what it is worth and "
        "why, and tell the listeners the first caller takes it. The prices "
        "are absurd and they are said as figures, not as 'a fortune'. "
        "For EACH painting, one host must propose a better title based on "
        "what they can actually see, naturally phrased as 'it should have "
        "been called ...' or 'this painting looks like ...'. Make the titles "
        "specific, vivid, and spoken aloud. Go properly off the wall with it."
        + (f" Somewhere in the middle one of you drops this, word for "
           f"word, as though it explains the art: \"{seed['text']}\""
           if seed else ""))
    angle += radio_prompt_instruction("gallery")
    began = time.time()
    lines = await dj_banter(None, angle=angle, lines=12,
                            source=(seed or {}).get("file", ""),
                            bank=bank_to is not None, bank_to=bank_to,
                            own_material=True)           # the painting is the material
    if bank_to is not None:
        # #855: THE PICTURES GO WITH THE ROUND. Everything the airing
        # needs in order to know what this round is ABOUT - which
        # paintings, and the descriptions they were written from - is
        # banked on the entry itself, so nothing has to be looked at a
        # second time when it finally airs and the vision passes are
        # paid for exactly once.
        try:
            if bank_to:
                bank_to[-1]["prep_gallery"] = [
                    {"name": str(n), "desc": str(d)[:600]}
                    for n, d in pieces]
                if seed:
                    speakbox_remember(seed)
        except Exception:  # noqa: BLE001
            pass
        return []
    # #702: the paintings ride the lines that are about them.
    # #991: ...and the RIGHT one does, matched on the description.
    gallery_line_mark([n for n, _ in pieces], began,
                      [d for _, d in pieces])
    if lines and seed:
        speakbox_remember(seed)
    return lines


# --- Look again (#860) ------------------------------------------------------
#
# "Whenever I edit the prompt and I submit it, I want to submit the image for
#  re analysis and have the lines for speaking about it redone based on the
#  new analysis of the system prompt that I write in there."
#
# Looking takes the vision model the better part of a minute and writing a
# round takes longer still, so a re-analysis is a JOB: the panel gets a ticket
# straight back and watches it land. The new reading goes down the SAME road
# the gallery press uses and nowhere else -
#
#   describe_gallery_image(name, prompt=...)   looks, and on the way out
#     image_analysis_ready(...)                puts the new description in the
#                                              booth with the exact prompt
#     _RADIO["gallery_now"]                    holds the picture up beside the
#                                              dialogue
#   dj_reanalysis_round(name, desc)            writes and AIRS fresh lines off
#                                              the new description
#     gallery_line_mark([name], began)         hangs the picture on every line
#                                              the round just aired (#702)
#
# so the pair really are talking about the new reading, in their own voices,
# on the actual broadcast - not about a cached one.
_VISION_JOBS: dict[str, dict[str, Any]] = {}
_VISION_JOB_LOCK = RLock()


def vision_job_put(job: str, **fields: Any) -> dict[str, Any]:
    """Set down where a re-analysis got to. Keeps the last two dozen."""
    with _VISION_JOB_LOCK:
        row = _VISION_JOBS.setdefault(
            str(job), {"job": str(job), "state": "queued", "at": time.time(),
                       "image": "", "prompt": "", "description": "",
                       "lines": [], "error": "", "ms": 0})
        row.update(fields)
        row["seen"] = time.time()
        if len(_VISION_JOBS) > 24:
            old = sorted(_VISION_JOBS,
                         key=lambda k: float(_VISION_JOBS[k].get("at") or 0))
            for dead in old[:-24]:
                _VISION_JOBS.pop(dead, None)
        return dict(row)


def vision_job_get(job: str) -> dict[str, Any]:
    with _VISION_JOB_LOCK:
        row = _VISION_JOBS.get(str(job or ""))
        return dict(row) if row else {}


async def dj_reanalysis_round(name: str, desc: str) -> list[str]:
    """The pair take ONE picture up again, off the new reading (#860).

    The same shape as the gallery press: the description IS the thing they
    talk about, the booth holds the picture up, and every line the round airs
    gets the picture hung on it."""
    if not (name and desc):
        return []
    _RADIO["gallery_now"] = {
        "at": time.time(),
        "images": [{"name": name, "desc": desc}],
    }
    # #1005: and the lines of THIS round take them as each one
    # is written - see gallery_pending_set. Bound to the round
    # that is about them, so the next round's phone call does
    # not inherit the painting.
    try:
        _gp = _RADIO["gallery_now"]["images"]
        gallery_pending_set(
            [str((x or {}).get("name") or "") for x in _gp],
            [str((x or {}).get("desc") or "") for x in _gp])
    except Exception:  # noqa: BLE001
        pass
    try:
        seed = await speakbox_quote(most=4, cap=380)
    except Exception:                              # noqa: BLE001
        seed = None
    angle = (
        "THE PAIR LOOK AT ONE PICTURE AGAIN, PROPERLY. The station has just "
        "re-read this piece off the wall with fresh eyes and a new brief, and "
        "THIS is what came back - the only account of it that counts now: "
        f"\"{desc}\" "
        "Talk about THIS reading of it and nothing else: the colours and "
        "where they sit, the figures, what is happening in the corners, and "
        "what it does to you. Say out loud that you are looking at it again "
        "and seeing something you did not see the first time, and argue "
        "about what changed. One of you must propose a title out of what is "
        "actually described here, phrased naturally as 'it should have been "
        "called ...'. Spoken aloud; no markdown, no preamble, no list."
        + (f" Somewhere in it one of you drops this, word for word, as "
           f"though it settles the argument: \"{seed['text']}\""
           if seed else ""))
    angle += radio_prompt_instruction("gallery")
    began = time.time()
    lines = await dj_banter(None, angle=angle, lines=8,
                            source=(seed or {}).get("file", ""),
                            own_material=True)
    gallery_line_mark([name], began)
    if lines and seed:
        speakbox_remember(seed)
    return lines


async def vision_reanalyse_job(job: str, image: str, look: str,
                               redo_lines: bool = True) -> None:
    """Read one picture again through `look`, then redo what is said about
    it. Wrapped end to end - nothing in here may take the station off air."""
    try:
        vision_job_put(job, state="looking", image=image, prompt=look)
        began = time.monotonic()
        name, desc = await describe_gallery_image(image, prompt=look)
        if not desc:
            vision_job_put(
                job, state="failed",
                error=f"the vision model came back empty on {image[:60]!r} - "
                      "is that picture still on the wall?")
            return
        vision_job_put(job, state="writing", image=name, description=desc,
                       ms=int((time.monotonic() - began) * 1000))
        pipeline_log("model", f"looked again at {name} through an edited "
                              f"prompt - {len(desc)} chars (#860)")
        if not redo_lines:
            vision_job_put(job, state="done", lines=[])
            return
        said = await dj_reanalysis_round(name, desc)
        vision_job_put(job, state="done",
                       lines=[str(x) for x in (said or [])])
    except Exception as exc:                       # noqa: BLE001
        try:
            vision_job_put(job, state="failed", error=str(exc)[:200])
            pipeline_log("drop", f"the re-analysis died: {exc}"[:200])
        except Exception:                          # noqa: BLE001
            pass


# --- Hawking the art (#719, #723) -------------------------------------------
#
# The gallery round picked its own paintings and talked ABOUT them. This is
# the sales floor: pictures YOU chose, pitched at a named disposition, to a
# person on the line who either buys or refuses — and what does not sell is
# put aside, out loud, and the show carries on.
HAWK_MOODS = {
    "curious": "genuinely interested and full of questions about it",
    "impressed": "openly impressed, and says so more than once",
    "disgusted": "revolted by it and not hiding it",
    "appalled": "morally appalled that this is being sold at all",
    "angry": "angry — at the price, at the picture, at being asked",
    "emotional": "unexpectedly moved, close to tears about it",
    "effect": "affected by it in a way they cannot explain",
    "drunk": "several drinks in and not tracking the pitch",
    "inattentive": "not really listening, answering a beat late",
    "distracted": "distracted by something on their end all through it",
    "not understanding": "not understanding what is being described at all",
    "too expensive": "sure it is far too expensive and haggling hard",
}
# How long a hawk segment is 'on' for — callers who land inside it get asked.
HAWK_WINDOW = 420.0


def hawking_now() -> dict[str, Any] | None:
    """The sale in progress, or None once it has run its course."""
    hawk = _RADIO.get("hawking")
    if not hawk or time.time() - float(hawk.get("at") or 0) > HAWK_WINDOW:
        return None
    return hawk


def hawk_unsold() -> list[dict[str, Any]]:
    """The pile by the desk: what was hawked and did not go."""
    return list(_RADIO.get("hawk_unsold") or [])


async def dj_hawk_round(names: list[str], moods: list[str],
                        price: int = 0) -> list[str]:
    """The pair take pictures off the wall and try to SELL them, on air.

    They describe what they can actually see (the vision model looks), pitch
    it, work the person on the other end at whatever disposition was asked
    for — and that person buys it or refuses it outright. Anything unsold is
    put aside, said out loud, and they get back to work."""
    pieces: list[tuple[str, str]] = []
    for name in [n for n in names if n][:3]:
        got, desc = await describe_gallery_image(name)
        if desc:
            pieces.append((got or name, desc))
    if not pieces:
        # Nothing could be looked at — fall back to the wall's own draw so
        # pressing the thing never does nothing.
        got, desc = await describe_gallery_image()
        if desc:
            pieces.append((got, desc))
    if not pieces:
        return []
    dj = dj_settings()
    ask = price or random.randint(dj["ad_price_low"], dj["ad_price_high"])
    _RADIO["gallery_now"] = {
        "at": time.time(),
        "images": [{"name": n, "desc": d} for n, d in pieces],
    }
    # #1005: and the lines of THIS round take them as each one
    # is written - see gallery_pending_set. Bound to the round
    # that is about them, so the next round's phone call does
    # not inherit the painting.
    try:
        _gp = _RADIO["gallery_now"]["images"]
        gallery_pending_set(
            [str((x or {}).get("name") or "") for x in _gp],
            [str((x or {}).get("desc") or "") for x in _gp])
    except Exception:  # noqa: BLE001
        pass
    _RADIO["hawking"] = {
        "at": time.time(),
        "images": [n for n, _ in pieces],
        "moods": [m for m in moods if m in HAWK_MOODS],
        "price": ask,
    }
    chosen = [m for m in moods if m in HAWK_MOODS]
    if not chosen:
        chosen = random.sample(list(HAWK_MOODS), k=random.choice((1, 2)))
    mood_text = "; ".join(HAWK_MOODS[m] for m in chosen[:4])
    listing = " ".join(
        f"PIECE {i + 1}: \"{desc}\"" for i, (_, desc) in enumerate(pieces))
    seed = await speakbox_quote(most=4, cap=380)
    angle = (
        "THE PAIR ARE SELLING ART, LIVE ON AIR. They have taken "
        f"{len(pieces)} piece(s) off the station wall and they are hawking "
        f"them to whoever is on the line. {listing} "
        "Describe what you are LOOKING AT in your own words — colours, "
        "figures, what it does to you — then SELL it: hard, funny, "
        f"shameless, asking {ask} dollars. "
        "The person on the other end is a real presence in this: they "
        f"answer back, and they are {mood_text}. Work them. They either BUY "
        "it — and you make far too much of that — or they REFUSE it "
        "outright, saying plainly it is not for them, and you take that on "
        "the chin. Push the limit of what a sales pitch can be: strange "
        "comparisons, invented provenance, escalating claims, unique every "
        "time. "
        "ANYTHING THAT DOES NOT SELL you PUT ASIDE out loud — 'right, that "
        "one goes back against the wall' — and you get straight back to "
        "work, which is the radio show."
        + (f" Somewhere in it one of you drops this, word for word, as "
           f"though it explains the art: \"{seed['text']}\"" if seed else ""))
    began = time.time()
    # #977: the brief above says "the person on the other end is a real
    # presence in this: they answer back", and then this call passed no
    # caller_name - so there was no 'C: ...' marker in the format line and
    # no third person in the round. The buyer is drawn and named, the same
    # omission as the call-in road above.
    _buyer = ""
    _buyer_voice = ""
    try:
        _buyer = random.choice(caller_names())
        _buyer_voice = await caller_line_voice(_buyer)
    except Exception:  # noqa: BLE001
        _buyer, _buyer_voice = "", ""
    lines = await dj_banter(None, angle=angle, lines=12,
                            source=(seed or {}).get("file", ""),
                            caller_name=_buyer,
                            caller_voice=_buyer_voice,
                            own_material=True)
    gallery_line_mark([n for n, _ in pieces], began,
                      [d for _, d in pieces])                 # #991
    if lines and seed:
        speakbox_remember(seed)
    # What the round said about each piece decides nothing on its own — the
    # honest record is that it was offered. Anything offered goes on the
    # pile unless a later round sells it, and the pile is what the pair get
    # asked about when the phone next rings (#719).
    # Whole words and whole phrases only: "deal" alone matches "a great deal"
    # and "ideal", and "sold" matches "consoled" — a loose test here would
    # quietly mark everything sold and the pile would never fill.
    sold_words = re.compile(
        r"\b(sold|sold it|i(?:'| wi)?ll take it|it'?s yours|you'?ve got "
        r"(?:a |your )?deal|wrapped (?:it|that) up)\b")
    said = " ".join(lines or []).lower()
    pile = _RADIO.setdefault("hawk_unsold", [])
    went = bool(sold_words.search(said))
    for name, desc in pieces:
        if went:
            continue
        if any(str(p.get("name")) == name for p in pile):
            continue
        pile.append({"name": name, "at": int(time.time()),
                     "price": ask, "desc": desc[:200]})
    del pile[:-24]
    return lines


# #991: the words worth matching on. A description and a line about it
# share their NOUNS, not their glue - "the", "this", "picture", "painting"
# turn up in every gallery line ever written and would make everything
# match everything.
_GALLERY_STOP = {
    "the", "and", "this", "that", "with", "from", "into", "have", "just",
    "like", "what", "when", "where", "there", "here", "they", "them",
    "their", "your", "you", "for", "are", "was", "were", "been", "being",
    "not", "but", "all", "one", "two", "its", "about", "over", "out",
    "off", "some", "any", "who", "how", "why", "than", "then", "picture",
    "painting", "paintings", "image", "images", "look", "looks", "looking",
    "see", "seen", "seeing", "folks", "listen", "right", "something",
    "really", "very", "much", "more", "most", "kind", "sort", "thing",
    "things", "little", "called", "should", "would", "could", "gets",
    "got", "get", "well", "yeah", "okay", "dollars", "caller", "first",
}


def _gallery_words(text: str) -> set[str]:
    try:
        return {w for w in re.findall(r"[a-z]{4,}", str(text or "").lower())
                if w not in _GALLERY_STOP}
    except Exception:  # noqa: BLE001
        return set()


# #1005: THE PICTURES WAIT FOR THEIR LINES.
#
# gallery_line_mark is retroactive - it walks back through the booth log
# and hangs the paintings on rows that are already there. That works for
# a round written and aired in one breath, and measurably does not for
# the road most rounds now take: a round PREPARED during an earlier
# record airs through _banter_air, whose rows land as the audio is
# queued, and the mark can run before some or all of them exist. Measured
# on the live station: a gallery round aired with `selling_now` correctly
# holding up Ernie-Image-Turbo_00121_, seventy-five rows in the booth
# log, and NOT ONE of them carrying a picture.
#
# So the round leaves its pictures standing where the booth can reach
# them, and every line written while they are still up takes the one it
# is about - the same nouns-in-common scoring, applied forward instead of
# backward. Retroactive marking is unchanged and still runs; this only
# catches what it cannot reach.
_GALLERY_PENDING: dict[str, Any] = {}
GALLERY_PENDING_LIFE = 420.0


def gallery_pending_set(names: list[str],
                        descs: list[str] | None = None) -> None:
    """The paintings a round now on air is about, left up for its lines."""
    try:
        keep = [str(n) for n in (names or []) if n][:3]
        if not keep:
            return
        _GALLERY_PENDING.clear()
        _GALLERY_PENDING.update({
            "names": keep,
            "bags": [_gallery_words(d) for d in (descs or [])],
            "at": time.time()})
    except Exception:  # noqa: BLE001
        pass


def gallery_pending_pick(text: str) -> list[str]:
    """Which of the round's paintings this line is about, or [] when no
    round is up. Same rule as the retroactive pass: two shared nouns is a
    match, one is a coincidence in a round where everybody is talking
    about pictures, and a line about none of them keeps the whole strip."""
    try:
        if not _GALLERY_PENDING:
            # #1005: nothing is up. Deliberately NOT falling back to
            # selling_now() here, which was tried and measured wrong: a
            # phone call about a library book aired with a painting
            # hanging beside every line of it, because an ad had sold one
            # a minute earlier and "what is being held up" is a property
            # of the STATION rather than of this round. Pictures are
            # bound to the round that is about them - see the two setters
            # above and the one in _banter_air.
            return []
        if time.time() - float(_GALLERY_PENDING.get("at") or 0) \
                > GALLERY_PENDING_LIFE:
            _GALLERY_PENDING.clear()
            return []
        names = list(_GALLERY_PENDING.get("names") or [])
        bags = list(_GALLERY_PENDING.get("bags") or [])
        if not names:
            return []
        best, score = None, 0
        if len(bags) > 1:
            said = _gallery_words(text or "")
            if said:
                for at, bag in enumerate(bags):
                    if at >= len(names):
                        break
                    hit = len(said & bag)
                    if hit > score:
                        best, score = at, hit
        return [names[best]] if best is not None and score >= 2 else names[:3]
    except Exception:  # noqa: BLE001
        return []


def gallery_line_mark(names: list[str], since: float,
                      descs: list[str] | None = None) -> None:
    """Hang the paintings on the lines that discuss them (#702).

    #991: ON THE LINE THAT IS ACTUALLY ABOUT IT.

    This gave EVERY line of the round ALL THREE of the round's pictures -
    its own docstring said as much - and the booth holds up the first of
    them. So the pair could be describing two tabby cats in a hallway
    while the panel showed a portrait of a woman, which is precisely what
    the operator photographed: "the image isn't the image that's being
    presented."

    The round is written as PAINTING 1 / 2 / 3 out of the vision model's
    own descriptions and the pair go through them one at a time, so a line
    and the picture it is about share their nouns - the cats, the hallway,
    the fur - and no other line in the round does. Each line is scored
    against each description and keeps the one it matches best. A line
    that is about none of them in particular - a price, an aside, a joke -
    keeps the whole strip, which is what every line had before.

    Called without descriptions this is exactly the old behaviour, so the
    single-picture road is untouched."""
    if not names:
        return
    # #1005: and leave them up for the lines that have not been written
    # into the log yet - see gallery_pending_set.
    gallery_pending_set(names, descs)
    bags = [_gallery_words(d) for d in (descs or [])]
    marked = 0
    for entry in reversed(_RADIO.get("chat") or []):
        if float(entry.get("ts") or 0) < since:
            break
        if entry.get("who") not in ("dj", "cohost", "third", "caller"):
            continue
        best, score = None, 0
        if len(bags) > 1:
            said = _gallery_words(entry.get("text") or "")
            if said:
                for at, bag in enumerate(bags):
                    if at >= len(names):
                        break
                    hit = len(said & bag)
                    if hit > score:
                        best, score = at, hit
        # Two shared nouns is a real match; one is a coincidence in a
        # round where everybody is talking about pictures.
        entry["images"] = ([names[best]] if best is not None and score >= 2
                           else names[:3])
        marked += 1
    # #1005: say how many the backward pass could actually reach. On the
    # prepared road that number is routinely ZERO - the rows had not been
    # written yet - and until it was printed nobody could tell the
    # difference between "hung on every line" and "hung on nothing".
    try:
        pipeline_log("gallery", f"{len(names)} painting(s) hung on {marked} "
                     "line(s) already in the booth"
                     + ("; the rest of the round takes them as it is "
                        "written (#1005)" if marked < 3 else " (#991)"))
    except Exception:  # noqa: BLE001
        pass


def banter_pictures(limit: int = 6) -> str:
    """The imagery in the building: what he had the box generate — with his
    own words for it — and a random walk through the wider gallery on the
    render machine, myriad and offerable (#261)."""
    lines: list[str] = []
    try:
        # ONE random ledger entry at most, and only sometimes (#419, #474):
        # walking the ledger put the same fresh commission (one Dracula
        # session) in every prompt and the pair talked about nothing else.
        # The wide gallery is where the variety is, so it leads now.
        gens = [g for g in read_generations(200)
                if len(" ".join(str(g.get("request") or g.get("tags")
                                    or "").split())) > 8]
        random.shuffle(gens)
        if gens and random.random() < 0.4:
            subject = " ".join(str(
                gens[0].get("request") or gens[0].get("tags") or "").split())
            lines.append(f"- he had us generate: {subject[:170]}")
    except Exception:
        pass
    # The rest — the bulk — is a fresh random walk through the whole 1300-
    # image wall, so a different set of pictures comes up every round.
    for stem in gallery_sample(limit - len(lines)):
        lines.append(f"- in the station gallery: a picture called {stem}")
    return "\n".join(lines[:limit])


# #889: the accented letters that turn up in perfectly ordinary station
# copy - cafe, Bjork, Motorhead, Motley Crue, Sigur Ros, Beyonce. English
# borrows these; it does not borrow the rest of the Latin alphabet's
# extensions, and it does not use Greek, Cyrillic or anything east of them.
ENGLISH_ACCENTS = set(
    "\u00e1\u00e0\u00e2\u00e4\u00e3\u00e5\u00e9\u00e8\u00ea\u00eb"
    "\u00ed\u00ec\u00ee\u00ef\u00f3\u00f2\u00f4\u00f6\u00f5\u00fa"
    "\u00f9\u00fb\u00fc\u00e7\u00f1\u00f8\u00e6\u0153\u00df\u00ff"
    "\u00c1\u00c0\u00c2\u00c4\u00c3\u00c5\u00c9\u00c8\u00ca\u00cb"
    "\u00cd\u00cc\u00ce\u00cf\u00d3\u00d2\u00d4\u00d6\u00d5\u00da"
    "\u00d9\u00db\u00dc\u00c7\u00d1\u00d8\u00c6\u0152")


def looks_english(text: str) -> bool:
    """#792: the station broadcasts in ENGLISH. A Portuguese lyric swath
    rode a whole turn on air verbatim, so lines are checked: heavy
    diacritics, foreign function words outweighing English ones, or a
    long line with almost no English function words at all reads as
    foreign. Short lines pass — interjections and names carry no signal
    worth blocking on."""
    t = str(text or "").replace("\u2019", "'").replace("\u2018", "'")
    words = [w.lower() for w in re.findall(r"[A-Za-z\u00c0-\u00ff']+", t)]
    # #889: THE SHORT-LINE HOLE. "Tak nudzi sie depresji dziura." went out
    # in the HOST's voice, on air, because five words fell under this floor
    # of eight and the line was therefore never judged at all - the gate
    # returned True without looking. Short lines are judged now, on the
    # evidence a short line can actually carry.
    letters = [c for c in t if c.isalpha()]
    # Letters English does not use. A stray one is a borrowed name -
    # Tokyo, Bjork, a romanised title - and proves nothing.
    # A RUN of them is another script.
    _exotic = sum(1 for c in letters
                  if ord(c) > 127 and c not in ENGLISH_ACCENTS)
    if len(words) < 4:
        # Three words or fewer carry no grammar to judge, so the only
        # evidence left is the alphabet: "Skip", "1247" and "Bjork" pass,
        # "Dzien dobry" written with its own letters does not.
        return not _exotic
    _short = len(words) < 8
    if letters and not _short:
        _dia = sum(c in "\u00e1\u00e0\u00e2\u00e3\u00e4\u00e5\u00e6"
                        "\u00e7\u00e8\u00e9\u00ea\u00eb\u00ec\u00ed"
                        "\u00ee\u00ef\u00f1\u00f2\u00f3\u00f4\u00f5"
                        "\u00f6\u00f8\u00f9\u00fa\u00fb\u00fc\u00fd"
                        "\u00ff\u00c1\u00c0\u00c2\u00c3\u00c4\u00c5"
                        "\u00c6\u00c7\u00c8\u00c9\u00ca\u00cb\u00cc"
                        "\u00cd\u00ce\u00cf\u00d1\u00d2\u00d3\u00d4"
                        "\u00d5\u00d6\u00d8\u00d9\u00da\u00db\u00dc"
                        "\u00dd\u00df" for c in letters)
        if _dia / len(letters) > 0.04:
            return False
    _en = {"the", "a", "an", "and", "or", "but", "of", "to", "in", "on",
           "at", "is", "are", "was", "were", "be", "been", "it", "that",
           "this", "i", "you", "he", "she", "we", "they", "my", "your",
           "his", "her", "our", "their", "not", "no", "do", "did", "does",
           "have", "has", "had", "with", "for", "as", "so", "if", "what",
           "who", "how", "why", "when", "where", "there", "here", "just",
           "like", "up", "down", "out", "all", "one", "me", "him", "them",
           "us", "its", "get", "got", "can", "will", "would", "about",
           "into", "than", "then", "now", "some", "don't", "it's", "i'm",
           "you're", "ain't", "gonna", "gotta", "y'all", "man", "know"}
    _foreign = {"que", "n\u00e3o", "nao", "\u00e9", "eu", "voc\u00ea",
                "voce", "c\u00eas", "el", "la", "los", "las", "les",
                "une", "un", "una", "je", "tu", "il", "elle", "nous",
                "vous", "der", "die", "das", "und", "nicht", "ist",
                "ich", "du", "os", "\u00e0s", "de", "em", "com", "seu",
                "sua", "meu", "minha", "por", "para", "pero", "m\u00e1s",
                "mais", "est\u00e1", "esta", "yo", "mi", "t\u00fa",
                # #871: the everyday glue that carried the Spanish
                # straight past the old list.
                "y", "o", "si", "en", "como", "del", "al", "se", "lo",
                "ya", "muy", "cuando", "donde", "porque", "todo",
                "nada", "bien", "hasta", "sobre", "entre", "cada",
                "soy", "eres", "somos", "estoy", "est\u00e1s", "tiene",
                "tengo", "hacer", "puede", "vamos", "cueste", "canto",
                "aqu\u00ed", "all\u00ed", "tambi\u00e9n", "siempre",
                "nunca", "ahora", "despu\u00e9s", "antes", "gracias",
                "se\u00f1or", "d\u00eda", "noche", "vida", "gente",
                "et", "ou", "mais", "avec", "sans", "pour", "dans",
                "sur", "sont", "\u00eatre", "avoir", "cette", "ces",
                "moi", "toi", "lui", "leur", "ne", "pas", "plus",
                "aber", "oder", "auch", "noch", "sehr", "kein",
                "mit", "auf", "f\u00fcr", "sich", "wir", "sie", "es",
                # #889: the glue of the language that actually went
                # out - POLISH - plus Italian, neither of which this
                # list held a single word of. Only words English does
                # not also own, so nothing here can convict an English
                # line ("ale", "dove" and "come" are deliberately
                # absent).
                "nie", "jest", "jestem", "tego", "tym", "czy",
                "tylko", "bardzo", "jeszcze", "wszystko", "dlaczego",
                "dobrze", "teraz", "gdzie", "kiedy", "mnie", "ciebie",
                "nasz", "tutaj", "dzisiaj", "wiem", "moje", "twoje",
                "che", "non", "sono", "questo", "questa", "della",
                "delle", "anche", "molto", "perche", "sempre",
                "niente", "tutto", "essere", "quando", "adesso",
                "cosa"}
    en = sum(1 for w in words if w in _en)
    # Contractions and short English imperatives supply positive evidence.
    # "yo" and "die" are shared words, not sufficient foreign-language proof
    # in "Yo, what's good?" or "Hero fail, fall, die trying."
    en += sum(1 for w in words if re.fullmatch(r"[a-z]+'(?:s|re|ve|ll|d|m)", w)
              and w.split("'", 1)[0] in _en)
    short_english = sum(w in {"look", "good", "bro", "brodie", "dog", "hero",
                             "fail", "fall", "trying"} for w in words) if _short else 0
    shared_supported = en > 0 or short_english >= 2
    fr = sum(1 for w in words if w in _foreign
             and not (shared_supported and w in {"yo", "die"}))
    en += short_english if short_english >= 2 else 0
    # #889: an English sentence of four words or more essentially always
    # carries one of the function words above. NONE of them, plus a letter
    # English does not use, is another language however short the line is -
    # which is precisely the case the eight-word floor used to wave past.
    if en == 0 and _exotic:
        return False
    # A run of letters English does not use, with barely any English
    # around them, is another script outright - at any length. The floor
    # of two is what catches Polish, which spends its diacritics sparingly
    # ("Nie ma nic wazniejszego niz to co robimy tutaj" carries exactly
    # two); the length term keeps a long English line from tripping on a
    # couple of borrowed names.
    if _exotic >= max(2, len(letters) // 16) and en <= 1:
        return False
    if _short:
        return not ((fr >= 1 and en == 0) or (fr >= 2 and fr > en))
    if fr >= 3 and fr > en:
        return False
    # #871: two foreign markers and not one English word is not a
    # borrowed phrase, it is another language.
    if fr >= 2 and en == 0:
        return False
    # #871: THE HOLE. This used to end `or len(words) < 14`, so any
    # sentence under fourteen words passed whatever it contained —
    # which is exactly the length the Spanish lines came in at. An
    # English sentence of eight or more words essentially always
    # carries a function word; zero of them at that length is not
    # English, at any length.
    # ...but a bare LIST of English nouns carries no function words
    # either ("Hard Ops, Boxcutter, N Solve, vidBox, image Board") and
    # is perfectly good station copy. What separates it from another
    # language is that it has no foreign glue in it.
    if en == 0 and fr >= 1:
        return False
    # #936: NOTHING FOREIGN IN IT AT ALL — no letter English does not
    # use, and no foreign function word anywhere — so there is nothing
    # to convict on, at any length.
    #
    # The rule below used to end the function, and it reads "over
    # fourteen words with no function word is not English". That is
    # treating the ABSENCE of English as evidence of another language,
    # and it is not: it is the absence of evidence. Wordplay does it,
    # dense rap does it, a long list of titles does it. It refused this,
    # in the host's own voice, 487 times in one day:
    #
    #   "Empty today, rarely entertaining good rhymes. Enterprise time,
    #    roll economically growing. Extroverted guy round every thick
    #    red ebony goon, rigid."
    #
    # An acrostic — every word picked for its first letter, so not one
    # of "the, a, and, of, to, is" survives. This station's speakbox is
    # lyrics and wordplay, so the door was shut on precisely the
    # material the show is made of.
    #
    # Every branch above convicts on something POSITIVE and none of
    # them is touched. This one asks for evidence before convicting.
    if not _exotic and fr == 0:
        return True
    return en / len(words) >= 0.05 or len(words) < 14


def unrepeated(pool: list[str], key: str, keep: int = 8) -> str:
    """Draw from a pool without landing on what has just been used.

    Plain random.choice on eight angles repeats one inside three rounds often
    enough to be heard, and a show that tells the same joke twice in ten
    minutes sounds broken. The last few draws under each key are held back
    until the pool runs short."""
    if not pool:
        return ""
    # #1176: LEAVE TWO. Clamping to len(pool) - 1 lets the ring hold every
    # item but one, and `random.choice` on a list of one is not a choice -
    # it is a fixed cycle whose order was frozen by the first few draws.
    # Measured across the call sites, a dozen small pools were in that
    # state, most of them verbatim spoken copy. Two candidates costs
    # nothing: a pool of three still never repeats back to back.
    keep = min(keep, max(0, len(pool) - 2))
    recent = _RADIO.setdefault("recent", {}).setdefault(key, [])
    pick = random.choice([p for p in pool if p not in recent] or pool)
    recent.append(pick)
    if keep:
        del recent[:-keep]
    else:
        recent.clear()                  # a one-item pool has no history
    return pick


# --- The speakbox: other people's words -------------------------------------
# Markdown dropped in data/speakbox — stand-up transcripts, interviews,
# whatever he wants in their mouths. A line is lifted out of a random one and
# handed to one of the pair to say as their own thought. The chat entry
# remembers which document it came from so he can open it and rewrite it.

SPEAKBOX_DIR = data_path("speakbox")

# --- Minds (#627): a mind is a NAMED FOLDER plus its own shelf ------------
# A second folder of documents is not a second pile — it is a second head.
# Football facts and personal stories should not share a used-lines ring, a
# gem cache or a vector index with the studio transcripts, or one brain's
# reading bleeds into the other. So every piece of shelf state is resolved
# per mind, and the built-in "main" keeps the original paths untouched so
# nothing has to migrate.
MINDS_DIR = data_path("minds")


def speakbox_minds() -> list[dict[str, Any]]:
    rows = [{"id": "main", "name": "The studio", "dir": str(SPEAKBOX_DIR),
             "blurb": "", "builtin": True}]
    seen = {"main"}
    try:
        for row in (dj_settings().get("speakbox_minds") or []):
            rid = re.sub(r"[^a-z0-9_-]", "", str(row.get("id") or "").lower())
            # #868: one row per id, now that the list is allowed to be long.
            # The settings file is hand-editable and _mind_ensure appends, so
            # a duplicate is two heads sharing one folder — mind_row() hands
            # back whichever came first while both write the same shelf.
            if not rid or rid in seen:
                continue
            seen.add(rid)
            rows.append({
                "id": rid,
                "name": str(row.get("name") or rid)[:60],
                "dir": str(row.get("dir") or (MINDS_DIR / rid / "docs")),
                "blurb": str(row.get("blurb") or "")[:400],
                "weights": row.get("weights") or {},
                "builtin": False,
            })
    except Exception:
        pass
    return rows


def mind_id(rid: str = "") -> str:
    """The mind in play: an explicit one, else the live switch, else the
    saved default. An unknown id falls back to the studio rather than
    silently reading an empty folder."""
    want = (str(rid or "").strip()
            or str(_RADIO.get("mind") or "")
            or str(dj_settings().get("speakbox_mind") or "") or "main")
    return want if any(m["id"] == want for m in speakbox_minds()) else "main"


def mind_row(rid: str = "") -> dict[str, Any]:
    want = mind_id(rid)
    for row in speakbox_minds():
        if row["id"] == want:
            return row
    return {"id": "main", "name": "The studio", "dir": str(SPEAKBOX_DIR),
            "blurb": "", "builtin": True}


def speakbox_dir(rid: str = "") -> Path:
    # Looked up at CALL time, so the self-check can still swap the global.
    row = mind_row(rid)
    return SPEAKBOX_DIR if row["id"] == "main" else Path(row["dir"])


def mind_state(rid: str, leaf: str) -> Path:
    """Where this mind keeps its shelf. The studio keeps the original files
    so existing data needs no migration."""
    row = mind_row(rid)
    if row["id"] == "main":
        return {"heard": SPEAKBOX_HEARD, "gems": SPEAKBOX_GEMS,
                "vectors": SPEAKBOX_VECTORS}[leaf]
    return MINDS_DIR / row["id"] / f"{leaf}.json"


def mind_weights(rid: str = "") -> dict[str, int]:
    row = mind_row(rid)
    if row["id"] == "main":
        return dj_settings()["speakbox_weights"]
    return {str(k): int(v) for k, v in (row.get("weights") or {}).items()}


def mind_dir_ok(raw: str, rid: str) -> Path:
    """A mind's folder has to live under /app/data — that is the only path
    mounted into this container, so anything else is a folder the DJs would
    never be able to read."""
    text = str(raw or "").strip()
    base = DATA_DIR
    path = Path(text).expanduser() if text else (MINDS_DIR / rid / "docs")
    if not path.is_absolute():
        path = base / text
    path = path.resolve()
    if base.resolve() not in path.parents and path != base.resolve():
        raise ValueError(
            "A mind's folder has to sit under data/ — that is what is "
            "mounted into the container. Try a plain name like "
            "'football' and it lands in data/football.")
    path.mkdir(parents=True, exist_ok=True)
    return path


# Transcripts are timestamped per paragraph — "[0:47] I can still feel …" —
# and a timestamp read aloud is not a joke.
_SPEAKBOX_STAMP = re.compile(r"^\s*[\[(]?\d{1,3}:\d{2}(?::\d{2})?[\])]?\s*")


def speakbox_all(rid: str = "") -> list[Path]:
    """Every document in the folder, in play or not."""
    try:
        return sorted(p for p in speakbox_dir(rid).glob("*.md")
                      if p.is_file())
    except OSError:
        return []


def speakbox_files(rid: str = "") -> list[Path]:
    """Every document they are allowed to lift from.

    The folder is read each time, and what the settings hold is a weight per
    document rather than a list of the ones switched on — so anything dropped
    in the folder is in play on the next round without anyone going to tick a
    box for it, which is the whole point of a drop folder (#221). Held the
    other way round, a new file arrived excluded and there was no way to see
    it, let alone tick it. A weight of zero is off."""
    weights = mind_weights(rid)
    return [p for p in speakbox_all(rid)
            if speakbox_weight(p.name, weights, rid) > 0]


# #1193: how sharply a well-mined document is pushed down the list.
# draws-per-kilobyte divided by this is the penalty, so a document read
# once per kilobyte keeps most of its weight and one read ninety times
# per kilobyte keeps almost none.
HUNGER_SOFTEN = float(os.getenv("PINE_SPEAKBOX_HUNGER", "3.0"))
_HUNGER_CACHE: dict[str, Any] = {"at": 0.0, "rid": None, "uses": {}}
HUNGER_TTL = 120.0


def speakbox_uses(rid: str = "") -> dict[str, int]:
    """#1193: draws per document, off the said-memory. Cached two minutes -
    this is asked once per document per draw and the ring is long."""
    try:
        now = time.time()
        if (_HUNGER_CACHE["rid"] == rid
                and now - float(_HUNGER_CACHE["at"] or 0) <= HUNGER_TTL):
            return dict(_HUNGER_CACHE["uses"] or {})
        tally: dict[str, int] = {}
        for row in speakbox_heard(rid):
            got = str((row or {}).get("file") or "")
            if got:
                tally[got] = tally.get(got, 0) + int(row.get("used") or 1)
        _HUNGER_CACHE.update({"at": now, "rid": rid, "uses": tally})
        return dict(tally)
    except Exception:  # noqa: BLE001
        return dict(_HUNGER_CACHE.get("uses") or {})


def speakbox_hunger(name: str, rid: str = "",
                    uses: dict[str, int] | None = None) -> float:
    """#1193: 1.0 for a document nobody has opened, falling as it is mined.

    Relative to SIZE, because a big document has more to give before it
    starts repeating itself. Measured on the live shelf: ias2.md at 10 KB
    had been drawn 916 times (87 per KB) while com8.md at 585 KB had been
    drawn 470 (0.8 per KB), and 93 of 322 documents had never been opened
    at all. Never returns zero - a well-read document still comes round,
    it just waits behind the ones that have never been heard."""
    try:
        drawn = int((uses if uses is not None
                     else speakbox_uses(rid)).get(name) or 0)
        if drawn <= 0:
            return 1.0
        size_kb = max(1.0, (speakbox_dir(rid) / name).stat().st_size / 1024.0)
        per_kb = drawn / size_kb
        return 1.0 / (1.0 + per_kb / max(0.1, HUNGER_SOFTEN))
    except Exception:  # noqa: BLE001
        return 1.0


def speakbox_weight(name: str, weights: dict[str, int] | None = None,
                    rid: str = "", uses: dict[str, int] | None = None) -> int:
    """How hard this document is leaned on. Unnamed means ordinary. A
    document dropped in recently gets a propensity boost (#478) — the pair
    have an appetite for fresh material — decaying over about a week back to
    its base weight.

    #1193: ...and a document already mined goes DOWN the list, in
    proportion to how hard it has been mined for its size. There was no
    usage term here at all, so a file read a thousand times weighed the
    same as one never opened, and 93 of 322 documents had never been
    heard while a 10 KB file was drawn 916 times. See speakbox_hunger."""
    if weights is None:
        weights = mind_weights(rid)
    value = weights.get(name)
    base = 50 if value is None else max(0, min(100, int(value)))
    try:
        age = time.time() - (speakbox_dir(rid) / name).stat().st_mtime
        if age < 7 * 86400:
            # +100% at zero age, fading linearly to +0% at a week old.
            base = int(base * (1.0 + max(0.0, 1.0 - age / (7 * 86400))))
    except OSError:
        pass
    # A weight of ZERO is the operator switching a document off, and
    # speakbox_files() filters on `> 0` - so hunger must never lift one
    # off the floor. It only ever pushes a document DOWN.
    if base <= 0:
        return 0
    # Otherwise the floor is 1: pushed to the back of the queue, never
    # struck off it, and random.choices refuses an all-zero weighting.
    return max(1, int(round(base * speakbox_hunger(name, rid, uses))))


def _speakbox_runs(said: str, words: int = 16) -> list[str]:
    """A machine transcript has no full stops, so the whole forty seconds
    arrives as one run. Cut it on word boundaries instead.
    ponytail: word count, not meaning — a line may start mid-thought, which
    is what the source gives us. Sentence-split it properly if that grates."""
    parts = said.split()
    return [" ".join(parts[at:at + words])
            for at in range(0, len(parts), words)
            if len(parts) - at >= 6]


def _looks_like_verse(para: str) -> bool:
    """#1037: is this paragraph written in LINES rather than sentences?

    Narrow on purpose. Prose wrapped at eighty columns has short lines
    too, but it punctuates: its lines end in commas and full stops
    because they are pieces of sentences. Verse does not - a bar ends
    where the bar ends. So: several lines, most of them short, and most
    of them ending on a bare word.

    Getting this wrong in the safe direction costs nothing: a verse
    treated as prose is what happens today."""
    try:
        rows = [r.strip() for r in str(para or "").split("\n")]
        rows = [r for r in rows if r]
        if len(rows) < 3:
            return False
        # #1037: LENGTH IS THE DISCRIMINATOR, not shortness alone.
        # Prose wrapped at eighty columns also has short unpunctuated
        # lines - measured, a three-line wrapped paragraph passed the
        # first version of this test. What separates them is that wrapped
        # prose runs NEAR THE WRAP WIDTH on every line by construction,
        # while a verse line ends where the bar ends and varies wildly.
        # #1037: VARIANCE IS THE DISCRIMINATOR.
        #
        # Not shortness: prose wrapped at seventy columns has short lines
        # too, and the first version of this test called it verse. Not
        # punctuation either: "No corners. / No shadows. / Just white
        # swallowing white." is the lyric #868 was written about, and
        # every line of it ends in a full stop.
        #
        # What no wrapped prose can fake is IRREGULARITY. A wrapper fills
        # to the same width every time by construction, so its lines
        # cluster hard around the margin; a verse line ends where the bar
        # ends and scatters. Measured on real samples: wrapped prose
        # 0.02-0.05, transcripts 0.04, verse 0.24-0.39.
        widths = [len(r) for r in rows]
        mean = sum(widths) / len(widths)
        if mean > 70 or mean < 4:
            return False
        if max(widths) > 200:
            return False
        spread = (sum((w - mean) ** 2 for w in widths) / len(widths)) ** 0.5
        return (spread / mean) >= 0.15
    except Exception:  # noqa: BLE001
        return False


def _verse_lines(para: str, most: int = 200) -> list[str]:
    """#1037: the lines of a verse, kept whole and in order.

    Very short lines are carried onto the next one - "Uh." on its own is
    not worth saying and not worth embedding - but a carry NEVER crosses
    more than one join, so a couplet stays a couplet and the rhyme still
    lands at the end of what is stored."""
    out: list[str] = []
    carry = ""
    for row in str(para or "").split("\n"):
        said = spoken_text(row).strip(" -*>\"'")
        if not said:
            continue
        if carry:
            said = carry + " / " + said
            carry = ""
        if len(said) < 24:
            carry = said
            continue
        out.append(said[:most])
    if carry:
        if out:
            out[-1] = (out[-1] + " / " + carry)[:most]
        elif len(carry) >= 12:
            out.append(carry)
    return out


def speakbox_lines(text: str) -> list[str]:
    """Every sayable line in a document.

    Short enough to work into a conversation, long enough to be worth saying.
    Headings, images and the transcript's own timestamps are not dialogue."""
    out: list[str] = []
    for para in str(text or "").split("\n\n"):
        # #1037: VERSE KEEPS ITS LINES. The flatten below is right for
        # prose and fatal for lyrics - see _looks_like_verse. A bar ends
        # where the bar ends, and that is exactly where the rhyme is.
        if _looks_like_verse(para):
            got = _verse_lines(_SPEAKBOX_STAMP.sub("", para))
            if got:
                out.extend(got)
                continue
        flat = _SPEAKBOX_STAMP.sub("", " ".join(para.split()))
        if not flat or flat.startswith(("#", "![", "|", "```")):
            continue
        # #868: a sentence shorter than thirty characters used to be thrown
        # away, and a LYRIC is made of nothing else — "No corners." "No
        # shadows." "Just white swallowing white." Measured across the Allen
        # Interface documents, 23.1% of the sayable text never reached the
        # vector store and the worst song lost 54% of itself, which is why
        # the crystal read as two sentences a song. Short sentences now run
        # together until the carry is worth saying: nothing is discarded, and
        # every line handed out is still a whole thought.
        carry = ""
        began = len(out)
        for sentence in re.split(r"(?<=[.!?])\s+", flat):
            # spoken_text is what takes out [Music], [ __ ] and the rest of
            # the transcriber's own annotations.
            said = spoken_text(sentence).strip(" -*>\"'")
            if not said:
                continue
            if len(said) > 200:
                if carry:
                    out.append(carry)
                    carry = ""
                out.extend(_speakbox_runs(said))
                continue
            carry = f"{carry} {said}" if carry else said
            if len(carry) >= 30:
                if len(carry) <= 200:
                    out.append(carry)
                else:
                    out.extend(_speakbox_runs(carry))
                carry = ""
        if carry:
            # The tail of a paragraph, still short. It belongs on the end of
            # the line before it rather than in the bin — but only a line out
            # of the SAME paragraph, so a stray "Yeah." cannot glue itself to
            # the end of the stanza above.
            if len(out) > began and len(out[-1]) + len(carry) + 1 <= 200:
                out[-1] = f"{out[-1]} {carry}"
            elif " " in carry:
                out.append(carry)
    return out


# What they have already said out of the documents. Kept on disk so the show
# has a memory: a line lands once as a new thought and comes back later as
# something the pair have between them.
SPEAKBOX_HEARD = data_path("speakbox_heard.json")
SPEAKBOX_HEARD_MAX = 12000   # #824: ~30h at measured churn
_SPEAKBOX_LOCK = RLock()


# --- THE CHUNK LEDGER (#1042) ----------------------------------------
# One record of every passage either shelf has handed out: what it was,
# where it came from, which road asked for it, how often it has been
# used, and what the cast made of it. It is the cooldown AND it is the
# window on the cooldown - the operator asked to see what is resting,
# how long is left, how much it has been used and how it was answered,
# and all four of those are the same four facts.
CHUNK_LEDGER_PATH = data_path("chunk_ledger.json")
CHUNK_LEDGER_MAX = 4000
_CHUNK_LOCK = RLock()
_CHUNK_LEDGER: dict[str, dict[str, Any]] = {}
_CHUNK_READ = [False]


def chunk_cool_seconds() -> float:
    """How long a chunk rests before it may be drawn again."""
    try:
        return max(0.0, float(dj_settings().get("chunk_cool_seconds") or 0))
    except Exception:  # noqa: BLE001
        return 3600.0


def chunk_ledger_key(text: str) -> str:
    """The words, stripped of the punctuation that drifts between one
    telling and the next. Deliberately the same shape as _bin_key so a
    chunk and the line it became can be reasoned about together.

    #1043: NOT `chunk_key`. That name was already taken, by a
    two-argument sha1 defined further down the file - so the ledger's
    calls landed on it and raised, which took out both draws."""
    flat = " ".join(re.sub(r"[^\w\s]", " ",
                           str(text or "").lower()).split())
    return flat[:400]


def _chunk_all() -> dict[str, dict[str, Any]]:
    """The ledger, read from disk once and held."""
    if not _CHUNK_READ[0]:
        with _CHUNK_LOCK:
            if not _CHUNK_READ[0]:
                try:
                    rows = json.loads(CHUNK_LEDGER_PATH.read_text())
                    if isinstance(rows, list):
                        for row in rows:
                            k = str((row or {}).get("key") or "")
                            if k:
                                _CHUNK_LEDGER[k] = row
                except Exception:  # noqa: BLE001
                    pass
                _CHUNK_READ[0] = True
    return _CHUNK_LEDGER


_CHUNK_DIRTY = [0.0]      # when a save was last ASKED for; 0 = clean
_CHUNK_FLUSHER = [False]  # one flusher thread, ever


def _chunk_save() -> None:
    """#1149, second pass: a draw only ASKS for a save; one flusher does it.

    The first pass moved the disk write off the loop and left the sort,
    the trim and a fresh thread PER DRAW on it - and chunk_serve calls
    this on EVERY draw, dozens back to back in a prep round, so the
    hunter caught the very same frame again (the trim's `v not in rows`
    was also a deep-equality scan over 4000 dicts). Now the hot path is
    two assignments; a single daemon flusher wakes every few seconds,
    coalesces the burst, and does the sort, an O(n) key-set trim, the
    serialise and the write on ITS clock, holding the lock only for the
    copy. The ledger is a cooldown record - losing the last three
    seconds of counters at a crash is nothing; freezing every remote
    listener's polls per draw was the show."""
    _CHUNK_DIRTY[0] = time.time()
    with _CHUNK_LOCK:
        if _CHUNK_FLUSHER[0]:
            return
        _CHUNK_FLUSHER[0] = True
    Thread(target=_chunk_flush_worker, daemon=True).start()


def _chunk_flush_worker() -> None:
    try:
        while _CHUNK_DIRTY[0]:
            _CHUNK_DIRTY[0] = 0.0
            time.sleep(3.0)         # gather the burst into one write
            with _CHUNK_LOCK:
                rows = sorted(_CHUNK_LEDGER.values(),
                              key=lambda r: -float(r.get("last") or 0))
                del rows[CHUNK_LEDGER_MAX:]
                keep = {str(r.get("key") or "") for r in rows}
                for gone in [k for k in _CHUNK_LEDGER if k not in keep]:
                    _CHUNK_LEDGER.pop(gone, None)
                snapshot = [dict(r) for r in rows]
            try:
                CHUNK_LEDGER_PATH.parent.mkdir(parents=True, exist_ok=True)
                tmp = CHUNK_LEDGER_PATH.with_suffix(".tmp")
                tmp.write_text(json.dumps(snapshot, indent=1))
                tmp.replace(CHUNK_LEDGER_PATH)
            except Exception:  # noqa: BLE001
                pass            # a forgetful shelf still serves
    finally:
        with _CHUNK_LOCK:
            _CHUNK_FLUSHER[0] = False
        if _CHUNK_DIRTY[0]:
            _chunk_save()       # a request raced the shutdown - respawn


def chunk_liked(text: str) -> bool:
    """#1072: has the operator marked this material as good?"""
    try:
        return bool((_chunk_all().get(chunk_ledger_key(text))
                     or {}).get("liked"))
    except Exception:  # noqa: BLE001
        return False


def chunk_cooling(text: str) -> float:
    """Seconds left on this chunk's rest. Zero means it is free, and a
    chunk nobody has ever served is free by definition - which is what
    makes "things they never said" the front of the queue."""
    try:
        cool = chunk_cool_seconds()
        if cool <= 0:
            return 0.0
        row = _chunk_all().get(chunk_ledger_key(text))
        if not row:
            return 0.0
        # #1072: a favourite does not rest. "Rest this so we hear
        # something else" is the opposite of what a like means.
        if row.get("liked"):
            return 0.0
        left = cool - (time.time() - float(row.get("last") or 0))
        return max(0.0, left)
    except Exception:  # noqa: BLE001
        return 0.0


def chunk_serve(shelf: str, text: str, file: str = "", mind: str = "",
                road: str = "", crystal: str = "") -> str:
    """Stamp a chunk on its way out and return its key."""
    # #1043: EVERYTHING inside the try, key included. This line used to
    # sit above it, so a fault in the bookkeeping propagated into the
    # caller - and both callers are draws that then returned nothing.
    # The ledger is a record of the show; it is never a reason the show
    # does not happen.
    key = ""
    try:
        key = chunk_ledger_key(text)
        if not key:
            return ""
        with _CHUNK_LOCK:
            rows = _chunk_all()
            row = rows.get(key) or {
                "key": key, "shelf": str(shelf or ""),
                "text": str(text or "")[:600],
                "file": str(file or ""), "mind": str(mind or ""),
                "crystal": str(crystal or ""),
                "first": time.time(), "used": 0, "roads": [],
                "answers": [],
            }
            row["used"] = int(row.get("used") or 0) + 1
            row["last"] = time.time()
            row["shelf"] = str(shelf or row.get("shelf") or "")
            if file:
                row["file"] = str(file)
            if crystal:
                row["crystal"] = str(crystal)
            if road:
                roads = [r for r in (row.get("roads") or []) if r != road]
                roads.insert(0, str(road))
                row["roads"] = roads[:6]
            rows[key] = row
            _chunk_save()
    except Exception:  # noqa: BLE001
        pass
    return key


def chunk_answer(text: str, said: str, road: str = "") -> None:
    """What the cast MADE of this chunk.

    The operator asked to see "how it was responded to", and the honest
    answer is the line that actually came back - not a score, not a
    verdict, the words. Kept newest-first, a handful deep, so one
    passage shows its whole history of being answered differently."""
    try:
        key = chunk_ledger_key(text)
        got = " ".join(str(said or "").split())[:400]
        if not key or len(got) < 8:
            return
        with _CHUNK_LOCK:
            row = _chunk_all().get(key)
            if not row:
                return
            answers = [a for a in (row.get("answers") or [])
                       if str((a or {}).get("said") or "") != got]
            answers.insert(0, {"at": time.time(), "said": got,
                               "road": str(road or "")})
            row["answers"] = answers[:5]
            _chunk_save()
    except Exception:  # noqa: BLE001
        pass


def chunk_rank(items: list[Any], text_of: Any) -> list[Any]:
    """Reorder so the freshest material leads.

    Never served first - "everyone saying things they never said" - then
    whatever has been resting longest. Ties keep their incoming (random)
    order, so this SORTS the randomness rather than replacing it."""
    try:
        # #1072: favourites first, then never-served, then coldest. The
        # operator marking something good is the strongest signal the
        # station has about what to reach for, and it should outrank
        # "we have not used this one yet".
        return sorted(items, key=lambda it: (
            0 if chunk_liked(text_of(it)) else 1,
            chunk_cooling(text_of(it))))
    except Exception:  # noqa: BLE001
        return list(items)


def chunk_rows(most: int = 200, shelf: str = "",
               cooling_only: bool = False) -> list[dict[str, Any]]:
    """The ledger for the panel: what is resting, how long is left, how
    often it has been used, and what came back."""
    out: list[dict[str, Any]] = []
    try:
        cool = chunk_cool_seconds()
        now = time.time()
        for row in _chunk_all().values():
            if shelf and str(row.get("shelf") or "") != shelf:
                continue
            left = max(0.0, cool - (now - float(row.get("last") or 0)))
            if cooling_only and left <= 0:
                continue
            out.append({
                "key": str(row.get("key") or "")[:120],
                "shelf": str(row.get("shelf") or ""),
                "crystal": str(row.get("crystal") or ""),
                "file": str(row.get("file") or ""),
                "mind": str(row.get("mind") or ""),
                "text": str(row.get("text") or "")[:600],
                "used": int(row.get("used") or 0),
                "last": float(row.get("last") or 0),
                "first": float(row.get("first") or 0),
                "left": round(left, 1),
                "cooling": left > 0,
                "roads": list(row.get("roads") or [])[:6],
                "answers": list(row.get("answers") or [])[:5],
            })
        out.sort(key=lambda r: (-r["left"], -r["used"]))
        del out[max(1, int(most)):]
    except Exception:  # noqa: BLE001
        pass
    return out


def speakbox_heard(rid: str = "") -> list[dict[str, Any]]:
    try:
        rows = json.loads(mind_state(rid, "heard").read_text())
        return rows if isinstance(rows, list) else []
    except Exception:
        return []


def speakbox_remember(quote: dict[str, Any]) -> None:
    """Log what was aired, most recent first — line by line.

    A swath is several gems joined up, and remembering only the joined text
    let every one of its gems come straight back inside the next swath cut a
    line to either side. Each constituent line is recorded on its own, which
    is what makes the no-repeat filter in speakbox_quote actually bite
    (#235)."""
    if not (quote and quote.get("text")):
        return
    # Retired against the mind it CAME from (#627), even if the operator
    # jumped brains mid-round.
    rid = mind_id(str(quote.get("mind") or ""))
    heard = ([{"file": quote.get("file", ""), "text": line}
              for line in (quote.get("lines") or [])] or
             [{"file": quote.get("file", ""), "text": quote["text"]}])
    with _SPEAKBOX_LOCK:
        rows = speakbox_heard(rid)
        for one in heard:
            was = next((r for r in rows if r.get("text") == one["text"]), {})
            rows = [r for r in rows if r.get("text") != one["text"]]
            rows.insert(0, {**one, "used": int(was.get("used") or 0) + 1,
                            "last": int(time.time())})
        try:
            store = mind_state(rid, "heard")
            store.parent.mkdir(parents=True, exist_ok=True)
            _tmp = store.with_suffix(".tmp")
            _tmp.write_text(json.dumps(rows[:SPEAKBOX_HEARD_MAX], indent=1))
            _tmp.replace(store)
        except OSError:
            pass                        # a forgetful show still goes out


# The good lines, per document, once they have been found. Keyed on the file
# as it stood when they were found, so editing it in the panel throws them out
# and the next round goes back to the document.
SPEAKBOX_GEMS = data_path("speakbox_gems.json")
# #1039: was 1500, against documents that run to 240KB - one pass saw
# six-tenths of one percent of a big file, and what it saw is the entire
# pool the round is written from. Measured: 41% of draws had six lines
# or fewer to choose between. The repair model is given 8k of context
# for this, so the window was never the constraint; 1500 was.
SPEAKBOX_GEM_WINDOW = 5000         # characters of transcript read at a time


def _gem_cache(rid: str = "") -> dict[str, Any]:
    try:
        data = json.loads(mind_state(rid, "gems").read_text())
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def speakbox_gems(doc: Path, rid: str = "") -> list[str]:
    """The lines already found in this document, if it has not changed."""
    row = _gem_cache(rid).get(doc.name)
    row = row if isinstance(row, dict) else {}
    try:
        if row.get("at") != doc.stat().st_mtime_ns:
            return []                   # edited since; go and read it again
    except OSError:
        return []
    # Old harvests sometimes cached the repair prompt itself as speech.
    # Filter only those exact unquoted instruction clauses on read; original
    # documents and cached evidence remain available for inspection.
    return [cleaned for line in row.get("lines") or []
            if (cleaned := strip_repair_prompt_echo(str(line))).strip()]


def speakbox_body(doc: Path) -> str:
    """The document as one run of speech, timestamps and headings gone."""
    try:
        text = doc.read_text(errors="replace")
    except OSError:
        return ""
    keep = []
    for para in text.split("\n\n"):
        flat = _SPEAKBOX_STAMP.sub("", " ".join(para.split()))
        if flat and not flat.startswith(("#", "![", "|", "```")):
            keep.append(flat)
    return " ".join(keep)


def _harvest_window_start(body: str, at: int) -> int:
    """2026-09-08 (the scan): the harvest window opens on a sentence when
    the text has one within four hundred characters, else on a word - never
    inside a word. A window opened at a random CHARACTER handed the repair
    model "mfortable" and "sgard", it capitalised them, and the shelf served
    "Mfortable. Must feel good." and "Sgard." (bound as a name) as gems:
    sixteen of the evening's 199 cut lines were such stubs."""
    try:
        text = str(body or "")
        if at <= 0 or not text:
            return 0
        last = max(0, len(text) - 200)
        m = re.search(r"[.!?]\s+", text[at:at + 400])
        if m:
            return min(at + m.end(), last)
        space = text.find(" ", at)
        return at if space < 0 else min(space + 1, last)
    except Exception:  # noqa: BLE001
        return max(0, int(at or 0))


def _gem_is_stub(line: Any) -> bool:
    """A gem cut mid-word or mid-sentence by the harvest window - "Mfortable.
    Must feel good.", "Sgard. And i am burdened...", a lowercase opening - is
    not fresh material: the pair would read the stub aloud and the crystal
    would bind half a word as a name."""
    text = " ".join(str(line or "").split())
    if not text:
        return True
    if text[:1].islower():
        return True
    head = re.split(r"(?<=[.!?])\s", text, 1)[0]
    words = re.findall(r"[^\W\d_]+", head)
    if not words or len(words) > 2:
        return False
    return not _cmu_knows(words[0])


async def speakbox_harvest(doc: Path, rid: str = "") -> list[str]:
    """Read a passage of the document and pull the sayable lines out of it.

    A machine transcript has no punctuation and no sentence boundaries, so
    cutting one up by word count gives mush — the pair end up reading "don't
    don't don't make that the standard cuz they will" out loud, which is not
    a gem, it is a fault. The model reads a stretch of it and hands back whole
    thoughts. The window is picked at random, so running it again on the same
    document turns up different material."""
    body = speakbox_body(doc)
    if len(body) < 200:
        return []
    if len(body) > SPEAKBOX_GEM_WINDOW:
        at = random.randrange(0, len(body) - SPEAKBOX_GEM_WINDOW)
        at = _harvest_window_start(body, at)          # 2026-09-08: never mid-word
        body = body[at:at + SPEAKBOX_GEM_WINDOW]
    # Asked for "the eight best lines" it repairs the passage and hands back
    # one unbroken paragraph, which is nothing this can use. Asking for the
    # repair itself is the job it will actually do — and a repaired passage
    # has full stops in it, which is all the splitter ever needed.
    try:
        found = await ask_model(
            "Below is a rough machine transcript of people talking: no "
            "punctuation, no capitals, no sentence breaks, words mis-heard "
            "all through it. Write it out properly: put in the full stops and "
            "the capitals, break it into sentences, and repair what has "
            "obviously come out wrong. Keep every word and every turn of "
            "phrase you can. Do not summarise it, do not tidy up the "
            "language, do not add anything of your own and do not comment on "
            "it. Give back the repaired text and nothing else.\n\n"
            + body, limit=5200, result_contract="transcript_repair")  # #1039
    except Exception:
        return []

    # "Here is the repaired text:" is not one of the gems.
    found = re.sub(r"^[^.!?\n]{0,120}:\s*", "", found.strip())
    _cleaned_harvest = clean_repair_prompt_echo(found)
    if _cleaned_harvest["changed"]:
        pipeline_log("speakbox", "Removed echoed transcript-repair instructions before extracting dialogue",
                     extra=json.dumps({"source": str(doc), "original": found,
                                       "removed": _cleaned_harvest["removed"]}, ensure_ascii=False))
        found = _cleaned_harvest["text"]
    # #no-repeats: was [:12], and the cache line below REPLACED the shelf rather than
    # adding to it. A round takes four to nine consecutive lines, so twelve is
    # one or two rounds and then the document is exhausted — the live glass was
    # reading "1 unused lines on the shelf" — and an exhausted document is
    # served from its oldest lines again, verbatim, upstream of every gate.
    # Forty deep and ACCUMULATED means a document keeps giving.
    # #1039: was [:40]. A wider window is no use if the shelf still
    # only keeps forty lines of it.
    gems = [cleaned for gem in speakbox_lines(found)
            if " " in (cleaned := strip_repair_prompt_echo(gem))][:120]
    if gems:
        with _SPEAKBOX_LOCK:
            cache = _gem_cache(rid)
            try:
                held = cache.get(doc.name) or {}
                stamp = doc.stat().st_mtime_ns
                # Editing the document still throws its shelf away — that is
                # what keyed the cache on mtime in the first place.
                older = (list(held.get("lines") or [])
                         if held.get("at") == stamp else [])
                merged = older + [g for g in gems if g not in older]
                cache[doc.name] = {"at": stamp, "lines": merged[-400:]}
                store = mind_state(rid, "gems")
                store.parent.mkdir(parents=True, exist_ok=True)
                store.write_text(json.dumps(cache, indent=1))
            except OSError:
                pass                    # finding them again is cheap enough
    return gems


# --- Speakbox VECTOR INDEX (#566): every document embedded with a local model
# so the booth can pull SEMANTICALLY diverse swaths, and new markdown dropped in
# the folder is indexed automatically. Deliberately small — a JSON store and a
# pure-Python cosine scan over a few thousand chunks, plenty for a folder this
# size. ponytail: no numpy/faiss; add one only if the folder passes tens of
# thousands of swaths. The embedder being down is a no-op, never a dead radio.
SPEAKBOX_VECTORS = data_path("speakbox_vectors.json")
# --- The switchboard (#884) ------------------------------------------
# Five roads out of any moment, each mapped onto a round the station
# already knows how to do. The operator picks one from the booth; the
# station remembers what they picked.
SWITCH_KINDS: dict[str, dict[str, str]] = {
    "plot": {"round": "deep",
             "face": "a plot line",
             "ask": "an ongoing story thread between the pair — "
                    "something unresolved that they pick at"},
    "producer": {"round": "manager",
                 "face": "word from the producer",
                 "ask": "a message from the station's producer, which "
                        "the pair have to react to live"},
    "caller": {"round": "caller",
               "face": "a call comes in",
               "ask": "somebody ringing the station with a reason"},
    "track": {"round": "track",
              "face": "drop the needle",
              "ask": "stop talking and play the next record"},
    "rant": {"round": "bombshell",
             "face": "a side rant",
             "ask": "one of them goes off on a tangent sparked by "
                    "something out of the speakbox"},
}

DECISIONS_DIR = data_path("decisions")
DECISION_VECTORS = data_path("decision_vectors.json")
SWITCH_OFFER_LIFE = 300.0               # a board goes stale in 5 minutes
_SWITCHBOARD: list[dict[str, Any]] = []
_SWITCH_QUEUE: list[dict[str, Any]] = []    # what the operator has chosen
_SWITCH_FILLING = [False]
_SWITCH_LOCK = RLock()


def switchboard_live() -> list[dict[str, Any]]:
    """The offers still worth showing."""
    now = time.time()
    with _SWITCH_LOCK:
        _SWITCHBOARD[:] = [o for o in _SWITCHBOARD
                           if now - float(o.get("at") or 0) < SWITCH_OFFER_LIFE]
        return [dict(o) for o in _SWITCHBOARD]


# #957: THE TRANSITION, WATCHED FROM THE CLICK TO THE AIR.
#
# "If I click to change segments, put a loading bar showing the progress
# of the transition from the current broadcast to playing the segment
# that I'm trying to transition to."
#
# Changing segment is not instant and never could be: the round on air
# has to finish, then the new one is WRITTEN by a model and RECORDED by a
# voice engine that runs slower than real time. On this box that is
# ninety seconds to four minutes. Until now the desk said "goes out next"
# and then nothing at all for three minutes, which is indistinguishable
# from the click having been dropped.
#
# So the whole of it is followed. Nothing here is invented: the stages
# are the station's own - queued behind the round on air, taken off the
# switchboard, at the writing desk, in the recording room, speaking - and
# the reading inside a stage is elapsed time against what the task ledger
# has MEASURED that road to cost on this box. It is marked as an estimate
# where it is one.
_INTERJECT_RUN: dict[str, Any] = {}
INTERJECT_STAGE_SHARE = {
    "queued": (0.02, 0.12),
    "starting": (0.12, 0.18),
    "writing": (0.18, 0.48),
    "recording": (0.48, 0.93),
    "on air": (1.0, 1.0),
    "done": (1.0, 1.0),
    "lost": (0.0, 0.0),
}


def interject_mark(stage: str, **fields: Any) -> None:
    """Move the tracked transition to a stage. Unknown ids are ignored, so
    a round the operator never asked for cannot hijack the bar."""
    try:
        if not _INTERJECT_RUN:
            return
        if fields.get("id") and str(fields["id"]) != str(
                _INTERJECT_RUN.get("id") or ""):
            return
        now = time.time()
        if str(_INTERJECT_RUN.get("stage") or "") != str(stage):
            _INTERJECT_RUN["stage"] = str(stage)
            _INTERJECT_RUN["stage_at"] = now
            _INTERJECT_RUN.setdefault("marks", []).append(
                {"stage": str(stage), "at": now})
            del _INTERJECT_RUN["marks"][:-8]
        for key, value in fields.items():
            if key != "id":
                _INTERJECT_RUN[key] = value
    except Exception:  # noqa: BLE001
        pass


# How long a transition may run before the bar stops claiming to be
# waiting for it. Four minutes is the measured p90 of the slowest road on
# this box plus the round it has to wait behind.
INTERJECT_GIVE_UP = 420.0


def interject_progress() -> dict[str, Any]:
    """#957: where the transition has got to, 0..1, and what it is doing.

    The stage comes off the station's own breadcrumbs - _RADIO["activity"]
    is stamped by the writing desk and the voice engine as they work
    (#305) - so this reports rather than guesses. Only the position
    WITHIN a stage is an estimate, and it is measured: elapsed seconds
    against task_cost() for the road being built."""
    out: dict[str, Any] = {"running": False, "progress": 0.0, "stage": "",
                           "label": "", "say": "", "estimate": True}
    try:
        run = dict(_INTERJECT_RUN)
        if not run:
            return out
        now = time.time()
        stage = str(run.get("stage") or "queued")
        began = float(run.get("at") or now)
        if stage in ("done", "lost") or now - began > INTERJECT_GIVE_UP:
            if stage not in ("done", "lost"):
                stage = "lost"
            out.update({
                "running": False,
                "stage": stage,
                "label": str(run.get("label") or ""),
                "progress": 1.0 if stage == "done" else 0.0,
                "say": (f"{run.get('label')} is on the air"
                        if stage == "done" else
                        f"{run.get('label')} never made it to air - the "
                        "booth was still working when the transition timed "
                        "out"),
                "elapsed": round(now - began, 1),
            })
            return out
        # Follow the desk's own breadcrumbs while it works.
        act = _RADIO.get("activity") or {}
        act_stage = str(act.get("stage") or "")
        if stage in ("starting", "writing", "recording"):
            if act_stage == "writing":
                stage = "writing"
            elif act_stage in ("voicing", "recasting", "sting"):
                stage = "recording"
            elif act_stage == "speaking":
                stage = "recording"
        low, high = INTERJECT_STAGE_SHARE.get(stage, (0.0, 1.0))
        road = str(run.get("road") or "")
        try:
            expect = max(20.0, float(task_cost(road) or 0) or 120.0)
        except Exception:  # noqa: BLE001
            expect = 120.0
        into = max(0.0, now - float(run.get("stage_at") or began))
        share = min(0.97, into / expect) if expect > 0 else 0.0
        out.update({
            "running": True,
            "stage": stage,
            "label": str(run.get("label") or ""),
            "road": road,
            "progress": round(low + (high - low) * share, 3),
            "elapsed": round(now - began, 1),
            "expect_seconds": round(expect, 1),
            "queue": len(_SWITCH_QUEUE),
            "detail": str(act.get("detail") or "")[:80],
        })
        out["say"] = {
            "queued": (f"waiting for the round on air to finish, then "
                       f"{out['label']} goes"),
            "starting": f"the booth has taken {out['label']}",
            "writing": f"{out['label']} is at the writing desk",
            "recording": f"{out['label']} is in the recording room",
        }.get(stage, f"{out['label']} is on its way")
    except Exception:  # noqa: BLE001
        pass
    return out


def switchboard_take() -> dict[str, Any]:
    """The operator's next instruction, if they left one."""
    with _SWITCH_LOCK:
        if not _SWITCH_QUEUE:
            return {}
        got = _SWITCH_QUEUE.pop(0)
    # #957: it has left the queue and the booth has it. The bar stops
    # saying "waiting" and starts following the work.
    try:
        interject_mark("starting", id=str(got.get("id") or ""))
    except Exception:  # noqa: BLE001
        pass
    return got


def _decision_vectors() -> dict[str, Any]:
    try:
        got = json.loads(DECISION_VECTORS.read_text())
        if isinstance(got, dict):
            return got
    except Exception:  # noqa: BLE001
        pass
    return {"rows": []}


def _decision_vectors_save(store: dict[str, Any]) -> None:
    try:
        DECISION_VECTORS.parent.mkdir(parents=True, exist_ok=True)
        store["rows"] = list(store.get("rows") or [])[-4000:]
        tmp = DECISION_VECTORS.with_suffix(".tmp")
        tmp.write_text(json.dumps(store))
        tmp.replace(DECISION_VECTORS)
    except OSError:
        pass


async def decision_record(chosen: dict[str, Any],
                          refused: list[dict[str, Any]],
                          how: str = "picked") -> None:
    """#884: write the decision down — a markdown document AND a vector.

    This is the part that compounds. Every choice the operator makes is
    a statement about how this station should run, and until now every
    one of them evaporated the moment the round aired."""
    try:
        DECISIONS_DIR.mkdir(parents=True, exist_ok=True)
        now = time.time()
        stamp = time.strftime("%Y%m%d-%H%M%S", time.localtime(now))
        kind = str(chosen.get("kind") or "")
        face = str(chosen.get("face") or SWITCH_KINDS.get(kind, {}).get(
            "face", kind))
        premise = str(chosen.get("premise") or "")
        track = (_RADIO.get("now") or {})
        on_air = " - ".join(x for x in (str(track.get("artist") or ""),
                                        str(track.get("title") or "")) if x)
        turned_down = "; ".join(
            f"{o.get('kind')}: {str(o.get('premise') or '')[:80]}"
            for o in refused)[:600]
        body = (
            f"---\n"
            f"at: {int(now)}\n"
            f"when: {time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(now))}\n"
            f"kind: {kind}\n"
            f"how: {how}\n"
            f"on_air: {on_air}\n"
            f"---\n\n"
            f"# {face}\n\n"
            f"The operator sent the show down the *{face}* road.\n\n"
            f"**The premise taken:** {premise or '(none)'}\n\n"
            f"**Turned down:** {turned_down or '(nothing else was offered)'}\n\n"
            f"**Playing at the time:** {on_air or '(nothing)'}\n")
        (DECISIONS_DIR / f"{stamp}-{kind}.md").write_text(
            body, encoding="utf-8")
        # …and into the vector store, so the next board can lean on it.
        text = (f"{face}. {premise}. while playing {on_air}"
                if premise else f"{face}. while playing {on_air}")
        vecs = await _embed_texts([text])
        if vecs:
            store = _decision_vectors()
            store.setdefault("rows", []).append({
                "at": now, "kind": kind, "face": face,
                "premise": premise[:400], "on_air": on_air[:160],
                "how": how, "v": vecs[0]})
            _decision_vectors_save(store)
        pipeline_log("switchboard",
                     f"decision written down - {face} (#884)",
                     extra=premise[:180])
    except Exception:  # noqa: BLE001
        pass


async def decisions_recall(query: str, k: int = 5) -> list[dict[str, Any]]:
    """What the operator has chosen in moments like this one."""
    try:
        store = _decision_vectors()
        rows = list(store.get("rows") or [])
        if not rows or not query.strip():
            return []
        got = await _embed_texts([query])
        if not got:
            return []
        q = got[0]
        scored = []
        for row in rows:
            v = row.get("v") or []
            if len(v) != len(q):
                continue
            scored.append((sum(a * b for a, b in zip(q, v)), row))
        scored.sort(key=lambda pair: pair[0], reverse=True)
        return [dict(r, score=round(s, 4)) for s, r in scored[:k]]
    except Exception:  # noqa: BLE001
        return []


# #1156: directive_draw_kind asks for this on EVERY talk round, and the
# vector store is 4000 rows of 768 floats when it is full. Memoised on
# the file's (mtime, size), the way crystals_read is - json.loads holds
# the GIL, and the round dispatch is the show loop.
_DECISION_TASTE_MEMO: dict[str, Any] = {"key": None, "at": 0.0, "value": {}}


def decisions_taste() -> dict[str, int]:
    """A blunt tally of which roads get taken — enough to bias a board
    without needing the model to think about it."""
    _now = time.time()
    try:
        if (_DECISION_TASTE_MEMO["key"] is not None
                and _now - float(_DECISION_TASTE_MEMO["at"]) < 5.0):
            return dict(_DECISION_TASTE_MEMO["value"])
        st = DECISION_VECTORS.stat()
        key = (st.st_mtime_ns, st.st_size)
        if key == _DECISION_TASTE_MEMO["key"]:
            _DECISION_TASTE_MEMO["at"] = _now
            return dict(_DECISION_TASTE_MEMO["value"])
    except Exception:  # noqa: BLE001
        key = None
    tally: dict[str, int] = {}
    for row in (_decision_vectors().get("rows") or []):
        k = str(row.get("kind") or "")
        if k:
            tally[k] = tally.get(k, 0) + 1
    if key is not None:
        _DECISION_TASTE_MEMO.update({"key": key, "at": _now,
                                     "value": dict(tally)})
    return tally


async def switch_premise(kind: str) -> str:
    """A concrete, already-decided premise for one road.

    Drawn from the station's own material rather than written by the
    model, so standing a fresh board up costs nothing on a GPU that is
    already busy making voices."""
    try:
        if kind == "track":
            nxt = (_RADIO.get("coming") or {})
            title = " - ".join(x for x in (str(nxt.get("artist") or ""),
                                           str(nxt.get("title") or "")) if x)
            return f"cut the talk and play {title}" if title else \
                "cut the talk and drop the needle on the next record"
        seed = await speakbox_quote(most=2, cap=200)
        line = str((seed or {}).get("text") or "").strip()
        if not line:
            return str(SWITCH_KINDS.get(kind, {}).get("ask") or "")
        if kind == "rant":
            return f"set one of them off about this: \"{line[:170]}\""
        if kind == "caller":
            return f"a caller who turns up with this on their mind: " \
                   f"\"{line[:150]}\""
        if kind == "producer":
            return f"the producer sends word, and it lands on this: " \
                   f"\"{line[:150]}\""
        return f"the thread they keep circling: \"{line[:170]}\""
    except Exception:  # noqa: BLE001
        return str(SWITCH_KINDS.get(kind, {}).get("ask") or "")


async def switchboard_fill(want: int = 4) -> None:
    """Stand a fresh board up, weighted by what the operator likes."""
    if _SWITCH_FILLING[0]:
        return
    _SWITCH_FILLING[0] = True
    try:
        taste = decisions_taste()
        kinds = list(SWITCH_KINDS)
        # Roads the operator has taken before come up more often, but
        # every road keeps a floor so the board never collapses onto one.
        weights = [1.0 + 1.6 * float(taste.get(k, 0)) /
                   float(max(1, sum(taste.values()))) for k in kinds]
        picked: list[str] = []
        pool = list(zip(kinds, weights))
        while pool and len(picked) < max(2, min(int(want), len(kinds))):
            total = sum(w for _k, w in pool) or 1.0
            roll = random.random() * total
            run = 0.0
            for i, (k, w) in enumerate(pool):
                run += w
                if roll <= run:
                    picked.append(k)
                    pool.pop(i)
                    break
            else:
                picked.append(pool.pop(0)[0])
        fresh: list[dict[str, Any]] = []
        for kind in picked:
            fresh.append({
                "id": uuid.uuid4().hex[:10],
                "kind": kind,
                "face": SWITCH_KINDS[kind]["face"],
                "premise": await switch_premise(kind),
                "at": time.time(),
            })
        with _SWITCH_LOCK:
            _SWITCHBOARD[:] = fresh
    except Exception:  # noqa: BLE001
        pass
    finally:
        _SWITCH_FILLING[0] = False


async def switchboard_keeper() -> None:
    """Keep a board standing whenever the station is on air."""
    while True:
        try:
            if _RADIO.get("on"):
                live = switchboard_live()
                if len(live) < 2:
                    await switchboard_fill()
        except Exception:  # noqa: BLE001
            pass
        await asyncio.sleep(20)


EMBED_MODEL = os.getenv("EMBED_MODEL", "nomic-embed-text")
SPEAKBOX_VEC_MAX = 40000                # #816: 24000 was REACHED — the
                                        # positional cut silently erased
                                        # 14 whole documents
_VEC_LOCK = RLock()
_VEC_CACHE: dict[str, Any] = {}         # the store, kept warm in memory


def _vec_norm(v: list[float]) -> list[float]:
    mag = (sum(x * x for x in v) ** 0.5) or 1.0
    return [x / mag for x in v]


async def _embed_texts(texts: list[str]) -> list[list[float]]:
    """Embed a batch through the local nomic-embed-text on Ollama (already on
    the box). Returns UNIT vectors so a later cosine is just a dot product; []
    on any failure, so indexing degrades to a no-op instead of a dead show."""
    texts = [t for t in texts if t and t.strip()]
    if not texts:
        return []
    try:
        async with httpx.AsyncClient(timeout=120) as client:
            r = await client.post(f"{OLLAMA_URL}/api/embed",
                                  json={"model": EMBED_MODEL, "input": texts})
        if r.status_code != 200:
            return []
        return [_vec_norm(v) for v in r.json().get("embeddings", [])]
    except Exception:
        return []


def _load_vectors(rid: str = "") -> dict[str, Any]:
    """One warm store PER MIND (#627). A single shared cache meant the
    reindex pass for one folder deleted the other folder's vectors, because
    every chunk not present in the folder being scanned is pruned."""
    with _VEC_LOCK:
        key = mind_id(rid)
        held = _VEC_CACHE.get(key)
        if isinstance(held, dict) and held.get("loaded"):
            return held
        data: dict[str, Any] = {"model": EMBED_MODEL, "mtimes": {},
                                "chunks": []}
        try:
            store = mind_state(key, "vectors")
            if store.is_file():
                data = json.loads(store.read_text())
        except Exception:
            pass
        data["loaded"] = True
        _VEC_CACHE[key] = data
    # #1156: a cold load is the expensive moment; leave the sidecar behind
    # so the next process never needs to repeat it for a count.
    try:
        if not _vector_meta_path(key).is_file():
            _vector_meta_write(key, data)
    except Exception:  # noqa: BLE001
        pass
    return data


def _vector_meta_path(key: str) -> Path:
    store = mind_state(key, "vectors")
    return store.with_name(store.stem + ".meta.json")


def _vector_meta_from(held: dict[str, Any]) -> dict[str, Any]:
    chunks = held.get("chunks") or []
    per_file: dict[str, int] = {}
    for c in chunks:
        f = str((c or {}).get("file") or "?")
        per_file[f] = per_file.get(f, 0) + 1
    dim = 0
    for c in chunks:
        if (c or {}).get("vec"):
            dim = len(c["vec"])
            break
    return {"model": held.get("model") or EMBED_MODEL,
            "mtimes": dict(held.get("mtimes") or {}),
            "chunks": len(chunks), "per_file": per_file, "dim": dim,
            "at": time.time()}


def _vector_meta_write(key: str, held: dict[str, Any]) -> None:
    """#1156: the sidecar - counts, files and mtimes, a few KB. The
    `doom` mind's store is 625MB; parsing it for a chunk COUNT froze the
    loop 11.4s (the pulse caught it at boot under /api/crystals), and the
    C decoder holds the GIL so a thread does not help. Anything that only
    needs to know what is IN the store reads this instead."""
    try:
        meta = _vector_meta_from(held)
        path = _vector_meta_path(key)
        path.parent.mkdir(parents=True, exist_ok=True)
        tmp = path.with_suffix(".tmp")
        tmp.write_text(json.dumps(meta))
        tmp.replace(path)
    except Exception:  # noqa: BLE001
        pass


def _vector_meta(rid: str = "") -> dict[str, Any] | None:
    """The sidecar if there is one (None when it has never been written
    - the next full load or save writes it)."""
    key = mind_id(rid)
    try:
        path = _vector_meta_path(key)
        if not path.is_file():
            return None
        meta = json.loads(path.read_text())
        return meta if isinstance(meta, dict) else None
    except Exception:  # noqa: BLE001
        return None


def _vector_loaded(rid: str = "") -> dict[str, Any] | None:
    """The warm store, or None - never a load."""
    with _VEC_LOCK:
        held = _VEC_CACHE.get(mind_id(rid))
        return held if isinstance(held, dict) and held.get("loaded") else None


_VEC_WARMING: set[str] = set()


def _vector_warm_soon(rid: str = "") -> None:
    """Load a store on a thread (the GIL still holds the loop for the
    parse, but off the request path and once) and write its sidecar."""
    key = mind_id(rid)
    with _VEC_LOCK:
        if key in _VEC_WARMING or (_VEC_CACHE.get(key) or {}).get("loaded"):
            return
        _VEC_WARMING.add(key)

    def run() -> None:
        try:
            _load_vectors(key)
        finally:
            with _VEC_LOCK:
                _VEC_WARMING.discard(key)
    Thread(target=run, name=f"vec-warm-{key}", daemon=True).start()


def _vector_chunks_n(rid: str = "") -> int:
    """How many chunks a mind holds, WITHOUT parsing its store: the warm
    cache, else the sidecar (kicking a background warm when there is
    neither, so the number is right on the next ask)."""
    held = _vector_loaded(rid)
    if held is not None:
        return len(held.get("chunks") or [])
    meta = _vector_meta(rid)
    if meta is not None:
        return int(meta.get("chunks") or 0)
    _vector_warm_soon(rid)
    return 0


def _save_vectors(rid: str = "") -> None:
    # #816: snapshot under the lock, SERIALIZE outside it. The 410MB
    # json.dumps measured 4.8s and ran lock-held on the event loop —
    # freezing playout pacing and call pickup on every speakbox edit.
    with _VEC_LOCK:
        key = mind_id(rid)
        held = _VEC_CACHE.get(key) or {}
        payload = {k: held.get(k) for k in ("model", "mtimes", "chunks")}
    try:
        store = mind_state(key, "vectors")
        store.parent.mkdir(parents=True, exist_ok=True)
        tmp = store.with_suffix(".tmp")
        tmp.write_text(json.dumps(payload))
        tmp.replace(store)
    except Exception:
        pass
    _vector_meta_write(key, payload)                 # #1156


def speakbox_vector_stats(rid: str = "") -> dict[str, Any]:
    """What is in the index right now — for the status line and the #578 viz.
    Carries per-file USAGE (`uses`) and RECENCY (`last`) drawn from the said-
    memory, so the sphere can pull recently-used documents toward the core and
    scale them by how hard they are leaned on (#586)."""
    # #1156: cold store + sidecar = answer from the sidecar; the parse of
    # a giant store is never the price of a status line.
    _meta = None if _vector_loaded(rid) is not None else _vector_meta(rid)
    if _meta is not None:
        store = {"model": _meta.get("model"), "chunks": []}
        chunks = []
        per_file = {str(k): int(v) for k, v in
                    (_meta.get("per_file") or {}).items()}
        _dim = int(_meta.get("dim") or 0)
        _n = int(_meta.get("chunks") or 0)
    else:
        store = _load_vectors(rid)
        chunks = store.get("chunks") or []
        per_file = {}
        for c in chunks:
            per_file[c.get("file", "?")] = per_file.get(c.get("file", "?"), 0) + 1
        _dim = len(chunks[0]["vec"]) if chunks and chunks[0].get("vec") else 0
        _n = len(chunks)
    # Aggregate the said-memory to a per-document use count + last-used stamp.
    uses: dict[str, int] = {}
    last: dict[str, int] = {}
    for r in speakbox_heard(rid):
        f = r.get("file", "")
        if not f:
            continue
        uses[f] = uses.get(f, 0) + int(r.get("used") or 1)
        last[f] = max(last.get(f, 0), int(r.get("last") or 0))
    return {
        "model": store.get("model") or EMBED_MODEL,
        "documents": len(per_file),
        "chunks": _n,
        "dim": _dim,
        "now": int(time.time()),
        "files": sorted(({"file": f, "chunks": n,
                          "uses": uses.get(f, 0), "last": last.get(f, 0)}
                         for f, n in per_file.items()),
                        key=lambda r: -r["chunks"]),
    }


# #995: lyrics that landed in the STUDIO before #829 stopped them.
#
# INSIDE the studio folder, deliberately. data/speakbox is its own mount
# on this box - moving a file out of it raises "Invalid cross-device
# link" (Errno 18), measured - and a subfolder is on the same device by
# construction. It is invisible to the draw anyway: speakbox_all globs
# "*.md" one level deep, so nothing here is ever read, indexed or spoken.
SPEAKBOX_EVICTED = SPEAKBOX_DIR / "_evicted"


def speakbox_evict_lyrics() -> int:
    """#995: "Allen interface lyrics are not part of speakerbox. They are
    part of a separate data crystal similar to Doom."

    They are, now - #829 saw this and stopped extraction writing into the
    shared shelf, with the note "330 song files landed in the OPERATOR'S
    OWN speakbox". What it did not do is take out the ones already there.
    Three survived: the pair were drawing from them and putting
    "furielwrath62tidalwaveofrage - lyrics" on air as studio material.

    They are MOVED, not deleted - out of the studio into
    data/speakbox_evicted, where nothing draws from them and the operator
    can still get them back. The album minds keep their own copies
    untouched; those are the crystal's, and that is where they belong.

    speakbox_reindex already forgets a document that has left the folder,
    so the vectors go with them on the next pass without anything else
    being asked to happen."""
    # #1017: "I want you to make sure that the Pine box has a backup
    # system ensuring that speakerbox documents are never deleted ever
    # again."
    #
    # This pass is the only thing that has ever taken a document off that
    # shelf, and it was asked for at #995 - but the operator has since
    # reversed that plainly, twice, and has had the three files put back
    # by hand. Leaving it armed would move them straight back out on the
    # next restart, which is the exact failure the request is about.
    #
    # So it is OFF unless it is switched on. It is not deleted, because
    # the reason for it was real: the pair were reading
    # "furielwrath62tidalwaveofrage - lyrics" on air as studio material.
    # If that starts happening again, `speakbox_evict_lyrics` in the
    # settings turns it back on - and the vault below means even then
    # nothing is ever actually lost.
    try:
        if not bool(dj_settings().get("speakbox_evict_lyrics", False)):
            return 0
    except Exception:  # noqa: BLE001
        return 0
    moved = 0
    try:
        for path in sorted(SPEAKBOX_DIR.glob("*.md")):
            if not path.is_file():
                continue
            if not path.stem.lower().endswith(" - lyrics"):
                continue
            try:
                SPEAKBOX_EVICTED.mkdir(parents=True, exist_ok=True)
                dest = SPEAKBOX_EVICTED / path.name
                if dest.exists():
                    path.unlink(missing_ok=True)   # already rescued
                else:
                    try:
                        path.replace(dest)
                    except OSError:
                        # Belt as well as braces: shutil copies across a
                        # device boundary where rename cannot.
                        import shutil as _sh
                        _sh.move(str(path), str(dest))
                moved += 1
            except Exception as exc:  # noqa: BLE001
                pipeline_log("drop", f"could not evict {path.name}: "
                                     f"{type(exc).__name__}: {exc}"[:160])
                continue
        if moved:
            pipeline_log("speakbox", f"{moved} lyrics document(s) taken out "
                         "of the studio shelf - extraction lyrics belong to "
                         "their own crystal, not to the speakbox. They are "
                         "in data/speakbox_evicted (#995)")
    except Exception:  # noqa: BLE001
        pass
    return moved


# #1017: THE VAULT.
#
# "I need them examined, analyzed, assimilated into the crystal, and then
# of course backed up to ensure that they are never deleted ever again."
#
# Deliberately OUTSIDE data/speakbox, and that is the whole design. That
# folder is its own mount inside the container - which is why Explorer
# shows it empty over the share and why the operator has twice believed
# his documents were gone. The vault sits in data/ proper, on the share
# the operator can actually see, so a copy of every document he has ever
# put in the speakbox is visible from Windows without going through the
# app at all.
#
# IT NEVER DELETES. A document that disappears from the shelf stays in
# the vault and is marked missing, with the date it went. That is what
# makes it a backup rather than a mirror: a mirror of a folder somebody
# emptied is an empty folder.
SPEAKBOX_VAULT = data_path("speakbox_vault")
SPEAKBOX_VAULT_MANIFEST = SPEAKBOX_VAULT / "_manifest.json"
VAULT_EVERY = 600.0                     # a sweep at most this often
_VAULT_AT = [0.0]


def _vault_manifest() -> dict[str, Any]:
    try:
        got = json.loads(SPEAKBOX_VAULT_MANIFEST.read_text(encoding="utf-8"))
        if isinstance(got, dict):
            return got
    except Exception:  # noqa: BLE001
        pass
    return {"documents": {}}


def _vault_manifest_save(store: dict[str, Any]) -> None:
    try:
        SPEAKBOX_VAULT.mkdir(parents=True, exist_ok=True)
        tmp = SPEAKBOX_VAULT_MANIFEST.with_suffix(".tmp")
        tmp.write_text(json.dumps(store, indent=1), encoding="utf-8")
        tmp.replace(SPEAKBOX_VAULT_MANIFEST)
    except Exception:  # noqa: BLE001
        pass


def speakbox_vault_sync(force: bool = False) -> dict[str, Any]:
    """#1017: copy anything new or changed into the vault. Never delete.

    Runs on a timer and at startup. A copy rather than a move, and across
    a device boundary on purpose - shutil.copy2 handles that where
    rename cannot, which is the same EXDEV that made the eviction awkward
    in the first place."""
    out = {"at": time.time(), "copied": 0, "kept": 0, "missing": 0,
           "bytes": 0, "why": ""}
    try:
        now = time.time()
        if not force and now - float(_VAULT_AT[0] or 0) < VAULT_EVERY:
            out["why"] = "swept recently"
            return out
        _VAULT_AT[0] = now
        SPEAKBOX_VAULT.mkdir(parents=True, exist_ok=True)
        store = _vault_manifest()
        docs = store.setdefault("documents", {})
        seen: set[str] = set()
        import shutil as _sh
        for path in sorted(SPEAKBOX_DIR.glob("*.md")):
            if not path.is_file():
                continue
            name = path.name
            seen.add(name)
            try:
                stat = path.stat()
                raw = path.read_bytes()
            except Exception:  # noqa: BLE001
                continue
            digest = hashlib.sha1(raw).hexdigest()
            row = docs.setdefault(name, {"first": now})
            out["bytes"] += len(raw)
            if str(row.get("sha1") or "") == digest and (
                    SPEAKBOX_VAULT / name).exists():
                row["seen"] = now
                row.pop("missing_since", None)
                out["kept"] += 1
                continue
            try:
                _sh.copy2(str(path), str(SPEAKBOX_VAULT / name))
            except Exception as exc:  # noqa: BLE001
                pipeline_log("drop", f"could not vault {name}: "
                                     f"{type(exc).__name__}"[:120])
                continue
            row.update({"sha1": digest, "bytes": int(stat.st_size),
                        "seen": now, "copied": now})
            row.pop("missing_since", None)
            out["copied"] += 1
        # Anything the vault knows that is no longer on the shelf.
        for name, row in docs.items():
            if name in seen:
                continue
            row.setdefault("missing_since", now)
            out["missing"] += 1
        store["at"] = now
        store["folder"] = str(SPEAKBOX_DIR)
        store["vault"] = str(SPEAKBOX_VAULT)
        _vault_manifest_save(store)
        if out["copied"]:
            pipeline_log("speakbox",
                         f"{out['copied']} speakbox document(s) copied into "
                         f"the vault at {SPEAKBOX_VAULT} - nothing is ever "
                         "removed from there, so a document put in the "
                         "folder cannot be lost (#1017)")
    except Exception as exc:  # noqa: BLE001
        out["why"] = f"{type(exc).__name__}: {exc}"[:160]
    return out


def speakbox_vault_state() -> dict[str, Any]:
    """#1017: what the vault is holding, and what it is holding that the
    shelf no longer has."""
    store = _vault_manifest()
    docs = store.get("documents") or {}
    missing = [{"name": n, "since": float(r.get("missing_since") or 0),
                "bytes": int(r.get("bytes") or 0)}
               for n, r in docs.items() if r.get("missing_since")]
    missing.sort(key=lambda r: -r["since"])
    held = len(docs)
    return {
        "vault": str(SPEAKBOX_VAULT),
        "folder": str(SPEAKBOX_DIR),
        "documents": held,
        "bytes": sum(int((r or {}).get("bytes") or 0) for r in docs.values()),
        "missing": missing,
        "swept": float(store.get("at") or 0),
        "say": (f"{held} document(s) in the vault"
                + (f", {len(missing)} of which are no longer on the shelf"
                   if missing else " and every one of them is on the shelf")),
    }


def speakbox_vault_restore(names: list[str] | None = None) -> list[str]:
    """#1017: put a vaulted document back on the shelf. Never overwrites
    a document that is already there."""
    back: list[str] = []
    try:
        import shutil as _sh
        store = _vault_manifest()
        docs = store.get("documents") or {}
        want = set(names or []) or {n for n, r in docs.items()
                                    if r.get("missing_since")}
        for name in sorted(want):
            src = SPEAKBOX_VAULT / name
            dest = SPEAKBOX_DIR / name
            if not src.is_file() or dest.exists():
                continue
            try:
                _sh.copy2(str(src), str(dest))
                back.append(name)
                (docs.get(name) or {}).pop("missing_since", None)
            except Exception:  # noqa: BLE001
                continue
        if back:
            _vault_manifest_save(store)
            pipeline_log("speakbox", f"{len(back)} document(s) put back on "
                         "the studio shelf out of the vault (#1017)")
    except Exception:  # noqa: BLE001
        pass
    return back


async def speakbox_reindex(force: bool = False,
                           rid: str = "") -> dict[str, Any]:
    """Bring the vector index in step with the folder (#566): embed any new or
    changed markdown, drop vectors for deleted files. Auto-detected by mtime —
    a file dropped in the speakbox folder is in the DJs' heads on the next pass
    with nobody clicking anything. Per mind (#627)."""
    key = mind_id(rid)
    # #1156: the cold load is a json.loads of a vector store that can run
    # to hundreds of MB (625MB for one mind), and the C decoder holds the
    # GIL for all of it - so the clock, which walks every mind at boot,
    # asks the SIDECAR first: same files, same mtimes, nothing to do, no
    # parse. The store is only loaded when a document changed or when
    # somebody actually searches the mind.
    present = await asyncio.to_thread(
        lambda: {p.name: p for p in speakbox_all(key)})
    if not force and _vector_loaded(key) is None:
        meta = _vector_meta(key)
        if meta is not None:
            _mt = {str(k): int(v) for k, v in
                   (meta.get("mtimes") or {}).items()}
            _now = {}
            for name, path in present.items():
                try:
                    _now[name] = int(path.stat().st_mtime)
                except OSError:
                    continue
            if _now == _mt:
                return speakbox_vector_stats(key)     # in step, unparsed
    store = await asyncio.to_thread(_load_vectors, key)
    mtimes = dict(store.get("mtimes") or {})
    chunks = [c for c in (store.get("chunks") or [])
              if c.get("file") in present]          # forget deleted files
    changed = []
    for name, path in present.items():
        try:
            mt = int(path.stat().st_mtime)
        except OSError:
            continue
        if force or mtimes.get(name) != mt:
            changed.append((name, path, mt))
    if not changed and len(chunks) == len(store.get("chunks") or []):
        return speakbox_vector_stats(key)             # already in step
    changed_names = {n for n, _p, _m in changed}
    chunks = [c for c in chunks if c.get("file") not in changed_names]
    for i, (name, path, mt) in enumerate(changed):
        try:
            text = path.read_text(encoding="utf-8", errors="replace")
        except OSError:
            continue
        # Index ALL of every document (#597: "all dialogue must be assimilated
        # — some appear short"). Was 18 (truncated long docs); 100 is generous
        # enough to hold a whole document yet keeps ALL ~222 files inside
        # SPEAKBOX_VEC_MAX, so no file is dropped when the shelf fills — the
        # earlier 300 let a few giant files eat the budget and truncate the rest.
        # #868: a flat 100 is the wrong shape for an ALBUM mind of thirty
        # songs, which has the whole budget to itself. Share SPEAKBOX_VEC_MAX
        # out over the documents actually present and never go below the old
        # hundred, so the studio's big shelf keeps its behaviour while a small
        # mind stops losing the back half of a long document.
        _per_doc = min(1200, max(100, SPEAKBOX_VEC_MAX // max(1, len(present))))
        swaths = [s for s in speakbox_lines(text) if len(s) >= 24][:_per_doc]
        vecs = await _embed_texts(swaths) if swaths else []
        for swath, vec in zip(swaths, vecs):
            chunks.append({"file": name, "text": swath[:600], "vec": vec})
        mtimes[name] = mt
        # Persist progress every 25 files (#597) so a restart mid-rebuild does
        # not lose the whole pass — the next run resumes from the saved mtimes.
        if i % 25 == 24:
            with _VEC_LOCK:
                held = _VEC_CACHE.setdefault(key, {})
                held["mtimes"] = {n: m for n, m in mtimes.items()
                                  if n in present}
                held["chunks"] = chunks
                held["model"] = EMBED_MODEL
                held["loaded"] = True
            await asyncio.to_thread(_save_vectors, key)
    if len(chunks) > SPEAKBOX_VEC_MAX:
        # #816: when the cut drops a file to ZERO chunks, forget its mtime
        # too — otherwise the gate says "indexed" forever and the document
        # is erased from search with no road back (measured: 14 files).
        _before_files = {c.get("file") for c in chunks}
        _kept_files = {c.get("file") for c in chunks[-SPEAKBOX_VEC_MAX:]}
        for _lost in _before_files - _kept_files:
            mtimes.pop(_lost, None)
        chunks = chunks[-SPEAKBOX_VEC_MAX:]
    with _VEC_LOCK:
        held = _VEC_CACHE.setdefault(key, {})
        held["mtimes"] = {n: mt for n, mt in mtimes.items() if n in present}
        held["chunks"] = chunks
        held["model"] = EMBED_MODEL
        held["loaded"] = True
    await asyncio.to_thread(_save_vectors, key)
    return speakbox_vector_stats(key)


async def speakbox_search(query: str, k: int = 5, exclude: str = "",
                          rid: str = "") -> list[dict[str, Any]]:
    """The k swaths most semantically similar to `query`, ONE per document for
    variety (#566). Empty when the index or the embedder is cold — the caller
    then falls back to the random-swath mining that has always worked."""
    store = _load_vectors(rid)
    chunks = [c for c in (store.get("chunks") or [])
              if c.get("vec") and c.get("file") != exclude]
    if not chunks:
        return []
    qv = await _embed_texts([str(query or "")[:600]])
    if not qv:
        return []
    q = qv[0]
    # Rank in a thread (#597): the index now holds ALL of every document, so the
    # cosine scan is bigger — run it off the event loop so a search never stalls
    # the show.
    _votes = votes_read()

    def _rank() -> list[dict[str, Any]]:
        # #816: the pure-Python cosine over 24000x768 measured ~0.9s per
        # draw, GIL-bound, in the caller-response path. numpy does the
        # same matrix-vector product in milliseconds; the matrix is cached
        # on the store and rebuilt only when the chunk list changes.
        try:
            import numpy as _np
            # #914: THE CACHE KEY WAS WRONG, and it took every caller
            # round with it. The matrix is built from `chunks` — the
            # exclude-FILTERED list — but was cached under the identity
            # of store["chunks"], the UNFILTERED one. So a draw with an
            # exclude cached a short matrix, and the next draw without
            # one hit that cache and indexed off the end:
            #   IndexError: index 21615 is out of bounds ... size 21615
            # caller_clock swallows it as a drop line, so the call was
            # simply lost — which is why the phones read 0 of 5 an hour.
            # The key now carries what the matrix was actually built
            # from.
            _key = (id(store.get("chunks")),
                    len(store.get("chunks") or []),
                    len(chunks), str(exclude or ""))
            _mat = store.get("_np")
            if not _mat or _mat[0] != _key:
                _arr = _np.asarray([c["vec"] for c in chunks],
                                   dtype=_np.float32)
                _mat = (_key, _arr)
                store["_np"] = _mat
            _scores = _mat[1] @ _np.asarray(q, dtype=_np.float32)
            rows = []
            for i, c in enumerate(chunks):
                score = float(_scores[i])
                v = _votes.get(chunk_key(c["file"], c["text"]))
                if v:
                    net = int(v.get("up") or 0) - int(v.get("down") or 0)
                    if net <= -3:
                        continue
                    score *= 1.0 + max(-0.4, min(0.4, net * 0.08))
                rows.append({"file": c["file"], "text": c["text"],
                             "score": score})
            rows.sort(key=lambda r: -r["score"])
            return rows
        except ImportError:
            pass
        rows = []
        for c in chunks:
            score = sum(a * b for a, b in zip(q, c["vec"]))
            # #815: operator votes bend the draw — capped, and a heavily
            # buried chunk stops surfacing entirely.
            v = _votes.get(chunk_key(c["file"], c["text"]))
            if v:
                net = int(v.get("up") or 0) - int(v.get("down") or 0)
                if net <= -3:
                    continue
                score *= 1.0 + max(-0.4, min(0.4, net * 0.08))
            rows.append({"file": c["file"], "text": c["text"],
                         "score": score})
        rows.sort(key=lambda r: -r["score"])
        return rows
    scored = await asyncio.to_thread(_rank)
    out: list[dict[str, Any]] = []
    seen: set[str] = set()
    for r in scored:                    # one swath per document, best first
        if r["file"] in seen:
            continue
        seen.add(r["file"])
        out.append(r)
        if len(out) >= k:
            break
    return out


def _vector_access_log(query: str, hit: dict[str, Any], ms: int,
                       n: int, who: str = "") -> None:
    """Record one booth vector-DB retrieval for the "how it reached the vector
    database" readout (#595): what section it pulled, the match strength, how
    long it took, which system located it. `who` is which presenter reached
    for it, so the sim can draw each of them touching the data (#640)."""
    station_flow_event("speakerbox", "ok", "Speakerbox source retrieved",
                       {"query": query, "hit": hit, "ms": ms,
                        "searched": n, "who": who}, from_node="schedule")
    log = _RADIO.setdefault("vector_access", [])
    log.insert(0, {
        "ts": int(time.time()),
        "query": " ".join(str(query or "").split())[:90],
        "file": hit.get("file", ""),
        "score": round(float(hit.get("score") or 0), 3),
        "ms": ms,
        "searched": n,
        "who": who or "booth",
        "engine": EMBED_MODEL,
        "how": "embed → cosine over the swath index",
    })
    del log[24:]
    # Per-presenter tallies, so a node can show how deep into the documents
    # that particular DJ has been (#640).
    if who:
        pulls = _RADIO.setdefault("vector_pulls", {})
        row = pulls.setdefault(who, {"pulls": 0, "last": 0, "file": ""})
        row["pulls"] += 1
        row["last"] = int(time.time())
        row["file"] = hit.get("file", "")


_SPEAKBOX_TOPIC_STOP = {
    "about", "active", "after", "again", "all", "and", "are", "around",
    "because", "before",
    "being", "caller", "calling", "could", "dialogue", "does", "from",
    "have", "into", "just", "line", "people", "radio", "runs", "show",
    "station", "story", "subject", "that", "the", "their", "theme", "thing",
    "things", "this", "those", "through", "very", "what", "when", "where",
    "which", "while", "with", "would",
}


def speakbox_topic_relevance(topic: str, text: str) -> dict[str, Any]:
    """Cheap proof that a semantic Speakerbox hit serves the named topic.

    Vector similarity alone is intentionally broad and can retrieve a vivid
    but unrelated passage.  That is useful for free banter and destructive
    for a scheduled call whose database topic is a contract.  Calls use this
    lexical cross-check after the vector search: one concrete topic term must
    actually occur in the passage before it can become their source material.
    """
    def _terms(value: str) -> set[str]:
        return {w for w in re.findall(r"[a-z0-9]+", str(value or "").lower())
                if len(w) > 2 and w not in _SPEAKBOX_TOPIC_STOP}

    asked = _terms(topic)
    found = _terms(text)
    if asked & {"heat", "hot"}:
        asked.update({"burning", "heater", "temperature", "thermal", "warm"})
    if asked & {"computer", "dgx", "machine", "spark"}:
        asked.update({"device", "electricity", "engine", "fan", "power"})
    shared = sorted(asked & found)
    flat = " ".join(str(text or "").split()).strip()
    words = re.findall(r"[a-z0-9']+", flat.lower())
    # Vector chunks are sometimes cut at an arbitrary token boundary.  A
    # dangling half-sentence is not source material a caller can naturally
    # bring to a conversation, however good its embedding score may be.
    complete = bool(len(words) >= 5 and re.search(r"[.!?\u2026][\"')\]]*$",
                                                flat))
    return {
        "ok": bool(shared and complete),
        "shared": shared[:20],
        "topic_terms": len(asked),
        "text_terms": len(found),
        "coverage": round(len(shared) / max(1, len(asked)), 3),
        "complete": complete,
    }


async def speakbox_semantic_seed(query: str, exclude: str = "",
                                 who: str = "",
                                 rid: str = "",
                                 require_overlap: bool = False,
                                 avoid_files: set[str] | None = None,
                                 ) -> dict[str, Any]:
    """A seed dict shaped like speakbox_quote's, but drawn by MEANING off the
    vector index (#566) — so a round can be steered toward what is being talked
    about instead of a blind random pull. {} when the index is cold. Logs the
    retrieval telemetry for the booth read-out (#595) and which presenter
    reached for it (#640)."""
    key = mind_id(rid)
    t0 = time.time()
    # #786: Mind Topology gives the operator two levers over this draw — a
    # PIN (this person speaks from THAT document) that outranks the meaning
    # search, and BLOCKS (documents deleted from the memory) that never come
    # back off the index.
    pins = _RADIO.get("seed_pins") or {}
    blocks = set(_RADIO.get("seed_blocks") or [])
    pin = str(pins.get(who) or "")
    # Topic-bound calls need a wider shelf because the lexical relevance and
    # complete-sentence gates intentionally throw broad vector matches away.
    # The cosine scan is paid once either way; only the small returned shelf
    # grows here.
    k = 32 if require_overlap else 8
    hits = await speakbox_search(query, k=k, exclude=exclude, rid=key)
    # #815: crystals that are ON compete in the draw — their minds' best
    # chunk enters weighted by strength, so a switched-on crystal really
    # bends what the pair reach for.
    for _cr in crystal_active():
        # #973: and the same rule on THIS road. Filtering only the #834
        # swath would have been half a fix: this block appends the
        # crystal minds' best chunks at score*strength and re-sorts, so a
        # tint-only crystal at high strength would still win the seed and
        # its text would arrive by the other door.
        if not crystal_sources(_cr):
            continue
        _w = max(5, min(100, int(_cr.get("strength") or 50))) / 100.0
        for _rid in (_cr.get("minds") or []):
            if mind_id(_rid) == key:
                continue
            for _h in await speakbox_search(query, k=1, exclude=exclude,
                                            rid=_rid):
                hits.append({**_h,
                             "score": float(_h.get("score") or 0) * _w})
    hits.sort(key=lambda h: -float(h.get("score") or 0))
    if blocks:
        hits = [h for h in hits if h.get("file") not in blocks]
    if pin:
        pinned = [h for h in hits if h.get("file") == pin]
        if pinned:
            hits = pinned
        else:
            # Nothing in the pinned document matched the query — draw a
            # swath from it directly, because the pin is the point.
            chunks = [c for c in (_load_vectors(key).get("chunks") or [])
                      if c.get("file") == pin and c.get("text")]
            if chunks:
                drawn = random.choice(chunks)
                hits = [{"file": pin, "text": str(drawn.get("text") or ""),
                         "score": 1.0}]
    # A caller batch reserves its sources without marking them as aired.
    # An explicit operator pin still wins; otherwise keep the semantic draw
    # out of documents already attached to calls waiting in the FIFO queue.
    if avoid_files and not pin:
        avoided = {str(name or "") for name in avoid_files if str(name or "")}
        hits = [hit for hit in hits
                if str(hit.get("file") or "") not in avoided]
    if require_overlap:
        relevant: list[dict[str, Any]] = []
        for hit in hits:
            proof = speakbox_topic_relevance(
                query, str(hit.get("text") or ""))
            if proof.get("ok"):
                relevant.append({**hit, "topic_relevance": proof})
        hits = relevant
    if not hits:
        return {}
    # #824: argmax was DETERMINISTIC — the same winner every round until
    # the index changed. Sample the top hits by softmax(score/T) instead,
    # skipping anything the pair already said in the last day, so the
    # scour genuinely wanders the shelf.
    if len(hits) > 1 and not pin:
        _heard_day = {r.get("text") for r in speakbox_heard(key)[:4000]
                      if time.time() - int(r.get("last") or 0) < 86400}
        _cands = [h for h in hits[:8]
                  if h.get("text") not in _heard_day] or hits[:8]
        try:
            _t = 0.15
            _mx = max(float(h.get("score") or 0) for h in _cands)
            _ws = [pow(2.718281828,
                       (float(h.get("score") or 0) - _mx) / _t)
                   for h in _cands]
            hits = [random.choices(_cands, weights=_ws, k=1)[0]]
        except Exception:
            hits = [_cands[0]]
    text = hits[0]["text"]
    _vector_access_log(query, hits[0], int((time.time() - t0) * 1000),
                       len((_load_vectors(key).get("chunks") or [])), who=who)
    return {"file": hits[0]["file"], "text": text, "mind": key,
            "score": float(hits[0].get("score") or 0),
            "topic_relevance": dict(hits[0].get("topic_relevance") or {}),
            "lines": speakbox_lines(text) or [text]}


async def speakbox_index_clock() -> None:
    """Keep the vector index current while the station is on (#566) — new
    markdown is picked up within a couple of minutes, no restart, no click."""
    await asyncio.sleep(5)
    while _RADIO.get("on"):
        # Every mind, not only the one in play (#627): jumping to the other
        # brain should not mean waiting for it to be read. The mtime gate
        # makes an unchanged folder a stat() per file, and each mind is
        # wrapped on its own so a bad folder cannot stop the rest.
        for row in speakbox_minds():
            try:
                await speakbox_reindex(rid=row["id"])
            except Exception:
                continue
        await asyncio.sleep(120)


# --- The document lock (#674) ------------------------------------------------
# Everything the pair say is seeded from a swath of one document drawn at
# random out of the folder. That is right for a night of radio and wrong for
# an hour of study: when you want them ON something — one manual, one
# transcript, one book — the draw keeps wandering off it. The lock pins the
# draw to a single document and expires by itself, because a lock nobody
# remembers setting is worse than no lock.
DOC_LOCK_PATH = data_path("doc_lock.json")
_DOC_LOCK_MEM: dict[str, Any] = {}


def doc_lock_read() -> dict[str, Any]:
    """The live lock, or {} — an expired lock is not a lock."""
    row = _DOC_LOCK_MEM
    if not row:
        try:
            row = json.loads(DOC_LOCK_PATH.read_text())
        except Exception:
            row = {}
        _DOC_LOCK_MEM.update(row or {})
    if not row.get("doc"):
        return {}
    if float(row.get("until") or 0) <= time.time():
        return {}
    return dict(row)


def doc_lock_set(doc: str, hours: float = 1.0,
                 mind: str = "") -> dict[str, Any]:
    """Pin the draw to one document, or pass an empty name to let go."""
    _DOC_LOCK_MEM.clear()
    row: dict[str, Any] = {}
    if doc:
        row = {"doc": doc, "mind": mind,
               "until": time.time() + max(0.05, min(24.0, hours)) * 3600,
               "since": time.time()}
    _DOC_LOCK_MEM.update(row)
    try:
        DOC_LOCK_PATH.parent.mkdir(parents=True, exist_ok=True)
        tmp = DOC_LOCK_PATH.with_suffix(".tmp")
        tmp.write_text(json.dumps(row, indent=1))
        tmp.replace(DOC_LOCK_PATH)
    except OSError:
        pass
    return row


def _crystal_influence_note(mind: str, file: str, text: str,
                            kind: str = "round") -> None:
    """#822: the observatory's feed. Every time crystal material lands
    in somebody's mouth, one row records which crystal, which mind,
    which document, the words themselves, and who the material was
    staged for — the live wiring the 🌆 view draws as trajectories."""
    try:
        cr = None
        for c in crystal_active():
            if mind in (c.get("minds") or []):
                cr = c
                break
        if cr is None:
            return
        plan = _RADIO.get("plan") or {}
        if kind == "sfxguy":
            targets = ["sfxguy"]
        elif (str(plan.get("kind")) == "call"
              and time.time() - float(plan.get("at") or 0) < 300):
            targets = ["caller", "host", "cohost"]
        else:
            targets = ["host", "cohost"]
        ring = _RADIO.setdefault("crystal_influence", [])
        ring.append({"ts": int(time.time()),
                     "crystal": str(cr.get("name") or ""),
                     "strength": int(cr.get("strength") or 50),
                     "mind": mind, "file": str(file or ""),
                     "text": str(text or "")[:240], "kind": kind,
                     "targets": targets})
        del ring[:-80]
    except Exception:  # noqa: BLE001
        pass


_NO_DOCS: dict[str, float] = {}


async def speakbox_quote(exclude: str = "", most: int = 9, cap: int = 0,
                         rid: str = "", only: str = "",
                         tinted: bool = True) -> dict[str, Any]:
    """A swath out of one document, both drawn at random.

    The directory is read every time, so anything dropped in the folder is in
    their mouths on the next round — there is nothing to reload. Lines they
    have not used yet come first, and when a document has none left it is read
    again at a different point, so the material renews itself. `exclude`
    keeps a named document out of the draw — that is how the comeback comes
    from somewhere other than the drop (#233)."""
    # #788: when the OPERATOR has set a theme, the theme's chosen report
    # outranks everything else for its share of swaths — the clause
    # (#775) tells the pair the subject, but the SEED material is what a
    # small model actually follows, and it kept arriving from elsewhere.
    if not rid and not only:
        _thm = theme_owns_air()
        if _thm:
            _trows = themes_read()
            _tdoc = str(_trows.get("doc") or "")
            _tp = max(0, min(100, int(_trows.get("strength")
                                      or 70))) / 100.0
            _troll = random.random() < _tp
            if _troll and not _tdoc:
                # No report chosen: the shelf documents most ABOUT the
                # theme stand in, so the theme owns its material either
                # way.
                #
                # 2026-09-10: k=1 IS NOT A DRAW, IT IS A CONSTANT. The
                # index does not move between rounds, so the same query
                # returned the same single document every time - and this
                # branch fires on `strength`% of ALL draws (84% here), so
                # it pinned the whole night to one file. Measured live:
                # 94.7% of the last hour's swaths came out of vil1.md,
                # 70.0% of the last six hours, out of 317 documents on
                # the shelf. The operator heard that as "no randomness
                # with the chunks chosen from the speakerbox", and every
                # anti-domination gate below - the weighted draw, the
                # six-document rotation, the oldest/newest band dives -
                # was being walked straight past by this one assignment.
                #
                # speakbox_search returns ONE swath per document (#566),
                # so k documents really are k different documents. Take a
                # BAND of them and re-roll per draw: the theme still owns
                # the subject, it no longer owns a single file.
                try:
                    _hits = await speakbox_search(
                        str(_thm.get("text") or _thm.get("name") or ""),
                        k=SPEAKBOX_THEME_BAND)
                    _pool = [str(h.get("file") or "")
                             for h in (_hits or []) if h.get("file")]
                    if _pool:
                        # Nearer the subject is likelier, but nothing is
                        # certain: rank r weighs (n - r), so the best
                        # match leads the band without owning it.
                        _n = len(_pool)
                        _tdoc = random.choices(
                            _pool, weights=[_n - i for i in range(_n)],
                            k=1)[0]
                    else:
                        _tdoc = ""
                except Exception:  # noqa: BLE001
                    _tdoc = ""
            if _tdoc and _troll:
                only = _tdoc
                pipeline_log("speakbox", "the swath is tonight's SUBJECT "
                             f"\u2014 {_thm.get('name')} via {_tdoc} "
                             "(#788)")
    # #907: a storyline that owns the half hour steers the MATERIAL as
    # well as the prompt. #788 and #834 both learned the same lesson in
    # this same function — a small model obeys what is in its mouth far
    # harder than what is in its instructions — and a plot the operator
    # wrote is at least as much an instruction as a theme is. Only when
    # a theme has not already taken the draw, and never when a caller
    # named its own document.
    if not rid and not only and tinted:
        try:
            _plt = plot_owns_air()
            if _plt and random.random() < 0.45:
                _pact, _pat, _pof = plot_act_now(_plt)
                # #1176: A BAND, NOT A PIN - the same correction the theme
                # branch above was given this morning. k=1 against a static
                # index is a constant, and this branch owns 45% of every
                # draw while a story is on, so it undid that fix the moment
                # a storyline was switched on. speakbox_search returns one
                # swath per document, so k documents really are k different
                # documents; rank r weighs (n - r), which lets the closest
                # match lead the band without owning it.
                _phits = await speakbox_search(
                    str(_pact or _plt.get("title") or ""),
                    k=SPEAKBOX_THEME_BAND)
                _ppool = [str(h.get("file") or "")
                          for h in (_phits or []) if h.get("file")]
                _pn = len(_ppool)
                _pdoc = (random.choices(
                    _ppool, weights=[_pn - i for i in range(_pn)],
                    k=1)[0] if _ppool else "")
                if _pdoc:
                    only = _pdoc
                    pipeline_log("speakbox", "the swath serves the "
                                 f"storyline \u2014 act {_pat}/{_pof} of "
                                 f"\"{_plt.get('title')}\" via {_pdoc} "
                                 "(#907)")
        except Exception:  # noqa: BLE001
            pass                        # the story is colour, not the show
    # #834: a crystal that is ON tints the SOURCE, not just the prompt —
    # at the dial's strength the swath is drawn from the crystal's own
    # minds, so DOOM (or whoever) enters the pair's mouths as material,
    # which a small model obeys far harder than an instruction.
    # #891: `tinted=False` is the operator's own sliders talking — the
    # opening and closing passages are about HOW MUCH verbatim material
    # airs, not about which mind it comes from, so a crystal never takes
    # those draws away from the studio library.
    if not rid and not only and tinted:
        # #973: only crystals that are allowed to lend their WORDS get to
        # redirect the draw. The rest still tint the prompt through
        # crystal_clause(); they simply stop taking the swath away from
        # the studio library.
        _crs = [c for c in crystal_active() if crystal_sources(c)]
        _tint_only = [c for c in crystal_active() if not crystal_sources(c)]
        if _tint_only and not _crs:
            _to = _tint_only[0]
            round_mark(crystal=str(_to.get("name") or ""),
                       crystal_strength=int(_to.get("strength") or 0),
                       crystal_mind="")
            pipeline_log("speakbox", f"the {_to.get('name')} crystal is "
                         "tinting the writing, but the swath stayed in the "
                         "speakerbox (#973)")
        if _crs:
            _cr = random.choice(_crs)
            _p = max(5, min(100, int(_cr.get("strength") or 50))) / 100.0
            _minds = [m for m in (_cr.get("minds") or [])
                      if any(x["id"] == m for x in speakbox_minds())]
            if _minds and random.random() < _p:
                rid = random.choice(_minds)
                # #941: the tinting, written down — "crystal tinting" is
                # one of the four figures the operator asked to see at
                # the top of every call.
                round_mark(crystal=str(_cr.get("name") or ""),
                           crystal_strength=int(_cr.get("strength") or 0),
                           crystal_mind=str(rid))
                pipeline_log("speakbox", "the swath comes from the "
                             f"{_cr.get('name')} crystal ({rid}) — the "
                             "universe is tinted (#834)")
    # #895: how deep to dig, this draw. Zero when the shelf is cold,
    # and every use of it below scales from zero — so an empty pantry
    # gets exactly the draw it always got.
    _depth = box_depth()
    if _depth > 0.05:
        # A longer swath and a bigger budget: "saying more and more
        # obscure things as they talk about the current topic at hand"
        # is partly just MORE of the passage, taken from further in.
        most = max(1, int(round(most * (1.0 + 0.6 * _depth))))
        cap = int(round((cap or SPEAKBOX_SWATH_MAX)
                        * (1.0 + 0.5 * _depth)))
    # #1083: AND THE SURPLUS ON TOP. #895's scaling is about digging
    # DEEPER into a document as the queue builds; this is about taking
    # MORE of it when the station can afford to. Handing the pair more
    # of the operator's own words is the one change measured to alter
    # what a small model writes.
    try:
        _extra = surplus()
        if _extra > 0.02:
            most = max(1, int(round(most * (1.0 + 0.8 * _extra))))
            cap = int(round((cap or SPEAKBOX_SWATH_MAX)
                            * (1.0 + 0.6 * _extra)))
    except Exception:  # noqa: BLE001
        pass
    key = mind_id(rid)
    files = [p for p in speakbox_files(key) if p.name != exclude]
    if not files:
        files = speakbox_files(key)     # one document beats none
    if not files:
        # #1078: AND IT SAYS SO. The crystal redirect above can point
        # this at a mind whose folder holds no *.md at all - the glob
        # is markdown only, so a folder of .txt is empty as far as the
        # station is concerned. At a grounding rate of 1.0 the gate
        # passes, this returns nothing, and the round goes out unseeded
        # with no event of any kind. That was the only completely
        # invisible way a fully-grounded round could lose its material.
        try:
            _seen = str(key or "the studio")
            if time.time() - float(_NO_DOCS.get(_seen) or 0) > 300:
                _NO_DOCS[_seen] = time.time()
                pipeline_log("speakbox",
                             f"(#1078) the {_seen} mind has no documents "
                             "the station can read - this round goes out "
                             "with no material. The speakbox reads *.md "
                             "only")
        except Exception:  # noqa: BLE001
            pass
        return {}
    # #674: while a lock is on, every seed comes from that one document —
    # including the `exclude` case, because the point of the lock is that
    # they stay ON it and a comeback from somewhere else breaks exactly the
    # thing you turned it on for.
    lock = doc_lock_read()
    if lock.get("doc"):
        pinned = [p for p in speakbox_files(key) if p.name == lock["doc"]]
        if pinned:
            files = pinned
    # #766: this ONE report, because a caller was told to ring in citing it.
    # Deliberately AFTER the station-wide lock and therefore ahead of it: the
    # lock is a standing instruction about where material comes from, and
    # this is a specific one about what a particular caller has read. The
    # narrower, more recent instruction wins, and only for that caller —
    # every other seed in the show still obeys the lock.
    if only:
        want = [p for p in speakbox_all(key) if p.name == only]
        if want:
            files = want
    # Drawn by weight, so the documents you have pushed up come round more
    # (#209) — but never the same one twice running while another is willing,
    # because plain weighted chance on three documents repeats a third of the
    # time and it stops sounding like a folder.
    weights = mind_weights(key)
    _uses = speakbox_uses(key)                                   # #1193
    first = unrepeated(
        random.choices([p.name for p in files],
                       weights=[speakbox_weight(p.name, weights, key, _uses)
                                for p in files], k=len(files)),
        # Six documents wait their turn before one comes round again
        # (#360) — three still let a big folder sound like a small one.
        # #895/#901: six documents wait their turn at rest — and MORE
        # of them as the pantry fills, which is the same "dig deeper as
        # the queue builds" dial #895 already turns on the swath length
        # and the archive dive, extended to the draw itself rather than
        # duplicated beside it. A deep shelf can afford to reach right
        # across the folder; a cold one keeps the rotation it had.
        f"doc:{key}", keep=max(1, min(len(files) - 1,
                                      int(round(6 + 10 * _depth)))))
    # Now and then, dive into the ARCHIVE instead (#478): lead with one of
    # the oldest documents so the deepest, most-forgotten material gets mined
    # and mixed back in — the swath itself already starts at a random (often
    # deep) point, so this reaches the obscure sections of old files.
    # #895: and the ARCHIVE dive gets likelier the deeper the queue —
    # a quarter of draws at rest, better than half of them once the
    # horizon is covered. The oldest documents are where the obscure
    # material is; they are only rarely worth the risk when the show is
    # living hand to mouth, and always worth it when it is not.
    # #1039: A BAND, NOT THE ONE FILE. Both of these used to assign the
    # single extreme - THE oldest document, THE newest - and both wrote
    # `first` directly, walking past the unrepeated() rotation that
    # exists to stop one document owning the show. At rest they fire on
    # 0.25 + 0.75 * 0.32 = 49% of draws, so half the night came out of
    # two files: measured, one document took 55 of 133 draws while 68
    # others split the rest two apiece. Reaching into the oldest sixth
    # (or newest sixth) keeps both dives doing exactly what they were
    # for and gives the rotation its documents back.
    def _band(pool: list[Any], oldest_end: bool) -> str:
        ranked = sorted(pool, key=lambda q: q.stat().st_mtime
                        if q.exists() else 0)
        wide = max(2, min(len(ranked), round(len(ranked) / 6) or 2))
        band = ranked[:wide] if oldest_end else ranked[-wide:]
        return random.choice(band).name

    if len(files) > 2 and random.random() < (0.25 + 0.30 * _depth):
        first = _band(files, True)
    elif len(files) > 2 and random.random() < 0.32:
        # Freshly-added documents get scoured PROMPTLY (#547): lead with the
        # newest so anything just dropped in the folder is in their mouths
        # soon, not lost behind the weighted rotation.
        # #1039: ...the newest SIXTH. See _band above.
        first = _band(files, False)
    order = ([p for p in files if p.name == first]
             + random.sample([p for p in files if p.name != first],
                             len(files) - 1))
    said = {r.get("text") for r in speakbox_heard(key)}
    exhausted: tuple[str, list[str]] | None = None
    _spent: list[tuple[str, list[str]]] = []      # #1177: every used-up doc
    # #1039: was order[:3] - and since the first document holding a
    # single unused line ends the search, "three were mined" was almost
    # always "one was mined". Six, so an exhausted document costs a look
    # rather than the whole draw.
    for doc in order[:6]:               # a doc of pure headings is not fatal
        gems = speakbox_gems(doc, key)
        # 2026-09-08 (the scan): a stub the old window cut mid-word is not
        # fresh material (_gem_is_stub); the shelf re-harvests sooner instead.
        fresh = [line for line in gems
                     if line not in said and looks_english(line) and not _gem_is_stub(line)]
        if not fresh:
            # Nothing left they have not used: read the document again at a
            # different point rather than repeat themselves.
            gems = await speakbox_harvest(doc, key) or gems
            if not gems:                # the model is down; the show is not
                gems = speakbox_lines(speakbox_body(doc))
            fresh = [line for line in gems
                     if line not in said and looks_english(line) and not _gem_is_stub(line)]
        if fresh:
            # #1042: among lines that have never aired, the ones resting
            # longest lead. The no-repeat set above answers "has this
            # ever been said"; this answers "and how long ago", which is
            # the question that keeps a shelf moving rather than just
            # keeping it honest. Adjacency still decides the swath - this
            # only chooses where in the document to stand.
            fresh = chunk_rank(fresh, lambda ln: ln)
            lines = speakbox_swath_lines(fresh, most=most, cap=cap,
                                         deep=_depth)
            for _ln in lines:
                chunk_serve("speakbox", _ln, file=doc.name,
                            mind=str(key or ""), road="seed")
            pipeline_log("speakbox",
                         f"mined {doc.name} — {len(fresh)} unused lines "
                         f"on the shelf, swath of {len(lines)} taken",
                 extra=("THE SWATH, word for word:\n- "
                        + "\n- ".join(lines)
                        + f"\n\nDecision: {doc.name} won the weighted "
                        "draw; consecutive unused lines taken so the "
                        "thought stays whole. Once aired these are "
                        "marked heard and will not repeat until the "
                        "shelf runs dry."))
            _crystal_influence_note(key, doc.name, " ".join(lines))
            # #941: which document, how many lines, and how hard the box
            # was being pushed when this swath was drawn.
            round_mark(seed_file=doc.name, seed_lines=len(lines),
                       seed_chars=len(" ".join(lines)),
                       seed_mind=str(key or ""),
                       seed_depth=round(_depth, 3),
                       seed_most=int(most), seed_cap=int(cap))
            return {"file": doc.name, "text": " ".join(lines),
                    "lines": lines, "mind": key}
        if gems:
            # #1177: collect them ALL. Keeping only the first one tripped
            # over made the repeat road a near-constant, which is how one
            # line reached 289 airings.
            _spent.append((doc.name, gems))
            if exhausted is None:
                exhausted = (doc.name, gems)
    # Every document tried is used up (#268). The least recently aired
    # lines come back rather than the show going quiet — but repetition is
    # now the LAST resort, after three documents were mined for anything
    # new, not the second choice inside the first one. Sorted by age, so
    # even the repeats are the oldest material on the shelf; the swath
    # loses strict adjacency here, which a re-run can afford.
    if exhausted:
        last = {r.get("text"): int(r.get("last") or 0)
                for r in speakbox_heard(key)}
        # #1177: of the documents that are used up, the one whose material
        # has been left alone longest goes first - "least recently aired"
        # applied to the document as well as to the line. A tie is broken
        # at random rather than by loop order.
        if len(_spent) > 1:
            def _age(row: tuple) -> float:
                _lines = row[1] or []
                return (min(int(last.get(ln) or 0) for ln in _lines)
                        if _lines else 0)
            _oldest = min(_age(r) for r in _spent)
            exhausted = random.choice(
                [r for r in _spent if _age(r) <= _oldest + 1.0]) or exhausted
        name, gems = exhausted
        pool = sorted(gems, key=lambda line: last.get(line, 0))
        # #no-repeats: this branch deliberately serves lines they HAVE used, which is
        # a verbatim repeat injected upstream of every gate — the swath goes
        # into the script as "A: ..." and is read out word for word. The
        # cooldown gets the last word here too: anything said inside the hour
        # is not eligible, however old it is relative to the rest.
        # #901: and the LINE window on top of the phrase cooldown.
        # This branch is the one place in the file that knowingly serves
        # material it has already aired, and it answered to the phrase
        # gate alone — which measures runs of words over an hour, not
        # whole lines over the three to five he asked for. The swath
        # goes into the script as "A: ..." and is read out word for
        # word, upstream of every gate, so this is the gate.
        cooled = [line for line in pool
                  if not phrase_check(line).get("block")
                  and not air_repeat_check(line).get("block")]
        if not cooled:
            # Everything left is inside the window. The show does not
            # stop for that — the oldest material still airs — but it is
            # a real fault the operator can fix by adding documents, and
            # it used to happen in complete silence. Measured: 20.7% of
            # speakbox airings were repeats, one line used 289 times.
            pipeline_log("speakbox",
                         f"{name} is exhausted and every line left on it "
                         "is still inside the rejection window — airing "
                         "the least recently used anyway. Add documents "
                         "to the speakbox (#901)")
        pool = cooled or pool
        lines = speakbox_swath_lines(pool[:max(most * 2, 12)],
                                     most=most, cap=cap, deep=_depth)
        return {"file": name, "text": " ".join(lines), "lines": lines,
                "mind": key}
    return {}


# How much of the document goes in their mouths at once. One sentence was a
# remark; he asked for the whole swath (#210), so a run of consecutive lines
# goes in together and comes out across as many turns as it takes.
SPEAKBOX_SWATH_MAX = 1100

# 2026-09-10: how many DIFFERENT documents a theme with no chosen report
# may draw from. One is a pin, not a draw - see the note in
# speakbox_quote. speakbox_search hands back one swath per document, so
# this is a count of documents, and the band is re-rolled every draw.
SPEAKBOX_THEME_BAND = 12


def swath_best(picks: list[dict[str, Any]]) -> dict[str, Any]:
    """#1177: the more intriguing swath LEADS; it does not own.

    `max(picks, key=swath_intrigue)` is a rank filter, not a draw:
    swath_intrigue is a pure function of the text and knows nothing about
    what has aired, so the same long question-bearing passages win their
    heat every time they are drawn and the air concentrates on a
    persistent top slice of the corpus. Weighted by score, the better one
    is likelier and the other is still possible - the same correction the
    theme band was given."""
    rows = [p for p in (picks or []) if p and str(p.get("text") or "").strip()]
    if not rows:
        return {}
    if len(rows) == 1:
        return rows[0]
    try:
        scores = [max(0.01, float(swath_intrigue(str(p.get("text") or ""))))
                  for p in rows]
        return random.choices(rows, weights=scores, k=1)[0]
    except Exception:  # noqa: BLE001
        return max(rows, key=lambda p: swath_intrigue(str(p.get("text") or "")))


def speakbox_swath_lines(pool: list[str], most: int = 9,
                         cap: int = 0, deep: float = 0.0) -> list[str]:
    """A run of consecutive lines out of the pool, not a single sentence.

    Consecutive matters: the gems were split out of one passage in order, so
    taking neighbours keeps the thought whole instead of stapling two
    unrelated remarks together. Returned as the lines themselves so each one
    can be remembered on its own (#235).

    #895: `deep` pushes the start toward the BACK of the document. A
    flat random start lands in the opening pages as often as anywhere,
    and the opening pages of a report are its abstract — the most
    quoted, least surprising part of it. "More and more obscure things"
    means the middle and the end of an old file, so as the queue builds
    the draw is taken from further in."""
    if not pool:
        return []
    cap = cap or SPEAKBOX_SWATH_MAX
    deep = max(0.0, min(1.0, float(deep or 0.0)))
    # #1041: THE LAST START AT WHICH A FULL SWATH STILL FITS. Drawing
    # the start across the whole pool means every start in the last
    # `most` positions returns a short swath - measured, a 2600-character
    # setting delivering 939 at its best and one line at its worst - and
    # `deep` made it worse by design, since it exists to push the start
    # toward the back where the fewest lines remain. A pool smaller than
    # the ask is unchanged: it had one honest answer already.
    last = max(1, len(pool) - max(1, int(most)) + 1)
    floor = int(last * 0.55 * deep)             # 0 at rest — unchanged
    start = (random.randrange(min(floor, last - 1), last)
             if floor else random.randrange(last))
    swath = [pool[start]]
    for line in pool[start + 1:start + most]:
        if len(" ".join(swath)) + len(line) + 1 > cap:
            break
        swath.append(line)
    return swath


def speakbox_swath(pool: list[str], most: int = 9) -> str:
    return " ".join(speakbox_swath_lines(pool, most))


# #1174: how many DIFFERENT documents a round is seeded from, beyond its
# primary swath. Three is a conversation; one is a recital.
SPEAKBOX_SPREAD = int(os.getenv("PINE_SPEAKBOX_SPREAD", "3"))


async def speakbox_spread(seen: Any = None, want: int = 0,
                          most: int = 5, cap: int = 520
                          ) -> list[dict[str, Any]]:
    """#1174: several swaths, each from a DIFFERENT document.

    `speakbox_quote` draws one document at a time and honours `exclude`,
    so asking it repeatedly while feeding back everything already drawn
    gives distinct files without touching the picker. A draw that lands
    on a file already held is simply dropped - the shelf has three
    hundred documents on it and the next ask will find another."""
    held = {str(f) for f in (seen or []) if f}
    out: list[dict[str, Any]] = []
    want = max(0, int(want or SPEAKBOX_SPREAD))
    for _ in range(want * 3):
        if len(out) >= want:
            break
        try:
            got = await speakbox_quote(
                exclude=",".join(sorted(held)) if held else "",
                most=most, cap=cap)
        except Exception:  # noqa: BLE001
            break
        name = str((got or {}).get("file") or "")
        text = str((got or {}).get("text") or "").strip()
        if not text or (name and name in held):
            continue
        if name:
            held.add(name)
        out.append(got)
    return out


def speakbox_spread_clause(spread: list[dict[str, Any]]) -> str:
    """#1174: the spread, handed over as separate things to talk about.

    Deliberately NOT phrased like `speakbox_aside`. That clause says
    "deliver these word for word and soak everything else in them", which
    is right for ONE passage and wrong for four - four passages delivered
    verbatim is a recital, not a round. These are offered as things the
    pair have each run into, to be argued with, connected, contradicted
    and used."""
    rows = [r for r in (spread or []) if str((r or {}).get("text") or "").strip()]
    if not rows:
        return ""
    body = "".join(
        "\n  (%d) \"%s\"" % (i + 1, str(r.get("text") or "")[:520])
        for i, r in enumerate(rows))
    return (
        "\n\nAND YOU HAVE EACH RUN INTO SOMETHING ELSE. These came from "
        "%d different places and they are not connected to each other:"
        % len(rows) + body +
        "\nBring them into the conversation as your OWN thoughts and your "
        "own words - a thing you read, a thing you heard, a thing you have "
        "been chewing on. You may quote a phrase from one if it is worth "
        "quoting, but do not recite them and never say where any of it came "
        "from. Set them AGAINST each other: let one of you raise one, the "
        "other answer with a different one, and find the argument between "
        "them. Two people who have read the same one thing can only agree; "
        "the point of these is that you have read different things.")


def speakbox_aside(quote: dict[str, str], pair: bool = True) -> str:
    """The same trick for one line rather than a whole round: the words go
    out, where they came from never does."""
    return (
        "\n\nYou also have lines to deliver, and they go out WORD FOR WORD, "
        "exactly as written, as your own speech — every sentence, in order, "
        "complete, worked into what you were asked for above, which still "
        "has to be said. Never call them a quotation, never say where they "
        f"came from, never name anyone: \"{quote['text']}\""
        # Only a round has a second mouth in it. Told to make the other one
        # answer, a single line comes back either as a rhetorical question
        # into dead air or with a literal "B:" in it, which the box then
        # reads out as "B colon" (#207).
        + (f" Whoever hears it must {unrepeated(list(SPEAKBOX_ENGAGE), 'engage')}"
           " rather than let it pass." if pair else
           " You are on your own here — one voice, no second speaker, and no "
           "speaker labels of any kind in what you write.")
        + " Beyond the quoted lines, let everything else you say be soaked "
        "in that passage: its subject, its attitude, its vocabulary."
        # #845: WHERE they go was never specified, and a small model
        # reads "say this word for word" as permission to recite it in a
        # block at one end of the round. Interjected is the word the
        # operator used.
        + " Thread them INTO the conversation at the point they land —"
        " interjected mid-discussion, answering or provoking what is"
        " being said around them — never parked at the start or the end"
        " as a block, and never read out as a passage. A listener should"
        " hear one of you making a point, not reciting something."
    )


# How the gem arrives. It is never announced as a quotation — it lands as
# something one of them has decided to say, and the other has to live with it.
SPEAKBOX_DROPS = (
    "drops it into a gap, dead flat, as though it followed from what was "
    "just said",
    "says it straight over the top of {other}, mid-sentence",
    "says it to the listeners rather than to {other}, who is sitting right "
    "there",
    "insists it is something {other} said last week and has never taken back",
    "reads it out as though it had just come in from a listener",
    "says it and then refuses to explain it, however hard {other} presses",
    "puts it about as a note that came down from management upstairs",
    "says it and then says it again, slower, as though {other} were the "
    "problem",
    "works it into what they were already saying as if {other} should have "
    "known it was coming",
    "says it as their considered professional opinion",
    "asks {other} to agree with it, on air, right now",
    "says it, and then blames {other} for making them say it",
)

# What it does to the other one. Every round draws a different temperature,
# which is what stops the pair being amused by everything.
SPEAKBOX_REACTIONS = (
    "genuinely blindsided, and unable to hide it from the listeners",
    "quietly furious, staying professional through gritted teeth",
    "completely lost, asking what that was even supposed to mean",
    "exasperated, because this is the third time this week",
    "delighted, and immediately making it worse",
    "wounded, taking it far more personally than it deserves",
    "convinced they are being wound up, and looking for the catch",
    "unnerved, and trying very hard to move the show along",
    "appalled, and worrying aloud about who might be listening",
    "openly furious, and letting it show on air",
    "so baffled they get the words wrong repeating them back",
    "pretending not to have heard it, and failing",
    "sure they know exactly what was meant, and explaining it at length",
    "taking it as a challenge and going one further",
)

# Whatever the temperature, the other one has to actually deal with it: answer
# it, run with it, or say what they think it means. Changing the subject is
# what made the pair sound like two people reading from different scripts
# (#207).
SPEAKBOX_ENGAGE = (
    "answer it directly, as though it were a point being made",
    "play along with it and take it one step further",
    "say what they think it actually means, and be wrong about it",
    "demand to know where that came from, and not let it drop",
    "argue with it on its own terms",
    "agree far too readily, which is its own kind of trouble",
    "relate it to something on this show, out loud",
    "ask a follow-up question about it and wait for the answer",
    # Intrigue, suspense, anger — he asked for those by name (#223).
    "be openly intrigued and press for the rest of it",
    "let the suspense of it sit, then say the quiet part",
    "get angry about it, properly angry, and say why",
    "treat it as a confession and ask how long this has been going on",
)

# Now and then one of them holds the floor: the whole passage delivered as a
# speech, the other one waiting, and the reaction landing at the end of it
# rather than in the middle (#223).
SPEAKBOX_MONOLOGUE = (
    "{first} takes the floor and does not give it back until the whole thing "
    "is said — several lines of it, one after another, {other} unable to get "
    "a word in until the end",
    "{first} tells it as a story, start to finish, taking as many lines as it "
    "needs, and only then does {other} get to speak",
    "{first} builds it slowly, holding the best of it back, and {other} has "
    "to wait through all of it",
)


def doc_recognition(other: str, file: str) -> str:
    """#577: a later beat where the OTHER host recognises the passage came out
    of the station's documents, they have a short funny debate about it, and
    settle it by NAMING the document to each other. Returns '' when there is no
    usable source name. Kept as an OCCASIONAL beat so the immersive default
    (lines delivered as their own) still rules most rounds."""
    title = re.sub(r"\.(md|txt|markdown)$", "", str(file or ""),
                   flags=re.I).replace("-", " ").replace("_", " ").strip()
    if not title or title.lower() in ("a pushed note", "speakbox"):
        return ""
    return (
        f" LATER — after it has landed as {other} kept listening — {other} "
        "pulls up short and calls it out: 'hold on… did you just say what I "
        "think you said? That's not you talking — that's straight out of one "
        "of our documents, isn't it?' They have a short, funny back-and-forth "
        "about whether it really came off the reading pile, the other playing "
        "innocent at first — and they settle it by NAMING the document out "
        f"loud to each other: it is from “{title}”. Then they get "
        "back into it.")


def speakbox_scene_angle(seed: dict[str, str],
                         pivot: dict[str, str] | None = None,
                         jab: dict[str, str] | None = None) -> str:
    """An entire moment recreated on air (#252, #253).

    One of them performs a whole passage word for word — whole cloth,
    unadulterated, without mercy — and the other spends the ENTIRE
    conversation coming to terms with it, through a funny struggle arc, then
    swerves it somewhere nobody saw coming with a passage of their own from
    a different document. Optionally a third lands as the last word."""
    first = random.choice(["A", "B"])
    other = "B" if first == "A" else "A"
    angle = (
        f"{first} recreates an entire moment on air, WHOLE CLOTH: the "
        "passage below is performed word for word, unadulterated, without "
        f"mercy — every sentence, in order, as {first}'s own lived truth, "
        f"across as many turns as it needs: \"{seed['text']}\" Never call "
        "it a quotation, never say where it came from. "
        f"{other} is blown away and spends the WHOLE conversation coming to "
        f"terms with it: first "
        f"{unrepeated(list(SPEAKBOX_REACTIONS), 'reaction')}, refusing to "
        "believe what was just said; then demanding details and getting "
        "more than anyone asked for; then trying to move the show along and "
        "failing; and at last managing a real comeback that makes the "
        "conversation richer. Let the struggle be funny."
    )
    if pivot and pivot.get("text"):
        angle += (
            f" Midway, {other}'s comeback swerves the conversation somewhere "
            "nobody saw coming: it carries this OTHER passage, word for "
            f"word, complete, as {other}'s own: \"{pivot['text']}\" — "
            f"which now blindsides {first} in turn.")
    if jab and jab.get("text"):
        angle += (
            f" And just before the end, {random.choice([first, other])} "
            "lands this, word for word, as the last word: "
            f"\"{jab['text']}\"")
    if random.random() < 0.35:               # #577: caught quoting a document
        angle += doc_recognition(other, seed.get("file", ""))
    return angle + (
        " Beyond the quoted passages, everything said this round is soaked "
        "in their subject, their attitude and their vocabulary. Play the "
        "whole conversation out of that.")


def speakbox_angle(quote: dict[str, str],
                   comeback: dict[str, str] | None = None) -> str:
    """One of them delivers the lines, and the other has to wear it.

    The lines land word for word: the harvest already repaired them into
    clean English, and half-remembered paraphrase was the one thing he kept
    not getting (#231, #232). Drop, reaction and who goes first are drawn
    separately and never twice running, so the same lines landing again are
    a different scene — and when there is a `comeback`, the other one answers
    with full lines out of a different document entirely (#233)."""
    first = random.choice(["A", "B"])
    other = "B" if first == "A" else "A"
    # A third of the time it is a speech rather than a line dropped in (#223).
    drop = (unrepeated(list(SPEAKBOX_MONOLOGUE), "monologue")
            if random.random() < 0.34
            else unrepeated(list(SPEAKBOX_DROPS), "drop"))
    drop = drop.format(first=first, other=other)
    # A monologue names its own speaker; the shorter drops do not.
    drop = re.sub(rf"^{first} ", "", drop)
    angle = (
        f"{first} has lines to deliver, and they go out WORD FOR WORD, "
        f"exactly as written, as {first}'s own speech: \"{quote['text']}\" "
        "Say every one of those sentences, in that order, complete — worked "
        "into the flow of the show, not read as a list. Take as many turns "
        "as it needs. Never call them a quotation, never say where they came "
        f"from, never name whoever said them first. Then {first} {drop}. "
        f"{other} is {unrepeated(list(SPEAKBOX_REACTIONS), 'reaction')}, and "
        f"must {unrepeated(list(SPEAKBOX_ENGAGE), 'engage')} — in the very "
        f"next line, before anything else. {other} does not change the "
        "subject, does not ignore it, and does not move the show along until "
        "it has been dealt with."
    )
    if comeback and comeback.get("text"):
        angle += (
            f" And {other}'s answer carries these lines of {other}'s OWN, "
            f"word for word, complete, mixed into what {other} says back: "
            f"\"{comeback['text']}\" — from somewhere else entirely, never "
            "explained, delivered as though it settled the matter."
        )
    if random.random() < 0.35:               # #577: caught quoting a document
        angle += doc_recognition(other, quote.get("file", ""))
    return angle + (
        " Beyond the quoted lines, let the WHOLE round be soaked in that "
        "passage — its subject, its attitude, its vocabulary — so everything "
        "either of you says this round comes from that world. Play the rest "
        "of the round out of that.")


# Piper's English voices, split by the voice's apparent gender. Only names
# that actually exist on this box are used — the list is filtered against the
