def _sfxguy_voice(voice: str = "") -> str:
    """The database KEY: every assigned voice keeps its own quip shelf,
    so swapping the SFX guy's voice swaps his whole vocabulary — and
    each shelf can be sharpened separately over time."""
    v = re.sub(r"[^A-Za-z0-9_-]", "", str(voice or "").strip())
    if not v:
        v = re.sub(r"[^A-Za-z0-9_-]", "",
                   str(dj_settings().get("drop_voice") or ""))
    return (v or "default")[:40]


def sfxguy_quips(voice: str = "") -> list[str]:
    v = _sfxguy_voice(voice)
    for path in (SFXGUY_QUIPS_DIR / f"{v}.json",
                 SFXGUY_QUIPS_DIR.with_suffix(".json")):  # pre-#835b file
        try:
            rows = json.loads(path.read_text())
            if isinstance(rows, list) and rows:
                return [str(r)[:200] for r in rows]
        except Exception:
            pass
    return list(SFXGUY_SEED_QUIPS)


def sfxguy_quips_save(rows: list[str], voice: str = "") -> None:
    v = _sfxguy_voice(voice)
    SFXGUY_QUIPS_DIR.mkdir(parents=True, exist_ok=True)
    tmp = SFXGUY_QUIPS_DIR / f"{v}.json.tmp"
    tmp.write_text(json.dumps(rows[:500], indent=1))
    tmp.replace(SFXGUY_QUIPS_DIR / f"{v}.json")


SFXGUY_SAID_PATH = data_path("sfxguy_said.json")
_SFXGUY_WARPED: list[str] = []
_SFXGUY_FILLING = [False]


from sfx_speech_bank import SfxSpeechBank, REACTION_SOURCES

_SFX_READY_BANK = SfxSpeechBank(data_path("sfxguy_speech.json"), VOICE_MEDIA_DIR)
_SFX_READY_LOCK = asyncio.Lock()
_SFX_RESERVE_WRITING: ContextVar[bool] = ContextVar("sfx_reserve_writing", default=False)
_SFX_READY_STATE: dict[str, Any] = {"made": 0, "why": "Waiting for the SFX speaker's preparation slot"}


def _sfxguy_ready_profile() -> str:
    """Bind persisted proof to the current Crystal and grading contract."""
    # Preserve the recorded SFX bank's profile across pronunciation additions.
    # Readiness still checks the take's proof, exact text and current rhyme.
    return hashlib.sha256(json.dumps({"crystal": continuity_crystal(),
        "force": crystal_force(), "coverage": crystal_coverage_target(),
        "wanted": dialogue_tint_wanted(), "strict_rhyme": crystal_grade_strict(),
        "grade_version": 6}, sort_keys=True).encode()).hexdigest()[:24]


def _sfxguy_ready_valid(row: dict[str, Any], voice: str = "") -> bool:
    """Pure readiness check: never repair, render or consume a pantry row."""
    voice = str(voice or dj_settings().get("drop_voice") or "")
    text = str(row.get("text") or "").strip()
    engine = voice_engine_for(voice) if voice else ""
    if (not text or row.get("who") != "drop" or row.get("voice") != voice
            or row.get("profile") != _sfxguy_ready_profile()
            or row.get("recorded_text") != text or row.get("recorded_voice") != voice
            or row.get("engine") != engine
            or row.get("key") != pantry_key(text, voice, engine)
            or row.get("review_cancel_pending") or row.get("off_brief")
            or not _SFX_READY_BANK.media_ready(row)):
        return False
    if dialogue_tint_wanted():
        if (not row.get("tint_ok") or not tint_coverage_ready(row.get("tint"))
                or row.get("tint_text_hash") != hashlib.sha256(text.encode()).hexdigest()
                or not rap_rhyme_evidence(text).get("ok")):
            return False
    return True


def sfxguy_ready_pick(context: str = "", voice: str = "") -> dict[str, Any] | None:
    """Reserve one already recorded whole line for the strict saved-take path."""
    current = str(dj_settings().get("drop_voice") or "")
    if not current or (voice and voice != current):
        return None
    try:
        row = _SFX_READY_BANK.pick(context, current, _sfxguy_ready_profile(),
                                  lambda item: _sfxguy_ready_valid(item, current))
        if row:
            row["seconds"] = float(row["clip"]["seconds"])
        return row
    except Exception:
        return None                      # Optional interjections never abort the hosts.


def sfxguy_ready_commit(identity: str) -> bool:
    try:
        return _SFX_READY_BANK.finish(identity, heard=True)
    except Exception:
        return False


def sfxguy_ready_release(identity: str) -> bool:
    try:
        return _SFX_READY_BANK.finish(identity, heard=False)
    except Exception:
        return False


def _sfxguy_ready_status(voice: str = "") -> dict[str, Any]:
    """Inspect stock and receipts without starting any preparation work."""
    current = str(voice or dj_settings().get("drop_voice") or "")
    rows = _SFX_READY_BANK.rows(current, _sfxguy_ready_profile())
    ready = [row for row in rows if row.get("state") == "ready" and _sfxguy_ready_valid(row, current)]
    failed = sorted((row for row in rows if row.get("why") and row not in ready),
                    key=lambda row: float(row.get("last_attempt") or 0), reverse=True)
    full = len(_SFX_READY_BANK.rows()) >= _SFX_READY_BANK.capacity
    return {**_SFX_READY_STATE, "voice": current, "total": len(rows),
        "capacity_exhausted": full,
        **({"why": "The retained SFX bank reached its capacity; no current-profile sources could be admitted"}
           if full and not rows else {}),
        "ready": len({row["text"] for row in ready}),
        "waiting": sum(row.get("state") != "suspended" and row not in ready for row in rows),
        "suspended": sum(row.get("state") == "suspended" for row in rows),
        "reserved": sum(float(row.get("reserved_until") or 0) > time.time() for row in rows),
        "heard": sum(int(row.get("plays") or 0) for row in rows),
        "last_failures": [{key: row.get(key) for key in ("id", "state", "why", "attempts", "retry_at")}
                          for row in failed[:8]],
        "rows": [{key: row.get(key) for key in
                  ("id", "voice", "state", "why", "attempts", "retry_at", "seconds", "last_played", "plays")}
                 for row in rows]}


async def _sfxguy_tint_source(row: dict[str, Any], voice: str, profile: str) -> dict[str, Any]:
    # Periodic rejected admission never joins the model FIFO. Below two
    # distinct valid takes, admit at most one short reserve writer there;
    # retain the normal model, grader and global FIFO, with no priority jump.
    stocked = {" ".join(item["text"].lower().split())
               for item in _SFX_READY_BANK.eligible("", voice, profile,
                   lambda item: _sfxguy_ready_valid(item, voice))}
    token = _SFX_RESERVE_WRITING.set(len(stocked) < 2)
    try:
        return await _line_review_scoped(crystal_tint(
            row["text_plain"], "sfxguy", whole_only=True,
            progress=row.get("tint_progress"), critical=False),
            {"entry": copy.deepcopy(row), "entry_id": row["id"],
             "script_plain": row["text_plain"], "speaker": "drop"})
    finally:
        _SFX_RESERVE_WRITING.reset(token)


async def sfxguy_ready_prepare(limit: int = 1) -> dict[str, Any]:
    """One bounded background job: retain paid-for tint before seeking TTS."""
    if _SFX_READY_LOCK.locked():
        return {"made": 0, "why": "SFX speech preparation is already running"}
    voice = str(dj_settings().get("drop_voice") or "")
    if not voice or int(dj_settings().get("sfxguy_rate") or 0) <= 0:
        return {"made": 0, "why": "The SFX speaker is not enabled"}
    made, attempted = 0, 0
    why = "The SFX speech reserve is ready"
    async with _SFX_READY_LOCK:
        profile = _sfxguy_ready_profile()
        sources = [{"text": text, "generic": True} for text in REACTION_SOURCES]
        sources += [{"text": text, "generic": False} for text in sfxguy_quips(voice)[:16]]
        _SFX_READY_BANK.seed(voice, profile, sources)
        for row in _SFX_READY_BANK.due(voice, profile):
            if _sfxguy_ready_valid(row, voice):
                continue
            if attempted >= max(1, min(2, int(limit))):
                break
            if prep_should_stop() or not pantry_window():
                why = "Waiting for a spare recording-room window"
                break
            attempted += 1
            row["last_attempt"] = time.time()
            try:
                text = str(row.get("text") or "").strip()
                proof = (row.get("tint_ok") and tint_coverage_ready(row.get("tint"))
                         and row.get("tint_text_hash") == hashlib.sha256(text.encode()).hexdigest())
                if dialogue_tint_wanted() and not proof:
                    got = await _sfxguy_tint_source(row, voice, profile)
                    row["tint_progress"] = copy.deepcopy(got.get("progress") or {})
                    row["tint"] = _tint_paper(got)
                    if got.get("deferred"):
                        row.update(state="waiting", retry_at=time.time() + 60,
                                   why="A bounded writer is busy; the original source remains queued")
                        why = row["why"]
                        continue
                    text = _tint_out_clean(got.get("script") or "")
                    if not (got.get("ok") and text and rap_rhyme_evidence(text).get("ok")):
                        row["attempts"] = int(row.get("attempts") or 0) + 1
                        row.update(state="suspended" if row["attempts"] >= 3 else "waiting",
                                   retry_at=time.time() + 300, why="The full line still needs an accepted rhyme")
                        why = row["why"]
                        continue
                    row.update(text=text, tint_ok=True,
                               tint_text_hash=hashlib.sha256(text.encode()).hexdigest())
                    row.pop("tint_progress", None)
                    _SFX_READY_BANK.put(row)  # Do not lose accepted wording if recording is cancelled.
                if len(text) > 400 or not looks_english(text) or _looks_meta(text):
                    row.update(state="suspended", why="The complete response is unsuitable for a short interjection")
                    why = row["why"]
                    continue
                if (voice != str(dj_settings().get("drop_voice") or "")
                        or profile != _sfxguy_ready_profile()):
                    why = "The voice or Crystal changed while preparing; saved work is retained"
                    break
                take = await prep_render_line(text, "drop", voice, kind="sfxguy")
                clip = pantry_get(str((take or {}).get("key") or "")) if take else None
                if not take or not clip or take.get("voice") != voice:
                    row.update(state="waiting", retry_at=time.time() + 30,
                               why="Accepted words await the configured SFX speaker's recording slot")
                    why = row["why"]
                    continue
                row.update(take, clip=dict(clip), recorded_text=text, recorded_voice=voice)
                if not _sfxguy_ready_valid(row, voice):
                    row.update(state="suspended", why="The saved take is missing, oversized or no longer matches its proof")
                    why = row["why"]
                    continue
                row.update(state="ready", retry_at=0, why="Whole rhymed line recorded in the SFX speaker's voice")
                made += 1
                _SFX_READY_STATE["last_ready"] = {"id": row["id"], "at": time.time(),
                    "key": row["key"], "voice": voice, "seconds": row["seconds"]}
            except asyncio.CancelledError:
                raise
            except Exception as exc:
                row["errors"] = int(row.get("errors") or 0) + 1
                row.update(state="suspended" if row["errors"] >= 3 else "waiting",
                           retry_at=time.time() + min(900, 60 * row["errors"]),
                           why=("Preparation suspended after three errors: " if row["errors"] >= 3
                                else "Preparation will retry: ") + type(exc).__name__)
                why = row["why"]
            finally:
                _SFX_READY_BANK.put(row)
        _SFX_READY_STATE.update(made=made, attempted=attempted, why=why, at=time.time(),
            ready=len({row["text"] for row in _SFX_READY_BANK.rows(voice, profile)
                       if row.get("state") == "ready" and _sfxguy_ready_valid(row, voice)}))
    return dict(_SFX_READY_STATE)


async def _sfxguy_ready_clock() -> None:
    await asyncio.sleep(12)
    while True:
        try:
            if _RADIO.get("on"):
                await sfxguy_ready_prepare(1)
        except Exception as exc:
            _SFX_READY_STATE.update(made=0, why=f"Preparation deferred: {type(exc).__name__}")
        await asyncio.sleep(30)


@app.on_event("startup")
async def _sfxguy_ready_start() -> None:
    fire_and_forget(_sfxguy_ready_clock())


def _sfxguy_key(line: str) -> str:
    return hashlib.sha1(line.strip().lower().encode()).hexdigest()[:12]


def _sfxguy_said() -> dict[str, float]:
    try:
        d = json.loads(SFXGUY_SAID_PATH.read_text())
        return d if isinstance(d, dict) else {}
    except Exception:  # noqa: BLE001
        return {}


def _sfxguy_stamp(line: str) -> None:
    """#798: every line carries a COOLDOWN — nothing repeats inside an
    hour, and the ledger survives restarts."""
    try:
        now = time.time()
        d = {k: v for k, v in _sfxguy_said().items()
             if now - float(v or 0) < 86400}
        d[_sfxguy_key(line)] = now
        SFXGUY_SAID_PATH.write_text(json.dumps(d))
    except Exception:  # noqa: BLE001
        pass


_SFXGUY_NEWS: list[dict[str, str]] = []
_SFXGUY_NEWS_FILLING = [False]
_SFXGUY_NEWS_AT = [0.0]


async def _sfxguy_news_fill() -> None:
    """#804: now and then the SFX guy is the one who BREAKS a story —
    a real headline off the wire with a spicy one-line take, brewed in
    the background, aired whole in his voice. The hosts pick it up as
    the topic (dj_banter reads the note he leaves)."""
    if _SFXGUY_NEWS_FILLING[0] or _SFXGUY_NEWS:
        return
    _SFXGUY_NEWS_FILLING[0] = True
    try:
        picks = news_selection(await drudge_headlines(24), False)
        if picks:
            story = picks[0]
            # #1018: the crystal's own lines ride along, not just its
            # description - see crystal_style_note.
            _news_words = sfx_words()                             # #1034
            _ntint = ""
            _ncrs = crystal_active()
            if _ncrs:
                _ntint = crystal_tint_note(random.choice(_ncrs))
            take = await ask_model(
                "You are a thick-accented, NASCAR-loving country boy in "
                f"a radio booth. Headline: {story.get('title')}. Give ONE "
                f"spicy, funny take on it, under {_news_words} words, no "
                f"quotes, no explanation.{_ntint}",               # #1066
                limit=max(200, _news_words * 9), spice=0.85,
                # #1022: his own brew, not whatever entry is on air.
                mark={"kind": "sfx news",
                      "for": "the SFX guy's take on a headline"})
            take = str(take or "").strip().strip('"').strip()[:180]
            # #1038: a brew that runs well ahead of air - it can afford
            # to be built properly.
            take = await crystal_line(take, "an SFX guy news take", 2)
            if take and looks_english(take):
                _SFXGUY_NEWS.append({
                    "title": str(story.get("title") or "")[:140],
                    "take": take,
                    "line": (f"Y'all hear this one? "
                             f"{story.get('title')}. {take}")})
    except Exception:  # noqa: BLE001
        pass
    finally:
        _SFXGUY_NEWS_FILLING[0] = False


async def _sfxguy_warp_fill(voice: str, context: str = "") -> None:
    """#799: the invention shed — warped, demented, proudly INCORRECT
    versions of the shelf sayings, brewed in the background so the air
    path never waits on the model. Tinted by the active crystal."""
    if _SFXGUY_FILLING[0] or len(_SFXGUY_WARPED) >= 8:
        return
    _SFXGUY_FILLING[0] = True
    try:
        rows = sfxguy_quips(voice)
        picks = random.sample(rows, k=min(2, len(rows)))
        # #820: the tint rides EVERY brew — reactions, warps, the lot —
        # with a shard of the crystal's own material folded in, because
        # material beats instruction on a small model.
        _tinted = ""
        _shard = ""
        _crs0 = crystal_active()
        if _crs0:
            _cr0 = random.choice(_crs0)
            # #1018: and the crystal's OWN LINES with it. This used to be
            # the description alone unless the crystal was allowed to
            # source, which is why a saying tinted through DOOM came back
            # with comic-book nouns in it and nothing that sounded like
            # the man. The gate below still governs the SWATH; this is
            # style reference, which is a different thing.
            _tinted = crystal_tint_note(_cr0)
            # #973: the flavour bleeds in either way (that is the tint,
            # which is what was asked for); the crystal's actual WORDS
            # only reach him if it is a crystal allowed to source. #820
            # argued "material beats instruction on a small model", and
            # that is exactly why this has to follow the same rule - a
            # tint-only crystal supplying his shard would be the whole
            # behaviour arriving through the side door.
            _minds0 = ([m for m in (_cr0.get("minds") or [])
                        if any(x["id"] == m for x in speakbox_minds())]
                       if crystal_sources(_cr0) else [])
            if _minds0:
                try:
                    _rid0 = random.choice(_minds0)
                    _sw0 = await speakbox_quote(most=1, cap=90, rid=_rid0)
                    if _sw0 and _sw0.get("text"):
                        _shard = (" Fold a shard of this line into it: "
                                  f"\"{str(_sw0['text'])[:90]}\".")
                        _crystal_influence_note(
                            _rid0, _sw0.get("file", ""),
                            _sw0["text"], "sfxguy")
                except Exception:  # noqa: BLE001
                    _shard = ""
        # #1040: ...and when no crystal lent him one, the STUDIO shelf
        # does. Every one of his four roads carried a style note and no
        # material of any kind - he is the only voice on the station
        # that was asked to be funny about nothing in particular. The
        # crystal's shard still wins when there is one; this is the
        # floor underneath it, on the same slider as everybody else.
        if not _shard:
            try:
                if random.random() < box_rate_now(
                        dj_settings().get("speakbox_rate", 1.0)):
                    _sw1 = await speakbox_quote(most=2, cap=180)
                    if _sw1 and _sw1.get("text"):
                        _shard = (" Fold a shard of this into it: "
                                  f"\"{str(_sw1['text'])[:180]}\".")
                        _crystal_influence_note(
                            _sw1.get("mind", ""), _sw1.get("file", ""),
                            _sw1["text"], "sfxguy")
            except Exception:  # noqa: BLE001
                _shard = ""
        # #804: when a line just aired, half his inventions REACT to it —
        # engaged with the conversation, not shouted past it.
        _react_words = sfx_words()                                # #1034
        # #1157: he is in the story too. He shouts over the same show
        # everybody else is making, and his shed brews off its own
        # prompt, so nothing of the plot reached him before this.
        _story = plotline_line_clause(220)
        if context and random.random() < 0.5:
            out = await ask_model(
                "You are a thick-accented country boy in a radio booth. "
                f"Someone on air just said: \"{context}\". Fire back ONE "
                "short reaction that actually engages with what was said "
                "— heckle it, one-up it, or agree way too hard — in your "
                f"backcountry voice.{_tinted}{_shard}{_story} Under "
                f"{_react_words} "
                "words, no quotes.",                          # #1066
                limit=max(200, _react_words * 9), spice=0.85,
                # #1022: his own brew. It runs whenever there is room, so
                # whatever entry is on air had nothing to do with it.
                mark={"kind": "sfx react",
                      "for": "the SFX guy reacting to a line that just "
                             "aired"})
            line = str(out or "").strip().strip('"').strip()
            line = await crystal_line(line, "an SFX guy reaction", 2)  # #1038
            if 8 <= len(line) <= 200 and looks_english(line) \
                    and "\n" not in line:
                _SFXGUY_WARPED.append(line)
                pipeline_log("air", "the SFX guy engages: "
                             f"{line[:70]} (#804)")
            return
        _warp_words = sfx_words()                                 # #1034
        recipe = random.choice((
            "say it confidently but get it WRONG in a way that makes "
            "no sense",
            "mash the two sayings into one glorious wreck",
            "twist it into NASCAR terms — left turns, restrictor "
            "plates, pit road",
            "make it about Dale Earnhardt somehow",
            "swap the animals and objects for much stranger ones",
            "start it normal and let it fall apart halfway through",
            "turn it into a proud boast that one-ups everybody "
            "listening",
        ))
        out = await ask_model(
            "You are a thick-accented country boy in a radio booth. "
            f"Take these sayings: {' / '.join(picks)} — and {recipe}."
            f"{_tinted}{_shard}{_story} Answer with the ONE new saying only, "
            f"under {_warp_words} words, no quotes, no explanation.",
            # #1066: the rhyme order is GONE from the first pass. A
            # small model obeys it with cheap monosyllabic couplets,
            # the second pass then faithfully preserves them, and the
            # measured result was the highest raw rhyme density on the
            # station with the LOWEST construction - 3.4% multisyllabic
            # against 13.7% everywhere else. Let him say a thing; the
            # tint is what makes it a bar.
            limit=max(200, _warp_words * 9), spice=0.9,
            # #1022: the invention shed. Nothing to do with the round on
            # air, and it must stop claiming that round's instruction.
            mark={"kind": "sfx warp",
                  "for": "the SFX guy warping a saying off his shelf"})
        line = str(out or "").strip().strip('"').strip()
        if 12 <= len(line) <= 200 and looks_english(line)                 and "\n" not in line:
            _SFXGUY_WARPED.append(line)
            pipeline_log("air",
                         f"the SFX guy invents: {line[:70]} (#799)")
    except Exception:  # noqa: BLE001
        pass
    finally:
        _SFXGUY_FILLING[0] = False


def sfxguy_line(voice: str, context: str = "") -> str:
    """#798/#799: what comes out of his mouth — at the invention dial's
    rate a warped never-before-said line off the shed, otherwise a shelf
    saying that has not aired inside the hour. #804: sometimes he breaks
    a NEWS story with a spicy take, and the hosts take it up as the
    topic."""
    warp = max(0, min(100, int(dj_settings().get("sfxguy_warp") or 0)))
    _wcrs = crystal_active()
    if _wcrs:
        # #820: the crystal takes the SFX guy too. His brewed lines are
        # the ones carrying the tint, so while a crystal is on they
        # outdraw the stock shelf at the crystal's own strength.
        _wstr = max(int(c.get("strength") or 50) for c in _wcrs)
        warp = max(warp, min(95, _wstr))
    line = ""
    if (_SFXGUY_NEWS and random.random() < 0.15
            and time.time() - _SFXGUY_NEWS_AT[0] > 600):
        story = _SFXGUY_NEWS.pop(0)
        _SFXGUY_NEWS_AT[0] = time.time()
        _RADIO["sfxguy_news"] = {**story, "at": time.time()}
        _sfxguy_stamp(story["line"])
        pipeline_log("air", "the SFX guy breaks a story: "
                     f"{story['title'][:70]} (#804)")
        fire_and_forget(_sfxguy_news_fill())
        return story["line"]
    if _SFXGUY_WARPED and random.random() < warp / 100.0:
        line = _SFXGUY_WARPED.pop(random.randrange(len(_SFXGUY_WARPED)))
    else:
        rows = sfxguy_quips(voice)
        said = _sfxguy_said()
        now = time.time()
        pool = [r for r in rows
                if now - float(said.get(_sfxguy_key(r)) or 0) > 3600]
        line = (random.choice(pool) if pool else
                min(rows, key=lambda r:
                    float(said.get(_sfxguy_key(r)) or 0)))
    _sfxguy_stamp(line)
    if len(_SFXGUY_WARPED) < 8:
        fire_and_forget(_sfxguy_warp_fill(voice, context))
    if not _SFXGUY_NEWS:
        fire_and_forget(_sfxguy_news_fill())
    return line


@app.get("/api/sfxguy/quips")
async def sfxguy_quips_get(
    voice: str = "",
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """?voice=vl_… reads that voice's shelf; default is the current
    drop voice. `databases` lists every shelf saved so far."""
    require_read_auth(authorization)
    v = _sfxguy_voice(voice)
    dbs = (sorted(f.stem for f in SFXGUY_QUIPS_DIR.glob("*.json"))
           if SFXGUY_QUIPS_DIR.exists() else [])
    return {"voice": v, "quips": sfxguy_quips(v), "databases": dbs,
            "speech_bank": _sfxguy_ready_status(v)}


@app.post("/api/sfxguy/quips")
async def sfxguy_quips_add(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Grow a shelf: {"text": "..."} or {"texts": [...]}, optional
    "voice" (default: the current drop voice's own database)."""
    require_auth(authorization)
    payload = await request.json()
    v = _sfxguy_voice(str(payload.get("voice") or ""))
    adds = [str(t).strip()[:200] for t in
            (payload.get("texts") or [payload.get("text") or ""]) if
            str(t).strip()]
    if not adds:
        raise HTTPException(status_code=400, detail="say something")
    rows = sfxguy_quips(v)
    rows.extend(a for a in adds if a not in rows)
    sfxguy_quips_save(rows, v)
    note_action(f"🤠 the SFX guy ({v}) learned {len(adds)} new line(s)")
    return {"voice": v, "quips": rows}


@app.delete("/api/sfxguy/quips")
async def sfxguy_quips_del(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    require_auth(authorization)
    payload = await request.json()
    v = _sfxguy_voice(str(payload.get("voice") or ""))
    kill = str(payload.get("text") or "").strip()
    rows = [r for r in sfxguy_quips(v) if r != kill]
    sfxguy_quips_save(rows, v)
    return {"voice": v, "quips": rows}


# --- Stingers (#208) --------------------------------------------------------
# A sample off the end of a line: a record scratch, a laser, a drop. The
# folders are yours — anything under the sample share — and the pack this was
# built against is the default so it works before you name one.


# #839: the sample SHARE is mounted read-only by design — it is the
# drop box other machines fill. Extracted cuts need somewhere WRITABLE:
# they land under data/samples (on the agent share, visible from any
# PC), and the rotation reads BOTH roots.
SFX_LOCAL_ROOT = data_path("samples")


def sfx_folders() -> list[Path]:
    """The folders in play, only the ones that really exist.

    A named folder that has gone (an unplugged NAS, a renamed pack) is simply
    not in the list: a dead SMB path must never take the show down with it.
    #839: a name resolves against the read-only share first, then the
    writable local root where extracted cuts live."""
    names = dj_settings()["sfx_folders"] or list(SFX_DEFAULT_FOLDERS)
    out: list[Path] = []
    for name in names:
        for base in (SFX_ROOT, SFX_LOCAL_ROOT):
            try:
                folder = (base / name).resolve()
                # A pasted path from anywhere else on disk is not a
                # sample folder.
                if not folder.is_relative_to(base.resolve()) \
                        or not folder.is_dir():
                    continue
            except OSError:
                continue
            out.append(folder)
            break
    # #835: the DROP roots, always in play. New cuts arrive on the share
    # while the show is on - straight into the root, or into a subfolder
    # made minutes ago that nobody has named in the panel - and the
    # operator should not have to come and tell the station about each
    # one. One level down only, and every lookup is wrapped: a dead SMB
    # path must never take the show down with it.
    try:
        drops = dj_settings().get("sfx_drop_folders")
        if drops is None:
            drops = list(SFX_DROP_FOLDERS)
    except Exception:  # noqa: BLE001
        drops = list(SFX_DROP_FOLDERS)
    for name in drops:
        # An empty name would resolve to the SHARE ROOT and pull the
        # whole 23,000-file pack tree into the rotation.
        wanted = str(name or "").strip().strip("/")
        if not wanted:
            continue
        for base in (SFX_ROOT, SFX_LOCAL_ROOT):
            try:
                root = (base / wanted).resolve()
                if not root.is_relative_to(base.resolve()) \
                        or not root.is_dir():
                    continue
                here = [root] + sorted(
                    (one for one in root.iterdir() if one.is_dir()),
                    key=lambda one: one.name)[:SFX_DROP_SUBS]
            except Exception:  # noqa: BLE001
                continue
            for folder in here:
                if folder not in out:
                    out.append(folder)
            break
    return out


def sfx_list(folder: Path) -> list[Path]:
    """The samples in one folder. Not recursive: you name the folder you mean,
    and the pack tree above it holds 23,000 files."""
    try:
        found = [p for p in folder.iterdir()
                 if p.is_file() and p.suffix.lower() in MUSIC_TYPES]
    except OSError:
        return []                       # the share went away; carry on
    if len(found) <= SFX_MAX_FILES:
        return sorted(found)
    # #817: a folder past the cap ROTATES instead of freezing on the
    # first four hundred names — the operator dropped 3,447 grabs into
    # one folder and five-sixths of them could never have aired. The
    # glob runs per pick, so a fresh sample each draw puts the WHOLE
    # library in play while the downstream cost stays bounded.
    return random.sample(found, SFX_MAX_FILES)


# #1198: the SHORTEST a sample may be and still be worth playing. There
# has only ever been a ceiling; measured, 333 of 742 stings that went out
# in six hours were under half a second and the shortest was 0.07s - a
# click, which is why the operator reports the stings as "skipped" while
# the ledger records them as played.
SFX_MIN_SECONDS = 0.45


# #1199: below this a clip is digital black, or close enough that the
# listener hears the gap rather than the sting.
SFX_SILENT_DB = -50.0
SFX_LEVEL_PATH = data_path("sfx_levels.json")
_SFX_LEVEL: dict[str, Any] = {}
_SFX_LEVEL_DIRTY = [0]


def _sfx_level_load() -> None:
    if _SFX_LEVEL:
        return
    try:
        got = json.loads(SFX_LEVEL_PATH.read_text())
        if isinstance(got, dict):
            _SFX_LEVEL.update(got)
    except Exception:  # noqa: BLE001
        pass


def _sfx_level_save() -> None:
    try:
        tmp = SFX_LEVEL_PATH.with_suffix(".tmp")
        tmp.write_text(json.dumps(_SFX_LEVEL))
        tmp.replace(SFX_LEVEL_PATH)
        _SFX_LEVEL_DIRTY[0] = 0
    except Exception:  # noqa: BLE001
        pass


def sfx_level(path: Path, measure: bool = True) -> Any:
    """#1199: the loudest this sample gets, in dBFS. None = not measured.

    Cached on path+mtime like the length. WAV is read with audioop, which
    costs no subprocess; anything else goes to ffmpeg's volumedetect. A
    file that cannot be measured stays None and is OFFERED to the
    operator rather than condemned - a gate that guesses would quietly
    bin half a library."""
    try:
        key = "%s:%s" % (path, path.stat().st_mtime_ns)
    except OSError:
        return None
    _sfx_level_load()
    if key in _SFX_LEVEL:
        got = _SFX_LEVEL[key]
        return None if got is None else float(got)
    if not measure:
        return None
    peak: Any = None
    try:
        if path.suffix.lower() == ".wav":
            import wave
            import audioop
            with wave.open(str(path), "rb") as handle:
                width = handle.getsampwidth()
                frames = handle.readframes(min(handle.getnframes(), 4_000_000))
            if frames and width:
                top = float(audioop.max(frames, width))
                full = float(1 << (8 * width - 1))
                peak = (20.0 * math.log10(top / full)) if top > 0 else -120.0
        else:
            import imageio_ffmpeg
            exe = imageio_ffmpeg.get_ffmpeg_exe()
            out = subprocess.run(
                [exe, "-hide_banner", "-nostats", "-i", str(path),
                 "-map", "0:a:0", "-af", "volumedetect", "-f", "null", "-"],
                capture_output=True, timeout=20, text=True, errors="replace")
            for line in (out.stderr or "").splitlines():
                if "max_volume:" in line:
                    peak = float(line.split("max_volume:")[1].split("dB")[0])
                    break
    except Exception:  # noqa: BLE001
        peak = None
    _SFX_LEVEL[key] = peak
    _SFX_LEVEL_DIRTY[0] += 1
    if _SFX_LEVEL_DIRTY[0] >= 25:
        _sfx_level_save()
    return peak


def sfx_is_silent(path: Path) -> bool:
    """#1199: measured, and too quiet to be a sting. Unmeasured is not."""
    got = sfx_level(path, measure=False)
    return got is not None and float(got) <= SFX_SILENT_DB


def sfx_floor_seconds() -> float:
    """The shortest a sample may be and still go out (#1198)."""
    try:
        got = float(dj_settings().get("sfx_min_seconds", SFX_MIN_SECONDS))
        return max(0.0, min(3.0, got))
    except Exception:  # noqa: BLE001
        return SFX_MIN_SECONDS


def sfx_cap_seconds() -> float:
    """The longest a sample may be and still go out (#704)."""
    try:
        return max(0.5, min(30.0, float(dj_settings().get(
            "sfx_max_seconds", SFX_MAX_SECONDS))))
    except Exception:
        return SFX_MAX_SECONDS


_SFX_LEN_CACHE: dict[str, float] = {}
# The current grab library alone holds over 15,000 clips. Keep their duration
# readings across rotating pool scans; overflow evicts oldest readings rather
# than discarding every cached SMB measurement at once.
SFX_LEN_CACHE_MAX = 32000
# #863: the measurements survive a restart. Keyed path+mtime, so a
# replaced file is re-measured and a renamed one simply misses.
SFX_LEN_PATH = data_path("sfx_lengths.json")
_SFX_LEN_DIRTY = [0]


def _sfx_len_load() -> None:
    try:
        rows = json.loads(SFX_LEN_PATH.read_text())
        if isinstance(rows, dict):
            _SFX_LEN_CACHE.update({str(k): float(v)
                                   for k, v in rows.items()})
    except Exception:  # noqa: BLE001
        pass


def _sfx_len_save() -> None:
    try:
        SFX_LEN_PATH.parent.mkdir(parents=True, exist_ok=True)
        tmp = SFX_LEN_PATH.with_suffix(".tmp")
        tmp.write_text(json.dumps(_SFX_LEN_CACHE))
        tmp.replace(SFX_LEN_PATH)
        _SFX_LEN_DIRTY[0] = 0
    except Exception:  # noqa: BLE001
        pass


def sfx_seconds(path: Path) -> float:
    """How long a sample actually runs. 0.0 means we could not tell.

    Cached on path+mtime: this is asked on every draw and the folder is
    hundreds of files."""
    try:
        key = f"{path}:{path.stat().st_mtime_ns}"
    except OSError:
        return 0.0
    held = _SFX_LEN_CACHE.get(key)
    if held is not None:
        return held
    secs = 0.0
    if path.suffix.lower() == ".wav":
        import wave
        try:
            with wave.open(str(path), "rb") as handle:
                secs = handle.getnframes() / float(handle.getframerate() or 1)
        except Exception:
            secs = 0.0
    if secs <= 0:
        try:
            import mutagen
            info = mutagen.File(str(path))
            secs = float(getattr(getattr(info, "info", None), "length", 0) or 0)
        except Exception:
            secs = 0.0
    while len(_SFX_LEN_CACHE) >= SFX_LEN_CACHE_MAX:
        _SFX_LEN_CACHE.pop(next(iter(_SFX_LEN_CACHE)), None)
    _SFX_LEN_CACHE[key] = secs
    # #863: written back in batches — one decode saved is one fewer
    # minute of a station with no stings after a restart.
    _SFX_LEN_DIRTY[0] += 1
    if _SFX_LEN_DIRTY[0] >= 50:
        _sfx_len_save()
    return secs


def sfx_short(path: Path) -> bool:
    """Whether this is a sting or a pad.

    Half the shipped pack runs six to twelve seconds — they are atmospheres,
    not punctuation, and an announce cannot be stopped once it starts.

    #704: it used to read a wav header and take EVERYTHING ELSE on trust,
    on the reasoning that the record scratches are short mp3s. That is how
    long samples kept getting on air: an mp3 or a flac pad sailed straight
    through the check. Every format is measured now, and a sample we cannot
    measure at all is refused rather than risked — except the scratches this
    station makes itself, which are known short by construction."""
    cap = sfx_cap_seconds()
    secs = sfx_seconds(path)
    if secs > 0:
        # #1198: ...AND LONG ENOUGH TO HEAR. A seventieth-of-a-second
        # fragment out of the grab library is a click, not punctuation;
        # it plays, the ledger says it played, and the operator hears
        # nothing. The floor is the other half of the same question the
        # ceiling asks.
        if not (sfx_floor_seconds() <= secs <= cap):
            return False
        # #1199: ...and it has to make a SOUND. Only a measured silence
        # refuses; a file nobody has measured yet still plays and is
        # offered to the operator on the SFX desk instead.
        return not sfx_is_silent(path)
    try:
        return SFX_MADE_DIR in path.parents
    except Exception:
        return False


def sfx_all() -> list[Path]:
    """Every sample they may reach for: the packs you named, plus the
    scratches this box makes for itself (#211).
    ponytail: globbed per pick, no index. One folder of stingers reads in
    0.01s over the wire; add a cache when someone points this at a library."""
    made = scratch_stock() if dj_settings()["sfx_make"] else []
    return made + [p for folder in sfx_folders() for p in sfx_list(folder)]


# Samples are mastered hot — a pack is meant to be mixed, not played raw next
# to speech — so a scratch lands several times louder than the DJ who set it
# up (#220). Levelled to a peak the voices sit comfortably under, cached
# beside the spoken clips so the work happens once.
SFX_PEAK = 0.35                    # of full scale, by measurement not by ear
# Every SFX is RMS-equalized to this loudness — deliberately UNDER the DJ
# voice's 5200 target so no sting can arrive louder than the person who set
# it up (the user's "SFX unable to be loud and obnoxious"). Bounded boost so
# a quiet/noisy sample is not over-amplified.
SFX_RMS = int(os.getenv("SFX_RMS", "3000"))
SFX_MAX_BOOST = float(os.getenv("SFX_MAX_BOOST", "4.0"))
SFX_LEVELLED = VOICE_MEDIA_DIR / "sfx"


# --- The caller vocoder ------------------------------------------------------
# Callers do not just get a phone line — they get a voice of their own,
# creatively mangled: pitched up or down, robotized, warbled, whispered.
# Built on the ffmpeg this box already ships rather than a borrowed library:
# afftfilt is a real spectral vocoder, and every knob here is adjustable per
# caller from the 👤 popup. Strangers draw a stable mangle from their name,
# so Big Ron always sounds like Big Ron and nobody sounds like anybody else.

# Simple entries are plain -af chains. "choir" and "autotune" are layered —
# the voice mixed with pitched or phase-locked copies of itself — and this
# static ffmpeg's fftools crashes on multi-branch filter graphs, so the
# layering is done here: each copy is its own single-chain pass, mixed in
# Python, which the build handles all day.
VOCODER_CHARACTERS = {
    "plain": "",
    # Phase-locked spectrum: the classic robot.
    "robot": ("afftfilt=real='hypot(re,im)*cos(0)'"
              ":imag='hypot(re,im)*sin(0)':win_size=512:overlap=0.75"),
    # Scrambled phase: all breath, no pitch.
    "whisper": ("afftfilt=real='hypot(re,im)*cos(random(0)*6.283)'"
                ":imag='hypot(re,im)*sin(random(0)*6.283)'"
                ":win_size=512:overlap=0.75"),
    "warble": "vibrato=f=6:d=0.4",
    "alien": "vibrato=f=9:d=0.6",
    "monster": "tremolo=f=11:d=0.7",
    "megaphone": ("highpass=f=400,lowpass=f=3200,volume=6dB,"
                  "alimiter=limit=0.9"),
    # Age is a tremble and a dulled top end; youth is the opposite.
    "oldman": "vibrato=f=6.5:d=0.22,lowpass=f=3300",
    "oldwoman": "vibrato=f=6:d=0.28,lowpass=f=3800",
    "child": "highpass=f=250,treble=g=5",
    # Effects that EVOLVE across the call (#461) — the modulation is inside
    # the single chain, so they animate over the line rather than sitting
    # still. All comma-free expressions (this static build splits -af on
    # commas and crashes on multi-branch graphs).
    # A cell signal that breaks up harder and faster the longer they talk.
    "badcell": ("highpass=f=320,lowpass=f=3400,acompressor=threshold=-16dB:"
                "ratio=5:makeup=6dB,"
                "volume='0.72+0.28*sin(2*PI*(1.6*t+0.35*t*t))':eval=frame,"
                "alimiter=limit=0.9"),
    # A slow lo-fi grind: bit-crush depth and a phase sweep both crawl.
    "lofi": ("acrusher=bits=6:mode=log:mix=0.55:lfo=1:lforate=0.25:"
             "lforange=6,aphaser=type=sinusoidal:speed=0.3:decay=0.5,"
             "alimiter=limit=0.95"),
    # One slow comb-filter whoosh rakes across the whole call.
    "jetsweep": ("flanger=delay=0:depth=8:speed=0.18:width=90:regen=45:"
                 "shape=sinusoidal,alimiter=limit=0.95"),
    # Layered in vocode_process, not here.
    "autotune": "",
    "choir": "",
    # A caller who sounds like they are half-SINGING (#461): the pitch
    # glides between the root and a fifth, so their words carry a little
    # melody. Layered in vocode_process.
    "musical": "",
}

# What a character sounds like before anyone touches the pitch slider: a
# child up seven, an old man down three. Only used when the pitch is unset.
VOCODER_DEFAULT_PITCH = {
    "child": 7, "oldman": -3, "oldwoman": 2, "monster": -5, "alien": 4,
}


def _pitch_chain(semitones: int, rate: int) -> str:
    """asetrate shifts pitch and speed together, aresample puts the rate
    back, atempo puts the speed back — leaving only the pitch moved. ±12
    semitones is the whole range atempo can undo in one pass."""
    st = max(-12, min(12, int(semitones or 0)))
    if not st:
        return ""
    ratio = 2.0 ** (st / 12.0)
    return (f"asetrate={rate}*{ratio:.5f},aresample={rate},"
            f"atempo={1.0 / ratio:.5f}")


def _ffmpeg_af(raw: bytes, chain: str) -> bytes:
    """One wav through one -af chain. Anything that fails plays dry."""
    if not chain:
        return raw
    import subprocess
    import tempfile

    try:
        import imageio_ffmpeg
        exe = imageio_ffmpeg.get_ffmpeg_exe()
        with tempfile.TemporaryDirectory(prefix="vocode-") as work:
            src = Path(work) / "in.wav"
            out = Path(work) / "out.wav"
            src.write_bytes(raw)
            subprocess.run(
                [exe, "-nostdin", "-loglevel", "error", "-y", "-i", str(src),
                 "-af", chain, "-f", "wav", str(out)],
                check=True, timeout=60)
            return out.read_bytes()
    except Exception:
        return raw


def _mix_wavs(parts: list[bytes], weights: list[float]) -> bytes:
    """Weighted mix of same-format wavs, padded to the longest."""
    import audioop
    import io
    import wave

    frames, params = [], None
    for part in parts:
        with wave.open(io.BytesIO(part), "rb") as handle:
            params = params or handle.getparams()
            frames.append(handle.readframes(handle.getnframes()))
    widest = max(len(f) for f in frames)
    width = params.sampwidth
    mixed = b"\x00" * widest
    for data, weight in zip(frames, weights):
        data += b"\x00" * (widest - len(data))
        mixed = audioop.add(mixed, audioop.mul(data, width, weight), width)
    out = io.BytesIO()
    with wave.open(out, "wb") as handle:
        handle.setparams(params)
        handle.writeframes(mixed)
    return out.getvalue()


_ROBOT_TIGHT = ("afftfilt=real='hypot(re,im)*cos(0)'"
                ":imag='hypot(re,im)*sin(0)':win_size=256:overlap=0.75")


def vocode_process(raw: bytes, character: str, semitones: int,
                   rate: int) -> bytes:
    """One caller's voice: the pitch stage, then the character.

    choir is the voice plus itself a major third and a fifth up — a synth
    harmony stack; autotune is half dry, half phase-locked, chorus over the
    top — the tuned sheen. Everything else is a single chain."""
    character = character or "plain"
    pre = _pitch_chain(semitones, rate)
    try:
        if character == "choir":
            base = _ffmpeg_af(raw, pre) if pre else raw
            third = _ffmpeg_af(base, _pitch_chain(4, rate))
            fifth = _ffmpeg_af(base, _pitch_chain(7, rate))
            return _ffmpeg_af(_mix_wavs([base, third, fifth],
                                        [0.55, 0.33, 0.3]),
                              "alimiter=limit=0.95")
        if character == "autotune":
            base = _ffmpeg_af(raw, pre) if pre else raw
            tuned = _ffmpeg_af(base, _ROBOT_TIGHT)
            return _ffmpeg_af(
                _mix_wavs([base, tuned], [0.55, 0.45]),
                "chorus=0.5:0.9:50|63:0.4|0.32:0.25|0.4:2|1.5,"
                "alimiter=limit=0.95")
        if character == "musical":
            # The melodic seesaw (#461): the root and a fifth-up copy fade
            # in and out on opposite half-second LFOs, so the perceived
            # pitch rocks between two consonant notes — it reads as a
            # simple sung melody under the words. A vibrato + chorus glue
            # gives it the singer's wobble.
            base = _ffmpeg_af(raw, pre) if pre else raw
            root = _ffmpeg_af(base, "volume='0.5+0.5*sin(2*PI*0.5*t)'"
                                    ":eval=frame")
            fifth = _ffmpeg_af(
                _ffmpeg_af(base, _pitch_chain(7, rate)),
                "volume='0.5-0.5*sin(2*PI*0.5*t)':eval=frame")
            return _ffmpeg_af(
                _mix_wavs([root, fifth], [1.0, 1.0]),
                "vibrato=f=5:d=0.4,chorus=0.6:0.9:55:0.4:0.25:2,"
                "alimiter=limit=0.95")
        simple = VOCODER_CHARACTERS.get(character, "")
        chain = ",".join(part for part in (pre, simple) if part)
        return _ffmpeg_af(raw, chain) if chain else raw
    except Exception:
        return raw                      # dry beats broken


def caller_mangle(caller: dict[str, Any]) -> dict[str, Any]:
    """This caller's voice settings.

    The master toggle silences the whole rack. A regular you dialled in on
    the popup gets exactly that — with the character's natural pitch when the
    slider was left alone. A stranger draws a stable mangle from their name,
    scaled by the depth slider: at 100 every name is charactered and fully
    bent, at 30 most ring in nearly straight, at 0 they are all plain."""
    dj = dj_settings()
    if not dj["caller_fx"]:
        return {"character": "plain", "pitch": 0}
    explicit = str(caller.get("character") or "")
    pitch = int(caller.get("pitch") or 0)
    # #617: a caller sculpted on the panel carries their own reverb / delay /
    # echo on top of the character + pitch, so the operator can dial the exact
    # voice they want and hear it in preview and on air.
    extra = {k: max(0.0, min(hi, float(caller[k])))
             for k, hi in (("reverb", 1.0), ("delay", 0.4), ("echo", 1.0))
             if caller.get(k) not in (None, "")}
    if explicit or pitch or extra:
        return {"character": explicit or "plain",
                "pitch": max(-12, min(12,
                                      pitch or VOCODER_DEFAULT_PITCH.get(
                                          explicit, 0))),
                **extra}
    # A cloned voice arrives already sounding like somebody — so it keeps its
    # identity, but gets a SLIGHT, stable variance so two callers on the same
    # clone tell apart and a repeat caller keeps their own colour (#517): a
    # few semitones off their name+voice, and a LIGHT vocode now and then,
    # never the heavy rack that would bury the clone. (Explicit popup pitch/
    # character above still wins.)
    if caller.get("voice_id"):
        depth = dj["caller_fx_depth"]
        digest = int(hashlib.sha1(
            (str(caller.get("voice_id"))
             + str(caller.get("name") or "")).encode()).hexdigest(), 16)
        pitch = round(((digest % 7) - 3) * depth / 100)   # -3..+3, scaled
        LIGHT = ["plain", "plain", "plain", "warble", "megaphone", "oldman"]
        character = LIGHT[(digest >> 8) % len(LIGHT)] if depth >= 30 else "plain"
        return {"character": character, "pitch": max(-4, min(4, pitch))}
    depth = dj["caller_fx_depth"]
    digest = int(hashlib.sha1(
        str(caller.get("name") or "someone").encode()).hexdigest(), 16)
    names = sorted(VOCODER_CHARACTERS)
    charactered = (digest % 100) < depth
    character = names[digest % len(names)] if charactered else "plain"
    base = (digest >> 8) % 17 - 8
    pitch = round(base * depth / 100) or VOCODER_DEFAULT_PITCH.get(
        character, 0)
    return {"character": character, "pitch": max(-12, min(12, pitch))}


# --- Echo and reverb on the booth voices (#222) -----------------------------
# Not every line — a DJ drenched in reverb every time is a broken plugin, not
# a booth. It lands now and then, at a depth drawn between the two settings,
# so it reads as a desk being played rather than a preset.


# --- Broadcast channel strips (§38-39) -------------------------------------
# Named ffmpeg chains, applied LAST in voice_effect_apply: the channel
# colours the finished voice and never modifies the performance. Any chain
# this static ffmpeg build rejects plays dry — the per-call try already
# guarantees it.

STRIP_CHAINS: dict[str, str] = {
    "studio_warm": ("highpass=f=70,acompressor=threshold=-16dB:ratio=2.5:"
                    "makeup=3dB,equalizer=f=180:t=q:w=1:g=2,"
                    "alimiter=limit=0.95"),
    "fm_host": ("highpass=f=90,acompressor=threshold=-14dB:ratio=4:"
                "attack=4:makeup=6dB,equalizer=f=3200:t=q:w=1.2:g=3,"
                "alimiter=limit=0.95"),
    "late_night": ("highpass=f=60,lowpass=f=9000,acompressor=threshold="
                   "-20dB:ratio=2:makeup=2dB,equalizer=f=150:t=q:w=1:g=3,"
                   "alimiter=limit=0.9"),
    "am_radio": ("highpass=f=300,lowpass=f=4500,acompressor=threshold="
                 "-12dB:ratio=6:makeup=6dB,alimiter=limit=0.9"),
    "telephone": ("highpass=f=350,lowpass=f=3400,acompressor=threshold="
                  "-15dB:ratio=5:makeup=5dB"),
    "bluetooth": ("highpass=f=200,lowpass=f=6800,acompressor=ratio=8,"
                  "alimiter=limit=0.9"),
    "laptop_mic": ("highpass=f=250,equalizer=f=1200:t=q:w=1:g=4,"
                   "lowpass=f=7500"),
    "vintage": ("highpass=f=150,lowpass=f=6000,vibrato=f=0.4:d=0.03,"
                "acompressor=ratio=4:makeup=4dB,alimiter=limit=0.9"),
}


def perf_dsp_chain(vec: dict[str, Any], rate: int) -> str:
    """The performance vector as one -af chain: atempo for pace, the
    existing pitch trick for pitch, volume + a compressor for energy.
    Identity comes back "" — most lines never touch ffmpeg for this.

    #756: the pace here is the performance's, multiplied by the station's
    own speed dial and by this voice's own trim, so a clone that renders
    slower than its source can be brought back in line without dragging
    every other voice with it. The ceiling is raised to 1.6 because 1.3 was
    below where a 20% station-wide lift plus an emphatic delivery lands."""
    parts: list[str] = []
    pace = max(0.6, min(1.6, float(vec.get("pace") or 1.0)
                        * float(vec.get("speed_trim") or 1.0)))
    if abs(pace - 1.0) > 0.02:
        parts.append(f"atempo={pace:.3f}")
    st = int(round(float(vec.get("pitch_st") or 0)
                   + float(vec.get("pitch_trim") or 0)))     # #756
    # #832: the pitch road is an asetrate resample trick — past two
    # semitones it audibly warbles ("modulating terribly", the
    # operator's ear). Intonation stays; the artifacts go.
    st = max(-2, min(2, st))
    if st:
        parts.append(_pitch_chain(st, rate))
    energy = float(vec.get("energy") or 0.0)
    if energy > 0.1:
        parts.append(f"volume={1 + 0.5 * min(energy, 1.0):.2f},"
                     "acompressor=threshold=-18dB:ratio=3:makeup=4dB")
    elif energy < -0.1:
        parts.append(f"volume={1 + 0.4 * max(energy, -1.0):.2f}")
    return ",".join(part for part in parts if part)


def perf_pause_stretch(raw: bytes, scale: float) -> bytes:
    """Pause lengths bent without touching the speech: quiet runs longer
    than 120 ms grow or shrink by `scale`. An exhausted speaker leaves the
    gaps hanging; an angry one closes them up.
    ponytail: stdlib audioop again, pinned 3.12 — sfx_levelled's note."""
    import audioop
    import io
    import wave

    scale = max(0.6, min(1.8, float(scale or 1.0)))
    try:
        with wave.open(io.BytesIO(raw), "rb") as src:
            params = src.getparams()
            frames = src.readframes(src.getnframes())
        width = params.sampwidth
        if width != 2 or params.nchannels != 1:
            return raw
        window = max(1, int(params.framerate * 0.02)) * width
        total = len(frames) // window
        quiet = [audioop.rms(frames[i * window:(i + 1) * window],
                             width) < 260
                 for i in range(total)]
        out = bytearray()
        i = 0
        while i < total:
            if not quiet[i]:
                out += frames[i * window:(i + 1) * window]
                i += 1
                continue
            j = i
            while j < total and quiet[j]:
                j += 1
            run = frames[i * window:j * window]
            # The final quiet run is the clip's tail, not a pause — an
            # exhausted speaker stretching END silence just sounds like
            # the station lagging (#378).
            if j - i >= 6 and j < total:   # 120 ms: a pause, not a beat
                keep = int(len(run) * scale)
                keep -= keep % width
                if keep <= len(run):
                    out += run[:keep]
                else:
                    out += run + b"\x00" * (keep - len(run))
            else:
                out += run
            i = j
        out += frames[total * window:]
        buffer = io.BytesIO()
        with wave.open(buffer, "wb") as dst:
            dst.setparams(params)
            dst.writeframes(bytes(out))
        return buffer.getvalue()
    except Exception:
        return raw                       # dry beats broken


def perf_apply(raw: bytes, vec: dict[str, Any]) -> bytes:
    """One clip through its performance vector: tempo, pitch and energy in
    ffmpeg, pause lengths in the wave itself."""
    try:
        import io
        import wave
        with wave.open(io.BytesIO(raw), "rb") as probe:
            rate = probe.getframerate()
        chain = perf_dsp_chain(vec, rate)
        if chain:
            raw = _ffmpeg_af(raw, chain)
        scale = float(vec.get("pause_scale") or 1.0)
        if abs(scale - 1.0) > 0.15:
            raw = perf_pause_stretch(raw, scale)
    except Exception:
        pass
    return raw


def voice_effect_pick() -> dict[str, float]:
    """How wet this line is, if at all. Empty means say it dry."""
    dj = dj_settings()
    if random.random() >= dj["fx_rate"]:
        return {}
    depth = random.uniform(dj["fx_min"], dj["fx_max"]) / 100.0
    if depth <= 0.01:
        return {}
    return {
        # An echo you can count, and a reverb you can only feel.
        "delay": random.uniform(0.09, 0.22),
        "echo": depth * random.uniform(0.35, 0.75),
        "room": depth * random.uniform(0.3, 0.6),
    }


def voice_effect_apply(raw: bytes, ext: str, fx: dict[str, float]) -> bytes:
    """Everything that happens to a finished take, in broadcast order:
    the PERFORMANCE first (pace, pitch drift, pauses, energy — the take
    itself), then the character and the room (echo/static/phone — where
    they are), then the CHANNEL STRIP (what they are heard through). The
    layers stay separate so a strip can change without re-performing (§38).
    Anything that is not a plain wav comes back untouched — better dry
    than mangled."""
    if not fx or ext.lower() not in (".wav", "wav"):
        return raw
    import audioop
    import io
    import wave

    if fx.get("perf"):
        raw = perf_apply(raw, fx["perf"])

    # The caller's own voice next — pitch and character — then the phone
    # line and the room go on top of whoever that made them.
    if fx.get("vocode") or fx.get("pitch"):
        try:
            with wave.open(io.BytesIO(raw), "rb") as probe:
                rate = probe.getframerate()
            raw = vocode_process(
                raw, str(fx.get("vocode") or "plain"),
                int(fx.get("pitch") or 0), rate)
        except Exception:
            pass                        # dry beats broken

    # The echo/room rack only runs when its knobs are present — a perf- or
    # strip-only fx dict skips it rather than KeyErroring into dryness.
    if fx.get("delay") is not None:
        try:
            with wave.open(io.BytesIO(raw), "rb") as src:
                params = src.getparams()
                frames = src.readframes(src.getnframes())
            width, rate = params.sampwidth, params.framerate
            # The telephone crush: down to phone bandwidth and back leaves
            # the timbre every caller has (#237).
            if fx.get("phone"):
                crushed, _ = audioop.ratecv(frames, width, params.nchannels,
                                            rate, 8000, None)
                frames, _ = audioop.ratecv(crushed, width, params.nchannels,
                                           8000, rate, None)
            step = max(1, int(rate * fx["delay"])) * width * params.nchannels
            # Room for the tail, or the last echo is cut off mid-bounce.
            frames += b"\x00" * step * 3
            wet = frames
            if fx.get("static"):
                hiss = audioop.mul(os.urandom(len(wet) - len(wet) % width),
                                   width, float(fx["static"]) * 0.08)
                wet = audioop.add(wet, hiss[:len(wet)], width)
            for tap, gain in ((1, fx["echo"]), (2, fx["echo"] * 0.45),
                              (3, fx["room"] * 0.4), (5, fx["room"] * 0.2)):
                if gain <= 0.01:
                    continue
                shifted = b"\x00" * (step * tap) + frames[:-step * tap]
                wet = audioop.add(wet, audioop.mul(shifted, width, gain),
                                  width)
            # Mixing four copies together overshoots; bring the peak back.
            peak = audioop.max(wet, width)
            ceiling = 2 ** (8 * width - 1) - 1
            if peak > ceiling * 0.9:
                wet = audioop.mul(wet, width, (ceiling * 0.89) / peak)
            out = io.BytesIO()
            with wave.open(out, "wb") as dst:
                dst.setparams(params)
                dst.writeframes(wet)
            raw = out.getvalue()
        except Exception:
            pass                         # dry beats broken

    if fx.get("strip"):
        raw = _ffmpeg_af(raw, STRIP_CHAINS.get(str(fx["strip"]), ""))
    # Equal loudness out the door (#306): the phone band-crush eats level,
    # so callers rode in low next to the hosts. Everything effected leaves
    # at the same speech RMS, capped clear of the ceiling (box-volume scaled).
    return _level_voice(raw)


def _level_rms(raw: bytes, target: int = 5200) -> bytes:
    """Bring a clip to a common speech loudness by RMS, never past 95% of
    full scale. Peak normalization alone left band-limited voices sounding
    half as loud as full-range ones at the same peak.
    ponytail: stdlib audioop, pinned 3.12 — sfx_levelled's note."""
    import audioop
    import io
    import wave

    try:
        with wave.open(io.BytesIO(raw), "rb") as src:
            params = src.getparams()
            frames = src.readframes(src.getnframes())
        if params.sampwidth != 2:
            return raw
        rms = audioop.rms(frames, 2)
        if rms <= 0:
            return raw
        gain = target / rms
        peak = audioop.max(frames, 2) or 1
        ceiling = 32767 * 0.95
        if peak * gain > ceiling:
            gain = ceiling / peak
        if abs(gain - 1.0) < 0.05:
            return raw
        out = io.BytesIO()
        with wave.open(out, "wb") as dst:
            dst.setparams(params)
            dst.writeframes(audioop.mul(frames, 2, gain))
        return out.getvalue()
    except Exception:
        return raw                       # dry beats broken


def _wav_tail_pad(raw: bytes, ms: int) -> bytes:
    """Append a beat of silence to a clip. The Pine Box speaker stutter-loops
    its last audio buffer at the tail of a clip (#493, the glitch that made
    him unplug it); ending every clip on silence means the buffer it loops is
    silent, so the glitch is inaudible."""
    if ms <= 0:
        return raw
    try:
        import io
        import wave
        with wave.open(io.BytesIO(raw), "rb") as r:
            params = r.getparams()
            frames = r.readframes(r.getnframes())
        pad = b"\x00" * int(params.framerate * params.nchannels
                            * params.sampwidth * ms / 1000)
        out = io.BytesIO()
        with wave.open(out, "wb") as w:
            w.setparams(params)
            w.writeframes(frames + pad)
        return out.getvalue()
    except Exception:
        return raw                       # never fail a clip over padding


def box_tail_seconds() -> float:
    """The beat of silence every clip carries at its END, in seconds.

    #908: named in one place because the DOWNLOAD road has to take it
    back off again. The pad is there so the Pine Box's speaker loops
    silence rather than the last syllable (#493, #712) - and it is
    precisely the "little bit of extra after" the operator hears on
    every clip he saves out of the booth.
    """
    try:
        return max(0.0, int(os.getenv("BOX_TAIL_MS", "900")) / 1000.0)
    except Exception:  # noqa: BLE001
        return 0.9


def box_gain() -> float:
    """The box-volume slider (#448) as a clamped multiplier, in ONE place so
    voice, stings AND the phone bell all track the same knob (#573). Stings and
    rings used to level to a FIXED loudness, so lowering the slider quieted the
    DJs while the sound effects kept firing at full blast."""
    try:
        return max(0.3, min(1.6, float(dj_settings().get("box_volume") or 1.0)))
    except Exception:
        return 1.0


# #971: what we last told the box, so the glass says it once per change
# rather than once per record.
_MUSIC_LEVEL_SET: dict[str, Any] = {}


def music_box_level() -> float:
    """#971: HOW LOUD A RECORD IS ON THE BOX, 0..1.

    "the music is broadcasting at full volume from the box when really
    the volume should be very low coming out of the Nabu device."

    box_gain() cannot answer this. It is an amplitude multiplier baked
    into clips WE render - _level_voice applies it to speech, and #573
    extended it to stings and the phone bell - but a record is never
    rendered by us. music_play_on_box hands the box a URL and the box
    fetches and plays the file itself, at whatever level the file is;
    that function's own note says so out loud: "no pause, seek or volume
    on the box".

    There is a volume, though, and the split between the two entities is
    what makes it safe. Speech goes to the assist_satellite entity by
    announce; music is redirected to the MEDIA PLAYER entity
    (NABU_MEDIA_PLAYER) by play_media. So a volume set on the media
    player moves the records and cannot touch the DJs."""
    try:
        return max(0.0, min(1.0, float(
            dj_settings().get("music_box_level", 0.35))))
    except Exception:  # noqa: BLE001
        return 0.35


async def box_level_send(level: float, *, operator: bool = False) -> dict[str, Any]:
    """#1014: put a level on the box's own volume, NOW.

    "Make sure that these settings are affecting the box in real time as
    I'm adjusting them."

    #1007 and this look like opposites and are not. What #1007 refused is
    the station ASSERTING a level nobody asked for - before every record,
    and again after every restart, undoing the dial on the device. What
    this is, is the operator moving the slider: an explicit instruction,
    obeyed at once. The station still never touches that number on its
    own; it touches it when it is told to, which is what a control is."""
    out: dict[str, Any] = {"ok": False, "why": "", "entity": ""}
    if not operator:
        out["why"] = "Only a deliberate operator volume adjustment may move the device dial"
        return out
    try:
        token, player = _ha_creds()
        if not (token and player):
            out["why"] = "no Home Assistant credentials"
            return out
        entity = (NABU_MEDIA_PLAYER if player == NABU_SATELLITE else player)
        out["entity"] = entity
        if not entity.startswith("media_player."):
            out["why"] = ("the DJs go to the satellite by announce, which "
                          "has no volume of its own - the level is baked "
                          "into each clip instead")
            return out
        want = max(0.0, min(1.0, round(float(level), 3)))
        async with httpx.AsyncClient(timeout=8.0) as client:
            reply = await client.post(
                f"{HA_URL}/api/services/media_player/volume_set",
                headers={"Authorization": f"Bearer {token}"},
                json={"entity_id": entity, "volume_level": want})
        out["ok"] = 200 <= reply.status_code < 300
        if not out["ok"]:
            out["why"] = f"HTTP {reply.status_code}"
        else:
            _MUSIC_LEVEL_SET.update({"at": want, "ok": True})
    except Exception as exc:  # noqa: BLE001
        out["why"] = f"{type(exc).__name__}: {exc}"[:140]
    return out


def nabu_volume_owned(player: str = "") -> bool:
    """The Nabu's physical dial owns its level, including older saved opt-ins."""
    return ((_RADIO.get("voice_device") or "nabu") == "nabu"
            or player in (NABU_SATELLITE, NABU_MEDIA_PLAYER))


def box_volume_control(player: str = "") -> bool:
    """#1007: may the station set the box's own volume?

    Default NO. The physical dial on the device is the owner of that
    number, and every scheme for "we set it, but politely" ends with the
    station putting it back after a restart - which is exactly what the
    operator kept hearing.

    Nabu always retains its physical setting (#1059), even if an older
    setting enabled automatic control. Other configured media players can
    retain their explicit opt-in to station level control."""
    try:
        if not player:
            _, player = _ha_creds()
        if nabu_volume_owned(player):
            return False
        return bool(dj_settings().get("box_volume_control", False))
    except Exception:  # noqa: BLE001
        return False


def _level_voice(raw: bytes) -> bytes:
    """Every spoken clip out the door at the same speech loudness (#306), the
    target scaled by the box-volume slider (#448). Applied to EVERY line now,
    not only effected ones, so plain DJ speech is equalized like the rest.
    Ends on a beat of silence so the box's tail buffer never loops (#493)."""
    levelled = _level_rms(raw, target=int(5200 * box_gain()))
    # 300 ms was not enough silence for this box to loop harmlessly — it was
    # still stuttering audible speech at the end of a message until it was
    # unplugged (#712). The buffer it repeats is longer than the pad was, so
    # the pad has to be longer than the buffer. 900 ms costs a beat of quiet
    # between lines and is the difference between a glitch you hear and one
    # you do not. Override with BOX_TAIL_MS if a different box wants less.
    return _wav_tail_pad(levelled, int(os.getenv("BOX_TAIL_MS", "900")))


def _as_wav(path: Path) -> Path:
    """An mp3 turned into a wav we can measure, cached beside the levelled
    ones. The stdlib cannot decode an mp3 and the sample packs are full of
    them, so without this the loudest samples in the folder are exactly the
    ones that skip levelling (#220, #225)."""
    if path.suffix.lower() == ".wav":
        return path
    import subprocess
    try:
        import imageio_ffmpeg
        exe = imageio_ffmpeg.get_ffmpeg_exe()
    except Exception:
        return path                      # no decoder; play it as it is
    out = SFX_LEVELLED / f"{sfx_id(path)}-{path.stat().st_mtime_ns}-src.wav"
    if out.exists():
        return out
    SFX_LEVELLED.mkdir(parents=True, exist_ok=True)
    try:
        subprocess.run([exe, "-nostdin", "-loglevel", "error", "-y",
                        "-i", str(path), "-ac", "1", "-ar", "22050",
                        str(out)], check=True, timeout=30)
    except Exception:
        out.unlink(missing_ok=True)
        return path
    return out


def sfx_levelled(path: Path) -> Path:
    """The same sample, EQUALIZED to a common loudness under the DJ voice —
    decoding it first if it is an mp3. Peak-capping alone let dense samples
    stay obnoxiously loud at the same peak, so this RMS-normalizes every
    sting to SFX_RMS (bounded boost) and then hard-caps the peak at SFX_PEAK,
    so nothing arrives louder than the DJ who set it up.
    ponytail: stdlib audioop, which goes away in Python 3.13. This image is
    3.12; when it moves, these are an rms/peak scan and a multiply. The '-v2'
    in the cache name invalidates clips levelled by the old peak-only rule."""
    import audioop
    import wave

    try:
        stamp = path.stat().st_mtime_ns
    except OSError:
        return path
    vol = box_gain()             # stings track the box-volume slider too (#573)
    out = SFX_LEVELLED / f"{sfx_id(path)}-v2-v{int(round(vol * 20))}-{stamp}.wav"
    if out.exists():
        return out
    source = _as_wav(path)
    try:
        with wave.open(str(source), "rb") as src:
            params = src.getparams()
            frames = src.readframes(src.getnframes())
        width = params.sampwidth
        peak = audioop.max(frames, width)
        rms = audioop.rms(frames, width)
        ceiling = float(2 ** (8 * width - 1) - 1)
        if not peak:
            return path
        # Equalize loudness (RMS), bounded so a quiet/noisy sample is not
        # over-amplified, then hard-cap the peak so a transient cannot spike.
        # Both the target and the cap ride the box-volume slider (#573), so a
        # lowered box quiets the stings the same way it quiets the voices.
        gain = (SFX_RMS * vol / rms) if rms > 0 else 1.0
        gain = max(0.05, min(SFX_MAX_BOOST, gain))
        if peak * gain > SFX_PEAK * vol * ceiling:
            gain = (SFX_PEAK * vol * ceiling) / peak
        SFX_LEVELLED.mkdir(parents=True, exist_ok=True)
        with wave.open(str(out), "wb") as dst:
            dst.setparams(params)
            dst.writeframes(audioop.mul(frames, width, gain))
    except Exception:
        return path                  # not a wav we can read; play it as it is
    return out


# --- Scratches made here, not downloaded (#211) -----------------------------
# A record scratch is a short pitch sweep through filtered noise: the needle
# dragged across a groove. Every open generator I could have pulled in is a
# few hundred lines of DSP and a dependency; the shape itself is a dozen lines
# of stdlib, and making them here means every one is different — a new scratch
# per zinger rather than the same wav forty times.
SFX_MADE_DIR = data_path("sfx")
SFX_MADE_KEEP = 60
SFX_MADE_RATE = 22050


def make_scratch(seed: int | None = None) -> Path | None:
    """Write one scratch and hand back the file.

    The sweep goes down and back up (a backspin) or just down (a stab), with
    the groove noise riding on it and a short envelope so it starts and stops
    without a click."""
    import math
    import struct
    import wave

    roll = random.Random(seed)
    length = roll.uniform(0.28, 0.75)
    frames = int(SFX_MADE_RATE * length)
    low, high = roll.uniform(70, 150), roll.uniform(600, 1500)
    backspin = roll.random() < 0.55
    rasp = roll.uniform(0.25, 0.6)        # how much groove is in it
    phase = 0.0
    samples = []
    for at in range(frames):
        where = at / frames
        # Down then up for a backspin, down only for a stab.
        bend = (1.0 - abs(2.0 * where - 1.0)) if backspin else (1.0 - where)
        freq = low + (high - low) * bend
        phase += 2.0 * math.pi * freq / SFX_MADE_RATE
        tone = math.sin(phase)
        noise = roll.uniform(-1.0, 1.0) * rasp * bend
        # Ten milliseconds of fade at each end: a square edge is a click.
        edge = min(1.0, at / (SFX_MADE_RATE * 0.01),
                   (frames - at) / (SFX_MADE_RATE * 0.01))
        value = (tone * (1.0 - rasp) + noise) * edge * 0.7
        samples.append(int(max(-1.0, min(1.0, value)) * 32767))

    SFX_MADE_DIR.mkdir(parents=True, exist_ok=True)
    name = f"scratch-{'backspin' if backspin else 'stab'}-{uuid.uuid4().hex[:6]}.wav"
    out = SFX_MADE_DIR / name
    try:
        with wave.open(str(out), "wb") as handle:
            handle.setnchannels(1)
            handle.setsampwidth(2)
            handle.setframerate(SFX_MADE_RATE)
            handle.writeframes(struct.pack(f"<{len(samples)}h", *samples))
    except OSError:
        return None
    # Bounded: this runs for hours and each one is a few tens of kilobytes.
    made = sorted(SFX_MADE_DIR.glob("scratch-*.wav"),
                  key=lambda p: p.stat().st_mtime, reverse=True)
    for old in made[SFX_MADE_KEEP:]:
        old.unlink(missing_ok=True)
    return out


def scratch_stock(want: int = 12) -> list[Path]:
    """Keep a handful of freshly made scratches on hand, and quietly make
    another whenever the stock runs low — so the one they reach for is rarely
    one you have heard before."""
    try:
        made = sorted(SFX_MADE_DIR.glob("scratch-*.wav"))
    except OSError:
        made = []
    while len(made) < want:
        fresh = make_scratch()
        if fresh is None:
            break
        made.append(fresh)
    return made


def sfx_id(path: Path) -> str:
    """The same opaque, unguessable shape a track id has, so the same guard
    and the same signature work."""
    return hashlib.sha1(str(path).encode()).hexdigest()[:16]


def sfx_by_id(wanted: str) -> Path | None:
    # #1204: the CACHED pool first. sfx_id hashes str(path), and the
    # cached pool and sfx_all() do not always spell the same file the
    # same way - so an id minted from one could not be looked up through
    # the other, and the SFX desk's play button served a 404 on a clip
    # sitting right there. Cheap, and it spares the CIFS walk besides.
    try:
        for path in sfx_pool_cached():
            if sfx_id(path) == wanted:
                return path
    except Exception:  # noqa: BLE001
        pass
    made = (list(SFX_MADE_DIR.glob("*.wav"))
            if SFX_MADE_DIR.is_dir() else [])
    for path in sfx_all() + made:
        if sfx_id(path) == wanted:
            return path
    return None


# Samples voted off the air (#269). A ▼ on the chat row or a toggle in the
# folder popup lands the id here, and the draw never picks it again.
SFX_HISTORY_PATH = data_path("sfx_history.json")
_SFX_HISTORY_LOCK = RLock()


def sfx_history_add(path: Path, who: str = "") -> None:
    """#862: remember that this sample aired. The operator asked to see
    the rotation and rule on it; nothing was recording it."""
    try:
        with _SFX_HISTORY_LOCK:
            try:
                rows = json.loads(SFX_HISTORY_PATH.read_text())
                rows = rows if isinstance(rows, list) else []
            except Exception:  # noqa: BLE001
                rows = []
            rows.append({"ts": int(time.time()), "id": sfx_id(path),
                         "name": path.name, "who": who[:24]})
            del rows[:-2000]
            SFX_HISTORY_PATH.parent.mkdir(parents=True, exist_ok=True)
            tmp = SFX_HISTORY_PATH.with_suffix(".tmp")
            tmp.write_text(json.dumps(rows))
            tmp.replace(SFX_HISTORY_PATH)
    except Exception:  # noqa: BLE001
        pass                      # a ledger must never cost a sting


def sfx_history_rows() -> list[dict[str, Any]]:
    try:
        rows = json.loads(SFX_HISTORY_PATH.read_text())
        return rows if isinstance(rows, list) else []
    except Exception:  # noqa: BLE001
        return []


SFX_BANS_PATH = data_path("sfx_bans.json")
_SFX_BANS_LOCK = RLock()


def sfx_bans() -> set[str]:
    try:
        rows = json.loads(SFX_BANS_PATH.read_text())
        return {str(x) for x in rows} if isinstance(rows, list) else set()
    except Exception:
        return set()


# How often a given sample is allowed to come up (#645). A ban is a hard
# no; this is the dial between "barely ever" and "lean on it" — 1.0 is the
# weight every sample starts with.
SFX_WEIGHTS_PATH = data_path("sfx_weights.json")
_SFX_WEIGHTS_LOCK = RLock()


def sfx_weights() -> dict[str, float]:
    try:
        rows = json.loads(SFX_WEIGHTS_PATH.read_text())
        return {str(k): float(v) for k, v in rows.items()} \
            if isinstance(rows, dict) else {}
    except Exception:
        return {}


def sfx_set_weight(sid: str, weight: float) -> dict[str, float]:
    with _SFX_WEIGHTS_LOCK:
        rows = sfx_weights()
        weight = max(0.0, min(4.0, float(weight)))
        if abs(weight - 1.0) < 0.01:
            rows.pop(sid, None)           # back to normal = no entry
        else:
            rows[sid] = round(weight, 2)
        try:
            SFX_WEIGHTS_PATH.parent.mkdir(parents=True, exist_ok=True)
            SFX_WEIGHTS_PATH.write_text(json.dumps(rows, indent=1))
        except OSError:
            pass
        return rows


# The scoreboard behind the 📊 tables (#300): plays per sample, and which
# presenter leaned on which button.
SFX_PLAYS_PATH = data_path("sfx_plays.json")
_SFX_PLAYS_LOCK = RLock()


def sfx_plays() -> dict[str, Any]:
    """The plays ledger, cached against the file's own mtime (#1062) -
    sfx_fresh_paths reads it on every draw now."""
    try:
        stamp = SFX_PLAYS_PATH.stat().st_mtime_ns
    except OSError:
        stamp = 0
    if stamp and _SFX_PLAYS_MEMO["at"] == stamp:
        return _SFX_PLAYS_MEMO["rows"]
    try:
        rows = json.loads(SFX_PLAYS_PATH.read_text())
        rows = rows if isinstance(rows, dict) else {}
    except Exception:
        rows = {}
    _SFX_PLAYS_MEMO.update({"at": stamp, "rows": rows})
    return rows


def sfx_note_play(sid: str, name: str, who: str, ms: int = 0) -> None:
    with _SFX_PLAYS_LOCK:
        rows = sfx_plays()
        row = rows.get(sid) or {"name": name, "plays": 0, "by": {}}
        row["name"] = name
        row["plays"] = int(row.get("plays") or 0) + 1
        by = row.get("by") or {}
        who = who or "board"
        by[who] = int(by.get(who) or 0) + 1
        row["by"] = by
        row["last"] = int(time.time())
        if ms:
            row["last_ms"] = int(ms)
        # Today's tally for the hover card (#335); yesterday is history.
        today = time.strftime("%Y-%m-%d")
        days = {d: n for d, n in (row.get("days") or {}).items()
                if d == today}
        days[today] = int(days.get(today) or 0) + 1
        row["days"] = days
        rows[sid] = row
        try:
            SFX_PLAYS_PATH.parent.mkdir(parents=True, exist_ok=True)
            SFX_PLAYS_PATH.write_text(json.dumps(rows, indent=1))
        except OSError:
            pass                        # an uncounted play still played


def sfx_ban_set(sid: str, banned: bool) -> set[str]:
    with _SFX_BANS_LOCK:
        bans = sfx_bans()
        if banned:
            bans.add(sid)
        else:
            bans.discard(sid)
        try:
            SFX_BANS_PATH.parent.mkdir(parents=True, exist_ok=True)
            SFX_BANS_PATH.write_text(json.dumps(sorted(bans), indent=1))
        except OSError:
            pass
        return bans


# When one last went out, so they do not chain.
_STING_AT = [0.0]


# What the drop guy shouts (#282). Short, hot, and gone.
# #901: THE most repeated line in the station's record — 32 airings in
# 44 hours, median gap about an hour, every one of them word for word.
# It was a single hardcoded sentence handed to dj_speak as `line=`, so
# no writer ever varied it and (until air_remember) no ledger ever saw
# it. A pool drawn through unrepeated() is the fix this file already
# uses everywhere else for exactly this shape of bug — see DROP_LINES
# immediately below, and #882, which is the same story about stings.
AD_HANDOFFS = (
    "And now, back to the music on {station}.",
    "That was the ad. This is {station}, and this is the music.",
    "Right — enough of that. Back to the records.",
    "Paid for and out of the way. {station} rolls on.",
    "Business done. Let us get back to it.",
    "That is the sponsor said and dealt with. Music.",
    "Back to the good stuff on {station}.",
    "Enough talking about money. Here comes the next one.",
    "We are square with the advertiser. Play the record.",
    "And with that out of the way — {station}, still here, still on.",
)

DROP_LINES = (
    "{station}!",
    "You are locked in to {station}.",
    "The {station} sound machine rolls on.",
    "That happened. This is {station}.",
    "More of that, right after this.",
    "Somebody had to say it.",
)

# #882: the SFX guy's liners are WRITTEN, not picked off a shelf of six.
# Four of those six named the station, and a bare random.choice over
# four options repeats back-to-back a quarter of the time — which is
# exactly what the operator heard, the same ID three stings running.
# These are brewed from speakbox material in the background and kept in
# a small stack, so the sting itself never waits on a model.
_DROP_FRESH: list[str] = []
_DROP_BREW_AT = [0.0]


async def drop_liner_brew(want: int = 6) -> None:
    """Write the SFX guy a fresh stack of station IDs."""
    if time.time() - _DROP_BREW_AT[0] < 90:
        return
    _DROP_BREW_AT[0] = time.time()
    station = dj_settings()["station_name"]
    got: dict[str, Any] = {}
    seed = ""
    try:
        got = await speakbox_quote(most=2, cap=200) or {}
        seed = str(got.get("text") or "").strip()
    except Exception:  # noqa: BLE001
        seed = ""
    ask = (
        "You are the sting voice on a radio station — the guy who says "
        "one hard line over a stab of sound and gets out. Write "
        f"{want} DIFFERENT station IDs for a station called "
        f"\"{station}\". Rules: one line each, under twelve words, "
        "English only, no stage directions, no quotation marks, no "
        "numbering. Most of them should name the station outright. "
        "They must not resemble each other — different rhythm, "
        "different angle, different attitude on every one.")
    if seed:
        ask += ("\n\nTake your colour from this material, without "
                f"quoting it directly:\n{seed[:400]}")
    # #1027: the liners the station drops between records. Never
    # banked, never through dj_banter, so nothing else was ever going to
    # tint them.
    ask += crystal_tint_note()
    try:
        raw = await ask_model(ask, limit=40 * max(1, want), spice=0.9)
    except Exception:  # noqa: BLE001
        return
    fresh: list[str] = []
    for row in str(raw or "").splitlines():
        line = re.sub(r"^\s*[-*\d.)\]]+\s*", "", row).strip()
        line = line.strip('"').strip("'").strip()
        if not (4 < len(line) <= 90):
            continue
        if not english_only(line):
            continue
        if line in _DROP_FRESH or line in fresh:
            continue
        fresh.append(line)
    if not fresh:
        return
    # #1046: THE DROPS LOSE THEIR TINT, and the reason is not about
    # drops. pantry_keeper exempts one road from the "the model is busy,
    # skip this" rule - the bumper - because "its liners are brewed in
    # the background and taken off a stack, not written here". #1038 put
    # a model visit inside this brew, one per line and six lines a brew,
    # which made that comment false: prep_one("station_id") began
    # waiting on the same saturated gate as everything it was exempt
    # from, and the last road that could still bank anything stopped.
    #
    # These are four-to-ninety-character quips, the shortest thing the
    # station says. They are the cheapest thing to give up and the
    # exemption is worth more than they are.
    _DROP_FRESH.extend(fresh)
    del _DROP_FRESH[24:]
    if seed:
        try:
            _crystal_influence_note("drop", str(got.get("file") or ""),
                                    seed, "sting")
        except Exception:  # noqa: BLE001
            pass


async def drop_liner(station: str) -> str:
    """One station ID, and never the one just heard.

    A written line if the stack has one — consumed on use, so it is
    genuinely new material every sting — and otherwise the old shelf,
    but drawn through unrepeated() so it cannot land twice running."""
    if len(_DROP_FRESH) < 3:
        fire_and_forget(drop_liner_brew())
    # #901: _DROP_FRESH is an in-memory stack and unrepeated() is a
    # ring of ten with no clock on it — both forget completely when the
    # process bounces, and the sting is one of the roads the operator
    # hears most (measured: 12.4% of SFX airings were repeats, 5.7% of
    # them inside five hours). The written liners answer to the ledger
    # too now, so an ID that went out ninety minutes ago cannot come
    # back just because spark-agent restarted.
    pool = [ln for ln in _DROP_FRESH if ln]
    _cool = [ln for ln in pool if not air_repeat_check(ln).get("block")]
    pool = _cool or pool
    if pool:
        line = unrepeated(pool, "drop_liner", keep=10)
        try:
            _DROP_FRESH.remove(line)
        except ValueError:
            pass
        return line
    naming = [ln for ln in DROP_LINES if "{station}" in ln] or list(DROP_LINES)
    _plain = unrepeated([ln.format(station=station) for ln in naming],
                        "drop_fallback", keep=3)
    # #1111: AND THE FALLBACK GETS THE CRYSTAL, WITH THE NAME HELD.
    #
    # An audit found all twenty-three liners in the cupboard were four
    # hardcoded strings scoring 2.3% on rhyme density - BELOW the 3.4%
    # baseline for untinted speech, because they are not written at all.
    # drop_liner_brew does write proper ones and does tint them, but it
    # is fired and forgotten, so whoever triggered it falls through to
    # here and prep_station_id banks the constant.
    #
    # `keep` is how quoted material survives a rewrite, and the
    # station's own name goes in it: the crystal may do what it likes
    # with the rest of the line, and "Big Apple's Little Pine Box FM
    # Station" comes out spelled the way it went in. A station that
    # renames itself on air twice an hour is worse than a plain one.
    #
    # Never blocks the sting: any failure returns the plain line.
    try:
        if crystal_tint_two_pass():
            _lit = await crystal_line(_plain, "a station ID", 1,
                                      [str(station)])
            if _lit and len(str(_lit).strip()) > 4:
                return str(_lit).strip()
    except Exception:  # noqa: BLE001
        pass
    return _plain


_SFX_POOL_CACHE: list[Path] = []
_SFX_POOL_AT = [0.0]
_SFX_POOL_FILLING = [False]
_SFX_POOL_JOB: list[Any] = [None]
_SFX_POOL_SIGNATURE: list[Any] = [None]
_SFX_POOL_READY_AT = [0.0]
# #835: every sample NAME seen on the last walk. sfx_list rotates a
# random 400 out of an over-cap folder (#817), so the playable pool
# alone cannot tell a new arrival from the rotation shuffling - this
# can, and it is what makes "3 new samples" in the feed mean something.
_SFX_SEEN: set[str] = set()
# #1062: "make sure that the station is always aware of new clips being
# added to the SFX directory and is utilizing randomization to make sure
# that new clips are constantly being played on the air randomly."
#
# Three things were true before this. The pool walk only ran when a sting
# happened to be due, so a quiet hour never noticed a new file. The walk
# announced arrivals against a set that died with the process, so a clip
# dropped while the station was down was never "new". And a big folder is
# SAMPLED to SFX_MAX_FILES per walk (#817), so a fresh file in the
# 3,447-grab folder had about a one-in-nine chance of being in the draw
# at all, and then one chance in four hundred of being drawn. Now: first
# sightings are written down (sfx_seen.json), a recent arrival is always
# in the pool, half the draws go to what is fresh, and the walk runs on
# its own clock while the show is on.
SFX_ARRIVALS_PATH = data_path("sfx_seen.json")
SFX_FRESH_HOURS = 48.0              # how long an arrival stays "new"
SFX_FRESH_SHARE = 0.75              # the share of draws that go to it ("always using new entries")
_SFX_ARRIVALS: dict[str, Any] = {"loaded": False, "rows": {}}
_SFX_PLAYS_MEMO: dict[str, Any] = {"at": -1, "rows": {}}


def _sfx_arrivals_rows() -> dict[str, float]:
    """path -> when the station first saw it (0 = before the ledger)."""
    if not _SFX_ARRIVALS["loaded"]:
        rows: dict[str, float] = {}
        try:
            got = json.loads(SFX_ARRIVALS_PATH.read_text())
            if isinstance(got, dict):
                rows = {str(k): float(v or 0) for k, v in got.items()}
        except Exception:  # noqa: BLE001
            rows = {}
        _SFX_ARRIVALS.update({"loaded": True, "rows": rows})
    return _SFX_ARRIVALS["rows"]


def _sfx_arrivals_note(seen: set[str]) -> list[str]:
    """Stamp first sightings; return the paths met for the first time.

    The first walk with no ledger stamps everything present as old (0),
    so a station that has had a folder of a thousand files for a month
    does not treat all thousand as arrivals. Files that have gone are
    dropped from the ledger so it cannot grow without bound."""
    rows = _sfx_arrivals_rows()
    fresh: list[str] = []
    now = time.time()
    first_walk = not rows and not SFX_ARRIVALS_PATH.is_file()
    for one in seen:
        if one not in rows:
            rows[one] = 0.0 if first_walk else now
            if not first_walk:
                fresh.append(one)
    for gone in [k for k in rows if k not in seen]:
        rows.pop(gone, None)
    try:
        SFX_ARRIVALS_PATH.parent.mkdir(parents=True, exist_ok=True)
        tmp = SFX_ARRIVALS_PATH.with_suffix(".tmp")
        tmp.write_text(json.dumps(rows))
        tmp.replace(SFX_ARRIVALS_PATH)
    except OSError:
        pass
    return sorted(fresh)


def sfx_arrivals_recent(hours: float = SFX_FRESH_HOURS) -> list[str]:
    """Paths first seen inside the window, newest first."""
    cut = time.time() - max(0.0, float(hours)) * 3600.0
    rows = _sfx_arrivals_rows()
    return sorted((k for k, v in rows.items() if v and v >= cut),
                  key=lambda k: -rows[k])


def sfx_fresh_paths(pool: list[Path]) -> list[Path]:
    """The samples in the pool that are NEW: never played, or first seen
    inside SFX_FRESH_HOURS. These get SFX_FRESH_SHARE of the draws."""
    try:
        plays = sfx_plays()
        recent = set(sfx_arrivals_recent())
        out: list[Path] = []
        for path in pool:
            sid = sfx_id(path)
            if int((plays.get(sid) or {}).get("plays") or 0) <= 0 \
                    or str(path) in recent:
                out.append(path)
        return out
    except Exception:  # noqa: BLE001
        return []


SFX_REVIEW_REST = 90.0
_SFX_REVIEW_MEMO: dict[str, Any] = {"at": 0.0, "value": None}


def sfx_pool_cached() -> list[Path]:
    """#1199: the sample pool WITHOUT walking the share.

    sfx_all() globs a CIFS folder of thousands of files, which is the
    #826 trap - the SFX desk answered in over 100 seconds because of it,
    even in a thread. sting_due() reads _SFX_POOL_CACHE for the same
    reason and the cache refreshes off-loop once a minute; the desk and
    the level sweep read it too."""
    try:
        if time.time() - _SFX_POOL_AT[0] > 60:
            fire_and_forget(_sfx_pool_refresh())
        return [Path(p) for p in _SFX_POOL_CACHE]
    except Exception:  # noqa: BLE001
        return []


async def sfx_levels_keeper() -> None:
    """#1199: measure the sample library's loudness, a few files a minute.

    Measuring an mp3 is an ffmpeg subprocess - 2.3s a clip measured, and
    the pool holds five thousand. Done inside the request the SFX desk
    took 139 seconds to answer; done here it costs nothing anybody is
    waiting on, and the desk reads the cache.

    Off the loop in a thread, small batches, and only while the show is
    on and samples are enabled - the same conditions #1062's arrivals
    walk keeps."""
    while True:
        try:
            await asyncio.sleep(45)
            if not (_RADIO.get("on") and dj_settings().get("sfx")):
                continue

            def batch() -> int:
                done = 0
                for path in sfx_pool_cached():
                    if done >= 8:
                        break
                    try:
                        if sfx_level(path, measure=False) is None:
                            sfx_level(path, measure=True)
                            done += 1
                    except Exception:  # noqa: BLE001
                        continue
                if done:
                    _sfx_level_save()
                return done

            got = await asyncio.to_thread(batch)
            if got:
                _SFX_LEVELS_DONE[0] += got
        except asyncio.CancelledError:
            raise
        except Exception:  # noqa: BLE001
            await asyncio.sleep(30)


_SFX_LEVELS_DONE = [0]


async def sfx_arrivals_keeper() -> None:
    """#1062: the walk on its own clock. sting_due only asked for a
    refresh when a sting happened to be due, so a quiet stretch never
    noticed a new file; the show now looks once a minute while it is on
    and samples are enabled.

    #1070: this was defined as a second `sfx_keeper`, so the #835 body
    below replaced it at import and dj_start spawned another #835 walker
    each time the show started; the once-a-minute look never ran."""
    while True:
        try:
            await asyncio.sleep(60)
            if not (_RADIO.get("on") and dj_settings().get("sfx")):
                continue
            if time.time() - _SFX_POOL_AT[0] >= 60:
                await _sfx_pool_refresh()
        except asyncio.CancelledError:
            raise
        except Exception:  # noqa: BLE001
            pass


def _sfx_pool_signature() -> tuple:
    """Settings identity only; never resolve or enumerate the sample share."""
    settings = dj_settings()
    return (tuple(settings.get("sfx_folders") or SFX_DEFAULT_FOLDERS),
            tuple(settings.get("sfx_drop_folders") if settings.get("sfx_drop_folders") is not None
                  else SFX_DROP_FOLDERS), bool(settings.get("sfx_make")),
            sfx_cap_seconds(), str(SFX_ROOT), str(SFX_LOCAL_ROOT), str(SFX_MADE_DIR))


def _sfx_pool_warm(folders: list[Path], cap: float, valid: Any, publish: Any) -> list[Path]:
    """Validate a small cached subset in a worker, before any full inventory."""
    import math as _math
    import stat as _stat
    parents = set(folders)
    candidates = []
    for key, seconds in list(_SFX_LEN_CACHE.items()):
        try:
            raw, stamp = key.rsplit(":", 1)
            path, duration = Path(raw), float(seconds)
            if (path.parent in parents and path.suffix.lower() in MUSIC_TYPES
                    and _math.isfinite(duration) and 0 < duration <= cap):
                candidates.append((path, int(stamp)))
        except (TypeError, ValueError):
            continue
    random.shuffle(candidates)
    out = []
    deadline = time.monotonic() + 2.0
    for path, stamp in candidates[:256]:
        if not valid() or len(out) >= 64 or time.monotonic() >= deadline:
            break
        try:
            # Resolve only this bounded candidate, so symlinks cannot borrow
            # a trusted duration from outside the configured sample folders.
            if path.resolve().parent not in parents:
                continue
            observed = path.stat()
            if (not _stat.S_ISREG(observed.st_mode) or observed.st_size <= 0
                    or observed.st_mtime_ns != stamp):
                continue
        except OSError:
            continue
        out.append(path)
        if len(out) == 1 or len(out) % 8 == 0:
            publish(tuple(out))
    if out:
        publish(tuple(out))
    return out


async def _sfx_pool_refresh() -> None:
    """#826: the pool scan walks a CIFS share of thousands of files and
    probes uncached durations — done SYNCHRONOUSLY inside sting_due it
    stalled the whole event loop on every other line (healthz itself
    was timing out). The walk lives in a worker thread now; picks read
    the cache."""
    if _SFX_POOL_FILLING[0]:
        return
    _SFX_POOL_FILLING[0] = True
    signature, job = _sfx_pool_signature(), object()
    _SFX_POOL_JOB[0] = job
    loop = asyncio.get_running_loop()
    was = len(_SFX_POOL_CACHE)
    if _SFX_POOL_SIGNATURE[0] != signature:
        _SFX_POOL_CACHE.clear()
        _SFX_POOL_AT[0] = 0.0
        _SFX_POOL_READY_AT[0] = 0.0
    _SFX_POOL_SIGNATURE[0] = signature
    baseline = tuple(_SFX_POOL_CACHE)

    def current() -> bool:
        return _SFX_POOL_JOB[0] is job and _sfx_pool_signature() == signature

    def publish(paths: tuple[Path, ...]) -> None:
        # This callback runs on the event loop; only memory/local policy reads.
        if not current():
            return
        banned, weights = sfx_bans(), sfx_weights()
        _SFX_POOL_CACHE[:] = [p for p in dict.fromkeys(paths)
            if sfx_id(p) not in banned and weights.get(sfx_id(p), 1.0) > 0.05]
        if _SFX_POOL_CACHE:
            _SFX_POOL_READY_AT[0] = time.time()

    def emit(paths: tuple[Path, ...]) -> None:
        if current():
            loop.call_soon_threadsafe(publish, paths)

    try:
        def scan() -> tuple[list[Path], set[str], list[str], int]:
            # Another startup hook loads after three seconds. This worker
            # must load first itself, or its cold scan wins that startup race.
            _sfx_len_load()
            folders = sfx_folders()
            cap = signature[3]
            warm = (list(baseline) if baseline else
                    _sfx_pool_warm(folders, cap, current, emit))
            pool: list[Path] = []
            have: set[str] = set()
            last_publish = time.monotonic()

            def add(path: Path) -> None:
                nonlocal last_publish
                if str(path) in have or not current():
                    return
                seconds = sfx_seconds(path)
                if not (0 < seconds <= cap or seconds <= 0 and SFX_MADE_DIR in path.parents):
                    return
                pool.append(path)
                have.add(str(path))
                if len(pool) == 1 or len(pool) % 32 == 0 or time.monotonic() - last_publish >= .5:
                    emit(tuple(warm + pool))
                    last_publish = time.monotonic()

            if signature[2]:
                for path in scratch_stock():
                    add(path)
            # #835: the raw INVENTORY as well as the playable pool, so
            # arrivals can be reported. It is the same directory read the
            # walk below already pays for, and it runs in the same worker
            # thread - nothing new touches the event loop.
            seen: set[str] = set()
            for folder in folders:
                if not current():
                    return [], set(), [], len(folders)
                try:
                    found = []
                    for one in folder.iterdir():
                        if one.is_file() \
                                and one.suffix.lower() in MUSIC_TYPES:
                            seen.add(str(one))
                            found.append(one)
                    # Keep the rotating per-folder cap without walking every
                    # directory a second time through sfx_all/sfx_list.
                    selected = (sorted(found) if len(found) <= SFX_MAX_FILES
                                else random.sample(found, SFX_MAX_FILES))
                    for path in selected:
                        add(path)
                except Exception:  # noqa: BLE001
                    continue        # that folder went away; carry on
            if not current():
                return [], set(), [], len(folders)
            # #1062: first sightings go on the ledger in this same worker
            # thread, and the arrivals it names are the ones this walk met
            # for the first time - across restarts, not per session.
            fresh_names = _sfx_arrivals_note(seen)
            # ...and a recent arrival is IN the pool regardless of the
            # SFX_MAX_FILES sample sfx_list draws from a big folder.
            for one in sfx_arrivals_recent():
                if not current():
                    return [], set(), [], len(folders)
                if one in seen and one not in have:
                    add(Path(one))
            return pool, seen, fresh_names, len(folders)
        pool, seen, arrived, folder_count = await asyncio.to_thread(scan)
        if not current():
            return
        _SFX_SEEN.clear()
        _SFX_SEEN.update(seen)
        publish(tuple(pool))
        _SFX_POOL_AT[0] = time.time()
        if arrived:
            pipeline_log("air", f"{len(arrived)} new sample(s) turned "
                         "up on the share and are in the rotation now - "
                         "half the draws go to what is fresh (#835/#1062)",
                         extra="\n".join(Path(one).name
                                         for one in arrived[:40]))
        # #862: say the size out loud when it MOVES. A pool that
        # collapses (an unmounted share) used to be invisible — the
        # DJs simply kept hitting the same two local files.
        if _SFX_LEN_DIRTY[0]:
            await asyncio.to_thread(_sfx_len_save)      # #863
        if len(pool) != was:
            pipeline_log("air", f"the sample pool is {len(pool)} clips "
                         f"(was {was}) across "
                         f"{folder_count} folder(s) (#862)")
    except Exception:  # noqa: BLE001
        pass
    finally:
        changed = _sfx_pool_signature() != signature
        if _SFX_POOL_JOB[0] is job:
            _SFX_POOL_JOB[0] = None
        _SFX_POOL_FILLING[0] = False
        if changed:
            fire_and_forget(_sfx_pool_refresh())


async def sfx_keeper() -> None:
    """#835: the sample share, re-read on a clock.

    The pool cache only ever refreshed from inside sting_due - and only
    once the sfx switch, the gap and the rate dice had ALL come up, so on
    a quiet show a folder the operator was filling live could sit unseen
    for hours. This walks the share on its own interval, in a worker
    thread, so a file dropped into samples_grabbed is in the draw a
    couple of minutes later with no restart and no click.

    Nothing in here may take the station down: the interval read and the
    walk are each wrapped, and a missed rescan simply waits."""
    while True:
        try:
            gap = float(dj_settings().get("sfx_rescan_seconds")
                        or SFX_RESCAN_SECONDS)
        except Exception:  # noqa: BLE001
            gap = float(SFX_RESCAN_SECONDS)
        await asyncio.sleep(max(15.0, min(3600.0, gap)))
        try:
            await _sfx_pool_refresh()
        except Exception:  # noqa: BLE001
            pass                    # a missed rescan is not a dead show


@app.on_event("startup")
async def _startup_sfx_keeper() -> None:
    fire_and_forget(_sfx_pool_refresh())
    fire_and_forget(sfx_keeper())       # #835


def _sfx_cadence_enabled() -> bool:
    settings = dj_settings()
    return bool(settings.get("sfx") and int(settings.get("sfx_every_units") or 0) > 0)


def _sfx_cadence_pick() -> Path | None:
    """A bounded, cached draw from the configured drop family, off the event loop."""
    settings = dj_settings()
    roots = [root / str(folder).strip("/")
             for root in (SFX_ROOT, SFX_LOCAL_ROOT)
             for folder in (settings.get("sfx_drop_folders") or [])]
    banned, weights = sfx_bans(), sfx_weights()
    pool = [Path(p) for p in _SFX_POOL_CACHE
            if any(Path(p).is_relative_to(root) for root in roots)
            and sfx_id(Path(p)) not in banned
            and weights.get(sfx_id(Path(p)), 1.0) > 0.05]
    last = str(_SFX_CADENCE_STATUS.get("last_sample") or "")
    fresh = [p for p in pool if str(p) != last]
    if fresh:
        pool = fresh
    # Never walk the share or probe its entire catalogue on the microphone.
    for _ in range(min(64, len(pool))):
        path = random.choices(pool, weights=[weights.get(sfx_id(p), 1.0) for p in pool], k=1)[0]
        pool.remove(path)
        if path.is_file() and 0 < sfx_seconds(path) <= sfx_cap_seconds():
            _SFX_CADENCE_STATUS["last_sample"] = str(path)
            return path
    return None


async def _sfx_cadence_additions(who: str, text: str, completed: int,
                                seconds: float, ready_takes=None, ready_meta=None) -> list[dict]:
    try:
        return await _sfx_cadence_additions_inner(who, text, completed, seconds, ready_takes, ready_meta)
    except Exception as exc:  # optional media must not discard accepted speech
        pipeline_log("sfx", "optional punctuation unavailable: " + str(exc)[:160])
        return []


async def _sfx_cadence_additions_inner(who: str, text: str, completed: int,
                                      seconds: float, ready_takes=None, ready_meta=None) -> list[dict]:
    """Plan optional recorded punctuation. This never claims that anything aired."""
    if not _sfx_cadence_enabled() or who not in ("dj", "cohost", "third", "host"):
        return []
    settings = dj_settings()
    additions = []
    meta = ready_meta or {}

    def fits(extra: float) -> bool:
        total = float(seconds) + sum(float(r["seconds"]) + max(CONCAT_BEAT) for r in additions)
        total += float(extra) + max(CONCAT_BEAT)
        if ready_takes is not None:
            return _ready_round_fits(str(meta.get("prep_kind") or ""), ready_takes,
                                    meta.get("_ready_slot"), seconds=total,
                                    start_at=time.time() + 5.0)
        # Keep optional punctuation out of a long hardware announce's tail.
        return total <= max(150.0, float(seconds))

    if sfx_due_after(completed, int(settings.get("sfx_every_units") or 0)):
        _SFX_CADENCE_STATUS["sample_due"] += 1
        sample = await asyncio.to_thread(_sfx_cadence_pick)
        duration = sfx_seconds(sample) if sample else 0.0
        if sample and fits(duration):
            additions.append({"path": str(sample), "who": "board", "text": "🔊 " + sample.stem,
                              "seconds": duration, "sfx_sample_id": sfx_id(sample)})
        else:
            _SFX_CADENCE_STATUS["sample_omitted"] += 1
    guy_interval = int(settings.get("sfxguy_every_units", 4) or 0)
    if (sfx_due_after(completed, guy_interval) and settings.get("drop_voice")
            and random.random() < float(settings.get("sfxguy_rate") or 0) / 100.0):
        _SFX_CADENCE_STATUS["guy_due"] += 1
        take = sfxguy_ready_pick(text, str(settings["drop_voice"]))
        if take and fits(float(take.get("seconds") or 0)):
            additions.append({"path": str(VOICE_MEDIA_DIR / str(take["clip"]["path"]).rsplit("/", 1)[-1]),
                              "who": "drop", "text": take["text"], "voice": take["voice"],
                              "seconds": float(take["seconds"]), "sfxguy_reservation": take["id"]})
        else:
            if take:
                sfxguy_ready_release(take["id"])
            _SFX_CADENCE_STATUS["guy_omitted"] += 1
    return additions


def _sfx_cadence_release(rows) -> None:
    for row in rows:
        if row.get("sfxguy_reservation"):
            sfxguy_ready_release(str(row["sfxguy_reservation"]))


def _box_receipt_audible(receipt: dict) -> bool:
    """Use the level actually dispatched, never the slider's later position."""
    if receipt.get("intentional_mute"):
        return False
    try:
        return "audible_gain" not in receipt or float(receipt["audible_gain"]) > 0
    except (TypeError, ValueError):
        return False


def _box_receipt_heard(path: str, receipt: dict) -> bool:
    """A whole-line receipt belongs to this recording and was not cut short."""
    return bool(path and receipt.get("key") == _played_out_key(path)
                and receipt.get("ok") is True and not receipt.get("interrupted")
                and _box_receipt_audible(receipt))


def _system2_repeat_rows(rows, entry=None) -> bool:
    """The exact repeat rule applies after every formatter and assembly await."""
    if not globals().get("_system2"):
        return True
    texts = []
    for row in rows:
        if row.get("who") == "board":
            continue
        for field in ("remember_text", "turn_text", "text", "chunk"):
            text = str(row.get(field) or "")
            if text and text not in texts:
                texts.append(text)
    return _system2().repeat_allowed(texts, entry)


def _system2_acknowledge_row(clip, row, receipt_id) -> None:
    """Remember both an audible chunk and its whole-turn identity, once."""
    if not globals().get("_system2"):
        return
    # #1070: a receipt the ledger will not take (the same receipt id seen
    # before with different words) is logged, never raised into the page
    # or box acknowledgement that delivered the line.
    try:
        _system2().acknowledge_line(clip, row, receipt_id)
        text = str(row.get("text") or "")
        memory = str(row.get("remember_text") or text)
        if text and text != memory:
            _system2().acknowledge_line(clip, {**row, "remember_text": text}, receipt_id + ":chunk")
    except Exception as exc:  # noqa: BLE001
        try:
            pipeline_log("drop", "(#1070) the hour ledger refused a receipt",
                         extra=f"{receipt_id}: {type(exc).__name__}: {exc}"[:300])
        except Exception:  # noqa: BLE001
            pass


def _sfx_cadence_audible(rows, position: float, previous: float = 0.0) -> None:
    """A completed audible row counts once, including page plus hardware copies."""
    complete = [r for r in rows if r.get("id") and "until" in r
                and float(r["until"]) <= float(position) + 0.05
                and float(r["until"]) >= float(previous)
                and float(r["until"]) > float(r.get("from") or 0)]
    receipts = [{"id": str(r["id"]),
                 "units": int(r.get("who") in ("dj", "cohost", "third", "host")),
                 "sample": str(r.get("sfx_sample_id") or "")} for r in complete]
    added = set(_SFX_CADENCE.record(receipts)) if receipts else set()
    for row in complete:
        if str(row["id"]) in added and row.get("sfx_sample_id"):
            try:
                sfx_note_play(str(row["sfx_sample_id"]), str(row.get("text") or "").removeprefix("🔊 "), "board")
            except Exception:
                pass  # the durable cadence receipt is already saved
        if str(row["id"]) in added and row.get("sfxguy_reservation"):
            sfxguy_ready_commit(str(row["sfxguy_reservation"]))


def sting_due() -> Path | None:
    """Whether to drop one now, and which. Spontaneous means unpredictable,
    not constant: a roll of the dice, and never twice inside the gap."""
    dj = dj_settings()
    if not (dj["sfx"] and dj["sfx_rate"]):
        return None
    # A hard 45-second floor under the configured gap (#414): a six-turn
    # round rolls the dice six times, and back-to-back hits sounded like
    # the soundboard had a stuck key.
    # The dial is the dial. This read max(45.0, sfx_gap), so the "never twice
    # inside" slider did NOTHING below forty-five seconds and the desk's own
    # default of 12 was unreachable — which is why the show sounded bare.
    # A floor of three keeps one sting from landing on top of the last.
    if time.time() - _STING_AT[0] < max(3.0, float(dj["sfx_gap"])):
        return None
    if random.random() >= dj["sfx_rate"]:
        return None
    banned = sfx_bans()
    # #826: never walk the share here — the cache refreshes off-loop
    # once a minute, and a newly dropped file is in the draw on the
    # next refresh rather than at the price of a frozen event loop.
    if time.time() - _SFX_POOL_AT[0] > 60:
        fire_and_forget(_sfx_pool_refresh())
    pool = [p for p in _SFX_POOL_CACHE if sfx_id(p) not in banned]
    if not pool:
        return None
    # Your dial on each one (#645): a sample marked down comes up rarely, one
    # marked up leans in. Applied as repeats in the draw so the unrepeated
    # memory below still works exactly as it did.
    weights = sfx_weights()
    if weights:
        weighted: list[str] = []
        for path in pool:
            want = weights.get(sfx_id(path), 1.0)
            if want <= 0.05:
                continue                    # marked all the way down
            weighted += [str(path)] * max(1, int(round(want * 2)))
        names_pool = weighted or [str(p) for p in pool]
    else:
        names_pool = [str(p) for p in pool]
    # #1062: HALF THE DRAWS GO TO WHAT IS NEW. A never-played sample, or
    # one first seen inside SFX_FRESH_HOURS, is drawn from its own short
    # list on a coin flip - through the same unrepeated memory, so a
    # single new file does not land three times in a row. The other half
    # of the draws is the rotation exactly as it was.
    try:
        fresh = {str(p) for p in sfx_fresh_paths(pool)}
    except Exception:  # noqa: BLE001
        fresh = set()
    if fresh and random.random() < SFX_FRESH_SHARE:
        fresh_pool = [n for n in names_pool if n in fresh] or sorted(fresh)
        names = unrepeated(fresh_pool, "sting",
                           keep=min(12, max(1, len(set(fresh_pool)) - 1)))
        if names:
            pipeline_log("air", f"(#1062) a fresh sample drawn ahead of "
                         f"the rotation: {Path(names).name} "
                         f"({len(fresh)} fresh of {len(pool)} in the pool)")
            return Path(names)
    names = unrepeated(names_pool, "sting",
                       keep=min(12, max(1, len(set(names_pool)) - 1)))
    return Path(names) if names else None


# How the booth feels about the sample that just went off (#292).
STING_REACTIONS = (
    "Ugh. Was that necessary?",
    "Do we need to do that every single time?",
    "I hate that button. I hate it.",
    "That was inappropriate and you know it.",
    "Every time. Every time with that thing.",
    "Warn me before you hit that. Please.",
    "Anyway. Moving on.",
)


async def _sting_react(who: str) -> None:
    """The OTHER presenter groans at the sample (#292), then the show
    carries on. by_hand so a groan is never busy-dropped mid-round; the
    sting gap stops the groan's own tail from firing another sample."""
    try:
        await asyncio.sleep(0.7)
        await dj_speak("reply", None,
                       line=unrepeated(list(STING_REACTIONS), "sting-react"),
                       who=who, by_hand=True)
    except Exception:
        pass


async def _sfx_verdict(about: str) -> None:
    """The SFX guy weighs in from his booth (#322): when the pair go
    looking for approval, the man of few words gives ONE deadpan line —
    agreement or argument — in his own voice, then goes back to his
    buttons."""
    try:
        dj = dj_settings()
        if not dj["drop_voice"]:
            return
        line = await ask_model(
            "You are the SFX guy in the corner booth of a radio studio — "
            "a man of VERY few words who almost never speaks. The "
            "presenters just appealed to you for approval about this: "
            f"\"{about[:300]}\" Write your ONE short deadpan line — firm "
            "agreement or blunt argument, nothing more. No stage "
            # #1027: his warps and his news takes carry the crystal; this
            # one did not, so the same man came back untinted whenever he
            # was asked for a verdict.
            "directions." + crystal_tint_note(), 120)
        # #1038: he is answering something that just aired, so one ask.
        line = await crystal_line(str(line or ""), "an SFX guy verdict", 1)
        if line:
            await asyncio.sleep(0.6)
            await dj_speak("reply", None, line=line, who="drop",
                           voice=dj["drop_voice"], name="The SFX Guy",
                           by_hand=True)
    except Exception:
        pass


def _sfx_any() -> Path | None:
    """A short unbanned sample, ignoring the rate/gap gate (#464) — for
    places that WANT a sound effect every time, like a custom ad."""
    banned = sfx_bans()
    pool = [p for p in sfx_all() if sfx_short(p) and sfx_id(p) not in banned]
    if not pool:
        return None
    names = unrepeated([str(p) for p in pool], "sting",
                       keep=min(12, max(1, len(pool) - 1)))
    return Path(names) if names else None


async def _sting_over_record(track: dict[str, Any] | None) -> None:
    """#1062 (2026-09-07): a sound effect does not need a line to ride on.

    Every sting rolled inside speak_turns, so an hour with no finished
    dialogue was an hour with no sound effects either - the operator
    heard records and nothing else. Once the needle is down the dice
    roll on the record itself, at the same dial and gap, never over a
    voice and never while paused."""
    try:
        await asyncio.sleep(random.uniform(8.0, 25.0))
        why = ""
        for _try in range(5):
            if radio_paused() or not _RADIO.get("on"):
                return
            if _SPEAKING[0]:
                why = "a voice is on the air"
            elif _floor_busy():
                why = "the floor is held"
            elif time.time() - _SPOKE_AT[0] < 2.5:
                why = "a line just ended"
            else:
                why = ""
                break
            await asyncio.sleep(random.uniform(9.0, 14.0))
        if why:
            pipeline_log("air", "sting over the record skipped - "
                         f"{why} (#1062)")
            return
        vto = _RADIO.get("voice_to") or "box"
        try:
            to_box = (vto in ("box", "both") and box_talk_ok()
                      and not box_firmware_down_now())
        except Exception:  # noqa: BLE001
            to_box = vto in ("box", "both")
        got = await dj_sting(to_box, who="record")
        if got:
            pipeline_log("air", "sting: a sample dropped over "
                         f"{(track or {}).get('title') or 'the record'} - "
                         "no line needed (#1062)")
        else:
            pipeline_log("air", "sting over the record: the dice said no "
                         "or the gap is not up (#1062)")
    except Exception as exc:  # noqa: BLE001
        pipeline_log("air", "sting over the record failed: "
                     f"{type(exc).__name__}: {exc}"[:160])


# 2026-09-08: "I want dead air always being punctuated with SFX clips. If
# there is a period of dead air, let the sfx attempt to fill it with clips
# and keep the momentum going." Measured before this: silence was answered
# only by dropping the needle on the next record (dead_air_watch), the talk
# gap's last resort was a LIVE render (cover_the_gap), and a floor held for
# a slow render left the air empty for neither watchdog to touch - the
# ~23,000 pre-rendered samples and the SFX Guy's recorded liners were never
# drawn from a silence path.
_SFX_GAP: dict[str, Any] = {"at": 0.0, "turn": 0, "count": 0, "why": "", "went": ""}
# 2026-09-08 (the flow scan): six, not nine. The operator's rule is a
# ten-second maximum intermission; with a nine-second rest plus detection
# and the announce the first filler cannot land inside ten. The bank can
# afford it - 400 gold bars at a five-minute rest serve 300 an hour
# against the 174 the rule needs.
SFX_GAP_REST = float(os.getenv("SFX_GAP_REST", "6"))


async def sfx_fill_gap(why: str = "", under_floor: bool = False) -> str:
    """Punctuate dead air with a clip that already exists - the SFX Guy's
    prepared station liner off its shelf when he has one (the pantry
    serves it; nothing renders), else a short sample off the pool - and
    never a render: the point is to buy the render its time. Returns what
    went out ("bar" / "liner" / "sample") or "".

    Never over a voice, never while paused, and it rests SFX_GAP_REST
    between clips (or the operator's sfx_gap dial, if longer). With
    `under_floor` it may fire while a writer holds the floor for a render
    that has not started playing - the one silence #1146's hold used to
    leave unpunctuated. Under the floor a GOLD BAR and a sample go out
    (both are clips that already exist, on the floorless road); only the
    liner waits, because a liner is written and would queue behind the
    round it is covering for."""
    try:
        if radio_paused() or not _RADIO.get("on"):
            return ""
        if _SPEAKING[0]:
            return ""
        floor_held = _floor_busy()
        if floor_held and not under_floor:
            return ""
        if time.time() - _SPOKE_AT[0] < 2.5:
            return ""
        # 2026-09-09: AIR ALREADY SOLD IS NOT DEAD AIR. The run below sells
        # up to forty-five seconds ahead on the page road, and a listener
        # whose client has not acknowledged playout yet leaves
        # talk_quiet_for() climbing the whole time - so the watchdog would
        # come back every two seconds and lay another run on top of the one
        # already sounding. The cursor is the truth: while it is in the
        # future, somebody is talking.
        try:
            if float(_PAGE_AIR_UNTIL[0] or 0) - time.time() > 1.5:
                return ""
        except Exception:  # noqa: BLE001
            pass
        rest = SFX_GAP_REST
        try:
            rest = max(rest, float(dj_settings().get("sfx_gap") or 0))
        except Exception:  # noqa: BLE001
            pass
        if time.time() - float(_SFX_GAP.get("at") or 0) < rest:
            return ""
        _SFX_GAP["at"] = time.time()
        _SFX_GAP["turn"] = int(_SFX_GAP.get("turn") or 0) + 1
        vto = _RADIO.get("voice_to") or "box"
        try:
            to_box = (vto in ("box", "both") and box_talk_ok()
                      and not box_firmware_down_now())
        except Exception:  # noqa: BLE001
            to_box = vto in ("box", "both")
        went = ""
        drop_voice = ""
        try:
            drop_voice = str(dj_settings().get("drop_voice") or "")
        except Exception:  # noqa: BLE001
            drop_voice = ""
        # 2026-09-08 (evening): "keep the station rapping 24/7" - a rhymed
        # bar that already aired, with its own take, goes out FIRST; the
        # liner and the sample are what is left while the gold rests.
        # 2026-09-08 (the flow scan): AND IT GOES OUT UNDER THE FLOOR TOO,
        # on the floorless road, because it is a clip that already exists.
        # Only the liner still waits for the floor - a liner is written and
        # rendered, and would queue behind the round it is covering for.
        went = await gold_fill_gap(
            why, floorless=floor_held,
            ahead=GOLD_RUN_AHEAD_HELD if floor_held else GOLD_RUN_AHEAD)
        if not went and drop_voice and not floor_held and _SFX_GAP["turn"] % 2 == 0:
            # A liner written and recorded for this voice earlier (#842):
            # the same road dj_sting's drop branch takes.
            _prep = None
            try:
                _prep = shelf_take("station_id", voice=drop_voice)
            except Exception:  # noqa: BLE001
                _prep = None
            if _prep and str(_prep.get("text") or "").strip():
                try:
                    out = await dj_speak("station_id", None, line=str(_prep["text"]),
                                         who="drop", voice=drop_voice, name="The SFX Guy")
                    went = "liner" if out else ""
                except Exception:  # noqa: BLE001
                    went = ""
        if not went:
            try:
                went = "sample" if await dj_sting(to_box, who="gap", force=True) else ""
            except Exception:  # noqa: BLE001
                went = ""
        if went:
            _SFX_GAP["count"] = int(_SFX_GAP.get("count") or 0) + 1
            _SFX_GAP["why"] = str(why)[:120]
            _SFX_GAP["went"] = went
            pipeline_log("air", f"dead air punctuated with a {went}"
                                + (f" - {why}" if why else "")
                                + (" (under the floor)" if floor_held else ""))
        return went
    except Exception as exc:  # noqa: BLE001
        pipeline_log("air", "the gap filler failed: "
                     f"{type(exc).__name__}: {exc}"[:160])
        return ""


def sfx_gap_status() -> dict[str, Any]:
    return {**_SFX_GAP, "rest": SFX_GAP_REST}


async def dj_sting(to_box: bool, after: str = "", who: str = "",
                   force: bool = False,
                   sample: Path | None = None) -> str:
    """Drop a sample off the end of what was just said.

    Both outputs, one place. On the box it is a second announce, which is why
    this is only ever called once the line itself has finished playing — an
    announce preempts, and the satellite has no stop service, so a sting fired
    early would take the line away instead of decorating it. `force` ignores
    the rate/gap gate and always drops an actual sample (#464)."""
    # In a thread: picking one reads a folder over SMB, and a NAS that has
    # gone away would otherwise hold up the whole event loop mid-show.
    # #1034: unless the caller chose the sample (a door behind an exit).
    if sample is None:
        sample = await asyncio.to_thread(sting_due)
    if sample is None and force:
        sample = await asyncio.to_thread(_sfx_any)
    if sample is None:
        return ""
    # The drop guy (#282): now and then, where a sample would have gone, a
    # VOICE shouts a liner instead — his own voice, assignable like any
    # other. Empty voice = the feature does not exist. A forced sting wants
    # an actual SOUND, so it skips the voice-liner substitution.
    drop_voice = str(dj_settings().get("drop_voice") or "")
    if drop_voice and not force and random.random() < 0.25:
        _STING_AT[0] = time.time()
        station = dj_settings()["station_name"]
        # The SFX guy's liner is a read FOR the station, so it always names
        # it in full (#462) — pick only the station-naming lines, and route
        # it as a station ID so the name governor leaves the full name in
        # (an "interject" would have scrubbed it down to "the station").
        # #882: written, seeded, and never the line just heard.
        # #842: a liner WRITTEN AND SHOUTED during an earlier record —
        # the sting costs the model and the voice engine nothing. Only a
        # liner prepared for THIS voice is taken; an empty shelf writes
        # one here exactly as before.
        _prep_id = None
        try:
            _prep_id = shelf_take("station_id", voice=drop_voice)
        except Exception:  # noqa: BLE001
            _prep_id = None
        if _prep_id and str(_prep_id.get("text") or ""):
            line = str(_prep_id["text"])
        else:
            line = await drop_liner(station)
            if station and station.lower() not in line.lower():
                line = f"{line} {station}."
        try:
            await dj_speak("station_id", None, line=line, who="drop",
                           voice=drop_voice, name="The SFX Guy")
        except Exception:
            pass
        return "drop"
    _STING_AT[0] = time.time()
    key = sfx_id(sample)
    signature = media_sign(key)
    # On the record like any spoken line (#269): which sample, from which
    # folder, with enough identity for the panel to vote it off the air.
    # #903 (#848): this row was written BEFORE any attempt to play, and
    # carried no `aired` key at all — so a sting that never sounded read
    # exactly like one that did. It is stamped now, and the branch below
    # that already knows it was dropped corrects it.
    _sting_row = {
        "ts": int(time.time()), "air_at": time.time(),
        "who": "board", "kind": "sfx",
        "text": sample.stem, "sfx": key,
        "sfx_dir": sample.parent.name or "sfx",
        # #704: how long it ran, on the entry — the point of seeing them
        # listed is being able to weed the ones that do not fit.
        "seconds": round(sfx_seconds(sample), 2),
        "url": f"/sfx/{key}?t={signature}",
        "aired": "airing",
    }
    _RADIO["chat"].append(_sting_row)
    del _RADIO["chat"][:-240]
    note_activity("sting", sample.stem)
    # #862: write it down — the operator rules on the rotation from this.
    sfx_history_add(sample, who)
    # The stings are part of the broadcast, so the episode recording keeps them
    # too (#560) — staged from the SFX store, which lives outside /media.
    _episode_stage(f"/sfx/{key}", f"[sfx] {sample.stem}", src_path=sample)
    _sting_started = time.monotonic()
    # Only where the line itself went. Queued for a browser in box-only mode
    # it would arrive as a scratch with no DJ in front of it, because the
    # line was never synthesised for that page. Exception (#559): when the box
    # is down/backed-up the voice lines mirror to the page, so the stings must
    # ride along or the page hears talk with no punctuation.
    _sfx_box_down = (time.time() < float(_BOX_DOWN.get("until") or 0)
                     or len(_BOX_HOLD) >= 6)
    if ((_RADIO.get("voice_to") or "box") != "box" or _sfx_box_down
            or _RADIO.get("monitor")):     # #825
        page_feed_append({              # #1147: honest broadcast stamp
            "url": f"/sfx/{key}?t={signature}",
            "text": "", "sting": sample.stem,
        })
    # A sting is MEANT to land over the DJ's own line it punctuates, so the
    # show's own just-finished announce tail must not block it (#559: "the
    # sound effects aren't coming through"). Same own-tail carve-out as the
    # voice path (#520) — still defers to a genuine human turn on the line.
    own_tail = (_SPEAKING[0] == 0
                and time.time() - _SPOKE_AT[0] <= _OUR_VOICE_FOR
                and time.time() - _SAT_SAW_TURN_AT[0] >= 30.0)
    played_anywhere = not to_box        # the page copy above counts
    if to_box and (own_tail or not await satellite_busy()):
        _SPEAKING[0] += 1
        try:
            await _play_on_box(f"/sfx/{key}", signature)
            played_anywhere = True
        except Exception:
            pass                        # a missing sting is not a dead show
        finally:
            _SPEAKING[0] = max(0, _SPEAKING[0] - 1)
            _SPOKE_AT[0] = time.time()
    elif to_box:
        # #738: the satellite was busy and this was not the own-tail
        # window, so the sting was dropped on the floor — and yet
        # sfx_note_play below still recorded it as played, which is
        # exactly "it was queued and it never sounded". Send it to the
        # page instead: heard in the wrong room beats not heard, and
        # say so rather than logging a play that never happened.
        page_feed_append({              # #1147: honest broadcast stamp
            "url": f"/sfx/{key}?t={signature}",
            "text": "", "sting": sample.stem,
        })
        played_anywhere = True
        pipeline_log("air", f"sting {sample.stem} could not go to the "
                            "box (satellite busy) — sent to the page "
                            "instead (#738)")
    if played_anywhere:
        sfx_note_play(key, sample.stem, who,
                      ms=int((time.monotonic() - _sting_started) * 1000))
        # #905: THE SUCCESS BRANCH, which #903 left out — the row was
        # stamped "airing" before the attempt and nothing ever took it
        # down, so every sting that played kept shouting "going out right
        # now" in red for the rest of the night.
        try:
            _sting_row["aired"] = "box" if to_box else "page"
            _sting_row["air_at"] = time.time()
        except Exception:  # noqa: BLE001
            pass
    else:
        pipeline_log("drop", f"sting {sample.stem} never sounded (#738)")
        try:                                   # #903/#905 (#848)
            # "never" is the word the glass tests for; "never sounded"
            # matched no branch and rendered as an ordinary row.
            _sting_row["aired"] = "never"
        except Exception:  # noqa: BLE001
            pass
    # Sometimes the other presenter has FEELINGS about the sample (#292).
    if who in ("dj", "cohost", "third") and random.random() < 0.3:
        other = "cohost" if who != "cohost" else "dj"
        asyncio.create_task(_sting_react(other))
    return sample.name


# --- Banter you wrote and approved (#202) -----------------------------------
# An exchange in the same "A: … B: …" shape the model writes, kept so it can
# come round again — written by hand, or caught off the air and kept.

SAVED_BANTER_PATH = data_path("banter_saved.json")
SAVED_BANTER_MAX = 200
_SAVED_LOCK = RLock()


def read_saved_banter() -> list[dict[str, Any]]:
    try:
        rows = json.loads(SAVED_BANTER_PATH.read_text())
        return rows if isinstance(rows, list) else []
    except Exception:
        return []


def write_saved_banter(rows: list[dict[str, Any]]) -> None:
    with _SAVED_LOCK:
        try:
            SAVED_BANTER_PATH.parent.mkdir(parents=True, exist_ok=True)
            SAVED_BANTER_PATH.write_text(
                json.dumps(rows[:SAVED_BANTER_MAX], indent=1))
        except OSError:
            pass


def add_saved_banter(text: str, source: str = "") -> dict[str, Any]:
    """Keep an exchange. Anything without a speaker marker is taken as one
    line for the host, so you can write "he never pays for the coffee" and
    have it come out of somebody's mouth."""
    text = str(text or "").strip()[:1200]
    if not re.search(r"(?:^|\s)[AB]\s*[:\-]\s*", " " + text, re.I):
        text = "A: " + text
    with _SAVED_LOCK:
        rows = read_saved_banter()
        row = {"id": uuid.uuid4().hex[:8], "text": text, "source": source,
               "added": int(time.time()), "used": 0}
        rows.insert(0, row)
        write_saved_banter(rows)
        return row


def delete_saved_banter(saved_id: str) -> None:
    with _SAVED_LOCK:
        write_saved_banter(
            [r for r in read_saved_banter() if r.get("id") != saved_id])


def draw_saved_banter() -> dict[str, Any]:
    """Whichever approved exchange has had the least air time — and nothing
    aired inside the last half hour. One kept row with no cooldown owned
    seventy percent of the show, forty-three airings in a day."""
    now = time.time()
    # #752: a ladder, not a flat half hour. A kept line waits an hour before
    # its first return, three before its second, and five from then on — the
    # rotation the request asks for, driven off the row's own airing count.
    rows = [r for r in read_saved_banter()
            if now - float(r.get("last") or 0)
            > TIER_GATES[min(int(r.get("used") or 0), 2)]]
    if not rows:
        return {}
    fewest = min(int(r.get("used") or 0) for r in rows)
    chosen = random.choice(
        [r for r in rows if int(r.get("used") or 0) == fewest])
    with _SAVED_LOCK:
        rows = read_saved_banter()
        for row in rows:
            if row.get("id") == chosen["id"]:
                row["used"] = int(row.get("used") or 0) + 1
                row["last"] = int(time.time())
        write_saved_banter(rows)
    # #752: "cycled out when they're not working". A kept line that keeps
    # colliding with fresher material has stopped earning its place, and the
    # print ledger is the only thing that knows. Retired through bin_line so
    # it inherits the never-say-this-again path rather than a second one.
    hits = next((r for r in line_prints()
                 if r.get("key") == _bin_key(chosen.get("text", ""))), {})
    if int(hits.get("blocked") or 0) >= 3:
        bin_line(str(chosen.get("text") or ""))
        pipeline_log("model", "a kept line stopped working and was cycled "
                              "out of the bank (#752)")
    return chosen


# Lines you have thumbed down. Approving a line is keeping it (above);
# burying one is the other half of the same gesture — it did not work, and it
# does not need to come round again (#215).
BINNED_PATH = data_path("banter_binned.json")
BINNED_MAX = 500


def _bin_key(text: str) -> str:
    """Punctuation and capitals drift between one telling and the next; the
    words are what was buried."""
    return " ".join(re.sub(r"[^\w\s]", " ", str(text or "").lower()).split())


def read_binned() -> list[str]:
    try:
        rows = json.loads(BINNED_PATH.read_text())
        return [str(r) for r in rows] if isinstance(rows, list) else []
    except Exception:
        return []


def bin_line(text: str) -> None:
    key = _bin_key(text)
    if not key:
        return
    with _SAVED_LOCK:
        rows = [r for r in read_binned() if r != key]
        rows.insert(0, key)
        try:
            BINNED_PATH.parent.mkdir(parents=True, exist_ok=True)
            BINNED_PATH.write_text(json.dumps(rows[:BINNED_MAX], indent=1))
        except OSError:
            pass
    # It cannot come back as approved banter either.
    for row in read_saved_banter():
        if _bin_key(re.sub(r"^\s*[AB]\s*:\s*", "", row.get("text") or "")) == key:
            delete_saved_banter(row["id"])


def is_binned(text: str) -> bool:
    return _bin_key(text) in set(read_binned())


# --- The unique-dialogue engine (#752) --------------------------------------
#
# "I'm hearing a lot of people call in and say the same thing over and over."
# They were, and here is why: the only anti-repeat gate at air time lived in
# dj_speak, and dj_speak is not the road most of the show takes. With
# stream_show and call_stream on — both default — banter, deep rounds and
# calls all go down the COALESCED branch of speak_turns, which renders a
# whole round into one clip and never calls dj_speak at all. The check ran on
# the minority of lines and the majority sailed past it.
#
# This is that gate, moved to the one place every conversational path
# genuinely funnels through, plus the memory it needs to be more than a
# ten-line goldfish: a print ledger on disk with timestamps, so "never twice"
# can mean never, and so a line that WORKED can come back on a real rotation
# instead of at random.
LINE_PRINTS_PATH = data_path("line_prints.json")
# "If lines are cooked up to the point that they are rhyming, I want those
# stored for double the amount of time so they can be reused... those are
# the lines I want to hear fired repeatedly and strategically with SFX
# clips at the end." A rhymed line that aired with a finished take is GOLD:
# its take is protected from the media sweep, its print row lives twice as
# long and may come round twice as often, and at a sting moment a gold bar
# from the other seat fires first, the sting after it.
GOLD_PATH = data_path("gold_bars.json")
# 2026-09-08 (the flow scan): two thousand, not four hundred. Every
# accepted rendered bar is already harvested before its round is let go
# and its take is already shielded from the media sweep; the cap was the
# only thing throwing them away. 400 bars is 52 minutes of finished
# rhymed audio; 2,000 is about four hours, which makes "the same line
# aired a hundred times" arithmetically impossible.
GOLD_MAX = int(os.getenv("GOLD_MAX", "2000"))
# 2026-09-09 (#1157): the bank's bound spends the TAKE, never the line. Words
# cost ~250 kB a thousand; audio costs 48 kB a second.
GOLD_TEXT_MAX = int(os.getenv("GOLD_TEXT_MAX", "20000"))
GOLD_FIRE_RATE = 0.5                 # share of sting moments that fire a bar
GOLD_REST = 1200.0                   # the same bar rests twenty minutes
_GOLD: dict[str, Any] = {"loaded": False, "rows": []}


def _gold_rows() -> list[dict[str, Any]]:
    if not _GOLD["loaded"]:
        rows: list[dict[str, Any]] = []
        try:
            got = json.loads(GOLD_PATH.read_text())
            rows = [r for r in got if isinstance(r, dict)] if isinstance(got, list) else []
        except Exception:  # noqa: BLE001
            rows = []
        _GOLD.update({"loaded": True, "rows": rows})
    return _GOLD["rows"]


def _gold_save() -> None:
    try:
        GOLD_PATH.parent.mkdir(parents=True, exist_ok=True)
        tmp = GOLD_PATH.with_suffix(".tmp")
        tmp.write_text(json.dumps(_gold_rows()[-GOLD_TEXT_MAX:], ensure_ascii=False))
        tmp.replace(GOLD_PATH)
    except OSError:
        pass


def gold_note(who: str, text: str, path: str, seconds: float) -> bool:
    """A rhymed line that just aired with its take - kept as gold."""
    try:
        text = " ".join(str(text or "").split())
        name = str(path or "").rsplit("/", 1)[-1].split("?")[0]
        if not text or not name or not rap_rhyme_evidence(text).get("ok"):
            return False
        key = hashlib.sha1(text.lower().encode("utf-8", "ignore")).hexdigest()[:16]
        rows = _gold_rows()
        for row in rows:
            if row.get("key") == key:
                row.update({"path": name, "seconds": float(seconds or 0), "who": who,
                            "at": time.time()})
                _gold_save()
                return True
        rows.append({"key": key, "who": str(who or "dj"), "text": text[:400], "path": name,
                     "seconds": float(seconds or 0), "at": time.time(), "fired": 0,
                     "last": 0.0})
        gold_trim()
        _gold_save()
        return True
    except Exception:  # noqa: BLE001
        return False


def gold_trim() -> None:
    """2026-09-09 (#1157): hold the bank's bound by releasing TAKES, not bars.

    `del rows[:-GOLD_MAX]` was a silent FIFO on rhymed lines - the one thing
    the operator asked never to lose - and at 28 bars an hour it reached its
    cap in under three days. The bound now falls on the audio, most-fired
    first, so a bar nobody has heard keeps its take while one that has been
    out ten times gives its seconds back and keeps its words."""
    try:
        rows = _gold_rows()
        with_take = [r for r in rows if r.get("path")]
        over = len(with_take) - GOLD_MAX
        if over > 0:
            with_take.sort(key=lambda r: (-int(r.get("fired") or 0),
                                          float(r.get("at") or 0)))
            for r in with_take[:over]:
                r["path"] = ""              # the take goes; the line stays
        if len(rows) > GOLD_TEXT_MAX:
            del rows[:len(rows) - GOLD_TEXT_MAX]
    except Exception:  # noqa: BLE001
        pass


GOLD_GAP_REST = 300.0                # ...five minutes when it is filling dead air
# 2026-09-09: THE RUN. "I want the gold tinted material filling in the
# dead air constantly, ensuring that there is never dead air." Measured
# over 18 hours of the air log: the bank held 514 bars with their takes
# on disk (67 minutes of finished rhymed audio, 282 of them never fired
# once) and the filler still put out ONE bar per hole - 116 of its 134
# fills were a single 6.8s median bar against holes of median 20.7s,
# and 58 holes of ten seconds or more ended WITH an interject, which is
# the filler arriving late and then stopping. A hole is now filled
# until it is closed, not punctuated once.
GOLD_RUN_MOST = 12                   # bars one run may lay
GOLD_RUN_SECONDS = 180.0             # ...and the airtime it may sell
GOLD_RUN_AHEAD = 45.0                # how far ahead a run keeps the air sold
# ...but a shorter runway UNDER THE FLOOR. There the hole is a seam in a
# round that is still coming, and every bar the run sells pushes that
# round's next page further out - the air is never dead either way, and
# twenty seconds is enough to cover a page join (median 20.7s) without
# standing a conversation up for the better part of a minute. The run
# simply fires again if the hole outlasts it.
GOLD_RUN_AHEAD_HELD = 20.0


def gold_pick(exclude_who: str = "", min_rest: float | None = None) -> dict[str, Any] | None:
    """The bar to fire: another seat's, rested, least fired, take on disk."""
    try:
        now = time.time()
        rest = GOLD_REST if min_rest is None else float(min_rest)
        pool = [r for r in _gold_rows()
                if str(r.get("who") or "") != str(exclude_who or "")
                and now - float(r.get("last") or 0) >= rest
                and (VOICE_MEDIA_DIR / str(r.get("path") or "")).is_file()]
        if not pool:
            return None
        least = min(int(r.get("fired") or 0) for r in pool)
        pool = [r for r in pool if int(r.get("fired") or 0) == least]
        return random.choice(pool)
    except Exception:  # noqa: BLE001
        return None


def gold_fired(row: dict[str, Any]) -> None:
    try:
        row["fired"] = int(row.get("fired") or 0) + 1
        row["last"] = time.time()
        _gold_save()
    except Exception:  # noqa: BLE001
        pass


def gold_protected_files() -> set[str]:
    return {str(r.get("path") or "") for r in _gold_rows() if r.get("path")}


def _gold_norm(text: str) -> str:
    return " ".join(re.sub(r"[^a-z0-9 ]+", " ", str(text or "").lower()).split())


_GOLD_MARKER_WHO = {"A": "dj", "B": "cohost", "C": "caller", "D": "third", "E": "caller2"}


def gold_harvest_entry(entry: Any, why: str = "") -> int:
    """2026-09-08 (evening): "keep and reuse the elements that are converted
    into song lyrics." Every bar of a round that PASSED the grader, with its
    rendered take, goes into the gold store before the round is let go - a
    cut of one bar no longer throws away the twenty that passed (measured:
    a 21-line call went from 20 accepted bars to none). Returns how many."""
    try:
        if not isinstance(entry, dict):
            return 0
        progress = (entry.get("tint_progress") or {}).get("turns") or (entry.get("tint") or {}).get("review_turns") or []
        good = [r for r in progress if isinstance(r, dict)
                and (r.get("evaluation") or {}).get("ok") and str(r.get("text") or "").strip()
                and not r.get("cut")]
        if not good:
            return 0
        by_text: dict[str, dict[str, Any]] = {}
        for key in _row_clip_keys(entry):
            prow = _PANTRY.get(str(key)) or {}
            norm = _gold_norm(prow.get("text"))
            if norm and _pantry_key_ready(str(key)):
                by_text[norm] = prow
        kept = 0
        for r in good:
            text = " ".join(str(r.get("text") or "").split())
            prow = by_text.get(_gold_norm(text))
            if not prow:
                continue
            clip = prow.get("clip") or {}
            path = str(clip.get("path") or "")
            if not path:
                continue
            who = str(prow.get("who") or _GOLD_MARKER_WHO.get(str(r.get("marker") or ""), "dj"))
            try:
                seconds = float(clip.get("seconds") or 0) or _clip_seconds(path)
            except Exception:  # noqa: BLE001
                seconds = 0.0
            if gold_note(who, text, path, seconds):
                kept += 1
        if kept:
            pipeline_log("air", f"{kept} rhymed bar(s) of a round let go ({why or 'replaced'}) "
                                "kept as gold with their takes")
        return kept
    except Exception:  # noqa: BLE001
        return 0


async def gold_fill_gap(why: str = "", floorless: bool = False,
                        ahead: float = 0.0) -> str:
    """Rhymed bars that already aired, with their own takes, fill the air -
    no model, no render - and they keep coming until the hole is closed.
    Returns "bar" when at least one went out.

    2026-09-08 (the flow scan): with `floorless` the bars go out on the
    same road a sting takes, without claiming the air floor. Under the
    hold a bar used to be skipped entirely - `dj_speak` would take the
    floor and queue behind the very round it was covering for - so while a
    round rendered (measured 6 to 78 seconds a line) the station had
    fifty-two minutes of finished rhymed audio on disk and was forbidden
    to play any of it. That silence is 20% of all on-air time.

    2026-09-09: it lays a RUN. `ahead` is how many seconds of air the run
    must leave sold in front of it (GOLD_RUN_AHEAD by default), bounded by
    GOLD_RUN_MOST bars and GOLD_RUN_SECONDS of airtime so a wedged round
    cannot hand the whole hour to the bank. Each bar butts against the
    last - the seat alternates so a run does not read as one presenter
    talking to himself - and the loop stands down the moment the station
    pauses or goes off air. Nothing here renders or calls a model, so a
    run costs the preparer nothing it needed."""
    want = float(ahead) if ahead else GOLD_RUN_AHEAD
    want = max(0.0, min(want, GOLD_RUN_SECONDS))
    laid = 0.0
    bars = 0
    went = ""
    last_who = ""
    while bars < GOLD_RUN_MOST and laid < want:
        # The FIRST bar is the caller's decision - sfx_fill_gap has already
        # tested the air, and the sting road hands this the same permission.
        # What is guarded here is the RUN: a pause landing mid-run must not
        # keep selling bars into a room nobody is listening to (#1155's
        # class - stock burned unheard).
        if bars and (radio_paused() or not _RADIO.get("on")):
            break
        try:
            bar = gold_pick(exclude_who=last_who, min_rest=GOLD_GAP_REST)
        except Exception:  # noqa: BLE001
            bar = None
        if not bar:
            break
        name = str(bar.get("path") or "").rsplit("/", 1)[-1].split("?")[0]
        if not name:
            break
        clip = {"path": f"/media/{name}", "sig": media_sign(name),
                "seconds": float(bar.get("seconds") or 0)}
        text = str(bar.get("text") or "")
        _door = _dj_speak_floorless if floorless else dj_speak
        try:
            out = await _door("interject", None, line=text,
                              who=str(bar.get("who") or "dj"),
                              checked=True, sting=False, clip=clip)
        except Exception as exc:  # noqa: BLE001
            pipeline_log("air", "a gold bar could not fill the air: "
                         f"{type(exc).__name__}: {exc}"[:160])
            break
        if not out:
            break
        gold_fired(bar)
        went = "bar"
        bars += 1
        last_who = str(bar.get("who") or "")
        laid += max(1.0, float(bar.get("seconds") or 0))
        pipeline_log("air", f"a gold bar fills the air ({why or 'dead air'}"
                            f"; bar {bars} of the run): {text[:70]}")
    if bars > 1:
        pipeline_log("air", f"the bank held the air for {laid:.0f}s across "
                            f"{bars} rhymed bars - {why or 'dead air'}")
    return went
_PRINTS_LOCK = RLock()
PRINTS_MAX = 8000     # #824: a disk bound — the WINDOW is 24h by age
# How long a KEPT line waits before it may air again: an hour the first time,
# three the second, five thereafter — the rotation #752 asks for.
TIER_GATES = (86400.0, 172800.0, 259200.0)  # #824: day-scale rotation
# Past this share of recent candidates blocked, the gate stands down. An
# anti-repeat engine that can silence the station is worse than repetition.
BLOCK_RATE_CAP = 0.35
_BLOCK_RECENT: list[int] = []

# --- The rejection window (#901) -------------------------------------
#
# "Make sure that we have a engine making sure that lines are not being
# repeated, that if they have been ran in the last three to five hours,
# that they are basically rejected."
#
# Every anti-repeat clock already in this file answers a different
# question: the phrase cooldown counts runs of WORDS in minutes,
# TIER_GATES counts days, and rerun_check's word-for-word leg had no
# clock at all on a full sentence. None of them was the band he named
# and none of them was a number anybody could point at. This is that
# number, in one place, in hours.
#
# It is a FLOOR, never a ceiling. A road that already refuses a repeat
# for longer keeps doing exactly that — rerun_check still bars a whole
# sentence word for word for as long as the ledger remembers it, which
# is stricter than five hours and was never the problem. What the floor
# buys is the roads that had NO clock: dj_speak, the sting liners, the
# exhausted-document fallback and the frozen larder round. Measured,
# that is 62% of everything the station says.
REPEAT_WINDOW_MIN_HOURS = 3.0
REPEAT_WINDOW_MAX_HOURS = 5.0
REPEAT_WINDOW_HOURS = 4.0          # the middle of the band he named


def repeat_window() -> float:
    """The rejection window in SECONDS, as the operator has it set.

    Clamped into the three-to-five band whenever the engine is on, so a
    stray value in the settings file cannot quietly turn a four-hour
    memory into a four-minute one. 0 is the single value outside the
    band and it means off — the same convention the phrase cooldown
    beneath already uses."""
    try:
        want = float(dj_settings().get("repeat_window_hours",
                                       REPEAT_WINDOW_HOURS))
    except Exception:  # noqa: BLE001
        want = REPEAT_WINDOW_HOURS
    if want <= 0:
        return 0.0
    return max(REPEAT_WINDOW_MIN_HOURS,
               min(REPEAT_WINDOW_MAX_HOURS, want)) * 3600.0


# #1194: how many SEPARATE aired lines must already carry a phrase
# before a new line carrying it is a habit rather than a coincidence.
PHRASE_ACROSS_LINES = int(os.getenv("PINE_PHRASE_ACROSS_LINES", "12"))
PHRASE_RUN_WORDS = 5
# #1194: runs the station is SUPPOSED to repeat. A sign-off and the phone
# opener are the show's furniture, not a habit - measured, "stay with pine
# box fm" had 29 prints and blocking it would be the gate eating the
# station's own name. Tuned against the ledger: at a threshold of 12 with
# these spared, 16% of recent lines would be held for a rewrite, which
# sits well under the 35% BLOCK_RATE_CAP the fuzzy legs share.
PHRASE_BOILERPLATE = ("pine box", "the station", "request line",
                      "line is ringing", "stay with")


def _phrase_is_furniture(run: str) -> bool:
    """#1194: is this run the show's own furniture rather than a habit?"""
    return any(bit in run for bit in PHRASE_BOILERPLATE)
_PHRASE_BOOK: dict[str, Any] = {"at": -1.0, "runs": {}}


def _runs(text: str, span: int = PHRASE_RUN_WORDS) -> set[str]:
    """#1194: the N-word runs of a line, for the phrase leg."""
    words = _bin_key(text).split()
    if len(words) < span:
        return set()
    return {" ".join(words[i:i + span])
            for i in range(len(words) - span + 1)}


def phrase_book(rows: list[dict[str, Any]]) -> dict[str, int]:
    """#1194: how many DIFFERENT aired lines carry each 5-word run.

    Built off the same ledger the fuzzy leg walks and cached against its
    length, because this is asked once per candidate line and the ledger
    runs to thousands of rows. Adverts and station IDs are left out for
    the reason #901 gives - they are meant to come round again."""
    try:
        stamp = float(len(rows))
        if _PHRASE_BOOK["at"] == stamp:
            return _PHRASE_BOOK["runs"]
        book: dict[str, int] = {}
        for row in rows:
            if str(row.get("kind") or "") in ("station_id", "ad"):
                continue
            for run in _runs(str(row.get("key") or "")):
                book[run] = book.get(run, 0) + 1
        _PHRASE_BOOK.update({"at": stamp, "runs": book})
        return book
    except Exception:  # noqa: BLE001
        return dict(_PHRASE_BOOK.get("runs") or {})


def _shingles(text: str) -> set[str]:
    """The 4-word runs of a line. Two lines sharing most of their runs are
    the same line wearing different punctuation."""
    words = _bin_key(text).split()
    if len(words) < 4:
        return {" ".join(words)} if words else set()
    return {" ".join(words[i:i + 4]) for i in range(len(words) - 3)}


_LINE_ROWS: dict[str, Any] = {"at": -1, "rows": []}


def line_prints() -> list[dict[str, Any]]:
    """The ledger, cached against the file's own mtime (#1063).

    It was read and parsed on EVERY call - 1.6MB of JSON - and
    air_repeat_check calls it once per candidate line, so one speakbox
    sweep over a hundred candidates parsed 160MB on the event loop. The
    pulse named it the top blocker: 34 stalls, 95s of deaf loop in ten
    minutes. phrase_prints beneath has had this cache since #901. A
    fresh list each call, as before, so callers may append and write."""
    try:
        stamp = LINE_PRINTS_PATH.stat().st_mtime_ns
    except OSError:
        stamp = 0
    if stamp and _LINE_ROWS["at"] == stamp:
        return list(_LINE_ROWS["rows"])
    try:
        rows = json.loads(LINE_PRINTS_PATH.read_text())
        rows = [r for r in rows if isinstance(r, dict)]
    except Exception:
        rows = []
    _LINE_ROWS.update({"at": stamp, "rows": rows})
    return list(rows)


def _prints_write(rows: list[dict[str, Any]]) -> None:
    try:
        LINE_PRINTS_PATH.parent.mkdir(parents=True, exist_ok=True)
        tmp = LINE_PRINTS_PATH.with_suffix(".tmp")
        _now = time.time()
        _kept = [r for r in rows
                 if _now - float(r.get("last") or r.get("at") or 0)
                 < (172800 if r.get("gold") else 86400)]        # gold lives twice as long
        # #901: PRINTS_MAX trims from the FRONT, so on a busy night the
        # disk bound could retire a line that is still inside the
        # rejection window — the one thing this ledger exists to
        # remember. Rows still inside the window are held back from the
        # cull and the older rows take the cut instead. Bounded at twice
        # the cap so a runaway night still cannot grow the file without
        # limit. Measured churn is ~132 lines/hour, so the window costs
        # about 660 rows of the 8000; this only matters on a bad day.
        _win = repeat_window()
        if _win and len(_kept) > PRINTS_MAX:
            _live: list[dict[str, Any]] = []
            _old: list[dict[str, Any]] = []
            for _r in _kept:
                _age = _now - float(_r.get("last") or _r.get("at") or 0)
                (_live if _age < _win else _old).append(_r)
            _room = max(0, PRINTS_MAX - len(_live))
            _kept = _old[-_room:] + _live
        _out = _kept[-(PRINTS_MAX * 2):]
        tmp.write_text(json.dumps(_out))
        tmp.replace(LINE_PRINTS_PATH)
        try:                                                        # #1063
            _LINE_ROWS.update({"at": LINE_PRINTS_PATH.stat().st_mtime_ns,
                               "rows": list(_out)})
        except OSError:
            pass
    except OSError:
        pass


def print_remember(text: str, who: str = "", kind: str = "") -> None:
    """Write down that this line went out. Upserted on the key, so the
    turn-by-turn path and the coalesced path cannot double-count it."""
    key = _bin_key(text)
    if len(key) < 12:
        return                        # "yeah", "okay" — a noise, not a line
    with _PRINTS_LOCK:
        rows = line_prints()
        now = int(time.time())
        for at, row in enumerate(rows):
            if row.get("key") == key:
                row["said"] = int(row.get("said") or 0) + 1
                row["last"] = now
                # #no-repeats: and it moves to the END. _prints_write keeps the last
                # PRINTS_MAX rows BY POSITION, so an upsert that left the row
                # where it was first appended let a line said seven times over
                # an hour age off the front of the ledger while it was still
                # actively recurring — after which it read as brand new.
                rows.append(rows.pop(at))
                _prints_write(rows)
                return
        try:
            _gold = bool(rap_rhyme_evidence(text).get("ok"))
        except Exception:  # noqa: BLE001
            _gold = False
        rows.append({"key": key, "who": who, "kind": kind, "gold": _gold,
                     "first": now, "last": now, "said": 1, "blocked": 0,
                     # #no-repeats: 60 was a SORTED prefix, so the kept 60 were an
                     # arbitrary alphabetical slice and a long line compared
                     # against a clipped version of itself.
                     "shingles": sorted(_shingles(text))[:400]})
        _prints_write(rows)


def print_penalise(key: str) -> None:
    """The PENALTY #752 asks for: a line that keeps trying to come back
    carries a count, and the bank retires whatever keeps colliding."""
    if not key:
        return
    with _PRINTS_LOCK:
        rows = line_prints()
        for row in rows:
            if row.get("key") == key:
                row["blocked"] = int(row.get("blocked") or 0) + 1
                _prints_write(rows)
                return


def air_remember(text: str, who: str = "", kind: str = "") -> None:
    # This door updates the editorial/repetition ledgers only.  It does NOT
    # prove playout: browser publication and completed synthesis both reach
    # here in several legacy paths.  The talk clock is deliberately advanced
    # only by a verified box result or an audible page `playing` ACK.
    # #1157: ...and for the same reason, the storyline's BEATS LEDGER.
    # What actually aired under each act is what the running account
    # is written from and what lets the paper and the screenplay cover
    # the story. A dict read and a length test - no disk here (#1142).
    try:
        plotline_beat_note(text, who, kind)
    except Exception:  # noqa: BLE001
        pass
    """ONE door for "this went out on air" (#901).

    Three ledgers back the anti-repeat engine — the line prints the GATE
    reads, the said-lines ring the PROMPTS read, and the phrase cooldown
    — and until now which of them a line landed in depended entirely on
    which road it took. The coalesced round wrote all three. The
    turn-by-turn road wrote two. dj_speak wrote one, and dj_speak is
    every advert, station ID, request line, memo, reply, sting liner and
    gallery line the station says.

    Measured before this existed: 64% of aired lines were absent from
    line_prints.json, so the gate was reading a third of the show and
    calling the other two thirds brand new. It blocked five lines in
    twenty-four hours.

    Deliberately NOT symmetric across the three:

      * the line prints take EVERYTHING, because that is the ledger the
        window is measured against and a line nobody wrote down is a
        line that can come back forever;
      * said_lines takes the CAST, because it feeds "you already said
        this" into the prompts and a jingle is not the pair repeating
        themselves;
      * the phrase cooldown takes only the pair's own conversational
        turns, because a station ID and an advert are MEANT to reuse
        their wording and poisoning the cooldown with them would hold
        back ordinary talk. It is also the most expensive of the three
        to write, and this door roughly triples how often it is called.

    Defensive throughout: remembering is bookkeeping, and bookkeeping may
    never be the reason a line does not go out."""
    try:
        body = " ".join(str(text or "").split())
        if len(body) < 12:
            return                      # "yeah", "okay" — noise, not a line
        coord_air_note(body, who, kind)
        print_remember(body, who, kind)
        if who in ("dj", "cohost", "third", "caller", "caller2", "host"):
            said_remember(body)
        if who in ("dj", "cohost", "third") \
                and kind not in ("station_id", "ad", "emergency_host", "response_audition"):
            phrase_remember(body, who)
    except Exception:  # noqa: BLE001
        pass


def _repeat_flow_verdict(text: str, who: str, kind: str,
                         verdict: dict[str, Any], gate: str,
                         check: str = "checked") -> dict[str, Any]:
    """Journal the actual gate decision without changing it or risking playout."""
    verdict = _line_repeat_acceptance(text, who, verdict)
    try:
        station_flow_event(
            "repeat", "error" if check == "error" else
            "held" if verdict.get("block") else "ok",
            "Repetition gate held a candidate" if verdict.get("block") else
            "Repetition check unavailable; candidate allowed" if check == "error" else
            "Repetition gate allowed a candidate",
            details={"gate": gate, "check": check, "who": who, "kind": kind,
                     "candidate": str(text or ""), "verdict": dict(verdict),
                     "history": "broadcast-history ledger"})
    except Exception:  # noqa: BLE001
        pass
    return verdict


def air_repeat_check(text: str, who: str = "",
                     kind: str = "") -> dict[str, Any]:
    """Has this line been on air inside the rejection window? (#901)

    The word-for-word leg of rerun_check with the named clock on it, on
    its own, for the roads that never had a gate at all. It answers only
    the question the operator actually asked — "has this been ran in the
    last three to five hours" — and deliberately does NOT run the fuzzy
    Jaccard leg. The roads that call this say single lines the station
    has to keep saying, where a near-miss verdict costs a whole segment
    and an exact verdict costs nothing.

    Never raises. On any fault it answers "not a repeat", because an
    engine that cannot answer must never be the reason a line is
    silenced."""
    verdict: dict[str, Any] = {"block": False, "why": "", "key": "",
                               "age": 0.0}
    try:
        window = repeat_window()
        if not window:
            return _repeat_flow_verdict(text, who, kind, verdict, "exact", "disabled")
        key = _bin_key(text)
        verdict["key"] = key
        # The same floor rerun_check uses: short enough and it is a
        # noise, not a line, and barring it is how a gate eats the show.
        if len(key) < 12 or len(key.split()) < 3:
            return _repeat_flow_verdict(text, who, kind, verdict, "exact", "short utterance")
        now = time.time()
        for row in line_prints():
            if row.get("key") != key:
                continue
            age = now - float(row.get("last") or row.get("at") or 0)
            # a gold bar may come round twice as often
            if age >= (window / 2.0 if row.get("gold") else window):
                return _repeat_flow_verdict(text, who, kind, verdict, "exact", "outside window")
            verdict.update({"block": True, "age": age,
                            "why": f"word for word {int(age / 60)} min ago"})
            return _repeat_flow_verdict(text, who, kind, verdict, "exact")
    except Exception:  # noqa: BLE001
        return _repeat_flow_verdict(text, who, kind,
                                    {"block": False, "why": "", "key": "", "age": 0.0},
                                    "exact", "error")
    return _repeat_flow_verdict(text, who, kind, verdict, "exact")


def _block_rate() -> float:
    if len(_BLOCK_RECENT) < 12:
        return 0.0
    return sum(_BLOCK_RECENT) / float(len(_BLOCK_RECENT))


def rerun_note(blocked: bool) -> None:
    _BLOCK_RECENT.append(1 if blocked else 0)
    del _BLOCK_RECENT[:-40]


def rerun_check(text: str, who: str = "", kind: str = "",
                allow_repeat: bool = False) -> dict[str, Any]:
    """Has this been said before? Two legs, cheapest first.

    An exact key, then a Jaccard overlap of 4-word runs — which catches the
    same thought re-punctuated, the thing the old substring test missed in
    both directions. Deliberately NOT applied to a station ID, an ad read, a
    direct reply, or a deliberate replay off the bank: those are supposed to
    repeat, and blocking them is how an anti-repeat engine takes a station
    off the air.

    Bounded by a rolling block rate: if the gate is eating more than a third
    of recent candidates it stands down until the rate falls. Repetition is
    a bad show; silence is no show."""
    verdict = {"block": False, "why": "", "key": _bin_key(text)}
    # #805: "call" joined the fast-exempt list for the CALLER'S OWN seats —
    # the fuzzy Jaccard leg was eating regulars' near-identical call turns
    # ("Hello — this is Big Ron" is near-identical EVERY call, by design),
    # which is how a rung phone aired one turn and died. Host seats keep
    # the exact word-for-word leg via the caller check in speak_turns.
    if allow_repeat or kind in ("station_id", "ad", "reply", "call"):
        return _repeat_flow_verdict(text, who, kind, verdict, "exact and fuzzy", "deliberate repeat exemption")
    key = verdict["key"]
    # #no-repeats: the old floor was 24 characters, and a catchphrase is precisely a
    # line shorter than that — "holy lord son" went out SIXTEEN times with
    # blocked=0 because the gate never looked at it once. Short lines are
    # checked now; what saves them from being barred forever is the clock.
    if len(key) < 12 or len(key.split()) < 3:
        return _repeat_flow_verdict(text, who, kind, verdict, "exact and fuzzy", "short utterance")
    rows = line_prints()
    now = time.time()
    # A catchphrase MAY come back — once the hour the operator asked for has
    # gone by. Only the short ones get that grace; a whole sentence repeated
    # word for word is a rerun at any distance.
    window = (max(float(phrase_setup()["station"] or 3600), 86400.0)
              if len(key) < 24 else 0.0)   # #824: 24h, as demanded
    # #no-repeats: the exact leg runs UNCONDITIONALLY. It used to sit behind the
    # breaker below — an anti-repeat engine that switches itself off exactly
    # when repetition is worst, which is the one thing it must never do.
    for row in rows:
        if row.get("key") == key:
            if window and now - float(row.get("last") or 0) >= window:
                return _repeat_flow_verdict(text, who, kind, verdict, "exact and fuzzy", "outside window")
            # a gold bar (rhymed) is the gold standard: it may come round
            # again after half the rejection window, at any length.
            if row.get("gold") and now - float(row.get("last") or 0) >= repeat_window() / 2.0:
                return _repeat_flow_verdict(text, who, kind, verdict, "exact and fuzzy", "gold bar outside its window")
            verdict.update({"block": True,
                            "why": ("said word for word inside the hour"
                                    if window else
                                    "said before, word for word")})
            return _repeat_flow_verdict(text, who, kind, verdict, "exact and fuzzy", "exact match")
    if _block_rate() > BLOCK_RATE_CAP:
        return _repeat_flow_verdict(text, who, kind, verdict, "exact and fuzzy", "fuzzy breaker open")
    mine = _shingles(text)
    if len(mine) >= 3:
        for row in rows:
            # #901: an advert read and a station ID are MEANT to come
            # round again, and since air_remember started writing every
            # road down the ledger holds them too. They are legitimate
            # history for the word-for-word leg above — that is exactly
            # how the 32-times-aired hand-off finally gets caught — and
            # they are poison for THIS one: a jingle shares four-word
            # runs with any line that mentions the sponsor or the
            # station, and blocking those is the gate eating the show.
            if str(row.get("kind") or "") in ("station_id", "ad"):
                continue
            theirs = set(row.get("shingles") or [])
            if not theirs:
                continue
            overlap = len(mine & theirs)
            if not overlap:
                continue
            union = len(mine | theirs)
            if union and overlap / union >= 0.62:
                verdict.update({"block": True,
                                "why": "near-identical to a line already said",
                                "hit": str(row.get("key") or "")})
                return _repeat_flow_verdict(text, who, kind, verdict, "exact and fuzzy", "Jaccard overlap")
            # #no-repeats: CONTAINMENT as well as symmetry. Every row written before
            # today holds a CHUNK of a turn rather than the turn, so a whole
            # turn can contain an aired fragment entire and still score barely
            # half on a symmetric Jaccard. A line that contains a line already
            # said is a line already said.
            small = min(len(mine), len(theirs))
            if small >= 6 and overlap / small >= 0.85:
                verdict.update({"block": True,
                                "why": "contains a line already said, whole",
                                "hit": str(row.get("key") or "")})
                return _repeat_flow_verdict(text, who, kind, verdict, "exact and fuzzy", "phrase containment")
    # #1194: THE PHRASE LEG. Both legs above compare WHOLE LINES, so a run
    # of words the station says over and over inside lines that are each
    # genuinely different scores far below either bar and goes straight
    # through. Measured over six hours: "what you actually wanted us to"
    # in fourteen separate lines, "is the part i cannot shake" in
    # thirteen, and the pencil trick carried by 9 of the 68 banked banter
    # rounds. Asking whether a PHRASE is a habit is a different question
    # from whether a LINE is a repeat, and nothing was asking it.
    try:
        _runs_mine = _runs(text)
        if _runs_mine:
            _book = phrase_book(rows)
            _worn = [(r, _book.get(r, 0)) for r in _runs_mine
                     if _book.get(r, 0) >= PHRASE_ACROSS_LINES
                     and not _phrase_is_furniture(r)]
            if _worn:
                _worst, _count = max(_worn, key=lambda p: p[1])
                verdict.update({
                    "block": True,
                    "why": ("a phrase the station has already said in %d "
                            "separate lines: “%s”" % (_count, _worst)),
                    "hit": _worst})
                return _repeat_flow_verdict(text, who, kind, verdict,
                                            "exact and fuzzy", "worn phrase")
    except Exception:  # noqa: BLE001
        pass                            # a gate that cannot answer never blocks
    return _repeat_flow_verdict(text, who, kind, verdict, "exact and fuzzy")


# --- The hour-long phrase cooldown (#no-repeats) -----------------------------------
#
# "Make sure that the system detects words and phrases said and ensures they
# are not repeated for an hour. I want the rhetoric unique and never
# repeating."
#
# Measured on the live station before this existed: across 166 spoken rows one
# line had aired SEVEN times byte-identical and a three-word catchphrase
# SIXTEEN times — both with blocked=0, the gate above never contesting either,
# and the breaker CLOSED (block_rate 0.05) the whole time. Three reasons, all
# fixed:
#
#   1. the ledger wrote CHUNKS — post-chunking, post-disfluency — while the
#      gate tested whole TURNS, so any turn longer than say_max_chars() could
#      never match its own row. Fixed at both write sites in speak_turns.
#   2. nothing under 24 characters was checked at all, which is the exact
#      shape of a catchphrase. Now checked, against a clock.
#   3. every anti-repeat window in the file was counted in LINES. The ledger
#      carried timestamps and nothing ever read them, so "for an hour" was
#      not implemented anywhere in this station. This is that hour.
#
# The ledger below is normalised n-grams, each carrying the moment it last
# aired and the moment each SPEAKER last used it — the per-character cooldown
# — trimmed by AGE and never by count, so the window is a real hour rather
# than however many lines happen to fit in a file. And on a hit a line is not
# dropped: dropping is what the old gate paid for repetition with, and it pays
# in dead air. It is rewritten, and failing that swapped for material off the
# speakbox shelf.
PHRASE_PRINTS_PATH = data_path("phrase_prints.json")
# #901, measured: the ledger writes ~4850 grams an hour on this
# station and stood at 19321 of 20000 — so the COUNT cap was binding at
# about 4.1 hours and silently truncating any window past it, whatever
# the clock below said. 26000 carries the top of the three-to-five band
# with a little room. It is still a disk bound and not a window; the
# clock in _phrase_write is the window.
PHRASE_PRINTS_MAX = 26000          # a disk bound, not a window
_PHRASE_PRESSURE: list[int] = []
_PHRASE_ROWS: dict[str, Any] = {"at": -1, "rows": {}}
# FUNCTION words only — the grammar of English, which every sentence is made
# of and nobody is "leaning on". A run needs two words from outside this set
# before it counts as somebody's turn of phrase.
#
# Kept deliberately tight. A first cut also held thing/know/way/really and
# demanded three content words, and it threw away "the only thing keeping me"
# — which is a run out of the very line the operator caught airing seven
# times. A filter that cannot see the reported bug is the wrong filter.
PHRASE_BORING = {
    "a", "an", "the", "and", "or", "but", "so", "to", "of", "in", "on", "at",
    "by", "for", "from", "with", "into", "over", "about", "as", "if", "than",
    "then", "that", "this", "these", "those", "it", "its", "i", "me", "my",
    "we", "us", "our", "you", "your", "he", "him", "his", "she", "her",
    "they", "them", "their", "is", "are", "was", "were", "be", "been",
    "being", "am", "do", "does", "did", "don", "have", "has", "had", "will",
    "would", "shall", "should", "can", "could", "may", "might", "must",
    "not", "no", "s", "t", "re", "ve", "ll", "m", "up", "out", "what",
    "when", "who", "how", "why", "which", "all", "any", "some", "more",
    "most", "very", "just", "like", "now", "well", "yeah", "ok", "okay",
    "too", "also", "again", "there", "here",
}


def phrase_setup() -> dict[str, Any]:
    """The cooldown as the operator set it — two clocks and a run length."""
    dj = dj_settings()
    return {
        "n": max(3, min(8, int(dj.get("phrase_ngram") or 5))),
        "station": max(0, min(1440, int(
            dj.get("phrase_cooldown_minutes") or 0))) * 60,
        "self": max(0, min(2880, int(
            dj.get("phrase_cooldown_self_minutes") or 0))) * 60,
        "retries": max(0, min(3, int(dj.get("phrase_retries") or 0))),
        "swap": bool(dj.get("phrase_swap_from_speakbox", True)),
    }


def phrase_grams(text: str, n: int = 5) -> list[str]:
    """Every run of n words in a line, minus the ones that are only grammar.

    Normalised through _bin_key, so punctuation and capitals drifting between
    one telling and the next cannot hide a rerun."""
    words = _bin_key(text).split()
    if len(words) < n:
        return []
    out: list[str] = []
    for at in range(len(words) - n + 1):
        run = words[at:at + n]
        if sum(1 for w in run if w not in PHRASE_BORING) < 2:
            continue
        out.append(" ".join(run))
    return out


def phrase_prints() -> dict[str, dict[str, Any]]:
    """The ledger, cached against the file's own mtime — it is read once per
    candidate line and runs to megabytes on a long night."""
    try:
        stamp = PHRASE_PRINTS_PATH.stat().st_mtime_ns
    except OSError:
        stamp = 0
    if stamp and _PHRASE_ROWS["at"] == stamp:
        return _PHRASE_ROWS["rows"]
    try:
        rows = json.loads(PHRASE_PRINTS_PATH.read_text())
        rows = rows if isinstance(rows, dict) else {}
    except Exception:
        rows = {}
    _PHRASE_ROWS.update({"at": stamp, "rows": rows})
    return rows


def _phrase_write(rows: dict[str, dict[str, Any]], horizon: float) -> None:
    """Trimmed by AGE, which is the whole point of the ledger. The count cap
    beneath it is a disk bound and it drops the OLDEST — never the busiest,
    which is the mistake the line ledger's positional trim makes."""
    now = time.time()
    keep = {k: v for k, v in rows.items()
            if now - float(v.get("at") or 0) <= horizon}
    if len(keep) > PHRASE_PRINTS_MAX:
        keep = dict(sorted(keep.items(),
                           key=lambda kv: -float(kv[1].get("at") or 0)
                           )[:PHRASE_PRINTS_MAX])
    try:
        PHRASE_PRINTS_PATH.parent.mkdir(parents=True, exist_ok=True)
        tmp = PHRASE_PRINTS_PATH.with_suffix(".tmp")
        tmp.write_text(json.dumps(keep))
        tmp.replace(PHRASE_PRINTS_PATH)
    except OSError:
        pass                            # a forgetful show still goes out


def phrase_remember(text: str, who: str = "") -> None:
    """Only what actually went out on air lands here."""
    cfg = phrase_setup()
    grams = phrase_grams(text, cfg["n"])
    if not grams:
        return
    now = int(time.time())
    # #901: and the line window, so raising the rejection window cannot
    # leave the phrase ledger forgetting underneath it.
    horizon = max(cfg["station"], cfg["self"], repeat_window(), 3600) * 2
    with _PRINTS_LOCK:
        rows = phrase_prints()
        for gram in grams:
            row = rows.get(gram)
            row = row if isinstance(row, dict) else {"at": 0, "n": 0, "by": {}}
            row["at"] = now
            row["n"] = int(row.get("n") or 0) + 1
            if who:
                by = row.get("by")
                row["by"] = by if isinstance(by, dict) else {}
                row["by"][who] = now
            rows[gram] = row
        _phrase_write(rows, horizon)


def _line_repeat_acceptance(text: str, who: str,
                            verdict: dict[str, Any]) -> dict[str, Any]:
    if verdict.get("block"):
        verdict["machine_block"] = True
        if line_review_permits("repetition", text,
                               reasons=[verdict.get("why") or "repetition"],
                               context={"who": str(who or "")}):
            verdict.update(block=False, operator_accepted=True)
    return verdict


def phrase_check(text: str, who: str = "",
                 also: set[str] | None = None) -> dict[str, Any]:
    """Has any run of these words been on air inside the window?

    `also` is the runs said EARLIER IN THIS ROUND, which are not in the ledger
    yet — a round is written whole and only recorded once its audio is built,
    so without this the two hosts can echo each other inside one exchange and
    the gate cannot see it. Caught live within a minute of switching this on:
    the co-host said "my career it has happened many many times since" and the
    host said it back fourteen seconds later, both aired, both invisible.

    Deliberately NOT bounded by a block rate. The gate above stands down when
    it fires too often; this one answers pressure with fresh material instead
    — see phrase_pressure. An engine that switches off under load is off
    exactly when it is needed."""
    verdict: dict[str, Any] = {"block": False, "phrase": "", "age": 0.0,
                               "why": ""}
    cfg = phrase_setup()
    if not (cfg["station"] or cfg["self"]):
        return verdict                  # both clocks at zero — engine off
    grams = phrase_grams(text, cfg["n"])
    if not grams:
        return verdict
    rows = phrase_prints()
    now = time.time()
    for gram in grams:
        if also and gram in also:
            verdict.update({"block": True, "phrase": gram, "age": 0.0,
                            "why": f'"{gram}" was already said earlier in '
                                   "this very round"})
            return _line_repeat_acceptance(text, who, verdict)
        row = rows.get(gram)
        if not isinstance(row, dict):
            continue
        age = now - float(row.get("at") or 0)
        if cfg["station"] and age < cfg["station"]:
            verdict.update({"block": True, "phrase": gram, "age": age,
                            "why": f'"{gram}" went out '
                                   f"{int(age / 60)} min ago"})
            return _line_repeat_acceptance(text, who, verdict)
        mine = float((row.get("by") or {}).get(who) or 0) if who else 0.0
        if cfg["self"] and mine and now - mine < cfg["self"]:
            verdict.update({"block": True, "phrase": gram, "age": now - mine,
                            "why": f'{who} used "{gram}" '
                                   f"{int((now - mine) / 60)} min ago"})
            return _line_repeat_acceptance(text, who, verdict)
    return verdict


def phrase_note(blocked: bool) -> None:
    _PHRASE_PRESSURE.append(1 if blocked else 0)
    del _PHRASE_PRESSURE[:-40]


def phrase_pressure() -> float:
    """How hard the cooldown is having to work.

    Never a reason to stand the gate down. It BUYS MATERIAL — it lifts the
    speakbox draw, so a station repeating itself gets FRESHER rather than
    thinner, which is the trade the old breaker had backwards."""
    if len(_PHRASE_PRESSURE) < 8:
        return 0.0
    return sum(_PHRASE_PRESSURE) / float(len(_PHRASE_PRESSURE))


def phrase_hot(most: int = 16) -> list[str]:
    """The runs still inside the cooldown, busiest first — so the DO-NOT-USE
    list in the prompt and the gate at air time read one truth."""
    cfg = phrase_setup()
    window = max(cfg["station"], cfg["self"])
    if not window:
        return []
    now = time.time()
    live = [(k, v) for k, v in phrase_prints().items()
            if isinstance(v, dict) and int(v.get("n") or 0) >= 2
            and now - float(v.get("at") or 0) < window]
    live.sort(key=lambda kv: (-int(kv[1].get("n") or 0),
                              -float(kv[1].get("at") or 0)))
    return [k for k, _ in live[:max(1, most)]]


# Material waiting in the wings. A line held back by the cooldown is SWAPPED
# for one of these rather than dropped — "prompt them to say more from the
# speakerbox database" (#no-repeats) — and because the shelf is stocked off-air the
# swap itself never waits on a mine or a model call.
_FRESH_POOL: list[dict[str, str]] = []
_FRESH_FILLING: list[bool] = [False]


async def fresh_pool_fill(want: int = 8) -> None:
    if _FRESH_FILLING[0] or len(_FRESH_POOL) >= want:
        return
    _FRESH_FILLING[0] = True
    try:
        quote = await speakbox_quote(most=4, cap=300)
        for line in (quote.get("lines") or []):
            if len(str(line or "")) < 30:
                continue
            if phrase_check(str(line)).get("block"):
                continue
            _FRESH_POOL.append({"text": str(line),
                                "file": str(quote.get("file") or ""),
                                "mind": str(quote.get("mind") or "")})
        del _FRESH_POOL[:-24]
    except Exception:
        pass                            # the shelf is a luxury, not the show
    finally:
        _FRESH_FILLING[0] = False


def fresh_pool_top(want: int = 8) -> None:
    """Ask for a refill without waiting on one."""
    if len(_FRESH_POOL) < want and not _FRESH_FILLING[0]:
        try:
            asyncio.get_running_loop().create_task(fresh_pool_fill(want))
        except RuntimeError:
            pass                        # no loop — a test, or the CLI


# --- THE SEAT WATCH (#1034) -------------------------------------------
# The host and the co-host are meant to be having a CONVERSATION. The
# talk watchdog above measures one clock for the whole booth, so a swath
# where one seat carried the show alone - the other's lines dropped by a
# gate, a cover here and there, a call one of them ran on their own -
# read as "somebody is talking" and passed. Nothing ever noticed that
# only one of them was.
#
# This watches the two seats separately, off the booth ring (the only
# per-line record with who + time in it; the durable air log, when
# merged, is the better source and seat_rows() is the one place to
# swap it in). When one seat has aired seat_quiet_lines lines, or
# seat_quiet_minutes minutes, since the OTHER seat last spoke, the
# silent one says where they are going - in their own voice, by hand,
# so nothing gates it - and the round writer is told the chair is
# empty. They come back after seat_away_minutes, or sooner when the
# next round needs both of them, and say so before it starts.
#
# The rules the rest of the file keeps while a seat is away: the round
# writer's format clause says there are no lines for that seat,
# banter_turns never flips a repeated marker INTO the empty chair and
# re-seats stray lines out of it, the one-sided re-split in
# _speak_turns_floorless stands down, the larder is not shopped (a
# banked two-hander would bring the voice straight back), the live
# record intro goes to whoever is present, and cover_speaker never
# picks the empty chair.
SEAT_AWAY_PATH = data_path("seat_away.json")
SEAT_SEATS = ("dj", "cohost")
# Fifteen minutes and a seat is back whatever the clocks say - a
# restart must never leave a chair empty for the night.
SEAT_AWAY_HARD_LIMIT = 900.0
# After a return the same seat is not sent out again for a while; the
# detector would otherwise fire on the very swath that preceded it.
SEAT_REST_AFTER_BACK = 600.0
# The swath must be LIVE: the present seat's newest line inside this
# window, or it is everybody-quiet (the talk watchdog's job, not ours).
SEAT_SWATH_STALE = 600.0
# Rows that are not the seat speaking in a conversation. Single-line
# roads (an intro over a record, a station id, an ad read) prove the
# seat is present but not that a conversation is running one-sided;
# markers and operator rows are not speech at all.
SEAT_NOT_SPEECH = frozenset({
    "chat", "marker", "sfx", "hangup", "drop", "analysis",
    "image_analysis", "upstairs", "played", "callin", "request_note",
})
SEAT_SOLO_KINDS = frozenset({
    "intro", "request", "outro", "open", "station_id", "ad", "media",
    "track_talk", "aside", "news_marker",
})
SEAT_AIRED = frozenset({"box", "stream", "both"})
# Rounds that want both chairs filled: the two-hander by construction,
# the phone (the hosts take the call together), the interview.
SEAT_NEEDS_BOTH = frozenset({"deep", "caller", "call", "guest", "recap",
                             "interview"})

