# #673: the switchboard is enormous and the line a caller comes in on is
# drawn fresh every time. "Line one" every single call made the station feel
# like it had exactly one phone; a number pulled from a switchboard this big
# makes it feel like a place people are queuing to get into.
CALL_LINES = 98837


def call_line_no() -> int:
    """Which line this caller came in on. 1 to 98,837, uniformly."""
    return random.randint(1, CALL_LINES)


def call_line_say(number: int) -> str:
    """How a person would say that number out loud on air."""
    return f"line {number:,}"


# --- How calls END, and the ledger of how they did (#691) -------------------
# Every call already finished on one of a fixed tuple of outcomes, drawn at
# random and dropped into the prompt — a good house style with no door into
# it. You could not add a way for a call to end, weight the ones you liked,
# retire the one that had worn out, or see afterwards which ending a given
# call actually took.
#
# The tuple becomes the SEED of an editable shelf instead. Rules are drawn by
# weight, never the same one twice running, and every termination is written
# down: which rule, for whom, how long the call ran, at what moment. The
# booth shows the hang-up as its own line and the reason is a chip you click
# to open the shelf.
HANGUPS_PATH = data_path("hangup_rules.json")
CALL_LOG_PATH = data_path("call_log.json")
_HANGUP_LOCK = RLock()
# A call is continuity data, not a rolling UI buffer.  Five thousand complete
# calls is years of useful novelty memory at the default rate while remaining a
# small JSON file.  The old 120-row cap forgot a premise in roughly a day.
CALL_LOG_KEPT = max(120, int(os.getenv("CALL_LOG_KEPT", "5000")))
CALL_NOVELTY_LOOKBACK = 240
CALL_NOVELTY_MAX_SIMILARITY = 0.48
CALL_CONTRACT_VERSION = 8

# Function words and the unavoidable furniture of a radio call carry no
# novelty.  Comparing them made every good call resemble every other merely
# because somebody said "you're on the air" and "thanks for calling".
_CALL_NOVELTY_STOP = {
    "a", "about", "after", "again", "all", "am", "an", "and", "are",
    "as", "at", "b", "be", "because", "been", "before", "being", "but",
    "by", "c", "call", "called", "caller", "calling", "can", "did", "do",
    "does", "for", "from", "go", "got", "had", "has", "have", "he",
    "hello", "hey", "host", "hosts", "i", "if", "in", "into", "is", "it",
    "just", "line", "me", "my", "no", "not", "now", "of", "oh", "on",
    "one", "or", "our", "out", "radio", "right", "said", "say", "she",
    "so", "station", "that", "the", "their", "them", "then", "there",
    "they", "this", "to", "us", "was", "we", "were", "what", "when",
    "who", "why", "with", "you", "your", "youre",
}


def call_script_text(script: Any) -> str:
    """A stable, speaker-labelled transcript string from any stored shape."""
    if isinstance(script, list):
        rows: list[str] = []
        for row in script:
            if isinstance(row, dict):
                who = str(row.get("marker") or row.get("who") or "").strip()
                said = str(row.get("text") or "").strip()
            elif isinstance(row, (list, tuple)) and len(row) >= 2:
                who, said = str(row[0]).strip(), str(row[1]).strip()
            else:
                continue
            if said:
                who = {"dj": "A", "host": "A", "cohost": "B",
                       "caller": "C", "third": "D", "caller2": "E"}.get(
                           who.lower(), who)
                rows.append(f"{who}: {said}" if who else said)
        return "\n".join(rows)
    return str(script or "")


# #1142: call_entry_contract re-verifies the fingerprint on every readiness
# sweep, from every polling surface — two regex passes and a sha256 over the
# whole script per caller row, measured (py-spy) grinding the event loop
# while /healthz sat deaf. The text is the entire identity, so the digest is
# memoized on it; the stored-vs-recomputed comparison keeps its meaning.
_CALL_FP_MEMO: dict[int, tuple[str, str]] = {}


def call_fingerprint(script: Any) -> str:
    """Exact-dialogue identity, insensitive to labels and punctuation."""
    text = call_script_text(script)
    hit = _CALL_FP_MEMO.get(hash(text))
    if hit is not None and hit[0] == text:
        return hit[1]
    flat = re.sub(r"(?:^|\s)[ABCDE]\s*:\s*", " ", text, flags=re.I)
    flat = re.sub(r"[^a-z0-9']+", " ", flat.lower())
    flat = " ".join(flat.split())
    made = hashlib.sha256(flat.encode("utf-8")).hexdigest() if flat else ""
    if len(_CALL_FP_MEMO) > 512:
        _CALL_FP_MEMO.clear()
    _CALL_FP_MEMO[hash(text)] = (text, made)
    return made


# #1022: the pulse ledger's top frame - 17 stalls, 31s in one evening,
# from call_flow_report -> call_novelty walking the whole call history
# per regrade. Memoised on the script text (the #1142 _CALL_FP_MEMO
# pattern): the history rows are the same texts every time.
_CALL_TERMS_MEMO: dict[int, tuple[str, list[str]]] = {}


def _call_novelty_terms(script: Any) -> list[str]:
    text = call_script_text(script)
    hit = _CALL_TERMS_MEMO.get(hash(text))
    if hit is not None and hit[0] == text:
        return list(hit[1])
    words = re.findall(r"[a-z0-9']+", text.lower())
    made = [w for w in words if len(w) > 2 and w not in _CALL_NOVELTY_STOP]
    if len(_CALL_TERMS_MEMO) > 512:
        _CALL_TERMS_MEMO.clear()
    _CALL_TERMS_MEMO[hash(text)] = (text, made)
    return list(made)


def _call_caller_text(text: str) -> str:
    """The caller's own turns (C and E) of a labelled transcript, or ""
    when the transcript carries no labels."""
    try:
        rows = [ln for ln in str(text or "").splitlines()
                if re.match(r"\s*[CE]\s*:", ln, flags=re.I)]
        return "\n".join(rows)
    except Exception:  # noqa: BLE001
        return ""


def _call_novelty_grams(script: Any, width: int = 3) -> set[str]:
    words = _call_novelty_terms(script)
    if not words:
        return set()
    if len(words) < width:
        return {" ".join(words)}
    return {" ".join(words[i:i + width])
            for i in range(len(words) - width + 1)}


def _call_history_scripts(include_shelf: bool = True,
                          exclude_entry: Any = None
                          ) -> list[dict[str, Any]]:
    """Completed calls plus calls already committed to the recording queue."""
    out: list[dict[str, Any]] = []
    for row in call_log_read()[-CALL_NOVELTY_LOOKBACK:]:
        text = call_script_text(row.get("transcript") or row.get("script"))
        if text:
            out.append({"id": str(row.get("id") or ""),
                        "name": str(row.get("name") or ""),
                        "topic": str(row.get("topic") or ""),
                        "source": str(row.get("source") or ""),
                        "speakerbox_text": str(
                            row.get("speakerbox_text") or ""),
                        "speakerbox_extra": [
                            str(t) for t in (row.get("speakerbox_extra")
                                             or []) if t],            # #1033
                        "plot": str((row.get("plot") or {}).get("id")
                                    or ""),                     # #1157
                        "script": text})
    if include_shelf:
        try:
            for kind, rows in list(_SHELF.items()):
                for row in rows or []:
                    entry = (row or {}).get("entry") or {}
                    if exclude_entry is not None and entry is exclude_entry:
                        continue
                    if not entry.get("caller_name"):
                        continue
                    text = call_script_text(entry.get("script"))
                    if text:
                        meta = entry.get("call") or {}
                        out.append({"id": str(meta.get("id") or "queued"),
                                    "name": str(entry.get("caller_name") or ""),
                                    "topic": str(meta.get("topic") or ""),
                                    "source": str(meta.get("source") or ""),
                                    "speakerbox_text": str(
                                        meta.get("speakerbox_text") or ""),
                                    "speakerbox_extra": [
                                        str(t) for t in
                                        (meta.get("speakerbox_extra") or [])
                                        if t],                        # #1033
                                    "plot": str(
                                        (meta.get("plot") or {}).get(
                                            "id") or ""),       # #1157
                                    "script": text})
        except Exception:  # noqa: BLE001
            pass
    return out[-CALL_NOVELTY_LOOKBACK:]


def call_novelty(script: Any, include_shelf: bool = True,
                 exclude_entry: Any = None,
                 exclude_ids: set[str] | None = None,
                 exclude_plot: str = "") -> dict[str, Any]:
    """Exact and structural comparison against calls the station remembers.

    #1039: `exclude_ids` are the calls a STORY may legitimately resemble
    - its own earlier parts. A sequel that names the same people and the
    same trouble was refused here as "too similar to a stored call"; it
    is compared against every call OTHER than its own now."""
    text = call_script_text(script)
    fingerprint = call_fingerprint(text)
    # 2026-09-08 (evening): the structural comparison reads the CALLER's
    # turns only. The census found every "too similar to a stored call"
    # (26 rows, 69 occurrences) matching the queued call on the same
    # scheduled theme, whose sentence sits verbatim inside the host's own
    # templated question - the hosts' formula lines were the similarity.
    grams = _call_novelty_grams(_call_caller_text(text) or text)
    best = 0.0
    matched: dict[str, Any] = {}
    exact = False
    _skip = {str(x) for x in (exclude_ids or ()) if x}
    _skip_plot = str(exclude_plot or "")
    for row in _call_history_scripts(include_shelf, exclude_entry):
        if _skip and str(row.get("id") or "") in _skip:
            continue                        # #1039: the story's own parts
        if _skip_plot and str(row.get("plot") or "") == _skip_plot:
            continue                        # #1157: the same storyline
        other = str(row.get("script") or "")
        other_fp = call_fingerprint(other)
        if fingerprint and other_fp == fingerprint:
            exact, best, matched = True, 1.0, row
            break
        theirs = _call_novelty_grams(_call_caller_text(other) or other)
        if not grams or not theirs:
            continue
        score = len(grams & theirs) / max(1, len(grams | theirs))
        if score > best:
            best, matched = score, row
    return {
        "ok": bool(fingerprint and not exact
                   and best < CALL_NOVELTY_MAX_SIMILARITY),
        "fingerprint": fingerprint,
        "exact": exact,
        "similarity": round(best, 3),
        "limit": CALL_NOVELTY_MAX_SIMILARITY,
        "matched_id": str(matched.get("id") or ""),
        "matched_name": str(matched.get("name") or ""),
        "matched_topic": str(matched.get("topic") or "")[:240],
    }


def _call_topic_terms(value: Any) -> set[str]:
    return {w for w in _call_novelty_terms(value)
            if w not in _SPEAKBOX_TOPIC_STOP}


def call_topic_report(script: Any, topic: str = "") -> dict[str, Any]:
    """Prove that the database topic is carried by both sides of the call."""
    terms = _call_topic_terms(topic)
    if not terms:
        return {"ok": True, "terms": [], "shared": [], "turns": [],
                "host": True, "caller": True}
    turns = banter_turns(call_script_text(script))
    hit_rows: list[int] = []
    shared: set[str] = set()
    host = False
    caller = False
    for at, (marker, said) in enumerate(turns):
        found = terms & _call_topic_terms(said)
        if not found:
            continue
        hit_rows.append(at)
        shared.update(found)
        host = host or marker in ("A", "B", "D")
        caller = caller or marker in ("C", "E")
    return {
        "ok": bool(len(hit_rows) >= 2 and host and caller),
        "terms": sorted(terms)[:30], "shared": sorted(shared)[:30],
        "turns": hit_rows[:30], "host": host, "caller": caller,
    }


def call_speakerbox_report(script: Any, speakerbox_text: str = "",
                           topic: str = "") -> dict[str, Any]:
    """Prove the caller-to-host Speakerbox handoff, not merely a word hit.

    The previous check searched the entire script.  A host could quote the
    selected source before the caller spoke and the call was certified even
    though the caller never introduced a pivot and nobody developed it.  The
    contract is directional now: a C/E turn must carry distinctive source
    language, then a later A/B/D turn must pick that language up.
    """
    texture = _call_topic_terms(speakerbox_text)
    if not texture:
        return {"ok": True, "required": False, "shared": [],
                "caller": False, "hosts": False, "pivot_turns": []}
    # Prefer a term that is not merely the database subject: that is evidence
    # that the source passage contributed texture, not just that both mention
    # the same theme.  A very short passage may have no such term, in which
    # case an anchored topic term is the honest available proof.
    distinctive = texture - _call_topic_terms(topic)
    wanted = distinctive or texture
    turns = banter_turns(call_script_text(script))
    caller_shared: set[str] = set()
    host_shared: set[str] = set()
    pivot_turns: list[int] = []
    for at, (marker, said) in enumerate(turns):
        if marker not in ("C", "E"):
            continue
        carried = wanted & _call_topic_terms(said)
        if not carried:
            continue
        pivot_turns.append(at)
        caller_shared.update(carried)
        # A later host has to engage with the pivot itself.  Requiring one
        # of its distinctive anchors makes a generic "interesting point"
        # response fail, which is exactly the talk-past behavior at issue.
        for later_marker, later_said in turns[at + 1:]:
            if later_marker in ("A", "B", "D"):
                host_shared.update(carried & _call_topic_terms(later_said))
    shared = caller_shared | host_shared
    return {"ok": bool(caller_shared and host_shared), "required": True,
            "shared": sorted(shared)[:30],
            "caller_shared": sorted(caller_shared)[:30],
            "host_shared": sorted(host_shared)[:30],
            "caller": bool(caller_shared), "hosts": bool(host_shared),
            "pivot_turns": pivot_turns[:20],
            "wanted": sorted(wanted)[:30]}


def call_speakerbox_novelty(speakerbox_text: str = "",
                            include_shelf: bool = True,
                            exclude_entry: Any = None) -> dict[str, Any]:
    """Do not assign the same Speakerbox seed to two calls in one queue."""
    flat = " ".join(str(speakerbox_text or "").lower().split())
    if not flat:
        return {"ok": True, "required": False, "matched_id": "",
                "matched_name": ""}
    for row in _call_history_scripts(include_shelf, exclude_entry):
        # #1033: the semantic seed AND the two fresh chunks a call
        # carried - one chunk, one call.
        for held in ([row.get("speakerbox_text")]
                     + list(row.get("speakerbox_extra") or [])):
            other = " ".join(str(held or "").lower().split())
            if other and other == flat:
                return {"ok": False, "required": True,
                        "matched_id": str(row.get("id") or ""),
                        "matched_name": str(row.get("name") or "")}
    return {"ok": True, "required": True, "matched_id": "",
            "matched_name": ""}


def call_tint_report(plain: Any, tinted: Any,
                     required_names: tuple[str, ...] = ()) -> dict[str, Any]:
    """Reject a stylish tint that changed the call's meaning or structure."""
    before = banter_turns(call_script_text(plain))
    after = banter_turns(call_script_text(tinted))
    faults: list[str] = []
    if not before:
        return {"ok": True, "checked": False, "faults": []}
    if len(before) != len(after):
        faults.append("the tint changed the number of turns")
    if [m for m, _ in before] != [m for m, _ in after]:
        faults.append("the tint changed the speaker order")
    for at, ((marker, source), (_marker, result)) in enumerate(
            zip(before, after)):
        src_terms = _call_topic_terms(source)
        out_terms = _call_topic_terms(result)
        if len(src_terms) >= 3:
            kept = len(src_terms & out_terms) / max(1, len(src_terms))
            # A tint may replace connective language and cadence; it may not
            # replace the content. The old 15% floor let a six-noun line keep
            # one generic noun and invent the rest. A 45% floor then rejected
            # faithful question paraphrases such as noticed→saw and
            # changed→shifted even while their exact concrete object, proper
            # names, numbers and question role survived the hard gates below.
            if kept < 0.35:
                faults.append(f"tint turn {at + 1} lost its subject")
        if (re.search(r"\b(thank|thanks|appreciate|goodbye|goodnight|take care)\b",
                      source.lower())
                and not re.search(
                    r"\b(thank|thanks|appreciate|goodbye|goodnight|take care)\b",
                    result.lower())):
            faults.append(f"tint turn {at + 1} lost the spoken sign-off")
        _facts = crystal_compare_contract(source, result, _TINT_EVAL_STOP, _crystal_vocab(), anchor_floor=0)
        if not _facts["question"]:
            faults.append(f"tint turn {at + 1} turned a question into a statement")
        if _facts["missing_numbers"]:
            faults.append(f"tint turn {at + 1} lost a number")
        if _facts["added_numbers"]:
            faults.append(f"tint turn {at + 1} introduced a different number")
        _source_contract = crystal_source_contract(source)
        _result_tokens = set(crystal_source_contract(result)["tokens"])
        _required_names = {token.casefold() for full in required_names for token in full.split()
                           if token and re.search(rf"\b{re.escape(token)}\b", source, re.I)}
        _inferred_names = {name["normalized"] for name in _source_contract["names"]}
        if _facts["missing_names"] or _required_names - _result_tokens:
            faults.append(f"tint turn {at + 1} lost a name")
        _source_intro = crystal_normalize_text(source).lower()
        _result_intro = crystal_normalize_text(result).lower()
        intro = re.search(r"\b(?:i am|i'm|im|this is|it is|it's|its)\s+([a-z0-9'_-]+)\b", _source_intro)
        if intro and intro.group(1) in (_required_names | _inferred_names):
            _name = re.escape(intro.group(1))
            # 2026-09-08 (the scan): "Tacoma on the line, courthouse bus
            # shelter" and "Salem, I am calling from" are introductions too.
            if not re.search(rf"\b(?:i am|i'm|im|this is|it is|it's|its)\s+{_name}\b"
                             rf"|\b{_name}\b(?:\W+\w+){{0,2}}?\W+(?:here|calling|from|on the line|speaking|checking in)\b",
                             _result_intro):
                faults.append(f"tint turn {at + 1} lost the self-introduction")
        if at:
            prior = " ".join(after[at - 1][1].lower().split())
            current = " ".join(result.lower().split())
            prior_words = prior.split()
            if len(prior_words) >= 5:
                lead = " ".join(prior_words[:5])
                if lead and lead in current:
                    faults.append(f"tint turn {at + 1} copied the prior turn")
    return {"ok": not faults, "checked": True,
            "turns_before": len(before), "turns_after": len(after),
            "faults": faults[:30]}


def call_flow_report(script: Any, caller_name: str = "",
                     caller2_name: str = "",
                     include_shelf: bool = True,
                     topic: str = "", source_script: Any = "",
                     speakerbox_text: str = "",
                     exclude_entry: Any = None,
                     story: dict[str, Any] | None = None,
                     plot: dict[str, Any] | None = None,
                     soft_quality: bool = False) -> dict[str, Any]:
    """Machine-check conversation, theme, tint fidelity and novelty.

    #1039: `story` (the call meta's story dict: id, part, call_ids) makes
    this a SEQUEL. A returning caller the hosts recognise fails two
    legs of the stranger's protocol by design - the host says their name
    before any introduction, and the caller does not introduce
    themselves - so those legs are skipped, and novelty is measured
    against every call but the story's own."""
    _story = dict(story) if isinstance(story, dict) and story.get("id") \
        else {}
    _story_ids = {str(x) for x in (_story.get("call_ids") or []) if x}
    turns = banter_turns(call_script_text(script), caller_name, caller2_name)
    caller_at = [i for i, (m, _t) in enumerate(turns) if m in ("C", "E")]
    host_at = [i for i, (m, _t) in enumerate(turns) if m in ("A", "B", "D")]
    first_caller = caller_at[0] if caller_at else -1
    first_text = turns[first_caller][1] if first_caller >= 0 else ""
    first_name = str(caller_name or "").split()[0].lower() if caller_name else ""
    first_clean = re.sub(r"[^a-z0-9' ]+", " ", first_text.lower())
    first_clean = " ".join(first_clean.split())
    # 2026-09-08 (the scan): "Salem, I am calling from a dimly lit corner",
    # "Howlin' Wolf here" - the name may sit two words before its "calling
    # from", and a trailing apostrophe is not a word boundary.
    _first_name = re.escape(first_name.rstrip("'"))
    introduced = bool(not first_name or re.search(
        rf"\b(?:i am|i'm|im|this is|it is|it's|its)\s+{_first_name}"
        rf"|\b{_first_name}\b(?:\W+\w+){{0,2}}?\W+(?:here|calling|from|on the line|speaking|checking in)\b",
        first_clean))
    questions = 0
    answered = 0
    grounded_questions = 0
    links = 0
    for i in range(len(turns) - 1):
        marker, said = turns[i]
        nxt, answer = turns[i + 1]
        if marker in ("A", "B", "D") and "?" in said:
            questions += 1
            # 2026-09-08 (the scan): in a three-voice call the co-host
            # speaks between the question and the caller's answer - the
            # answer within the next two turns counts.
            if nxt in ("C", "E") or (i + 2 < len(turns) and nxt in ("A", "B", "D")
                                     and turns[i + 2][0] in ("C", "E")):
                answered += 1
            if i and turns[i - 1][0] in ("C", "E"):
                ignore = (_call_topic_terms(topic)
                          | _call_topic_terms(caller_name)
                          | _call_topic_terms(caller2_name))
                asked_terms = set(_call_novelty_terms(said)) - ignore
                supplied = set(_call_novelty_terms(turns[i - 1][1])) - ignore
                if asked_terms & supplied:
                    grounded_questions += 1
        # A concrete lexical callback is strong evidence of response; a
        # question immediately answered by the caller is the other natural
        # form.  This is diagnostic, not a semantic oracle.
        left = set(_call_novelty_terms(said))
        right = set(_call_novelty_terms(answer))
        if left & right or ("?" in said and nxt in ("C", "E")):
            links += 1
    share = len(caller_at) / max(1, len(turns))
    # #1157: an OPERATOR-AUTHORED storyline may resemble itself for the
    # same reason a caller storyline may - three people ringing about
    # one night in one town are not the station repeating itself.
    _plot_id = str((plot or {}).get("id") or "") if isinstance(
        plot, dict) else ""
    novelty = call_novelty(script, include_shelf=include_shelf,
                           exclude_entry=exclude_entry,
                           exclude_ids=_story_ids or None,      # #1039
                           exclude_plot=_plot_id)               # #1157
    topic_grade = call_topic_report(script, topic)
    speakerbox_grade = call_speakerbox_report(
        script, speakerbox_text, topic)
    speakerbox_novelty = call_speakerbox_novelty(
        speakerbox_text, include_shelf, exclude_entry)
    tint_grade = call_tint_report(
        source_script, script,
        tuple(n for n in (caller_name, caller2_name) if n))
    close_text = turns[-1][1].lower() if turns else ""
    closed = bool(turns and turns[-1][0] in ("A", "B", "D")
                  and re.search(r"\b(thank|thanks|goodbye|goodnight|"
                                r"appreciate|take care)\b", close_text))
    # A sign-off is not a resolution if the hosts spend the final two turns
    # talking after the caller's last contribution.  The audible arc must
    # return to the person on the line, let them land it, then close.
    resolved = bool(closed and caller_at
                    and caller_at[-1] == len(turns) - 2)
    # A real request-line call has an observable protocol, not merely three
    # C-labelled speeches inside banter: a host answers a ringing line without
    # already knowing the stranger's name; the caller introduces themselves;
    # the next host greets that person and starts the interview.
    opening_marker, opening_text = turns[0] if turns else ("", "")
    opening_flat = " ".join(opening_text.lower().split())
    answered_line = bool(
        opening_marker in ("A", "B", "D")
        and re.search(r"\b(call|phone|phones|line|request line)\b",
                      opening_flat)
        and re.search(r"\b(ring|ringing|live|on air|go ahead|hello|pine box)\b",
                      opening_flat))
    host_knew_name = bool(first_name and re.search(
        rf"\b{re.escape(first_name)}\b", opening_flat))
    first_words = re.findall(r"[a-z0-9']+", first_text.lower())
    first_topic = _call_topic_terms(first_text) & _call_topic_terms(topic)
    # A caller may naturally identify the place they are calling from.  One
    # incidental theme word in that location (for example ``ice machine``
    # while the subject is the DGX machine) is still a brief introduction;
    # requiring zero overlap rejected a perfectly normal request-line hello.
    # Two or more subject terms is enough evidence that the caller has begun
    # the story before the host has greeted them, and remains a hard failure.
    intro_only = bool(first_text and len(first_words) <= 30
                      and len(first_topic) <= 1)
    greeted = False
    if first_caller >= 0 and first_caller + 1 < len(turns):
        # 2026-09-08 (the scan): the greeting is in the FIRST TWO host turns
        # after the introduction. The live road can put two caller turns
        # together, and on a three-voice call the co-host says something
        # before the host greets - both read as "never greeted by name".
        _hosts = [t for t in turns[first_caller + 1:first_caller + 4]
                  if t[0] in ("A", "B", "D")][:2]
        greeted = bool(first_name and any(
            re.search(rf"\b{_first_name}", text.lower()) for _m, text in _hosts))
    faults: list[str] = []
    if len(turns) < 6:
        faults.append("fewer than six complete turns")
    if len(caller_at) < 3:
        faults.append("the caller has fewer than three turns")
    # 2026-09-08 (the scan): with a third voice on the call the caller's
    # share of ALL turns runs a third at best (7 of 21 = 0.333); the floor
    # is 0.30 there.
    _share_floor = 0.30 if any(m in ("B", "D") for m, _t in turns) and any(m == "A" for m, _t in turns) else 0.35
    if caller_at and not _share_floor <= share <= 0.72:
        faults.append("the caller/host turn share is out of balance")
    if first_caller < 0 or first_caller > 1:
        faults.append("the caller is not heard immediately after the host answers")
    if not answered_line:
        faults.append("the opening host does not audibly answer a ringing line")
    # #1039: a story call-back is greeted by name and skips the
    # self-introduction - the hosts know exactly who this is.
    if host_knew_name and not _story:
        faults.append("the host says the stranger's name before they introduce themselves")
    if not introduced and not _story:
        faults.append("the caller does not introduce themselves")
    if not intro_only and not _story:
        faults.append("the caller's first turn is not a brief introduction")
    if not greeted:
        faults.append("a host does not greet the caller by name after the introduction")
    if not closed:
        faults.append("a host does not give the call a clear spoken sign-off")
    if not resolved:
        faults.append("the caller does not resolve the exchange immediately "
                      "before the host signs off")
    if questions < 2 or answered < 2:
        faults.append("fewer than two natural host questions are answered by "
                      "the caller")
    # 2026-09-08 (the scan): the three RICHNESS legs. On a call that has
    # already been rapped they are advisory: the tint is allowed to
    # paraphrase the topic words and the speakbox passage, and re-refusing
    # the call at activation threw away six fully rapped calls (66 accepted
    # bars, 23 deep asks) tonight. Every PROTOCOL leg above and every tint
    # fidelity fault below stays binding.
    soft: list[str] = []
    _soft = soft.append if soft_quality else faults.append
    if grounded_questions < 2:
        _soft("fewer than two host questions pick up a concrete "
              "detail from the caller's prior answer")
    if len(turns) >= 6 and links / max(1, len(turns) - 1) < 0.2:
        faults.append("too few adjacent turns visibly connect")
    if not novelty["ok"]:
        faults.append("the premise or dialogue is too similar to a stored call")
    if not topic_grade["ok"]:
        _soft("the database topic is not carried by both caller and hosts")
    if not speakerbox_grade["ok"]:
        _soft("the selected Speakerbox source never enters the dialogue")
    # 2026-09-10: ADVISORY ON A CALL THAT IS ALREADY RAPPED, for exactly the
    # reason the richness legs above were softened - re-refusing a finished
    # call at activation throws the whole thing away. A seed collision is a
    # VARIETY concern, not a protocol violation: the caller still introduced
    # themselves, was greeted, answered questions, resolved and was signed
    # off. Measured in the review queue: 27 of 301 pending decisions were a
    # fully written call refused because its Speakerbox passage had been used
    # inside the 240-call lookback - about a day at the current quota - while
    # the caller road was already failing 86% of its attempts and the
    # schedule was missing 75 of 76 entries for want of one.
    if not speakerbox_novelty["ok"]:
        _soft("the selected Speakerbox source is already assigned "
              "to another call")
    faults.extend(tint_grade.get("faults") or [])
    return {
        "ok": not faults, "turns": len(turns), "soft_faults": soft,
        "caller_turns": len(caller_at), "host_turns": len(host_at),
        "caller_share": round(share, 3), "first_caller": first_caller,
        "answered_line": answered_line, "host_knew_name": host_knew_name,
        "introduced": introduced, "intro_only": intro_only,
        "intro_topic_terms": sorted(first_topic),
        "greeted": greeted, "closed": closed, "resolved": resolved,
        "questions": questions,
        "answered_questions": answered,
        "grounded_questions": grounded_questions,
        "linked_turns": links, "faults": faults, "novelty": novelty,
        "topic": topic_grade, "speakerbox": speakerbox_grade,
        "speakerbox_novelty": speakerbox_novelty,
        "tint": tint_grade,
        "story": str(_story.get("id") or ""),                     # #1039
        "plot": _plot_id,                                        # #1157
    }


def call_entry_contract(entry: Any) -> bool:
    """Whether a banked call was explicitly accepted by today's contract.

    We deliberately do not auto-bless older cupboard rows here. They were
    written before complete transcripts, topics and novelty fingerprints were
    retained, so their quality cannot be established without pretending. A
    paused station will replace them with graded calls; their orphaned audio is
    then eligible for ordinary pantry cleanup instead of being aired or kept.
    """
    try:
        if not isinstance(entry, dict) or not entry.get("caller_name"):
            return False
        meta = entry.get("call") or {}
        quality = meta.get("quality") or {}
        script = str(entry.get("script") or "").strip()
        fingerprint = str(meta.get("fingerprint") or "")
        return bool(
            int(meta.get("contract_version") or 0) == CALL_CONTRACT_VERSION
            and str(meta.get("topic") or "").strip()
            and quality.get("ok")
            and fingerprint
            and fingerprint == call_fingerprint(script)
        )
    except Exception:  # noqa: BLE001
        return False


@_with_review_instances
def call_entry_regrade(entry: dict[str, Any],
                       include_shelf: bool = True) -> dict[str, Any]:
    """Bind the phone contract to the words that would air right now.

    Tinting is allowed to change cadence and diction, which necessarily
    changes the exact fingerprint.  The former pipeline graded the plain
    draft, activated a later tint, and left the old fingerprint attached;
    every successfully tinted call then failed readiness forever.  Regrading
    at each activation also catches a stylish tint that damaged the phone
    protocol, theme, Speakerbox evidence or semantic fidelity.
    """
    if not isinstance(entry, dict):
        return {"ok": False, "faults": ["there is no call entry"]}
    meta = entry.setdefault("call", {})
    caller_name = str(entry.get("caller_name") or "")
    caller2_name = str(entry.get("caller2_name") or "")
    active = str(entry.get("script") or "")
    source = (str(entry.get("script_plain") or "")
              if entry.get("use") == "tinted" else "")
    report = call_flow_report(
        active, caller_name, caller2_name,
        include_shelf=include_shelf,
        topic=str(meta.get("topic") or ""), source_script=source,
        speakerbox_text=str(meta.get("speakerbox_text") or ""),
        exclude_entry=entry,
        story=(meta.get("story") if isinstance(meta.get("story"), dict)
               else entry.get("story")),                          # #1039
        plot=(meta.get("plot") if isinstance(meta.get("plot"), dict)
              else entry.get("plot")),                            # #1157
        # 2026-09-08 (the scan): this call has been rapped - the richness
        # legs are advisory here, the protocol and the tint's fidelity are not.
        soft_quality=bool(str(entry.get("use") or "") == "tinted"))
    if report.get("soft_faults"):
        pipeline_log("call", "the rapped call keeps the air with advisories: "
                     + "; ".join(str(f) for f in report["soft_faults"])[:220])
    turns = banter_turns(active, caller_name, caller2_name)
    report.update(machine_ok=bool(report.get("ok")),
                  machine_faults=list(report.get("faults") or []))
    if not report.get("ok") and _call_line_review(entry, report, "grade"):
        report.update(ok=True, operator_accepted=True)
    premise = next((said for marker, said in turns
                    if marker in ("C", "E")), "")
    meta.update({
        "contract_version": CALL_CONTRACT_VERSION,
        "fingerprint": str((report.get("novelty") or {}).get(
            "fingerprint") or ""),
        "premise": str(premise)[:700],
        "quality": report,
    })
    station_flow_event("conversation", "ok" if report.get("ok") else "fail",
                       "Caller conversation contract evaluated",
                       {"script": active, "caller": caller_name, "report": report},
                       trace_id=str(meta.get("fingerprint") or ""), from_node="draft")
    return report


def call_novelty_prompt(exclude_plot: str = "") -> str:
    """A compact memory of recent openings/topics for the writing prompt.

    #1157: `exclude_plot` drops the calls that belong to the storyline
    on air. This clause is the station's anti-memory - "do not revisit
    any of these" - and pointed at a deliberate serial it is an
    instruction to abandon the story between one caller and the next,
    which is precisely what the operator says is missing. So the
    storyline's own calls come out of the list, and the writer is told
    in as many words that continuing THIS one is the job."""
    _keep = str(exclude_plot or "")
    rows = [r for r in _call_history_scripts()
            if not (_keep and str(r.get("plot") or "") == _keep)][-12:]
    if not rows:
        return ""
    seen: list[str] = []
    for row in reversed(rows):
        turns = banter_turns(str(row.get("script") or ""),
                             str(row.get("name") or ""))
        caller_line = next((t for m, t in turns if m in ("C", "E")), "")
        topic = str(row.get("topic") or "").strip()
        sample = " / ".join(x for x in (topic, caller_line[:150]) if x)
        if sample and sample not in seen:
            seen.append(sample)
    if not seen:
        return ""
    return ("\n\nCALL MEMORY - these are recently used premises/opening moves. "
            "Do not paraphrase, reskin, or revisit any of them; choose a "
            "different concrete situation, conflict, questions and landing:\n- "
            + "\n- ".join(seen[:10])
            + ("\n(The STORYLINE on air tonight is the exception and is "
               "not in this list: carrying it forward is the job, and "
               "this caller must ADD to it, never retell it.)"
               if _keep else ""))


def _hangup_seed() -> list[dict[str, Any]]:
    return [{"id": uuid.uuid4().hex[:8], "text": text, "weight": 1.0,
             "enabled": True, "uses": 0, "last": 0, "added": int(time.time())}
            for text in (*CALLER_OUTCOMES, *CALLER_SUCCESS_OUTCOMES)]


# #1000: the endings that stop rather than finish. #673 put three of
# these in on purpose - "a call that simply stops reads as the writer
# running out of road, but a call that stops and gets remarked on reads as
# a thing that happened" - and that argument still holds. What did not
# hold is the FREQUENCY: three of sixteen seeded outcomes, so about one
# call in five just ended, which is what the operator kept hearing.
#
# They are damped rather than deleted, once, on the shelf the operator can
# edit - so the texture survives at about one call in twenty and the
# operator can still turn any of them back up by hand.
_HANGUP_ABRUPT = ("hangs up abruptly", "goes silent mid-answer",
                  "slams the phone down")
HANGUP_ABRUPT_WEIGHT = 0.2


def _hangup_damp_abrupt(rows: list[dict[str, Any]]) -> bool:
    """Once: pull the just-stops endings down to a rare flavour. Marked on
    the row so it is never done twice and an operator who turns one back
    up keeps their setting."""
    moved = False
    for row in rows:
        try:
            if row.get("damped_1000"):
                continue
            text = str(row.get("text") or "").lower()
            if not any(k in text for k in _HANGUP_ABRUPT):
                continue
            row["damped_1000"] = True
            if float(row.get("weight") or 0) > HANGUP_ABRUPT_WEIGHT:
                row["weight"] = HANGUP_ABRUPT_WEIGHT
            moved = True
        except Exception:  # noqa: BLE001
            continue
    return moved


def hangup_rules() -> list[dict[str, Any]]:
    """The shelf, seeded from the built-in outcomes the first time it is
    asked for — so the house style is what you start editing, not an empty
    box you have to refill before a call can end."""
    with _HANGUP_LOCK:
        try:
            rows = json.loads(HANGUPS_PATH.read_text())
            if isinstance(rows, list) and rows:
                rows = [r for r in rows if isinstance(r, dict) and r.get("text")]
                known = {str(r.get("text") or "").strip() for r in rows}
                added = False
                for text in CALLER_SUCCESS_OUTCOMES:
                    if text not in known:
                        rows.append({"id": uuid.uuid4().hex[:8], "text": text,
                                     "weight": 1.0, "enabled": True,
                                     "uses": 0, "last": 0,
                                     "added": int(time.time())})
                        added = True
                if _hangup_damp_abrupt(rows):              # #1000
                    added = True
                if added:
                    _hangup_write(rows)
                return rows
        except Exception:
            pass
        rows = _hangup_seed()
        _hangup_damp_abrupt(rows)                              # #1000
        _hangup_write(rows)
        return rows


def _hangup_write(rows: list[dict[str, Any]]) -> None:
    try:
        HANGUPS_PATH.parent.mkdir(parents=True, exist_ok=True)
        tmp = HANGUPS_PATH.with_suffix(".tmp")
        tmp.write_text(json.dumps(rows[:200], indent=1) + "\n")
        tmp.replace(HANGUPS_PATH)
    except OSError:
        pass


def hangup_add(text: str, weight: float = 1.0) -> dict[str, Any]:
    with _HANGUP_LOCK:
        rows = hangup_rules()
        entry = {"id": uuid.uuid4().hex[:8], "text": str(text)[:600],
                 "weight": max(0.0, min(10.0, float(weight))),
                 "enabled": True, "uses": 0, "last": 0,
                 "added": int(time.time())}
        rows.append(entry)
        _hangup_write(rows)
        return entry


def hangup_update(rule_id: str, **fields: Any) -> dict[str, Any] | None:
    with _HANGUP_LOCK:
        rows = hangup_rules()
        for row in rows:
            if row.get("id") != rule_id:
                continue
            if "text" in fields:
                row["text"] = str(fields["text"])[:600]
            if "weight" in fields:
                try:
                    row["weight"] = max(0.0, min(10.0, float(fields["weight"])))
                except (TypeError, ValueError):
                    pass
            if "enabled" in fields:
                row["enabled"] = bool(fields["enabled"])
            _hangup_write(rows)
            return row
    return None


def hangup_delete(rule_id: str) -> bool:
    with _HANGUP_LOCK:
        rows = hangup_rules()
        keep = [r for r in rows if r.get("id") != rule_id]
        if len(keep) == len(rows):
            return False
        # Never empty the shelf: a call has to be able to end somehow, and
        # an empty file re-seeds itself on the next read anyway, which would
        # silently resurrect everything you just deleted.
        if not keep:
            return False
        _hangup_write(keep)
        return True


# --- The case book (#854) --------------------------------------------------
# "connect the writing desk to the database of cases that come up when
# customers call ... sophisticated cases written for calls that's able to be
# acted out and set up in the reserve that's able to play out through the
# radio in a stream seamlessly."
#
# CALLER_DISPOSITIONS (#879) says what TEMPER the caller arrived in. The
# hang-up shelf above (#691) says how the call ENDS. Neither has ever said
# what the call is ABOUT: the subject was whatever the speakbox happened to
# hand over that second, which is why the phone could ring nine times in an
# hour and every call be the same shape.
#
# This is the missing third leg. A persisted, operator-editable database of
# SITUATIONS — a grievance, a question, a demand, a giveaway — each graded
# on a heat scale so the desk can ask for a gentle one or a hostile one and
# get a script that actually behaves that way.
#
# The division of labour is strict, and it is the whole reason three
# generators can share one prompt without fighting:
#     the CASE        supplies the SUBJECT   (what they rang about)
#     the RULE        supplies the ENDING    (how the call terminates)
#     the DISPOSITION supplies the TEMPER    (who is holding the phone)
CASES_PATH = data_path("caller_cases.json")
_CASES_LOCK = RLock()

# THE HEAT SCALE. Four rungs, and a call written at one of them has to sound
# like that rung — a gentle case must not be talked into a row, a hostile one
# must not be defused into a chat.
CASE_HEATS = (0, 1, 2, 3)
CASE_HEAT_NAMES = {0: "gentle", 1: "warm", 2: "heated", 3: "hostile"}
CASE_COOL_HEATS = (0, 1)
CASE_HOT_HEATS = (2, 3)
# A PRIZE call is a different KIND of thing rather than another rung: the
# station gives something away, and a giveaway is a promise the script has to
# keep. A prize case still carries a heat — a hostile caller who ends up
# winning is the best call this station knows how to make.
CASE_KINDS = ("call", "prize")

CASE_HEAT_CLAUSE = {
    0: (" HEAT — GENTLE. This one never gets loud. The caller is warm, or "
        "shy, or simply glad somebody picked up, and the pair are gentle "
        "back. Whatever they came for is small and human and they are not "
        "spoiling for anything. If friction appears at all it dissolves in "
        "a laugh inside two lines. Nobody raises their voice at any point "
        "of this call and the hosts do not manufacture a row out of it to "
        "make it interesting — the interest is in how ordinary it is."),
    1: (" HEAT — WARM. There is a real edge under the politeness. The "
        "caller has a genuine grievance and they do say it, but they say "
        "it civilly and they let the hosts answer before going again. It "
        "is allowed to get pointed — one dry remark, one flash of "
        "impatience, one 'well, that's easy for you to say' — and then it "
        "settles. It never becomes a shouting match, and both sides come "
        "out of it still liking each other."),
    2: (" HEAT — HEATED, AND IT CLIMBS. It opens reasonably and it does "
        "NOT stay there. The caller starts firm, gets less patient with "
        "every answer they will not accept, begins talking over one of the "
        "hosts, and by the middle of the call they are plainly angry. Play "
        "the escalation IN STAGES so a listener can hear it climbing — the "
        "volume, the speed, the manners going one at a time. The hosts do "
        "not simply capitulate to make it stop: one of them holds the "
        "station's corner, which makes it worse before it gets better."),
    3: (" HEAT — HOSTILE. This person did not ring to be handled. They "
        "come in hot from their very first line, they accuse, they "
        "interrupt, they will not be soothed, and they take everything "
        "offered as further proof of what they already believe. Let it be "
        "genuinely uncomfortable to listen to: the pair are rattled, one "
        "takes it personally, the other tries to be reasonable and gets "
        "nowhere at all. Never cut the tension with a joke to escape it — "
        "whatever comedy is in this call is in how badly the two of them "
        "handle it. Real anger, real words, and nobody narrates the arc."),
}

CASE_PRIZE_CLAUSE = (
    " THIS IS A PRIZE CALL AND THE STAKES ARE REAL. The station is GIVING "
    "SOMETHING AWAY on this call and it has to be honoured OUT LOUD before "
    "the call is over: the pair name the prize plainly, say what this "
    "caller has actually won, and settle how they get it — when they can "
    "collect, from whom, and what they have to bring. Nobody hints at it "
    "and moves on, nobody quietly takes it back, and it is never revealed "
    "to be a trick. The caller reacts entirely in character: a gentle one "
    "is overwhelmed by it, an angry one is thrown by winning and does not "
    "soften anything like as much as the pair expect. The prize is not the "
    "joke; the reaction to it is. The giveaway is settled BEFORE the "
    "ending below, which still has to be the last thing that happens.")


def case_heat(case: dict[str, Any]) -> int:
    """The rung this case sits on, always a legal one."""
    try:
        return max(0, min(3, int(case.get("heat") or 0)))
    except (TypeError, ValueError):
        return 0


def case_heat_name(case: dict[str, Any]) -> str:
    return CASE_HEAT_NAMES.get(case_heat(case), "gentle") if case else ""


def case_is_prize(case: dict[str, Any]) -> bool:
    return bool(case) and str(case.get("kind") or "call") == "prize"


def _case_row(row: dict[str, Any]) -> dict[str, Any]:
    """One case, normalized. Everything that reaches a prompt or a slider is
    clamped here, so a hand-edited file can be wrong without being fatal."""
    try:
        weight = max(0.0, min(10.0, float(row.get("weight", 1.0))))
    except (TypeError, ValueError):
        weight = 1.0
    kind = str(row.get("kind") or "call")
    return {
        "id": str(row.get("id") or uuid.uuid4().hex[:8])[:40],
        "title": str(row.get("title") or "")[:120],
        "blurb": str(row.get("blurb") or "")[:900],
        "heat": case_heat(row),
        "kind": kind if kind in CASE_KINDS else "call",
        "weight": weight,
        "outcome": str(row.get("outcome") or "")[:400],
        "props": str(row.get("props") or "")[:300],
        "enabled": bool(row.get("enabled", True)),
        "uses": int(row.get("uses") or 0),          # times it has AIRED
        "picks": int(row.get("picks") or 0),        # times it has been WRITTEN
        "last": int(row.get("last") or 0),
        "aired": int(row.get("aired") or 0),
        "added": int(row.get("added") or 0),
    }


