CALLER_VOICES_PATH = data_path("caller_voices.json")
_CALLER_VOICE_LOCK = RLock()

# The face on the licence (#699). Drawn from the gallery once and REMEMBERED
# — the same trap the voice rotation was in was waiting here: picking with
# hash(name) % len(gallery) would hand a caller a different face every time
# you rendered another image.
CALLER_FACES_PATH = data_path("caller_faces.json")
_CALLER_FACE_LOCK = RLock()


def caller_face(name: str) -> str:
    """A gallery image for this caller — the same one every time they ring."""
    if not name:
        return ""
    with _CALLER_FACE_LOCK:
        try:
            book = json.loads(CALLER_FACES_PATH.read_text())
            book = book if isinstance(book, dict) else {}
        except Exception:
            book = {}
        held = str(book.get(name) or "")
        # #831: a remembered face is only good while its picture can still be
        # SERVED. Five callers were holding contact-sheet jpgs out of a
        # subfolder the image route could never resolve, and a held pick came
        # straight back unchecked — so their licence photo was broken for
        # good. One that cannot be found is re-drawn instead.
        if held and comfy_output_find(held) is not None:
            return held
        try:
            found = [q.name for q in COMFY_OUTPUT.rglob("*")
                     if q.is_file() and q.suffix.lower() in
                     (".png", ".jpg", ".jpeg", ".webp")
                     and face_candidate(q)]
        except OSError:
            found = []
        if not found:
            return ""
        # One nobody else on the switchboard is already wearing.
        spoken_for = set(book.values())
        free = [f for f in found if f not in spoken_for] or found
        pick = random.choice(free)
        book[name[:80]] = pick
        if len(book) > 400:
            book = dict(list(book.items())[-300:])
        try:
            CALLER_FACES_PATH.parent.mkdir(parents=True, exist_ok=True)
            tmp = CALLER_FACES_PATH.with_suffix(".tmp")
            tmp.write_text(json.dumps(book, indent=1))
            tmp.replace(CALLER_FACES_PATH)
        except OSError:
            pass
        return pick


def _caller_voice_book() -> dict[str, str]:
    """Who sounds like whom (#699) — remembered, so the same person really
    does keep the same voice even when the library grows underneath them."""
    try:
        rows = json.loads(CALLER_VOICES_PATH.read_text())
        return {str(k): str(v) for k, v in rows.items()} \
            if isinstance(rows, dict) else {}
    except Exception:
        return {}


def _caller_voice_remember(name: str, vid: str) -> None:
    with _CALLER_VOICE_LOCK:
        book = _caller_voice_book()
        book[str(name)[:80]] = vid
        # Bounded: the conjured strangers are endless, the regulars are not.
        if len(book) > 400:
            book = dict(list(book.items())[-300:])
        try:
            CALLER_VOICES_PATH.parent.mkdir(parents=True, exist_ok=True)
            tmp = CALLER_VOICES_PATH.with_suffix(".tmp")
            tmp.write_text(json.dumps(book, indent=1) + "\n")
            tmp.replace(CALLER_VOICES_PATH)
        except OSError:
            pass


def clone_caller_pct() -> int:
    """What share of callers ring in on a library voice (#699). Was a
    constant at 45; it is a dial now, because "use the voices I add" is a
    thing you should be able to turn up."""
    try:
        return max(0, min(100, int(dj_settings().get("clone_caller_pct",
                                                     CLONE_CALLER_PCT))))
    except Exception:
        return CLONE_CALLER_PCT


def caller_voice_for(name: str, taken: set[str],
                     catalogue: set[str] | None = None,
                     gender: str = "",
                     clones: list[str] | None = None) -> str:
    """A stable third voice per caller, never the pair's own: the same person
    ringing twice sounds like the same person. Filtered against what Piper
    actually has when the catalogue is passed — a voice that is not
    installed synthesises nothing, and the caller goes silent. A caller
    with a gender set draws only from that side of the bank (#267);
    unset, the whole bank as before. When `clones` is passed (only when the
    XTTS engine is up), a share of callers ring in with a cloned voice so
    all the generated voices get on air (#457) — stable per name."""
    digest = int(hashlib.sha1(name.encode()).hexdigest(), 16)
    usable = [c for c in (clones or []) if c not in taken]
    # #1021: under the avoid-Piper policy EVERY caller offered a clone
    # takes one - the remembered voice for a name we have heard, the
    # least-aired for a new one. clone_caller_pct is the share only when
    # the policy is off.
    if usable and (voicepolicy_avoid_piper()
                   or (digest % 100) < clone_caller_pct()):
        # #699: the assignment is REMEMBERED, and an unheard voice goes first.
        #
        # It used to be usable[digest % len(usable)] — a pure function of the
        # name and the pool SIZE. Two things fell out of that. A voice was
        # only ever heard if some caller's digest happened to land on its
        # index, so importing a voice into a library this size could mean
        # never hearing it. And because the size is in the modulus, adding
        # one re-pointed every existing caller at a different voice, which is
        # the opposite of the stability the hash was chosen for.
        #
        # Now: whoever we have heard before keeps the voice they had, and a
        # caller we have not heard before takes the least-aired voice in the
        # library — so a voice you added five minutes ago is the very next
        # one out of the phone.
        book = _caller_voice_book()
        held = book.get(name)
        if held and held in usable:
            return held
        air = voice_airtime()
        fresh = sorted(
            usable,
            key=lambda v: (int((air.get(v) or {}).get("airings") or 0),
                           int((air.get(v) or {}).get("last") or 0),
                           v))
        pick = fresh[0]
        _caller_voice_remember(name, pick)
        return pick
    banks = ([BANTER_VOICES[gender]] if gender in BANTER_VOICES
             else BANTER_VOICES.values())
    pool = sorted(n for names in banks for n in names
                  if n not in taken
                  and (catalogue is None or n in catalogue))
    if not pool:
        return usable[digest % len(usable)] if usable else ""
    # #1021: a Piper voice for this caller, and the reason on the log -
    # the only way here under the policy is an empty clone pool, which
    # means no clone engine answered when the draw was made.
    if voicepolicy_avoid_piper():
        voicepolicy_say(f"caller:piper:{name[:40]}",
                        f"caller {name[:60]}: Piper voice "
                        f"{pool[digest % len(pool)]} - no library clone "
                        "was offered for the draw (both clone engines "
                        "down, or the pool is empty) (#1021)")
    return pool[digest % len(pool)]


_NAMEISH = re.compile(r"\b[A-Z][a-z]{2,12}\b")
_NAME_STOP = {
    "The", "And", "But", "You", "She", "Her", "His", "They", "That", "This",
    "There", "Then", "What", "When", "Where", "Well", "With", "From", "Not",
    "Now", "Just", "Like", "Yeah", "Okay", "Look", "Man", "God", "Jesus",
    "Christ", "Mister", "Miss", "Sir", "Hey", "How", "Why", "Who", "All",
    "One", "Two", "Because", "Maybe", "Right", "Come", "Here", "Every",
    "Never", "Nothing", "Something", "Someone", "Everybody", "Nobody",
}


def speakbox_character(doc_name: str) -> str:
    """Somebody actually named in the document (#260).

    A capitalised word that appears more than once mid-sentence in the
    cached gems is a person the transcript keeps talking about — Snake,
    Tyrion, Stillman. The pick is stable per document, so the same character
    keeps ringing back."""
    row = _gem_cache().get(doc_name)
    if not isinstance(row, dict):
        return ""
    counts: dict[str, int] = {}
    for line in row.get("lines") or []:
        for at, word in enumerate(_NAMEISH.findall(str(line))):
            if word in _NAME_STOP:
                continue
            # Sentence-initial capitals are grammar, not names; a crude but
            # cheap filter is to ignore the very first word of the line.
            if at == 0 and str(line).startswith(word):
                continue
            counts[word] = counts.get(word, 0) + 1
    named = sorted((w for w, c in counts.items() if c >= 2),
                   key=lambda w: (-counts[w], w))
    if not named:
        return ""
    digest = int(hashlib.sha1(doc_name.encode()).hexdigest(), 16)
    return named[digest % min(3, len(named))]


# What the unhinged ones are on about (#358). Each premise is believed
