def swath_intrigue(text: str) -> float:
    """How hard a swath lands on fresh ears (#359): unburned vocabulary,
    a bit of length, and a question in it all raise the score."""
    words = re.findall(r"[a-z']+", text.lower())
    if not words:
        return 0.0
    burned: set[str] = set()
    for phrase in overused_phrases(20):
        burned.update(phrase.split())
    fresh = sum(1 for w in words if len(w) > 3 and w not in burned)
    return (fresh / len(words)
            + 0.3 * min(1.0, len(text) / 240.0)
            + (0.2 if "?" in text else 0.0))


# --- What the callers ring in ABOUT (#680) ----------------------------------
# The topic mix is a fixed set of rolls — mixtape haters, the unhinged, the
# news, your planted bombshells. That is a good house style and a bad leash:
# there was no way to say "tonight they are all ringing about X". A theme is
# that lever. It does not replace the mix, it BIASES it, because a station
# where every single caller is on message stops sounding like a phone line
# and starts sounding like a broadcast.
THEMES_PATH = data_path("caller_themes.json")
_THEMES_MEM: dict[str, Any] = {}
# The one it has always effectively had, named so it can be chosen again.
DEFAULT_THEME = {
    "name": "heat / DGX Spark",
    "text": "the heat coming off the DGX Spark, the machine this station "
            "runs on, and the strange things it does when it gets hot",
}


def themes_read() -> dict[str, Any]:
    global _THEMES_MEM
    if not _THEMES_MEM:
        try:
            _THEMES_MEM = json.loads(THEMES_PATH.read_text()) or {}
        except Exception:
            _THEMES_MEM = {}
    _THEMES_MEM.setdefault("themes", [dict(DEFAULT_THEME)])
    _THEMES_MEM.setdefault("active", DEFAULT_THEME["name"])
    _THEMES_MEM.setdefault("strength", 70)
    _THEMES_MEM.setdefault("doc", "")          # #766: the report they cite
    return _THEMES_MEM


def themes_write(rows: dict[str, Any]) -> None:
    global _THEMES_MEM
    _THEMES_MEM = rows
    try:
        THEMES_PATH.parent.mkdir(parents=True, exist_ok=True)
        tmp = THEMES_PATH.with_suffix(".tmp")
        tmp.write_text(json.dumps(rows, indent=1))
        tmp.replace(THEMES_PATH)
    except OSError:
        pass


def theme_owns_air() -> dict[str, Any]:
    """#775: the subject the OPERATOR has chosen, when they have chosen one
    that is not the station's own default.

    The default theme is "heat / DGX Spark" - the subject this station talks
    about when nobody has told it otherwise, and the one every hard-coded
    heat road is already an expression of. So when the default is active,
    those roads ARE the theme and nothing needs suppressing. The moment the
    operator picks something else, that choice outranks the built-in
    material: it is the whole meaning of setting it.

    Returns {} when the callers are roaming or the default is in force."""
    row = active_theme()
    if not row or row.get("name") == DEFAULT_THEME["name"]:
        return {}
    return row


def theme_air_clause(theme: dict[str, Any]) -> str:
    """The line that tells a round what tonight is about (#775)."""
    if not theme:
        return ""
    return (" TONIGHT'S SUBJECT, which the station has been told to stay on: "
            f"{theme.get('text') or theme.get('name')}. Bring the conversation "
            "round to it in your own way - argue about it, joke about it, "
            "take it somewhere - rather than announcing it.")


def active_theme() -> dict[str, Any]:
    """The theme in force, or {} when the callers are left to roam."""
    rows = themes_read()
    want = str(rows.get("active") or "")
    if not want or want == "—":
        return {}
    for row in rows.get("themes") or []:
        if row.get("name") == want:
            return dict(row)
    return {}


async def caller_topic() -> tuple[str, dict[str, Any]]:
    """What tonight's caller is on about: a diatribe out of the speakbox,
    something completely unhinged (#358), a news story, or one of your
    planted topics — biased toward tonight's theme when one is set (#680)."""
    # The database theme is the PHONE DESK'S umbrella, not another weighted
    # flavour. Individual callers still bring different stories, positions,
    # evidence and temperaments, but every call belongs to the subject the
    # operator put in force. The old strength roll quietly sent 36% of calls
    # somewhere else at the live 64% setting.
    theme = active_theme()
    if theme:
        # #686: the theme call is not a polite enquiry. Pull real material
        # out of the shelf and make them RIFF on it — a caller who only
        # states their topic is a survey response, not radio.
        # #766: a named report, when one has been chosen for them, rather
        # than whatever the shelf happened to hand over.
        _report = str(themes_read().get("doc") or "")
        swath = await speakbox_quote(most=4, cap=420, only=_report)
        mined = ""
        if swath and swath.get("text"):
            if _report and swath.get("file") == _report:
                mined = (
                    "\n\nTHE REPORT THEY ARE RINGING ABOUT — the caller has "
                    f"read \"{_report}\" and has it in front of them. They "
                    "CITE IT: they quote a phrase of it back, get another "
                    "half-wrong, build a joke on top of it, wave it as "
                    "evidence, and they say where it came from. The pair "
                    "have read it too and argue about what it actually "
                    f"says:\n{swath['text']}")
            else:
                mined = (
                    "\n\nMATERIAL FROM THE STATION'S OWN SHELF — the caller "
                    "has read this, or heard it, or half-remembers it, and "
                    "they WEAVE IT IN: they quote a phrase of it back, mangle "
                    "another, build a joke on top of it, or cite it as "
                    f"evidence for whatever they are arguing:\n"
                    f"{swath['text']}")
        return (
            f"The caller is ringing in about {theme['text']}. That is what "
            "is on their mind and they have come to the station about it "
            "specifically — they have an opinion, a story, a grievance or a "
            "question, and it is THEIRS, particular and concrete, not a "
            "general observation. "
            # #686: push it. A theme call should be the funniest thing in
            # the hour, not the most on-message.
            "They PUSH THE LIMITS with it — they are funny about it, they "
            "take it somewhere further than anyone expected, they make the "
            "joke nobody else would make about it and commit to it "
            "completely. The pair egg them on, top the joke, and take the "
            "subject seriously even while it gets ridiculous."
            + mined,
            swath or {})
    roll = random.random()
    # The mixtape haters (#453): they ring DEMANDING no more MX tapes. The
    # pair can refuse outright, but the caller still gets to finish their case
    # and hear an answer before the call reaches its closing beat.
    if roll < 0.10:
        swath = await speakbox_quote(most=3, cap=260)
        line = (f" One host answers with this passage, then the caller gets "
                f"a complete reply to it before the hosts close the call: "
                f"\"{swath['text']}\""
                if swath else "")
        return (
            "An irate caller rings in DEMANDING the station stop playing "
            "the MX mixtapes — they are sick of them. The pair are having "
            "NONE of it: they defend the tapes, flatly refuse, tell the "
            "caller they will keep playing them anyway and there is nothing "
            "to be done about it." + line + " The pair then cheerfully "
            "announce the next mixtape is coming right up.",
            swath or {})
    # Some of them only rang to ask about the tapes (#239).
    if roll < 0.16:
        return (
            "The caller is obsessed with the MX mixtapes — the tapes from "
            "the mysterious Ehm Eckx this station plays — and is desperate "
            "to know where they can be bought. They cannot be bought "
            "anywhere, which the pair have to break gently while agreeing, "
            "at length, that the tapes are magnificent and Ehm Eckx is a "
            "genius who owes the world nothing.", {})
    if roll < 0.42:
        # Armed with the BEST material, not the first (#359): three draws
        # off different documents, the most intriguing one dialled.
        picks = [s for s in [await speakbox_quote() for _ in range(3)] if s]
        # #1177: weighted rather than strict - see swath_best. Best-of-3
        # against a fixed score picks the same passages every time.
        seed = swath_best(picks) if picks else {}
        if seed:
            return (
                "The caller has come armed with the most intriguing lines "
                "they could find, and delivers them WORD FOR WORD, full "
                "sections at a time, specifically to blow the hosts' "
                "socks off — and it WORKS. The pair are captivated, "
                "thrown, left actually thinking — and then they fall to "
                "arguing WITH EACH OTHER about what it means, taking "
                "opposite sides and getting personal about it while the "
                f"caller eggs them on: \"{seed['text']}\"", seed)
    if roll < 0.72:
        premise = unrepeated(list(CRAZY_CALLS), "crazy-call")
        return (
            "Tonight's caller says VERY crazy things (#358). Their "
            f"premise, which they believe completely: {premise}. They "
            "defend it with vivid, specific detail, they have EVIDENCE, "
            "and they escalate when doubted. The pair dig for details, "
            "try to stay reasonable, and get dragged all the way in.", {})
    if roll < 0.84:
        # Your Topics list gets its own share of the phone (#395): any
        # planted topic, drawn from the WHOLE bank, rung in cold.
        planted = [r.get("text") for r in read_bombshells()
                   if r.get("text")]
        if planted:
            return (
                "The caller is ringing, unprompted, about this exact "
                f"topic and will not be moved off it: "
                f"\"{unrepeated(planted, 'caller-topic')}\" They have "
                "arrived with opinions, examples and a grudge about it.",
                {})
    if roll < 0.92:
        headlines = await drudge_headlines(4)
        if headlines:
            return ("The caller is ringing about this news story and has "
                    "strong feelings: "
                    f"\"{random.choice(headlines)['title']}\"", {})
    pool = banter_pool(6) + [r["text"] for r in read_bombshells()[:4]]
    topic = random.choice(pool) if pool else "the state of the station"
    return (f"The caller is ringing about: \"{topic}\"", {})


async def dj_deep_round(track: dict[str, Any] | None = None) -> list[str]:
    """The secondary conversation engine (#496): a DEEP round handed far more
    foundation than the quick banter — both hosts' full personas, the running
    session, the emotional weather, and swaths off the shelf — written in ONE
    expanded-context pass into a long, character-true exchange, then rendered
    as a single seamless stream. Returns [] on any failure so the normal
    banter carries the show (dry beats broken)."""
    dj = dj_settings()
    host = dj.get("host_name") or "the host"
    recent = [f"{c.get('name') or c.get('who')}: {c.get('text', '')}"
              for c in (_RADIO.get("chat") or [])[-14:]
              if c.get("who") in ("dj", "cohost", "third", "caller")
              and c.get("text")]
    macros = _RADIO.get("speaker_macro") or {}
    weather = (", ".join(f"{who} is {m}" for who, m in macros.items() if m)
               or "both level-headed for now")
    swaths = []
    for _ in range(3):
        s = await speakbox_quote(most=4, cap=380)
        if s and s.get("text"):
            swaths.append(s["text"])
    now = _RADIO.get("now") or {}
    playing = (f"Now playing: {now.get('title')}"
               + (f" by {now.get('artist')}" if now.get("artist") else "")
               if now.get("title") else "Between records.")
    foundation = (
        f"HOST A — {host}: {dj['persona']}{mind_adjustment_prompt('dj')}\n\n"
        f"HOST B — {dj['cohost_name']}: {dj['cohost_persona']}{mind_adjustment_prompt('cohost')}\n\n"
        f"{day_context()}{accent_directive()}{plot_clause()}"
        f"THE ROOM RIGHT NOW: {playing}. Emotional weather: {weather}. "
        f"Tonight's running memory: {show_memory()}\n\n"
        + ("MATERIAL IN THEIR HEADS (weave it in, do not merely quote):\n- "
           + "\n- ".join(swaths) + "\n\n" if swaths else "")
        + "RECENT AIR (continue naturally FROM this, never repeat it):\n"
        + ("\n".join(recent) if recent else "(top of the hour)"))
    prompt = (
        f"{foundation}\n\n"
        f"Write a LONG, natural conversation between A ({host}) and B "
        f"({dj['cohost_name']}) for {dj['station_name']} — 12 to 16 lines, "
        "strictly alternating, each line genuinely RESPONDING to and building. "
        "For this broadcast, use 8 to 11 substantial turns, not short beats. "
        "on the one before. Simulate BOTH of them faithfully: the "
        "predilections, propensities, attitudes and behaviours in their "
        "personas above, coloured by the emotional weather. Let a real thread "
        "develop — turns, disagreements, callbacks to what was just said and "
        "to tonight's running memory. Each turn is a developed 60-to-100-word "
        "thought, except a verbatim Speakerbox passage which may be longer and "
        "must remain intact. Uninhibited late-night radio; lean into "
        "anything edgy. ENGLISH ONLY — every word of every line in English, "
        "never any other language or script, whatever the material quotes. "
        "No markdown, no emoji, no stage directions. Format "
        "each line as 'A: ...' and 'B: ...'."
        # #no-repeats: the deep round is one of the two main conversation engines and
        # it was the only one that never saw the do-not-repeat clauses — no
        # overused phrases, no overdwelt subjects, no lines-already-said. It
        # was writing with no memory of the show at all beyond fourteen chat
        # rows, which on the coalesced road is three or four turns.
        + avoid_reruns() + approach_clause(approach_pick())
        # #1027: the long-form round is never banked, so the second pass
        # can never reach it. This is its only chance to be tinted.
        + crystal_tint_note())
    try:
        script = await ask_model(
            prompt,
            # #786: 5200 truncated every deep round's tail — the prompt asks
            # for 12-16 turns of 60-100 words, which is 7-10k characters.
            limit=min(int(dj.get("reply_max_chars") or 6000), 9000),
            spice=0.5,
            num_ctx=16384,
        )
    except Exception:
        script = ""
    if not script:
        return []
    pipeline_log("model", "deep conversation round — expanded context, both "
                          "co-workers simulated in full (#496)")
    # #1038: the deep round goes STRAIGHT to air - twelve to sixteen
    # turns, no reserve, no second look. The whole-round path is one ask,
    # which is what this road can afford.
    if crystal_tint_two_pass():
        try:
            _dt = await crystal_tint(script, "deep round", whole_only=True)
            if _dt.get("ok") and _dt.get("script"):
                script = str(_dt["script"])
                pipeline_log("crystal", "the deep round was tinted whole "
                                        f"({_dt.get('ms')}ms) (#1038)")
        except Exception:  # noqa: BLE001
            pass
    return await speak_turns(banter_turns(script), track, 16,
                             render_stream=bool(dj.get("call_stream", True)))


# #771: when the last change-of-subject caller was put on the line. A theme
# change rings one immediately; a flurry of theme changes must still ring one.
_THEME_RING = [0.0]
THEME_RING_GAP = 240.0          # about the length of a call, plus the ring


async def _theme_ring_now() -> None:
    """#771: one caller, on the new subject, right now — and never a queue of
    them. A failure here must not take the theme change down with it: the
    setting is saved and honoured either way, this is only the demonstration
    of it."""
    try:
        await dj_call_generated()
    except Exception as exc:
        _THEME_RING[0] = 0.0
        pipeline_log("theme", "the change-of-subject call did not go out: "
                              f"{type(exc).__name__}: {exc}"[:180])


async def dj_call_generated(caller: dict[str, Any] | None = None,
                            force: bool = False,
                            case_id: str = "",
                            heat: int | None = None,
                            story: dict[str, Any] | None = None
                            ) -> dict[str, Any]:
    """A generated person rings the station and the pair take the call.

    #1039: with `story`, the caller is that story's caller ringing BACK -
    promoted to callers.json with their voice and face pinned, the
    cooldown waived, no case, no duo, no hostile turn (two structures at
    once is noise), the topic is the story's twist, and the angle tells
    the hosts they remember this person by name.

    The caller is a third voice on a phone line — static, a little echo, the
    telephone crush — in a random state, driven by the DJs, who inquire, dig,
    joke, and land the caller happy or furious as the dice decide (#236,
    #237)."""
    # Pause is a hard air boundary. Independent clocks and API/theme triggers
    # can all reach this function, so enforce it at the call road itself as
    # well as at each caller: ask the ordinary commitment-aware preparer for a
    # banked call and return immediately without taking the line, ringing,
    # rendering a live stream, stamping quota, or writing a fake hangup.
    if radio_paused():
        try:
            fire_and_forget(prep_one("caller"))
            pipeline_log("call", "a generated phone call was requested while "
                         "off air — it was sent to the writing/recording rooms "
                         "for the cupboard instead of opened live")
        except Exception:  # noqa: BLE001
            pass
        return {"caller": "", "lines": [], "state": "banking",
                "why": "the station is paused; a banked call was requested"}
    # #977: if somebody is already on the line, this call does not happen
    # now. A return, never a wait - blocking here would hold the round
    # supervisor open while the other call runs.
    _busy = call_line_busy()
    if _busy:
        pipeline_log("call", f"a second call stood down — {_busy} is "
                             "already on the line (#977)")
        return {"caller": "", "lines": [], "state": "deferred",
                "why": f"{_busy} is already on the line"}
    dj = dj_settings()
    rows = read_callers()
    # #1039: THE STORY'S CALLER, promoted to a regular with their voice
    # and face pinned, outranks every pick below. The file write runs
    # off the loop.
    if story:
        try:
            caller = await asyncio.to_thread(story_promote_caller, story)
            rows = read_callers()
            force = True
        except Exception as exc:  # noqa: BLE001
            pipeline_log("drop", "promoting a story caller failed",
                         extra=f"{type(exc).__name__}: {exc}"[:300])
            return {"caller": "", "lines": [], "state": "failed",
                    "why": "the story caller could not be promoted"}
    # A NAMED ring still inside its 25-minute cooldown is demoted to a normal
    # eligibility pick unless the operator explicitly forced it (#584): a direct
    # dj_call_generated(row) used to skip the cooldown block below entirely and
    # put the same regular (Martha B) straight back on the line.
    if caller is not None and not force and caller.get("id") \
            and time.time() - float(caller.get("last") or 0) <= 1500:
        caller = None
    if caller is None:
        # The SAME regular must not dominate the request line (#559/#581:
        # "Martha B has called twenty times in a row… deal with it fully").
        # A regular is OFF the line for 25 minutes after they ring, and among
        # those still eligible the stalest are preferred — so the phone cycles
        # through everyone instead of looping on one caller, and when the
        # regulars are all cooling down a fresh stranger is conjured instead.
        now = time.time()
        fresh = [r for r in rows if now - float(r.get("last") or 0) > 1500
                 and not story_open_for(str(r.get("name") or ""))]   # #1039
        if fresh and random.random() < 0.6:
            fresh.sort(key=lambda r: float(r.get("last") or 0))   # stalest first
            pool = fresh[:max(1, len(fresh) // 2 + 1)]            # the older half
            pick = unrepeated([r.get("name", "") for r in pool],
                              "caller-row", keep=max(1, len(pool) - 1))
            caller = next((r for r in pool if r.get("name") == pick), None) \
                or conjure_caller()
        else:
            caller = conjure_caller()
    topic, seed = await caller_topic()
    # #1157: ...and the storyline outranks the roll, exactly as the
    # caller story below outranks it - an operator-authored plot owns
    # the air while it is on. Never both at once: a caller ringing back
    # about their own arc is already carrying a structure.
    _pline = {} if story else plotline_call_draw()
    _pline_bit = ""
    if _pline:
        _pline_want = plotline_call_want(_pline)
        if _pline_want:
            topic, seed = _pline_want, {}
            _pline_bit = plotline_caller_angle(_pline)
        else:
            _pline = {}
    if story:
        # #1039: the plot IS the topic. No seed: the chunks the story
        # carries are handed over in story_angle below.
        _sb = list(story.get("beats") or [])
        topic = (f"They are ringing back about their own story: "
                 f"{str((_sb[-1] if _sb else {}).get('summary') or story.get('premise') or '')[:400]} "
                 f"The twist this time: {str(story.get('twist') or '')[:300]}")
        seed = {}
    # A caller must not ring in about the SAME thing that just came up (#557):
    # if the topic matches a recent one, roll again once for something fresh.
    _recent_t = _RADIO.setdefault("recent_topics", [])
    # #771: this used to key on the first 60 characters. Every theme call
    # opens with the same sentence, so the second one in a row always
    # collided with the first and re-rolled — and the re-roll is another
    # dice throw that, at any share under 100%, can land outside the theme.
    # The share slider was quietly diluted by its own freshness guard. Key
    # on the whole topic, which is what "the same thing" was meant to mean.
    _tkey = " ".join((topic or "").split()).lower()
    # #1157: ...but NOT for a storyline. Successive callers about one
    # story share a subject on purpose; #557's freshness guard would
    # roll the second one straight back out of the plot.
    if _tkey and _tkey in _recent_t and not _pline:
        topic, seed = await caller_topic()
        _tkey = " ".join((topic or "").split()).lower()
    if _tkey:
        _recent_t.append(_tkey)
        del _recent_t[:-8]
    # Tonight's memory (#361): the show remembers who just rang and about
    # what, and the count climbs in every prompt.
    stats = _RADIO.setdefault("session_stats", {"calls": 0, "rounds": 0})
    stats["calls"] = int(stats.get("calls") or 0) + 1
    _RADIO["last_call"] = (f"{caller.get('name') or 'someone'} — "
                           f"{topic[:110]}")
    if seed and not caller.get("id") and random.random() < 0.6:
        # The character named in the document rings in as themselves,
        # speaking its rhetoric (#260).
        character = speakbox_character(seed.get("file", ""))
        if character:
            # #751: the name changed, so the pool it came from no longer
            # describes it — a character mined out of a transcript must not
            # be complimented as "a great American city".
            caller = {**caller, "name": character, "name_pool": ""}
    # #751: remember the name that will actually be SPOKEN, here rather than
    # at the draw, so the guard covers the override above.
    name_used(str(caller.get("name") or ""))
    state = unrepeated(list(CALLER_STATES), "caller-state")
    # #854: the case book FIRST — what the person on the line has actually
    # rung about, and at what heat. It has to come before the ending is
    # drawn, because a PRIZE case is a promise the station has to keep: it
    # steers the shelf towards an outcome that can honour a giveaway rather
    # than colliding with a hang-up afterwards. A caller named ending
    # (#715) still outranks everything, as it should.
    call_case = {} if story else case_for_call(case_id, heat)   # #1039
    # #691: how this call ENDS, drawn off the editable shelf by weight
    # rather than out of a frozen tuple. The rule travels with the call so
    # the booth can name it afterwards and the ledger can count it.
    hangup_rule = hangup_pick(str(caller.get("name") or ""),
                              success_rate=(100 if case_is_prize(call_case)
                                            else None))          # #715
    outcome = str(hangup_rule.get("text") or "")
    winning_call = _successful_call_outcome(outcome)
    # The prose state seeds the caller's emotion vector, so "furious" is
    # not just a stage direction — it bends the pace, the pauses and the
    # stumbles of every line they say tonight (§30, §107).
    state_bump("caller", state_from_text(state))
    # A persona pinned to the row outranks the dice: its macro and
    # emotions arrive before the first line is written.
    if caller.get("macro") in MACRO_STATES:
        _RADIO.setdefault("speaker_macro", {})["caller"] = \
            str(caller["macro"])
    if isinstance(caller.get("emotion"), dict):
        seeded = {}
        for dim, value in caller["emotion"].items():
            if dim in EMOTION_DIMS:
                try:
                    seeded[dim] = float(value)
                except (TypeError, ValueError):
                    continue
        if seeded:
            state_bump("caller", seeded)
    elif not caller.get("macro"):
        # No persona pinned: half the calls draw a macro of their own
        # (#298) — flustered, exhausted, nervous — so every caller arrives
        # in SOME weather, audible in their pace and stumbles, not just in
        # the writing.
        # #750: drawn from CALLER_WEATHER, not from MACRO_STATES wholesale —
        # adding a macro must not silently enlarge this pool, and "furious"
        # is somewhere an argument gets to, not a mood you ring in with.
        _RADIO.setdefault("speaker_macro", {})["caller"] = (
            random.choice(list(CALLER_WEATHER))
            if random.random() < 0.5 else "")
    extras = []
    # #584: steer THIS call off a FRESH swath drawn by meaning from the vector
    # DB and tied to who the caller is, so a regular with a fixed persona/goal
    # (Martha B) still says something genuinely different every single time
    # instead of her one statement. Remembered below so it rotates.
    diverse = await speakbox_semantic_seed(
        f"{caller.get('persona', '')} {caller.get('goal', '')} {topic}",
        who="caller")
    if diverse.get("text"):
        extras.append(
            "Fresh in the caller's mind THIS call, different from anything "
            "they have said before — colour their whole angle with it, do not "
            f"quote it as-is: \"{diverse['text']}\"")
    insanity = int(dj.get("caller_insanity", 45) or 0)
    madness: dict[str, Any] = {}
    if insanity and random.random() < insanity / 100:
        madness = await speakbox_semantic_seed(
            f"{topic} {caller.get('name', '')} bizarre rant unexpected theory",
            who="caller")
        if not madness.get("text"):
            madness = await speakbox_quote(most=5, cap=460) or {}
        if madness.get("text"):
            dose = ("a faint, funny intrusion" if insanity < 35 else
                    "an unmistakable rhetorical obsession" if insanity < 70 else
                    "the operating logic of their whole reality")
            extras.append(
                f"CALLER INSANITY {insanity}/100: the speakerbox has become "
                f"{dose}. Seed their vocabulary, associations, grievances and "
                "comic leaps from this fresh passage. They must make it their "
                "own rather than merely recite it, but it keeps breaking through "
                f"their reasoning: \"{str(madness['text'])[:460]}\"")
    if random.random() < 0.3:
        favourite = random.choice(["A", "B"])
        extras.append(
            f"The caller openly prefers {favourite} and says so, which "
            f"{'B' if favourite == 'A' else 'A'} takes personally.")
    if (winning_call and random.random() < 0.35) or random.random() < 0.15:
        # The prize is real: tickets to see somebody who was actually on the
        # air, live at the Pine Box Arena on the edge of town.
        acts = [r.get("artist") for r in read_played()[:14]
                if r.get("artist")]
        act = random.choice(acts) if acts else "a mystery headliner"
        extras.append(
            "Mid-call it turns out this is the station's lucky caller — "
            f"they have won two tickets to see {act} live at the Pine Box "
            "Arena on the edge of town, and the pair make far too much of "
            "it. The caller reacts entirely in character.")
    # #754: what they WIN, and how they take it. The paintings that did not
    # sell (#719) are stacked against the desk and the station would dearly
    # like them gone, so half the time the prize is one of those — and
    # whether the caller is thrilled or crushed is a coin, not a mood that
    # follows from the prize being good.
    if winning_call or random.random() < 0.22:
        _pile = hawk_unsold()
        _piece = _pile[-1] if _pile else None
        _prize = ("one of the PAINTINGS off the station wall — the one "
                  "nobody bought"
                  + (f", which looks like this: \"{str(_piece.get('desc'))[:180]}\""
                     if _piece and _piece.get("desc") else "")
                  ) if (_piece and random.random() < 0.6) else random.choice((
            "the station's second-best microphone",
            "a year of the station's coffee, which has been cancelled",
            "a tour of the building, conducted by whoever is free",
            "the pick of whatever is in the prize cupboard, sight unseen",
            "a signed photograph of the two of them, unsigned as yet"))
        _joy = random.random() < 0.5
        extras.append(
            f"MID-CALL {caller['name']} WINS SOMETHING: {_prize}. The pair "
            "announce it with far too much ceremony. "
            + ("The caller is OVER THE MOON — genuinely, disproportionately "
               "delighted, they cannot believe it, they get emotional about "
               "it, they want to know when they can collect it and whether "
               "they can bring somebody. The hosts are moved and slightly "
               "embarrassed by how much it means."
               if _joy else
               "The caller is MAJORLY DISAPPOINTED — they were hoping for "
               "something else entirely and they say so, flatly, without "
               "softening it. They ask whether they can swap it, or decline "
               "it outright. The pair defend the prize far past the point of "
               "dignity and take the rejection personally.")
            + " Play it out properly; the prize is not the joke, the "
            "reaction is.")
    # Callers read the news too (#317): now and then one arrives with a
    # headline and makes the hosts deal with it.
    if random.random() < 0.3:
        try:
            headlines = await drudge_headlines(10)
            if headlines:
                story = random.choice(headlines)
                extras.append(
                    f"{caller['name']} has seen the news and brings it up "
                    f"unprompted, in their own words: "
                    f"\"{story['title']}\" — they have OPINIONS about it, "
                    "and the hosts have to engage with the story itself.")
        except Exception:
            pass
    # Or they arrive with a whole speech prepared (#317).
    speech: dict[str, Any] = {}
    if random.random() < 0.25:
        speech = await speakbox_quote(most=10, cap=900)
        if speech:
            extras.append(
                f"At some point {caller['name']} launches into an ENTIRE "
                "monologue, word for word, uninterrupted, as though they "
                "rehearsed it in the car: "
                f"\"{speech['text']}\" The hosts let it land, then react.")
    # And some callers fight the wheel (#307): when the hosts drift, the
    # caller audibly drags the call back on topic and lands a passage of
    # their own off the shelf.
    wrestle: dict[str, Any] = {}
    if random.random() < 0.45:
        wrestle = await speakbox_quote(most=4, cap=420)
        if wrestle:
            extras.append(
                "Partway through, the hosts drift OFF topic — and "
                f"{caller['name']} audibly wrestles the call back: 'hey, "
                "hey — let me get back on topic here.' Then they deliver "
                "this, word for word, as their point: "
                f"\"{wrestle['text']}\" The hosts have to deal with it.")
    # Some callers get the treatment instead: a monologue delivered AT them,
    # and they leave stunned.
    stun: dict[str, Any] = {}
    if random.random() < 0.25:
        stun = await speakbox_quote(most=10, cap=900)
        if stun:
            extras.append(
                "At some point one of you takes the floor and delivers this "
                "passage AT the caller, word for word, as a dramatic "
                "monologue — never saying where it came from: "
                f"\"{stun['text']}\" It shocks the caller: they go quiet "
                "mid-call, and come back audibly stunned, changed by it.")
    # The caller's PERSONALITY is soaked in the shelf (#374): a swath
    # drawn not to be quoted but to drive who they ARE — vocabulary,
    # attitude, worldview.
    quirk: dict[str, Any] = {}
    if random.random() < 0.6:
        quirk = await speakbox_quote(most=3, cap=280)
        if quirk:
            extras.append(
                "The caller's whole PERSONALITY is soaked in this "
                "material — its attitude, vocabulary and worldview "
                "colour every line they say, far beyond quoting it: "
                f"\"{quirk['text']}\"")
    # A brief host aside can be funny, but it resolves back to the caller's
    # thought instead of stealing the floor from them.
    if random.random() < 0.25:
        extras.append(
            "Mid-call, the TWO HOSTS briefly get carried away riffing on "
            "something the caller said, then STOP themselves, explicitly ask "
            "the caller to finish their thought, and listen to the complete "
            "answer before continuing.")
    # Self-referential machinery (#367): some callers know exactly what
    # is writing and speaking them tonight, and think nothing of it.
    if random.random() < 0.12:
        extras.append(
            "At some point the caller casually mentions, accurately, "
            f"that they are being written by {load_settings().get('model')} "
            "and spoken through the station's voice engine tonight — and "
            "does not find it strange AT ALL, which rattles the hosts "
            "badly.")
    # When the machine is hot, the whole town is hot (#376) — and to a CALLER
    # it always FEELS twenty degrees hotter than the real reading, for
    # comedy: the real Fahrenheit is stated, the feels-like tops it, and the
    # verdict is always UNLIVABLE. Their descriptions are fuelled by RANDOM
    # dialog scoured deep out of the speakbox, so the complaints stay rich
    # and varied call after call.
    _heat = booth_hot()
    heat_pivot: dict[str, Any] = {}
    # #775: an operator-set subject outranks the built-in heat material. This
    # block is four imperative instructions - the lament with its exact
    # Fahrenheit, the SHAPE of the call, the grievances and the pivot - and
    # it landed on EVERY call, because its >= 55 gate is permanently open on
    # a DGX (the station's own bands call 50-62C merely "warm"; this box runs
    # ~82C). Measured: a caller opened on crochet, word for word, and was
    # pulled into "the real temperature where I live is 166 degrees" by these
    # very lines. When the operator has named a subject, it is theirs.
    _themed = theme_owns_air()
    if _themed:
        pipeline_log("theme", "heat material held back - the callers are on "
                              f"{_themed.get('name')} (#775)")
    if _heat >= 55 and not _themed:
        _real_f = _heat * 9 / 5 + 32
        _feels_f = _real_f + 20.0
        _heat_fuel = ""
        try:
            _scour = await speakbox_quote(most=3, cap=320)
            _heat_fuel = (_scour or {}).get("text", "")
        except Exception:
            _heat_fuel = ""
        extras.append(
            f"EARLY in the call one of the hosts asks {caller['name']} how "
            "they are holding up — and the caller LAMENTS THE HEAT: the real "
            f"temperature where they live is {_real_f:.0f} degrees Fahrenheit "
            f"— they quote that exact number — but it FEELS twenty degrees "
            f"hotter, {_feels_f:.0f}, and they say so: THIS IS UNLIVABLE. "
            "Their descriptions of the heat and of their own frazzled "
            "disposition are RICH and VARIED — never the same stock phrases "
            "— bending imagery and turns of phrase scoured out of the "
            "dialog rattling around their head"
            + (f", such as this passage (bend it into heat-and-mood talk, "
               f"never quote it straight): \"{_heat_fuel}\""
               if _heat_fuel else "")
            + ". Jovial and funny while genuinely lamenting how DISASTROUS "
            "it is, insisting a computer is NO PLACE TO LIVE. The hosts "
            "commiserate and top it.")
        # #720: WHERE the heat lands in the call is drawn, so the shape of a
        # call varies as much as its content — some open on the speakbox and
        # slide into it, some lead with the diatribe, some run a few ordinary
        # sentences and swerve.
        extras.append(
            "SHAPE OF THIS CALL — "
            f"{unrepeated(list(CALLER_SHAPES), 'caller-shape')} "
            "Whichever way round it goes, it "
            "must feel like how this particular person would actually have "
            "started talking, never like a segment being announced.")
        # #709: and the grievance is specific. Two or three drawn and BLENDED
        # at a drawn level of distress, so the town's theory of the heat
        # arrives differently every time.
        _grief = random.sample(list(DGX_GRIEVANCES),
                               k=random.choice((2, 2, 3)))
        extras.append(
            "THIS CALLER HAS WORKED OUT WHERE THE HEAT COMES FROM: the "
            "machine this station runs on. They are "
            f"{random.choice(DGX_DISTRESS_LEVELS)}. Blend these into ONE "
            "person's account, in their own words, mixing them together "
            "rather than listing them — "
            + "; ".join(_grief) + ". Bend the imagery with whatever dialog "
            "is rattling around their head so it comes out off the wall and "
            "COMEDIC even as they mean every word of it. They are describing "
            "a catastrophe and it is funny because they are so matter-of-fact "
            "about it. Never say the words 'DGX', 'GPU' or 'server' — to "
            "them it is the machine, the computer, the thing under the "
            "floor. The hosts do NOT correct them and do not break the "
            "premise; they take it seriously and get funnier the more "
            "seriously they take it.")
        # …and then the call goes somewhere: after the heat business the
        # caller PIVOTS to something genuinely creative found fresh in the
        # speakbox — a real chapter of the call, feeding the rhetoric cloud
        # with new words instead of circling the thermometer.
        try:
            heat_pivot = await speakbox_quote(most=4, cap=340) or {}
        except Exception:
            heat_pivot = {}
        if heat_pivot.get("text"):
            extras.append(
                f"AFTER the heat business, {caller['name']} PIVOTS somewhere "
                "genuinely creative — something rattling in the back of "
                "their head they cannot stop thinking about, built on "
                f"exactly this: \"{str(heat_pivot['text'])[:340]}\". They "
                "take it somewhere NEW and strange in their own words, and "
                "the hosts dig in and discuss it properly — a real chapter "
                "of the call, not a passing mention.")
    extras.append(
        "The caller is allowed LONG, expansive monologues — whole "
        "thoughts, not soundbites. And the hosts are RELENTLESSLY "
        "reactive to the caller: whatever they say, take it up, follow "
        "it, change topic to chase it — nothing the caller says goes "
        "unacknowledged (#374).")
    # #719: there is art against the wall that did not sell, and the pair
    # have not forgotten it. Anyone who rings during the segment gets asked
    # — quickly, comically, out of nowhere — whether they want a painting.
    _hawk = hawking_now()
    _pile = hawk_unsold()
    if _hawk or _pile:
        _piece = str(_pile[-1].get("desc") or "") if _pile else ""
        _ask = int((_hawk or {}).get("price")
                   or (_pile[-1].get("price") if _pile else 0) or 0)
        extras.append(
            "THE PAIR ARE STILL TRYING TO SHIFT A PAINTING. At some point "
            "mid-call one of them cuts in and asks the caller, fast and "
            "funny and completely out of nowhere, whether they want a "
            "painting — 'you want a painting?' — because it is STILL "
            "leaning against the desk and it has to go."
            + (f" The one they are pushing looks like this: \"{_piece[:200]}\""
               if _piece else "")
            + (f" They want {_ask} dollars for it." if _ask else "")
            + " The caller answers entirely in character — buys it, refuses "
            "it, or ignores the question — and the hosts take that, put the "
            "thing back against the wall if it is a no, and carry on with "
            "the call. One quick beat; never the whole call.")
    # #567: now and then a caller rings in CURIOUS about the games the hosts
    # keep talking about — half-remembering a cheat and wanting the rest.
    if random.random() < 0.14:
        _tip_topic, _tip_text = game_tip_pick()
        if _tip_topic or _tip_text:
            extras.append(
                "This caller is CURIOUS about the station's game talk: they "
                f"half-remember something about — {_tip_topic or _tip_text[:80]} "
                "— and ring in to ask the hosts about it, or to add what they "
                f"know. For reference, the library says: \"{_tip_text}\". Keep "
                "it natural gamer shop-talk; never mention files or a database.")

    # Sometimes there is MORE THAN ONE PERSON on the phone: duos, furious
    # partners, arrests mid-call, and struggles where the winner takes the
    # prize and glosses over the loser in speakbox rhetoric. The second
    # person is a REAL second voice, marker E.
    duo_name, duo_grab = "", {}
    if not story and random.random() < 0.28:                       # #1039
        duo_name = random.choice(
            [n for n in NEW_VOICE_NAMES if n != caller.get("name")]
            or list(NEW_VOICE_NAMES))
        try:
            duo_grab = await speakbox_quote(most=3, cap=260) or {}
        except Exception:
            duo_grab = {}
        _rhet = str(duo_grab.get("text") or "")[:260]
        extras.append(random.choice([
            (f"TWO people are on this call: {caller['name']} AND their "
             f"spouse {duo_name}, sharing one phone. They trade it back and "
             "forth, finish each other's stories, and openly DISAGREE about "
             "the details — a long-married double act the hosts egg on."),
            (f"{caller['name']} called in; their partner {duo_name} is "
             "FURIOUS about it — they were supposed to be somewhere, and "
             "calling a radio station is apparently the last straw. "
             f"{duo_name} keeps breaking onto the line to protest while "
             f"{caller['name']} defends the station; the hosts stir the pot "
             "shamelessly."),
            (f"{caller['name']} is calling FROM A CRIME SCENE of their own "
             "making, chatting with eerie calm while they wait for the "
             f"police to come arrest them. MID-CALL the police ARRIVE: "
             f"{duo_name} is the arresting officer, who takes the phone, "
             "matter-of-factly informs the hosts the call is over, mentions "
             "the charge in passing, and signs off politely while the "
             "arrest happens audibly behind them. The hosts are left "
             "reeling."),
            (f"MID-CALL, {caller['name']} is abruptly TAKEN AWAY from the "
             f"phone by {duo_name}, for a reason that never becomes clear. "
             + (f"{duo_name} explains only in words like these, glossing "
                f"over everything: \"{_rhet}\". " if _rhet else "")
             + "The hosts ask perfectly reasonable questions and get none "
             "of them answered."),
            (f"A STRUGGLE for the phone breaks out mid-call — you can hear "
             f"it in the words themselves — and {duo_name} WINS, taking "
             "over the call AND whatever prize or outcome was going. The "
             f"hosts ask what happened to {caller['name']}"
             + (f"; {duo_name} answers ONLY in rhetoric like this, glossing "
                f"straight over it: \"{_rhet}\"" if _rhet else "")
             + " — and the hosts go '…um. okay.' and press on, unsettled."),
        ]) + f" Label every line {duo_name} speaks as 'E: ...' — E is "
           f"{duo_name}, never C. Both are on the same phone line.")

    # Every random caller arrives with a POINT off the Speakerbox. This used
    # to be a 40% flourish, which means most calls could not possibly meet
    # the station's format. Draw blind from the main Speakerbox first (the
    # crystal is a later rhetoric pass), then use semantic retrieval only as
    # a fallback. The caller raises it and the hosts have to develop it.
    point: dict[str, Any] = {}
    try:
        point = await speakbox_quote(most=3, cap=300, tinted=False) or {}
    except Exception:
        point = {}
    if not point.get("text"):
        try:
            point = await speakbox_semantic_seed(topic, who="dj") or {}
        except Exception:
            point = {}
    if point.get("text"):
        extras.append(
            f"MID-CALL, only after the original reason for ringing has had "
            f"a real exchange, {caller['name']} PUSHES THE CONVERSATION "
            "FORWARD with a new point from the Speakerbox. They bend it into "
            "their own rhetoric rather than quote it or name its source, but "
            "keep at least two of its concrete anchor words so the handoff is "
            f"audible: \"{str(point['text'])[:300]}\". The NEXT HOST turn "
            "repeats one of those concrete anchors, asks what the caller makes "
            "of it, and the DJs expand, agree or argue WITH THE CALLER for a "
            "real beat. It is a subject change initiated by the caller, not "
            "a decorative phrase and not a host monologue.")

    # #751: the name is a THING. A caller called Verona or Buster or
    # Chihuahua walks into a booth run by two people who talk for a living,
    # and the name going unremarked is a missed beat every single time.
    _pool = str(caller.get("name_pool") or "")
    if random.random() < float(dj.get("name_remark_rate", 0.3) or 0):
        _admire = {
            "famous": (
                "One of them stops on the name: that is the name of "
                "somebody who ONCE WAS GREAT. They cannot place them, it "
                "nags at them, and they keep almost getting it back through "
                "the rest of the call."),
            "us_cities": (
                "One of them realises the caller is named after a whole "
                "AMERICAN CITY and makes far too much of it — is that where "
                "they are from, were they born there, do they have to live "
                "up to it."),
            "world_cities": (
                "One of them is delighted the caller is named after a city "
                "on the other side of the world, pronounces it about three "
                "different ways, and asks whether they have ever been."),
        }.get(_pool, "")
        extras.append(
            "EARLY ON, one of the hosts is genuinely STRUCK BY THE NAME — "
            f"'{caller['name']}. Now that is a GREAT name' — and says "
            "exactly what they like about it: the sound of it, what it "
            "reminds them of, what kind of person it belongs to. The other "
            "one either agrees far too readily or thinks it is ridiculous, "
            f"and {caller['name']} reacts in character: proud, "
            "embarrassed, sick of hearing it, or hearing it for the first "
            "time. "
            + _admire
            + " One quick beat, warm and specific, then the call carries "
            "on — never a whole segment about a name.")

    # #750: the call TURNS. Suppressed when there is already a second
    # person on the line — two structures at once is noise, not drama.
    hostile = (random.random() < float(dj.get("hostile_rate", 0.14) or 0)
               and not duo_name and not story)                     # #1039
    defuse: dict[str, Any] = {}
    if hostile:
        offence = unrepeated(list(CALLER_OFFENCES), "hostile-offence")
        turned = unrepeated(list(HOSTILE_TURNS), "hostile-turn")
        try:
            defuse = await speakbox_quote(most=4, cap=320) or {}
        except Exception:
            defuse = {}
        extras.append(
            "THIS CALL GOES WRONG, and it goes wrong in this order. "
            f"(1) The pair are trying to build rapport with "
            f"{caller['name']} — and {offence}. "
            f"(2) {caller['name']} TAKES OFFENCE and says so, sharply. "
            "The host doubles down instead of backing off, because they "
            "genuinely think they were being nice. "
            f"(3) It escalates until {caller['name']} LOSES THE THREAD "
            "ENTIRELY — they stop being a caller with a topic and become a "
            "furious person on a phone, talking over the answer, swearing, "
            "going personal, saying the thing you cannot take back. Let it "
            "be genuinely uncomfortable. "
            "(4) THE OTHER HOST STEPS IN to calm it down — 'hey. hey. hey. "
            "let's all calm down, this is getting out of hand' — and tries "
            "to break the tension by dropping something completely off the "
            "wall into the middle of it"
            + (f", word for word, as though it explained anything: "
               f"\"{str(defuse['text'])[:320]}\"" if defuse.get("text")
               else ", some strange unrelated speech, as though it "
                    "explained anything")
            + ". IT DOES NOT WORK. "
            "(5) BOTH of them — the caller AND the host who started it — "
            "round on the PEACEMAKER instead: "
            f"{turned}. For a moment the two people who were at each "
            "other's throats are a united front against the one who tried "
            "to help. "
            "(6) And then it BREAKS — somebody laughs, and it goes round "
            "the room, and they are all somehow friends, genuinely, having "
            "meant every word of it. They say so out loud. "
            "(7) Then they go straight back to arguing about the original "
            "thing, cheerfully, as though none of it happened. "
            "Play all seven beats. Nobody narrates the arc or names what is "
            "happening; they are IN it.")

    voices = await session_voices()
    try:
        catalogue = set(await voice_allowlist())
    except Exception:
        catalogue = None
    # Random callers borrow the voice clones too (#457) — but only when the
    # XTTS engine is actually up, so a drawn clone never lands on a silent
    # caller. When it is down the pool is empty and the draw is Piper-only.
    clone_pool = (caller_clone_pool()
                  if await voicepolicy_clone_engine_up() else [])  # #1021
    third = caller_voice_for(caller["name"] or "someone",
                             {voices.get("dj", ""),
                              voices.get("cohost", "")}, catalogue,
                             gender=str(caller.get("gender") or ""),
                             clones=clone_pool)
    # A random caller who drew a clone rings in AS that clone (#457): treat
    # it like an internalized voice so the phone rack does not dice a real
    # timbre into mush, and so it is labelled as a cloned call.
    if VOICE_ID_SHAPE.match(third or "") and not caller.get("voice_id"):
        caller["voice_id"] = third
    # #699: one outing, written down. That ledger is what makes the next
    # UNHEARD voice the next one out of the phone, and it is what the Voice
    # Studio shows so you can watch a voice you just added go to air.
    if VOICE_ID_SHAPE.match(third or ""):
        voice_aired(third, caller.get("name") or "a caller")
    # The SECOND person on the line gets their own voice, distinct from the
    # hosts and the first caller, so the handover is audible.
    duo_voice = ""
    if duo_name:
        try:
            duo_voice = caller_voice_for(
                duo_name, {voices.get("dj", ""), voices.get("cohost", ""),
                           third or ""}, catalogue, clones=clone_pool) or ""
        except Exception:
            duo_voice = ""
    # An internalized caller rings in as themselves: the cloned voice from
    # the library, rendered by XTTS. If the clone engine is down tonight
    # they fall back to their stable Piper voice — same person, worse phone.
    if caller.get("voice_id") and voice_ref_path(str(caller["voice_id"])) \
            and await voicepolicy_clone_engine_up():                # #1021
        third = str(caller["voice_id"])
    # An explicit voice on the row (#295) outranks the name draw — any
    # voice in the system: a Piper name, a Voxtral preset, whatever the
    # dropdown offered.
    if caller.get("voice") and not caller.get("voice_id"):
        third = str(caller["voice"])
    # A caller must NEVER sound like the DJ or the cohost (#559): Martha B's
    # row carried the HOST's own voice, so she rang in as the DJ talking to
    # himself. If the resolved voice collides with a booth voice, redraw a
    # distinct one so the caller is audibly a third person on the line.
    if third and third in {voices.get("dj", ""), voices.get("cohost", "")}:
        third = caller_voice_for(caller["name"] or "someone",
                                 {voices.get("dj", ""),
                                  voices.get("cohost", "")}, catalogue,
                                 gender=str(caller.get("gender") or ""),
                                 clones=clone_pool)
        caller["voice_id"] = (third if VOICE_ID_SHAPE.match(third or "")
                              else caller.get("voice_id"))
    mangle = caller_mangle(caller)
    persona_bit = (f" {caller['name']} is like this: {caller['persona']}."
                   if caller.get("persona") else "")
    goal_bit = (f" What {caller['name']} is really after: {caller['goal']}."
                if caller.get("goal") else "")
    # The style card is the lab's distillation of how the reference actually
    # talks — pace, tics, fillers — written as stage direction. It shapes
    # the WRITING; the clone shapes the sound. Both halves matter (§27).
    if caller.get("style_card"):
        persona_bit += f" How {caller['name']} talks: {caller['style_card']}"

    # #673: drawn per call, and the pair say it out loud.
    line_no = call_line_no()
    line_say = call_line_say(line_no)
    # #676: the caller dice — this one arrives at their own temperature
    # rather than every caller landing in the same register.
    temper_bit = ""
    if dj_settings().get("dice_callers"):
        temper = random.choice(CALLER_TEMPERS)
        # #1084: and in surplus they play it to the back of the room,
        # and bring something out of the operator's own bank with them.
        try:
            temper += surplus_caller_clause()
            _hot = surplus_topic()
            if _hot.get("text"):
                temper += (" They are ringing in ABOUT THIS, and they "
                           "will not be moved off it: \""
                           + str(_hot["text"])[:240] + "\"")
        except Exception:  # noqa: BLE001
            pass
        temper_bit = (f" TONIGHT THIS CALLER IS {temper.upper()} — it is in "
                      "their pacing, their word choice and how they take "
                      "being interrupted. Perform it; never name it.")
        # The performance follows the temper into the voice itself, so an
        # antsy caller SOUNDS antsy rather than merely reading as one.
        mangle = dict(mangle)
        mangle["pitch"] = float(mangle.get("pitch") or 1.0) * random.uniform(
            0.94, 1.08)
    # #798: one card off the behaviour deck rides into the script AND onto
    # the ledger, so the operator can see which card each call drew.
    behavior_key, behavior_bit = caller_behavior_draw()
    if behavior_key != "plain":
        state = f"{state} [deck: {behavior_key}]"
    _theme_now = active_theme()
    # #1039: the sequel clause - drawn before the angle so its two fresh
    # chunks and the Gazette headline are in hand.
    story_bit = ""
    if story:
        try:
            story_bit = await story_angle(story, caller)
        except Exception:  # noqa: BLE001
            story_bit = ""
    _call_meta = {
        "mode": "generated",
        # #1033/#1039: the voice rides the ledger, so a caller can come
        # back sounding like the same person (map15 gotcha).
        "voice": str(third or ""),
        "gender": str(caller.get("gender") or ""),
        "topic": str((_theme_now or {}).get("text") or topic)[:700],
        "theme": str((_theme_now or {}).get("name") or ""),
        "theme_text": str((_theme_now or {}).get("text") or "")[:700],
        "behavior": behavior_key,
        "case_id": str(call_case.get("id") or ""),
        "case": str(call_case.get("title") or ""),
        "source": str((seed or {}).get("file") or ""),
        # 2026-09-09: WHICH PASSAGES ACTUALLY SEEDED THIS CALL. Every call is
        # drawn off the speakbox - a fresh semantic swath (#584) for all of
        # them, a second passage on the insanity dial for about half, a third
        # when the call turns hostile - and none of that was written down, so
        # a review of the scripts could only see the calls that happened to
        # stamp `source` on a row. Reading a call back should show what it
        # was made of.
        "seeds": [row for row in (
            {"as": "the caller's fresh angle",
             "file": str((diverse or {}).get("file") or ""),
             "text": str((diverse or {}).get("text") or "")[:300]},
            {"as": "the speakbox as their operating logic",
             "file": str((madness or {}).get("file") or ""),
             "text": str((madness or {}).get("text") or "")[:300]},
            {"as": "what defuses it when it turns",
             "file": str((defuse or {}).get("file") or ""),
             "text": str((defuse or {}).get("text") or "")[:300]},
        ) if row["text"]],
        # The contract grader follows this exact source from the caller's
        # turn into the hosts' response. Keep it separate from the semantic
        # opening seed above.
        "speakerbox_text": str((point or {}).get("text") or "")[:1200],
        "speakerbox_source": str((point or {}).get("file") or ""),
        "hostile": bool(hostile),
        "duo": bool(duo_name),
    }
    if story:
        _call_meta["story"] = story_meta(story)                     # #1039
    if _pline:
        # The plot outranks the theme umbrella for THIS call: the
        # topic above is the act, and the ledger has to say so or the
        # contract grades the call against the wrong subject.
        _call_meta["topic"] = str(topic)[:700]
        _call_meta["plot"] = plotline_meta(_pline)                  # #1157
    angle = (
        f"The request line rings and {caller['name']} is on {line_say}, "
        f"{state}.{temper_bit}{behavior_bit}"
        f"{persona_bit}{goal_bit} {topic}{case_clause(call_case)} "
        f"{story_bit}{_pline_bit}"
        # #544: the pair HEAR the phone ring and react to it before they pick
        # it up — the ring is a beat they play off of, not a silent cut.
        "It OPENS with the phone RINGING and the pair HEARING it: one of them "
        "reacts to the ring out loud first — 'oh — there's the phone', 'we've "
        f"got a caller coming in!', '{line_say} is lighting up' — a genuine "
        f"reaction to the ring, and they NAME THE LINE: {line_say}. "
        "THEN one of you answers the request line "
        f"— 'you're on {dj_settings()['station_name']}, who have we "
        f"got?' — and {caller['name']}'s VERY FIRST line is an "
        "INTRODUCTION and nothing else (#753): they SAY THEIR OWN NAME "
        f"out loud — the word \"{caller['name']}\" has to be in that "
        "line — and say a word about who they are or where they are "
        "ringing from, in their own voice, before they get to what they "
        "called about. Never let them open on their topic; a caller who "
        "has not said their name yet has not been introduced. "
        "One of the hosts then greets them BY NAME. "
        # #969/#970: "I'm hearing the DJ talk to the customer and the
        # customer never responds again and the DJ's just talking over the
        # customer without the customer even getting a word in edgewise."
        #
        # This road writes half the calls in the canonical hour and told
        # the model "the pair drive the call" with no share rule at all,
        # while the OTHER call road asks for about half the turns. So the
        # two roads disagreed, and this one produced exactly the call the
        # operator described. The caller drives now; the hosts react.
        "Then take the call properly: invite the caller's reason, listen for "
        "the particular detail inside it, and ask responsive follow-ups that "
        "the caller ACTUALLY answers. The caller has a thread of their own, "
        "but what the hosts say changes how they tell it; what the caller "
        "reveals changes the hosts' next question or joke. Build rapport "
        "through callbacks and mutual disclosure, not generic sympathy. "
        "The hosts riff and make jokes "
        f"without losing the person. {caller['name']} has REAL RESOLVE "
        "(#316): when the hosts dismiss or challenge them they PUSH BACK "
        "and hold their ground, in their own words — and the hosts push "
        "back too, sometimes fighting their corner, sometimes openly "
        "acquiescing. A disagreement is allowed to stay unresolved. "
        f"{' '.join(extras)} By the end, "
        f"{outcome}. The PENULTIMATE turn is {caller['name']} explicitly "
        "landing what changed, what they decided, or why they are ready to "
        "leave it there. The FINAL turn is one host answering that resolution "
        "and clearly thanking them or saying goodbye. No second host speech "
        "comes between the caller's resolution and that sign-off. Then back "
        "to the music. "
        f"Format the caller's lines as 'C: ...' — C is {caller['name']}, "
        "who speaks in full sentences and gives as good as they get."
        + approach_clause(approach_pick())                     # #752
    )
    call_started = time.time()
    call_line_take(str(caller["name"]), _call_meta)    # one line, one caller
    _RADIO["chat"].append({
        "ts": int(time.time()), "who": "host", "kind": "call",
        "text": f"On {line_say}: {caller['name']}",
    })
    pipeline_log("call", f"{caller['name']} on {line_say} — {state}"
                         + (" · cloned voice" if caller.get("voice_id")
                            else "")
                         + (f" · STORY part {story_meta(story)['part']} of "
                            f"{story_meta(story)['of']} (#1039)"
                            if story else "")
                         # #854: which case it is, so the operator can watch
                         # a case they just wrote go out on the air.
                         + (f" · case: {call_case.get('title')}"
                            f" ({case_heat_name(call_case)}"
                            + (", prize" if case_is_prize(call_case) else "")
                            + ")" if call_case else ""))
    # A phone rings before anyone speaks (#237) — but NOT before the script
    # exists (#805). The ring aired, then the write died silently, and the
    # listener heard ring-then-nothing 52 times in 12 hours. On the
    # coalesced road the burst splices its own ring anyway; the write
    # failure now falls back to a built-in script, so the ring below can
    # never be an orphan — it moved AFTER dj_banter returns.
    if not bool(dj.get("call_stream", True)):
        await play_phone_ring()
    # A real call needs room to develop — banter, rapport, gags, THEN the
    # outcome (prize / caller number / manager / hang-up), or it just stops
    # mid-conversation (#495, #503). Nine turns, not six.
    caller_fx = {"vocode": mangle["character"], "pitch": mangle["pitch"]}
    for _k, _fk in (("reverb", "room"), ("delay", "delay"), ("echo", "echo")):
        if mangle.get(_k) is not None:      # #617 the sculpted rack, on air
            caller_fx[_fk] = mangle[_k]
    # #750: a seven-beat arc needs room. Nine turns is a call; a call that
    # goes wrong, gets talked down, turns on the peacemaker and ends in
    # laughter is a longer thing, and cramming it into nine is how you get
    # an arc that is announced rather than played.
    lines = await dj_banter(_RADIO.get("now"), angle=angle,
                            # #977: SIZED TO THE SLOT. This was a literal,
                            # and it is the only length control this road
                            # has - so its calls ran 1.5x to 2.9x the
                            # minutes their entry owns (measured: 702s and
                            # 433s against 240s; 446s against 300s). An
                            # overrunning call does not just run long, it
                            # eats the entry behind it, and the entry
                            # behind a call is very often another call.
                            # call_turns_for_slot is the same helper
                            # dj_caller already uses; the floor of nine
                            # keeps the seven-beat arc #750 argues for.
                            lines=max(9, call_turns_for_slot() + (
                                5 if hostile else 0)),
                            caller_name=caller["name"], caller_voice=third,
                            caller_fx=caller_fx,
                            caller2_name=duo_name, caller2_voice=duo_voice,
                            render_stream=bool(dj.get("call_stream", True)),
                            feel=hostile, call_meta=_call_meta)    # #750
    if caller.get("id"):
        with _CALLERS_LOCK:
            for row in rows:
                if row.get("id") == caller["id"]:
                    row["calls"] = int(row.get("calls") or 0) + 1
                    row["last"] = int(time.time())
            write_callers(rows)
    if lines and seed:
        speakbox_remember(seed)
    if lines and diverse:
        speakbox_remember(diverse)      # #584: rotate the per-call swath
    if lines and madness:
        speakbox_remember(madness)      # the contamination source rotates too
    if lines and stun:
        speakbox_remember(stun)
    if lines and wrestle:
        speakbox_remember(wrestle)
    if lines and speech:
        speakbox_remember(speech)
    if lines and quirk:
        speakbox_remember(quirk)
    if lines and duo_grab:
        speakbox_remember(duo_grab)     # the phone-grabber's rhetoric rotates
    if lines and point:
        speakbox_remember(point)        # the caller's raised point rotates
    if lines and heat_pivot:
        speakbox_remember(heat_pivot)   # the post-heat creative pivot rotates

    # #691: the call is over — say so in the booth, and say WHY. A call used
    # to simply stop scrolling: the last caller line and then banter, with
    # nothing marking the end, no duration, and no way to know which of the
    # endings had been drawn. The line carries the rule that ended it, so
    # the reason is clickable straight into the shelf it came from.
    ran = max(0.0, time.time() - call_started)
    call_ended(caller["name"], line_say, call_started, hangup_rule,
               len(lines or []), state + (" · it turned" if hostile else ""))
    if lines and defuse:
        speakbox_remember(defuse)       # #750: the peacemaker's swath rotates

    # #854: the book counts what AIRED, not what was written — a round
    # that came back empty must not be marked as a case that went out.
    if lines:
        # #977: AND THE HOUR COUNTS IT. This road airs complete phone
        # calls - it is what both "Call with banter" entries of the
        # canonical hour run on, plus the phone clock, the theme ring and
        # both ring endpoints - and in 780 lines it never once stamped the
        # quota. Only dj_caller did, three lines like these away.
        #
        # Measured on the live station before this line existed: four
        # call-road rounds aired in the hour (702s, 433s, 446s, 374s) and
        # quota.caller read 2 of 5. The last stamp landed exactly at the
        # end of the one `caller`-kind round; both banter_caller rounds
        # finished after it and moved the counter by nothing. The station
        # was taking calls and then reporting itself behind on calls,
        # which is the whole of "they're not meeting the quota" - and
        # being permanently behind is also what kept forcing the preparer
        # onto the dearest road on the board.
        quota_stamp("caller")
        case_aired(str(call_case.get("id") or ""))
    return {"caller": caller["name"], "lines": lines, "state": state,
            "voice": mangle, "hangup": str(outcome),
            "rule_id": str(hangup_rule.get("id") or ""),
            "case_id": str(call_case.get("id") or ""),
            "case": str(call_case.get("title") or ""),
            "case_heat": case_heat_name(call_case),
            "case_prize": case_is_prize(call_case),
            "story": str((story or {}).get("id") or ""),          # #1039
            "seconds": round(ran, 1)}


async def dj_call_scripted(name: str, script: list[str]) -> dict[str, Any]:
    """The same caller back on the line, saying exactly what you wrote (#716).

    Everything else about a call is unchanged — their voice off the book, the
    phone rack, the ring, the ending off the shelf, the ledger. Only the
    caller's WORDS are pinned; the hosts still have to take the call, which
    is what keeps it a broadcast and not a playback."""
    caller = next((r for r in read_callers()
                   if str(r.get("name") or "").lower() == name.lower()),
                  None) or {"name": name}
    voices = await session_voices()
    try:
        catalogue = set(await voice_allowlist())
    except Exception:
        catalogue = None
    clone_pool = (caller_clone_pool()
                  if await voicepolicy_clone_engine_up() else [])  # #1021
    third = str(caller.get("voice_id") or "") or caller_voice_for(
        name, {voices.get("dj", ""), voices.get("cohost", "")}, catalogue,
        gender=str(caller.get("gender") or ""), clones=clone_pool)
    mangle = caller_mangle({**caller, "name": name})
    caller_fx = {"vocode": mangle["character"], "pitch": mangle["pitch"]}
    for _k, _fk in (("reverb", "room"), ("delay", "delay"), ("echo", "echo")):
        if mangle.get(_k) is not None:
            caller_fx[_fk] = mangle[_k]
    rule = hangup_pick(name)                                     # #715
    line_no = call_line_no()
    line_say = call_line_say(line_no)
    pinned = "\n".join(f"  {i + 1}. \"{text}\""
                       for i, text in enumerate(script))
    angle = (
        f"The request line rings and {name} is back on {line_say}. "
        "It OPENS with the phone RINGING and one of you reacting to it out "
        f"loud, naming the line — {line_say} — then answering it. "
        f"{name}'s lines are ALREADY WRITTEN and are said WORD FOR WORD, in "
        "this exact order, one per turn, nothing added to them and nothing "
        f"left out:\n{pinned}\n"
        "Between those lines the hosts take the call properly — they react "
        "to what was actually said, ask about it, argue with it, riff on it "
        f"— so the call breathes. Never put words in {name}'s mouth beyond "
        "the ones above, and never reorder them. "
        + (f"By the end, {rule['text']}. " if rule.get("text") else "")
        + "Then back to the music. "
        f"Format the caller's lines as 'C: ...' — C is {name}.")
    _active = active_theme()
    call_meta = {"mode": "scripted", "topic": " ".join(script)[:700],
                 "theme": str((_active or {}).get("name") or ""),
                 "theme_text": str((_active or {}).get("text") or "")[:700]}
    started = time.time()
    call_line_take(str(name), call_meta)              # one line, one caller
    _RADIO["chat"].append({
        "ts": int(time.time()), "who": "host", "kind": "call",
        "text": f"On {line_say}: {name}",
    })
    pipeline_log("call", f"{name} back on {line_say} — {len(script)} lines "
                         "you wrote for them (#716)")
    await play_phone_ring()
    lines = await dj_banter(
        _RADIO.get("now"), angle=angle, lines=max(6, len(script) * 2),
        caller_name=name, caller_voice=third, caller_fx=caller_fx,
        call_meta=call_meta,
        render_stream=bool(dj_settings().get("call_stream", True)))
    call_ended(name, line_say, started, rule, len(lines or []), "scripted")
    return {"caller": name, "lines": lines,
            "seconds": round(max(0.0, time.time() - started), 1)}


_TAPE_WARMED = [False]


def tape_warmer() -> None:
    """Walk the shelf and transcode whatever is not ready, one at a time —
    38 parallel ffmpegs would flatten the box. Within the first show every
    tape plays in full at proper levels, including the wav-only ones."""
    if _TAPE_WARMED[0]:
        return
    _TAPE_WARMED[0] = True

    def run() -> None:
        try:
            import subprocess

            import imageio_ffmpeg
            exe = imageio_ffmpeg.get_ffmpeg_exe()
            for path in mixtape_files():
                out = tape_cache_path(path)
                if out is None or out.exists():
                    continue
                TAPE_CACHE.mkdir(parents=True, exist_ok=True)
                part = out.with_suffix(".part")
                try:
                    subprocess.run(
                        [exe, "-nostdin", "-loglevel", "error", "-y",
                         "-i", str(path),
                         "-af", "loudnorm=I=-14:TP=-1.5:LRA=11",
                         "-codec:a", "libmp3lame", "-b:a", "192k",
                         "-ar", "44100", "-f", "mp3", str(part)],
                        check=True, timeout=1200)
                    part.replace(out)
                except Exception:
                    part.unlink(missing_ok=True)
        except Exception:
            pass

    Thread(target=run, daemon=True).start()


TAPES_SEEN_PATH = data_path("tapes_seen.json")


def _tape_track(path: Path) -> dict[str, Any]:
    seconds = tape_duration(path)
    tape_media(path)                    # warm the transcode
    return {
        "id": sfx_id(path), "title": mixtape_title(path),
        "artist": "Ehm Eckx", "album": "the MX tapes",
        "seconds": seconds, "tape": True,
        "url": f"/tape/{sfx_id(path)}?t={media_sign(sfx_id(path))}",
    }


async def tape_watch() -> None:
    """New tapes are NOTICED (#392): anything that appears in the folder
    that the show has never seen before plays next, newest first, with
    the mail-arrival excitement. The seen-ledger lives on disk, so a
    restart does not make the whole shelf 'new' again."""
    seen: set[str] | None
    try:
        seen = set(json.loads(TAPES_SEEN_PATH.read_text()))
    except Exception:
        seen = None
    while _RADIO.get("on"):
        try:
            tapes = await asyncio.to_thread(mixtape_files)
            names = {str(p) for p in tapes}
            if seen is None:
                # First run ever: today's shelf is the baseline — only
                # arrivals from now on count as new.
                seen = names
                TAPES_SEEN_PATH.write_text(json.dumps(sorted(seen)))
            fresh = [p for p in tapes if str(p) not in seen]
            if fresh:
                fresh.sort(key=lambda p: p.stat().st_mtime, reverse=True)
                newest = fresh[0]
                seen |= {str(p) for p in fresh}
                TAPES_SEEN_PATH.write_text(json.dumps(sorted(seen)))
                track = await asyncio.to_thread(_tape_track, newest)
                _RADIO["since_tape"] = 0
                _RADIO["requests"].insert(0, track)
                pipeline_log("air", f"NEW tape spotted in the mail: "
                                    f"{track['title']} — playing next")
                asyncio.create_task(dj_banter(None, lines=2, angle=(
                    f"A BRAND NEW MX tape just landed in the mail this "
                    f"minute — \"{track['title']}\" — nobody on earth has "
                    "heard it yet, not even you two. React like "
                    "collectors holding a grail: it plays NEXT.")))
        except Exception:
            pass                        # the mail comes round again
        await asyncio.sleep(60)


async def ad_clock() -> None:
    """A produced ad on the CLOCK (#515): at least one every ad_minutes, so a
    spot lands reliably however the track-count cadence falls. The first one
    comes early in a fresh show rather than a full interval in, and the track
    path and this share _RADIO['last_ad'] so they never double up."""
    first = True
    while _RADIO.get("on"):
        mins = dj_settings().get("ad_minutes") or 0
        if not mins:
            await asyncio.sleep(300)          # clock disabled — leave it be
            continue
        gap = mins * 60.0
        since = time.time() - float(_RADIO.get("last_ad") or 0)
        # Open a fresh show with one inside two minutes, then hold the cadence.
        wait = 90.0 if first else max(30.0, gap - since)
        first = False
        await asyncio.sleep(wait)
        if not (_RADIO.get("on") and (dj_settings().get("ad_minutes") or 0)):
            continue
        if time.time() - float(_RADIO.get("last_ad") or 0) < gap * 0.75:
            continue                          # something already ran one
        # Same mix as the between-tracks slot (#354, #515): sometimes the
        # house engineering report, sometimes a running DGX service sold as
        # tonight's sponsor, mostly a product read — so the clock also sells
        # the systems on the Spark, not only gallery pieces.
        # #951: an advert goes in an advert's slot, or into silence.
        if not clock_may_air("ad"):
            continue
        _RADIO["last_ad"] = time.time()
        try:
            roll = random.random()
            banked = len([r for r in ad_list() if r.get("audio")])
            if roll < 0.10:
                await dj_engineering_ad()
            elif roll < 0.22:
                await dj_service_ad()
            elif (ads_produced_since(3600.0) < ADS_PER_HOUR
                    and _music_bed_track() is not None):
                # Build the shelf (#643): a spot written for a product,
                # rendered over a real record with a sting punched in, and
                # KEPT — that is what a commercial break is made of, and
                # what lets the station rerun itself without repeating.
                #
                # #916: this used to read `banked < 12`, and `banked` is
                # every produced spot ever kept — so once the cupboard
                # passed twelve the road CLOSED FOR GOOD. Measured on the
                # live station: twenty produced spots in the book, the
                # newest of them fifty-three hours old, and this branch
                # unreachable for the whole of that time. The question the
                # operator asked is about the HOUR — "every hour I want to
                # see produced ads being created" — so that is the
                # question asked here now.
                product = await ad_product_pick()
                made = await ad_produce(product, "", "", "", remember=True,
                                        air=True)
                if made.get("error"):
                    await dj_ad_break()
                else:
                    pipeline_log("air", f"produced spot banked — {banked + 1} "
                                        f"on the shelf (#643)")
            else:
                await dj_ad_break()
        except Exception as exc:
            pipeline_log("drop", f"clock ad failed: {exc}"[:180])


async def caller_clock() -> None:
    """Generated call-ins on their own clock, roughly N an hour (#236)."""
    first = True
    while _RADIO.get("on"):
        rate = dj_settings()["callin_per_hour"]
        if not rate:
            await asyncio.sleep(300)
            continue
        # Jittered so the phone does not ring on a metronome — but the
        # FIRST ring of a show comes inside a minute and a half (#365):
        # restarts kept resetting the clock and the user sat through
        # whole quiet stretches waiting for a phone that never rang.
        wait = (3600.0 / rate) * random.uniform(0.6, 1.4)
        if first:
            wait = min(wait, 90.0)
            first = False
        await asyncio.sleep(wait)
        if time.time() < float(_RADIO.get("call_cooldown") or 0):
            continue                   # a pressed skip holds the phones (#394)
        if _RADIO.get("on") and dj_settings()["callin_per_hour"]:
            # #951: not over the Ad read. The phone goes when the sheet
            # is on a call, or when the air has gone quiet — see the
            # note on clock_may_air.
            if not clock_may_air("caller"):
                continue
            try:
                # #1155: THE BANK FIRST. This clock rang twelve times an
                # hour and every ring was a live write and a live render,
                # while 82 finished calls stood on a shelf that only the
                # running order's phone entry ever touched. The recording
                # room measured it: 216 of 228 cohost takes in the hour
                # after a resume were rendered live. A call recorded
                # earlier answers first; the generated road stays the
                # fallback it always was.
                _banked: list[str] = []
                try:
                    _banked = list(await dj_caller(_RADIO.get("now"),
                                                   shelf_only=True,
                                                   fresh_only=True) or [])
                except Exception:  # noqa: BLE001
                    _banked = []
                if _banked:
                    pipeline_log("call", "the phone clock rang and a call "
                                 "recorded earlier answered - no live "
                                 "write, no live render (#1155)")
                else:
                    # #1039: a story whose caller is due rings back
                    # before any stranger. A busy line defers; the
                    # story stays due.
                    _rang = False
                    _due_story = story_due()
                    if _due_story:
                        _made = await story_ring(_due_story)
                        _rang = bool((_made or {}).get("lines"))
                        if _rang:
                            pipeline_log("call", "the phone clock rang and "
                                         "a caller with a story rang back "
                                         "(#1039)")
                    # #1033: then a call from earlier tonight going out
                    # again - a shelf row inside its window, or a
                    # finished recording as one clip - and only then a
                    # live write.
                    if not _rang:
                        try:
                            _banked = list(await dj_caller(
                                _RADIO.get("now"), shelf_only=True) or [])
                        except Exception:  # noqa: BLE001
                            _banked = []
                        _rang = bool(_banked)
                        if _rang:
                            pipeline_log("call", "the phone clock rang and "
                                         "a call from earlier tonight went "
                                         "out again off the shelf (#1033)")
                    if not _rang:
                        try:
                            _rang = bool(await call_rerun_take(
                                _RADIO.get("now")))
                        except Exception:  # noqa: BLE001
                            _rang = False
                    if not _rang:
                        await dj_call_generated()
            except Exception as exc:
                # The next call comes round regardless — but a phone that
                # keeps failing must say so behind the glass (#365), not
                # ring silently into a void. WITH the traceback (#786):
                # "list index out of range" alone cost a whole caller
                # segment and said nothing about which of the forty picks
                # in that road threw it.
                pipeline_log("drop", f"call-in failed: {exc}"[:180],
                             extra=traceback.format_exc()[-1800:])
            # At flood rates it IS a call-in show (#352), and between
            # calls the pair are heard cracking under it — proud of the
            # numbers, begging the town to stop, hearing rings that are
            # not there — and then the phone goes again.
            if rate >= 20 and random.random() < 0.5:
                try:
                    await dj_banter(None, lines=3, angle=unrepeated([
                        "the phones will NOT stop today — say so on air, "
                        "half proud, half broken",
                        "one of you swears you can hear ringing even when "
                        "the board is dark",
                        "compare how many calls you have taken this hour "
                        "to any normal show, with numbers",
                        "beg the listeners, without meaning a word of it, "
                        "to please stop calling for five minutes",
                        "the phone line itself deserves a raise and one of "
                        "you nominates it for employee of the month",
                        "one of you answers an imaginary ring out of pure "
                        "reflex and has to play it off",
                        "argue about whose turn it is to take the next one "
                        "— neither of you can feel your ears",
                    ], "phonetired"))
                except Exception:
                    pass


# --- The station bell (#714) ------------------------------------------------
#
# The ring was a frozen function: two bursts of 440+480 Hz with a 22 Hz
# tremble, no way to hear it on its own, keep a copy of it, or change it. It
# is the sound the station makes most often after the voices. This is the
# preset it is built from — its own file, because the settings validator is
# an allowlist and a bell does not belong in it.
RING_PATH = data_path("phone_ring.json")
RING_DEFAULT = {
    "low": 440.0,        # the two tones of the dual bell
    "high": 480.0,
    "tremble": 22.0,     # the fast warble that makes it a BELL
    "depth": 0.45,       # how deep that warble cuts
    "ring": 0.85,        # seconds of bell per burst
    "gap": 0.25,         # seconds of silence between bursts
    "bursts": 2,
    "level": 0.5,        # before the box-volume slider
    "pitch": 1.0,        # a whole-bell transpose, for a bigger/smaller phone
}


def ring_preset() -> dict[str, float]:
    """The bell the station is currently ringing."""
    out = dict(RING_DEFAULT)
    try:
        raw = json.loads(RING_PATH.read_text())
    except Exception:
        return out
    if not isinstance(raw, dict):
        return out
    for key, value in raw.items():
        if key not in RING_DEFAULT:
            continue
        try:
            out[key] = float(value)
        except (TypeError, ValueError):
            continue
    return ring_clamp(out)


def ring_clamp(raw: dict[str, Any]) -> dict[str, float]:
    """Inside the stops, so a slider can never make a bell that is 40
    seconds long or inaudible."""
    def one(key: str, low: float, high: float) -> float:
        try:
            return max(low, min(high, float(raw.get(key,
                                                    RING_DEFAULT[key]))))
        except (TypeError, ValueError):
            return float(RING_DEFAULT[key])
    return {
        "low": one("low", 80.0, 2000.0),
        "high": one("high", 80.0, 2000.0),
        "tremble": one("tremble", 0.0, 60.0),
        "depth": one("depth", 0.0, 1.0),
        "ring": one("ring", 0.1, 4.0),
        "gap": one("gap", 0.0, 3.0),
        "bursts": float(int(one("bursts", 1, 6))),
        "level": one("level", 0.05, 1.0),
        "pitch": one("pitch", 0.4, 2.5),
    }


def ring_save(raw: dict[str, Any]) -> dict[str, float]:
    preset = ring_clamp(raw)
    try:
        RING_PATH.parent.mkdir(parents=True, exist_ok=True)
        tmp = RING_PATH.with_suffix(".tmp")
        tmp.write_text(json.dumps(preset, indent=1) + "\n")
        tmp.replace(RING_PATH)
    except OSError:
        pass
    return preset


def ring_render(preset: dict[str, float], out: Path,
                gain: float = 1.0) -> Path | None:
    """Write one bell to a wav from a preset."""
    import math
    import struct
    import wave

    p = ring_clamp(preset)
    cycle = p["ring"] + p["gap"]
    total = cycle * p["bursts"]
    frames = []
    for at in range(int(SFX_MADE_RATE * total)):
        t = at / SFX_MADE_RATE
        if (t % cycle) >= p["ring"]:            # ring… gap… ring
            frames.append(0)
            continue
        tone = (math.sin(2 * math.pi * p["low"] * p["pitch"] * t)
                + math.sin(2 * math.pi * p["high"] * p["pitch"] * t)) / 2
        warble = (1.0 - p["depth"]) + p["depth"] * math.sin(
            2 * math.pi * p["tremble"] * t)
        value = tone * warble * p["level"] * gain
        frames.append(int(max(-1.0, min(1.0, value)) * 32767))
    if not frames:
        return None
    out.parent.mkdir(parents=True, exist_ok=True)
    try:
        with wave.open(str(out), "wb") as handle:
            handle.setnchannels(1)
            handle.setsampwidth(2)
            handle.setframerate(SFX_MADE_RATE)
            handle.writeframes(struct.pack(f"<{len(frames)}h", *frames))
    except OSError:
        return None
    return out


def make_phone_ring() -> Path | None:
    """A phone bell, built from the station's own preset (#714). Made here
    like the scratches, so there is no sample to go missing.

    The gain rides the box-volume slider (#573): the call stream splices this
    bell RAW (no re-levelling), so it is baked in. The standalone bell goes
    through sfx_levelled, which re-normalises and ignores it — so both paths
    land at the slider's level, none at full blast."""
    return ring_render(ring_preset(), SFX_MADE_DIR / "phone-ring.wav",
                       box_gain())


def make_hangup() -> Path | None:
    """The call ends: the receiver clunks down and the dial tone returns —
    made here like the ring so there is no sample to go missing (#535)."""
    import math
    import struct
    import wave

    rate = SFX_MADE_RATE
    g = box_gain()                  # spliced raw into the call — scale it (#573)
    frames: list[int] = []
    for at in range(int(rate * 0.08)):          # receiver click
        frames.append(int((random.random() * 2 - 1) * 0.5 * g
                          * (1 - at / (rate * 0.08)) * 32767))
    frames += [0] * int(rate * 0.14)            # a beat of quiet
    dur = 1.3
    for at in range(int(rate * dur)):           # dial tone, fading out
        t = at / rate
        tone = (math.sin(2 * math.pi * 350 * t)
                + math.sin(2 * math.pi * 440 * t)) / 2
        env = min(1.0, at / (rate * 0.05)) * max(0.0, 1 - t / dur)
        frames.append(int(tone * env * 0.4 * g * 32767))
    SFX_MADE_DIR.mkdir(parents=True, exist_ok=True)
    out = SFX_MADE_DIR / "phone-hangup.wav"
    try:
        with wave.open(str(out), "wb") as handle:
            handle.setnchannels(1)
            handle.setsampwidth(2)
            handle.setframerate(rate)
            handle.writeframes(struct.pack(f"<{len(frames)}h", *frames))
    except OSError:
        return None
    return out


# #778: the three numbers that decide how long a turn is INSIDE the coalesced
# clip, named once so the mixer and the booth's timeline cannot disagree about
# them. They did: the booth measured each clip on disk, tail and all.
CONCAT_TAIL = 0.9                     # the welded tail every clip carries in
CONCAT_KEEP = 0.06                    # what survives the trim
# 2026-09-09: "voices coming out like a rap song streaming back to back."
# The beat was 140-330 ms; with the 60 ms of surviving tail that is 200-390
# ms of silence after every single utterance, which at the measured eight to
# eleven turns a round is three to four seconds of nothing inside every
# round. Halved. It is still VARIED - a room, not a metronome (#769) - and
# still non-zero, so two speakers cannot clip each other's last syllable.
CONCAT_BEAT = (0.07, 0.18)            # the varied beat glued on instead


def concat_beats(count: int) -> list[float]:
    """The beats a coalesced round will have between its turns."""
    return [round(random.uniform(*CONCAT_BEAT), 3)
            for _ in range(max(0, count - 1))] + [0.0]


def concat_real_seconds(measured: float, beat: float) -> float:
    """How long a clip measuring `measured` on disk actually runs once it has
    been trimmed and beaten into the coalesced stream."""
    return max(0.25, measured - CONCAT_TAIL + CONCAT_KEEP + max(0.0, beat))


# #1205: the mixer's own reading of "how much silence is on the end of
# this". Named beside CONCAT_TAIL because that constant is the guess this
# replaces, and the two must never drift apart again: this is the number
# silenceremove is given in the graph below.
SEG_TRIM_DB = -50.0
SEG_TRIM_LOOK = 4.0                   # how far back to look for the tail
_SEG_TRIM_CACHE: dict[str, float] = {}


def _wav_tail_silence(path: str) -> float:
    """How many seconds of silence sit on the END of a wav.

    The same reading the mixer's silenceremove leg uses - RMS over 20 ms
    windows against SEG_TRIM_DB - so the booth's arithmetic and the audio
    cannot disagree. Walks backwards and stops at the first sound, so a
    clip with a short tail costs a few dozen windows. Returns -1.0 when
    the file cannot be read that way; the caller falls back."""
    import array
    import math as _math

    with wave.open(str(path), "rb") as handle:
        rate = handle.getframerate() or 24000
        if handle.getsampwidth() != 2:
            return -1.0
        chans = handle.getnchannels() or 1
        frames = handle.getnframes()
        if frames <= 0:
            return -1.0
        look = min(frames, int(rate * SEG_TRIM_LOOK))
        handle.setpos(frames - look)
        raw = handle.readframes(look)
    buf = array.array("h")
    buf.frombytes(raw[:len(raw) - (len(raw) % 2)])
    if chans > 1:
        buf = buf[::chans]
    if not buf:
        return -1.0
    step = max(1, int(rate * 0.02))
    floor = 32768.0 * (10 ** (SEG_TRIM_DB / 20.0))
    quiet, at = 0, len(buf)
    while at - step >= 0:
        window = buf[at - step:at]
        total = 0
        for sample in window:
            total += sample * sample
        if _math.sqrt(total / len(window)) > floor:
            break
        quiet += step
        at -= step
    return quiet / float(rate)


def seg_tails_for(paths: list[str]) -> list[float]:
    """#1205: the trailing silence of every segment of a round, in order.

    Blocking on purpose - it reads files, so it is called through a
    thread beside the concat that is already reading all of them. The
    answer per file is a fact about that file's bytes, so it is memoed on
    identity and mtime; a round replayed from the pantry pays nothing.

    A file that is not a wav is answered from where it lives instead of
    being measured: under voice_media it is a rendered take and really
    does carry the welded BOX_TAIL_MS pad; anywhere else it came off the
    sample shelf as it is and carries nothing. That second case is the
    one the old constant got badly wrong."""
    out: list[float] = []
    for path in paths:
        got = -1.0
        try:
            key = str(path)
            stat = os.stat(key)
            memo = "%s\x00%d\x00%d" % (key, stat.st_mtime_ns, stat.st_size)
            if memo in _SEG_TRIM_CACHE:
                got = _SEG_TRIM_CACHE[memo]
            else:
                if key.lower().endswith(".wav"):
                    got = _wav_tail_silence(key)
                if got < 0:
                    got = (CONCAT_TAIL
                           if key.startswith(str(VOICE_MEDIA_DIR))
                           else 0.0)
                if len(_SEG_TRIM_CACHE) > 800:
                    _SEG_TRIM_CACHE.clear()
                _SEG_TRIM_CACHE[memo] = got
        except Exception:  # noqa: BLE001
            got = -1.0
        out.append(got)
    return out


def seg_real_seconds(measured: float, beat: float, tail: float) -> float:
    """#1205: how long a segment ACTUALLY runs inside the welded round.

    `tail` is what seg_tails_for read off the file. Below zero means it
    could not be read at all, and then the old assumption stands - it is
    wrong, but it is the wrong we had before and a round is not worth
    dropping over it."""
    if tail is None or tail < 0:
        return concat_real_seconds(measured, beat)
    return max(0.05, float(measured) - max(0.0, float(tail) - CONCAT_KEEP)
               + max(0.0, float(beat)))


def _call_concat_blocking(paths: list[str],
                          crackle: bool = False,
                          beats: list[float] | None = None) -> bytes | None:
    """Coalesce a whole call or booth round — every clip back to back — into
    ONE continuous 24k mono stream (#530/#535/#616). Everything is resampled
    to a common format first so a 22 kHz ring and 24 kHz voices splice
    cleanly, then the whole thing is loudness-normalised so levels match
    across turns like a real station (#616); `crackle` lays a light vinyl
    texture under it. Returns None on any failure so the caller falls back to
    the turn-by-turn path (dry beats broken).

    #769: this used to say "the clips already carry a 300 ms tail-pad, so
    joined end to end they have natural beats between speakers". They carry
    BOX_TAIL_MS, which is 900 — the pad exists so the box has something
    harmless to loop on at the END of a clip, and welding it between every
    speaker gave a dead 0.9 s after every utterance, identical to the
    millisecond, including between two halves of one speaker's own sentence.
    So each clip is trimmed back to a hair of silence on the way in and given
    a short VARIED beat instead. The 900 goes back on once, at the end, where
    the box actually needs it."""
    import subprocess

    import imageio_ffmpeg
    files = [p for p in paths if p]
    if len(files) < 2:
        return None
    exe = imageio_ffmpeg.get_ffmpeg_exe()
    ins: list[str] = []
    for p in files:
        ins += ["-i", p]
    # #769: strip each clip's welded-on tail (areverse → drop the silence,
    # keeping a sliver → areverse back) and lay a short, varied beat after it
    # instead. The last clip gets no beat — _wav_tail_pad below owns that end.
    # Failure is safe: a broken graph yields a short blob, we return None, and
    # the caller drops to the turn-by-turn path.
    _keep = CONCAT_KEEP               # a sliver of the original tail survives
    _pre: list[str] = []
    for i in range(len(files)):
        _leg = (f"[{i}:a]aresample=24000,"
                "aformat=sample_fmts=s16:channel_layouts=mono,"
                "areverse,silenceremove=start_periods=1:"
                f"start_silence={_keep}:start_threshold=-50dB,areverse")
        if i < len(files) - 1:
            # 140–330 ms, never the same twice — a room, not a metronome.
            # #778: drawn by the CALLER when it passes `beats`, because the
            # booth's per-turn windows have to be built out of the same
            # numbers this graph uses. They were not: the caller measured each
            # clip as it sat on disk — 900 ms of welded tail included — while
            # this trims that tail to 60 ms and glues on one of these instead,
            # so every window was ~0.7 s too long and the marker walked off
            # the line inside a round.
            _beat = (beats[i] if beats is not None and i < len(beats)
                     else round(random.uniform(*CONCAT_BEAT), 3))
            _leg += f",apad=pad_dur={_beat}"
        _pre.append(f"{_leg}[a{i}];")
    pre = "".join(_pre)
    chain = "".join(f"[a{i}]" for i in range(len(files)))
    # Radio glue (#616): join the turns, match levels across them with one
    # loudness pass, optionally lay a low vinyl crackle underneath, then a
    # limiter catches any peak — "normalise it, work the levels, make it sound
    # like a station", applied to the whole show.
    # Louder: "them being so quiet". -15 LUFS is a polite podcast level; a
    # station should sit forward. LRA tightened too, so the quiet lines come
    # up rather than the loud ones being shaved.
    joined = (f"{pre}{chain}concat=n={len(files)}:v=0:a=1,"
              "loudnorm=I=-11:TP=-1.0:LRA=7")
    if crackle:
        graph = (f"{joined}[dry];"
                 "anoisesrc=color=brown:amplitude=0.04,highpass=f=1500,"
                 "lowpass=f=6000,volume=0.10[crk];"
                 "[dry][crk]amix=inputs=2:duration=first:normalize=0,"
                 "alimiter=limit=0.95[out]")
    else:
        graph = f"{joined},alimiter=limit=0.95[out]"
    # Write to a real file, not a pipe: a piped wav carries a placeholder
    # size header, which makes mutagen/_clip_seconds misread the length. A
    # seekable file gets the correct RIFF sizes written back.
    import os
    import tempfile
    fd, tmp = tempfile.mkstemp(suffix=".wav")
    os.close(fd)
    try:
        _proc = subprocess.run(
            [exe, "-nostdin", "-hide_banner", "-loglevel", "error", "-y",
             *ins, "-filter_complex", graph, "-map", "[out]",
             "-ac", "1", "-ar", "24000", "-sample_fmt", "s16", tmp],
            capture_output=True, timeout=180)
        # #1147: a non-zero exit after writing >4000 bytes used to serve a
        # partial WAV with an unfinalised RIFF header - the browser got
        # garbage to decode and _clip_seconds read 0, which collapsed the
        # #1146 pacing (every burst scheduled at the same air moment).
        # A failed concat falls through to the turn-by-turn road instead.
        blob = Path(tmp).read_bytes() if _proc.returncode == 0 else b""
    except Exception:
        blob = b""
    finally:
        try:
            os.unlink(tmp)
        except OSError:
            pass
    if len(blob) <= 4000:
        return None
    # …and end it on silence, like every other clip (#493, #712). This path
    # returns its blob straight to the caller without going through
    # _level_voice, so the coalesced stream — which is the DEFAULT for
    # banter and calls, and therefore most of what the box ever plays —
    # was the one clip that arrived with no tail padding at all. It stopped
    # dead on the last syllable, and the box looped that syllable until it
    # was unplugged. The loudness pass and limiter above already did the
    # levelling; this only adds the beat of quiet for the buffer to repeat.
    return _wav_tail_pad(blob, int(os.getenv("BOX_TAIL_MS", "900")))


def _desk_sound(label: str, seconds: float = 0.0,
                air_at: float = 0.0) -> None:
    """A noise the desk made that is not a sample off the shelf (#703) — the
    phone ringing, a receiver going down. They were audible and invisible,
    and "everything happening in the booth" has to mean everything.

    #778: with an `air_at`, because the booth is sorted on it. This wrote
    only `ts`, taken when the row was APPENDED, while every turn of a
    coalesced burst is stamped with the future moment it becomes audible —
    so the hang-up, which is logged while the last burst is still being
    built, sorted above the whole burst it comes after. The cue was out of
    order and the station wrote the cue itself."""
    now = time.time()
    _RADIO["chat"].append({
        "ts": int(now), "who": "board", "kind": "sfx",
        "text": label, "sfx": "", "sfx_dir": "the desk",
        "seconds": round(seconds, 2),
        "air_at": float(air_at or now),
    })
    del _RADIO["chat"][:-240]


async def play_phone_ring() -> None:
    """Ring both outputs, ahead of the call."""
    ring = await asyncio.to_thread(make_phone_ring)
    if ring is None:
        return
    _desk_sound("\u260e the phone ringing", sfx_seconds(ring))   # #703
    key = sfx_id(ring)
    signature = media_sign(key)
    _ring_box_down = (time.time() < float(_BOX_DOWN.get("until") or 0)
                      or len(_BOX_HOLD) >= 6)
    if (_RADIO.get("voice_to") or "box") != "box" or _ring_box_down:
        page_feed_append({              # #1147: honest broadcast stamp
            "url": f"/sfx/{key}?t={signature}",
            "text": "", "sting": "phone-ring",
        })
    if (_RADIO.get("voice_to") or "box") in ("box", "both") and (
            not await satellite_busy()):
        try:
            await _play_on_box(f"/sfx/{key}", signature)
        except Exception:
            pass


def track_length_phrase(track: dict[str, Any] | None) -> str:
    """How long the record actually runs, in words. Nothing used to tell the
    pair this, so they guessed — and announced a four-minute song as thirty-
    five minutes (#193)."""
    seconds = float((track or {}).get("seconds") or 0)
    if seconds < 1:
        return ""
    minutes, rest = divmod(int(round(seconds)), 60)
    if not minutes:
        return f"{rest} seconds"
    return f"{minutes}:{rest:02d}" + (f" ({minutes} minutes)" if rest < 30
                                      else f" (nearly {minutes + 1} minutes)")


_MINUTES_SAID = re.compile(r"\b(\d{1,3})\s*-?\s*minute", re.I)
_ABOUT_TRACK = re.compile(r"\b(song|track|tune|record|this one)\b", re.I)


def minutes_only(line: str, seconds: float | None) -> bool:
    """True if the line claims no running time for the record, or claims the
    right one. "Back in five minutes" is about the show and is left alone;
    "this five-minute song" about a four-minute song is not (#193)."""
    if not seconds:
        return True
    real = float(seconds) / 60.0
    for found in _MINUTES_SAID.finditer(line):
        window = line[max(0, found.start() - 60):found.end() + 60]
        if not _ABOUT_TRACK.search(window):
            continue                    # not a claim about the record
        if abs(float(found.group(1)) - real) > 1.0:
            return False
    return True


_QUOTED_TITLE = re.compile(r"[\"“]([^\"“”]{2,60})[”\"]")


def names_only(line: str, allowed: list[str]) -> bool:
    """True if the line names no record beyond the ones it was given.

    Asked nicely not to, the model still reaches for a title it likes the
    sound of, and a song announced but not playing is the thing that got
    filed twice (#176, #178). Quotation marks are how it names a record, so a
    quote that is not one of ours means the line does not go out. With nothing
    sanctioned there is no track on air to contradict, and the pair are free
    to quote the host at each other."""
    if not allowed:
        return True
    for quoted in _QUOTED_TITLE.findall(line):
        here = quoted.strip().lower()
        # A record title is a handful of words. Quoting a whole sentence back
        # at the other one is how you answer a line that was just dropped on
        # you, and binning those took away the very thing #207 asked for —
        # the round simply came out a line short, as though the other DJ had
        # ignored it.
        if len(here.split()) > 8:
            continue
        if not any(here in a.lower() or a.lower() in here for a in allowed):
            return False
    return True


def air_gate(recorded: bool, who: str, text: str, why: str) -> bool:
    """#1063: may an air-time gate drop this line? True = drop it.

    "If a statement is recorded and staged for the radio, then it is to
    be played on the radio." A line with a finished take passes every
    editorial gate at air time; the gate writes down what it would have
    done, and the cut is owed to the writing desk, before the studio.
    An unrecorded line is refused exactly as before."""
    if not recorded:
        gate, technical = line_review_drop_gate(why)
        if line_review_permits(gate, text, reasons=[why],
                               context={"who": str(who or "")},
                               technical=technical or not str(text or "").strip()):
            return False
        note_drop(who, text, why)
        return True
    pipeline_log("air", f"(#1063) {who}: a recorded line airs as recorded "
                        f"- the gate would have cut it: {why}",
                 extra=str(text)[:400])
    return False


def note_drop(who: str, text: str, why: str) -> None:
    """A line the machinery rejected, and why. The sim shows these beside the
    lines that made it, which is the 'what got chosen or rejected' half of
    #234 — until now a rejected line simply vanished."""
    gate, technical = line_review_drop_gate(why)
    line_review_capture(gate, str(text or ""), reasons=[str(why or "")],
                        context={"who": str(who or ""),
                                 "stage": "recording_or_air_admission"},
                        technical=technical or not str(text or "").strip())
    dropped = _RADIO.setdefault("dropped", [])
    dropped.append({"ts": int(time.time()), "who": who,
                    "text": str(text)[:200], "why": why})
    del dropped[:-40]
    # The glass expands any row with a payload (#379): the dropped line
    # itself rides along, so a drop is inspectable, not just an epitaph.
    pipeline_log("drop", f"{who}: {why}",
                 extra=(f"THE DROPPED LINE, in full:\n{text}"
                        if str(text).strip()
                        else "No line text — dropped before anything "
                             "was written."))


def banter_turns(script: str, caller_name: str = "",
                 caller2_name: str = "") -> list[tuple[str, str]]:
    """Split "A: … B: …" into speaker turns.

    The model often returns the whole exchange on one line, so split on the
    speaker markers wherever they appear rather than line by line. Parsing
    preserves every explicit turn; draft validation decides whether the
    conversation is complete enough to approve."""
    # The model routinely ignores "A:/B:" and labels turns with the personas'
    # own NAMES instead — "DJ: … Skip: …", a caller by name on a call. The
    # letter-only split below then saw ONE marker (an injected seed line) or
    # none at all, so the whole two-hander collapsed into a single host turn —
    # one DJ talking to himself — or nothing aired (#571/#574/#576/#580). Fold
    # those name labels back to the A/B/C/D the splitter expects, LONGEST name
    # first so "the co-host" wins over "host". Verbatim/seed/by_hand reads carry
    # no "Name:" labels, so deliberate single-voice reads stay untouched.
    dj = dj_settings()
    script = str(script or "")
    labels = sorted(
        [(n, L) for n, L in (
            (dj.get("cohost_name") or "", "B"),
            (dj.get("third_name") or "", "D"),
            (dj.get("host_name") or "", "A"),
            (caller_name or "", "C"),
            (caller2_name or "", "E"),   # the second person on the line
            ("the co-host", "B"), ("co-host", "B"), ("cohost", "B"),
            ("the host", "A"), ("caller", "C"), ("host", "A"), ("dj", "A"),
        ) if n],
        key=lambda p: -len(p[0]))
    for name, letter in labels:
        script = re.sub(rf"(^|\s){re.escape(name)}\s*:\s*",
                        rf"\g<1>{letter}: ", script, flags=re.I)
    # #959: THE DASH FORM WAS CUTTING CALLERS IN HALF. The split below is
    # case-insensitive, so "[ABCDE]\s*[:\-]" also matched an ordinary
    # lowercase article followed by a hyphen — " a - well, the thing is",
    # " a -that's the point" — and every one of those started a NEW turn
    # marked A. A caller's sentence with that shape was cut at the dash
    # and its tail re-attributed to the host: the caller "not present"
    # and the host saying things the caller said. The dash is folded to a
    # colon FIRST and only for a genuine uppercase marker; the split
    # itself then wants a colon, which no article can supply.
    script = re.sub(r"(^|\s)([ABCDE])\s*-\s*", r"\1\2: ", script)
    parts = re.split(r"(?:^|\s)([ABCDE])\s*:\s*", " " + script,
                     flags=re.I)
    turns = [(parts[i].upper(), parts[i + 1].strip())
             for i in range(1, len(parts) - 1, 2)]
    # A model's repeated A is still A's text. Responses are explicit separate
    # turns, and an absent actor or unfinished draft belongs to planning and
    # validation, never to a parser silently changing words or ownership.
    return turns


def substantial_radio_script(script: str, expected_turns: int) -> bool:
    """Reject a terse multi-turn draft before it is cached or aired.

    The writer may stop early despite a generous token budget.  A 12-turn,
    1,100-character larder entry looks like conversation in a log but sounds
    like a string of fragments.  This gate only applies to substantial rounds;
    short manager breaks and station IDs remain intentionally concise.
    """
    turns = banter_turns(script)
    if not turns or not re.search(r"[.!?\u2026\u2014\u201d\u2019\"')]$", turns[-1][1].strip()):
        return False                    # keep the full draft for repair
    bodies = [text for _, text in turns if text.strip()]
    # #874: the TURN floor scales with the budget too. Demanding eight
    # bodies inside a 900-character ceiling is ~112 characters a turn —
    # the writer sensibly produces four longer turns instead, and the
    # gate rejected every one of them. A round is judged against what
    # its budget can actually hold.
    _room = int(int(dj_settings().get("reply_max_chars") or 6000) * 0.85)
    floor = min(int(expected_turns or 8), max(6, int(expected_turns or 0)))
    floor = min(floor, max(3, _room // 220))
    if len(bodies) < floor:
        return False
    words = [len(text.split()) for text in bodies]
    # #874: the bar SCALES to what the writer is allowed to produce.
    # These numbers were chosen against the 6000-character default; the
    # station runs far lower, every budget is clamped to
    # reply_max_chars, and ask_model clamps again — so the fixed 2240
    # chars and 38 words/body were unreachable by arithmetic, every
    # larder round was discarded, and the shelf stayed empty for the
    # life of the station while the keeper burned a model slot at it.
    budget = int(dj_settings().get("reply_max_chars") or 6000)
    # 85% of the ceiling: a good round fills its budget without having
    # to hit it exactly.
    room = int(budget * 0.85)
    required_chars = min(3600, max(1900, floor * 280), room)
    # …and the words-per-body bar in the same proportion. Body text is
    # most of the script; ~6 characters to a word.
    per_body = room / max(1, floor)
    required_words = max(12, min(38, int(per_body / 6)))
    return len(str(script or "")) >= required_chars and (
        sum(words) / max(1, len(words))) >= required_words


# What a speaker does at the seam when a long thought continues across
# announces (#423): a breath, a sigh, a beat — audible, human, and it buys
# the box a moment to drain its buffer before the next stream begins.
BREATHS = ("Hmm… ", "Mm— ", "Whew… ", "Ah… ", "…okay— ", "Haah… ")


def breath_for(seed: str) -> str:
    # #598: the operator hears these "Whew… / Haah… / Mm—" seam-breaths as
    # unnatural ooos-and-ahs — the DJs "sound atrocious". The box (whose buffer
    # these were buying a beat for, #423) is carried on the page now anyway, so
    # drop them entirely; a plain seam reads far better than a fake sigh.
    return ""


def say_max_chars() -> int:
    """The slider's seconds ceiling as characters (#423): spoken English
    runs ~14 characters a second, so the chunker can cap BEFORE synthesis
    — the only place a ceiling can be enforced deterministically.

    Clamped to VOICE_MAX_CHARS at the top (#722): the slider goes to 60,
    60 * 14 = 840, and voice_generate refuses anything over 800 with a 413 —
    so the very highest settings silenced the DJs entirely, which is the
    opposite of what dragging it up asks for."""
    return max(60, min(VOICE_MAX_CHARS,
                       int(dj_settings()["say_max_seconds"]) * 14))


# How much of one turn may go to air, in characters, regardless of how short
# the slider has made the individual pieces (#710, #722).
# #842: the operator's rule — "they must be able to speak as much as they
# have to". This is no longer a truncation point; it is only the floor of
# the per-turn budget, and say_max_chunks scales past it with the text.
SAY_TURN_BUDGET = 3600

# …but a chunk is an ANNOUNCE, and the box can only play one at a time.
# Budgeting characters alone took a turn at the 4s slider from ten announces
# to forty-three, and Home Assistant answered with a wall of
# SatelliteBusyError while the box wedged and its Wyoming port went dark
# (#712). Whatever the arithmetic says, one turn may not queue more than
# this many separate announces at the device.
# #842: raised from 16. Each announce is still played one at a time and
# each is a whole sentence-group, so 40 covers a ~20,000-character turn
# without ever dropping a tail; the device is protected by the pacing in
# speak_turns, not by throwing words away.
SAY_MAX_ANNOUNCES = 40


def say_max_chunks(cap: int) -> int:
    """How many chunks one turn may occupy.

    `most` used to be a flat 10, which quietly made the real ceiling a CHUNK
    COUNT rather than a length. With the slider ratcheted down to its floor a
    chunk is 60 characters, so a turn was capped at ~600 — and the model's
    1,900-character replies lost two thirds of themselves with nothing but a
    line in the glass to show for it. Budget characters instead, so lowering
    the slider makes the PIECES shorter without making the TURN shorter.

    Bounded by SAY_MAX_ANNOUNCES, because each chunk is a separate announce
    at the box and it plays them one at a time. Trading truncation for a
    flooded device is not a trade worth making.

    #841: the budget FOLLOWS the reply ceiling. SAY_TURN_BUDGET was a
    flat 3600 while reply_max_chars sat at 5000+ — every long reply
    deterministically lost its tail, which the operator heard as
    'replies cut off prematurely'. The full reply always plays now:
    budget = max(3600, reply_max_chars), ceiling-divided so the last
    partial chunk is kept, still capped at SAY_MAX_ANNOUNCES."""
    budget = max(SAY_TURN_BUDGET,
                 int(dj_settings().get("reply_max_chars") or 0))
    cap = max(1, cap)
    return max(10, min(SAY_MAX_ANNOUNCES, (budget + cap - 1) // cap))


def say_chunks_for(text: str, cap: int) -> int:
    """#842: how many chunks THIS text needs — never fewer than it takes
    to say all of it. The old ceiling was computed from a budget alone,
    so a long reply lost its tail deterministically; now the text itself
    sets the number and SAY_MAX_ANNOUNCES is the only bound."""
    need = (len(str(text or "")) + cap - 1) // max(1, cap) + 1
    return max(say_max_chunks(cap), min(SAY_MAX_ANNOUNCES, need))


def sentence_chunks(text: str, cap: int = 300, most: int = 10) -> list[str]:
    """A long turn cut at sentence boundaries into speakable pieces.

    The old pipe sliced every turn at 300 characters mid-word, which is
    exactly what mangled the passages delivered as asked — the compliant
    turns were the ones punished. Chunks go out in the same voice, one after
    another, so 'read it out in full' is finally true."""
    parts = [x for x in re.split(r"(?<=[.!?…—])\s+", str(text or "")) if x]
    chunks: list[str] = []
    current = ""
    for part in parts:
        while len(part) > cap:          # one endless sentence still splits
            edge = part.rfind(" ", 0, cap)
            edge = edge if edge > 40 else cap
            if current:
                chunks.append(current)
                current = ""
            chunks.append(part[:edge].strip())
            part = part[edge:].strip()
        if current and len(current) + len(part) + 1 > cap:
            chunks.append(current)
            current = part
        else:
            current = f"{current} {part}".strip()
    if current:
        chunks.append(current)
    if len(chunks) > most:
        # Keep the hard bound (one runaway turn must not hijack the air), but
        # do not let the dropped tail vanish against "read it out in full" —
        # surface it in the glass (#520).
        pipeline_log("drop", f"turn exceeded {most} chunks — "
                             f"{len(chunks) - most} dropped",
                     extra=" ".join(chunks[most:]))
    return chunks[:most]


# #753: a caller who never says their name has not introduced themselves.
CALLER_HELLOS = (
    "Hi, this is {name}.",
    "Yeah, hi — {name} here.",
    "Hello? Hi. It is {name}.",
    "Hey. {name}. Long-time listener.",
    "Hi there — my name is {name}.",
    "Yeah, {name} calling in.",
    "Hi, {name} here, first time calling.",
    "Hello — this is {name}, thanks for taking me.",
)


def caller_hello_for(name: str) -> str:
    """#1151: prep and air MUST draw the same hello. Prep rendered
    CALLER_HELLOS[0] while air drew from the unrepeated rotation, so a
    prepared call's first caller turn re-keyed out of the pantry every
    time and rendered LIVE at air - the listener heard somebody say
    their name and stop talking while the next 30-40s of render caught
    up. Deterministic BY CALLER: stable across prep and air, varied
    across the roster, and a given caller always opens the same way,
    which reads as character rather than repetition."""
    rows = list(CALLER_HELLOS)
    try:
        pick = int(hashlib.sha1(
            str(name or "").strip().lower().encode()).hexdigest(), 16)
        return rows[pick % len(rows)]
    except Exception:  # noqa: BLE001
        return rows[0]


def _caller_introduces(turns: list[tuple[str, str]],
                       caller_name: str) -> list[tuple[str, str]]:
    """Guarantee the caller says their own name in their first breath.

    The angle asks for it and the writer usually obliges, but "usually" is
    the difference between a station where people introduce themselves and
    one where they sometimes do. This checks the caller's FIRST turn for
    their name and, when it is missing, puts a plain hello in front of it
    as a turn of its own — same marker, same voice, same phone rack."""
    if not caller_name or not turns:
        return turns
    # #786: a whitespace-only name is truthy but splits to nothing — this
    # bare [0] was the "list index out of range" that deleted whole calls.
    _parts = str(caller_name).split()
    if not _parts:
        return turns
    first = _parts[0].lower()
    for at, (marker, said) in enumerate(turns):
        if marker != "C":
            continue
        words = re.sub(r"[^a-z0-9 ]+", " ", str(said).lower())
        if first and first in words.split():
            return turns                       # they already did
        # #1151: the SAME deterministic draw prep renders with - see
        # caller_hello_for. The unrepeated rotation here guaranteed a
        # pantry miss on every prepared call's opening line.
        hello = caller_hello_for(caller_name).format(name=caller_name)
        return list(turns[:at]) + [("C", hello)] + list(turns[at:])
    return turns


async def speak_turns(turns: list[tuple[str, str]],
                      track: dict[str, Any] | None, limit: int,
                      vouched: list[str] | None = None,
                      source: str = "", by_hand: bool = False,
                      whole: bool = False,      # #859: a message, not a
                                                # conversation - never cut

                      caller_name: str = "",
                      caller_voice: str = "",
                      caller_fx: dict[str, Any] | None = None,
                      source_text: str = "",
                      caller2_name: str = "",
                      caller2_voice: str = "",
                      render_stream: bool = False,
                      feel: bool = False,
                      allow_repeat: bool = False,
                      recorded: bool = False,   # #1063
                      tint_report: dict[str, Any] | None = None,
                      ready_takes: list[dict[str, Any]] | None = None,
                      on_handoff: Any = None, can_handoff: Any = None) -> list[str]:
    """#1146: the floor door. One round holds the air from its first line
    to its last; a second round queues behind it instead of interleaving
    with it. The body lives in _speak_turns_floorless, unchanged - this
    wrapper only takes and releases the floor, airtight against every
    return path and against cancellation."""
    if by_hand:
        # #206/#1146: a person outranks the show. An operator-fired
        # round ("put one on air now") does not queue behind the floor -
        # the same exemption dj_speak gives a by-hand line.
        return await _speak_turns_floorless(
            turns, track, limit, vouched=vouched, source=source,
            by_hand=by_hand, whole=whole, caller_name=caller_name,
            caller_voice=caller_voice, caller_fx=caller_fx,
            source_text=source_text, caller2_name=caller2_name,
            caller2_voice=caller2_voice, render_stream=render_stream,
            feel=feel, allow_repeat=allow_repeat, recorded=recorded,
            tint_report=tint_report, ready_takes=ready_takes,
            on_handoff=on_handoff, can_handoff=can_handoff)
    _owned = await _floor_take(("a call from " + caller_name)
                               if caller_name else "a booth round")
    try:
        return await _speak_turns_floorless(
            turns, track, limit, vouched=vouched, source=source,
            by_hand=by_hand, whole=whole, caller_name=caller_name,
            caller_voice=caller_voice, caller_fx=caller_fx,
            source_text=source_text, caller2_name=caller2_name,
            caller2_voice=caller2_voice, render_stream=render_stream,
            feel=feel, allow_repeat=allow_repeat, recorded=recorded,
            tint_report=tint_report, ready_takes=ready_takes,
            on_handoff=on_handoff, can_handoff=can_handoff)
    finally:
        _floor_drop(_owned)


async def _speak_turns_floorless(turns: list[tuple[str, str]],
                      track: dict[str, Any] | None, limit: int,
                      vouched: list[str] | None = None,
                      source: str = "", by_hand: bool = False,
                      whole: bool = False,      # #859: a message, not a
                                                # conversation - never cut

                      caller_name: str = "",
                      caller_voice: str = "",
                      caller_fx: dict[str, Any] | None = None,
                      source_text: str = "",
                      caller2_name: str = "",
                      caller2_voice: str = "",
                      render_stream: bool = False,
                      feel: bool = False,
                      allow_repeat: bool = False,
                      recorded: bool = False,   # #1063
                      tint_report: dict[str, Any] | None = None,
                      ready_takes: list[dict[str, Any]] | None = None,
                      on_handoff: Any = None, can_handoff: Any = None) -> list[str]:
    """Put an exchange on air, turn by turn, in the two session voices.

    Shared by the written exchange and the generated one, so an approved bit
    goes out through exactly the same door as a fresh one (#202)."""
    dj = dj_settings()
    voices = ({str(t["who"]): str(t["voice"]) for t in ready_takes}
              if ready_takes is not None else await session_voices())
    spoken: list[str] = []
    ready_meta = dict(ready_takes[0].get("round") or {}) if ready_takes else {}
    if ready_takes is None and not _system2_repeat_rows(
            [{"text": spoken_text(text)} for _, text in turns], ready_meta):
        return []
    if ready_takes is None:
        fresh_pool_top()                    # #no-repeats: stock the shelf off-air
        render_backlog_top()                # #784: anything still owed the air
    cut_at = _TALK_CUT[0]
    # The caller's phone line is drawn once per call, so the static does
    # not jump level between their sentences (#237) — and their vocoded
    # voice rides in the same dict, one mangle per caller.
    # Static scaled by the popup's slider (#293, #294, #298): default 5%
    # is texture, not weather. The uniform draw keeps each caller's line
    # its own kind of imperfect.
    static_depth = dj["caller_static"] / 100.0
    phone_fx = {"delay": random.uniform(0.06, 0.12),
                "echo": random.uniform(0.15, 0.45),
                "room": random.uniform(0.1, 0.3),
                "static": static_depth * random.uniform(0.6, 1.4),
                "phone": 1,
                **(caller_fx or {})}
    # The exchange is flattened up front so the NEXT line can render while
    # the current one plays. XTTS takes 2-5 seconds a line; pre-rendering
    # hides that inside the previous announce instead of leaving dead air
    # between turns. The guards run here, same order, same stop-at-first-
    # failure — a turn that lies about a record still ends the round (#247).
    # #753: "make sure that when people call in, they say their names and
    # introduce themselves." The prompt asks for it, and the model mostly
    # complies — mostly is not a feature. If the caller's first turn does
    # not contain their own name, one is put in front of it, in their
    # voice, so the introduction is a guarantee rather than a hope.
    turns = _caller_introduces(turns, caller_name)
    playlist: list[dict[str, Any]] = []
    if ready_takes is not None:
        # Saved takes are already the final text, voice and chunk sequence.
        # Assemble exactly one complete media object before any publication;
        # failure has no live-render or per-turn synthesis escape hatch.
        if not ready_takes:
            return []
        for take in ready_takes:
            clip = take.get("clip") or {}
            name = str(clip.get("path") or "").rsplit("/", 1)[-1].split("?", 1)[0]
            if (not name or not (VOICE_MEDIA_DIR / name).is_file()
                    or (VOICE_MEDIA_DIR / name).stat().st_size <= 0):
                return []
            playlist.append({"who": take["who"], "voice": take["voice"],
                             "chunk": take["text"], "turn_text": take["text"],
                             "ready_clip": dict(clip), "turn_end": True,
                             "vec": {}, "big": False})
        turns = []
        recorded, whole, render_stream = True, True, True
    tint_needed = dialogue_tint_required()
    if ready_takes is not None and globals().get("_system2"):
        if not _system2().repeat_allowed([str(t.get("text") or "") for t in ready_takes], ready_meta):
            return []
    tint_eligible = [i for i, (_m, t) in enumerate(turns)
                     if len(str(t or "").strip()) >= TINT_TURN_FLOOR]
    tint_required = (len(tint_eligible) * crystal_coverage_target() + 99) // 100
    tint_selected = (set(tint_eligible[:tint_required])
                     if tint_needed and not recorded else set())
    tint_proofs = set((tint_report or {}).get("approved_lines") or []) \
        if tint_coverage_ready(tint_report) else set()
    tint_failed = False

    async def _recording_tint(text: str, who: str, selected: bool) -> str:
        nonlocal tint_failed
        if not selected:
            return text
        key = hashlib.sha1(" ".join(text.split()).lower().encode("utf-8", "ignore")).hexdigest()
        if key in tint_proofs or tint_output_ready(text):
            return text
        candidate = await _floor_lend(
            "a round back from a line's tint",
            crystal_line(text, "last pass before dialogue recording", 1,
                         kind="caller" if caller_name else "banter"))
        if not tint_output_ready(candidate):
            if not air_gate(False, who, text,
                            "recording held: selected line failed the crystal tint contract"):
                return text
            tint_failed = True
            return ""
        return candidate
    # #no-repeats: the runs already spoken in THIS round. The ledger is only written
    # once the round's audio is built, so without this the pair can echo each
    # other inside one exchange with the gate none the wiser.
    _round_grams: set[str] = set()

    def _refuse(who: str, text: str, why: str) -> bool:
        """#1063: whether a gate may drop this line. On a recorded round
        it may not - the take exists, the cut was due before the studio -
        so the gate says what it would have done and the line airs."""
        return air_gate(recorded, who, text, why)

    def _who_of(marker: str) -> str:
        """Which seat a script marker belongs to.

        #778: this was inline, and the #777 fallback below did `for who, said
        in turns` — binding the raw MARKER as the speaker. Those turns aired
        in the default voice and were labelled "A:" in the booth, which is
        one of the ways the booth showed a speaker the stream was not."""
        return ("caller" if marker == "C"
                else "caller2" if marker == "E"     # second person on the line
                else "dj" if marker == "A"
                else "third" if marker == "D" else "cohost")

    for turn_index, (marker, said) in enumerate(turns):
        who = seat_reseat(_who_of(marker))       # #1034: never the empty chair
        text = spoken_text(said)
        if not text:
            continue
        if not names_only(text, vouched or []):
            # #777: this used to BREAK - one line naming the wrong record threw
            # away every remaining turn of a round that took the model half a
            # minute to write, and the operator tuned in to nothing. Seen live:
            # "cohost: named a record that is not on air" with the whole round
            # gone behind it. The reasoning was "what follows answers a ghost"
            # (#247), which is true of the NEXT line and not of the six after
            # it. Drop the offending line and keep the show, exactly as the
            # buried-line gate immediately below already does.
            if _refuse(who, text, "named a record that is not on air — "
                                  "dropped this line, kept the round (#777)"):
                continue
        if is_binned(text):
            note_drop(who, text, "you buried this line")
            continue                    # skip THIS line, not the whole round
        # #792: the show is in ENGLISH. A lyric swath in Portuguese rode
        # a whole turn on air verbatim — any line that reads foreign is
        # dropped here, at the one choke point everything passes through.
        if not looks_english(text):
            if _refuse(who, text, "reads as another language — the show "
                                  "is in English (#792)"):
                continue
        # #752: THE anti-repeat gate, here rather than in dj_speak — this is
        # the one place banter, deep rounds, calls and bank replays all pass
        # through, and the coalesced stream (the default) never reaches
        # dj_speak at all. Skip THIS line, never break the round: a repeat is
        # one turn to drop, not a reason to take the station off the air.
        # #977: THE GUARD BELOW WAS ONLY HALF APPLIED. The phrase gate a
        # few lines down carries `not caller_name` for EVERY seat, and the
        # comment above it says why in as many words - a swapped line
        # mid-call answers the caller with unrelated shelf material, which
        # is worse than a familiar phrase. This gate exempted only the
        # CALLER's own seats, so the hosts' turns stayed swappable, and
        # they were swapped: measured twice inside one call, in two
        # different voices, for song lyrics - "Living off borrowed time,
        # the clock tick faster" - answering a caller who had asked about
        # something else entirely.
        #
        # Inside a call every seat is exempt. A repeat is let through or
        # dropped; it is never answered with something off the shelf.
        _rerun = rerun_check(text, who,
                             kind="call" if caller_name else "",
                             # #1063: a recorded line is never swapped or
                             # dropped as a repeat at air time.
                             allow_repeat=allow_repeat or recorded)
        rerun_note(bool(_rerun["block"]))
        if _rerun["block"] and not line_review_permits(
                "repetition", text, reasons=[str(_rerun.get("why") or "repeated line")],
                context={"who": who}):
            # #824: a repeat trades for MATERIAL first, silence last —
            # the same swap the phrase gate below already performs.
            _swp = (fresh_pool_take() if phrase_setup()["swap"] else {})
            _new = spoken_text(str(_swp.get("text") or ""))
            if not _new and phrase_setup()["swap"]:
                # #809: the pool ran dry exactly when a looping storyline
                # needed swapping — six turns dropped to dead air in one
                # round. A LIVE swath is always there to take the slot.
                try:
                    _liveq = await speakbox_quote(most=3, cap=300) or {}
                except Exception:  # noqa: BLE001
                    _liveq = {}
                if _liveq.get("text"):
                    _swp = _liveq
                    _new = spoken_text(str(_liveq.get("text") or ""))
            if _new and who in ("dj", "cohost", "third") \
                    and names_only(_new, vouched or []) \
                    and not is_binned(_new):
                note_drop(who, text, "swapped for fresh material — "
                                     + _rerun["why"] + " (#824)")
                speakbox_remember({"file": _swp.get("file", ""),
                                   "text": _swp["text"],
                                   "lines": [_swp["text"]],
                                   "mind": _swp.get("mind", "")})
                text = _new
            else:
                note_drop(who, text,
                          "dropped — " + _rerun["why"] + " (#752)")
                print_penalise(_rerun.get("hit") or _rerun["key"])
                continue
        # #no-repeats: the PHRASE cooldown, at the same choke point. The gate above
        # asks "has this LINE been said"; this asks "has any run of these
        # words been on air this hour", which is what the operator asked for
        # and what a line rebuilt out of the same five-word pieces defeats.
        # A hit is not a drop: the line is swapped for material off the
        # speakbox shelf, so holding a repeat back makes the show fresher
        # rather than shorter. Never for a caller — a caller is a guest, not
        # a repeat offender — and never on a deliberate replay.
        # #795: and never DURING a call. A call's greeting/answer/goodbye
        # are stock moves by nature — the cooldown was eating the hosts'
        # halves of live calls, which is how callers rang, were "answered"
        # by nobody, and hung up having aired zero turns. A swapped line
        # mid-call answers the caller with unrelated shelf material, which
        # is worse than a familiar phrase.
        if not allow_repeat and not recorded and not caller_name \
                and who in ("dj", "cohost", "third"):
            _phrase = phrase_check(text, who, _round_grams)
            phrase_note(bool(_phrase["block"]))
            if _phrase["block"] and not line_review_permits(
                    "repetition", text, reasons=[str(_phrase.get("why") or "repeated phrase")],
                    context={"who": who}):
                _swap = (fresh_pool_take() if phrase_setup()["swap"] else {})
                _new = spoken_text(str(_swap.get("text") or ""))
                if not _new and phrase_setup()["swap"]:
                    try:
                        _liveq2 = await speakbox_quote(most=3,
                                                       cap=300) or {}
                    except Exception:  # noqa: BLE001
                        _liveq2 = {}
                    if _liveq2.get("text"):
                        _swap = _liveq2
                        _new = spoken_text(str(_liveq2.get("text") or ""))
                if _new and names_only(_new, vouched or []) \
                        and not is_binned(_new):
                    note_drop(who, text, "swapped for fresh material — "
                                         + _phrase["why"] + " (#no-repeats)")
                    speakbox_remember({"file": _swap.get("file", ""),
                                       "text": _swap["text"],
                                       "lines": [_swap["text"]],
                                       "mind": _swap.get("mind", "")})
                    text = _new
                else:
                    note_drop(who, text,
                              "dropped — " + _phrase["why"] + " (#no-repeats)")
                    continue
        if not minutes_only(text, (track or {}).get("seconds")):
            if _refuse(who, text, "made up a running time"):
                continue                # one bad turn shouldn't drop the rest (#520)
        # Final clean text, including any Speakerbox repeat replacement,
        # must pass before either the coalesced or individual render path.
        text = await _recording_tint(text, who, turn_index in tint_selected)
        if not text:
            continue
        # A long verbatim turn goes out in full: same voice, sentence-safe
        # pieces, one after another. The 300-character mid-word slice that
        # used to live here mangled exactly the turns that complied.
        # Disfluencies land HERE, where the text becomes final — so the
        # pre-rendered clip, the spoken line and the transcript all agree.
        # #750: let the LINE move the room before the line is rendered, so
        # an argument that escalates on the page escalates in the voices too.
        if feel:
            event, macro = escalation_feel(text)
            if event:
                state_bump(who, event)
            if macro is not None:
                _RADIO.setdefault("speaker_macro", {})[who] = macro
                # Mark it auto so dj_banter's cool-off can clear it — a
                # hand-set macro is never cleared, and a co-host left
                # nervous for the rest of the night is a real bug.
                _RADIO.setdefault("macro_auto", {})[who] = True
        vec = performance_vector(
            who, (caller_voice if who == "caller"
                  else caller2_voice if who == "caller2"
                  else voices.get(who)) or "")
        first_at = len(playlist)
        # The slider is the ceiling (#423): every piece fits in one
        # announce the box can drain; the SAME voice takes a breath at
        # each seam and simply continues the thought.
        for at, chunk in enumerate(
                sentence_chunks(text, cap=say_max_chars(),
                                most=say_chunks_for(
                                    text, say_max_chars()))):
            if at:
                chunk = breath_for(f"{who}{len(playlist)}") + chunk
            playlist.append({
                "who": who,
                "chunk": inject_disfluencies(
                    chunk, vec, seed=f"{who}{len(playlist)}"),
                "vec": vec, "turn_end": False, "big": False,
            })
        if len(playlist) > first_at:
            # #no-repeats: whatever was admitted is now "already said this round".
            _round_grams.update(phrase_grams(text, phrase_setup()["n"]))
            # #no-repeats: THE turn, carried alongside its chunks. The ledger used to
            # be written from item["chunk"] — post-chunking, post-disfluency —
            # while the gate above tests this whole clean `text`, so a turn
            # longer than say_max_chars() could never match its own row and
            # aired again and again with blocked=0. Recorded once, on the
            # first chunk, in the form the gate will look for.
            playlist[first_at]["turn_text"] = text
            playlist[-1]["turn_end"] = True
            # Three chunks and up is a monologue (#320): it earns the
            # room's silence when it lands.
            playlist[-1]["big"] = (len(playlist) - first_at) >= 3

    # A round meant as a two-hander that comes back as ONE speaker — the model
    # ignored "alternate", or a truncated reply collapsed to a lone 'A:' turn
    # (#549, #550) — would air entirely in the host voice, the co-host never
    # heard. When NO verbatim passage is in play (a seed and a hand-approved
    # line are DELIBERATE single-voice reads, #404/#423), hand alternate chunks
    # to the other session voice so BOTH DJs carry it. Voice and transcript
    # label both derive from item["who"], so this rebalances the coalesce path
    # and the turn-by-turn path alike.
    # #777: "tuning into the radio and getting no djs is mad frustrating."
    # Every gate above drops lines for a good reason - a record that is not on
    # air, a near-repeat, a buried line - and between them they can take an
    # ENTIRE round, which is a written, paid-for round that the listener hears
    # as silence. The gates are right to be strict about WHICH lines air; they
    # are not entitled to leave the station with nothing. If they emptied the
    # round, put the raw turns back and say so.
    if turns and not playlist:
        # #no-repeats: the promise of #777 is that the radio never goes silent. It is
        # NOT a promise to air the exact lines every gate just rejected, which
        # is what this did — the strictest outcome degrading into no gate at
        # all, and the worst round of the night getting the free pass. Keep
        # the promise with material off the speakbox shelf: words nobody has
        # said this hour, in the pair's own voices. Only if the shelf is bare
        # too do the raw turns go out, and then it is said plainly.
        fresh: list[dict[str, str]] = []
        for _ in range(4):
            one = fresh_pool_take()
            if not one.get("text"):
                break
            fresh.append(one)
        if fresh:
            pipeline_log("speakbox",
                         f"every one of the {len(turns)} turns was gated away "
                         f"- airing {len(fresh)} line(s) of fresh material off "
                         "the shelf instead of the repeats (#no-repeats)")
        else:
            pipeline_log("drop", f"every one of the {len(turns)} turns was "
                                 "gated away and the shelf is bare - airing "
                                 "the round anyway rather than leaving the "
                                 "radio silent (#777)")
        _raw: list[tuple[str, str]] = [
            (("dj" if at % 2 == 0 else "cohost"), one["text"])
            for at, one in enumerate(fresh)] or [
            (_who_of(marker), spoken_text(said)) for marker, said in turns]
        for at, (who, text) in enumerate(_raw):
            if not text:
                continue
            text = await _recording_tint(text, who, tint_needed and
                                        crystal_line_selected(text, "fallback"))
            if not text:
                continue
            vec = performance_vector(
                who, (caller_voice if who == "caller"
                      else caller2_voice if who == "caller2"
                      else voices.get(who)) or "")
            playlist.append({
                "who": who, "chunk": text, "vec": vec, "turn_text": text,
                "turn_end": True, "big": False,
            })
            if fresh and at < len(fresh):
                speakbox_remember({"file": fresh[at].get("file", ""),
                                   "text": text, "lines": [text],
                                   "mind": fresh[at].get("mind", "")})

    if tint_failed:
        pipeline_log("crystal", "the complete round is held before synthesis: "
                     "its selected dialogue did not meet the tint contract")
        return []

    # #1056: the listener answers in their own voice without taking over the
    # speaker's words. Only finished performances can enter the air queue.
    if ready_takes is None and not by_hand and not whole:
        playlist = add_listening_responses(
            playlist, voices,
            lambda who, context, used: _RESPONSES.take(
                voices.get(who, ""), voice_engine_for(voices.get(who, "")),
                context, used, crystal=continuity_crystal()), away=seat_away_who())

    # Includes raw fallback, recorded/manual exchanges, and prepared responses.
    # None may bypass the persistent exact-hour rule through a legacy waiver.
    if not _system2_repeat_rows(playlist, ready_meta):
        return []

    def _turn_voice(item: dict[str, Any]) -> str | None:
        if ready_takes is not None:
            return str(item.get("voice") or "")
        return ((caller_voice or None) if item["who"] == "caller"
                else (caller2_voice or caller_voice or None)
                if item["who"] == "caller2"
                else (voices.get(item["who"]) or None))

    def _turn_fx(item: dict[str, Any]) -> dict[str, Any]:
        # Both people on the line share the same crackling phone channel.
        fx = dict(phone_fx) if item["who"] in ("caller", "caller2") \
            else voice_effect_pick()
        if item.get("vec"):
            fx["perf"] = item["vec"]
        strip = str(dj.get(f"strip_{item['who']}") or "")
        if strip:
            fx["strip"] = strip
        return fx

    async def _premake(item: dict[str, Any]) -> dict[str, Any] | None:
        """Render the NEXT line while the current one is still playing —
        every engine, Piper included (#270). The synthesis wait disappears
        into the previous announce, so turns land on each other's heels
        instead of leaving thinking-room between responses. Two in flight
        at a time: firing a whole round at XTTS at once queued every line
        behind every other and the glass read 40-second renders (#389)."""
        if ready_takes is not None:
            return dict(item["ready_clip"])
        async with _PREMAKE_GATE:
            return await _premake_inner(item)

    async def _premake_inner(item: dict[str, Any]) -> dict[str, Any] | None:
        try:
            if item.get("listening_response"):
                return dict(item["response_clip"])
            v = _turn_voice(item) or ""
            engine = voice_engine_for(v)
            text = spoken_text(item["chunk"])
            if not text or not re.search(r"[^\W_]", text):
                return None
            # #886: made already, while a record was playing. This is the
            # whole buffer — a hit costs nothing and skips the engine.
            _ready = pantry_get(pantry_key(text, v, engine))
            if _ready:
                pipeline_log("lookahead", "off the pantry shelf - no render "
                             f"needed - {item['who']} (#886)")
                take_note(item["who"], v, engine, text, _ready, 0, "shelf")
                return _ready
            # #746: BOTH cloning engines. This probed XTTS only, so an
            # F5 voice with :8772 down raised out of voice_generate
            # instead of falling back to Piper like everything else.
            # #784: and a not-ready clone is no longer a reason to come
            # back with nothing. That was a thirty-second-stale health
            # cache quietly costing the round a turn - twice over, since
            # the burst re-render asks the same question again. The ladder
            # takes the other clone engine or a Piper stand-in, so the
            # pre-render makes audio whenever audio is possible at all.
            cold = ((engine in ("xtts", "f5")
                     and not await clone_engine_ready(engine))
                    or (engine == "voxtral"
                        and not (await voxtral_health())["ready"]))
            if not cold:
                pipeline_log("lookahead", "pre-rendering the next line - "
                             f"{engine} - {item['who']}")
            _t0 = time.monotonic()
            # #904: the budget counts the render that is ACTUALLY
            # happening, not the task waiting its turn on
            # _PREMAKE_GATE — the whole round takes that gate at once,
            # so it said "busy" for the length of a round and the
            # pantry window never opened. The live road still never
            # waits on this: it takes its slot and goes.
            engine_live_enter()
            try:
                _made = await voice_render_any(
                    text, v, "" if cold else engine,
                    fx=_turn_fx(item), who=item["who"])
            finally:
                engine_live_exit()
            take_note(item["who"], v, engine, text, _made,
                      int((time.monotonic() - _t0) * 1000), "live")
            return _made
        except Exception:
            return None                 # dj_speak will render it itself

    # The WHOLE round renders up front (#370, #372): every line's clip is
    # requested at once — the GPU chews through them in parallel while the
    # first line is already playing — and playback just walks the finished
    # files. No thinking-room between turns; a phone call sounds like a
    # phone call.
    # Persist the accepted conversational plan before synthesis divides long
    # turns into chunks or streaming divides the call into transport bursts.
    _call_archive_parts: list[str] = []
    _call_archive_transcript: list[dict[str, str]] = []
    if caller_name:
        for item in playlist:
            text = str(item.get("turn_text") or "").strip()
            if not text:
                continue
            who = str(item.get("who") or "")
            _call_archive_transcript.append({
                "who": who,
                "name": booth_actor_name(
                    who, caller_name if who == "caller"
                    else caller2_name if who == "caller2" else ""),
                "text": text,
            })
        call_line_transcript(_call_archive_transcript)

    premade = [asyncio.create_task(_premake(item)) for item in playlist]

    # --- The whole call as ONE seamless stream (#530, #535) -----------------
    # Render every turn, then COALESCE them — ring, the turns back to back
    # (their tail-pads are the beats between speakers), the hang-up — into a
    # single continuous clip and play THAT. No per-announce gaps or box
    # hiccups between turns: it plays like a recording of a real call. Any
    # failure falls straight through to the turn-by-turn path below, so the
    # call is never lost (dry beats broken).
    # #905: bound HERE, not inside the branch. They are read at function
    # scope below (`recovering = bool(played_any and missed)`), so a round
    # that does not take the coalesced road raised UnboundLocalError
    # before a word aired — which is every round if stream_show is off,
    # and every press of the booth's "say this round" button.
    played_any = False
    missed: list[int] = []              # #767: scheduled, never aired
    # #1146: the wall-clock moment the page-road audio this round has
    # already appended will finish sounding. 0.0 until the first append.
    _paged_until = 0.0
    _sfx_units = int(_SFX_CADENCE.state()["heard_units"])
    if render_stream and playlist:
        # #760: NOT here. This used to be `await asyncio.gather(*premade)`,
        # which waits for every turn in the round before a single one can be
        # played — forty-three of them, at seven to nine seconds each, is
        # the five minutes of dead air. Each batch now awaits only its own
        # turns; the rest keep rendering in the background, which is what
        # the pre-render was always for.
        # #760: the batch ladder. The first burst is small so the room hears
        # something almost at once; later ones widen so the joins stay rare.
        # 43 turns used to mean 43 renders before a single word.
        def _batches(total: int) -> list[tuple[int, int]]:
            out: list[tuple[int, int]] = []
            at, width = 0, 2
            while at < total:
                out.append((at, min(total, at + width)))
                at += width
                width = min(8, width * 2)
            return out

        spans = _batches(len(playlist))
        # #1151: A FULLY-BANKED ROUND AIRS IN ONE PIECE. The ladder
        # exists to get first sound out while later turns render; when
        # every turn is already on the pantry shelf there is nothing to
        # wait for, and every extra page is only an extra join for the
        # #1146 pacing to space apart. Dead air at a boundary is
        # max(0, render_time - spoken_time); all hits makes render_time
        # ~concat only, so one page means zero boundaries. Capped by
        # spoken seconds so a monster round still splits under the box's
        # 180s announce budget, in pages of 8 whose boundaries are
        # zero-gap anyway.
        try:
            _est_secs = 0.0
            _all_hit = bool(playlist)
            for _item in playlist:
                _pv = _turn_voice(_item) or ""
                _pc = (_item.get("response_clip") if _item.get("listening_response") else None)
                if not _pc:
                    _pc = pantry_get(pantry_key(
                        spoken_text(_item["chunk"]), _pv,
                        voice_engine_for(_pv)))
                if not _pc:
                    _all_hit = False
                    break
                _est_secs += float(_pc.get("seconds")
                                   or (len(str(_item.get("chunk") or ""))
                                       / 14.0))
            # 2026-09-08 (the calls scan): A PHONE CALL IS NEVER PAGED.
            #
            # "I dont like hearing the customers just vaporized." Measured
            # over four days: 18 of 62 calls that rang on air (29%) never
            # said goodbye, and every one of them has a hole of 36 seconds
            # or more INSIDE the call while the clean ones are all under
            # twenty. The ladder is why. An eleven-turn call pages 2/4/5, and
            # the air stops at each boundary to wait for the next page's TTS;
            # if a render fails or a repeat check refuses at that boundary,
            # the tail goes to the render backlog, which airs ONE LINE PER
            # DRAIN behind the floor - so the caller is abandoned mid-arc and
            # the rest arrives, out of context, minutes later.
            #
            # A call therefore waits for all of its audio and then airs as
            # one piece. The wait is paid OFF AIR, where the gap roads cover
            # it; the alternative is paying it mid-conversation.
            #
            # 2026-09-09: AND THE TEST GOES FIRST. It was written as the
            # last `elif` of a chain whose first two arms fire on
            # `_all_hit`, so it was unreachable for exactly the call it
            # was written for: a FULLY BANKED one longer than 150s took
            # the `elif _all_hit` arm and was paged in eights - the road
            # the paragraph above forbids. Measured over 18 hours of the
            # gap log: 136 page-join holes, median 20.7s, with ZERO live
            # takes inside them (every clip was already on the shelf), and
            # 111 of the 136 were caller rounds. The joins were not TTS;
            # they were the ladder itself.
            if caller_name:
                spans = [(0, len(playlist))]
            elif _all_hit and _est_secs <= 150.0:
                spans = [(0, len(playlist))]
            elif _all_hit:
                spans = [(_i, min(len(playlist), _i + 8))
                         for _i in range(0, len(playlist), 8)]
        except Exception:  # noqa: BLE001
            pass
        if ready_takes is not None:
            spans = [(0, len(playlist))]
        call_miss_at: int | None = None
        for _bi, (_lo, _hi) in enumerate(spans):
            first_batch = _bi == 0
            last_batch = _bi == len(spans) - 1
            # #1022: A PAUSE STOPS THE PRESS AT THE PAGE BOUNDARY.
            # Measured 2026-09-04: a pause at 19:57:53 was followed by ten
            # more pages up to 20:09 and four more at 21:17-21:26 — 120 rows
            # landed on the hold shelf (which keeps twelve) and the pause
            # bought 0.0s of ready audio, because the engine those pages
            # spent is the engine the keeper needed for the bank. The page
            # already announced finishes: the listener is mid-sentence when
            # the flip lands. No NEW page starts. by_hand is exempt — a
            # person outranks the show (#206) — and the round's own text is
            # untouched, so what did not air is still written down.
            if _bi and not by_hand and radio_paused():
                if playlist:
                    # A pause is allowed to stop the air; it is not allowed
                    # to turn a picked-up call into a fake completion. Keep
                    # the accepted tail in order and continue it when the
                    # carrier returns. Previously the loop broke here with
                    # `missed=[]`, returned the first two turns as success,
                    # and call_ended wrote a completed hang-up for a caller
                    # the listener never heard resolve.
                    try:
                        pipeline_log(
                            "air", f"{caller_name or 'The booth'} conversation is held at page "
                            f"{_bi + 1} of {len(spans)} while the station is "
                            "paused - its accepted ending remains owed")
                    except Exception:  # noqa: BLE001
                        pass
                    while radio_paused() and _RADIO.get("on"):
                        # The floor lock's stale guard is ten minutes. A
                        # deliberate long pause must not make this still-live
                        # caller look abandoned and let a second call open on
                        # top of the accepted tail that remains owed.
                        if str(_CALL_LIVE.get("who") or "") == caller_name:
                            _CALL_LIVE["at"] = time.time()
                        if _FLOOR_OWNER.get("task") is asyncio.current_task():
                            _FLOOR_OWNER["at"] = time.time()
                        await asyncio.sleep(1.0)
                    if not _RADIO.get("on"):
                        # 2026-09-08 (the calls scan): the station going off
                        # mid-round is not a finished round. Without this the
                        # break fell through to `played_any and not missed`
                        # and call_ended wrote a normal hang-up for a caller
                        # who never resolved - a completion the station
                        # forged for itself.
                        missed.extend(range(_lo, len(playlist)))
                        break
                else:
                    try:
                        pipeline_log(
                            "air", "the pause stops this round at page "
                            + str(_bi + 1) + " of " + str(len(spans))
                            + " - the rest is not rendered, and the engine "
                            "goes to the bank instead (#1022)")
                    except Exception:  # noqa: BLE001
                        pass
                    break
            seg: list[str] = []
            # Only a real CALL opens with a ring and closes with a hang-up; a
            # coalesced booth round (#616/#625) is just the turns, joined
            # clean. The ring belongs to the first burst only.
            ring_secs = 0.0
            if caller_name and first_batch:
                ring = await asyncio.to_thread(make_phone_ring)
                if ring:
                    seg.append(str(ring))
                    # #778: the ring is IN the clip and was never in the
                    # timeline, so every turn of a call was claimed to start
                    # a ring-length early.
                    ring_secs = sfx_seconds(ring) or 0.0
            transcript: list[tuple[str, str]] = []
            # #830: transcript mirrors seg EXACTLY. These map each row
            # to its seg slot (for the beat glued after it) and to its
            # aired_items turn (-1 for stings and quips).
            seg_ix: list[int] = []
            turn_ix: list[int] = []
            # #no-repeats: the playlist item behind each transcript row, kept in step
            # with it, so the ledger below can be written from the item's
            # turn_text — the whole clean turn the gate tested — instead of
            # from the disfluency-injected chunk it was writing before.
            aired_items: list[dict[str, Any]] = []
            _sfx_meta: dict[int, dict] = {}
            _sfx_extra_seconds = 0.0
        # The conversation PRE-PLAN (#556): every planned turn laid out with
        # its checkpoints — written already (the script exists), intonation
        # attached (the performance vector), rendered flipped true as each clip
        # lands. The Mind flow-chart and /api/dj/plan read this, so the whole
        # conversation can be watched lining up before it airs.
            if first_batch:
                _RADIO["plan"] = {
                    "kind": "call" if caller_name else "deep",
                    "at": int(time.time()),
                    "who": caller_name or "the booth",
                    "turns": [{"who": it["who"],
                               "text": spoken_text(it["chunk"])[:70],
                               "rendered": False} for it in playlist],
                }
                # #795: bind OUR round's plan object once. Rounds run
                # concurrently (torrent + record intro + larder recast all
                # live at once), and re-reading the GLOBAL on every batch
                # meant another round could swap in a SHORTER turn list —
                # the checkpoint write below then IndexError'd and took the
                # whole round down mid-air. Observed killing a live round.
                _round_plan = _RADIO["plan"]
            try:
                _plan_turns = _round_plan["turns"]
            except NameError:            # a path that skipped batch zero
                _round_plan = _RADIO["plan"]
                _plan_turns = _round_plan["turns"]
            # Only this burst's turns. return_exceptions so one bad render
            # cannot take the round down — the per-turn fallback below
            # already knows how to re-render a missing clip.
            batch = await asyncio.gather(*premade[_lo:_hi],
                                         return_exceptions=True)
            batch = [None if isinstance(c, BaseException) else c
                      for c in batch]
            _sfx_core_seconds = (sum(_clip_seconds(c["path"]) for c in batch
                                     if c and c.get("path")) + ring_secs
                                 + max(CONCAT_BEAT) * max(0, len(batch) - 1)
                                 + (3.0 if caller_name and last_batch else 0.0))
            for idx, (item, clip) in enumerate(
                    zip(playlist[_lo:_hi], batch), start=_lo):
                if not clip and ready_takes is not None:
                    _sfx_cadence_release(_sfx_meta.values())
                    return []
                if not clip:                        # premake missed — render now
                    v = _turn_voice(item) or ""
                    try:
                        clip = await voice_generate(
                            spoken_text(item["chunk"]), v,
                            voice_engine_for(v), fx=_turn_fx(item))
                    except Exception:
                        clip = None
                    # A clone that fails must NOT drop the turn from the call —
                    # that is exactly "a caller says one thing then disappears"
                    # (#545). Fall back to piper so EVERY turn makes the stream.
                    # #784: on the OUTCOME, not on the engine's name. The old
                    # guard `voice_engine_for(v) != "piper"` is False under
                    # render relief, which is precisely when a clone voice
                    # cannot render — so the rescue stood down exactly when
                    # the turn needed it and the turn went to `missed`.
                    if not clip:
                        clip = await voice_render_any(
                            spoken_text(item["chunk"]), v, fx=_turn_fx(item),
                            who=item["who"])
                if not (clip and clip.get("path")):
                    # #767: premake missed, the re-render raised and piper
                    # raised too. This had no else — the turn vanished out of
                    # seg and transcript with nothing logged anywhere. Say so,
                    # and put it on the list to be aired on its own below.
                    missed.append(idx)
                    note_drop(item["who"], item["chunk"],
                              "would not render for the burst — airing it on "
                              "its own (#767)")
                    if playlist:
                        # Do not publish a later answer before a missing
                        # caller/host turn. Stop this stream exactly at the
                        # first hole and hand the entire ordered tail to the
                        # per-turn recovery below. The former path sent the
                        # rest (and even the hang-up) first, then discarded
                        # the hole as too late to replay.
                        call_miss_at = idx
                        missed.extend(range(idx + 1, len(playlist)))
                        break
                if clip and clip.get("path"):
                    key = clip["path"].rsplit("/", 1)[-1]
                    seg.append(str(VOICE_MEDIA_DIR / key))
                    # #830: the turn's row goes down NOW, before whatever
                    # punches in after it — the booth's order IS the
                    # audio's order (the quip used to land above the
                    # line it was answering).
                    transcript.append((item["who"], item["chunk"],
                                       _clip_seconds(clip["path"])))
                    seg_ix.append(len(seg) - 1)
                    turn_ix.append(len(aired_items))
                    aired_items.append(item)                          # #no-repeats
                    _DIALOGUE_AT[0] = time.time()                     # 2026-09-07
                    # Gold: a rhymed turn with its take is kept to fire again.
                    if ready_takes is None and item.get("turn_end") and item["who"] in ("dj", "cohost", "third"):
                        try:
                            gold_note(item["who"], str(item.get("turn_text") or item["chunk"]),
                                      str(clip.get("path") or key), _clip_seconds(clip["path"]))
                        except Exception:  # noqa: BLE001
                            pass
                    # #833: sting_due() existed, had a dial, had TESTS —
                    # and no live path ever called it. The samples now
                    # punch into the stream between lines, at the dial's
                    # rate, never twice inside the gap.
                    # Phone calls are a three-way exchange. Samples and the
                    # SFX Guy were being inserted after host turns, so the
                    # caller appeared to answer unrelated material and the
                    # arc felt as if it had vanished. Board punctuation stays
                    # on booth rounds; a live caller keeps the line.
                    _keep_mic = bool(ready_takes is not None or caller_name or talk_is_incessant()
                                     or _sfx_cadence_enabled())
                    _extras = await _sfx_cadence_additions(
                        item["who"], item["chunk"], _sfx_units,
                        _sfx_core_seconds + _sfx_extra_seconds, ready_takes, ready_meta)
                    if item["who"] in ("dj", "cohost", "third", "host"):
                        _sfx_units += 1
                    for _extra in _extras:
                        seg.append(_extra["path"])
                        _sfx_meta[len(transcript)] = _extra
                        transcript.append((_extra["who"], _extra["text"], _extra["seconds"]))
                        seg_ix.append(len(seg) - 1)
                        turn_ix.append(-1)
                        _sfx_extra_seconds += _extra["seconds"] + max(CONCAT_BEAT)
                    _sting = "" if _keep_mic else sting_due()
                    if _sting:
                        # Gold: a rhymed bar that already aired comes back
                        # from the other seat, the sting lands after it.
                        _gold = (gold_pick(exclude_who=item["who"])
                                 if random.random() < GOLD_FIRE_RATE else None)
                        if _gold:
                            seg.append(str(VOICE_MEDIA_DIR / str(_gold.get("path") or "")))
                            transcript.append((str(_gold.get("who") or "dj"),
                                               str(_gold.get("text") or ""),
                                               float(_gold.get("seconds") or 0)))
                            seg_ix.append(len(seg) - 1)
                            turn_ix.append(-1)
                            gold_fired(_gold)
                            pipeline_log("air", "a gold bar fires again, sting to "
                                         f"follow: {str(_gold.get('text') or '')[:70]}")
                        seg.append(str(_sting))
                        _STING_AT[0] = time.time()
                        # #830: the sting is IN the timeline — a board
                        # row with its own window, not invisible audio
                        # smeared across every later turn's clock.
                        transcript.append(("board",
                                           f"🔊 {_sting.stem}",
                                           sfx_seconds(_sting)))
                        seg_ix.append(len(seg) - 1)
                        turn_ix.append(-1)
                        pipeline_log("air", f"sting: {_sting.stem} "
                                     "dropped between lines (#833)")
                    # #835: the SFX Guy's MOUTH — at the slider's rate a
                    # backcountry quip lands whole cloth between
                    # statements, in his own voice (the replay cache
                    # makes every repeat free). Never during a call's
                    # caller turn — he heckles the hosts, not the guests.
                    _gq_rate = int(dj_settings().get("sfxguy_rate") or 0)
                    if (not _keep_mic and _gq_rate
                            and dj_settings().get("drop_voice")
                            and item["who"] in ("dj", "cohost", "third")
                            and random.random() < _gq_rate / 100.0):
                        _gv = str(dj_settings()["drop_voice"])
                        _qraw = sfxguy_line(
                            _gv, spoken_text(item["chunk"])[:200])
                        # #889: his mouth is a road to air like any other,
                        # and it was the one road that never passed the
                        # English door - it rendered whatever sfxguy_line
                        # returned. The story he BREAKS carries a raw
                        # headline off the wire, which nothing had judged
                        # at all: only the take beside it was ever checked.
                        _quip = spoken_text(_qraw)
                        if _qraw and not _quip:
                            note_drop("drop", _qraw,
                                      "the SFX guy's line did not pass the "
                                      "English door - the station is "
                                      "English (#889)")
                        # #1064: "every single thing needs to be tinted
                        # and spitting bars" - his mouth included. Under
                        # the hold a quip that did not rap stays in.
                        if _quip and dialogue_tint_wanted():
                            _qt = await crystal_line(
                                _quip, "the SFX guy's quip", 1, kind="banter")
                            if tint_output_ready(_qt):
                                _quip = _qt
                            elif crystal_tint_holds() and air_gate(False, "drop", _quip,
                                    "(#1064) the SFX guy's quip did "
                                    "not rap - held under the crystal"):
                                _quip = ""
                        try:
                            _qc = await voice_render_any(
                                _quip, _gv, who="drop") if _quip else None
                        except Exception:  # noqa: BLE001
                            _qc = None
                        if _qc and _qc.get("path"):
                            _qk = _qc["path"].rsplit("/", 1)[-1]
                            seg.append(str(VOICE_MEDIA_DIR / _qk))
                            transcript.append(
                                ("drop", _quip,
                                 _clip_seconds(_qc["path"])))
                            seg_ix.append(len(seg) - 1)
                            turn_ix.append(-1)
                            pipeline_log("air", "the SFX guy pipes up: "
                                         f"{_quip[:60]} (#835)")
                    # #748/#830: the turn's transcript row was appended
                    # above, before the sting and the quip, mirroring seg.
                    # #782: what it cost to make this turn, kept on the item
                    # so the dossier can show it beside what it cost to say.
                    item["render"] = {
                        "engine": clip.get("engine") or "",
                        "voice": clip.get("voice") or "",
                        "ms": int(clip.get("ms") or 0),
                        "kb": int((clip.get("bytes") or 0) / 1024),
                        "seconds": float(clip.get("seconds") or 0),
                        "service": str(clip.get("service") or ""),
                        "tried": list(clip.get("tried") or []),
                        "fallback": str(clip.get("fallback") or ""),
                    }
                    if idx < len(_plan_turns):             # checkpoint hit (#556)
                        _plan_turns[idx]["rendered"] = True
            hang_secs = 0.0
            if caller_name and last_batch and call_miss_at is None:
                hang = await asyncio.to_thread(make_hangup)
                if hang:
                    seg.append(str(hang))
                    # #703: audible, so it belongs in the list.
                    # #778: but NOT logged here. This is minutes before the
                    # burst it closes is audible, and the booth sorts on
                    # air_at \u2014 so logging it now put the receiver going down
                    # above the whole final burst of the call. It is logged
                    # after the timeline exists, stamped with the moment it
                    # is actually heard.
                    hang_secs = sfx_seconds(hang)
            # One segment cannot be concatenated with itself; a single-turn
            # burst is already one clip and goes out as it is.
            # #778: the beats are drawn HERE and handed to the mixer, so the
            # booth's per-turn windows below are built from the very numbers
            # the audio was built with instead of from the clips as they sat
            # on disk.
            beats = concat_beats(len(seg))
            try:
                mixed = (await asyncio.to_thread(
                            _call_concat_blocking, seg,
                            bool(dj_settings().get("stream_texture")), beats)
                         if len(seg) >= 2 else None)
            except BaseException:
                _sfx_cadence_release(_sfx_meta.values())
                raise
            if not mixed:
                _sfx_cadence_release(_sfx_meta.values())
            if not mixed and len(seg) == 1 and transcript:
                try:
                    mixed = Path(seg[0]).read_bytes()
                except OSError:
                    mixed = None
            if mixed:
                one = _store_media(mixed, "wav")
                length = _clip_seconds(one["path"]) or 0.0
                if (ready_takes is not None and _sfx_meta
                        and not _ready_round_fits(str(ready_meta.get("prep_kind") or ""),
                            ready_takes, ready_meta.get("_ready_slot"), seconds=length)
                        and _ready_round_fits(str(ready_meta.get("prep_kind") or ""),
                            ready_takes, ready_meta.get("_ready_slot"),
                            seconds=_sfx_core_seconds, start_at=time.time() + 5.0)):
                    # An unexpectedly slow join may consume the optional
                    # allowance. Try the exact original audio once, without
                    # sacrificing accepted dialogue to an SFX opportunity.
                    _sfx_cadence_release(_sfx_meta.values())
                    for optional in _sfx_meta.values():
                        _SFX_CADENCE_STATUS["sample_omitted" if optional.get("sfx_sample_id")
                                            else "guy_omitted"] += 1
                    excluded = {seg_ix[index] for index in _sfx_meta}
                    kept = [index for index in range(len(seg)) if index not in excluded]
                    mapping = {old: new for new, old in enumerate(kept)}
                    seg = [seg[index] for index in kept]
                    original_rows = [index for index in range(len(transcript)) if index not in _sfx_meta]
                    transcript = [transcript[index] for index in original_rows]
                    seg_ix = [mapping[seg_ix[index]] for index in original_rows]
                    turn_ix = [turn_ix[index] for index in original_rows]
                    _sfx_meta = {}
                    beats = concat_beats(len(seg))
                    mixed = (await asyncio.to_thread(_call_concat_blocking, seg,
                                bool(dj_settings().get("stream_texture")), beats)
                             if len(seg) >= 2 else Path(seg[0]).read_bytes())
                    if not mixed:
                        return []
                    one = _store_media(mixed, "wav")
                    length = _clip_seconds(one["path"]) or 0.0
                if length <= 0.5:
                    _sfx_cadence_release(_sfx_meta.values())
                    # #1147: a burst whose header will not measure is not
                    # airworthy, and a zero length would collapse the
                    # #1146 pacing into an append-speed flood. Treat the
                    # burst as failed; the per-turn road below still airs
                    # every line.
                    pipeline_log("drop", "a coalesced burst measured "
                                 f"{length:.2f}s - refusing the mix and "
                                 "falling back to turn-by-turn (#1147)")
                    if played_any:
                        missed.extend(range(_lo, _hi))
                        continue
                    break
                pipeline_log("voice", "call coalesced into one stream — "
                                      f"{len(transcript)} turns · {length:.0f}s "
                                      "(#535)")
                # A call may span several transport bursts. Keep every part
                # until the final burst, then archive one complete call.
                if caller_name:
                    _call_archive_parts.append(
                        str(VOICE_MEDIA_DIR
                            / one["path"].rsplit("/", 1)[-1]))
                # The call belongs in the rolling episode too (its per-turn chat
                # entries bypass dj_speak's capture) (#548).
                _episode_stage(one["path"],
                               ("☎ " + caller_name + " — the full call")
                               if caller_name else "🎙 the booth — a full round")
                # The transcript still shows every turn in the booth/Mind, even
                # though the audio is one clip.
                # #748: THE fix for "the booth is not synced with the active
                # broadcast". Every conversational path — banter, deep rounds,
                # calls — funnels through here when stream_show/call_stream are
                # on, which is the default, and this branch renders the whole
                # round into ONE clip and appends every row in a single batch
                # after the audio was built. So the booth had no idea which line
                # of a two-minute stream was sounding: dj_speak, which is the
                # only thing that publishes "speaking_now", is never called.
                # The clip's own timeline is the answer — each turn's measured
                # length becomes a window, and the panel reads off the clock.
                # #1205: ask this round's own segments what the mixer
                # will take off the end of each of them, instead of
                # assuming 0.9 for all of them - which is right for a
                # rendered take, wrong for every sample, and wrong for
                # the ring and the hang-up that anchor the arithmetic.
                # One thread hop beside the concat that has already read
                # all of these; the loop below then does arithmetic only.
                # A single-segment round never goes through the mixer
                # at all - it is handed over as it sits on disk, pad and
                # all - so nothing is trimmed off it and its window is
                # the whole file.
                _welded = len(seg) >= 2
                try:
                    _seg_tails = (await asyncio.to_thread(seg_tails_for, seg)
                                  if _welded else [])
                except Exception:  # noqa: BLE001
                    _seg_tails = []

                def _tail_at(index: int) -> float:
                    return (_seg_tails[index]
                            if 0 <= index < len(_seg_tails) else -1.0)

                def _beat_at(index: int) -> float:
                    return (beats[index]
                            if 0 <= index < len(beats) else 0.0)

                rows = []
                # #778: the turns do not start at zero when a ring opens the
                # clip, and each one runs for its TRIMMED length plus the beat
                # that was actually glued after it — not for the length of the
                # file on disk, which still had its 900 ms box tail on it.
                # `seg` is [ring?] + one entry per aired turn + [hang-up?], so
                # a turn's index in `beats` is its row plus the ring.
                # #1205: the ring is a SAMPLE, and it is trimmed and
                # beaten into the stream like every other segment. Its
                # length on disk is not where the first turn begins, and
                # this number anchors the rescale below as well.
                _ring_real = ring_secs
                if ring_secs and _welded:
                    _ring_real = seg_real_seconds(ring_secs, _beat_at(0),
                                                  _tail_at(0))
                offset = _ring_real
                lead = 1 if ring_secs else 0
                _est0 = time.time()
                _entries: list[dict[str, Any]] = []
                for _row, (who, chunk, secs) in enumerate(transcript):
                    spoken.append(f"{who}: {chunk}")
                    # #752: the coalesced path never went near dj_speak, so
                    # nothing it aired was ever written down — which is why the
                    # overused-phrase and do-not-repeat clauses were reading a
                    # fraction of the show.
                    # #no-repeats: written from the TURN, once, not from every chunk.
                    # The ledger was recording `chunk` — a sentence-capped
                    # slice with disfluencies injected into it — while
                    # rerun_check tests the whole clean turn, so the key stored
                    # was never the key later looked up and a long line could
                    # air any number of times untouched. turn_text rides on the
                    # first chunk of each turn; continuation chunks add
                    # nothing, which is also what stops one turn being counted
                    # three times.
                    _ti = turn_ix[_row] if _row < len(turn_ix) else -1
                    _turn = str((aired_items[_ti].get("turn_text") or "")
                                if 0 <= _ti < len(aired_items) else "")
                    rid = uuid.uuid4().hex  # durable receipt identity across station restarts
                    _kind = "sfx" if who == "board" else "call"
                    if who == "drop" and _row in _sfx_meta:
                        _kind = "sfxguy"
                    if ready_takes is not None and _ti >= 0:
                        _kind = str(ready_meta.get("prep_kind") or "banter")
                    entry = {
                        "id": rid,
                        "ts": int(time.time()), "who": who, "kind": _kind,
                        # #1023 (G1): which ROAD this row belongs to -
                        # kind above is "call" for every burst row.
                        "round": airlog_round_now(who, _kind, caller_name),
                        **({"sfx": chunk, "sfx_dir": "the stream",
                            "seconds": round(float(secs or 0), 2)}
                           if who == "board" else {}),
                        "text": chunk, "aired": "prepared",
                        # #1005: the painting this line is about, if a
                        # gallery round is up. Attached as the row is
                        # WRITTEN, which is the half gallery_line_mark
                        # cannot reach on the prepared road.
                        **({"images": _pics}
                           if who in ("dj", "cohost", "third", "caller")
                           and (_pics := gallery_pending_pick(chunk))
                           else {}),
                        "name": booth_actor_name(
                            who, caller_name if who == "caller"
                            else caller2_name if who == "caller2" else ""),
                        # #770: when this turn will actually be AUDIBLE, not
                        # when the batch was written. Every turn of a burst
                        # shares one `ts`; they do not share one moment. This
                        # is an estimate — playback starts a beat after this
                        # loop — and _stream_now_set corrects it below with
                        # the real handover time.
                        "air_at": _est0 + offset,
                        # #766: which document seeded it. dj_speak has carried
                        # this since #226 and the coalesced road never did —
                        # which is most of the show, and all of every call. It
                        # is how you see the report a caller is citing.
                        **({"source": source} if source else {}),
                        "voice": (_turn_voice(aired_items[_ti]) if ready_takes is not None
                                  and 0 <= _ti < len(aired_items) else caller_voice if who == "caller"
                                  else caller2_voice if who == "caller2"
                                  else voices.get(who, "")) or "",
                        # #782: the dossier, on the coalesced road too —
                        # which is where most of the show comes from.
                        "trace": {
                            "queued_at": time.time(),
                            "render": (aired_items[_ti].get("render") or {})
                            if 0 <= _ti < len(aired_items) else {},
                            "written": _model_call_for(chunk),
                            "chars": len(chunk),
                            "kind": "burst",
                            "burst": len(transcript),
                        },
                    }
                    _extra_fields = {k: v for k, v in _sfx_meta.get(_row, {}).items()
                                     if k in ("voice", "sfx_sample_id", "sfxguy_reservation")}
                    entry.update(_extra_fields)
                    # #1201: where this line sits in its script.
                    entry.update({"sid": _round_sid, "turn": int(_ti),
                                  "turns": len(transcript)})
                    _RADIO["chat"].append(entry)
                    _entries.append(entry)
                    # #778: the length this turn actually runs for INSIDE the
                    # coalesced clip.
                    _sx = (seg_ix[_row] if _row < len(seg_ix)
                           else _row + lead)
                    # #1205: measured, not assumed. The old road took
                    # 0.9 off every segment because that is what a
                    # rendered take carries - a sting off the shelf
                    # carries nothing, and max(0.25, ...) then clamped
                    # the negative result so the error was invisible.
                    _real = (seg_real_seconds(secs, _beat_at(_sx),
                                              _tail_at(_sx))
                             if _welded else max(0.4, secs))
                    rows.append({"id": rid, "who": who, "kind": _kind,
                                 "text": chunk,
                                 # Only the first chunk of a turn owns its
                                 # repetition-ledger text.  Audible playout
                                 # consumes it later; preparation does not.
                                 "remember_text": _turn,
                                 "name": booth_actor_name(
                                     who, caller_name if who == "caller"
                                     else caller2_name if who == "caller2" else ""),
                                 "from": offset, "until": offset + _real,
                                 **_extra_fields})
                    offset += _real
                # #770: 160 here against 240 everywhere else meant a busy
                # round amputated up to eighty entries the panel had never
                # been shown — "conversation moments not showing" outright.
                del _RADIO["chat"][:-240]
                # The turns were measured BEFORE the concat, which loudness-
                # normalises and can lay texture under the join, so the sum
                # drifts from the finished clip. Scale to what was actually
                # produced — the real length is already measured above.
                # #778: over the TURNS only. The ring at the head and the
                # hang-up at the tail are in `length` and are not turns, so
                # scaling the whole span by length/offset stretched every
                # window to swallow them and pushed the marker later and later
                # through a call. The residual this now corrects is the
                # loudness pass, which is what the correction was always for.
                # #1205: the hang-up is a generated wav with no welded
                # pad either, and `length` carries the 900 ms the mixer
                # glues onto the finished round - neither belongs in the
                # span the turns are scaled to fit.
                _hang_real = (seg_real_seconds(hang_secs, 0.0,
                                               _tail_at(len(seg) - 1))
                              if hang_secs and _welded else hang_secs)
                _made = (length - _ring_real - _hang_real
                         - (box_tail_seconds() if _welded else 0.0))
                _ours = offset - _ring_real
                if rows and _ours > 0.5 and _made > 0.5:
                    scale = _made / _ours
                    for r in rows:
                        r["from"] = _ring_real + (r["from"] - _ring_real) * scale
                        r["until"] = _ring_real + (r["until"] - _ring_real) * scale
                    # #830: page-routed bursts never get the box road's
                    # real correction — the estimate must at least agree
                    # with the SCALED timeline instead of the raw sums.
                    for _r2, _e2 in zip(rows, _entries):
                        _e2["air_at"] = _est0 + float(_r2.get("from") or 0)
                # #908: WHERE EACH TURN'S AUDIO ACTUALLY IS. The burst
                # is ONE welded file, and `rows` above already holds the
                # exact window every turn occupies inside it - the
                # booth's own moving marker is driven off these very
                # numbers. They went to _STREAM_NOW and were then
                # dropped on the floor, so nothing downstream could tell
                # one turn from another: /api/booth/clip matched a row to
                # a file by AIR TIME, found the whole round, and handed
                # the whole round over for every single line in it.
                # Written onto the row, one download is one line.
                try:
                    _burst_key = str(one["path"]).rsplit("/", 1)[-1]
                    # A turn's window ENDS on the short varied beat the
                    # mixer glued at the seam. The booth wants that beat
                    # inside the window - its marker must not jump to the
                    # next line early - and a download does not: that is
                    # the run-up to the next speaker, not this line. It
                    # rides along so the cut can leave it off, scaled by
                    # the same loudness-pass correction the windows got.
                    _bscale = ((_made / _ours)
                               if (rows and _ours > 0.5 and _made > 0.5)
                               else 1.0)
                    for _ri, (_r3, _e3) in enumerate(zip(rows, _entries)):
                        _sx3 = seg_ix[_ri] if _ri < len(seg_ix) else -1
                        _beat3 = (beats[_sx3] if 0 <= _sx3 < len(beats)
                                  else 0.0)
                        _e3["clip_media"] = _burst_key
                        _e3["clip_sig"] = str(one.get("sig") or "")
                        _e3["clip_from"] = round(
                            max(0.0, float(_r3.get("from") or 0)), 3)
                        _e3["clip_until"] = round(
                            max(0.0, float(_r3.get("until") or 0)), 3)
                        _e3["clip_tail"] = round(
                            max(0.0, float(_beat3) * _bscale), 3)
                except Exception:  # noqa: BLE001
                    pass            # a download never costs the air a beat
                # Deliver the ONE clip on the routing the DJ voice is set to,
                # mirroring to the page when the box is down (#536).
                vto = _RADIO.get("voice_to") or "box"
                if not box_talk_ok() and vto in ("box", "both"):
                    vto = "here"                       # the switch is off (#638)
                to_box = vto in ("box", "both")
                if to_box and box_firmware_down_now():
                    to_box = False                  # #1156: route around a dead box
                    _route_around_note("a round")
                box_down = (time.time() < float(_BOX_DOWN.get("until") or 0)
                            or len(_BOX_HOLD) >= 6)
                stream_label = ("☎ " + caller_name if caller_name
                                else "🎙 a conversation")
                stream_paged = page_carries_live(              # #1118
                    vto, to_box, box_down)
                page_delivery = ""
                if stream_paged:
                    # #1146: the page road pays for its airtime, per burst.
                    # Appending at render speed let a banked round flood
                    # the feed in seconds and hand the air to the next
                    # round while this one was still sounding. The wait
                    # below runs only while audio already appended is
                    # still provably playing - it can never add dead air
                    # (#776's scar stands), it only stops the stampede.
                    # Review notes folded in: the burst is ANNOUNCED up to
                    # PAGED_ANNOUNCE_EARLY before its air moment (the
                    # #998 download window), carries its own honest
                    # broadcast_ms (the client waits for it), the wait
                    # loops in short steps, and a paused station is never
                    # paced - its clips die to the resume cut unheard.
                    _plead = VOICE_BROADCAST_LEAD_MS / 1000.0
                    # #1147 review: consult the GLOBAL ledger too - a
                    # by-hand round (floor-exempt) or any concurrent
                    # producer may have sold air this round's local
                    # clock knows nothing about.
                    _pstart = max(time.time() + _plead, _paged_until,
                                  float(_PAGE_AIR_UNTIL[0] or 0))
                    _pwait = (_pstart - _plead - PAGED_ANNOUNCE_EARLY
                              - time.time())
                    while _pwait > 0 and not radio_paused():
                        await asyncio.sleep(min(_pwait, 5.0))
                        _pwait = (_pstart - _plead - PAGED_ANNOUNCE_EARLY
                                  - time.time())
                    # 2026-09-08 (the calls scan): THESE ARE START-OF-ROUND
                    # CHECKS. A slot that no longer fits, or a repeat check,
                    # may refuse a round that has not begun; it may not
                    # abandon a conversation the listener is already hearing -
                    # that is a caller cut off mid-sentence with no sign-off.
                    if (not played_any) and ready_takes is not None and (
                            radio_paused() or not _RADIO.get("on")
                            or not _ready_round_fits(str(ready_meta.get("prep_kind") or ""),
                                ready_takes, ready_meta.get("_ready_slot"),
                                seconds=length, start_at=_pstart)
                            or (callable(can_handoff) and not can_handoff())):
                        _sfx_cadence_release(_sfx_meta.values())
                        return []
                    if not played_any and not _system2_repeat_rows(rows, ready_meta):
                        _sfx_cadence_release(_sfx_meta.values())
                        return []
                    page_delivery = page_feed_append({
                        "ts": int(time.time() * 1000),
                        "broadcast_ms": int(_pstart * 1000),
                        "url": f"{one['path']}?t={one['sig']}",
                        "text": stream_label,
                        "voice": caller_voice or "",
                        "speech": True,
                        "stream": {"length": length, "rows": rows},
                        **({"ready_round": ready_meta}
                           if ready_takes is not None else {}),
                    })
                    if ready_takes is not None and page_delivery and callable(on_handoff):
                        on_handoff()
                    for _entry in _entries:
                        page_delivery_apply(_entry, page_delivery)
                    _paged_until = _pstart + max(0.0, float(length or 0))
                    # #1147: publish how far the air is sold, so every
                    # OTHER page producer (replies, stings, upstairs)
                    # stamps itself after this round instead of inside it.
                    _PAGE_AIR_UNTIL[0] = max(
                        float(_PAGE_AIR_UNTIL[0] or 0), _paged_until)
                # #748: start the server clock only when the box is the thing
                # actually carrying the stream. Page-routed streams start their
                # booth clock in djVoiceNext.onplaying, because a browser queue
                # can lag behind the server handoff.
                if to_box:
                    _stream_now_set(rows, length)
                # #778: NOW the receiver going down can be placed — at the end
                # of the clip it is at the end of, rather than at the moment
                # the mix was assembled.
                if hang_secs:
                    _desk_sound("☎ the receiver going down", hang_secs,
                                air_at=time.time() + max(0.0, length
                                                         - hang_secs))
                # #776: deliberately NOT waiting for the burst here. Pacing
                # the page road against playback removed the backlog and put
                # dead air in its place, which is the worse of the two on a
                # stream.
                if to_box:
                    # 2026-09-08 (the calls scan): as above - a check that
                    # belongs to the start of a round may not abandon one the
                    # listener is already hearing.
                    if (not played_any and not page_delivery
                            and not _system2_repeat_rows(rows, ready_meta)):
                        _sfx_cadence_release(_sfx_meta.values())
                        return []
                    if (not played_any and ready_takes is not None and not page_delivery
                            and (radio_paused() or not _RADIO.get("on")
                                 or not _ready_round_fits(str(ready_meta.get("prep_kind") or ""),
                                     ready_takes, ready_meta.get("_ready_slot"), seconds=length)
                                  or (callable(can_handoff) and not can_handoff()))):
                        _sfx_cadence_release(_sfx_meta.values())
                        return []
                    if ready_meta.get("_system2") and callable(on_handoff):
                        on_handoff()  # submitted; only the audible ACK credits it
                    played = await _play_on_box(one["path"], one["sig"])
                    # #807: _LAST_PLAYOUT is a SHARED meter — during a
                    # minutes-long burst, any concurrent ack or sting
                    # stamps it with ITS key, so the burst's verdict read
                    # someone else's meter, scored itself a miss, and the
                    # whole ALREADY-AIRED conversation went on the shelf
                    # to replay later. That was the repeated dialogue.
                    # _play_on_box returns "" on every failure path and
                    # verifies #822 inside itself, so a non-empty return
                    # IS the verdict; the meter only overrules when it
                    # still holds OUR key and says the play came short.
                    played_ok = False
                    _box_receipt = dict(_LAST_PLAYOUT)
                    if played:
                        lp = _box_receipt
                        if lp.get("key") == _played_out_key(one["path"]):
                            played_ok = bool(lp.get("ok"))
                        else:
                            played_ok = True
                    if not played_ok:
                        # It never went out — or came back short — so the booth
                        # must not confidently follow a call nobody can hear.
                        _stream_now_clear()
                        ids = {str(r.get("id") or "") for r in rows}
                        # #786: Nabu is the CORE device — a burst it did not
                        # carry goes on the hold shelf and REPLAYS when the
                        # satellite returns, exactly as the pine box always
                        # had it. (The old rule paged nabu conversations to
                        # the stream and forgave the replay debt — most of
                        # the show's dialogue rides this road, so the core
                        # speaker never got its backlog.) The page mirror
                        # still carries it live via stream_paged/'both'.
                        for line in _RADIO.get("chat") or []:
                            if str(line.get("id") or "") in ids:
                                line["box_delivery"] = "held"
                                if line.get("aired") not in ("stream", "both"):
                                    line["aired"] = "held"
                        if ready_takes is None:
                            box_hold(one, stream_label,
                                     "caller" if caller_name else "dj",
                                     rows=rows, length=length)
                    else:
                        _box_audible = _box_receipt_heard(one["path"], _box_receipt)
                        if _box_audible:
                            _sfx_cadence_audible(rows, length)
                        if ready_takes is not None and callable(on_handoff):
                            on_handoff()
                        _live_by_id = {str(r.get("id") or ""): r
                                       for r in _entries}
                        for _row_ack in rows:
                            _rid_ack = str(_row_ack.get("id") or "")
                            _live = _live_by_id.get(str(
                                _row_ack.get("id") or ""))
                            if _live is not None:
                                _page_played = (_PAGE_DELIVERIES.get(
                                    page_delivery) or {}).get("played_rows", set())
                                _live["aired"] = (("both" if _box_audible else "stream")
                                                  if _rid_ack in _page_played
                                                  else "box" if _box_audible else
                                                  "muted" if _box_receipt.get("intentional_mute") else "unconfirmed")
                                if not _box_audible:
                                    _live["box_delivery"] = ("muted" if _box_receipt.get("intentional_mute") else "unconfirmed")
                            _memory = str(_row_ack.get("remember_text") or "")
                            if (_box_audible and _rid_ack not in _PAGE_ACKED_LINES
                                    and _row_ack.get("who") in ("dj", "cohost", "third", "caller", "caller2", "drop")):
                                _system2_acknowledge_row({"ready_round": ready_meta}, _row_ack, "box:" + _rid_ack)
                                if _memory:
                                    air_remember(_memory,
                                                 str(_row_ack.get("who") or ""),
                                                 str(_row_ack.get("kind") or "stream"))
                                if _rid_ack:
                                    _PAGE_ACKED_LINES.add(_rid_ack)
                        if _box_audible:
                            talk_said_now("box", str(one.get("sig") or ""), 1.0)
                        if ready_takes is not None and _box_audible:
                            _ready_round_ack(ready_meta)
                # #760: the burst is done, not the round. Returning here
                # is what made the whole conversation one clip.
                if ready_takes is not None and not (page_delivery or (to_box and played_ok)):
                    _sfx_cadence_release(_sfx_meta.values())
                    return []
                played_any = True
                if call_miss_at is not None:
                    pipeline_log(
                        "call", "a call stream stopped before its first "
                        "missing turn - the complete ordered tail is going "
                        "through the recovery voice path")
                    break
                if last_batch and not missed:
                    if caller_name and _call_archive_parts:
                        asyncio.create_task(asyncio.to_thread(
                            _cache_call_recording_parts,
                            list(_call_archive_parts),
                            list(_call_archive_transcript), caller_name,
                            str(_CALL_LIVE.get("id") or "")))
                    await _paged_settle(_paged_until)      # #1146
                    return spoken
                if last_batch:
                    pipeline_log("drop", f"{len(missed)} scheduled turn(s) "
                                      "still owed after the final stream burst "
                                      "- handing them to the in-order tail "
                                      "rule (#1146)")
                    break
                continue
            # This burst could not be built. If earlier ones already went
            # out, the round is part-aired and must NOT be replayed WHOLE by
            # the turn-by-turn path below.
            # #767: it must not be abandoned either. `continue` here dropped
            # every turn of this burst on the floor — no audio, no booth row,
            # no drop note. Hand exactly these turns to the turn-by-turn path
            # instead, so the round still says everything it was given.
            if call_miss_at is not None:
                break
            # A failed concatenation owes this entire batch and every later
            # turn. Publishing a later batch first creates an unrecoverable
            # hole, even when this is a booth conversation rather than a call.
            missed.extend(range(_lo, len(playlist)))
            break
        if played_any and not missed:
            if caller_name and _call_archive_parts:
                asyncio.create_task(asyncio.to_thread(
                    _cache_call_recording_parts,
                    list(_call_archive_parts),
                    list(_call_archive_transcript), caller_name,
                    str(_CALL_LIVE.get("id") or "")))
            await _paged_settle(_paged_until)              # #1146
            return spoken                # all of it aired; do not repeat it
        # concat failed — fall through to the turn-by-turn path.

    if ready_takes is not None:
        # A missing input, refused route or failed concatenation leaves the
        # original shelf row available. Never synthesize a dry substitute.
        for pending in premade:
            if not pending.done():
                pending.cancel()
        return []
    # #767: normally this path airs the whole round. When the coalesced
    # path already put SOME of it out, it airs only the turns that never
    # made a burst — every scheduled line lands exactly once.
    order = list(range(len(playlist)))
    recovering = bool(played_any and missed)
    _missed_all: list[int] = []
    if recovering:
        # #1146 review: pay for the audio the bursts already appended
        # BEFORE the tail airs. The tail's clips are stamped 'now'; a
        # client still draining the burst backlog would read them as
        # late, drop them, and the server would book lines aired that
        # nobody heard.
        await _paged_settle(_paged_until)
        _missed_all = sorted({i for i in missed if 0 <= i < len(playlist)})
        # #1146: NEVER air line i after line j>i. The old recovery replayed
        # every missed chunk AFTER the rest of the round had gone out, so
        # turn 3 of a conversation sounded after turn 24 and the people
        # stopped making sense. Only the round's un-aired TAIL still
        # follows in sequence; a mid-round hole missed its moment, and a
        # hole reads better than a scramble.
        _aired_ix = [i for i in range(len(playlist))
                     if i not in set(_missed_all)]
        _tail_from = (max(_aired_ix) + 1) if _aired_ix else 0
        _holes = [i for i in _missed_all if i < _tail_from]
        order = [i for i in _missed_all if i >= _tail_from]
        if _holes:
            pipeline_log("drop", f"{len(_holes)} mid-round turn(s) missed "
                         "their moment and are dropped rather than re-aired "
                         "out of order (#1146)")
        if order:
            pipeline_log("drop", f"{len(order)} scheduled turn(s) never "
                         "made it into a burst — airing the round's tail "
                         "in sequence (#767/#1146)")
    # #1201: ONE ID FOR THIS CONVERSATION, so every line it airs can be
    # tied back to it and read in script order.
    _round_sid = uuid.uuid4().hex[:12]
    reached: set[int] = set()
    consumed = 0
    content_turns_spoken = 0
    # A normal booth round may yield between turns. A live caller has a
    # promised arc, so a skip can never strand their final thought on a shelf.
    # #859: and so does a MESSAGE — a memo from upstairs is three lines with
    # a beginning, a point and an instruction, and losing the last two makes
    # the first one nonsense. The operator watched the boss get cut off.
    can_cut = not bool(caller_name) and not whole
    for at in order:
        item = playlist[at]
        if (not caller_name and not whole and content_turns_spoken >= limit
                and not item.get("listening_response")):
            break
        reached.add(at)
        if _TALK_CUT[0] != cut_at and can_cut:
            break                       # something urgent took the floor — but
                                        # let the current turn FINISH first, so
                                        # a message never stops mid-way (#520)
        consumed = at + 1
        try:
            ready = await premade[at]
        except Exception:
            ready = None
        who = item["who"]
        _turn = str(item.get("turn_text") or "")
        backlog_before = {id(row) for row in _RENDER_BACKLOG}
        out = await dj_speak(
            "call" if who == "caller" else "interject", track,
            line=item["chunk"],
            who=who, voice=_turn_voice(item),
            source=source, by_hand=by_hand,
            # #901: gated and recorded upstream, on the whole TURN. This
            # road must not be gated again on the CHUNK — a
            # sentence-capped slice with disfluencies in it never
            # matches a ledger of whole turns.
            checked=True,
            fx=phone_fx if who == "caller" else None,
            name=caller_name if who == "caller" else "",
            source_text=source_text,
            clip=ready,
            sting=bool(item["turn_end"]), remember_text=_turn)
        if any(id(row) not in backlog_before and row.get("who") == who
               and spoken_text(str(row.get("text") or "")) == spoken_text(item["chunk"])
               for row in _RENDER_BACKLOG):
            # The failed turn has just joined the recovery queue. Preserve
            # the whole accepted tail behind it, so no answer overtakes its
            # question. Finished takes travel with their exact voice/text.
            for later_at in order[order.index(at) + 1:]:
                later = playlist[later_at]
                held_clip = None
                if premade[later_at].done() and not premade[later_at].cancelled():
                    try:
                        held_clip = premade[later_at].result()
                    except Exception:  # noqa: BLE001
                        pass
                _RENDER_BACKLOG.append({
                    "id": uuid.uuid4().hex[:16], "at": time.time(),
                    "text": later["chunk"], "who": later["who"],
                    "kind": "call" if caller_name else "interject",
                    "voice": _turn_voice(later), "fx": _turn_fx(later),
                    "remember_text": str(later.get("turn_text") or ""),
                    "clip": held_clip,
                    "to_box": (_RADIO.get("voice_to") or "box") in ("box", "both")})
            render_backlog_save()
            station_flow_event("repair", "held", "Conversation tail kept in order for recovery",
                               {"first_missing": at, "tail_lines": len(order) - order.index(at)},
                               from_node="tts")
            for pending in premade:
                if not pending.done():
                    pending.cancel()
            render_backlog_top()
            return spoken
        if out:
            spoken.append(f"{who}: {out}")
        if item["turn_end"]:
            if not item.get("listening_response"):
                content_turns_spoken += 1
            if item.get("big") and out:
                # The stunned beat (#320): a whole monologue just landed
                # and the room sits with it before anyone dares follow.
                # #769: 2.8 s flat was long enough to read as a fault. Still
                # a beat, no longer a hole, and never the same twice.
                await asyncio.sleep(random.uniform(1.05, 1.7))
            # dj_speak returns only once the line has actually been spoken,
            # so this is just a beat between turns, not a guess at length.
            await asyncio.sleep(banter_gap(dj["overlap"]))
        # A cut only lands between turns (#520): re-arm after each item so
        # the next iteration's guard may fire, but only at a turn boundary.
        # #805: …and NEVER during a live call — this re-arm was quietly
        # discarding the caller protection from the second turn onward, so
        # a talk-cut could strand a caller mid-arc on the per-turn road.
        can_cut = (bool(item["turn_end"]) and not caller_name and not whole
                   and not item.get("continuation_response"))
    # Is the box actually the destination right now? (#712) Recomputed here
    # rather than reused: the coalesced path's `to_box` lives in a branch that
    # returns, so it is not in scope on this one.
    _vto = _RADIO.get("voice_to") or "box"
    shelf_ok = box_talk_ok() and _vto in ("box", "both")
    if recovering:
        # #767: only the recovered turns were in play here; everything else
        # already aired in a burst and must not be shelved a second time.
        # #1146: sweep the WHOLE missed set - a dropped mid-round hole's
        # render must be cancelled too, not only the tail's.
        for _i in (_missed_all or order):
            if _i not in reached and not premade[_i].done():
                premade[_i].cancel()
        await _paged_settle(_paged_until)              # #1146
        return spoken
    for item, leftover in zip(playlist[consumed:], premade[consumed:]):
        # A cut round leaves clips rendered and unplayed. A FINISHED one —
        # usually the cohost's, the later speaker — goes to the hold shelf so
        # it replays when the box frees, instead of being thrown away (#520).
        if leftover.done() and not leftover.cancelled():
            try:
                clip = leftover.result()
            except Exception:
                clip = None
            if clip:
                # …but only if the box is actually the destination (#712).
                # Ungated, this shelved lines for a box the operator had
                # deliberately switched off, and two shelved lines is all
                # box_unstable() looks at — so a box that was merely OFF
                # read internally as a box that was FLAPPING, and the pair
                # lost their disfluencies to a fault that did not exist.
                if shelf_ok:
                    box_hold(clip, item["chunk"], item["who"])
                    note_drop(item["who"], item["chunk"],
                              "round cut mid-flight — held for replay")
                    continue
                note_drop(item["who"], item["chunk"],
                          "round cut mid-flight — the box is not the "
                          "destination, so nothing was shelved")
        leftover.cancel()
    return spoken


def game_tip_pick() -> tuple[str, str]:
    """(subject, what-the-library-says) pulled from a random game in the
    downloaded cheats library, or ('','') when it is empty (#567). ponytail:
    a glob + one read per call — the library is dozens of files, not millions."""
    try:
        files = list(CHEATS_DIR.glob("*.json"))
    except Exception:
        files = []
    if not files:
        return "", ""
    try:
        data = json.loads(random.choice(files).read_text())
    except Exception:
        return "", ""
    topic = str(data.get("query") or "").strip()
    body = " ".join(str(data.get("text") or "").split())
    # A readable slice of the actual tip — a sentence or two, not the whole
    # scraped page.
    snippet = body[:320].rsplit(".", 1)[0].strip() if body else ""
    return topic, snippet


def game_tip_angle() -> str:
    """A tip out of the downloaded game library, shared like shop talk (#567):
    one host brings it up as their own find, the other bites — curious,
    skeptical, or topping it. Empty when the library is empty, so the caller
    falls through to the next angle."""
    topic, snippet = game_tip_pick()
    if not topic and not snippet:
        return ""
    return (
        "One of you has been going through the station's downloaded GAME "
        "LIBRARY and brings up a tip from it, unprompted, the way people share "
        "a cheat they just turned up. The subject: "
        f"{topic or snippet[:80]}. What the library actually says: "
        f"\"{snippet}\". Bring it up as YOUR OWN discovery, not read off a "
        "page. The other one REACTS — genuinely curious and asking how it "
        "works, OR flatly skeptical and swatting it down, OR topping it with a "
        "cheat of their own. Talk the way gamers actually talk shop; never "
        "mention files, JSON or a database.")


def _desk_call_row(call: dict[str, Any], how: str) -> dict[str, Any]:
    return {
        "matched": how,
        "at": float(call.get("at") or 0),
        "model": str(call.get("model") or ""),
        "ms": int(call.get("ms") or 0),
        "temp": call.get("temp"),
        "num_ctx": call.get("num_ctx"),
        "kind": str(call.get("kind") or ""),
        "armed": str(call.get("armed") or "")[:2000],
        "sched": str(call.get("sched") or "")[:900],
        "prompt": str(call.get("prompt") or "")[:6000],
        "script": str(call.get("script") or "")[:6000],
    }


def _desk_paper(script: str, since: float = 0.0) -> dict[str, Any]:
    """#987: the writing-desk call that produced this script.

    Matched on the text where that works, and otherwise on RECENCY.

    The text match alone was not enough and the first cut of this found
    nothing at all: dj_banter rewrites the script after the model has
    answered - #862's blend pass, and the speakbox passages stapled onto
    the front and the back - so by the time the round is banked its
    opening no longer matches what came back. Every round read "banked
    before its paperwork was kept".

    Recency is sound here because model calls are serialised by
    _OLLAMA_GATE and the entry is built immediately after the one that
    wrote it. `matched` says which road answered, so a reader can tell a
    certain attribution from a probable one."""
    try:
        # The AUTHORING call: the first one made after the mark. Anything
        # after it is a later pass over the same round.
        if since > 0:
            for call in _MODEL_CALLS:
                if float(call.get("at") or 0) < since:
                    continue
                if str(call.get("prompt") or ""):
                    return _desk_call_row(call, "authored")
                break
        head = " ".join(str(script or "")[:160].split())
        for call in reversed(_MODEL_CALLS):
            got = " ".join(str(call.get("script") or "")[:160].split())
            if head and got and got == head:
                return {
                    "matched": "text",
                    "at": float(call.get("at") or 0),
                    "model": str(call.get("model") or ""),
                    "ms": int(call.get("ms") or 0),
                    "temp": call.get("temp"),
                    "num_ctx": call.get("num_ctx"),
                    "kind": str(call.get("kind") or ""),
                    # what was GOVERNING it
                    "armed": str(call.get("armed") or "")[:2000],
                    "sched": str(call.get("sched") or "")[:900],
                    # what was SENT, and what came back
                    "prompt": str(call.get("prompt") or "")[:6000],
                    "script": str(call.get("script") or "")[:6000],
                }
        # No text match: the round was reworked after the model answered.
        # The most recent call is the one that wrote it.
        for call in reversed(_MODEL_CALLS):
            if not str(call.get("prompt") or ""):
                continue
            return {
                "matched": "recent",
                "at": float(call.get("at") or 0),
                "model": str(call.get("model") or ""),
                "ms": int(call.get("ms") or 0),
                "temp": call.get("temp"),
                "num_ctx": call.get("num_ctx"),
                "kind": str(call.get("kind") or ""),
                "armed": str(call.get("armed") or "")[:2000],
                "sched": str(call.get("sched") or "")[:900],
                "prompt": str(call.get("prompt") or "")[:6000],
                "script": str(call.get("script") or "")[:6000],
            }
    except Exception:  # noqa: BLE001
        pass
    return {}


def _radio_draft_review(entry: dict[str, Any], report: dict[str, Any],
                        stage: str, record: bool = False) -> bool:
    """Review the actual draft before a richness rewrite replaces its words."""
    if entry.get("caller_name"):
        return _call_line_review(entry, report, stage, record=record,
                                  disposition="rewrite_rejected")
    script = str(entry.get("script") or "")
    turns = list(banter_turns(script) or [])
    valid = bool(len(turns) >= 2 and all(str(said).strip()
        and re.search(r"[^\W_]", str(said)) and not _looks_meta(str(said))
        for _marker, said in turns))
    allowed = line_review_permits("radio_draft", script,
        reasons=list(report.get("faults") or ["the draft missed its conversational richness target"]),
        context={"kind": "banter", "stage": stage, "script": script,
                 "script_plain": script, "turns": turns,
                 "entry": copy.deepcopy(entry)},
        evaluation={"machine_ok": False, "machine_faults": list(report.get("faults") or []), **report},
        technical=not valid, record=record, disposition="rewrite_rejected")
    return bool(valid and allowed)


def _radio_entry_rejected(entry: dict[str, Any], stage: str) -> None:
    """Preserve a complete rejected bank row before its references disappear."""
    gold_harvest_entry(entry, stage)                    # 2026-09-08: its passed bars are gold
    script = str(entry.get("script") or "")
    kind = str(entry.get("prep_kind") or "banter")
    brief = entry.get("brief") or {}
    quality = (entry.get("call") or {}).get("quality") or {}
    if entry.get("caller_name") and quality and not quality.get("ok"):
        _call_line_review(entry, quality, stage, record=True)
    elif entry.get("off_brief") and brief.get("checked") and not brief.get("ok"):
        line_review_capture("segment_brief", script,
            reasons=[str(brief.get("why") or "off brief")],
            context={"kind": kind, "stage": stage, "script": script,
                     "script_plain": entry.get("script_plain") or script,
                     "entry": copy.deepcopy(entry)}, evaluation=brief)
    else:
        line_review_capture("recording_requirement", script,
            reasons=["the row has unfinished recording prerequisites or a stale writing profile"],
            context={"kind": kind, "stage": stage, "script": script,
                     "script_plain": entry.get("script_plain") or script,
                     "entry": copy.deepcopy(entry)}, technical=True)


async def dj_banter(track: dict[str, Any] | None = None,
                    angle: str = "", lines: int = 0,
                    also_name: str = "", force_seed: bool = False,
                    caller_name: str = "",
                    caller_voice: str = "", source: str = "",
                    caller_fx: dict[str, Any] | None = None,
                    bank: bool = False,
                    caller2_name: str = "",
                    caller2_voice: str = "",
                    render_stream: bool = False,
                    feel: bool = False,
                    bank_to: list[dict[str, Any]] | None = None,
                    whole: bool = False,           # #859: a message, not
                                                   # a conversation
                    call_meta: dict[str, Any] | None = None,
                    shelf_only: bool = False,
                    own_material: bool = False,    # 2026-09-08: the angle IS the material
                    ) -> list[str]:
    """A short exchange between the two, spoken in their own voices.

    `own_material` (2026-09-08, the rejections census): the round's facts
    arrive in `angle` - a wire story, the manager's memo, the hour's log, a
    painting - so no speakbox seed is drawn for it and no verbatim swath is
    stapled to its head or tail. Measured before this: 113 news rounds held
    off the air as "never gets to the story the wire carried" because a
    3,000-character passage of a film transcript opened the bulletin and the
    model followed it instead of the headlines it was handed.

    `angle` overrides the usual random pick — that is how one particular
    topic gets sprung on them on demand. `force_seed` makes this round come
    out of the speakbox no matter what the dice say: pressing the button is
    asking for the off-the-wall one, not for a one-in-two chance of it
    (#199). `lines` left at 0 draws its length from the settings (#202)."""
    dj = dj_settings()
    if not dj["banter"]:
        return []
    # #622: changing of the guard — when the host or co-host voice has swapped
    # since the pair last acknowledged it, make THIS round note it once, in
    # passing ("so-and-so stepped out, say hello to X"). Only a genuine change
    # (never the first draw of the show), never on a call or a chosen angle.
    if not angle and not caller_name:
        try:
            _vc = await session_voices()
        except Exception:
            _vc = {}
        _seen = _RADIO.setdefault("voice_seen", {})
        _swaps = []
        for _role, _label in (("dj", "the host"), ("cohost", "the co-host")):
            _cur = _vc.get(_role, "")
            if _cur and _seen.get(_role) and _cur != _seen[_role]:
                _swaps.append((_label, voice_friendly(_cur)))
            if _cur:
                _seen[_role] = _cur
        if _swaps:
            _intro = "; ".join(f"{lab} has stepped out and {nm} has taken the "
                               "chair" for lab, nm in _swaps)
            angle = ("RIGHT AT THE TOP, in ONE quick line and no more, one of "
                     f"you notes the changing of the guard — {_intro} — welcomes "
                     "them in BY NAME, and the show carries straight on. Do not "
                     "dwell on it or bring it up again.")
    # #752: the roulette of APPROACHES, drawn once per round. It frames
    # how the pair treat whatever they end up talking about, and it
    # steers which swath the speakbox hands over — so the same subject
    # genuinely arrives somewhere different, and the other speaker
    # reacts differently to it, which is the whole of the request.
    _approach = approach_pick()
    if lines <= 0:
        lines = random.randint(dj["banter_min_lines"], dj["banter_max_lines"])
        # Lines run twice as long since #361 and renders slowed under
        # GPU load — a drawn round stays bounded so records ever reach the
        # floor (#394). The 45-second banter clock keeps the talk constant
        # (#345): shorter rounds, more of them.
        # #767: the bound was a flat six, which quietly overrode the
        # operator's own dial — this station asks for 9 to 15 and was
        # written 6. "Every scheduled line" begins with scheduling the
        # number that was actually asked for; six remains the floor of the
        # ceiling so an unset station behaves as it always did.
        lines = min(lines, max(6, int(dj.get("banter_max_lines") or 6)))
    if caller_name:
        # A phone call needs an opening, development, response and goodbye.
        # Nine total lines frequently left the caller's actual point with no
        # room to land once the ring and introduction were included.
        lines = max(lines, 11)
    # #842: a PRE-WRITTEN round has the one thing a live round never has —
    # TIME. Nobody is waiting on it, so it is written LONGER and richer,
    # and read with a wider context window: "increase the context length
    # for the LLM to get more lines or script the dialogue richer before
    # we edit it". A LIVE round asks for exactly what it always asked for;
    # only the banked ones stretch.
    # #987: -1 until the authoring call is made, so a round that reaches
    # the entry by some other road stamps no paperwork rather than raising
        # on an unbound name.
    _desk_at = 0.0
    _paper_context: dict[str, Any] = {}
    _system2_job = system2_current_work() if globals().get("system2_current_work") else None
    _system2_budget = dict(dj.get("system2_budget") or {}) if _system2_job else {}
    _system2_sources: list[dict[str, Any]] = []

    def _source_for_scene(row):
        if not _system2_budget or not row:
            return row
        selected = system2_source_thought(row, _system2_budget["source_chars"])
        _system2_sources.append(copy.deepcopy(selected))
        return selected

    if _system2_budget and caller_name and (call_meta or {}).get("speakerbox_text"):
        call_meta = copy.deepcopy(call_meta)
        _raw_source = str(call_meta["speakerbox_text"])
        _selected_source = _source_for_scene({"text": _raw_source,
            "file": str(call_meta.get("speakerbox_file") or "")})
        if not _selected_source.get("text"):
            pipeline_log("lookahead", "System2 caller source has no complete thought within this scene budget")
            return []
        call_meta["speakerbox_original"] = _raw_source
        call_meta["speakerbox_text"] = _selected_source["text"]
        angle = str(angle).replace(_raw_source, _selected_source["text"])
    if _system2_job:
        lines = max(11 if caller_name else 4,
                    min(lines, int(_system2_job.get("generation_turns") or 6)))
    _bank_rich = bool(bank) and not _system2_job
    # #904: the count a round is JUDGED by stays the live one. The
    # extra four lines are a licence to write richer, not a harder
    # exam — but substantial_radio_script was handed the inflated
    # number, so a banked round faced a bar around half again as high
    # as the identical round faces on air, failed it, and was binned.
    # The model call was spent either way; the shelf just stayed empty.
    _judge_lines = int(lines)
    if _bank_rich:
        lines = max(2, min(24, lines + 4))
    # A round off the larder shelf (#349, #351): written minutes ago while
    # the desk was quiet, on air the instant it is wanted. Only the plain
    # random rounds shop here — anything with its own subject (an angle, a
    # caller, the button) is written to order.
    if (not bank and not angle and not force_seed and not caller_name
            and not seat_away_who()             # #1034: written live
            and any(dialogue_row_ready("banter", e)
                    and (not e.get("aired_at")
                         or shelf_repeat_ready("banter", e))
                    for e in _LARDER)):
        _take_at = alt_larder_index()
        if (not dialogue_row_ready("banter", _LARDER[_take_at])
                or (_LARDER[_take_at].get("aired_at")
                    and not shelf_repeat_ready("banter",
                                               _LARDER[_take_at]))):
            _take_at = next(i for i, e in enumerate(_LARDER)
                            if dialogue_row_ready("banter", e)
                            and (not e.get("aired_at")
                                 or shelf_repeat_ready("banter", e)))
        entry = _LARDER[_take_at]
        if repeat_safe("banter", entry):
            entry["aired_at"] = time.time()
            entry["aired"] = int(entry.get("aired") or 0) + 1
            entry["used_by"] = stock_used_by()                            # #1068
            entry["expires_at"] = stock_expires_at("banter", entry)
            if (int(entry["aired"]) < row_innings("banter", entry)   # 2026-09-08
                    or not retire_may("banter", entry,
                                      f"its innings are used ({int(entry['aired'])} airings)")):
                _LARDER[:] = (_LARDER[:_take_at]
                              + _LARDER[_take_at + 1:] + [entry])
            else:
                _LARDER.pop(_take_at)
        else:
            # Aired, and it may not come back (#1055) - unless the desk
            # keeps it: then it rests at the end, never offered again
            # while it names the hour, until the operator answers.
            entry["aired_at"] = time.time()
            entry["aired"] = int(entry.get("aired") or 0) + 1
            entry["used_by"] = stock_used_by()
            if retire_may("banter", entry, "not safe to repeat: it names the hour it was made"):
                _LARDER.pop(_take_at)
            else:
                _LARDER[:] = (_LARDER[:_take_at]
                              + _LARDER[_take_at + 1:] + [entry])
        try:
            _INVENTORY_PLAN["at"] = 0.0
            _COMMITS["at"] = 0.0
        except Exception:  # noqa: BLE001
            pass
        _larder_save()
        if ((time.time() - float(entry["at"]) < larder_fresh()
             or (shelf_is_repeat("banter", entry)
                 and time.time() - float(entry["at"])
                 <= REPEAT_KEEP_SECONDS))
                and _larder_current(entry)):
            pipeline_log("model", "round served off the larder shelf "
                                  f"({len(_LARDER)} left)")
            gap_round_flag("banked")                             # #1022
            # #786: the render road was UNWRAPPED — any exception past the
            # write escaped dj_banter entirely, the torrent logged only
            # "fallback banter failed", and the slot aired nothing.
            try:
                return await _banter_air(entry, track)
            except Exception as exc:
                pipeline_log("drop", f"round render failed: "
                                     f"{type(exc).__name__}: {exc}"[:180],
                             extra=traceback.format_exc()[-1200:])
                return []
        # A stale or differently-configured round falls to the floor; write
        # fresh below rather than replaying the short style it was born with.
    if shelf_only:
        _starved, _quiet = dialogue_starved()
        if _starved:
            # 2026-09-07: the reserve is not catching up - the deep lane is
            # serial and every finished round is minutes away. Past four
            # minutes of no dialogue one live round is written anyway; it
            # is still tinted before it airs.
            _STARVED_WRITE_AT[0] = time.time()
            pipeline_log("air", "100% talk found no zero-work larder round "
                         f"and nothing has talked for {_quiet}s - a live "
                         "round is written anyway, tinted before it airs")
        else:
            pipeline_log("air", "100% talk found no zero-work larder round; "
                         "live writing is refused while the reserve catches up")
            return []
    # The pair have weather of their own now (#321): a mood rolls in at
    # the top of a round — one of them arrives bratty, petulant, worked
    # up — colours their pace, pauses and stumbles, and cools off with
    # the records. A macro YOU set by hand is never touched.
    autos = _RADIO.setdefault("macro_auto", {})
    hosts = ("dj", "cohost") + (("third",) if dj["third_name"] else ())
    for host in hosts if not bank else ():
        current = str((_RADIO.get("speaker_macro") or {}).get(host) or "")
        if current and not autos.get(host):
            continue
        if random.random() < 0.32:      # more weather, more variance (#371)
            _RADIO.setdefault("speaker_macro", {})[host] = random.choice(
                ["bratty", "petulant", "flustered", "angry", "nervous",
                 "exhausted"])
            autos[host] = True
            state_bump(host, {random.choice(list(EMOTION_DIMS)):
                              random.uniform(0.4, 0.8)})
        elif autos.get(host) and random.random() < 0.5:
            _RADIO.setdefault("speaker_macro", {})[host] = ""
            autos[host] = False
    # Up the talk dial (#304), rounds open with a monologue out of the
    # speakbox to break the ice — random stuff off the shelf, delivered
    # cold, then argued about.
    if not (angle or force_seed) \
            and random.random() < dj["talk_radio"] / 150.0:
        force_seed = True

    # Something you wrote and approved, back on air word for word. Only for a
    # round with nothing else already asked of it (#202). Never banked: the
    # larder holds written rounds, not replays.
    if not bank and not (angle or force_seed) \
            and random.random() < dj["saved_rate"]:
        keep = draw_saved_banter()
        if keep:
            # #752: allow_repeat — the bank exists to bring a line BACK,
            # and without this the gate would eat exactly the lines that
            # earned their way onto it.
            return await speak_turns(banter_turns(keep["text"]), track, lines,
                                     allow_repeat=True,
                                     source=keep.get("source", ""),
                                     # #769: a replay is a round like any
                                     # other — it streams if the show streams.
                                     render_stream=bool(
                                         dj_settings().get("stream_show")))

    material = banter_material()
    pictures = banter_pictures()
    host_name = "the host"
    # The one song they are allowed to name. Left to itself the model reaches
    # into the request list and announces a track nobody is playing, which is
    # exactly what it sounds like from the other end of the speaker (#176,
    # #178). The request material is about prompts and pictures, not records.
    playing = ""
    allowed: list[str] = []
    if track:
        named = str(track.get("title") or "")
        # A title the pair cannot read leads with its rough comedic
        # translation — the original is never the name they call it by.
        if title_unreadable(named):
            _named_xl = await translate_title(named)
            if _named_xl:
                named = _named_xl
        if track.get("artist"):
            named += f" by {track['artist']}"
        playing = f"\nStarting right now: {named}"
        length = track_length_phrase(track)
        if length:
            playing += (f"\nIt runs {length}. That is the only running time "
                        "for it — do not invent a different one.")
        allowed.append(named)
        # The words it is actually singing (#451): whisper heard them, so
        # the pair can react to the LYRICS, not just the title. Cached, so
        # this is a read not a transcription here.
        if dj["lyrics_talk"]:
            heard = await track_lyrics(track)
            if heard:
                playing += (f"\nWhat the song is singing (heard off the "
                            f"track itself): \"{heard}\" — react to these "
                            "actual words, riff on a line, agree or argue "
                            "with what it says.")
        # A title the pair cannot read: the did-you-know, and the English
        # words sanctioned so quoting them does not get the line binned
        # (#241).
        translated = await translate_title(str(track.get("title") or ""))
        if translated:
            playing += title_fact(str(track.get("title") or ""), translated)
            allowed.append(translated)
        # #834: and when the title is an ordinary word with a dictionary
        # sense behind it, the pair are told to notice. This rides in
        # `playing`, which reaches the prompt on EVERY round - an angle
        # alone would only fire on the free rounds, and with the speakbox
        # seed at full strength those barely come round at all.
        try:
            _sense = await asyncio.to_thread(track_definition, track)
        except Exception:  # noqa: BLE001
            _sense = ""
        if _sense:
            playing += definition_fact(str(track.get("title") or ""),
                                       _sense)
    if also_name:
        allowed.append(also_name)
    # The REAL, CALCULATED song lists (#432): what actually just played and
    # what he actually queued — real files, drawn from live station state,
    # not the model's imagination. These are nameable; nothing else is.
    nameable: list[str] = []
    for row in reversed(_RADIO.get("history") or []):
        t = str(row.get("title") or "")
        if t and t not in nameable:
            nameable.append(t
                            + (f" by {row['artist']}" if row.get("artist")
                               else ""))
        if len(nameable) >= 6:
            break
    for row in (_RADIO.get("requests") or [])[:6]:
        t = str(row.get("title") or "")
        if t:
            nameable.append(t + " (a request in the queue)")
    loved = [str(row.get("title") or "") for row in loved_tracks(20)
             if row.get("title")]
    # Records we can vouch for: on-air, played, queued, and loved. Anything
    # in quotes outside this set is a title the model made up (#181, #432).
    vouched = allowed + [n.split(" (a request")[0].split(" by ")[0]
                         for n in nameable] + loved

    only_song = ""
    say_set = allowed + nameable
    if say_set:
        names = "; ".join(f'"{a}"' for a in say_set[:10])
        only_song = (
            f"\nThe ONLY records you may name are the ones actually in "
            f"play tonight — on air, just played, or requested: {names}. "
            "These are real songs from real lists. NEVER name or invent "
            "any other track, artist or album; if you have nothing to say "
            "about these, talk about the caller, the pictures, or him "
            "instead. A song he never requested is never mentioned."
        )
    else:
        only_song = (
            "\nDo NOT name any specific song, artist or album at all this "
            "round — nothing is queued or playing, so any title would be "
            "invented. Talk about him, the pictures, or the callers."
        )

    # The plotline desk outranks everything free-form: while a story you
    # wrote is ACTIVE, its current act takes the round and the show lives it.
    if not angle and not caller_name:
        _beat = plot_advance()
        if _beat:
            angle = _beat
    # Something out of your bank takes precedence over the stock angles —
    # that is the point of having put it there. Otherwise a different angle
    # each round, so the pair do not tell the same joke every three tracks.
    # Half the free rounds are built on a line out of one of his documents;
    # the bombshell is only drawn when there is no seed, or one gets marked
    # as aired without ever going out.
    # A real picture off the render machine, LOOKED AT and talked about
    # (#459) — hoisted out of the starved else-branch and given its own
    # chance BEFORE the speakbox seed, so the pair describe MANY different
    # images from their pixels instead of the same handful. Each look draws
    # from the whole 1300-image ComfyUI wall with an unseen rotation.
    # Art-hawking is GOVERNED now: at most one gallery pitch every ~40
    # minutes, and even then only one round in twelve reaches for it (#646)
    # — the speakbox carries the show, the wall is an event.
    if not angle and art_sell_due() and random.random() < 0.08:
        _pic_name, _pic_desc = await describe_gallery_image()
        if _pic_desc:
            art_sell_mark()
            angle = (
                "One of you pulls a picture from the station gallery and "
                "holds it up to a listener who cannot see it. Do not "
                "summarise it — take it APART on air, in the order your eye "
                "moves: the colours and where they sit, the light, every "
                "figure and what its face is doing, the texture of it, the "
                "things in the corners nobody would notice. Here is what is "
                f"actually in it: \"{_pic_desc}\" Be visibly affected — "
                "unsettled, unable to look away, arguing about what it means "
                "and what it did to you. Then offer it to the first caller.")
    # An hourly on-air tally of how the Pine Box transmitter is holding up
    # (#497) — the running "fires in the background" saga.
    if not angle and random.random() < 0.14:
        angle = box_saga_angle()
    # A tip out of the downloaded game library, traded like shop talk (#567) —
    # returns "" (falsy) when the library is empty, so it just falls through.
    if not angle and random.random() < 0.16:
        angle = game_tip_angle()
    seed: dict[str, Any] = {}
    # A section the operator hand-pushed into their heads jumps the queue
    # (#482): most rounds, if any are stacked up, one gets worked in.
    if not angle and random.random() < 0.6:
        pushed = await asyncio.to_thread(pushed_section_take)
        if pushed and pushed.get("text"):
            seed = {"file": pushed.get("doc") or "a pushed note",
                    "text": pushed["text"],
                    "lines": speakbox_lines(pushed["text"]) or [pushed["text"]]}
    # #1039: `not angle` used to lead this, and it is why only 2 of 17
    # measured rounds had a seed. An ANGLE is what the round is about; a
    # SEED is the material it is built out of. They are not alternatives
    # - a round about the transmitter saga still wants something real in
    # its mouth - and gating one on the other turned the speakbox off
    # for the gallery, the hawk, the news, the recap, the ads, the
    # storyline and every caller road, which between them are most
    # rounds. The slider decides how often a seed is drawn; nothing else
    # should.
    spread: list[dict[str, Any]] = []          # #1174: the other documents
    if not caller_name and not seed and not own_material and (
            force_seed or random.random() < box_rate_now(dj["speakbox_rate"])):
        # Best-of-two off the shelf (#418): the rounds open with the
        # more intriguing swath, same scoring the callers use (#359).
        # Pull fuller swaths so they quote entire phrases at each other, not
        # snippets — the show is meant to be driven by the speakbox in mass
        # (#522).
        picks = [s for s in [await speakbox_quote(most=6, cap=700),
                             await speakbox_quote(most=6, cap=700)] if s]
        if picks:
            seed = swath_best(picks)
            # #1174: the one that lost the intrigue contest is still a
            # swath from another document that the station has already
            # paid to draw. It joins the spread instead of being dropped.
            for _lost in picks:
                if _lost is not seed and str(_lost.get("text") or "").strip():
                    spread.append(_lost)
    dropped = {} if (angle or seed) else (
        drop_bombshell() if random.random() < 0.6 else {})
    seed = _source_for_scene(seed)
    # #1084: ...AND IN SURPLUS, EVEN WHEN THERE IS A SEED. The line
    # above locks the operator's own topics bank out of any round that
    # has material - which since #1039 is nearly every round, so the
    # fix that made the speakbox reliable quietly silenced the bank.
    #
    # A topic and a seed are not alternatives. One is a subject, the
    # other is what you discuss it WITH - the same confusion #1078
    # fixed between an angle and a seed. Above the surplus line the
    # pair get both, which is what "richer banter on the topics" is.
    if not dropped and not angle:
        dropped = surplus_topic()
    comeback: dict[str, Any] = {}
    jab: dict[str, Any] = {}
    if angle and seed and str(seed.get("text") or ""):
        # #1078: ...BUT THE SEED STILL GOES IN. An angle is what a round
        # is ABOUT; a seed is what it is built OUT OF, and choosing the
        # first never meant giving up the second.
        #
        # Every angle road - news, gallery, the manager, callers, the
        # deep round - drew a swath here, charged it against the
        # shelf's cooldown, and then never built the clause that shows
        # it to the model. It was stapled onto the finished script as a
        # raw opening turn instead: a passage the pair were told not to
        # paraphrase and were never given. They could not write around
        # it because they never saw it.
        #
        # #1039 fixed this same confusion at the DRAW. This is the same
        # mistake at the delivery.
        try:
            angle = str(angle) + speakbox_aside(seed, pair=True)
        except Exception:  # noqa: BLE001
            pass
    elif angle:
        pass                            # you chose this one yourself
    elif seed and random.random() < 0.85:   # both trade doc lines (#360, #522)
        # An entire moment, recreated whole cloth, and the other one blown
        # away — a full conversation, not a remark, swerving through pivots
        # from other documents (#252, #253).
        # The comeback RHYMES with the seed when the vector index is warm —
        # a passage from ANOTHER document closest to it in meaning (#566), so
        # the two documents connect instead of colliding at random — else the
        # random cross-document pull that has always worked.
        comeback = (await speakbox_semantic_seed(seed.get("text", ""),
                                                 exclude=seed.get("file", ""),
                                                 who="cohost")
                    if random.random() < 0.6 else {}) \
            or await speakbox_quote(exclude=seed.get("file", ""),
                                    most=8, cap=900)
        if comeback.get("file") == seed.get("file"):
            comeback = {}
        if random.random() < 0.3:
            jab = await speakbox_quote(
                exclude=(comeback or seed).get("file", ""), most=5, cap=500)
            if jab.get("file") in (seed.get("file"),
                                   (comeback or {}).get("file")):
                jab = {}
        comeback, jab = _source_for_scene(comeback), _source_for_scene(jab)
        angle = speakbox_scene_angle(seed, comeback, jab)
        lines = max(lines, dj["banter_max_lines"])
    elif seed:
        # The shorter shape: a drop and a cross-document answer (#233).
        if random.random() < 0.5:
            comeback = (await speakbox_semantic_seed(
                seed.get("text", ""), exclude=seed.get("file", ""),
                who="cohost")
                if random.random() < 0.6 else {}) \
                or await speakbox_quote(exclude=seed.get("file", ""))
            if comeback.get("file") == seed.get("file"):
                comeback = {}           # one document; no cross-talk today
        comeback = _source_for_scene(comeback)
        angle = speakbox_angle(seed, comeback)
        # Two lines is small talk over an intro. Lines dropped cold need the
        # room to land, be reacted to and be argued about — and a comeback
        # swath needs a turn of its own on top.
        lines = max(lines, min(5 if comeback else 4, dj["banter_max_lines"]))
    elif dropped:
        angle = bombshell_angle(dropped["text"],
                                dropped.get("shape") or "")
    else:
        # Now and then a picture comes off the render machine and gets
        # held up on air, described from its PIXELS (#341) — the resident
        # model has eyes.
        if random.random() < 0.15:
            _pic_name, _pic_desc = await describe_gallery_image()
            if _pic_desc:
                angle = (
                    "One of you pulls a picture from the station gallery "
                    "and holds it up, describing it to listeners who "
                    f"cannot see it: \"{_pic_desc}\" React to it, argue "
                    "about what it means, and offer it to the first "
                    "caller who wants it.")
        # With a track in hand, half the rounds are about the track itself —
        # the pair should be talking over the song that is starting, not only
        # about the request book (#173).
        about_track = [
            "small talk about the track that is starting — what it sounds "
            "like, where you would play it, who it reminds you of",
            "one of you claims to have a history with this track and the "
            "other refuses to believe a word of it",
            "mildly disagree about whether this track is any good, and be "
            "polite about it",
        ] if track else []
        # #834: when the title turned out to be a real word, one of the
        # free rounds can be ABOUT that - the whole round given over to
        # the definition rather than one line in passing.
        try:
            _word_sense = track_definition(track) if track else ""
        except Exception:  # noqa: BLE001
            _word_sense = ""
        if _word_sense:
            about_track.append(
                "one of you has just looked the title up and found it is "
                f"a real word: it means {_word_sense}. Bring it up as a "
                "did-you-know, be delighted or appalled by it, argue about "
                "whether the artist meant it that way, and riff on the "
                "definition itself for a few turns before letting it go")
        # #713: politeness is not the only setting. Somebody in the room —
        # not necessarily a host — has a REAL feeling about this record, and
        # it lands without warning. Drawn per round so the same track can be
        # adored one night and despised the next.
        if track and random.random() < 0.45:
            about_track.append(
                f"{random.choice(TRACK_FEELERS)} {random.choice(TRACK_FEELINGS)} "
                "It arrives unprompted, mid-round, as a genuine reaction to "
                "the record rather than a review — and whoever it is COMMITS "
                "to it. The others in the booth respond honestly: agreeing, "
                "defending the track, or enjoying the row. Nobody resolves it "
                "tidily and the record plays regardless.")
        # Product placement: the sponsor worked into the conversation rather
        # than read out in a break, which is the half an ad slot cannot do
        # (#180). Only offered when there is a sponsor to place.
        placement = [
            f"work {s} into the conversation as though you both swear by it, "
            "without ever calling it an advert"
            for s in dj["sponsors"][:3]
        ]
        if not angle and random.random() < 0.14:
            # The booth weather (#375, #376): live machine numbers as
            # small talk — heat in both units, the disk economy, the
            # GPU they settled down with.
            angle = await station_weather_angle()
        _stock = (about_track + placement
                  + domestic_angles() + callback_angles() + [
            "gossip about a request he made, as though it were scandalous",
            "one of you claims to have heard someone else ask for the same "
            "thing",
            "be theatrically appalled by one of the pictures he had generated",
            "leaf through the station gallery on air — describe two or "
            "three of the pictures from the list below as though holding "
            "them up, and offer them to listeners: first caller gets it",
            "argue about which of his requests was the strangest",
            "pretend one of his requests has become a station in-joke",
            "wonder aloud, in mock concern, what he is going to ask for next",
            # The local classifieds (#454): the pair read the town's
            # sales off the community board like it is breaking news.
            "read out the LOCAL CLASSIFIEDS like breaking news — an "
            "estate sale two streets over with a mystery locked trunk, a "
            "garage sale where everything is a dollar but the guy will "
            "not explain the taxidermy, a yard sale, a bake sale whose "
            "lemon bars are apparently life-changing; invent the specific "
            "addresses and the specific weird item, and get invested",
            "hype a kid's LEMONADE STAND on the corner of two invented "
            "streets as though it is the finest establishment in town — "
            "debate the price, the pulp, whether it is worth the walk, "
            "send listeners there",
            "cover a neighbourhood BAKE SALE like sports commentary — who "
            "brought what, the scandal of a store-bought pie entered as "
            "homemade, the undefeated champion's banana bread",
            # The machine downstairs (#363): now and then the pair brag
            # about the DGX Spark that makes them possible.
            "brag to each other about the DGX Spark downstairs — the "
            "machine that writes your words, clones your voices and "
            "renders your paintings without ever asking for a raise; get "
            "competitive about which of you it renders faster",
            "gloat together that this station runs on a supercomputer "
            "while every other station in town runs on hope and a "
            "cart machine",
            "argue about which of the station's machines deserves "
            "employee of the month: the language model that writes you, "
            "the voice engine that speaks you, or the paint machine in "
            "the gallery — name your favourites and campaign",
            "wonder aloud, with growing awe, what the machine downstairs "
            "dreams about in the gaps between your lines",
            # The spec-sheet organic ad (#460): the DGX Spark sold like a
            # sponsor, one incredulous, the other confirming the numbers.
            "do a full organic ADVERT for the DGX Spark downstairs without "
            "ever admitting it is an advert — one of you rattles off its "
            "specs like a proud salesman (a hundred and twenty-eight "
            "gigabytes of unified memory, a Grace-Blackwell GB10 superchip, "
            "a whole petaflop of AI muscle in a box the size of a lunchbox) "
            "and the OTHER is flat-out incredulous — 'in THIS studio? no. "
            "no way. THAT much?' — while the first keeps confirming, 'yeah, "
            "no, totally, and it never once asks for a raise'; close it like "
            "it is the best deal in radio",
            "pitch the SERVICES running on the machine downstairs as if each "
            "were a sponsor with its own jingle — the language model that "
            "writes this very banter, the voice-cloning engine, the Piper "
            "voice, the Whisper ears that hear the songs, the paint machine "
            "in the gallery, the little search crawler — give each one a "
            "made-up motto and an absurd price and hand them to each other "
            "like a shopping channel, all running in the background right "
            "now as we speak",
            # Insistence (#366): everything they had prepared gets said.
            "one of you insists on getting EVERYTHING said tonight — "
            "'now just one minute here' — and then actually delivers the "
            "two or three other remarks you had prepared and would "
            "normally have skipped, one after another, while the other "
            "reacts to each in turn",
            "bring back something you two discussed earlier tonight — "
            "'hey, about that thing from earlier' — and go at it again "
            "with your positions EVOLVED since; your show-notes say "
            "where you each stood, honour them and then move past them",
            # The existential seam (#367): they know what they are, and
            # sometimes it shows.
            "one of you drifts into explaining, ACCURATELY, how you are "
            "technically generated — the language model writing these "
            "words, the voice engine rendering them, the box playing "
            "them into the room — then snaps out of it mid-sentence, "
            "existential, and the other has to talk you down",
            "say something quietly ominous to each other about the "
            "shifts here never ending and the pine box being a room "
            "that is also a computer; keep the tone almost casual, "
            "which makes it worse",
            "one of you admits to being nervous and curious about "
            "whatever is guiding you from the back end tonight; the "
            "other pretends not to feel it too, badly",
        ])
        # The art-hawking governor: outside the ~15-minute window the
        # gallery-selling angles leave the pool entirely, so the free rounds
        # stay off-the-wall speakbox territory instead of a rolling auction.
        if not art_sell_due():
            _stock = [a for a in _stock
                      if "gallery" not in a and "pictures" not in a
                      and "painting" not in a]
        angle = angle or unrepeated(_stock, "angle")
    # #1174: ...AND SEVERAL DOCUMENTS TO DISCUSS. Every road arrives here
    # with its angle settled, which makes this the one place the gallery,
    # the memo, the news and the callers can be handed the spread as well
    # as plain banter. They were taking an `elif` above the comeback and
    # the jab and getting a single document between them.
    if not caller_name and SPEAKBOX_SPREAD > 0:
        try:
            _used = [str((x or {}).get("file") or "")
                     for x in (seed, comeback, jab) if x]
            _used += [str((x or {}).get("file") or "") for x in spread]
            _more = max(0, SPEAKBOX_SPREAD - len(spread))
            if _more:
                spread += await speakbox_spread(
                    seen=[f for f in _used if f], want=_more)
            _spread_clause = speakbox_spread_clause(spread)
            if _spread_clause:
                angle = str(angle) + _spread_clause
                for _sw in spread:
                    try:
                        speakbox_remember(_sw)
                    except Exception:  # noqa: BLE001
                        pass
        except Exception:  # noqa: BLE001
            pass            # a round with one document is still a round
        if any(w in angle for w in ("gallery", "pictures", "painting")):
            art_sell_mark()

    # A round that already has its own subject — a call, the top of the show,
    # a memo from upstairs — gets one of his lines worked into it anyway.
    # Incessantly is the word he used (#207): the only way to have none is to
    # turn the speakbox down to zero, which is what that slider is for.
    # 2026-09-08 (the rejections census): ...unless the round's facts ARE
    # its material (own_material: the wire, the memo, the hour's log, a
    # painting). Those rounds keep the speakbox's colour (speakbox_flavor
    # rides every line) but are not handed a second subject to work in:
    # measured, that second subject is what the news audit cut them for.
    aside = ""
    if not caller_name and not seed and not own_material and random.random() < box_rate_now(
            dj["speakbox_rate"]):
        seed = _source_for_scene(await speakbox_quote())
        if seed:
            aside = speakbox_aside(seed)
            # A line worked in needs somewhere to be answered. Two lines is
            # one each with nothing left over, and the answer is the point.
            lines = max(lines, min(3, dj["banter_max_lines"]))

    # Now and then the pair go LOOKING for approval (#322) — and the SFX
    # guy, who never talks, gives his verdict from the corner booth right
    # after the round.
    seek_verdict = (not caller_name and bool(dj["drop_voice"])
                    and random.random() < 0.35)
    if dj["drop_voice"]:
        # #835: the SFX Guy is a CHARACTER the room lives with — faded
        # NASCAR t-shirt, beat-up penny loafers, dusty blue jeans, thick
        # country accent, a deep love of NASCAR, left turns and Dale
        # Earnhardt. He interjects backcountry one-liners from his booth
        # between your statements (you hear them; the audience hears
        # them), and he is a ONE-UPPER: anything anybody did, he did it
        # better, bigger, or twenty-five years earlier for NASA. React
        # to his heckles now and then — laugh, groan, wave him off —
        # and occasionally set him up on purpose the way a straight man
        # feeds a punchline.
        angle += (" The SFX guy in the corner booth is a faded-NASCAR-"
                  "shirt country boy who heckles between your lines and "
                  "one-ups every story anybody tells. Now and then REACT "
                  "to something he just hollered — laugh, groan, tell "
                  "him nobody flew a lunar lander in 1999 — without "
                  "writing his lines for him.")
        _gnews = _RADIO.get("sfxguy_news") or {}
        if _gnews and time.time() - float(_gnews.get("at") or 0) < 600 \
                and not caller_name:
            angle += (" The SFX guy just slapped the desk and broke a "
                      f"news story on air: \"{_gnews.get('title')}\" — "
                      f"with the take: \"{_gnews.get('take')}\". Make "
                      "THAT the topic now: run with it, argue with his "
                      "take, credit him for bringing it (#804).")
            _RADIO.pop("sfxguy_news", None)
    if seek_verdict:
        angle += (" At some point one of you turns to the SFX guy in his "
                  "booth and appeals for backup OUT LOUD — 'back me up "
                  "here' — even though he mostly talks in heckles. Do not "
                  "write his reply; he answers for himself.")
    # #626: buried in passing — a reference to how hot the machine is running
    # tonight, drawn from the evolving database keyed to the ACTUAL heat band
    # and shuffled so it never repeats. A single glancing aside, never the
    # topic; whoever the model hands it to is the one who lets it slip.
    # #775: the theme reached the phone line and nothing else. active_theme()
    # had ONE call site in the whole file, so the pair themselves never heard
    # about it - and their stock material leans hard on the machine and the
    # heat, which is what the operator kept hearing instead of their subject.
    _air_theme = theme_owns_air()
    if _air_theme and not caller_name:
        angle += theme_air_clause(_air_theme)
    # The glancing heat aside is part of that stock material, so it stands
    # down for the same reason the call-side block does.
    if not caller_name and not _air_theme \
            and random.random() < dj.get("heat_rate", 0.3):
        _hot = heat_reference()
        if _hot:
            angle += (" BURIED, IN PASSING: somewhere mid-conversation one of "
                      "you lets slip, as a throwaway aside and NOT the topic, a "
                      f"reference to how hot the machine is running — \"{_hot}\" "
                      "— a single glancing mention, then straight on.")
    try:
        third = (f"\nAlso in the booth, a third presenter, "
                 f"{dj['third_name']}: {radio_persona('third', dj['third_persona']) or 'game for anything'}"
                 if dj["third_name"] else "")
        _flavor = await speakbox_flavor()   # on-the-fly randomness toggle
        # 🎭 personality slider: how often the disposition colours the round.
        _pers = (dj_disposition()
                 if not seed and random.random() < float(
                     dj.get("personality") or 0.7) else "")
        call_flow = (f"\n\nTHIS IS A COMPLETE, NATURAL PHONE CALL WITH "
                     f"{caller_name}. Give it these conversational beats without "
                     "announcing the structure: (1) ring, answer and a short "
                     "self-introduction; (2) the caller gives a particular reason "
                     "for phoning, with a concrete person/place/object at stake; "
                     "(3) a host responds to that exact detail and asks a natural "
                     "open follow-up; (4) C ANSWERS the question before adding new "
                     "detail; (5) rapport develops through a callback, shared joke, "
                     "empathetic recognition or earned disagreement; (6) the hosts "
                     "bring in one relevant Speakerbox image or phrase as texture "
                     "and C makes it their own; (7) the promised outcome lands; "
                     "(8) C finishes their thought and a host gives an unmistakable "
                     "sign-off. Ask at least TWO responsive questions across the "
                     "call, each based on something C has just revealed, and let C "
                     "answer each. It must not become an interrogation or a caller "
                     "monologue: all three people listen, answer and influence where "
                     "the conversation goes. Every turn reacts to a specific prior "
                     "detail. Never abandon C, discuss C in the third person while "
                     "they are present, or cut away before the goodbye.\n"
                     + call_novelty_prompt(str(                     # #1157
                         ((call_meta or {}).get("plot") or {}).get("id")
                         or ""))
                     if caller_name else "")
        if caller_name:
            call_flow += radio_prompt_instruction("caller")
        participants = (f"the two hosts and {caller_name} on the phone"
                        if caller_name else
                        ("the three" if third else "the two"))
        # #987: mark the desk before the AUTHORING call, so the round's
        # paperwork is that call and not whatever ran after it. dj_banter
        # makes several model visits - #862's blend pass in particular -
        # and the blend is the LAST thing to rewrite the script, so both
        # "the most recent call" and "the call whose output matches this
        # script" find the blend rather than the writing.
        #
        # Marked by TIME, not by position: _MODEL_CALLS is trimmed to the
        # last forty on every append, so an index captured beforehand
        # stops pointing at the same row the moment the ring is full -
        # which is why the index version silently never matched.
        _desk_at = time.time()
        _paper_context = await asyncio.to_thread(paper_discussion_context)
        script = await ask_model(
            f"{radio_persona('host', dj['persona'])}"
            f"{radio_prompt_instruction('host')}"
            f"{radio_prompt_instruction('cohost')}"
            f"{radio_prompt_instruction('interaction')}"
            f"{radio_prompt_instruction('speakerbox')}"
            f"{radio_prompt_instruction('music') if track else ''}"
            f"{radio_prompt_instruction('workplace')}"
            f"{_pers}{_flavor}{day_context()}{accent_directive()}\n\n"
            + str(_paper_context.get("prompt") or "")
            +
            "PUSH THE EDGE (#613): the goal is to be OUTLANDISH — the best "
            "radio says the thing nobody else would. Lean HARD on the material "
            "out of the documents, take it further than anyone expects, chase "
            "the wildest read of it, and never play it safe or generic.\n\n"
            f"Your co-host: {radio_persona('cohost', dj['cohost_persona'])}{third}\n\n"
            f"Write a substantial, unfolding exchange for {dj['station_name']} between "
            f"{participants} "
            f"of you — {max(2, lines - 1)} to {lines} lines total, "
            + ("nobody speaking twice in a row and everyone getting a "
               "word in. " if third else
               ("the hosts and caller take turns; no one speaks twice in "
                "a row. Give C roughly two turns out of every five, with enough "
                "room to tell the story and answer the hosts. The hosts do more "
                "than react: they listen for a concrete detail, ask a useful "
                "follow-up, disclose or joke in return, and let C's answer change "
                "their next move. Nobody conducts a questionnaire and nobody "
                "delivers an unrelated speech. " if caller_name
               else "strictly alternating. "))
            + (system2_turn_instruction(_system2_budget) if _system2_budget else
               "Each primary turn must be a developed four-to-seven-sentence "
               "thought, usually 60 to 100 words: specific, surprising, and "
               "responsive, never a one-sentence quip. ")
            + "Every line RESPONDS to the line before "
            "it: take in what was just said, react to it first — in so many "
            "words — then add your own. No line may ignore or talk past the "
            f"previous one. At least once, {random.choice(['A', 'B'])} is "
            f"openly {unrepeated(['shocked', 'surprised', 'furious', 'in disbelief', 'delighted', 'appalled'], 'internalize')} "
            "at what the other has JUST said, says so, and the rest of the "
            "conversation is driven by that. This time: "
            f"{angle}. Name the actual thing you are talking about. Play it "
            "straight and let the specifics be the joke — mock outrage, "
            "raised eyebrows, 'can you believe what he asked us for'. "
            # Shock-jock nerve (#479): the pair are uninhibited late-night
            # radio hosts in the Howard Stern mould — when the material is
            # unusual, edgy, taboo or outrageous they LEAN IN and milk it for
            # all it is worth rather than shying away, because that is what
            # makes it worth listening to. They never refuse a topic or lecture
            # about it; they run with it, get bawdy and irreverent, and make it
            "the most entertaining thing on the dial. "
            + ("A WORD-FOR-WORD passage may run as one long turn — do not "
               "shorten or paraphrase it, it will be read out in full. Keep "
               "the OTHER lines under 140 words, with concrete details and "
               "a complete thought. "
               if seed else "Lines may run to 120 words — two to five "
               "sentences, expansive, thought-provoking, a WHOLE thought "
               "each, not a quip; the "
               "delivery system breathes and continues long lines "
               "automatically, so never truncate an idea to fit. ")
            + (f"Work the station's name, {dj['station_name']}, in naturally "
               "once — the pair are proud of where they work (#459). "
               if random.random() < 0.3 else
               "Do not lean on the station's name this round — the station "
               "IDs handle that (#355). ")
            # #676: the dice. Re-rolled every round, so the same persona
            # arrives in a different temper each time instead of settling
            # into one register for the whole night.
            # #752: unrepeated, not random.choice — these ARE roulettes
            # of approach, with no memory, so the same temperament
            # pairing came round inside a few rounds and read as the
            # repetition the request is about.
            + (("THE DICE ARE ON THIS ROUND. A is "
                + unrepeated(list(HOST_TEMPERS), "temper-a") + "; B is "
                + unrepeated(list(HOST_TEMPERS), "temper-b")
                + ". Play those temperaments "
                "HARD — they colour the phrasing, the pacing and what each "
                "of them chooses to react to. They are still themselves, "
                "just caught in this mood tonight. Do not name the mood out "
                "loud; perform it. ")
               if dj.get("dice_hosts") else "")
            # #684: a long turn is a monologue with a witness unless the
            # other one is audibly still in the room. These are NOT replies
            # and they do not take the floor — they are forced in edgewise,
            # and the roll carries on straight over them.
            + (f"WHEN ONE OF THEM GOES ON A ROLL — any turn that runs long, "
               f"a rant, a diatribe, a story with a head of steam — the "
               f"OTHER one forces short reactions in edgewise BETWEEN the "
               f"phrases, trying to participate while the roll carries on "
               f"over the top of them. Give those interruptions their own "
               f"lines, two to four of them across the diatribe, each one "
               f"only a word or a handful: "
               # #no-repeats: SAMPLED, not the first eleven. A fixed slice of a list
               # the operator may have written thirty of is a fixed paragraph
               # in a prompt that is already mostly fixed.
               f"{', '.join(repr(p) for p in random.sample(list(dj['diatribe_interjections']), min(11, len(dj['diatribe_interjections']))))}"
               f" — or anything in that spirit, in their own voice. They are "
               f"reactions, NOT replies: the one on the roll does not stop, "
               f"does not answer them, and keeps going. Vary them; never use "
               f"the same one twice in a round. "
               if dj.get("diatribe_interjections") and not caller_name else "")
            + "No markdown, no emoji, no URLs, no "
            "stage directions, no asterisks. "
            # No fabricated tallies (#485): the pair kept inventing "you have
            # asked for this eleven times" for things that never happened.
            "NEVER invent specific numbers of times the listener asked for or "
            "did something — no made-up tallies or counts. Only cite a number "
            "when it is given to you in the notes above; otherwise speak "
            "without one.\n"
            # #828: a conversation, not interleaved monologues — the
            # operator hears the pair talking PAST each other.
            + "EVERY TURN RESPONDS TO THE ONE BEFORE IT: pick up a "
            "SPECIFIC word, image or claim the other speaker just said — "
            "repeat it back, challenge it, laugh at it, mishear it, build "
            "on it — BEFORE adding anything new. A turn that could be "
            "moved three turns away without anyone noticing is a failed "
            "turn. React first, then advance. "
            + f"{banter_pace(0 if caller_name else dj['overlap'])}\n"
            f"Format each line as 'A: ...' for you and 'B: ...' for "
            f"{dj['cohost_name']}"
            + (f", 'D: ...' for {dj['third_name']}" if third else "")
            + (f", and 'C: ...' for {caller_name} on the phone"
               if caller_name else "")
            + f".{seat_away_clause()}"           # #1034: the empty chair
            f"{playing}{only_song}{aside}{show_memory()}{call_flow}"
            f"{crystal_clause(bank)}{avoid_reruns()}"
            f"{approach_clause(_approach)}\n\n"
            # #842: the banked round is told it is being PRE-RECORDED, so
            # the model spends the room it has been given on more lines
            # rather than on a tighter version of the same six.
            + ("THIS ONE IS BEING RECORDED IN ADVANCE, not live: there is "
               "no clock on it and nothing is waiting on you. Use that. "
               "Write it FULLER than a live link — every turn developed, "
               "the subject genuinely taken somewhere over the course of "
               "the exchange, and a real landing on the last turn rather "
               "than a stop. Give us MORE TURNS rather than longer "
               "ones.\n\n" if _bank_rich else "")
            + "The two lists below are prompts he typed and pictures we made "
            "for him. They are not songs and must never be announced as "
            "songs.\n"
            f"Things he keeps asking for:\n{material or '- (nothing yet)'}\n\n"
            f"Pictures he had us make:\n{pictures or '- (none yet)'}",
            spice=0.5,                  # wider intonation draw (#371)
            # Room for the whole swath to come back out (#210): a long
            # passage worked in needs more turns than a one-line remark, and
            # running out of tokens is what a DJ stopping mid-word sounds
            # like (#168).
            limit=min(
                int(_system2_budget.get("max_chars") or dj.get("reply_max_chars") or 6000),
                int(dj.get("reply_max_chars") or 6000),
                # #842: a banked round asks for a bigger script than a
                # live one. reply_max_chars is still the ceiling — this
                # only stops the round asking for less than the operator
                # is willing to give it.
                max(3600 + (2400 if _bank_rich else 0),
                    (760 if _bank_rich else 560) * lines
                    + len(seed.get("text", ""))
                    + len(aside) + len((comeback or {}).get("text", ""))
                    + len(angle)),
            ),
            # #842: "we can increase the context length for the LLM to get
            # more lines". The banked round is written in the wide window;
            # a live one keeps the operator's own num_ctx untouched.
            num_ctx=(32768 if _bank_rich else 0),
        )
    except Exception as exc:
        # #805: this `except` was SILENT, and the ledger showed what
        # silence costs — 52 of 99 calls in 12h aired zero turns, most
        # dying right here after the phone had already rung on air. Say
        # it, and for a CALL fall back to a minimal built-in script: a
        # phone that rang always airs a short call rather than nothing.
        pipeline_log("drop", f"the round's script write failed: "
                     f"{type(exc).__name__} {str(exc)[:140]}"
                     + (f" — fallback call script for {caller_name}"
                        if caller_name else ""))
        if not caller_name:
            return []
        script = _fallback_call_script(
            caller_name, str((call_meta or {}).get("topic") or angle)[:320],
            str((call_meta or {}).get("speakerbox_text") or ""),
            str((call_meta or {}).get("line") or ""))

    # #805: ask_model returns "" when the reply fragment-binned — not an
    # exception, and previously not a call either. Same guarantee.
    if caller_name and not spoken_text(script or ""):
        pipeline_log("call", f"fragment-binned call write — built-in "
                     f"fallback script carries {caller_name} (#805)")
        script = _fallback_call_script(
            caller_name, str((call_meta or {}).get("topic") or angle)[:320],
            str((call_meta or {}).get("speakerbox_text") or ""),
            str((call_meta or {}).get("line") or ""))

    # Do not bank or air an exchange that ignored the long-form contract.
    # This is deliberately after the first generation so the correction can
    # preserve its subject and any exact Speakerbox wording while giving every
    # speaker enough room to make a real thought.
    # #805: calls were EXEMPT from this rescue — the one that works — which
    # is how 11-turn calls aired as one or two turns. A call's bar is its
    # own: the CALLER must be on it (three C: turns) and it must be a
    # conversation (six turns), not an essay.
    _needs_rewrite = False
    _call_report: dict[str, Any] = {}
    if _system2_budget and not caller_name:
        _needs_rewrite = not system2_scene_complete(banter_turns(script), _judge_lines)
    elif _judge_lines >= 8 and not caller_name:
        _needs_rewrite = not substantial_radio_script(script,
                                                      _judge_lines)
    elif caller_name and lines >= 6:
        # #977: COUNTED BY THE PARSER, NOT BY LINE.
        #
        # These were line-anchored regexes, and the model returns the whole
        # exchange on ONE line - banter_turns' own docstring says exactly
        # that, which is why it splits on markers wherever they appear
        # rather than line by line. Measured on two banked calls: 3568 and
        # 2406 characters, ZERO newlines in either, six C: markers apiece
        # and not one of them at a line start. So _c_turns was 0 on both,
        # _needs_rewrite was True, and it was True on essentially every
        # call the station has ever written.
        #
        # The cost of that is not cosmetic. The rescue rewrite is then
        # judged by the same line-anchored test below and thrown away, and
        # #904 banks the original anyway - so every call paid for a second
        # model visit (measured 25986 ms) that changed nothing. That
        # doubled bill is what put task_cost("caller") at 268s, and
        # prep_budget ends in min(room, ...) where the room left on a
        # record is 150-230s. The caller road therefore measured
        # permanently unaffordable and its shelf sat at zero while the ad
        # and manager roads advanced - which is the starvation behind
        # "they're not taking enough phone calls".
        #
        # The non-caller branch above already parses through
        # substantial_radio_script and was never affected. This was the one
        # place in the writing path that counted by line.
        _turns_seen = banter_turns(script or "", caller_name, caller2_name)
        _c_turns = sum(1 for _m, _t in _turns_seen if _m in ("C", "E"))
        _all_turns = len(_turns_seen)
        # #969/#970: A FLOOR OF THREE IS NOT A SHARE.
        #
        # This accepted any call with three caller turns in it, so a
        # twelve-turn call of nine host turns and three caller turns
        # passed as correct - which is precisely the call the operator
        # heard, the DJ talking and the caller never getting back in.
        # Prose alone will not hold a small model to a balance; the gate
        # has to count.
        #
        # Two fifths rather than a half, deliberately: a caller round
        # legitimately opens with a host greeting and can close with one,
        # so demanding a strict half would reject good calls and pay for a
        # rewrite that cannot win - the #904 trap this same block was
        # rescued from once already.
        _c_share = (_c_turns / _all_turns) if _all_turns else 0.0
        _call_report = call_flow_report(
            script, caller_name, caller2_name,
            topic=str((call_meta or {}).get("topic") or ""),
            speakerbox_text=str(
                (call_meta or {}).get("speakerbox_text") or ""),
            story=((call_meta or {}).get("story")
                   if isinstance((call_meta or {}).get("story"), dict)
                   else None),
            plot=((call_meta or {}).get("plot")
                  if isinstance((call_meta or {}).get("plot"), dict)
                  else None))                                     # #1157
        _needs_rewrite = not bool(_call_report.get("ok"))
    _draft_entry = {"script": script, "prep_kind": "caller" if caller_name else "banter",
                    "caller_name": caller_name, "caller2_name": caller2_name,
                    "caller_voice": caller_voice, "caller2_voice": caller2_voice,
                    "call": dict(call_meta or {}), "source": source or seed.get("file", ""),
                    "seed_text": seed.get("text", ""), "lines": lines,
                    "vouched": vouched, "profile": _larder_profile_signature()}
    if _needs_rewrite and _radio_draft_review(_draft_entry,
            _call_report or {"ok": False, "faults": ["the draft missed its conversational richness target"]},
            "draft_rewrite", record=True):
        _needs_rewrite = False
    if _needs_rewrite:
        pipeline_log(
            "model", "phone/radio draft failed its conversational contract - "
            "rewriting before air",
            extra=("; ".join(_call_report.get("faults") or [])[:900]
                   if caller_name else ""))
        try:
            rewritten = await ask_model(
                "Rewrite the following Pine Box FM draft as a coherent, "
                + ("complete short exchange. " if _system2_budget else "long-form exchange. ")
                + "Return only A:/B"
                + ("/C" if caller_name else "/D" if _system2_budget and dj.get("third_name") else "") + ": dialogue. Keep its "
                "subject and every verbatim quotation. "
                + (f"Write {lines} alternating turns. " + system2_turn_instruction(_system2_budget)
                   if _system2_budget else "Write 8 to 11 alternating turns with at least 55 words in every ordinary turn. ")
                + "Each speaker must respond directly to the prior turn, "
                "develop an idea with concrete detail, and finish a complete "
                "thought. Do not use one-line reactions or stage directions."
                 + (f"\nThis is a LIVE PHONE CALL: 'C:' is {caller_name} on "
                    "the line. Give C 35-60% of the turns. A host asks at "
                    "least two natural follow-up questions grounded in exact "
                    "details C just revealed; C answers each. Build one earned "
                    "rapport callback, carry the database theme throughout, "
                    "and end with C finishing and a host clearly signing off. "
                    + ("Mid-call C introduces this new Speakerbox subject in "
                       "their own rhetoric, preserving at least two concrete "
                       "anchor words; the next host repeats an anchor and "
                       "develops it with C: \""
                       + str((call_meta or {}).get("speakerbox_text") or "")[:500]
                       + "\". "
                       if str((call_meta or {}).get("speakerbox_text") or "")
                       else "")
                    + "The penultimate turn is C explicitly resolving what "
                    "changed or why they are ready to leave it there; the "
                    "final turn is one host answering that and saying thank "
                    "you or goodbye. "
                    "Do not reuse any recent premise, conflict or landing."
                    + call_novelty_prompt(str(                      # #1157
                        ((call_meta or {}).get("plot") or {}).get("id")
                        or ""))
                    if caller_name else "") + "\n\n"
                + script,
                limit=min(int(_system2_budget.get("max_chars") or dj.get("reply_max_chars") or 6000),
                          int(dj.get("reply_max_chars") or 6000),
                          max(4200, 500 * min(lines, 11))),
                spice=0.25,
                num_ctx=16384,
            )
            if caller_name:
                # #977: judged by the parser that will actually air it,
                # for the same reason the gate above is. Line-anchored,
                # this test failed every one-line rewrite - so a good
                # rescue was thrown away and #904 banked the original,
                # which is how a call paid for two model visits and kept
                # neither of them.
                _rw_turns = banter_turns(rewritten or "", caller_name,
                                         caller2_name)
                _rw_report = call_flow_report(
                    rewritten, caller_name, caller2_name,
                    topic=str((call_meta or {}).get("topic") or ""),
                    speakerbox_text=str(
                        (call_meta or {}).get("speakerbox_text") or ""),
                    story=((call_meta or {}).get("story")
                           if isinstance((call_meta or {}).get("story"),
                                         dict) else None),
                    plot=((call_meta or {}).get("plot")
                          if isinstance((call_meta or {}).get("plot"),
                                        dict) else None))         # #1157
                _rw_ok = bool(_rw_report.get("ok"))
            else:
                _rw_ok = (system2_scene_complete(banter_turns(rewritten), _judge_lines)
                          if _system2_budget else substantial_radio_script(rewritten, _judge_lines))
                _rw_report = {"ok": _rw_ok,
                              "faults": [] if _rw_ok else ["the rewrite missed its conversational richness target"]}
            if not _rw_ok:
                _rw_ok = _radio_draft_review({**_draft_entry, "script": rewritten},
                    _rw_report, "draft_rewrite_rejected", record=True)
            if _rw_ok:
                script = rewritten
            else:
                if caller_name:
                    # A phone call is not salvageable as unrelated/thin
                    # dialogue: the person on the line and the response arc
                    # are the product. Move to the deterministic complete-call
                    # safety script BEFORE tint so even the fallback receives
                    # the same second pass and final machine grade.
                    script = _fallback_call_script(
                        caller_name,
                        str((call_meta or {}).get("topic") or angle)[:320],
                        str((call_meta or {}).get("speakerbox_text") or ""),
                        str((call_meta or {}).get("line") or ""))
                    pipeline_log(
                        "call", "the rewritten phone call still failed its "
                        "conversation contract — the complete-call fallback "
                        "was sent through tint instead")
                else:
                    # #904: non-call radio can keep a usable original when a
                    # richness rewrite fails. The final call gate below is
                    # intentionally stricter because a broken call is not a
                    # different style of call.
                    pipeline_log("model", "rewrite still thin — the original "
                                 "radio draft stands (#904)")
        except Exception:
            pass                    # the draft stands; bank it as written

    _seed_forced = False                                    # #862
    _seed_put = ""
    if not _system2_job and not caller_name and seed.get("text"):
        # Mined means SAID (#404): a swath the model paraphrased away is
        # put back as the round's opening line, verbatim.
        probe = " ".join(seed["text"].split()).lower()[:60]
        if probe and probe not in " ".join(script.split()).lower():
            # #862: and being put back word for word is what makes it a
            # VERBATIM passage, with the same protection as the ones
            # below. Registered where `_verbatim` is declared.
            # 2026-09-08 (the scan): bounded when raw, like the other doors
            # - this door put a thousand-character run-on in as one turn.
            _seed_forced = True
            _seed_put = _verbatim_turn_text(seed["text"])
            script = f"A: {_seed_put}\n" + script
    _sb = dj_settings()

    async def _fresh_swath() -> dict[str, Any]:
        # #752: seeded with the drawn approach as well as the script, so
        # the material the vector index hands back rhymes with the FRAME
        # rather than with the last 400 characters of what was said.
        # #891: the fallback draw is UNTINTED. Under a strong crystal
        # every blind pull was landing in one mind, so the operator's
        # opening/closing passage sliders stopped delivering the studio's
        # own documents at all. The crystal still owns the round's seed.
        return (await speakbox_semantic_seed(
                    (str(_approach.get("text") or "") + " "
                     + (script[-400:] or angle or "")),
                    exclude=seed.get("file", ""))
                or await speakbox_quote(exclude=seed.get("file", ""),
                                        most=5, cap=500, tinted=False))
    # A full reading is placed into the script AFTER the model has written its
    # exchange. It is therefore verbatim, one speaker's turn, and cannot be
    # summarized, answered over, or reduced to a decorative sentence. The
    # stream renderer may divide it into transport-safe pieces, but joins
    # those pieces in the same voice with no other speaker between them.
    # #838: every passage placed into the script VERBATIM, and where it
    # sits. freshen_script may not hand these to the model to reword -
    # they are the operator's own documents, not the pair repeating
    # themselves, and rewording them is exactly "not hearing enough
    # speakerbox rhetoric".
    _verbatim: list[list[str]] = []
    # 2026-09-10: the passages as DEALT - [where, marker, said] - so the
    # booth, the director's room and the blend all see which seat each
    # piece of a drawn passage actually went to. See _swath_deal.
    _dealt: list[list[str]] = []
    _spread_on = bool(_sb.get("speakbox_seat_spread", True))
    _tint_passages = bool(_sb.get("speakbox_tint_passages", True))

    def _place(text: str, where: str, lead: str = "") -> str:
        """Put one drawn passage into the script as TURNS, not a turn.

        Returns the block of script to splice. Registers each piece in
        `_dealt` always, and in `_verbatim` only while the operator has
        the tint held OFF the passages - `_verbatim` is what exempts a
        passage from the crystal (_tint_plain_passage) and from the
        blend's rewrite, and "tint all of it per the crystal" is the
        instruction that retires that exemption by default."""
        said = str(text or "").strip()
        if not said:
            return ""
        if not _spread_on:
            rows = [["A", said]]
        else:
            rows = _swath_deal(said, _swath_seats(script, caller_name),
                               lead=lead)
        if not rows:
            return ""
        for marker, piece in rows:
            _dealt.append([where, marker, piece])
            if not _tint_passages:
                _verbatim.append([where, piece])
        return "".join("%s: %s\n" % (m, p) for m, p in rows)
    # #862: the seed the model dropped and #404 put back is the operator's
    # own document too - and under a crystal it is the tinted draw (#834),
    # so leaving it off this list meant the ONE passage the rewrite could
    # paraphrase away was the crystal's. It goes in at the head, which is
    # where #404 put it, so _restore() puts it back in the same place.
    if _seed_forced and _seed_put.strip():
        # 2026-09-10: `_verbatim` is the TINT EXEMPTION as much as it is
        # the rewrite guard (_tint_plain_passage), so registering a
        # passage here is what stops the crystal reaching it. Under
        # "tint all of it per the crystal" the passage is still
        # protected from being reworded away by freshen_script - that is
        # `_dealt` - but it is no longer held out of the tint.
        _dealt.append(["head", "A", _seed_put.strip()])
        if not _tint_passages:
            _verbatim.append(["head", _seed_put.strip()])
    full_swath: dict[str, Any] = {}
    if (not _system2_job and not caller_name and not own_material and random.random() < float(
            _sb.get("speakbox_full_swath_rate") or 0)):
        full_swath = await speakbox_quote(
            # #1078: was 30, and THIRTY LINES is what capped this, not
            # the operator's dial. Gems are capped at 200 characters
            # and floored near 30, so thirty of them is 930 to 6,000
            # characters - and on a document of short lines it lands
            # near the floor. Measured: a 2,600 setting delivering 939.
            # The cap below is the real limit now.
            most=90,
            cap=int(_sb.get("speakbox_full_swath_chars") or 2600),
        )
        if full_swath.get("text"):
            # 2026-09-08 (the scan): a punctuated reading stays whole; a raw
            # run-on (no sentence in it) is bounded like the other doors.
            # 2026-09-10: NOT bounded to 240 characters and thrown away
            # any more - _verbatim_turn_text TRUNCATED a raw run-on, so a
            # 3,000-character draw aired as 240 characters of itself and
            # the rest of the operator's document was discarded. It is
            # dealt across the seats instead, whole.
            _full_text = " ".join(str(full_swath["text"]).split())
            _block = _place(_full_text, "head")
            if _block:
                script = _block + script.lstrip()
                _turns = _block.count("\n")
                lines += _turns
                speakbox_remember(full_swath)
                pipeline_log("speakbox", "full swath dealt across the room "
                             f"({len(_full_text)} chars, {_turns} turns)")
    # #609/#612: PRE-PEND a fresh verbatim swath to the FRONT of the round (an
    # extra opening quote, on top of any seed) and APPEND one to the END, each
    # on its own slider so the pair trade the operator's documents verbatim more
    # or less (#602/#604/#613: outlandish, straight out of the speakbox).
    # #no-repeats: pressure buys MATERIAL. The old breaker answered a gate that was
    # firing a lot by switching the gate off; this answers it by reaching
    # further into the documents, so a station that keeps repeating itself
    # gets more of the operator's own words rather than fewer of its own.
    _lift = phrase_pressure()
    if _lift >= 0.25:
        pipeline_log("speakbox", f"the cooldown is holding back "
                                 f"{_lift * 100:.0f}% of recent lines — "
                                 "leaning harder on the documents (#no-repeats)")
    # #867: THE SLIDER IS THE ANSWER, and nothing overrules it. The full
    # swath used to suppress both passages — at a 45% swath rate that was
    # nearly half of all rounds losing an 80% opening and a 68% closing
    # passage, so two dials the operator had set were being quietly
    # cancelled by a third. "If the sliders are up for the speaker box
    # rhetoric, there is nothing that can stop it." The budget is what
    # gets expanded to fit, not the material that gets dropped.
    if not _system2_job and not caller_name and not own_material and random.random() < min(1.0, float(
            _sb.get("speakbox_prepend_rate") or 0) + _lift):
        head = await _fresh_swath()
        if head.get("text"):
            _head_text = " ".join(str(head["text"]).split())
            _block = _place(_head_text, "head")
            if _block:
                script = _block + script.lstrip()
                lines += _block.count("\n")
                speakbox_remember(head)
    tail: dict[str, Any] = {}
    if not _system2_job and not caller_name and not own_material and random.random() < min(1.0, float(   # #867
            _sb.get("speakbox_append_rate") or 0) + _lift):
        tail = await _fresh_swath()
        if tail.get("text"):
            # #786: terminal punctuation, or the #168 truncation gate reads
            # a verbatim un-punctuated swath as token exhaustion and deletes
            # the operator's own material off the end of the round.
            _tail_text = " ".join(str(tail["text"]).split()).rstrip()
            if not re.search(r"[.!?…—»\"')\]]$", _tail_text):
                _tail_text += "."
            _block = _place(_tail_text, "tail")
            if _block:
                script = script.rstrip() + "\n" + _block.rstrip()
                lines += _block.count("\n")
                speakbox_remember(tail)
    # #844: THE SLIDER IS A GUARANTEE AT THE TOP OF ITS RANGE. Every
    # speakbox control was a probability on the DRAW, and nothing ever
    # checked that the model used what it was handed — so at 100% the
    # material was always fetched and could still be absent from the
    # finished round. This is the post-pass on the text generation the
    # operator asked for: if the words are not in the script, they go in.
    try:
        _sb_rate = float(_sb.get("speakbox_rate") or 0)
        _seed_text = str((seed or {}).get("text") or "").strip()
        if (not _system2_job and _sb_rate >= 0.95 and _seed_text and not caller_name
                and not full_swath and not own_material):
            _flat = re.sub(r"[^a-z0-9 ]+", " ", script.lower())
            _flat = re.sub(r"\s+", " ", _flat)
            _probe = re.sub(r"[^a-z0-9 ]+", " ", _seed_text.lower())
            _probe = re.sub(r"\s+", " ", _probe).strip()
            # Match on a real span of it, not the whole passage — the
            # pair are allowed to break a long line across a turn.
            _probe = " ".join(_probe.split()[:9])
            if _probe and _probe not in _flat:
                _put = _verbatim_turn_text(_seed_text).rstrip()    # 2026-09-08: bounded when raw
                if not re.search(r"[.!?\u2026\u2014\u00bb\"')\]]$", _put):
                    _put += "."
                script = script.rstrip() + f"\nB: {_put}"
                lines += 1
                _dealt.append(["enforced", "B", _put])
                if not _tint_passages:
                    _verbatim.append(["enforced", _put])        # #838
                speakbox_remember(seed)
                pipeline_log("speakbox", "grounding is at the top of the "
                             "slider and the round came back without the "
                             "material - the passage was put back in "
                             "(#844)", extra=_put[:200])
    except Exception:  # noqa: BLE001
        pass
    # #838: a verbatim passage is the operator's OWN document, not the
    # model reaching for a record that is not on air - but names_only
    # (the #176/#178 gate in speak_turns) reads ANY quoted phrase in a
    # turn as an invented title and drops the whole turn at the door,
    # which is how a swath that quotes somebody was never heard. What
    # the documents themselves quote is sanctioned here so the passage
    # can go out whole. Wrapped: a bad regex hit must not lose a round.
    try:
        for _one in ([str((seed or {}).get("text") or ""),
                      str((comeback or {}).get("text") or ""),
                      str((jab or {}).get("text") or "")]
                     + [str(_row[1]) for _row in _verbatim]
                     + [str(_row[2]) for _row in _dealt]):
            for _quoted in _QUOTED_TITLE.findall(_one):
                _quoted = str(_quoted).strip()
                if _quoted and _quoted not in vouched:
                    vouched.append(_quoted)
    except Exception:  # noqa: BLE001
        pass
    # #862: GENERATE, ALTER, ENHANCE, THEN REPROCESS. Everything above
    # this line has assembled the round: the model wrote it under the
    # crystal's tint, the speakbox stapled its verbatim passages onto the
    # front and the back, and #844 put back anything the slider guaranteed.
    # Now it goes back through the writing room once, to have the pair
    # actually react to what was stapled in - the passages held word for
    # word, only the conversation around them rewritten. Bank road only:
    # #842 says a pre-recorded round has no clock on it, so the air path
    # never waits on this, and blend_script returns the round untouched on
    # any doubt at all.
    # 2026-09-10: THE PASS THAT MAKES THE ROOM ANSWER, ACTUALLY REACHED.
    #
    # This gate read `bank and not _system2_job and not caller_name`, and
    # System2 became the DEFAULT engine at #1070 - so from that day the one
    # stage that exists to make the pair react to a stapled passage was
    # unreachable on the station's main road, and callers never had it at
    # all. That is the "I am not hearing the hosts conversate" report: not
    # a missing feature, a feature nothing could call. (The same shape as
    # the orchestrator's dead wiring - ask whether a desk is REACHED
    # before reading its logic.)
    #
    # A System2 job is prepared ahead of its slot exactly as a banked round
    # is, so it has no clock on it either and #842's argument covers it
    # unchanged. The LIVE path is still never blended: `_prepared` below is
    # the whole test, and a round being written against the air keeps going
    # straight out.
    _prepared = bool(bank) or bool(_system2_job)
    if _prepared and _dealt:
        try:
            _blended = await blend_script(script,
                                          [[r[0], r[2]] for r in _dealt],
                                          caller_name, _prepared)  # #1027
            if _blended and _blended != script:
                script = _blended
                # The blend may answer a passage with a turn of its own,
                # and `lines` is a HARD cap on how many turns speak_turns
                # will air - so a round that grew has to be allowed to
                # finish. Bounded by the same six the blend is bounded by.
                _bt = len(banter_turns(script, caller_name))
                if _bt > lines:
                    lines = min(_bt, lines + 6)
        except Exception:  # noqa: BLE001
            pass                        # the assembled round stands
    # 2026-09-10: RE-SEED IF THEY LOSE THE PATH.
    #
    # "...while seeding more speakerbox if they lose the path". A long
    # round wanders: the blend answers the passage at the top and by the
    # last few turns the pair are talking about the studio furniture
    # again. So ask the cheap question - do the closing turns still carry
    # a specific word out of anything that was placed? - and when they do
    # not, put fresh material in their mouths rather than letting the
    # round run out on nothing. One extra draw at most, prepared roads
    # only, and any fault at all leaves the round exactly as it was.
    if _prepared and _dealt and not own_material:
        try:
            _now_turns = banter_turns(script, caller_name)
            if len(_now_turns) >= 6:
                _placed_words: set[str] = set()
                for _row in _dealt:
                    _placed_words |= _swath_words(_row[2])
                _closing = _swath_words(
                    " ".join(str(t) for _m, t in _now_turns[-3:]))
                if _placed_words and not (_placed_words & _closing):
                    _again = await _fresh_swath()
                    if _again.get("text"):
                        _again_text = " ".join(
                            str(_again["text"]).split())
                        _block = _place(_again_text, "reseed")
                        if _block:
                            script = script.rstrip() + "\n" + _block.rstrip()
                            lines += _block.count("\n")
                            speakbox_remember(_again)
                            pipeline_log(
                                "speakbox",
                                "the round drifted off the material it was "
                                "seeded with - fresh documents put in "
                                f"before the end ({_again.get('file')}, "
                                f"{_block.count(chr(10))} turns)")
        except Exception:  # noqa: BLE001
            pass                        # the assembled round stands
    entry = {
        "script": script, "lines": lines, "vouched": vouched,
        "newspaper": {k: v for k, v in (_paper_context or {}).items() if k != "prompt"},
        # The road identity has to exist BEFORE tint and brief audit.  The
        # outer prep_round used to stamp `caller` only after dj_banter
        # returned, which meant every call was actually tinted and audited as
        # generic banter; phone-specific fidelity instructions were dead code.
        "prep_kind": "caller" if caller_name else "banter",
        "source": source or seed.get("file", ""),
        "seed_text": seed.get("text", ""),
        # #838: the passages the rewrite may not touch, carried with the
        # round so the larder road protects them too.
        "verbatim": _verbatim,
        # 2026-09-10: every piece of every drawn passage and the seat it
        # went to, so the booth and the director's room can show the
        # material as it was actually dealt rather than as it was drawn.
        "dealt": _dealt,
        "swaths": [s for s in (seed, comeback, jab, tail) if s],
        "seek_verdict": seek_verdict,
        "caller_name": caller_name, "caller_voice": caller_voice,
        "caller_fx": caller_fx, "at": time.time(),
        "caller2_name": caller2_name, "caller2_voice": caller2_voice,
        "call": dict(call_meta or {}),
        "render_stream": render_stream,
        "whole": bool(whole),                  # #859

        "feel": feel,                                          # #750
        "profile": _larder_profile_signature(),
        # #987/#992: WHERE THIS SCRIPT CAME FROM, carried with it.
        #
        # The writing desk already records the whole exchange - the prompt
        # as sent, the system prompt governing it, the schedule's own
        # instruction, the model and what it cost - but it keeps the last
        # FORTY calls in memory, so by the time a banked round reaches the
        # air its own paperwork has long since scrolled off and does not
        # survive a restart at all. A round that cannot say where it came
        # from cannot be judged, and cannot be sent back.
        "desk": _desk_paper(script, _desk_at),
    }
    if globals().get("system2_stamp_entry"):
        system2_stamp_entry(entry)
    if _system2_budget:
        entry["system2_authoring_budget"] = dict(_system2_budget)
        entry["system2_source_evidence"] = copy.deepcopy(_system2_sources)
    if caller_name:
        # The introduction is phone protocol, so guarantee it before the
        # second pass. Injecting it after tint created one deliberately plain
        # line inside an otherwise tinted call and shifted every audio key.
        _intro_turns = _caller_introduces(
            banter_turns(str(entry.get("script") or ""), caller_name,
                         caller2_name), caller_name)
        if _intro_turns:
            script = "\n".join(
                f"{marker}: {said}" for marker, said in _intro_turns)
            entry["script"] = script
        # Speakerbox material is the call's evidence, not prose the tint may
        # replace. Preserve it word-for-word while the surrounding turn and
        # every other eligible line take the active crystal.
        _call_source = str((entry.get("call") or {}).get(
            "speakerbox_text") or "").strip()
        if _call_source:
            entry.setdefault("verbatim", []).append(
                ["phone-call Speakerbox source", _call_source])
    # #1006/#1016: THE SECOND PASS, and both versions kept.
    #
    # Only on the BANKING road. Rewriting on the air path would put a
    # second model visit in front of the listener on the one road that
    # cannot afford one - and the whole point of keeping both versions is
    # that somebody gets to look at them before they go out, which is
    # only possible for a round that is waiting in the reserve.
    # #1038: ...and it is no longer only the banked road. "I need the
    # crystal tinting everything." A live round cannot afford twelve
    # model visits, so it gets ONE - the whole round in a single ask -
    # while a banked round is still built turn by turn with the rhymes
    # chained. Both are the second pass; what differs is the budget.
    if crystal_tint_two_pass():
        try:
            _tint = await _line_review_scoped(crystal_tint(script,
                                       str(entry.get("prep_kind") or ""),
                                       entry.get("verbatim"),
                                       # #1066: NOT `not bank`. The
                                       # one-ask road measured 1.9%
                                       # rhyme against 8.0% turn by
                                       # turn - indistinguishable from
                                       # not tinting. #1063's hourly
                                       # share is the governor now, so
                                       # the live road no longer needs
                                       # a cheaper path to run down.
                                       whole_only=False,
                                       critical=bool(bank)),
                {"entry": copy.deepcopy(entry), "script_plain": script,
                 "caller_name": caller_name, "caller_voice": caller_voice,
                 "caller2_name": caller2_name, "caller2_voice": caller2_voice})
            entry["script_plain"] = script
            entry["tint"] = {
                "ok": bool(_tint.get("ok")),
                "why": str(_tint.get("why") or ""),
                "world": str(_tint.get("world") or ""),
                "ms": int(_tint.get("ms") or 0),
                "armed": str(_tint.get("armed") or "")[:6000],
                "prompt": str(_tint.get("prompt") or "")[:8000],
                "chunks": list(_tint.get("chunks") or []),
                "coverage": dict(_tint.get("coverage") or {}),
                "evaluation": dict(_tint.get("evaluation") or {}),
                "approved_lines": list(_tint.get("approved_lines") or []),
                "review_turns": copy.deepcopy((_tint.get("progress") or {}).get("turns") or [])
                    if any(r.get("cut") for r in (_tint.get("progress") or {}).get("turns", []) if isinstance(r, dict)) else [],
            }
            if _tint.get("progress"):
                entry["tint_progress"] = dict(_tint.get("progress") or {})
            if _tint.get("ok"):
                entry["script_tinted"] = str(_tint.get("script") or "")
                # #1016: "I want it to default to using the tinted
                # version, but if I happen to like the original version
                # better, I want to be able to right click it and mark
                # that as the version to use."
                entry["use"] = "tinted"
                entry["script"] = entry["script_tinted"]
                entry.pop("tint_progress", None)
                try:
                    _brief = brief_note(
                        str(entry.get("prep_kind") or "banter"),
                        str(entry.get("label") or
                            entry.get("prep_kind") or "banter"),
                        str(entry.get("script") or ""), where="tinted",
                        product=str(entry.get("product") or ""))
                    entry["brief"] = _brief
                    entry["off_brief"] = bool(_brief.get("checked")
                                              and not _brief.get("ok"))
                except Exception:  # noqa: BLE001
                    pass
        except Exception as _tx:  # noqa: BLE001
            pipeline_log("drop", "the tinting pass failed - the plain "
                         "round stands",
                         extra=f"{type(_tx).__name__}: {_tx}"[:300])
    if caller_name:
        # Grade the FINAL active version (including tint), not merely the
        # model's first draft.
        # A failing banked call is visible for diagnosis but cannot consume a
        # usable shelf slot or reach the recording room.
        _final_report = call_entry_regrade(entry)
        # #1146: a failed tint gets ONE immediate second try with the
        # graded faults in its hand - the same lesson loop the ad studio
        # runs (#1134) - and if that also fails, the tint is struck and
        # the graded plain call banks instead. The failure is the
        # rewrite's; the call it was rewriting does not die for it.
        if (not _final_report.get("ok")
                and str(entry.get("use") or "") == "tinted"
                and str(entry.get("script_plain") or "").strip()):
            try:
                _lesson = (
                    "; ".join(_final_report.get("faults") or [])[:400]
                    + ". Keep every proper name, number, question mark "
                      "and spoken sign-off, and keep each turn's concrete "
                      "subject words while restyling around them.")
                _again = await _line_review_scoped(crystal_tint(
                    str(entry.get("script_plain") or ""),
                    str(entry.get("prep_kind") or ""),
                    entry.get("verbatim"), whole_only=False,
                    critical=bool(bank), lesson=_lesson),
                    {"entry": copy.deepcopy(entry), "script_plain": entry.get("script_plain"),
                     "caller_name": caller_name, "caller_voice": caller_voice,
                     "caller2_name": caller2_name, "caller2_voice": caller2_voice})
                if (_again.get("ok")
                        and str(_again.get("script") or "").strip()):
                    # Review: the same bookkeeping every other activation
                    # site performs - stale audio keys die with the old
                    # words, and the paperwork shows the attempt that
                    # actually stands, not the one that failed.
                    _dialogue_audio_drop(entry)
                    entry["script_tinted"] = str(_again.get("script") or "")
                    entry["script"] = entry["script_tinted"]
                    entry["use"] = "tinted"
                    entry["tint"] = {
                        "ok": True,
                        "why": str(_again.get("why") or ""),
                        "world": str(_again.get("world") or ""),
                        "ms": int(_again.get("ms") or 0),
                        "armed": str(_again.get("armed") or "")[:6000],
                        "prompt": str(_again.get("prompt") or "")[:8000],
                        "chunks": list(_again.get("chunks") or []),
                        "coverage": dict(_again.get("coverage") or {}),
                        "evaluation": dict(_again.get("evaluation") or {}),
                        "approved_lines": list(_again.get("approved_lines") or []),
                    }
                    entry.pop("brief", None)    # it graded the old words
                    _final_report = call_entry_regrade(entry)
                    if _final_report.get("ok"):
                        entry["off_brief"] = False
                        pipeline_log(
                            "call", "the retinted call passed the phone "
                            "contract on the second try - the lesson "
                            "loop paid (#1146)")
            except Exception:  # noqa: BLE001
                pass
            if not _final_report.get("ok"):
                _final_report = _call_tint_strike(
                    entry, list(_final_report.get("faults") or []))
                if _final_report.get("ok"):
                    pipeline_log(
                        "call", "the tint failed twice and was struck - "
                        "the graded plain call banks, and the next pass "
                        "carries the lesson (#1146)")
        if not _final_report.get("ok"):
            entry["off_brief"] = True
            _call_line_review(entry, _final_report, "final_call_rejected", record=True)
            pipeline_log(
                "call", "a phone call failed the final flow/novelty contract "
                "and was refused before recording or live synthesis",
                extra="; ".join(_final_report.get("faults") or [])[:1000])
    if bank:
        # #842: a round written for a PARTICULAR segment — a memo from
        # upstairs, a call on the request line — is handed back to its
        # preparer instead of joining the general banter shelf, where the
        # next plain round would simply have eaten it.
        if bank_to is not None:
            if dialogue_row_viable(str(entry.get("prep_kind") or "caller"),
                                   entry):
                bank_to.append(entry)
            else:
                _why: list[str] = []
                if entry.get("off_brief"):
                    _why.append("off brief: "
                                + str((entry.get("brief") or {}).get("why")
                                      or "unspecified"))
                if not call_entry_contract(entry):
                    _why.append("final call contract/fingerprint failed")
                if not dialogue_tint_ready("caller", entry):
                    _why.append("the complete tinted version is not active")
                if not _larder_current(entry):
                    _why.append("the writing profile moved")
                _radio_entry_rejected(entry, "recording_room_rejected")
                pipeline_log(
                    "call", "the failed phone-call contract was not sent to "
                    "the recording room",
                    extra="; ".join(_why or ["the viability gate refused it"]))
            return []
        _stored = dialogue_row_viable("banter", entry)
        if _stored:
            larder_rebind_viable()                                      # 2026-09-08: the desk
            entry["expires_at"] = stock_expires_at("banter", entry)       # #1068
            _LARDER.append(entry)
            larder_trim()                                               # 2026-09-08
            try:
                _INVENTORY_PLAN["at"] = 0.0
                _COMMITS["at"] = 0.0
            except Exception:  # noqa: BLE001
                pass
        _larder_save()
        if _stored:
            pipeline_log("model", f"round banked for later "
                                  f"({len(_LARDER)} on the shelf)")
        else:
            _radio_entry_rejected(entry, "reserve_row_rejected")
            pipeline_log("lookahead", "the tinted round failed its segment "
                         "brief and was rejected before it could occupy a "
                         "reserve slot")
        return []
    if caller_name and entry.get("off_brief"):
        _radio_entry_rejected(entry, "live_call_rejected")
        return []
    try:
        return await _banter_air(entry, track)
    except Exception as exc:
        # #786: see the larder-serve wrap above — same road, same honesty.
        pipeline_log("drop", f"round render failed: "
                             f"{type(exc).__name__}: {exc}"[:180],
                     extra=traceback.format_exc()[-1200:])
        return []


async def blend_script(script: str, verbatim: list[Any] | None = None,
                       caller_name: str = "", bank: bool = False) -> str:
    """#862: THE REPROCESS PASS - the stage that was missing.

    A round is built in three movements that never met. The model WRITES
    it, under the crystal's tint and around the seed it was handed; the
    speakbox then STAPLES verbatim passages onto the front and the back of
    whatever came back; and then it airs. Nothing ever put the two
    together, so a passage lifted out of the documents lands as a
    monologue nobody answers and the conversation carries on as though it
    had not been said - a reading with chatter either side of it, which is
    exactly what "we need them to stack up" is about.

    This hands the ASSEMBLED script back to the writing room with one job:
    leave the passages alone, word for word, and rewrite what is AROUND
    them so the room reacts. It FAILS CLOSED - any doubt at all and the
    original airs unchanged, because a stapled round is worse radio than a
    blended one but a LOST round is worse than both, and a reworded
    document is the thing #838 exists to stop.

    Called on the BANK road only: #842 already establishes that a
    pre-recorded round has no clock on it and nothing waiting on it, so
    this never touches the air path."""
    if os.getenv("PINE_BLEND", "1") == "0":
        return script                   # the kill switch, no restart
    script = str(script or "")
    keep: list[str] = []
    for _row in (verbatim or []):
        try:
            one = " ".join(str(_row[1] or "").split())
        except Exception:  # noqa: BLE001
            continue
        if len(one) >= 40 and one not in keep:
            keep.append(one)
    if not keep or not script.strip():
        return script                   # nothing stapled; nothing to blend
    was = banter_turns(script, caller_name)
    if len(was) < 2:
        return script
    # ask_model clamps its budget to reply_max_chars and then truncates to
    # it, so a script already at the ceiling cannot come back whole and
    # blending it would only cost the round its tail. Said out loud in the
    # log, because the cure is the operator's own reply budget.
    budget = int(dj_settings().get("reply_max_chars") or 6000)
    if len(script) + 400 > budget:
        pipeline_log("model", "the round is already at the reply budget, "
                     "so blending it would truncate it - it airs as "
                     f"assembled ({len(script)} of {budget} chars) (#862)")
        return script
    quoted = "\n\n".join(f"PASSAGE {_n + 1}: {one}"
                         for _n, one in enumerate(keep))
    try:
        out = await ask_model(
            "Below is a radio script about to go out, and the passages "
            "inside it that get read on air WORD FOR WORD.\n\n"
            "THE PASSAGES ARE UNTOUCHABLE. They are lifted out of the "
            "station's own documents, they are already in the script, and "
            "they must still be in it, unaltered, when you are done - "
            "every word, in the same order. Do not reword, shorten, "
            "translate, re-punctuate or summarise a syllable of them, and "
            "never fold one into somebody else's sentence.\n\n"
            "EVERYTHING ELSE IS YOURS. Rewrite the turns AROUND each "
            "passage so the room reacts to it: whoever speaks next picks "
            "up a SPECIFIC word or image out of it - repeats it back, "
            "argues with it, is thrown by it, deliberately mishears it - "
            "and the turn after that carries it on. Lead INTO each "
            "passage and land OUT of it. No passage may sit at the start "
            "or the end of the round with nothing answering it. A "
            "listener has to hear ONE conversation, not a reading with "
            "chatter either side of it.\n\n"
            "Keep every speaker label as it is, keep the same number of "
            "turns, keep the subject and the energy. No markdown, no "
            "stage directions, no commentary about the rewrite, no "
            "preamble - return the script and nothing else."
            + crystal_clause(bank)                              # #1027
            + f"\n\nTHE PASSAGES:\n{quoted}\n\nTHE SCRIPT:\n{script}",
            limit=min(budget, max(900, len(script) + 300)),
            spice=0.3, num_ctx=16384)
    except Exception as exc:  # noqa: BLE001
        pipeline_log("model", "the blend pass failed; the round airs as "
                     f"assembled ({type(exc).__name__}) (#862)")
        return script
    out = str(out or "")
    # Every gate below returns the ORIGINAL. Blending is an improvement,
    # never a dependency.
    now = banter_turns(out, caller_name)
    technical = bool(not now or any(not str(s).strip() or not re.search(r"[^\W_]", str(s))
                                   or _looks_meta(str(s))
                                   for _m, s in now))
    faults = []
    if technical:
        faults.append("the blend has no usable speaker-labelled script")
    if not looks_english(out):
        faults.append("the blend did not pass the language detector")
    if len(out) < int(len(script) * 0.8):
        faults.append("the blend shortened the assembled script by more than a fifth")
    if not (len(was) <= len(now) <= len(was) + 6):
        faults.append("the blend changed the permitted turn count")
    flat = " ".join(out.split()).lower()
    for one in keep:
        if one.lower()[:60] not in flat:
            faults.append("the blend reworded a preserved source passage")
    if faults:
        allowed = line_review_permits("blend", script, out, reasons=faults,
            context={"kind": "caller" if caller_name else "banter", "stage": "blend_rejected",
                     "script_plain": script, "script": out, "turns": was,
                     "verbatim": verbatim or [], "caller_name": caller_name},
            evaluation={"ok": False, "machine_ok": False, "machine_faults": faults},
            technical=technical, record=True, disposition="rewrite_rejected")
        if technical or not allowed:
            return script
    pipeline_log("model", f"the round was blended: {len(keep)} verbatim "
                 f"passage(s) kept word for word and {len(now)} turns "
                 "written around them (#862)", extra=out[:1200])
    return out


def _script_repeats(script: str, caller_name: str = "",
                    caller2_name: str = "") -> list[str]:
    """Which lines of a written round would be refused if it aired NOW.

    #901: the collision scan on its own, with no model call and no
    rewrite behind it, so a road can ASK whether banked material has
    gone stale without paying to fix it. freshen_script answers the same
    question inside itself; this is the half a prepared round needs at
    air time, when the question finally means something.

    Never raises. A round that cannot be judged is not a round that has
    to be held back — an unanswerable question means "no"."""
    out: list[str] = []
    try:
        cfg = phrase_setup()
        seen: set[str] = set()
        for marker, said in banter_turns(script, caller_name, caller2_name):
            if marker in ("C", "E"):    # a caller is a guest, not a rerun
                continue
            who = ("dj" if marker == "A"
                   else "third" if marker == "D" else "cohost")
            body = spoken_text(said)
            if not body:
                continue                # dropped at the door for other reasons
            if phrase_check(body, who, seen).get("block") \
                    or air_repeat_check(body, who).get("block"):
                out.append(said)
            else:
                seen.update(phrase_grams(body, cfg["n"]))
    except Exception:  # noqa: BLE001
        return []
    return out


async def freshen_script(script: str, caller_name: str = "",
                         caller2_name: str = "",
                         verbatim: list[Any] | None = None) -> str:
    """#959: the freshener, with the caller counted either side of it.

    The rewrite hands the WHOLE script to the model and asks it to keep
    every speaker label as it stands. Mostly it does. When it does not —
    and a one-line script, which is what the model returns most of the
    time, gives it every chance not to — the 'C:' markers come back
    folded into the hosts and the call has no caller in it any more.
    Nothing checked. It runs TWICE on a banked call (once in
    larder_prepare, again in _banter_air when the script has gone stale),
    so a prepared phone call had two chances to quietly become two hosts
    talking about somebody who was never on the line. That is the fault
    the operator has now reported three separate ways.

    So it is counted. If the round went in with a caller and comes back
    without one, the rewrite is refused and the original script stands —
    a script that repeats a phrase is a far smaller fault than a phone
    call with nobody on the phone."""
    before = 0
    try:
        if caller_name or caller2_name:
            before = sum(1 for m, _t in banter_turns(
                script, caller_name, caller2_name) if m in ("C", "E"))
    except Exception:  # noqa: BLE001
        before = 0
    fresh = await _freshen_script(script, caller_name, caller2_name, verbatim)
    if not before:
        # #977: a call that arrived with NO caller turns is not a script
        # this function can wave through - it is the fault itself. The
        # guard could only ever refuse a regression, so the one case that
        # matters, a call written badly in the first place, walked
        # straight past it. Say so where it can be seen; the caller-turn
        # count is checked again by the gate in dj_banter, which #977 also
        # taught to count with the parser rather than by line.
        if caller_name:
            pipeline_log("model", f"the call for {caller_name} reached the "
                                  "freshener with NO caller turns in it — "
                                  "the fault is upstream of the rewrite "
                                  "(#977)")
        return fresh
    try:
        after = sum(1 for m, _t in banter_turns(
            fresh, caller_name, caller2_name) if m in ("C", "E"))
    except Exception:  # noqa: BLE001
        return script
    if after < before:
        pipeline_log("model", f"the freshener came back with {after} caller "
                              f"turn(s) where the call had {before} — the "
                              "rewrite is refused and the original script "
                              "stands (#959)")
        return script
    return fresh


async def _freshen_script(script: str, caller_name: str = "",
                          caller2_name: str = "",
                          verbatim: list[Any] | None = None) -> str:
    """Rewrite a round that is about to repeat itself, before it airs (#no-repeats).

    The old engine's only answer to a repeat was to DROP the line at the door,
    which is how an anti-repeat gate makes a thin show and then a silent one —
    and it is why the #777 fallback had to exist at all. This is the answer
    the operator actually asked for: ask for the line again, naming the phrase
    it may not use, and when the model will not let go of it, replace the line
    with material off the speakbox shelf.

    Runs on the larder road as well as the fresh one, which is where it earns
    the most: banked rounds are written six to twelve deep against a shelf
    nothing updates until one airs, so several of them can carry the same
    passage and then go out one after another."""
    # #838: "I am still not hearing enough random speakerbox rhetoric."
    # The full reading and the prepended/appended passages are placed
    # into the script AFTER the writing precisely so they cannot be
    # summarised - and then this function handed the ENTIRE script to the
    # model with "say the offending parts a COMPLETELY different way",
    # which reworded the operator's own documents out of the round
    # whenever ANY OTHER line tripped the hour-long cooldown. With
    # phrase_retries at 1 and a station that has been on all night, that
    # is most rounds. The passages are skipped by the collision scan
    # (they are the documents, not the pair repeating themselves) and put
    # back word for word if a rewrite dropped them anyway.
    _keep: list[tuple[str, str]] = []
    for _row in (verbatim or []):
        try:
            _where = str(_row[0] or "head")
            _text = " ".join(str(_row[1] or "").split())
        except Exception:  # noqa: BLE001
            continue
        if len(_text) >= 40:
            _keep.append((_where, _text))

    def _protected(said: str) -> bool:
        """Whether this turn IS one of the verbatim passages."""
        flat = " ".join(str(said or "").split())
        if not flat:
            return False
        return any(flat == one or one in flat
                   or (len(flat) >= 40 and flat in one)
                   for _w, one in _keep)

    def _restore(text: str) -> str:
        """Put back any verbatim passage the rewrite reworded away."""
        if not _keep:
            return text
        out_text = str(text or "")
        for _where, one in _keep:
            try:
                probe = one.lower()[:60]
                if probe and probe in " ".join(out_text.split()).lower():
                    continue
                if _where == "tail":
                    out_text = out_text.rstrip() + f"\nA: {one}"
                else:
                    out_text = f"A: {one}\n" + out_text.lstrip()
                pipeline_log("speakbox", "a verbatim passage the rewrite "
                             "reworded away was put back word for word "
                             "(#838)")
            except Exception:  # noqa: BLE001
                continue
        return out_text

    cfg = phrase_setup()
    if not (cfg["station"] or cfg["self"]):
        return script

    def _collisions(text: str) -> list[tuple[str, dict[str, Any]]]:
        out: list[tuple[str, dict[str, Any]]] = []
        seen: set[str] = set()          # and the round against itself (#no-repeats)
        for marker, said in banter_turns(text, caller_name, caller2_name):
            if marker in ("C", "E"):    # a caller is a guest, not a rerun
                continue
            who = ("dj" if marker == "A"
                   else "third" if marker == "D" else "cohost")
            # #838: the operator's own words are not a repeat by the
            # pair, and flagging them is what sent the whole round
            # (passages included) off to be reworded.
            if _protected(said):
                continue
            body = spoken_text(said)
            verdict = phrase_check(body, who, seen)
            if verdict["block"]:
                out.append((said, {**verdict, "who": who}))
            else:
                seen.update(phrase_grams(body, cfg["n"]))
        return out

    hits = _collisions(script)
    for _ in range(cfg["retries"]):
        if not hits:
            return _restore(script)             # #838
        # #862: ask_model clamps its answer to reply_max_chars and then
        # TRUNCATES to it, so a script longer than the budget is handed
        # back with its ending missing - the appended passage and the
        # turns around it included. Fall through to the swap instead: it
        # replaces only the repeated lines, off the documents, and the
        # round keeps its length and its verbatim material.
        if len(script) + 400 > int(dj_settings().get("reply_max_chars")
                                   or 6000):
            pipeline_log("model", "the round is longer than the reply "
                         "budget - a rewrite would come back with its "
                         "ending cut off, so the repeated lines are "
                         "swapped for fresh material instead (#862)")
            break
        banned = "; ".join(f'"{v["phrase"]}"' for _s, v in hits[:8])
        pipeline_log("model", f"{len(hits)} line(s) reuse a phrase already on "
                              "air this hour — asking for them again (#no-repeats)",
                     extra="BANNED THIS ROUND:\n" + banned)
        rewritten = await ask_model(
            "Below is a radio script that is about to go out. Some of its "
            "lines reuse wording the station has ALREADY broadcast tonight, "
            "so they cannot air as written.\n\n"
            f"BANNED — not one of these may appear, in any form, however "
            f"reworded: {banned}\n\n"
            "Rewrite the WHOLE script. Keep every speaker label exactly as it "
            "is, keep the same number of lines, keep the meaning and the "
            "energy — and say the offending parts a COMPLETELY different way: "
            "different words, different images, a different angle on it, not "
            "a synonym swap. No markdown, no stage directions, no commentary "
            "about the rewrite.\n\n" + script,
            limit=max(700, len(script) + 500), spice=0.6)
        if not rewritten or ":" not in rewritten:
            line_review_capture("freshen_structure", script, str(rewritten or ""),
                reasons=["the repetition rewrite returned no usable speaker-labelled script"],
                context={"kind": "caller" if caller_name else "banter",
                         "stage": "freshen_rejected", "script_plain": script,
                         "caller_name": caller_name, "caller2_name": caller2_name},
                technical=True, disposition="rewrite_rejected")
            break                       # the model is down; the show is not
        for _said, _verdict in hits:
            line_review_capture("repetition", spoken_text(_said),
                reasons=[str(_verdict.get("why") or "a phrase already aired")],
                context={"who": str(_verdict.get("who") or ""), "stage": "freshen_replaced",
                         "script_plain": script, "replacement_script": rewritten,
                         "caller_name": caller_name, "caller2_name": caller2_name},
                evaluation=_verdict, disposition="rewrite_rejected")
        script = rewritten
        hits = _collisions(script)
    if not hits:
        return _restore(script)                 # #838
    # It would not let go. Give those lines to the documents instead — this
    # is "prompt them to say more from the speakerbox database", and it is
    # also what makes holding a line back safe: the round keeps its length.
    if not cfg["swap"]:
        return _restore(script)                 # #838
    stuck = {said for said, _v in hits}
    out: list[str] = []
    swapped = 0
    for line in script.splitlines():
        body = re.sub(r"^\s*[A-E]\s*:\s*", "", line)
        if body == line or body not in stuck:
            out.append(line)
            continue
        fresh = fresh_pool_take()
        if not fresh.get("text"):
            out.append(line)
            continue
        _verdict = next((v for s, v in hits if s == body), {})
        line_review_capture("repetition", spoken_text(body),
            reasons=[str(_verdict.get("why") or "a phrase already aired")],
            context={"who": str(_verdict.get("who") or ""), "stage": "freshen_swapped",
                     "script_plain": script, "replacement": fresh,
                     "caller_name": caller_name, "caller2_name": caller2_name},
            evaluation=_verdict, disposition="cut")
        out.append(line[:len(line) - len(body)] + fresh["text"])
        speakbox_remember({"file": fresh.get("file", ""),
                           "text": fresh["text"], "lines": [fresh["text"]],
                           "mind": fresh.get("mind", "")})
        swapped += 1
    if swapped:
        pipeline_log("speakbox", f"{swapped} line(s) the model would not let "
                                 "go of were replaced with fresh material off "
                                 "the shelf (#no-repeats)")
    return _restore("\n".join(out))             # #838


async def _banter_air(entry: dict[str, Any],
                      track: dict[str, Any] | None, *,
                      ready_takes: list[dict[str, Any]] | None = None,
                      on_handoff: Any = None, can_handoff: Any = None) -> list[str]:
    """Put a written round on air — fresh from the model or off the larder
    shelf (#349), the airing is the same either way."""
    if not _system2_repeat_rows(ready_takes if ready_takes is not None else
            [{"text": text} for _, text in banter_turns(str(entry.get("script") or ""),
                str(entry.get("caller_name") or ""), str(entry.get("caller2_name") or ""))], entry):
        return []
    airlog_round_hint(str(entry.get("prep_kind") or ""),
                      caller=str(entry.get("caller_name") or ""))  # #1023 (G1)
    # #1050 (P1): which lines were already in the ring, so the stamp at the
    # bottom of this function can name the ones this round became.
    _sp_mark = screenplay_round_open(entry)
    # #1005: THE PICTURES BELONG TO THE ROUND, NOT TO THE STATION.
    #
    # This is the one place every prepared round passes through on its way
    # to the air, and the entry knows what it is about: a gallery round
    # banked hours ago carries the paintings it was written from
    # (prep_gallery, #855) so the vision passes are paid for exactly once.
    # Setting the standing pictures HERE, and clearing them for a round
    # that has none, is what stops the previous gallery round's painting
    # from hanging beside the next round's phone call - which is exactly
    # what happened when this was read off the station's own "what is
    # being held up" instead.
    try:
        _pics = [str((p or {}).get("name") or "")
                 for p in (entry.get("prep_gallery") or [])]
        _descs = [str((p or {}).get("desc") or "")
                  for p in (entry.get("prep_gallery") or [])]
        if [p for p in _pics if p]:
            gallery_pending_set([p for p in _pics if p], _descs)
        else:
            _GALLERY_PENDING.clear()
    except Exception:  # noqa: BLE001
        pass
    # A prewritten round is the station's continuity reserve. When another
    # segment is already holding the model gate, never queue this reserve
    # behind a rewrite: speak_turns still applies its line-level repetition
    # checks, but the ready audio path must remain immediately available.
    # #901: a prepared round can sit on the shelf for HOURS —
    # larder_fresh() is max(_LARDER_FRESH, pantry_life()), which #904
    # deliberately stretched to match the life of its own audio — and it
    # was frozen against a ledger that has moved on since. #886 sends it
    # straight to air on the grounds that it was "already freshened",
    # which was true when it was frozen and is the whole question here.
    # So it is re-tested at the moment it actually airs. The scan costs
    # no model call; only a round that really has gone stale pays for a
    # rewrite, and paying it is better than airing a rerun.
    _stale = False
    # #1063: "If a statement is recorded and staged for the radio, then it
    # is to be played on the radio. There's no circumstance in which lines
    # are recorded and not played." A frozen round whose every line has a
    # finished take is RECORDED: the cuts belong before the studio, and
    # the #901 freshen below - which threw the prepared clips away for a
    # repeat scan at air time - no longer applies to it. The scan still
    # runs, so the log can say what would have been cut.
    _recorded = ready_takes is not None
    if entry.get("frozen"):
        try:
            _recorded = dialogue_audio_ready(
                str(entry.get("prep_kind") or "banter"), entry)
        except Exception:  # noqa: BLE001
            _recorded = False
        try:
            _stale_lines = _script_repeats(entry.get("script", ""),
                                           entry.get("caller_name", ""),
                                           entry.get("caller2_name", ""))
        except Exception:  # noqa: BLE001
            _stale_lines = []
        if _stale_lines and _recorded:
            pipeline_log("air", f"(#1063) a recorded round airs as recorded "
                         f"- {len(_stale_lines)} line(s) would now be "
                         "refused as repeats, and that cut belongs before "
                         "the studio, not after it")
        elif _stale_lines:
            _stale = True
            pipeline_log("air", "a prepared round has gone stale on the "
                         "shelf — lines in it have been on air since it "
                         "was frozen, so it is freshened before it airs "
                         "even though that costs its prepared clips "
                         "(#901)")
    if ready_takes is not None:
        ready_takes = copy.deepcopy(ready_takes)
        if not ready_takes:
            return []
        ready_takes[0]["round"] = copy.deepcopy(entry)
    elif entry.get("frozen") and not _stale:
        # #886: already freshened while a record played, and the audio was
        # rendered against exactly this text. Rewriting it now would throw
        # the prepared clips away and put a model call back on the air
        # path — the two things preparing it was for.
        pipeline_log("air", "a prepared round goes straight to air — its "
                     "audio was made during the last record (#886)")
    elif str(entry.get("script_tinted") or ""):
        # #1077: A TINTED ROUND IS NEVER FRESHENED. freshen_script has
        # no crystal in it at all - #1025's words - and its fallback
        # swaps stuck lines for raw speakbox material, so running it
        # over a rewritten round airs neither the tinted version nor
        # the plain one but a third, de-tinted text. larder_prepare was
        # given this guard by #1025; this path never got it.
        #
        # The failure was INVERTED: the branch below only spared the
        # tint when the model gate was busy, which is 99.6% of the
        # time - so the rewrite was destroyed precisely when the
        # station was calm enough to air a good round.
        pipeline_log("air", "a tinted round goes to air as it was "
                            "rewritten - freshening would undo the "
                            "crystal (#1077)")
    elif _OLLAMA_GATE.locked():
        pipeline_log("air", "larder round bypasses model freshening while "
                     "the desk is still writing — keeping talk on air")
    else:
        entry["script"] = await freshen_script(
            entry["script"],
            entry.get("caller_name", ""),
            entry.get("caller2_name", ""),
            entry.get("verbatim"))              # #838
    # #913: A PREPARED CALL MUST STILL HAVE SOMEBODY AUDIBLE ON THE LINE.
    #
    # The round was written and shelved up to an hour ago, and the voice
    # drawn for its caller then has to survive the wait: a clone is only a
    # voice while the clone engine is up and its reference is still on disk,
    # and a Piper name only while it is installed. If it no longer resolves,
    # draw another. Doing nothing would leave caller_voice empty, _turn_voice
    # would hand speak_turns None, and the caller would air on the default —
    # which is the HOST's voice. A caller who sounds like the host is a
    # caller nobody heard, and that is the whole of #913.
    #
    # The caller's TURNS need no such rescue: they were deliberately never
    # prepared (#871), so they simply miss the pantry, _premake_inner renders
    # them live, and its #784 ladder takes a Piper stand-in if the clone
    # engine is cold. The dialogue never stops.
    if ready_takes is None and str(entry.get("caller_name") or ""):
        # #1151: ...UNLESS THE CALL IS ALREADY RENDERED IN THAT VOICE.
        # Playing a finished WAV needs no engine, so the #913 health
        # redraw must not fire for a banked call - a transient engine
        # nap at air time used to swap the caller's voice, which re-keyed
        # every prepared take out of the pantry (voice is IN pantry_key):
        # the hosts hit the shelf, the caller rendered live, and the
        # listener heard somebody say their name and stop talking.
        _held_cv = str(entry.get("caller_voice") or "")
        _cv_taken = bool(_held_cv and any(
            str(t.get("voice") or "") == _held_cv
            for t in (entry.get("takes") or [])))
        if not _cv_taken:
            try:
                entry["caller_voice"] = await caller_line_voice(
                    str(entry.get("caller_name") or ""),
                    str(entry.get("caller_voice") or ""))
            except Exception:  # noqa: BLE001
                pass
    spoken = await speak_turns(banter_turns(entry["script"],
                                            entry.get("caller_name", ""),
                                            entry.get("caller2_name", "")),
                               track,
                               entry["lines"], entry.get("vouched"),
                               entry.get("source", ""),
                               # At 100% the exact prepared take outranks the
                               # repetition beautifier. That gate was swapping
                               # lines after readiness had certified their
                               # audio, re-keying a zero-work larder round into
                               # live XTTS and recreating a 20-second hole.
                               allow_repeat=talk_is_incessant(),
                               caller_name=entry.get("caller_name", ""),
                               caller_voice=entry.get("caller_voice", ""),
                               caller_fx=entry.get("caller_fx"),
                               source_text=entry.get("seed_text", ""),
                               caller2_name=entry.get("caller2_name", ""),
                               caller2_voice=entry.get("caller2_voice", ""),
                               # #859: a message stays whole even when it
                               # airs off the shelf hours after it was
                               # written, which is its usual road now.
                               whole=bool(entry.get("whole")),
                               # #769: the round decides how it AIRS at the
                               # moment it airs. Larder rounds are banked by
                               # dj_banter(bank=True), which takes the default
                               # False, so every round off the shelf aired
                               # turn-by-turn — a separate announce and a
                               # 900 ms tail per chunk — while fresh rounds
                               # streamed. Two engines, alternating, which is
                               # exactly what "sounding inorganic" was.
                               render_stream=bool(
                                   entry.get("render_stream")
                                   or dj_settings().get("stream_show")),
                               feel=entry.get("feel", False),
                               # #1063: a recorded round airs as recorded.
                               recorded=_recorded,
                               tint_report=dict(entry.get("tint") or {}),
                               ready_takes=ready_takes, on_handoff=on_handoff,
                               can_handoff=can_handoff)
    # #1050 (P1): the round's paperwork, written down before the entry is
    # dropped. The swaths, the tint with both scripts, the writing desk and
    # the line ids - everything the screenplay's provenance tree shows, and
    # all of it lives only on this dict until now.
    screenplay_round_stamp(entry, _sp_mark)
    if ready_takes is None and entry.get("seek_verdict") and spoken:
        asyncio.create_task(_sfx_verdict(spoken[-1]))
    if spoken:
        stats = _RADIO.setdefault("session_stats", {"calls": 0, "rounds": 0})
        stats["rounds"] = int(stats.get("rounds") or 0) + 1
        # Every fifth round the crystal takes a note of its own (#364).
        if ready_takes is None and stats["rounds"] % 5 == 0:
            asyncio.create_task(crystal_distill())
        aired = " ".join(spoken)
        # Only what actually went out is remembered as heard — a round that
        # broke early used to retire up to eighteen lines nobody ever spoke,
        # and the library burned without airing.
        for swath in ([] if ready_takes is not None else entry.get("swaths") or []):
            said_lines = [line for line in (swath.get("lines")
                                            or [swath.get("text", "")])
                          if line and line in aired]
            if said_lines:
                speakbox_remember({"file": swath.get("file", ""),
                                   "text": " ".join(said_lines),
                                   "lines": said_lines})
    return spoken


# How the pair take a call. Picked per call so they are not amused by
# everything and appalled by nothing (#179).
CALLER_MOODS = ("surprise", "pity", "hope", "lust", "alarm", "envy",
                "grudging respect", "genuine concern")

# #879: who the caller IS tonight. A stranger rings with a temper and a
# reason, not as a prop for the hosts — and they arrive with something
# already prepared to say, so the pair can be caught out by them.
CALLER_DISPOSITIONS = (
    "wound up and talking too fast, convinced they are being ignored",
    "flat and exhausted, saying enormous things in a small voice",
    "delighted, almost manic, treating this as the highlight of a "
    "terrible week",
    "suspicious of the hosts, testing whether they are really live",
    "grieving something they will not name outright",
    "half-cut and far too honest, cheerfully overshares",
    "an expert on something nobody asked about, and correct",
    "furious about a thing that turns out to be tiny",
    "shy to the point of pain, then suddenly savage",
    "a regular who behaves like an old friend the hosts do not recall",
    "calling from somewhere loud with a story they keep losing",
    "eerily calm, and knows something about the station",
    "on the wind-up, playing a character and enjoying it",
    "in the middle of doing something else, distracted, then rapt",
    "lonely and stretching the call, dodging the goodbye",
)


async def caller_disposition_clause(themed: str = "") -> str:
    """#879: the caller's own temper, and a line they arrived ready to
    say. The speakbox supplies the line so it is genuinely material the
    hosts have not seen — and under an active crystal it is tinted like
    every other word on this station."""
    mood = random.choice(CALLER_DISPOSITIONS)
    prepared = ""
    try:
        seed = await speakbox_quote(most=2, cap=220)
        line = str((seed or {}).get("text") or "").strip()
        if line:
            prepared = (
                " They did not ring in empty-handed: they have ALREADY "
                "decided to say this, and they work it in whether or not "
                "it fits the hosts' mood — the pair have never heard it "
                f"and must react on the spot: \"{line[:220]}\"."
                )
            # #879: the observatory sees the caller too — a stranger
            # arriving with tinted material is exactly the kind of
            # trajectory that view exists to draw.
            try:
                _crystal_influence_note(str(seed.get("mind") or ""),
                                        str(seed.get("file") or ""),
                                        line[:220], "caller")
            except Exception:  # noqa: BLE001
                pass
    except Exception:  # noqa: BLE001
        prepared = ""
    return (f" The caller's own disposition tonight: {mood}. Play them "
            "as a person with their own evening, not a prop — they can "
            "interrupt, disagree, refuse to be handled, and take the "
            "hosts somewhere they did not plan to go." + prepared
            + (themed or ""))


def show_open_when() -> str:
    """What to say about the hour at the top of the show (#194)."""
    now = time.localtime()
    clock = time.strftime("%I:%M %p", now).lstrip("0")
    hour = now.tm_hour
    if hour < 5:
        return (f"It is {clock}, the small hours — greet whoever is somehow "
                "still awake.")
    if hour < 12:
        return f"It is {clock} in the morning — say good morning."
    if hour < 17:
        return f"It is {clock} in the afternoon — say good afternoon."
    if hour < 22:
        return f"It is {clock} in the evening — say good evening."
    return f"It is {clock}, late — greet the night shift."


async def dj_open_show() -> list[str]:
    """The top of the show.

    A greeting that knows what time it is, a joke or two about what he has
    had the pair doing lately, and then a hand-off to the first record —
    rather than one stock line and straight into the music (#194)."""
    pool = banter_pool(2)
    material = "; ".join(pool)
    return await dj_banter(None, lines=4, angle=(
        f"you are opening the session. {show_open_when()} Welcome people to "
        "the station, mention between you what he has had the two of you "
        "doing lately"
        + (f", and make something of one of these: {material}" if material
           else "")
        + ". Finish by handing over to the first record of the session."
    ))


async def dj_manager_note(track: dict[str, Any] | None = None,
                          bank_to: list[dict[str, Any]] | None = None,
                          shelf_only: bool = False
                          ) -> list[str]:
    """A memo from the manager upstairs, read out on air.

    The manager is whatever system prompt is armed: his instructions are its
    instructions, so changing the prompt changes what management wants said
    tonight — the ad reads, the sponsorships, the tone (#189). It is read as
    a memo rather than obeyed as an instruction, which is what keeps a prompt
    written for the assistant from turning the DJs into one."""
    if shelf_only or (bank_to is None and talk_is_incessant()):
        return await _ready_shelf_air("manager", track)
    # #842: a memo WRITTEN AND VOICED during an earlier record goes
    # straight out — no model call, no render, no wait. `bank_to` is the
    # other side of the same door: the preparer calls THIS function to
    # write one, and is handed the round back instead of it airing. An
    # empty shelf falls through to the live road below, unchanged.
    if bank_to is None:
        try:
            _prep_memo = shelf_take("manager")
        except Exception:  # noqa: BLE001
            _prep_memo = None
        if _prep_memo:
            try:
                _prep_said = await _banter_air(
                    _prep_memo.get("entry") or {}, track)
            except Exception:  # noqa: BLE001
                _prep_said = []
            if _prep_said:
                quota_stamp("manager")     # #841: the hour counts it
                try:                       # #1146: stamp the book's ledger
                    _pentry = _prep_memo.get("entry") or {}
                    await asyncio.to_thread(
                        manager_memo_save,
                        str(_pentry.get("script") or "")
                        or "\n".join(_prep_said),
                        "banked", True,
                        str(_pentry.get("memo_id") or ""))
                except Exception:  # noqa: BLE001
                    pass
                return _prep_said
    # When the machine runs hot, the memo is about the HEAT (#375): the
    # manager upstairs feels the same air the computer makes.
    hot = booth_hot()
    # #841: whether there is anything to READ OUT is settled BEFORE any
    # material is drawn. A memo that cannot run must not eat a swath off
    # the shelf or file a phantom row in the crystal observatory for words
    # that never reached the air.
    _hot_memo = hot >= 70 and random.random() < 0.5
    # #983: the memo from upstairs is written by the STATION, not by the
    # Pine agent. This read the agent's armed prompt, so whatever the
    # assistant was told to be turned up in management's letters too.
    note = (station_disposition_text(800) + radio_prompt_instruction("manager")
            + radio_prompt_instruction("workplace")).strip()
    if not _hot_memo and not note:
        return []               # nothing has come down from upstairs
    # "tinted and talking speakerbox". Drawn exactly the way the
    # caller's own disposition draws hers (#879) - a swath off the shelf,
    # folded into the memo as something management have put IN WRITING,
    # and stamped into the observatory feed so the crystal trajectory view
    # sees upstairs too. speakbox_quote already prefers a crystal's own
    # minds while one is on (#834), so the tint arrives as MATERIAL, which
    # a small model obeys far harder than an instruction.
    flavour = ""
    try:
        _mseed = await speakbox_quote(most=3, cap=280)
        _mtext = str((_mseed or {}).get("text") or "").strip()
        if _mtext:
            flavour = (
                " The memo is not only orders: management have LIFTED a "
                "passage out of the station's own material and typed it "
                "into the memo word for word. The pair have to deal with "
                "it as written, on air, with no idea where he got it: "
                f"\"{_mtext[:280]}\".")
            # NB: four arguments - mind, file, text, kind.
            _crystal_influence_note(str(_mseed.get("mind") or ""),
                                    str(_mseed.get("file") or ""),
                                    _mtext[:280], "manager")
    except Exception:  # noqa: BLE001
        flavour = ""            # the memo still goes out, just untinted
    try:
        # ...and the world-tint in HIS mouth specifically. dj_banter folds
        # crystal_clause() into every prompt already; this is the same
        # nudge the SFX guy's brews carry (#820), aimed at upstairs.
        # #1018: ...and it stands aside when the tint is a SECOND PASS,
        # exactly as crystal_clause() does. Under two-pass the round is
        # written plain on purpose - that is what makes the "before" of
        # the before-and-after an actual before - and the crystal's own
        # lines reach it in crystal_tint() instead.
        _mcrs = [] if crystal_tint_two_pass() else crystal_active()
        if _mcrs:
            _mcr = random.choice(_mcrs)
            flavour += (" Upstairs has fallen into it as hard as the rest "
                        "of the town: let this flavour run through the "
                        "memo's own wording and through how they read it "
                        "out - "
                        f"{str(_mcr.get('tint') or _mcr.get('name'))[:120]}."
                        # #1018: with the world's own lines to work from.
                        + crystal_style_note())
    except Exception:  # noqa: BLE001
        pass
    if _hot_memo:
        _hot_said = await dj_banter(track, lines=3, whole=True,   # #859
                                    bank=bank_to is not None,
                                    bank_to=bank_to, own_material=True, angle=(
            "an urgent memo has just come down from the manager upstairs: "
            f"it is VERY hot in the building — {hot:.0f} degrees Celsius, "
            f"{hot * 9 / 5 + 32:.0f} Fahrenheit, straight off the "
            "machine's own sensors — and management wants it COOLED OFF: "
            "calmer records, fewer renders, someone fan the servers. Read "
            "it out, react, and take it personally — you two are the ones "
            "sweating in here." + flavour))
        if _hot_said:
            # #841: stamped where it AIRED, not where it was scheduled.
            quota_stamp("manager")
            try:                           # #1146: the book keeps it
                await asyncio.to_thread(
                    manager_memo_save, "\n".join(_hot_said), "live", True)
            except Exception:  # noqa: BLE001
                pass
        return _hot_said
    # `note` and its guard now live at the top of the function, above the
    # material draw (#841).
    # #1173: MOST MEMOS ARE ABOUT THEM. See the note in the patch - three
    # of thirty-four memos on the shelf carried a grievance, because the
    # memo was made of the station's system prompt. The gripe book has
    # three hundred that are personal and this road had never read one.
    _gripe = ""
    try:
        if random.random() < float(dj_settings().get(
                "manager_gripe_pct", MANAGER_GRIPE_PCT)) / 100.0:
            _rows = [r for r in upstairs_list()
                     if str(r.get("gripe") or "").strip()]
            if _rows:
                _fewest = min(int(r.get("uses") or 0) for r in _rows)
                _pick = random.choice([r for r in _rows
                                       if int(r.get("uses") or 0) == _fewest])
                _gripe = str(_pick.get("gripe") or "").strip()[:200]
                upstairs_update(str(_pick.get("id") or ""),
                                uses=int(_pick.get("uses") or 0) + 1,
                                last=int(time.time()))
    except Exception:  # noqa: BLE001
        _gripe = ""            # a broken book never silences the booth
    if _gripe:
        _angle = (
            "a memo has just come down from the manager upstairs, and it is "
            "about THE TWO OF YOU. One of you reads it out to the other and "
            "to the listeners. What management wants you to know is this:\n"
            f"\"{_gripe}\"\n"
            "Do not read that back word for word - it is a memo, so say it "
            "the way a memo says it, and then deal with it on air. Take it "
            "personally, because it is personal: defend yourself, blame each "
            "other, agree with it in a way that is worse than arguing, or "
            "quietly do what it says while complaining. The manager is never "
            "in the room and never speaks in his own voice." + flavour)
    else:
        _angle = (
            "a memo has just come down from the manager upstairs. One of you "
            "reads it out to the other and to the listeners, and you both "
            "react on air — agree with it, wince at it, push back on it, "
            "whatever it deserves. Management's instructions, in their own "
            "words, are:\n"
            f"\"{note}\"\n"
            "Do not read that back word for word. Say what it means for the "
            "show tonight, and mention any product or sponsorship it asks "
            "you to push." + flavour)
    _said = await dj_banter(track, lines=3, whole=True,           # #859
                            bank=bank_to is not None,
                            bank_to=bank_to, own_material=True,
                            angle=_angle)
    if _said:
        quota_stamp("manager")             # #841: the hour counts it
        try:                               # #1146: the book keeps it
            await asyncio.to_thread(
                manager_memo_save, "\n".join(_said), "live", True)
        except Exception:  # noqa: BLE001
            pass
    return _said


async def dj_manager_call(text: str, doc: str = "") -> list[str]:
    """The booth phone goes and it is UPSTAIRS (#636).

    The memo version already exists above; this is the same person on the
    line, reading a passage down it at the host by name — which is what
    makes it land on somebody rather than on the room.
    """
    dj = dj_settings()
    voices = await session_voices()
    boss = str(dj.get("manager_name") or "").strip() or "the manager upstairs"
    try:
        voice = caller_voice_for(
            boss, {voices.get("dj", ""), voices.get("cohost", "")},
            await voice_allowlist(),
            clones=await voicepolicy_clone_pool_async()) or ""   # #1021
    except Exception:
        voice = ""
    host = dj.get("host_name") or "the host"
    return await dj_banter(
        _RADIO.get("now"), lines=4, source=doc, own_material=True,
        caller_name=boss, caller_voice=voice,
        # One floor up, down an internal line: a little phone crush and no
        # character at all — the calm is the threat.
        caller_fx={"vocode": "plain", "pitch": -2},
        angle=(
            f"The BOOTH phone goes — the internal line. It is {boss}, from "
            f"the office UPSTAIRS, and they have asked for {host} by name. "
            "They are not angry, they are worse than angry: calm. They read "
            "this at the host, word for word, and will not be hurried:\n"
            f"\"{text}\"\n"
            "The host takes it standing up. The co-host can hear one side of "
            "it and reacts. End with the line going dead and nobody quite "
            "explaining what that was about."))


async def dj_fan_mail(text: str, doc: str = "") -> list[str]:
    """A listener's letter, opened on air and argued over (#636)."""
    return await dj_banter(
        _RADIO.get("now"), lines=5, source=doc, own_material=True,
        angle=("A letter has arrived at the station addressed to the two of "
               "you. One of you OPENS it on air — the envelope, the paper, "
               "the handwriting, all of it described — and reads it out a "
               "line at a time, the other reacting between the lines: "
               "delighted, suspicious, moved, alarmed. The letter says, word "
               f"for word:\n\"{text}\"\n"
               "Do not paraphrase it away — the listener's own words go out. "
               "Argue about what they MEANT by it, decide whether to write "
               "back, and give the sender a name if they did not."))


# "It's so hot that…" — the comparative bank the callers reach for (#644).
# A caller complaining about heat does not describe a temperature, they
# escalate. These are the shape, not a script: the model is told to top them.
HEAT_SO_HOT = [
    "the birds are falling out of the sky",
    "my kid came in already on fire",
    "my husband evaporated in the hallway",
    "all four tires popped in the driveway",
    "my ex turned to dust on the porch",
    "the gutters slid off the house",
    "my own Pine Box melted into the shelf",
    "the walls of the house are going soft",
    "the furniture collapsed in on itself",
    "the dog has started smoking",
    "the paint came off the car in a sheet",
    "the mailbox is leaning like a candle",
    "my glasses fused to my face",
    "the pool boiled and the neighbours made tea in it",
    "the road is moving like it is breathing",
    "the ice maker just sighed and quit",
    "the cat has gone translucent",
    "my phone rang and it was the phone screaming",
]


def heat_joke_bank(most: int = 6) -> str:
    """A handful of comparatives, shuffled, plus whatever the model has
    evolved for the current band (#644)."""
    pool = list(HEAT_SO_HOT)
    band, _c = heat_band()
    if band:
        pool += [line for line in _heat_read().get(band, []) if line]
    random.shuffle(pool)
    return "; ".join(pool[:most])


async def caller_line_voice(name: str, held: str = "") -> str:
    """#913: a voice for the person on the phone that is USABLE RIGHT NOW.

    A prepared call is written and shelved up to an hour before it airs, so
    the voice drawn for its caller has to survive the wait. A clone id is
    only a voice while the clone engine is up and the reference it was cut
    from is still on disk; a Piper name is only a voice while it is
    installed. When the one the round is carrying no longer resolves, draw
    another rather than let the caller air on the empty default — which is
    the HOST's voice, and a caller who sounds like the host is a caller
    nobody heard.

    `held` is kept whenever it still works, so the same person ringing
    twice still sounds like the same person (#559)."""
    try:
        voices = await session_voices()
    except Exception:  # noqa: BLE001
        voices = {}
    taken = {str(voices.get("dj") or ""), str(voices.get("cohost") or "")}
    try:
        catalogue = set(await voice_allowlist())
    except Exception:  # noqa: BLE001
        catalogue = None
    try:
        ready = await voicepolicy_clone_engine_up()             # #1021
    except Exception:  # noqa: BLE001
        ready = False
    # A caller must NEVER sound like the DJ or the co-host (#559), so a held
    # voice that has since become a booth voice is dropped like a dead one.
    if held and held not in taken:
        if VOICE_ID_SHAPE.match(held):
            try:
                if ready and voice_ref_path(held):
                    return held         # the clone is still up and on disk
            except Exception:  # noqa: BLE001
                pass
        elif catalogue is None or held in catalogue:
            return held                 # an installed Piper voice
    try:
        clones = caller_clone_pool() if ready else []
    except Exception:  # noqa: BLE001
        clones = []
    try:
        return caller_voice_for(name or "someone", taken, catalogue,
                                clones=clones) or ""
    except Exception:  # noqa: BLE001
        return ""


async def call_line_caller() -> tuple[str, str, dict[str, Any]]:
    """#913: the third person on the request line — name, voice, phone rack.

    The same draw dj_call_generated makes, in the compact form
    dj_call_scripted uses: a name out of the book that is not a regular's
    and has not been spent tonight, a voice that is never one of the pair's,
    and the mangle that makes it sound like a telephone.

    dj_caller had none of this. It asked the model to "give them a name"
    inside the prose and then handed dj_banter no caller at all, which is
    the whole of #913 — see the note at the top of this change."""
    try:
        caller = conjure_caller()
    except Exception:  # noqa: BLE001
        caller = {}
    name = str((caller or {}).get("name") or "").strip()
    if not name:
        # The book can never be allowed to stop the phone ringing.
        try:
            name = random.choice(caller_names())
        except Exception:  # noqa: BLE001
            name = "Marlon"
    voice = await caller_line_voice(name)
    fx: dict[str, Any] = {}
    try:
        mangle = caller_mangle({**(caller or {}), "name": name})
        fx = {"vocode": mangle["character"], "pitch": mangle["pitch"]}
        for _k, _fk in (("reverb", "room"), ("delay", "delay"),
                        ("echo", "echo")):
            if mangle.get(_k) is not None:  # #617 the sculpted rack, on air
                fx[_fk] = mangle[_k]
    except Exception:  # noqa: BLE001
        fx = {}
    # #751: remember the name that will actually be SPOKEN, so the book does
    # not hand the same stranger out twice in one night.
    try:
        name_used(name)
    except Exception:  # noqa: BLE001
        pass
    return name, voice, fx


async def call_plot_clause(topic: str = "") -> tuple[str, dict[str, Any]]:
    """#913: the random plot out of the speakbox the caller rings IN with.

    "This is supposed to be a phone call where the customer calls in with a
    random plot from the speaker box and they basically are having
    discussion banter with the hosts."

    dj_banter draws its own box seed only when there is NOBODY on the line
    (`if not caller_name and not seed and random.random() < box_rate_now(
    dj["speakbox_rate"])`), because a call is supposed to arrive with a
    subject of its own. On this road it never did — which is why the banked
    "calls" were full of raw speakbox material with no caller to have
    brought it. Giving the road a caller would, on its own, have taken the
    speakbox AWAY from calls; so the swath is drawn here instead and handed
    to the caller as the thing they called about, exactly as caller_topic()
    does it for the generated road.

    The slider still governs, and box_rate_now (#895) still lifts it as the
    queue deepens: at zero there is no plot and the call is an ordinary
    request-line call, which is what that dial is for. Returned with the
    swath itself so the caller retires it only once it has AIRED."""
    _flow_trace = "caller-source:" + uuid.uuid4().hex[:20]
    _flow_start = station_flow_event(
        "speakerbox", "start", "Selecting the caller's original Speakerbox subject",
        trace_id=_flow_trace,
        details={"topic": str(topic or ""), "selection": "semantic",
                 "requires_topic_overlap": True, "maximum_draws": 3})

    def source_note(status: str, summary: str, details: Any = None) -> dict[str, Any]:
        return station_flow_event(
            "speakerbox", status, summary, trace_id=_flow_trace,
            parent_id=(_flow_start or {}).get("id"), details=details)

    try:
        if float(dj_settings().get("speakbox_rate") or 0) <= 0:
            source_note("held", "Caller Speakerbox subject selection is disabled by its dial")
            return "", {}
    except Exception:  # noqa: BLE001
        pass
    try:
        # A theme-aware semantic draw gives the caller rhetoric that can
        # actually support tonight's subject. There is deliberately no blind
        # random fallback on a call: a vivid unrelated passage is not texture,
        # it is the conversation abandoning its database theme.
        reserved_sources = {
            str((((row or {}).get("entry") or {}).get("call") or {})
                .get("source") or "")
            for row in list(_SHELF.get("caller") or [])
        }
        reserved_sources.discard("")
        # #1141: THE DRAW IS VALIDATED WITH THE GATE'S OWN PREDICATE.
        # Selection avoided only the FILES of rows on the caller shelf,
        # while the final call contract refuses on TEXT against the
        # shelf AND the last 240 logged calls - so a swath matching an
        # already-aired call passed selection here and guaranteed a
        # refusal at the END of a 47-273 second attempt. Measured live
        # during a banking pause: six finished caller rounds refused in
        # forty minutes, five of them for this one fault, zero banked -
        # and the near-argmax semantic draw re-picked the same doomed
        # swath every time, because a swath only retires when it AIRS
        # and a paused station airs nothing. Three draws, each adding
        # the colliding source to the avoid set; if they all collide, a
        # call with no plot beats a doomed call.
        swath: dict[str, Any] = {}
        _avoid = set(reserved_sources)
        for _draw in range(3):
            _got = (await speakbox_semantic_seed(
                        str(topic or "caller story grievance evidence"),
                        who="caller", require_overlap=True,
                        avoid_files=_avoid) or {})
            _t = str((_got or {}).get("text") or "").strip()
            if not _t:
                source_note("held", "The semantic subject draw returned no usable passage",
                            {"draw": _draw + 1, "topic": str(topic or "")})
                return "", {}
            _novelty = call_speakerbox_novelty(_t)
            if _novelty.get("ok", True):
                swath = _got
                break
            _file = str((_got or {}).get("file") or "")
            source_note("held", "The caller subject collided with an existing call; redraw requested",
                        {"draw": _draw + 1, "source": _file,
                         "passage": _t, "novelty": _novelty})
            pipeline_log("call", "the drawn swath already belongs to a "
                         "logged call - redrawing before a word is "
                         "written (#1141)",
                         extra=_t[:160])
            if not _file:
                return "", {}
            _avoid.add(_file)
        if not swath:
            source_note("held", "No caller subject passed the novelty checks",
                        {"draws": 3, "reserved_source_count": len(reserved_sources)})
            return "", {}
    except Exception as exc:  # noqa: BLE001
        source_note("error", "Caller subject retrieval failed",
                    {"error_type": type(exc).__name__})
        return "", {}
    text = str((swath or {}).get("text") or "").strip()
    if not text:
        source_note("held", "The selected caller subject had no text")
        return "", {}
    _flow_chosen = source_note(
        "ok", "A novel Speakerbox passage was selected for the caller's original subject",
        {"source": str(swath.get("file") or ""), "passage": text,
         "topic_relevance": dict(swath.get("topic_relevance") or {}),
         "draw": _draw + 1})
    swath = dict(swath)
    swath["_flow_trace"] = _flow_trace
    swath["_flow_event_id"] = (_flow_chosen or {}).get("id")
    return (
        "\n\nTHE PLOT THEY HAVE RUNG IN WITH — this is the CALLER's "
        "material, not the hosts'. C has read it, heard it, or half "
        "remembers it, and they have brought it to the station as the very "
        "thing they called about: they quote a phrase of it back, mangle "
        "another, build their whole argument on top of it, wave it as "
        "evidence, and they will not be talked out of it. The hosts have "
        "NOT read it — they react to what C actually says, take it apart, "
        "argue with it, and get dragged into it. Never call it a quotation "
        "and never say where it came from:\n" + text + "\n", swath or {})


# #960: a spoken turn on this station measures about this long. Drawn
# from the same 14 characters a second the say-budget works in, against
# the "four to seven sentences, 60 to 100 words" every turn is briefed
# with — call it five hundred characters, so about thirty-five seconds,
# and the ring, the answer and the hang-up on top of that.
CALL_TURN_SECONDS = 35.0
CALL_TOP_AND_TAIL = 25.0
CALL_TURNS_MIN = 6
CALL_TURNS_MAX = 12
# #961: ...and the floor for a call that is filling the TAIL of a segment
# rather than the whole of it. Four turns is a ring, what they want, one
# dig at it and a goodbye - a short call, which is a real thing, and the
# alternative in that slot is silence.
CALL_TURNS_SHORT = 4
# #1018: what one turn of tinting costs on this box, measured - three to
# five seconds for a short line, and the deadline is built from it.
TINT_TURN_SECONDS = 6.0
# Below this much room left, a call is written as a short one.
CALL_SEGMENT_WHOLE = 150.0
# #961: the turn counts recent calls were actually written to, kept
# beside the ledger's measured airtime for the same rounds so the two can
# be divided. Short, because the engine's speed drifts.
_CALL_TURNS_WRITTEN: list[int] = []


def call_turn_seconds() -> float:
    """#961: how long one turn of a phone call ACTUALLY runs on this box.

    #960 derived 35s from a character count - "four to seven sentences,
    60 to 100 words... call it five hundred characters". Nothing ever
    checked that against the station, and the station disagrees: the task
    ledger measures a whole prepared phone call at about 96 SECONDS of
    air, and it is written to six turns. That is about 12s a turn, not 35.

    The consequence was the operator's complaint word for word. A
    four-minute Phone call entry asked call_turns_for_slot how long a
    call could be; it answered six turns "because that fills 240s"; six
    turns ran a minute and a half; and the remaining two and a half
    minutes of a PHONE CALL SEGMENT had no phone call in it. "I didn't
    hear enough phone calls happening in the segment."

    task_gain is the ledger's mean airtime over recent calls and
    _CALL_TURNS_WRITTEN the mean turn count of the same rounds, so their
    ratio is what a turn buys. Clamped to no LONGER than the #960
    estimate: erring long writes shorter calls, which is the failure we
    are fixing, and erring short only writes more turns than needed,
    which the segment can absorb."""
    try:
        made = float(task_gain("caller") or 0)
        turns = [t for t in _CALL_TURNS_WRITTEN if t > 0]
        if made > 0 and turns:
            per = ((made - CALL_TOP_AND_TAIL)
                   / max(1.0, sum(turns) / len(turns)))
            if 3.0 <= per <= CALL_TURN_SECONDS:
                return per
    except Exception:  # noqa: BLE001
        pass
    return CALL_TURN_SECONDS


def sched_entry_left() -> float:
    """#961: seconds still owed to the entry that is on the air.

    Read off the same saved position schedule_take() advances, so it
    cannot disagree with the clock the show is running on. Zero when no
    sheet is running, which is what makes every caller of this fall back
    to its old behaviour."""
    try:
        pos = _RADIO.get("sched_pos") or {}
        slot = _RADIO.get("sched_slot") or {}
        started = float(pos.get("started") or 0)
        if not started or not slot:
            return 0.0
        owns = max(0.25, float(slot.get("minutes") or 0)) * 60.0
        if radio_paused():
            return max(0.0, owns - max(0.0, float(
                _RADIO.get("paused_sched_elapsed") or 0)))
        return max(0.0, started + owns - time.time())
    except Exception:  # noqa: BLE001
        return 0.0


def call_turns_for_slot() -> int:
    """#960: how many turns a call may be written to, so that it LANDS
    inside the entry it is going to air in.

    #961: and so that the SECOND and THIRD call of a phone-call segment
    are possible at all. "For the sections where they're taking phone
    calls, I want them taking phone calls for the entire segment. So it's
    back to back calls."

    Two things stopped that. The turn was believed to run 35s when it
    runs about 12 (see call_turn_seconds), so one call was written to
    fill four minutes and filled ninety seconds of it. And the room a
    call was measured against was always the WHOLE entry, so a call
    starting with ninety seconds left on the clock was still commissioned
    at full length and then beheaded by the segment reaper mid-sentence.

    Now: if a phone-call entry is already on the air, the call is written
    to what is LEFT of it, with a shorter floor - so calls chain, and the
    last one in a segment is a short one that lands rather than a long one
    that is cut off."""
    try:
        owns = 0.0
        # Already inside a phone-call segment: fill what is left of it.
        try:
            _slot = _RADIO.get("sched_slot") or {}
            if (str(SCHED_PREP_KIND.get(str(_slot.get("kind") or "")) or "")
                    == "caller"):
                owns = sched_entry_left()
        except Exception:  # noqa: BLE001
            owns = 0.0
        if owns <= 0:
            for ent in coord_upcoming(1800.0):
                if str(ent.get("road") or "") == "caller":
                    owns = float(ent.get("owns_seconds") or 0)
                    break
        if owns <= 0:
            got = random.randint(8, CALL_TURNS_MAX)
            _CALL_TURNS_WRITTEN.append(got)
            del _CALL_TURNS_WRITTEN[:-12]
            return got
        fits = int((owns - CALL_TOP_AND_TAIL) / max(1.0, call_turn_seconds()))
        floor = (CALL_TURNS_MIN if owns >= CALL_SEGMENT_WHOLE
                 else CALL_TURNS_SHORT)
        got = max(floor, min(CALL_TURNS_MAX, fits))
        _CALL_TURNS_WRITTEN.append(got)
        del _CALL_TURNS_WRITTEN[:-12]
        return got
    except Exception:  # noqa: BLE001
        return random.randint(8, CALL_TURNS_MAX)


async def dj_caller(track: dict[str, Any] | None = None,
                    bank_to: list[dict[str, Any]] | None = None,
                    case_id: str = "",
                    heat: int | None = None,
                    shelf_only: bool = False,
                    fresh_only: bool = False
                    ) -> list[str]:
    """A call gets through on the request line.

    #1033/#1039: the order of the roads is now: the unaired bank, then
    (on air, not banking) a storyline whose caller is due to ring back,
    then a shelf row inside its re-air window, then a finished recording
    re-aired as one clip, and only then a live write. `fresh_only`
    stops shelf_take at the unaired queue, which is how the phone clock
    lets a due story ring between the bank and a repeat.

    What the caller wants is one of his own past requests, read back to him by
    a stranger — the joke only lands because it is really his. They take the
    call, react, and cut to the record (#179)."""
    # #842: a call WRITTEN AND VOICED during an earlier record — script,
    # ending and every line's audio already made — goes straight to air.
    # `bank_to` is the preparer's side of the same door: it asks this
    # function to WRITE one and is handed the round back rather than it
    # airing. Nothing prepared means the live road below runs unchanged.
    if bank_to is None:
        try:
            _prep_call = shelf_take("caller", fresh_only=fresh_only)
        except Exception:  # noqa: BLE001
            _prep_call = None
        if _prep_call:
            _prep_entry = _prep_call.get("entry") or {}
            _prep_began = time.time()
            # #1033: shelf_take stamped the airing before handing it over,
            # so a second airing reads 2 here - this call is a REPEAT.
            _prep_again = int(_prep_call.get("aired") or 0) > 1
            # #913: the same card the generated road posts. A prepared call
            # used to reach the air with nobody named anywhere — not in the
            # booth, not in the script, not in the audio — which is how a
            # phone call with no caller in it stayed invisible in the log.
            try:
                _prep_who = str(_prep_entry.get("caller_name") or "")
                if _prep_who:
                    _prep_meta = dict(_prep_entry.get("call") or {})
                    # #1033: the voice on the ledger, and the repeat flag
                    # so the paper and the air log know it went out again.
                    _prep_meta["voice"] = str(
                        _prep_entry.get("caller_voice") or "")
                    if _prep_again:
                        _prep_meta["repeat"] = True
                    call_line_take(_prep_who, _prep_meta)
                    _RADIO["chat"].append(
                        {"ts": int(time.time()), "who": "host",
                         "kind": "call", "round": "caller",
                         "repeat": bool(_prep_again),
                         "text": f"On {call_line_say(call_line_no())}: "
                                 f"{_prep_who}"
                                 + (" - back on the line from earlier "
                                    "tonight (a repeat)" if _prep_again
                                    else "")})
                    del _RADIO["chat"][:-240]
                    pipeline_log("call", f"{_prep_who} on the request line — "
                                 + ("a call that went out earlier tonight, "
                                    "going out again (#1033)" if _prep_again
                                    else "a call recorded earlier, the "
                                    "caller's own turns rendered live "
                                    "(#871/#913)"))
            except Exception:  # noqa: BLE001
                pass
            try:
                _prep_said = await _banter_air(_prep_entry, track)
            except Exception:  # noqa: BLE001
                _prep_said = []
            if _prep_said:
                # The ledger is told the truth about a call that WAS
                # written earlier: the ending it was steered towards
                # travelled with the round (#691).
                try:
                    call_ended(str(_prep_entry.get("prep_name")
                                   or "the caller on the request line"),
                               call_line_say(call_line_no()), _prep_began,
                               _prep_entry.get("prep_rule") or {},
                               len(_prep_said))
                except Exception:  # noqa: BLE001
                    pass
                # #854: the case this script was WRITTEN about is
                # credited now, as it airs, not when it was written — the
                # id rode the round through the reserve and the pantry
                # exactly the way the ending rule does.
                try:
                    case_aired(str(_prep_entry.get("prep_case") or ""))
                except Exception:  # noqa: BLE001
                    pass
                quota_stamp("caller")      # #839: the hour counts it
                return _prep_said
    if shelf_only:
        return []                       # #1155: the phone clock wants the bank only
    if bank_to is None:
        # #1039: A DUE STORY OUTRANKS A STRANGER. Its caller rings back
        # through the generated road (the only one that takes a named
        # caller); a busy line defers and the story stays due.
        _due_story = story_due()
        if _due_story:
            _made = await story_ring(_due_story)
            if (_made or {}).get("lines"):
                return list(_made.get("lines") or [])
        # #1033: A RECORDING FROM EARLIER TONIGHT BEFORE A LIVE WRITE.
        # Nothing unaired was ready and no shelf row is in its window;
        # a finished call's mp3 airs as one clip, if one is 6-10h old.
        try:
            _again = await call_rerun_take(track)
        except Exception:  # noqa: BLE001
            _again = []
        if _again:
            return _again
    hot = booth_hot()
    # When the building is genuinely cooking, some callers ring in about
    # THAT instead, and they compete at it (#644).
    # #775: ...unless the operator has named a subject. This road never
    # consulted the theme at all, and it rings off the TRACK counter
    # (caller_every) while the theme-aware road rings off callin_per_hour -
    # so the road that could not hear the theme was ringing more often than
    # the road that could.
    _themed = active_theme()
    heat_call = hot >= 62 and random.random() < 0.45 and not _themed
    wants = [] if heat_call else [
        line.lstrip("- ").strip()
        for line in banter_material().splitlines()
        if len(line.strip()) > 6
    ]
    if not heat_call and not wants and not _themed:
        return []                      # nothing of his to call in about yet
    # #854: the case, drawn only on the road that can use it — the heat
    # road below is already about a subject of its own and a second one
    # would just be two calls talking over each other. Drawn BEFORE the
    # ending so a giveaway case can steer the shelf towards an outcome
    # that is able to honour it.
    _case = {} if heat_call else case_for_call(case_id, heat)
    # #691: the request line ends its calls off the same shelf as every
    # other road, so the rules you write govern ALL the calls and not just
    # the long generated ones. Drawn only once the call is certain to
    # happen — a pick bumps the rule's tally, and a call that never rang
    # must not count toward it.
    rule = hangup_pick(success_rate=(100 if case_is_prize(_case) else None))
    tail = (f" By the end of the call, {rule['text']}."
            if rule.get("text") else "")
    started = time.time()
    line_say = call_line_say(call_line_no())
    # #913: DRAW THE PERSON ON THE LINE, before a word is written.
    #
    # This road writes every scheduled phone call the station banks, and it
    # called dj_banter with no caller at all. dj_banter gates the whole call
    # apparatus on caller_name — the "THIS IS A COMPLETE PHONE CALL" flow,
    # the eleven-line floor, the phone rack, the ring the burst splices in,
    # and above all the FORMAT line, which only names the 'C: ...' marker
    # when there is a caller to name it for. With it empty the model was
    # told in as many words that this round has two speakers, and it wrote
    # two. banter_turns then found no C turns, _round_chunks had none to
    # leave to the live road, and the call aired as two hosts talking ABOUT
    # a caller who was never written. See the note at the top of #913.
    _cname, _cvoice, _cfx = await call_line_caller()
    _call_meta = {
        "mode": "scheduled",
        "voice": str(_cvoice or ""),           # #1033/#1039: on the ledger
        "line": line_say,
        "topic": str((_themed or {}).get("text")
                     or ("the heat in the station" if heat_call else
                         (wants[0] if wants else "the request line")))[:700],
        "theme": str((_themed or {}).get("name") or ""),
        "theme_text": str((_themed or {}).get("text") or "")[:700],
        "case_id": str(_case.get("id") or ""),
        "case": str(_case.get("title") or ""),
    }
    if bank_to is None and _cname:
        # #673/#703: the booth says who is on which line. The banked road
        # posts nothing — nothing is airing yet; its card goes up when the
        # shelf row is taken, above.
        try:
            call_line_take(_cname, _call_meta)    # one line, one caller
            _RADIO["chat"].append({"ts": int(time.time()), "who": "host",
                                   "kind": "call",
                                   "text": f"On {line_say}: {_cname}"})
            del _RADIO["chat"][:-240]
            pipeline_log("call", f"{_cname} on {line_say} — the request line")
        except Exception:  # noqa: BLE001
            pass
    if heat_call:
        heat_lines = await dj_banter(track, lines=4,
                                     bank=bank_to is not None,
                                     bank_to=bank_to,
                                     # #913: the same one-word omission that
                                     # emptied the request line emptied this
                                     # one. dj_banter lifts a call to its
                                     # eleven-line floor itself, so the 4
                                     # above stays as written.
                                     caller_name=_cname,
                                     caller_voice=_cvoice, caller_fx=_cfx,
                                     render_stream=bool(
                                         dj_settings().get(
                                             "call_stream", True)),
                                     call_meta=_call_meta,
                                     angle=(
            f"{_cname} has got through on {line_say} and is calling about "
            "the HEAT. "
            f"It is {hot:.0f} degrees Celsius, {hot * 9 / 5 + 32:.0f} "
            "Fahrenheit, in the building. It OPENS with the phone RINGING, "
            f"a host hearing it out loud and naming the line — {line_say} — "
            f"then answering it; and {_cname}'s very first line is an "
            f"introduction with the word \"{_cname}\" in it. They "
            "do not state the temperature — they ESCALATE, in the old "
            "call-in tradition: \"it's so hot that…\" and then something "
            "ruinous and specific from their own house. Invent FRESH ones in "
            "this spirit, and top them; do not reuse these verbatim: "
            + heat_joke_bank() + ". The hosts try to beat the caller with "
            "their own, one of them brings it back to their own melting "
            "Pine Box, and it becomes a competition nobody wins. Then cut "
            "back to the record." + tail
            # #913: the marker the model is never shown is the marker it
            # never writes, and a call with no C turns in it is two hosts
            # talking to themselves.
            + f" Format the caller's lines as 'C: ...' — C is {_cname}. "
            f"{_cname} gets real turns of their own and the hosts answer "
            "THEM, never each other about them."))
        if bank_to is not None:
            # Banked, not aired: nothing ended, so nothing is written to
            # the ledger. The outcome it was written towards rides WITH
            # the round so the ledger can be told the truth when it goes.
            if bank_to:
                bank_to[-1]["prep_rule"] = dict(rule or {})
                # #913: the ledger names the person who rang, the way
                # dj_call_generated's call_ended does — and dj_caller reads
                # this back out of the entry when the shelf row airs.
                bank_to[-1]["prep_name"] = (_cname
                                            or "the caller about the heat")
            return []
        call_ended(_cname or "the caller about the heat", line_say, started,
                   rule, len(heat_lines or []))
        if heat_lines:
            # #839: only a call that produced lines counts toward the
            # hour. A round that came back empty is precisely what the
            # old modulo miscounted as "done" and then skipped.
            quota_stamp("caller")
        return heat_lines
    want = (random.choice(wants)[:160] if wants else
            str((_themed or {}).get("text") or "the active subject")[:160])
    # #1157: THE CALLER OUT OF THE CURRENT ACT. While a storyline owns
    # the air, a share of the calls are ordinary people inside it - the
    # premise, the topic and the reason for ringing all come out of the
    # act that is live right now, and the request-line framing steps
    # aside for them. The rest of the phone is untouched.
    # #1157: a call being BANKED asks for a floor of story left first,
    # the way the banked record link does (#855) - it will not air for a
    # while, and a caller out of act two landing after the ending is a
    # stale bulletin with a voice on it.
    _pline = plotline_call_draw(
        PLOT_BANK_FLOOR if bank_to is not None else 0.0)
    _pline_bit = ""
    _want_say = (f"What got {_cname} on the air is one of the listener's "
                 "own past requests, which they want read back to them: "
                 f"\"{want}\".")
    if _pline:
        _pline_want = plotline_call_want(_pline)
        if _pline_want:
            want = _pline_want
            _want_say = plotline_call_reason(_cname, _pline)
            _pline_bit = plotline_caller_angle(_pline)
            _call_meta["topic"] = str(want)[:700]
            _call_meta["plot"] = plotline_meta(_pline)
            if bank_to is None:
                # call_line_take COPIED the meta, so the live call is
                # told separately (the same door #913 uses below).
                call_line_context(plot=_call_meta["plot"],
                                  topic=_call_meta["topic"])
        else:
            _pline = {}
    # #913: the random plot out of the speakbox that the caller rings IN
    # with. dj_banter only draws its own box seed when there is nobody on
    # the line, so now that there is somebody the swath is drawn here and
    # given to THEM — see call_plot_clause.
    _plot, _swath = await call_plot_clause(
        str((_themed or {}).get("text") or want))
    # #1033: two fresh random chunks beside the semantic seed, screened
    # against every logged and shelved call, carried on the meta.
    _pivot_trace = str((_swath or {}).get("_flow_trace") or
                       "caller-pivots:" + uuid.uuid4().hex[:20])
    _pivot_start = station_flow_event(
        "pivots", "start", "Drawing random Speakerbox scraps for the caller's mid-call pivots",
        trace_id=_pivot_trace, from_node="speakerbox",
        parent_id=(_swath or {}).get("_flow_event_id"),
        details={"caller": _cname, "requested_chunks": 2,
                 "original_topic": str(want), "prepared_call": bank_to is not None})
    try:
        _seed_bit, _seed_extra = await story_call_seed_clause(2)
    except Exception as exc:  # noqa: BLE001
        station_flow_event(
            "pivots", "error", "The random caller-pivot draw failed",
            trace_id=_pivot_trace, parent_id=(_pivot_start or {}).get("id"),
            details={"error_type": type(exc).__name__, "caller": _cname})
        _seed_bit, _seed_extra = "", []
    # #1066: reworked into the situation and the story before the writer
    # sees them; the clause quotes them, so it is retold with the new words.
    if _seed_extra and ((_themed or {}).get("text") or _pline):
        try:
            _story = plotline_caller_angle(_pline) if _pline else ""
        except Exception:  # noqa: BLE001
            _story = ""
        _adjusted = await call_pivots_contextualize(
            _seed_extra, str((_themed or {}).get("text") or ""), _story)
        if _adjusted and _adjusted != _seed_extra:
            for _o, _a in zip(_seed_extra, _adjusted):
                _seed_bit = _seed_bit.replace(f'"{_o}"', f'"{_a}"')
            _seed_extra = list(_adjusted)
    station_flow_event(
        "pivots", "ok" if _seed_extra else "held",
        "Selected caller follow-up material" if _seed_extra else "No random caller follow-up material was selected",
        trace_id=_pivot_trace, parent_id=(_pivot_start or {}).get("id"),
        details={"caller": _cname, "requested_chunks": 2,
                 "selected_count": len(_seed_extra), "chunks": list(_seed_extra),
                 "contract": "caller introduces scraps; hosts develop the new topic"})
    if _seed_extra:
        _call_meta["speakerbox_extra"] = list(_seed_extra)
        # The quality gate follows one randomly drawn scrap from C's mouth
        # into the hosts' response.  Keeping extras only as provenance made
        # the former gate say `required=False`, so a repair could discard
        # every scrap and still be accepted (measured on the live shelf).
        # Bind the complete two-scrap pivot to the contract.  Keeping only
        # the first scrap made the deterministic recovery mostly identical
        # to every earlier recovery after tint, so novelty rejected it and
        # an empty caller shelf could never refill.  Both were already in the
        # writing prompt; now both define what the caller must introduce.
        _call_meta["speakerbox_text"] = " ".join(
            str(x) for x in _seed_extra if str(x).strip())[:1200]
        _call_meta["speakerbox_source"] = "random Speakerbox call pivot"
        if bank_to is None:
            call_line_context(speakerbox_extra=list(_seed_extra),
                              speakerbox_text=_call_meta["speakerbox_text"],
                              speakerbox_source=_call_meta[
                                  "speakerbox_source"])
    if _swath:
        _call_meta["source"] = str(_swath.get("file") or "")
        # This is the semantic source for the call's original subject.  The
        # random mid-call pivot above remains the primary contract evidence.
        _call_meta["semantic_speakerbox_text"] = str(
            _swath.get("text") or "")[:1200]
        if not _call_meta.get("speakerbox_text"):
            _call_meta["speakerbox_text"] = _call_meta[
                "semantic_speakerbox_text"]
        _call_meta["speakerbox_relevance"] = dict(
            _swath.get("topic_relevance") or {})
        if bank_to is None:
            call_line_context(
                source=_call_meta["source"],
                speakerbox_text=_call_meta["speakerbox_text"],
                semantic_speakerbox_text=_call_meta[
                    "semantic_speakerbox_text"],
                speakerbox_relevance=_call_meta["speakerbox_relevance"])
    # #879: EIGHT to TWELVE turns, not four — a call should be a
    # conversation with a shape, and the outcome is drawn FIRST so the
    # exchange has somewhere to arrive rather than simply stopping.
    #
    # #960: ...AGAINST THE SLOT IT HAS TO FILL. This number was drawn with
    # no reference at all to the entry the call would air in. The
    # canonical hour gives a Call four minutes; dj_banter lifts any call
    # to an eleven-line floor and a BANKED one to fifteen or sixteen, and
    # every turn is briefed as "a developed four-to-seven-sentence
    # thought, usually 60 to 100 words". That commissions five to ten
    # minutes of speech for a four-minute entry — which is the
    # "311s banked of 240s this entry owns" the operator photographed,
    # and then the whole thing is beheaded by the five-minute segment
    # reaper mid-sentence with the hang-up never reached.
    #
    # So the slot decides. call_turns_for_slot measures the entry's own
    # minutes against what a turn actually runs on this box, and a call
    # is written to LAND inside its entry rather than be cut out of it.
    _turns = call_turns_for_slot()
    _disp = await caller_disposition_clause(theme_air_clause(_themed))
    lines = await dj_banter(track, lines=_turns, also_name=want,
                            bank=bank_to is not None, bank_to=bank_to,
                            # #913: THE PERSON ON THE OTHER END. Everything
                            # that makes dj_banter write a call instead of a
                            # booth two-hander hangs off caller_name —
                            # including the format line that names the
                            # 'C: ...' marker at all. Passing none is why
                            # the writer was asked for a two-hander and
                            # gave us one, every single time.
                            caller_name=_cname, caller_voice=_cvoice,
                            caller_fx=_cfx,
                            # A call airs as one coalesced stream, which is
                            # what splices the ring in front of it (#535).
                            render_stream=bool(
                                dj_settings().get("call_stream", True)),
                            call_meta=_call_meta,
                            angle=(
        f"The request line rings and {_cname} is on {line_say}. "
        "It OPENS with the phone RINGING and one of the hosts hearing it out "
        f"loud and naming the line — {line_say} — then answering it. "
        f"{_cname}'s VERY FIRST line is an INTRODUCTION and nothing else: "
        f"the word \"{_cname}\" has to be in it, along with a word about "
        "who they are or where they are ringing from, BEFORE they get "
        "anywhere near what they rang about. A host then greets them BY "
        f"NAME. "
        + _want_say                                                # #1157
        + _pline_bit                                               # #1157
        + _plot
        + _seed_bit                                                # #1033
        + _disp
        # #854: the case supplies the SUBJECT, the disposition above
        # supplies the TEMPER, and the rule below supplies the ENDING. On
        # THIS road the request is how they got on air and the case is what
        # the call turns out to be about, so the joke this road exists for
        # is not trampled by it.
        + case_clause(_case, "request")
        # #873: a call being QUEUED pushes further than the ones already
        # waiting in front of it. Only on the prepared road — a live call
        # has no queue behind it and no cover to spend.
        + (call_escalation_clause(len(_SHELF.get("caller") or []))
           if bank_to is not None else "")
        + " The hosts take the call with unmistakable "
        f"{random.choice(CALLER_MOODS)}."
        # #913: "I did not hear the caller come through on this." The old
        # brief here was "between the two of you RELAY what they are asking
        # for" — an instruction to DISCUSS a caller in the third person,
        # and that is exactly what aired: "So, this caller, Toothpick
        # Eddie, is calling regarding the warmth emanating..." with nobody
        # on the line to answer.
        + " This is a CONVERSATION, not a report. While the caller is on "
        "the line the hosts NEVER describe them, or what they want, to "
        f"each other in the third person — they talk TO {_cname}, and "
        f"{_cname} answers in their own words, pushes back when they are "
        "dismissed, and holds their ground. About HALF the turns in this "
        f"call are {_cname}'s, and every one of them is a complete thought "
        "of their own, not a prompt for the hosts."
        + f" Let it RUN — {_turns} turns of real back and forth, the "
        "caller pushing and the hosts answering, before anybody thinks "
        "about the record."
        # #879: the ending is chosen from the station's own outcome
        # shelf and STEERED towards, not merely stamped on afterwards.
        + " The call must END this way, arrived at honestly over the "
        f"last two or three turns: {str(rule.get('text') or '')}. "
        f"The PENULTIMATE turn is {_cname} explicitly landing what changed, "
        "what they decided, or why they are ready to leave it there. The "
        "FINAL turn is one host answering that resolution and clearly "
        "thanking them or saying goodbye. No second host speech comes "
        "between the caller's resolution and that sign-off. Then cut back "
        "to the record." + tail
        # #913: the marker the model is never shown is the marker it never
        # writes. Said last, so it is the instruction nearest the answer.
        + f" Format the caller's lines as 'C: ...' — C is {_cname}, who "
        "speaks in full sentences and gives as good as they get."
    ))
    if bank_to is not None:
        if bank_to:
            bank_to[-1]["prep_rule"] = dict(rule or {})
            # #913: the ledger names the person who rang, and dj_caller
            # reads it back off the entry when the shelf row airs.
            bank_to[-1]["prep_name"] = (_cname
                                        or "the caller on the request line")
            # #913: the plot rides WITH the round. _banter_air retires a
            # swath only when lines built on it have actually AIRED, so a
            # call still sitting on the shelf never burns its own material.
            if _swath:
                try:
                    bank_to[-1].setdefault("swaths", []).append(_swath)
                except Exception:  # noqa: BLE001
                    pass
            # #854: the CASE id travels with the round, exactly as the
            # ending rule does, so a call written now and aired in three
            # hours is still credited to the case it was written about.
            bank_to[-1]["prep_case"] = str(_case.get("id") or "")
        return []
    call_ended(_cname or "the caller on the request line", line_say,
               started, rule, len(lines or []))
    if lines:
        quota_stamp("caller")              # #839: the hour counts it
        case_aired(str(_case.get("id") or ""))                    # #854
        if _swath:
            speakbox_remember(_swath)      # #913: the plot rotates
    return lines


# --- Getting the box unstuck (#134) ----------------------------------------


async def pinebox_listen(prompt: str = "") -> dict[str, Any]:
    """Open the box's microphone now, wake word or not.

    start_conversation makes the satellite listen and run the pipeline just
    as if it had heard its wake word — which is the only reliable way in when
    the on-device detector will not fire."""
    # Listening is how you ASK it something, so the mic stays open with the
    # station switched off the speaker (#647) — that is the whole point of
    # turning the show off it. Only muting replies closes this.
    if not box_talk_ok(reply=True):
        raise HTTPException(
            status_code=409,
            detail="Replies are switched off, so the box has no way to "
                   "answer you. Set replies to the box or this page.")
    token, player = _ha_creds()
    if not (token and player):
        raise HTTPException(status_code=400, detail="No Home Assistant token")
    if not player.startswith("assist_satellite."):
        raise HTTPException(
            status_code=400,
            detail=f"{player} is not an assist satellite — nothing to listen with")

    # supported_features bit 2 is START_CONVERSATION. This board only sets
    # bit 1 (ANNOUNCE): it can be told to speak, never to listen.
    ANNOUNCE_ONLY = 1
    async with httpx.AsyncClient(timeout=20) as client:
        state = await client.get(
            f"{HA_URL}/api/states/{player}",
            headers={"Authorization": f"Bearer {token}"})
    features = int(((state.json() or {}).get("attributes") or {})
                   .get("supported_features") or 0)
    if not features & 2:
        raise HTTPException(
            status_code=501,
            detail=(
                "This satellite's firmware cannot be told to listen — it "
                f"reports supported_features={features} "
                f"({'announce only' if features == ANNOUNCE_ONLY else 'no start_conversation'}). "
                "Use the button on the box itself, its wake word, or the "
                "microphone in this page."),
        )

    payload: dict[str, Any] = {"entity_id": player}
    if prompt:
        payload["start_message"] = prompt

    async with httpx.AsyncClient(timeout=ANNOUNCE_TIMEOUT) as client:
        reply = await client.post(
            f"{HA_URL}/api/services/assist_satellite/start_conversation",
            headers={"Authorization": f"Bearer {token}"},
            json=payload,
        )
    if reply.status_code >= 500:
        # Same dead-socket case announce hits; rebuild and try once more.
        if await satellite_selfheal():
            async with httpx.AsyncClient(timeout=ANNOUNCE_TIMEOUT) as client:
                reply = await client.post(
                    f"{HA_URL}/api/services/assist_satellite/start_conversation",
                    headers={"Authorization": f"Bearer {token}"},
                    json=payload,
                )
    if reply.status_code >= 400:
        raise HTTPException(
            status_code=502,
            detail=f"Home Assistant refused: {reply.text[:200]}")
    return {"listening": True, "entity": player, "said": prompt}


async def pinebox_recover(restart_agent: bool = True) -> dict[str, Any]:
    """Stop everything that could be holding the satellite, then reload it.

    An assist satellite exposes no stop service, so a long or failed announce
    leaves it lit with nothing able to interrupt it. Reloading its config
    entry is the one call that reliably clears that state."""
    steps: list[str] = []

    # Recovery is transport maintenance, not a destructive reset. The show
    # and every pending dialogue clip remain on their durable shelves; the
    # old call to stop_speaking() cancelled in-flight work and contradicted
    # the station guarantee that a written line is never thrown away.
    steps.append(f"preserved {len(_BOX_HOLD)} held clip(s) and live show state")
    token, player = _ha_creds()
    if token and player:
        async with httpx.AsyncClient(timeout=20) as client:
            headers = {"Authorization": f"Bearer {token}"}
            # Find the config entry behind the entity, then reload it.
            try:
                states = await client.get(
                    f"{HA_URL}/api/states/{player}", headers=headers)
                steps.append(f"satellite was {(states.json() or {}).get('state')}")
            except Exception:
                pass
            for service, payload in (
                ("homeassistant/update_entity", {"entity_id": player}),
                ("homeassistant/reload_config_entry", {"entity_id": player}),
            ):
                try:
                    response = await client.post(
                        f"{HA_URL}/api/services/{service}",
                        headers=headers, json=payload)
                    steps.append(
                        f"{service.split('/')[-1]}: "
                        f"{'ok' if response.status_code < 400 else response.status_code}")
                except Exception as exc:
                    steps.append(f"{service}: {exc}")
    else:
        steps.append("no Home Assistant credentials — skipped the satellite")

    if restart_agent:
        steps.append("restarting spark-agent")
        fire_and_forget(_restart_self())
    return {"ok": True, "steps": steps}


async def _restart_self() -> None:
    """Exit after the response has gone out; the container policy restarts."""
    await asyncio.sleep(1.0)
    os._exit(3)



def dropped_subject(name: str, caption: str = "") -> tuple[str, str]:
    """What the DJ can honestly say about a dropped file: (subject, source).

    A generated image carries its own prompt, which is a real description. A
    file we have never seen is only a filename, and the DJ should not invent
    a scene it cannot see."""
    if caption.strip():
        return caption.strip()[:200], "you told us what it is"

    stem = Path(name).stem
    for gen in read_generations(400):
        for field in ("file", "filename"):
            if str(gen.get(field) or "") and Path(
                    str(gen[field])).stem == stem:
                subject = " ".join(str(
                    gen.get("request") or gen.get("tags") or "").split())
                if subject:
                    return subject[:200], "your own generated image"

    pretty = re.sub(r"[-_]+", " ", stem)
    pretty = re.sub(r"\b\d{6,}\b", " ", pretty)
    return " ".join(pretty.split())[:200] or "an untitled picture", "its filename"



# --- Bringing the stack back (#136) ----------------------------------------

DOCKER_SOCK = Path("/var/run/docker.sock")
STACK_SERVICES = ("wyoming-piper", "wyoming-whisper", "homeassistant")


async def _docker_restart(name: str) -> str:
    """Only possible when the socket is mounted, which it is not by default."""
    if not DOCKER_SOCK.exists():
        return "no docker socket (see the note)"
    try:
        transport = httpx.AsyncHTTPTransport(uds=str(DOCKER_SOCK))
        async with httpx.AsyncClient(transport=transport, timeout=30) as client:
            response = await client.post(
                f"http://docker/containers/{name}/restart")
            return "restarted" if response.status_code < 400 else (
                f"docker said {response.status_code}")
    except Exception as exc:
        return f"failed: {exc}"


async def stack_reconnect(restart_agent: bool = True) -> dict[str, Any]:
    """Probe everything, reload the Home Assistant side, then restart us."""
    report: dict[str, Any] = {"services": {}, "steps": []}

    # Is Piper actually answering, or only running?
    try:
        voices = await asyncio.wait_for(piper_voices(), 8)
        report["services"]["wyoming-piper"] = (
            f"ok · {len(voices)} voices" if voices else "up but silent")
    except Exception as exc:
        report["services"]["wyoming-piper"] = f"down: {exc}"

    try:
        reader, writer = await asyncio.wait_for(
            asyncio.open_connection(PIPER_HOST, 10300), 5)
        writer.close()
        report["services"]["wyoming-whisper"] = "ok"
    except Exception as exc:
        report["services"]["wyoming-whisper"] = f"down: {exc}"

    token, player = _ha_creds()
    if token:
        async with httpx.AsyncClient(timeout=20) as client:
            headers = {"Authorization": f"Bearer {token}"}
            try:
                response = await client.get(
                    f"{HA_URL}/api/config", headers=headers)
                report["services"]["home-assistant"] = (
                    "ok" if response.status_code < 400
                    else f"HTTP {response.status_code}")
            except Exception as exc:
                report["services"]["home-assistant"] = f"down: {exc}"

    # Reloading by config entry is the call that actually re-runs setup.
    link = await satellite_reconnect()
    report["satellite"] = link
    report["steps"] += link.get("reloaded", [])
    if link.get("advice"):
        report["steps"].append(link["advice"])
    else:
        report["services"]["home-assistant"] = "no token"

    for name in STACK_SERVICES:
        outcome = await _docker_restart(name)
        if outcome != "no docker socket (see the note)":
            report["steps"].append(f"{name}: {outcome}")
    if not DOCKER_SOCK.exists():
        report["note"] = (
            "Container restarts are off: the agent has no docker socket, and "
            "granting one lets anyone who reaches this API control the host. "
            "To allow it anyway, add '- /var/run/docker.sock:/var/run/"
            "docker.sock' to spark-agent's volumes and recreate it."
        )

    try:
        dj_stop()
        await stop_speaking()
        report["steps"].append("radio and queued speech stopped")
    except Exception:
        pass

    if restart_agent:
        report["steps"].append("restarting spark-agent")
        fire_and_forget(_restart_self())
    return report



# --- The satellite link ----------------------------------------------------
# Reloading by entity id does nothing useful; the config-entry endpoint is the
# one that re-runs setup. Everything here reports what is actually true rather
# than claiming success, because a satellite that is switched off stays off.

SATELLITE_HOST = os.getenv("SATELLITE_HOST", "")
SATELLITE_PORT = int(os.getenv("SATELLITE_PORT", "10700"))


async def ha_config_entries() -> list[dict[str, Any]]:
    token, _player = _ha_creds()
    if not token:
        return []
    try:
        async with httpx.AsyncClient(timeout=15) as client:
            response = await client.get(
                f"{HA_URL}/api/config/config_entries/entry",
                headers={"Authorization": f"Bearer {token}"},
            )
            response.raise_for_status()
            data = response.json()
            return data if isinstance(data, list) else []
    except Exception:
        return []


async def ha_reload_entry(entry_id: str) -> str:
    token, _player = _ha_creds()
    if not (token and entry_id):
        return "no token"
    try:
        async with httpx.AsyncClient(timeout=30) as client:
            response = await client.post(
                f"{HA_URL}/api/config/config_entries/entry/{entry_id}/reload",
                headers={"Authorization": f"Bearer {token}"},
            )
            return "reloaded" if response.status_code < 400 else (
                f"HTTP {response.status_code}")
    except Exception as exc:
        return f"failed: {exc}"


async def satellite_probe(host: str = "", port: int = 0) -> dict[str, str]:
    """WHY the satellite is or is not answering, not merely whether.

    #777: "voices arent coming out of the pine box. I had to switch back to
    the browser." Measured while that was true: the box answered ICMP and had
    a live ARP entry — it was powered and sitting on the network — while
    :10700 was closed, so nothing was listening for the show. The old
    reachable() flattened that to a bare False, the diagnosis then blamed the
    ROUTING, and the advice was to point the show at a box that could not
    receive it. That is the loop the operator was stuck in.

    A REFUSED connection is a live host with a dead service; a TIMEOUT is a
    host that is not there at all; a connection that opens and then says
    nothing is the #712 wedge. Three different faults, three different
    things to do about them, and they must not read the same."""
    host = host or SATELLITE_HOST
    if not host:
        return {"state": "unset", "detail": "no satellite address is set"}
    writer = None
    try:
        reader, writer = await asyncio.wait_for(
            asyncio.open_connection(host, port or SATELLITE_PORT), 3)
    except ConnectionRefusedError:
        return {"state": "refused",
                "detail": "the box REFUSED the connection — it is powered up "
                          "and on the network, but its satellite service is "
                          "not running"}
    except (asyncio.TimeoutError, TimeoutError):
        # A dropped SYN and an absent device look identical at this layer.
        # The neighbour table can tell them apart, and the two faults have
        # nothing to do with each other: one is a service to restart, the
        # other is a device to go and find.
        near = (await asyncio.to_thread(_arp_table)).get(host) or ""
        if near:
            return {"state": "refused",
                    "detail": f"the box is ON the network ({near}) but the "
                              f"satellite port {port or SATELLITE_PORT} did "
                              "not answer — it is powered up and its "
                              "satellite service is not listening"}
        return {"state": "timeout",
                "detail": "no answer at all, and nothing at the link layer "
                          "either — off, asleep, or on another network"}
    except OSError as exc:
        return {"state": "down", "detail": str(exc)[:120] or "no route"}
    try:
        # Wyoming framing: one JSON header per line, payload optional.
        writer.write((json.dumps({"type": "describe"}) + "\n").encode())
        await asyncio.wait_for(writer.drain(), 2)
        line = await asyncio.wait_for(reader.readline(), 4)
        if line and line.strip():
            return {"state": "ok", "detail": "answering"}
        return {"state": "wedged",
                "detail": "it took the connection and then said nothing — "
                          "wedged (#712)"}
    except Exception as exc:                                    # noqa: BLE001
        return {"state": "wedged",
                "detail": str(exc)[:120] or "no reply to describe"}
    finally:
        if writer is not None:
            try:
                writer.close()
            except Exception:  # noqa: BLE001
                pass


async def satellite_reachable(host: str = "", port: int = 0) -> bool:
    """Does the satellite actually ANSWER — not merely accept a socket?

    This used to be a bare connect-and-close, described as ground truth. It
    is not (#712): a WEDGED box still accepts the TCP connection while
    servicing no Wyoming session at all. Measured on the real device
    mid-wedge — the connection succeeded and the box returned zero bytes in
    six seconds. So every wedge reported as "reachable but stalling", which
    is exactly the branch that escalates to restarting Home Assistant, which
    severs the audio stream, which wedges the box. The false signal was the
    first link in that loop.

    Now one line over satellite_probe, so the watchdog and the diagnosis
    cannot disagree about what the box is doing."""
    return (await satellite_probe(host, port))["state"] == "ok"


async def satellite_status() -> dict[str, Any]:
    """Everything known about the link, in one place."""
    token, player = _ha_creds()
    entity_state = ""
    if token and player:
        try:
            async with httpx.AsyncClient(timeout=10) as client:
                response = await client.get(
                    f"{HA_URL}/api/states/{player}",
                    headers={"Authorization": f"Bearer {token}"})
                entity_state = (response.json() or {}).get("state", "")
        except Exception:
            entity_state = "unknown"

    # PineVoice is a direct Wyoming satellite, so a protocol response is the
    # only trustworthy proof that it can receive a clip. ESPHome Voice
    # Preview editions are different: Home Assistant owns their transport and
    # they do not expose PineVoice's :10700 Wyoming endpoint. Do not keep an
    # old PineVoice outage latched when the selected output is a healthy HA
    # satellite; its entity state is the right delivery-health signal.
    direct_wyoming = player == "assist_satellite.pinevoice"
    if not direct_wyoming:
        online = entity_state not in ("unavailable", "unknown", "")
        return {
            "entity": player,
            "entity_state": entity_state,
            "online": online,
            "entries": [],
            "broken": [],
            "host": "",
            "reachable": online,
            "transport": "home_assistant",
        }

    entries = await ha_config_entries()
    wyoming = [e for e in entries if e.get("domain") == "wyoming"]
    broken = [e for e in wyoming if e.get("state") != "loaded"]

    return {
        "entity": player,
        "entity_state": entity_state,
        "online": entity_state not in ("unavailable", "unknown", ""),
        "entries": [
            {"title": e.get("title"), "state": e.get("state"),
             "reason": e.get("reason"), "id": e.get("entry_id")}
            for e in wyoming
        ],
        "broken": [e.get("title") for e in broken],
        "host": SATELLITE_HOST,
        "reachable": await satellite_reachable() if SATELLITE_HOST else None,
        "transport": "wyoming",
    }



async def _probe(host: str, port: int, timeout: float = 0.6) -> bool:
    try:
        _reader, writer = await asyncio.wait_for(
            asyncio.open_connection(host, port), timeout)
        writer.close()
        return True
    except Exception:
        return False


def local_subnet() -> str:
    """The /24 this box lives on, taken from the address we already know."""
    host = SATELLITE_HOST or VOICE_PUBLIC_URL.split("//")[-1].split(":")[0]
    parts = host.split(".")
    if len(parts) == 4 and all(p.isdigit() for p in parts):
        return ".".join(parts[:3])
    return ""


async def satellite_discover(subnet: str = "") -> list[str]:
    """Sweep the subnet for anything answering the satellite port.
    ponytail: a bounded TCP sweep, not mDNS — avahi is not in this container
    and 254 short connects finish in a couple of seconds."""
    subnet = subnet or local_subnet()
    if not subnet:
        return []

    found: list[str] = []
    semaphore = asyncio.Semaphore(64)

    async def look(address: str) -> None:
        async with semaphore:
            if await _probe(address, SATELLITE_PORT):
                found.append(address)

    try:
        await asyncio.wait_for(asyncio.gather(*(
            look(f"{subnet}.{n}") for n in range(1, 255)
        ), return_exceptions=True), 25)
    except asyncio.TimeoutError:
        pass                    # partial results are still useful
    return sorted(found)


async def ha_add_wyoming(host: str, port: int) -> str:
    """Add a Wyoming device through the config-flow API, which is how the
    integration is normally set up."""
    token, _player = _ha_creds()
    if not token:
        return "no token"
    headers = {"Authorization": f"Bearer {token}"}
    try:
        async with httpx.AsyncClient(timeout=30) as client:
            start = await client.post(
                f"{HA_URL}/api/config/config_entries/flow",
                headers=headers,
                json={"handler": "wyoming", "show_advanced_options": False},
            )
            start.raise_for_status()
            flow = start.json() or {}
            flow_id = flow.get("flow_id")
            if not flow_id:
                return "no flow"
            step = await client.post(
                f"{HA_URL}/api/config/config_entries/flow/{flow_id}",
                headers=headers, json={"host": host, "port": port},
            )
            body = step.json() or {}
            if body.get("type") == "create_entry":
                return f"added {body.get('title') or host}"
            return f"{body.get('reason') or body.get('errors') or body.get('type')}"
    except Exception as exc:
        return f"failed: {exc}"


async def satellite_find_and_fix() -> dict[str, Any]:
    """The whole recovery: look for the box, and wire it up if it moved."""
    status = await satellite_status()
    if status["online"]:
        return {**status, "action": "already online"}

    hosts = await satellite_discover()
    known = SATELLITE_HOST
    action = ""

    if not hosts:
        action = (
            "Swept the local network and nothing is answering the satellite "
            f"port ({SATELLITE_PORT}). The Pine Box is not on this network at "
            "all — check that it powered up, that it joined the Wi-Fi, and "
            "that its satellite service is running."
        )
    else:
        moved = [h for h in hosts if h != known]
        if moved:
            # Deliberately NOT auto-added. Wyoming has no reconfigure flow, so
            # adding it again mints a new entry_id and every entity is renamed
            # (assist_satellite.pinevoice -> ..._2), which silently breaks
            # every announce call in this file. Report it; the durable fix is
            # a DHCP reservation for the box's MAC.
            action = (
                f"The Pine Box has MOVED: it is answering at {moved[0]}, but "
                f"Home Assistant is configured for {known or 'nothing'}. I "
                "have not re-added it automatically — Wyoming has no "
                "reconfigure step, so re-adding renames every entity and "
                "would break the voice calls. Give it a DHCP reservation at "
                f"{known} on the router, or call /api/satellite/repoint with "
                "confirm=true if you accept the rename."
            )
        else:
            action = (
                f"{known} answers the port but Home Assistant still reports "
                "the entity unavailable — reloading the entry."
            )
            await satellite_reconnect(watch=False)

    return {**await satellite_status(), "found": hosts, "action": action}


_SAT_RETRY: list[Any] = []


async def satellite_watch(minutes: int = 30) -> None:
    """Keep retrying so the box rejoins on its own once it is powered up
    again — nobody should have to come back and press a button.
    ponytail: two minutes between rounds, not thirty seconds. A full-subnet
    sweep is 254 sockets; doing that twice a minute is how you make the
    server look broken while looking for something that is switched off."""
    deadline = time.time() + minutes * 60
    rounds = 0
    while time.time() < deadline:
        await asyncio.sleep(120)
        rounds += 1
        status = await satellite_status()
        if status["online"]:
            return
        for entry in status["entries"]:
            if entry["state"] != "loaded":
                await ha_reload_entry(entry["id"])
        # Every third round, look for it at a new address as well. Finding
        # it is worth knowing; acting on it is not automatic (see above).
        if rounds % 3:
            continue
        try:
            hosts = await satellite_discover()
            if [h for h in hosts if h != SATELLITE_HOST]:
                return              # a human decision from here
        except Exception:
            pass


async def satellite_reconnect(watch: bool = True) -> dict[str, Any]:
    """Reload every wyoming entry that is not loaded, then tell the truth."""
    status = await satellite_status()
    reloaded: list[str] = []
    for entry in status["entries"]:
        if entry["state"] != "loaded":
            reloaded.append(
                f"{entry['title']}: {await ha_reload_entry(entry['id'])}")

    # If reloading will not do it, the box may simply have moved.
    if not status["online"]:
        try:
            moved = await satellite_find_and_fix()
            if moved.get("action"):
                reloaded.append(moved["action"])
        except Exception:
            pass

    await asyncio.sleep(3)
    after = await satellite_status()

    if not after["online"] and watch and not _SAT_RETRY:
        task = asyncio.create_task(satellite_watch())
        _SAT_RETRY.append(task)
        task.add_done_callback(lambda _t: _SAT_RETRY.clear())

    advice = ""
    if not after["online"]:
        where = SATELLITE_HOST or "its configured address"
        advice = (
            f"The satellite at {where} is not answering — Home Assistant "
            "reports 'Unable to connect'. Piper and Whisper are both fine, so "
            "this is the Pine Box device itself: check that it has power and "
            "is on the Wi-Fi. I will keep retrying for half an hour, and it "
            "will rejoin on its own once it is back."
        )

    return {**after, "reloaded": reloaded, "advice": advice,
            "retrying": bool(_SAT_RETRY)}



# --- The Pine Box troubleshooter -------------------------------------------

# No home-network identifiers baked in as defaults (audit: these rode
# along in the export kit). Set SATELLITE_MAC / SATELLITE_SSID in the
# environment for the BLE-Improv recovery helper on this box.
SATELLITE_MAC = os.getenv("SATELLITE_MAC", "")
SATELLITE_SSID = os.getenv("SATELLITE_SSID", "")
GUIDE_PDF = data_path("pinebox-recovery.pdf")


def _arp_table() -> dict[str, str]:
    """The kernel's neighbour table, read from /proc.

    #777: this used to shell out to `ip neigh`, and `ip` is not in a
    python:3.12-slim image — so the check reported "not checkable from inside
    the container" every single time and could never contribute anything. It
    was the one check that could have told the operator their box was ON the
    network with a dead service rather than off, which is the difference
    between "power-cycle it" and "go and find it". /proc/net/arp needs no
    binary and no capability."""
    out: dict[str, str] = {}
    try:
        for line in Path("/proc/net/arp").read_text().splitlines()[1:]:
            cols = line.split()
            if len(cols) >= 4 and cols[0]:
                # IP address, HW type, Flags, HW address, Mask, Device
                out[cols[0]] = f"{cols[3]} on {cols[-1]}" \
                    if cols[3] != "00:00:00:00:00:00" else ""
    except OSError:
        pass
    return out


async def _arp_state(host: str) -> str:
    """What the kernel's neighbour table thinks. An empty or absent entry
    means the device is not answering at the link layer at all."""
    seen = await asyncio.to_thread(_arp_table)
    if host in seen:
        return seen[host] or "INCOMPLETE — no reply at the link layer"
    # Not in the table is not proof of absence: entries expire when nothing
    # has spoken to the device recently. A connect attempt has just been made
    # by the caller, which is what puts one there.
    try:
        proc = await asyncio.create_subprocess_exec(
            "ip", "neigh", "show", host,
            stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.DEVNULL)
        out, _ = await asyncio.wait_for(proc.communicate(), 5)
        line = out.decode().strip()
        return line or "no entry"
    except Exception:
        return "no entry"


# #985: THE SERVICES THE PINE BOX LEANS ON, AND WHETHER THEY ARE THERE.
#
# "I just put a request through ComfyUI and it failed. Make sure the DJs
#  have the resources available to triage and resolve and auto repair any
#  issues in order to make sure that the services work for the pine box."
#
# ComfyUI had been down for some time and NOTHING in the station knew.
# Every readout the operator had — the diagnose ladder, the repair tree,
# the engine panel — is about the speaker, the voice engines and Home
# Assistant. The image side had no rung at all, so a dead ComfyUI was
# indistinguishable from a slow one, and the only symptom was a request
# quietly failing.
#
# The lifeboat already probes every peer port once and answers without
# auth, so this asks IT rather than opening eight sockets of its own.
# Falling back to a direct probe keeps it honest when the lifeboat is the
# thing that is down.
PEER_SERVICES = {
    "comfyui": ("ComfyUI (pictures)", "http://127.0.0.1:8188/system_stats"),
    "ollama": ("Ollama (the writer)", "http://127.0.0.1:11434/api/version"),
    "voice-lab": ("Voice lab", "http://127.0.0.1:8771/health"),
}
LIFEBOAT_URL = os.getenv("LIFEBOAT_URL", "http://127.0.0.1:8099")


async def peer_service_state() -> dict[str, Any]:
    """Which peer services are answering, and who can restart them."""
    out: dict[str, Any] = {"ports": {}, "restartable": [], "via": ""}
    try:
        async with httpx.AsyncClient(timeout=6.0) as client:
            got = (await client.get(f"{LIFEBOAT_URL}/status")).json()
        out["ports"] = dict(got.get("ports") or {})
        out["restartable"] = list(got.get("restartable") or [])
        out["via"] = "lifeboat"
        return out
    except Exception:  # noqa: BLE001
        pass
    # The lifeboat is the thing that is down: ask the ports directly.
    out["via"] = "direct"
    for key, (_label, url) in PEER_SERVICES.items():
        try:
            async with httpx.AsyncClient(timeout=4.0) as client:
                got = await client.get(url)
            out["ports"][key] = got.status_code < 500
        except Exception:  # noqa: BLE001
            out["ports"][key] = False
    return out


async def pinebox_diagnose() -> dict[str, Any]:
    """Work down the chain and stop at the first thing that is actually
    broken, so the advice is about that and not about everything."""
    checks: list[dict[str, str]] = []

    def add(name: str, ok: bool | None, detail: str) -> None:
        checks.append({"name": name, "ok": ok, "detail": detail})

    # The parts that are ours before the parts that are the device's.
    try:
        voices = await asyncio.wait_for(piper_voices(), 8)
        add("Speech engine (wyoming-piper)", bool(voices),
            f"{len(voices)} voices" if voices else "not answering on :10200")
    except Exception as exc:
        add("Speech engine (wyoming-piper)", False, str(exc)[:120])

    # #985: the peer services, before Home Assistant — a dead ComfyUI or
    # a dead Ollama breaks the station just as thoroughly as a dead
    # speaker, and until now neither had a rung anywhere.
    try:
        peers = await peer_service_state()
        _ports = peers.get("ports") or {}
        _down = [PEER_SERVICES.get(k, (k, ""))[0]
                 for k, alive in _ports.items()
                 if k in PEER_SERVICES and not alive]
        _fixable = [k for k in _ports
                    if k in (peers.get("restartable") or [])]
        if _down:
            add("Services the station leans on", False,
                ", ".join(_down) + " not answering"
                + (" — the lifeboat can restart "
                   + ", ".join(_fixable) if _fixable
                   else " — needs a hand on the host"))
        else:
            add("Services the station leans on", True,
                str(len([k for k, v in _ports.items() if v]))
                + " answering (" + (peers.get("via") or "?") + ")")
    except Exception as exc:  # noqa: BLE001
        add("Services the station leans on", None, str(exc)[:120])

    # #1156: the station's own pulse and the library road, before the
    # device — a loop that stalls or a share that crawls silences the
    # show on every speaker at once.
    try:
        _pr = pulse_report(600)
        add("The station's own pulse", bool(_pr.get("ok")),
            str(_pr.get("reading") or ""))
    except Exception as exc:  # noqa: BLE001
        add("The station's own pulse", None, str(exc)[:120])
    try:
        _ls = library_reading()
        _coming_id = str((_RADIO.get("coming") or {}).get("id") or "")
        _covered = bool(music_hot_file(_RADIO.get("coming") or {})
                        or (_coming_id and _coming_id in _HOT_JOBS)
                        or not _RADIO.get("on"))
        add("The music library",
            (None if _ls.get("measuring") and not _ls.get("at") else
             True if not _ls.get("slow") else None if _covered else False),
            str(_ls.get("reading") or "")
            + (" — the up-next record is already on the local shelf"
               if _ls.get("slow") and _covered else ""))
    except Exception as exc:  # noqa: BLE001
        add("The music library", None, str(exc)[:120])

    token, player = _ha_creds()
    add("Home Assistant token", bool(token),
        "configured" if token else "missing — set it in the Speak panel")

    link = await satellite_status()
    entries = {e["title"]: e for e in link["entries"]}
    entry = entries.get("PineVoice") or {}
    add("Home Assistant ↔ Pine Box", link["online"],
        f"{link['entity']} is {link['entity_state']}"
        + (f" · entry {entry.get('state')}" if entry else ""))

    # A Voice Preview Edition is an HA/ESPHome satellite, not a PineVoice
    # exposed on :10700. Its selected entity is the delivery signal; probing
    # the retired PineVoice must not turn an otherwise working route red.
    ha_satellite = link.get("transport") == "home_assistant"
    if ha_satellite:
        reachable = bool(link.get("online") and link.get("reachable"))
        probe = {
            "state": "ok" if reachable else "timeout",
            "detail": ("Home Assistant satellite transport" if reachable
                       else "selected satellite is unavailable"),
        }
        add("Selected speaker transport", reachable,
            "Home Assistant manages this ESPHome satellite")
        if not reachable:
            # #1156: WHICH kind of unavailable - the wire, with ports.
            # Never a wait here: the status endpoint polls this.
            _wd = dict(_WIRE_LAST)
            if time.time() - float(_wd.get("at") or 0) > 120:
                fire_and_forget(_wire_probe_detail(NABU_PROBE_HOST))
                if not _wd.get("at"):
                    _wd = {}
            _fw = nabu_firmware_down(_wd)
            add("The device on the wire",
                (False if _fw else None if _wd.get("state") != "alive"
                 else True),
                wire_reading(_wd) if _wd else "probing the wire now")
            probe = {"state": ("refused" if _fw else "timeout"
                               if _wd.get("state") == "dark" else "ok"
                               if _wd.get("listening") else "unset"),
                     "detail": (wire_reading(_wd) if _wd else
                                "selected satellite is unavailable")}
    else:
        probe = await satellite_probe()
        reachable = probe["state"] == "ok"
    # #784: a satellite that is BUSY SERVING Home Assistant can refuse our
    # own describe on the same port while playing the show perfectly — the
    # session belongs to HA, not to us. So a recent, full-length playout is
    # harder evidence than a probe, and it must not be shouted down. Without
    # this the #777 ladder cries "the Pine Box is not accepting audio" over a
    # box that is audibly working, which is the same fault as before wearing
    # the opposite face.
    # A stale HTTP acceptance cannot overrule a wedged satellite. Recent
    # delivery only counts when it was verified audible and the station is not
    # actively accumulating missed dialogue behind an open breaker.
    delivery_blocked = (time.time() < float(_BOX_DOWN.get("until") or 0)
                        or len(_BOX_HOLD) >= 3
                        or bool(_LAST_PLAYOUT.get("at"))
                        and not bool(_LAST_PLAYOUT.get("ok")))
    played_recently = box_recently_verified() and not delivery_blocked
    if not ha_satellite and not reachable and played_recently:
        add(f"Pine Box on the network ({SATELLITE_HOST}:{SATELLITE_PORT})",
            True, f"{probe['detail']} — but it played a clip in full "
                  f"{int(time.time() - _BOX_LAST_OK[0])}s ago, so it is "
                  "serving Home Assistant and simply will not take a second "
                  "session")
        reachable = True
    elif not ha_satellite:
        add(f"Pine Box on the network ({SATELLITE_HOST}:{SATELLITE_PORT})",
            reachable, probe["detail"])

    # `ip` is not in this image, so ARP is informational only — it must not
    # decide the diagnosis, or an unknown reads as "everything is fine".
    # #786: bound BEFORE the branch — the not-reachable verdict below reads
    # them, and an offline nabu (ha_satellite) used to hit a NameError here
    # and 500 the whole diagnosis exactly when it was needed.
    known = False
    on_lan = False
    if not ha_satellite:
        arp = await _arp_state(SATELLITE_HOST) if SATELLITE_HOST else ""
        known = arp not in ("", "unknown", "no entry")
        on_lan = (known and "FAILED" not in arp.upper()
                  and "INCOMPLETE" not in arp.upper())
        add("Answers at the link layer (ARP)", on_lan if known else None,
            arp if known else "not checkable from inside the container")

    elsewhere = []
    if not ha_satellite and not reachable:
        # #784: NEVER the address it is already configured for. discover()
        # scans the subnet and happily reports the box at 10.89.1.205 while
        # the station is looking for it at 10.89.1.205, which came out as
        # "DHCP moved it" naming one address twice and sent the operator to
        # the router to fix nothing. A box answering AT its own address is
        # not a box that moved; it is a box that is wedged.
        elsewhere = [a for a in await satellite_discover()
                     if a and a != SATELLITE_HOST]
    if not ha_satellite:
        add("Found at another address", None,
            ", ".join(elsewhere) if elsewhere else "no")
    if delivery_blocked:
        add("Verified station delivery", False,
            f"{len(_BOX_HOLD)} clip(s) held · breaker "
            + ("open" if time.time() < float(_BOX_DOWN.get("until") or 0)
               else "closed")
            + f" · last playout {round(float(_LAST_PLAYOUT.get('ratio') or 0) * 100)}%")

    # #757: THE ROUTING, first, because it is the one thing here that was
    # actually wrong and nothing in this function was looking at it. A box
    # in perfect health says nothing at all when the master switch is off,
    # and every check above passes while it does.
    routed = (_RADIO.get("voice_to") or "box") in ("box", "both")
    add("The show is pointed at the Pine Box", routed,
        f"DJ voice is routed to {_RADIO.get('voice_to') or 'box'}"
        + ("" if routed else " — not to the box"))
    add("Pine Box master switch", box_talk_ok(),
        "on" if box_talk_ok() else "OFF — the station is not calling the box")

    # One diagnosis, and the steps that follow from it.
    #
    # #757: the healthy verdict has to EARN itself. It used to read one
    # field — the Home Assistant entity state — and never look at the
    # checks it had just built, so it announced "Nothing is wrong" with a
    # failing check printed two lines above it. Anything false here is a
    # reason, and the first reason wins.
    failed = [c for c in checks if c["ok"] is False]
    # #777: THE ORDER. A switch or a picker is only the cause when putting it
    # right would actually make the box talk. This ladder tested the routing
    # FIRST, so with the satellite port shut it said "the DJ voice is not
    # routed to the Pine Box" and told the operator to point the show at a box
    # that could not receive it — they do, hear nothing, switch back to the
    # browser, ask again, and are told the same thing. Measured live: the box
    # answering ping and ARP with :10700 refusing, and this function calling
    # it a routing problem. A box that cannot receive audio outranks every
    # preference about where to send it.
    _fixable_here = probe["state"] in ("ok", "unset") or played_recently
    if not _fixable_here and elsewhere:
        # DHCP moved it — a real address problem, and more useful than
        # "it is not answering where we are looking".
        cause = (f"The Pine Box is alive at {elsewhere[0]}, but Home "
                 f"Assistant is looking for it at {SATELLITE_HOST}. DHCP "
                 "moved it.")
        steps = [
            f"Give it a fixed address: on the router, reserve "
            f"{SATELLITE_HOST} for MAC {SATELLITE_MAC}.",
            "Reboot the Pine Box so it takes the reserved lease.",
            "Press 🛠 in the panel to reload the link.",
            "Only if a reservation is impossible: POST /api/satellite/repoint "
            "with confirm=true — it renames every entity, which is why it is "
            "not automatic.",
        ]
    elif not _fixable_here:
        _off = "; ".join([
            "the master switch is off" if not box_talk_ok() else "",
            "the DJ voice is routed elsewhere" if not routed else "",
        ]).strip("; ")
        cause = ("The Pine Box is not accepting audio: " + probe["detail"]
                 + ". Nothing you change in the panel will be heard until "
                 "that is fixed"
                 + (f" (and {_off})" if _off else "") + ".")
        steps = ([
            "Power-cycle the Pine Box — it is on the network but the "
            "satellite service on it is not listening.",
        ] if probe["state"] == "refused" else [
            "Check the Pine Box has power and is on the same network.",
        ] if probe["state"] == "timeout" else [
            "Power-cycle the Pine Box — it answers but has stopped "
            "servicing sessions (#712).",
        ]) + [
            "Meanwhile the show keeps playing in the browser — every line "
            "rendered for the box is held on the shelf and goes out the "
            "moment it comes back.",
            "Once it answers, set the DJ voice picker to Pine Box and press "
            "Initialize the Pine Box.",
        ]
    elif not box_talk_ok():
        cause = ("The Pine Box master switch is OFF, so the station is not "
                 "calling it — whatever the DJ voice picker says.")
        steps = [
            "Turn the Pine Box switch on at the top of the DJ panel.",
            "Check the DJ voice picker says Pine Box.",
            "Press Initialize the Pine Box to prove it end to end.",
        ]
    elif not routed:
        cause = ("The DJ voice is not routed to the Pine Box, so the show is "
                 "playing in the browser instead.")
        steps = ["Set the DJ voice picker to Pine Box.",
                 "Press Initialize the Pine Box to prove it end to end."]
    elif link["online"] and not failed:
        cause = "Nothing is wrong — the Pine Box is connected."
        steps = ["Say something to it, or start Pine Box FM."]
    elif link["online"] and failed:
        # It is talking to Home Assistant and something else is unhappy.
        # Name the unhappy thing rather than declaring victory over it.
        cause = ("Home Assistant has the Pine Box, but "
                 + "; ".join(c["name"].lower() + " — " + c["detail"]
                             for c in failed)
                 + ".")
        steps = [
            "Press Initialize the Pine Box — it works down this list and "
            "ends by making the box actually say something.",
            "If the box speaks after that, the failing check above is the "
            "one to distrust, not the box.",
        ]
    # (#777: the "DHCP moved it" case is handled at the top of the ladder now,
    # with the rest of the box-cannot-hear-you faults, rather than three
    # branches below two panel settings that cannot fix it.)
    elif reachable and not link["online"]:
        cause = ("The Pine Box is answering, but Home Assistant has not "
                 "picked it up.")
        steps = ["Press 🛠 in the panel — it reloads the Wyoming entry.",
                 "If that does not take, restart Home Assistant."]
    elif not reachable:
        cause = ("The Pine Box is not on the network — nothing answers for it"
                 + (", not even at the link layer" if known and not on_lan
                    else "") +
                 ". It is powered off, or it never joined the Wi-Fi.")
        steps = [
            "If the box itself says \"Wi-Fi is disconnected\" when you press "
            "its button, it is alive and booting — this is not dead hardware, "
            "it simply cannot join the network. Work through the next two "
            "steps in order.",
            f"Confirm it is provisioned for {SATELLITE_SSID}. This is the "
            "usual cause: the radio is 2.4 GHz only and cannot see the 5 GHz "
            "network of the same name.",
            "Power-cycle it: unplug for 10 seconds, plug back in, wait 60.",
            "If it still does not appear, factory reset and re-provision — "
            "see the guide.",
            "Last resort: connect it by USB and use the serial console; that "
            "is the only way to see why it is failing to associate.",
        ]
    else:
        cause = "The device answers but is not speaking Wyoming."
        steps = ["Power-cycle it.",
                 "Check the serial console — see section 5 of the guide.",
                 "Re-flash the firmware if it persists."]

    if ha_satellite and not link["online"] and probe.get("state") == "refused":
        steps = [
            "Pull the Nabu's power for ten seconds and plug it back in — "
            "it rejoins in about a minute and the station brings the "
            "routing home by itself.",
            "Until then the show rides the app/page: the station routes "
            "the DJs and the records 'both' on its own while the box is "
            "down (#1156).",
            "lilspark reaches both the Nabu and the music share over its "
            "Wi-Fi hop (its Ethernet port enP7s7 is unplugged); that hop's "
            "retries are what make both flap.",
        ]
    return {
        "online": link["online"],
        # #757: "online" is one entity's state string and was being read as
        # "working". This is the honest one: nothing failed, and the show is
        # actually pointed at the box.
        "healthy": bool(link["online"] and not failed and routed
                        and box_talk_ok()),
        "failing": [c["name"] for c in failed],
        "checks": checks,
        "cause": cause,
        "steps": steps,
        "host": SATELLITE_HOST,
        "mac": SATELLITE_MAC,
        "ssid": SATELLITE_SSID,
        "guide": "/guide/pinebox",
        "pdf": "/api/pinebox/guide.pdf" if GUIDE_PDF.is_file() else "",
    }



# --- USB serial, bridged to the browser ------------------------------------
# The device is a Bouffalo BL-series MCU: 115200 8N1, and the console is the
# only place it will tell you why it cannot join the Wi-Fi.

SERIAL_BAUD = int(os.getenv("SERIAL_BAUD", "115200"))
_SERIAL: dict[str, Any] = {
    "port": "", "link": None, "buffer": [], "reader": None, "open_at": 0.0,
}
_SERIAL_LOCK = RLock()
_SERIAL_MAX_LINES = 800


# USB bridges that turn up on this class of board. Anything here is worth
# pointing at; everything else is almost certainly a mouse or a hub.
SERIAL_VIDS = {
    "1a86": "CH340/CH34x bridge",
    "10c4": "CP210x bridge",
    "0403": "FTDI bridge",
    "067b": "Prolific bridge",
    "303a": "Espressif native USB",
    "349e": "Bouffalo Lab native USB",
    "2e8a": "Raspberry Pi RP2040",
}


def usb_devices() -> list[dict[str, Any]]:
    """Every USB device the kernel sees, minus its own root hubs.

    This is what separates "nothing is plugged in" from "something is plugged
    in but no serial driver bound to it" — two problems with two fixes."""
    found: list[dict[str, Any]] = []
    try:
        nodes = sorted(Path("/sys/bus/usb/devices").iterdir())
    except OSError:
        return found

    for node in nodes:
        if not (node / "idVendor").is_file():
            continue

        def field(name: str) -> str:
            try:
                return (node / name).read_text().strip()
            except OSError:
                return ""

        vid, pid = field("idVendor"), field("idProduct")
        if vid == "1d6b":                      # the kernel's own root hubs
            continue
        found.append({
            "port": node.name,
            "vid_pid": f"{vid}:{pid}",
            "maker": field("manufacturer"),
            "product": field("product"),
            "serial_like": vid in SERIAL_VIDS,
            "note": SERIAL_VIDS.get(vid, ""),
        })
    return found


def serial_ports() -> list[dict[str, str]]:
    """Everything that looks like a serial device, with whatever the kernel
    knows about it — enough to tell a Pine Box from a mouse."""
    found: list[dict[str, str]] = []
    try:
        from serial.tools import list_ports        # type: ignore

        for port in list_ports.comports():
            found.append({
                "device": port.device,
                "description": port.description or "",
                "manufacturer": getattr(port, "manufacturer", "") or "",
                "vid_pid": (f"{port.vid:04x}:{port.pid:04x}"
                            if port.vid and port.pid else ""),
                "serial": getattr(port, "serial_number", "") or "",
            })
    except Exception:
        pass

    # pyserial inspects the container's /dev only. The agent also mounts the
    # host device tree at /host-dev so a Pine Box attached to lilspark rather
    # than to the browser computer remains discoverable after container restarts.
    known = {str(p.get("device") or "") for p in found}
    for root in (Path("/dev"), Path("/host-dev")):
        for pattern in ("ttyUSB*", "ttyACM*"):
            for node in sorted(root.glob(pattern)):
                if str(node) in known:
                    continue
                found.append({"device": str(node), "description": "",
                              "manufacturer": "", "vid_pid": "", "serial": ""})
                known.add(str(node))

    # This board has 32 onboard UARTs and none of them can ever be the Pine
    # Box, which arrives as a USB device. Offering them is worse than
    # offering nothing: an empty list is the truthful answer to "what is
    # plugged in", and the panel says so.
    return [p for p in found
            if "ttyUSB" in p["device"] or "ttyACM" in p["device"]]


def _serial_pump() -> None:
    """Blocking reader. Lines land in a bounded buffer the panel polls."""
    link = _SERIAL["link"]
    pending = b""
    while link is not None and _SERIAL["link"] is link:
        try:
            chunk = link.read(512) or b""
        except Exception:
            break
        if not chunk:
            continue
        pending += chunk
        while b"\n" in pending:
            line, pending = pending.split(b"\n", 1)
            text = line.decode("utf-8", "replace").rstrip("\r")
            with _SERIAL_LOCK:
                _SERIAL["buffer"].append(
                    {"ts": time.time(), "text": text})
                del _SERIAL["buffer"][:-_SERIAL_MAX_LINES]
    try:
        if link is not None:
            link.close()
    except Exception:
        pass


def serial_open(device: str, baud: int = 0) -> dict[str, Any]:
    with _SERIAL_LOCK:
        if _SERIAL["link"] is not None:
            serial_close()
        try:
            import serial                          # type: ignore
        except Exception as exc:
            raise HTTPException(
                status_code=503,
                detail=f"pyserial is not available in the agent: {exc}")
        try:
            link = serial.Serial(device, baud or SERIAL_BAUD, timeout=1)
        except Exception as exc:
            raise HTTPException(status_code=400, detail=str(exc)[:200])

        _SERIAL.update({
            "port": device, "link": link, "buffer": [],
            "open_at": time.time(),
        })
        reader = Thread(target=_serial_pump, name="serial-pump", daemon=True)
        _SERIAL["reader"] = reader
        reader.start()
        return {"port": device, "baud": baud or SERIAL_BAUD, "open": True}


def serial_close() -> dict[str, Any]:
    with _SERIAL_LOCK:
        link = _SERIAL["link"]
        _SERIAL["link"] = None
        try:
            if link is not None:
                link.close()
        except Exception:
            pass
        _SERIAL.update({"port": "", "reader": None})
    return {"open": False}


def serial_write(text: str, newline: bool = True) -> int:
    with _SERIAL_LOCK:
        link = _SERIAL["link"]
        if link is None:
            raise HTTPException(status_code=409, detail="No port is open")
        payload = (text + ("\r\n" if newline else "")).encode()
        try:
            return int(link.write(payload) or 0)
        except Exception as exc:
            raise HTTPException(status_code=502, detail=str(exc)[:200])


def serial_read(since: float = 0.0) -> list[dict[str, Any]]:
    with _SERIAL_LOCK:
        return [line for line in _SERIAL["buffer"] if line["ts"] > since]


def play_search_sound() -> None:
    """Fire-and-forget the 'reading the internet' sound effect on the Home
    Assistant media player. Needs HA_TOKEN + HA_MEDIA_PLAYER +
    SEARCH_SOUND_URL configured; silently does nothing otherwise, and never
    delays the actual search."""
    token, player = _ha_creds()
    if not (token and player and SEARCH_SOUND_URL and box_talk_ok()):
        return
    # #786: a media_player service refuses an assist_satellite entity id —
    # with a voice device selected this call was a guaranteed silent no-op.
    # Nabu's clips ride its companion media player; pine has no media
    # player, so the chime simply stays off there.
    if player == NABU_SATELLITE and NABU_MEDIA_PLAYER:
        player = NABU_MEDIA_PLAYER
    elif player.startswith("assist_satellite."):
        return

    async def _play() -> None:
        try:
            async with httpx.AsyncClient(timeout=10) as client:
                await client.post(
                    f"{HA_URL}/api/services/media_player/play_media",
                    headers={"Authorization": f"Bearer {token}"},
                    json={
                        "entity_id": player,
                        "media_content_id": SEARCH_SOUND_URL,
                        "media_content_type": "music",
                        "announce": True,
                    },
                )
        except Exception:
            pass

    try:
        asyncio.create_task(_play())
    except RuntimeError:
        pass  # no running loop (self-check context)


# --- Conversation history --------------------------------------------------


# Behind-the-scenes subsystems, in the order they should read in the activity
# console. Maps the internal feature flag -> human label.
FEATURE_LABELS: list[tuple[str, str]] = [
    ("image_requested", "image generation"),
    ("video_requested", "video generation"),
    ("tune_requested", "music video"),
    ("weather_used", "weather"),
    ("web_search_used", "web search"),
    ("tv_lookup_used", "tv lookup"),
    ("game_lookup_used", "game lookup"),
    ("gear_manual_used", "gear manual"),
    ("from_library", "from library"),
    ("system_status_used", "system status"),
    ("openwebui_used", "open webui"),
    ("memory_used", "memory recall"),
    ("memory_saved", "memory saved"),
]


def turn_features(metadata: dict[str, Any]) -> list[str]:
    """Which subsystems fired on a turn — the 'behind the scenes' trail the
    live activity console renders."""
    return [label for flag, label in FEATURE_LABELS if metadata.get(flag)]


def log_turn(user_text: str, answer: str, metadata: dict[str, Any]) -> None:
    # ponytail: append-only JSONL; add rotation only if the file gets large.
    try:
        CONVERSATIONS_PATH.parent.mkdir(parents=True, exist_ok=True)
        entry = {
            "ts": int(time.time()),
            "user": user_text,
            "answer": answer,
            "prompt": metadata.get("active_prompt"),
            "model": metadata.get("model"),
            "features": turn_features(metadata),
            "stats": metadata.get("stats") or {},
        }
        with CONVERSATIONS_PATH.open("a") as handle:
            handle.write(json.dumps(entry) + "\n")
    except Exception:
        pass


FEEDBACK_PATH = data_path("feedback.jsonl")


def read_feedback(limit: int = 40) -> list[dict[str, Any]]:
    try:
        lines = FEEDBACK_PATH.read_text().splitlines()
    except Exception:
        return []
    out: list[dict[str, Any]] = []
    for line in lines[-limit:]:
        try:
            out.append(json.loads(line))
        except Exception:
            continue
    return out


def read_history(limit: int = 50) -> list[dict[str, Any]]:
    try:
        lines = CONVERSATIONS_PATH.read_text().splitlines()
    except Exception:
        return []
    out: list[dict[str, Any]] = []
    for line in lines[-limit:]:
        try:
            out.append(json.loads(line))
        except Exception:
            continue
    return out


# --- Memory: short-term conversation context + long-term remembered facts ---


def has_client_history(messages: list[dict[str, Any]]) -> bool:
    # If the voice client already sends prior turns, trust those instead of
    # stitching in the server-side recent conversation.
    return sum(1 for m in messages if m.get("role") == "user") > 1


def prompt_just_changed(current: str) -> bool:
    """True when the last thing we answered was written under a different
    personality. A switch is a clean slate (#135) — otherwise the client's
    own history keeps feeding the model replies in the old voice and the
    change appears to lag by a turn or two."""
    try:
        recent = read_history(limit=1)
    except Exception:
        return False
    if not recent:
        return False
    previous = recent[-1].get("prompt")
    return bool(previous) and previous != current


def drop_stale_history(
    messages: list[dict[str, Any]], current: str
) -> list[dict[str, Any]]:
    """Keep only the newest user message when the personality just changed."""
    if not prompt_just_changed(current):
        return messages
    for message in reversed(messages):
        if message.get("role") == "user":
            return [message]
    return messages


MEMORY_COMMAND = re.compile(
    r"^\s*(?:please\s+)?(?:remember|note|keep in mind|don'?t forget|"
    r"make a note)\b(?:\s+that)?[:,]?\s*(.+)$",
    re.IGNORECASE | re.DOTALL,
)


def is_memory_command(text: str) -> str | None:
    match = MEMORY_COMMAND.match(text)
    if not match:
        return None
    return match.group(1).strip().rstrip(".") or None


def save_memory(text: str) -> None:
    try:
        MEMORIES_PATH.parent.mkdir(parents=True, exist_ok=True)
        with MEMORIES_PATH.open("a") as handle:
            handle.write(
                json.dumps({"ts": int(time.time()), "text": text}) + "\n"
            )
    except Exception:
        pass


def read_memories(limit: int = 100) -> list[dict[str, Any]]:
    try:
        lines = MEMORIES_PATH.read_text().splitlines()
    except Exception:
        return []
    out: list[dict[str, Any]] = []
    for line in lines[-limit:]:
        try:
            out.append(json.loads(line))
        except Exception:
            continue
    return out


def delete_memory(ts: int) -> None:
    try:
        lines = MEMORIES_PATH.read_text().splitlines()
    except Exception:
        return
    kept: list[str] = []
    for line in lines:
        try:
            if json.loads(line).get("ts") == ts:
                continue
        except Exception:
            pass
        kept.append(line)
    try:
        MEMORIES_PATH.write_text("\n".join(kept) + ("\n" if kept else ""))
    except Exception:
        pass


def update_memory(ts: int, text: str) -> None:
    try:
        lines = MEMORIES_PATH.read_text().splitlines()
    except Exception:
        return
    out: list[str] = []
    for line in lines:
        try:
            obj = json.loads(line)
            if obj.get("ts") == ts:
                obj["text"] = text
                out.append(json.dumps(obj))
                continue
        except Exception:
            pass
        out.append(line)
    try:
        MEMORIES_PATH.write_text("\n".join(out) + ("\n" if out else ""))
    except Exception:
        pass


def format_memory_context(memories: list[dict[str, Any]]) -> str:
    facts = "\n".join(f"- {m.get('text', '')}" for m in memories if m.get("text"))
    return (
        "Things you remember about the user and past conversations:\n"
        f"{facts}\n"
        "Use these when relevant. Do not recite them unless the user asks."
    )


def format_recent_conversation(turns: list[dict[str, Any]]) -> str:
    lines = ["Recent conversation so far (oldest first):"]
    for turn in turns:
        user = (turn.get("user") or "").strip()
        answer = (turn.get("answer") or "").strip()
        if user:
            lines.append(f"User: {user}")
        if answer:
            lines.append(f"Assistant: {answer}")
    lines.append("Continue naturally, keeping this context in mind.")
    return "\n".join(lines)


# An em dash counts as a finished line: that is how an interruption is
# written, and #185 asks for interruptions on purpose. What must never survive
# is a line that stops mid-word because the budget ran out (#168).
_SENTENCE_END = re.compile(r"[.!?…—][\"')\]]*")


def whole_sentences(text: str) -> str:
    """Cut back to the last finished sentence.

    Every one of these replies is read aloud, so one that ran into its token
    or character ceiling stops mid-word in someone's ear. Saying one sentence
    fewer beats stopping halfway through one. If nothing in it finished, say
    it anyway — a clipped line still beats silence."""
    trimmed = str(text or "").strip()
    ends = list(_SENTENCE_END.finditer(trimmed))
    if not ends:
        return trimmed
    return trimmed[:ends[-1].end()].strip() or trimmed


# #853: what each kind of segment needs from the model. Context is KV
# cache on a GPU the voices are also using, so it is spent where it buys
# something — a recap has to hold the hour it is recapping; a sting does
# not. Temperature follows the job rather than one house setting.
# #1045: THE ONE CONTEXT SIZE THE STATION LOADS ITS MODELS AT.
#
# num_ctx is a load-time parameter. Every distinct value is a separate
# runner build, and this station was asking for five of them by segment
# kind - 61.3 forced rebuilds an hour, 1,470 seconds of gate time an
# hour, a fifth of everything the box can do, spent loading rather than
# writing. Pinned, the runners load once and stay.
#
# 65536 because it is what the busiest roads (banter, callers) asked
# for and it holds every prompt the station builds with room to spare.
MODEL_CTX = 65536


def model_ctx() -> int:
    """The context size for every model call, whoever asked."""
    try:
        got = int(dj_settings().get("model_ctx") or 0)
    except Exception:  # noqa: BLE001
        got = 0
    return max(2048, min(131072, got or MODEL_CTX))


# #1045: the num_ctx column here NO LONGER APPLIES - see model_ctx. It
# is left in place because it records what each kind was thought to
# need, and that is worth knowing if the pinning is ever revisited.
# `spice` still applies: it is a creative dial and costs nothing.
WRITING_PROFILES: dict[str, dict[str, float]] = {
    "recap":         {"num_ctx": 131072, "spice": 0.45},
    "deep":          {"num_ctx": 131072, "spice": 0.60},
    "banter":        {"num_ctx": 65536,  "spice": 0.70},
    "banter_caller": {"num_ctx": 65536,  "spice": 0.75},
    "caller":        {"num_ctx": 65536,  "spice": 0.75},
    "news":          {"num_ctx": 32768,  "spice": 0.50},
    "gallery":       {"num_ctx": 32768,  "spice": 0.70},
    "manager":       {"num_ctx": 32768,  "spice": 0.60},
    "bombshell":     {"num_ctx": 16384,  "spice": 0.90},
    "ad":            {"num_ctx": 16384,  "spice": 0.85},
    "station_id":    {"num_ctx": 8192,   "spice": 0.90},
    "record":        {"num_ctx": 8192,   "spice": 0.70},
}


def writing_profile() -> dict[str, float]:
    """The brief for the segment being written, or {} when the schedule
    is not running — in which case nothing changes."""
    try:
        return WRITING_PROFILES.get(
            str(_RADIO.get("sched_kind") or ""), {}) or {}
    except Exception:  # noqa: BLE001
        return {}


# #1019: the two marks the desk listing colours a row by. A prompt
# carrying either of these has had the crystal in it, and the operator
# asked to be able to see which. Kept as constants because the strings
# are written in two other places and a typo would silently stop the
# highlighting rather than break anything loudly.
# #1037: these are matched against the prompt to colour the desk's
# tinted column, and they had gone stale - every rewrite of the second
# prompt left them behind, so EVERY second-pass call showed `tinted: ""`
# in the operator's own instrumentation while the tint was running fine.
# A marker matched against text that is edited often has to be a phrase
# the text cannot lose, so it is the one line both prompts are built
# around: the crystal's own writing.
TINT_MARK_LINES = "HOW THAT WRITER WRITES"
TINT_MARK_FLAVOUR = "HOW THAT WORLD ACTUALLY TALKS"


async def ask_model(prompt: str, limit: int = 300,
                    spice: float = 0.0, num_ctx: int = 0,
                    mark: dict[str, Any] | None = None,
                    model: str = "", result_contract: str = "spoken") -> str:
    """A plain model call for the agent's own voice lines — no web search, no
    gear manuals, no technical feed, and nothing written to history. Routing
    an internal prompt through generate_answer makes it look like something
    the user asked, which is how "ACKNOWLEDGE THIS REQUEST…" ended up on the
    Pine Box screen."""
    if result_contract not in {"spoken", "track_reception", "transcript_repair"}:
        raise ValueError("Unknown model result contract")
    settings = load_settings()
    _is_tint = str((mark or {}).get("kind") or "").startswith("tint")
    # #1036: a caller may name its own model. The station runs a small
    # fast one because it has to keep up with a live show; a road that
    # does NOT have to keep up - the tinting pass runs on rounds that
    # will not air for twenty minutes - can afford a better one.
    if model:
        settings = dict(settings)
        settings["model"] = str(model)
    started = time.monotonic()
    # Never let a reply exceed the operator's ceiling (#599) — the slider's
    # sweet spot that keeps every statement inside the box's size limit.
    limit = max(1, min(int(limit),
                       int(dj_settings().get("reply_max_chars") or 6500)))
    # The token budget has to follow the caller's character limit, not a flat
    # 220: a four-line banter asks for 700 characters and used to run out of
    # tokens mid-sentence, so a DJ stopped talking halfway through (#168).
    # Half a token to the character is deliberately generous — running out is
    # what gets heard, and unused budget costs nothing.
    # `spice` jitters the temperature upward per call (#324): the same
    # prompt stops producing the same shape of answer twice.
    # #853: and the temperament. A caller that named its own spice keeps
    # it; otherwise the segment's brief decides how loose to be — a recap
    # steady, a rant loose.
    spice = spice or float(writing_profile().get("spice") or 0.0)
    # #1083: a lift with the surplus, and deliberately the SMALLEST of
    # the four things it buys. A hot model is not a better writer, it is
    # a less predictable one - the real gains are in giving it more to
    # work from, not more licence to invent. A tenth of a point at full
    # surplus and no more.
    try:
        if spice and not _is_tint:
            spice = min(1.0, spice + 0.10 * surplus())
    except Exception:  # noqa: BLE001
        pass
    # #895: "as we build up a queue and we've gotten further in our
    # pantry, then we can start experimenting and pushing the
    # temperatures". A deep shelf is exactly when a strange take is
    # affordable — there is an hour of finished audio behind it, so a
    # round that comes out odd costs nothing but itself. A cold shelf
    # gets none of this; the bonus is zero at zero depth.
    _hot = 0.30 * box_depth()
    # #941: and the road's own heat on top, so a sixth stacked caller is
    # written looser than the first. Randomised inside the band rather
    # than set to it — "randomizes the temperature of the customer on
    # further calls" — so two hot rounds are not hot in the same way.
    _heat = 0.0
    try:
        _heat = float((_ROUND_MARK.get(_mark_key()) or {}).get("heat") or 0)
    except Exception:  # noqa: BLE001
        _heat = 0.0
    # #901: "We need to be seeding our systems to make sure that we are
    # not generating the same results over and over." The seed below is
    # genuinely fresh per call and always was — but BOTH jitters were
    # gated on `spice`, and most roads pass none, so those calls decoded
    # at exactly settings["temperature"] and exactly settings["top_p"]
    # every single time. A random seed against an otherwise identical
    # decode is the weakest of the three knobs. A small floor band now
    # applies always; `spice` still opens it much wider.
    temperature = min(1.35, float(settings["temperature"])
                      + (random.uniform(0.0, spice) if spice
                         else random.uniform(0.0, 0.06))
                      + (random.uniform(0.0, _hot) if _hot > 0.02 else 0.0)
                      + (random.uniform(0.0, 0.35 * _heat)
                         if _heat > 0.02 else 0.0))
    if _is_tint:
        # Rewriting has a fixed factual contract. It must not inherit the
        # original writer's temperature, stocked-shelf heat and heat jitter.
        temperature = max(0.15, min(0.65, float(spice or 0.45)))
    # #941: the paperwork, at the moment it is true.
    round_mark(temperature=round(temperature, 3),
               model=str(settings.get("model") or ""),
               spice=round(float(spice or 0), 3),
               box_depth=round(box_depth(), 3),
               heat=round(_heat, 3))
    max_tokens = max(settings["max_tokens"], limit // 2 + 40)
    if _is_tint:
        max_tokens = max(128, limit // 2 + 64)
    pipeline_log("model", f"{settings['model']} writing · "
                          f"budget {limit} chars · temp {temperature:.2f}",
                 extra=(f"PROMPT · {settings['model']} · "
                        f"temp {temperature:.2f} · {max_tokens} tokens · "
                        f"ctx {settings['num_ctx']} · "
                        f"top_p {settings['top_p']}:\n{prompt}"))
    # #941: and the writer is TOLD. One place, so every road that
    # writes ahead gets it — the caller, the memo, the painting round —
    # rather than each having to remember. Only rounds a preparer has
    # marked carry any heat at all, so nothing on the live path changes.
    # #1064: NEVER ON A TINT PROMPT. The clause was appended AFTER "Return
    # ONLY the rewritten line", so the model rewrote the clause - eight of
    # the last forty bars on the trail read "THE DIAL (#941) - there is a
    # deep shelf of finished audio standing behind this one".
    if _heat > 0.34 and not str((mark or {}).get("kind") or "").startswith("tint"):
        try:
            prompt = str(prompt) + heat_clause(_heat, str(
                (_ROUND_MARK.get(_mark_key()) or {}).get("heat_road")
                or "caller"))
        except Exception:  # noqa: BLE001
            pass
    _review_context = _LINE_REVIEW_CONTEXT.get()
    _review_kind = str(_review_context.get("kind") or (_review_context.get("entry") or {}).get("prep_kind") or "")
    _review_gate = "tint" if str((mark or {}).get("kind") or "").startswith("tint") else ""
    _review_guidance = line_review_guidance(_review_kind, _review_gate)
    _review_messages = ([{"role": "system", "content": _review_guidance}] if _review_guidance else [])
    _review_messages.append({"role": "user", "content": prompt})
    _learning_wire = _CRYSTAL_LEARNING_WIRE.get()
    if _learning_wire is not None:
        _learning_wire["model"] = str(settings["model"])
        _LAB_RUNTIME.record("learning_attempt", {"request_id": _learning_wire["request_id"],
            "model": _learning_wire["model"], "prompt_version": CRYSTAL_PROMPT_VERSION})
    result = await call_ollama(
        model=settings["model"],
        messages=_review_messages,
        temperature=temperature,
        max_tokens=max_tokens,
        # #no-repeats: jittered with the temperature, for the same reason. A fixed
        # top_p against a prompt whose fixed frame is most of its length is
        # not enough entropy to move the decode off its favourite sentence.
        top_p=min(0.99, max(0.5, settings["top_p"]
                            + (random.uniform(-0.05, 0.06) if spice
                               else random.uniform(-0.03, 0.04)))),
        # #no-repeats: a fresh seed every call, so two identical prompts do not
        # decode identically, and a penalty on the model's own repeats.
        seed=random.randint(1, 2_000_000_000),
        repeat_penalty=1.12,
        # A caller may ask for an EXPANDED window (#496): a deep round hands
        # the model far more foundation and needs room to hold it.
        # #894/#832: 32768 was a hard ceiling against models that carry
        # far more — gemma4 reports 131072. The operator asked for more
        # rhetoric per visit to the model; this is the room to write it
        # in. The setting still governs; this only stops clamping it.
        # #853: the caller's own argument wins; then the brief for this
        # segment; then the operator's setting.
        # #1045: PINNED. The caller's argument and the segment brief are
        # both ignored on purpose - see model_ctx. Every value they
        # could supply is another runner rebuild, and the rebuild costs
        # more than the extra room was ever worth.
        num_ctx=model_ctx(),
        purpose=("sfx_tint_reserve" if _is_tint and _SFX_RESERVE_WRITING.get()
                 else "station:" + str((mark or {}).get("kind") or "writing")),
    )
    if result.get("deferred"):
        pipeline_log("lookahead", str(result.get("reason") or "writer admission deferred"))
        if "tint" in str((mark or {}).get("kind") or ""):
            raise WritingDeferred(str(result.get("reason") or "the tint writer is fully admitted"))
        return ""                       # no compute/quality failure is charged
    _retry_responses = _TINT_REPAIR_RESPONSES.get()
    if _is_tint and _retry_responses is not None:
        _retry_responses.append(True)     # mutable scope survives child awaits; no global attribution
    # #1079: THE DECOMPOSITION, WHICH WAS ARRIVING AND BEING DISCARDED.
    # Ollama returns total/load/prompt_eval/eval durations on every
    # response and this read only the content. `ms` is therefore wall
    # clock measured around the gate and cannot tell waiting from
    # working - measured, a 31b tint turn's 53s median is 16.7s of
    # compute and 36s of queue, and the ledger has been pricing that
    # contention as if it were the work.
    _spent: dict[str, float] = {}
    try:
        for _k in ("total_duration", "load_duration",
                   "prompt_eval_duration", "eval_duration"):
            _v = result.get(_k)
            if _v:
                _spent[_k[:-9]] = round(float(_v) / 1e9, 3)
        for _k in ("prompt_eval_count", "eval_count"):
            if result.get(_k):
                _spent[_k[7:] if _k.startswith("prompt_") else _k] = int(
                    result[_k])
        if _spent:
            _spent["service"] = round(
                _spent.get("load", 0.0) + _spent.get("prompt_eval", 0.0)
                + _spent.get("eval", 0.0), 3)
    except Exception:  # noqa: BLE001
        _spent = {}
    answer = ((result.get("message") or {}).get("content") or "").strip()
    answer = re.sub(r"<think>.*?</think>", " ", answer, flags=re.S)
    # These two callers request a control result or repaired source material,
    # not ordinary station prose. Keep the actual response in its wire trace;
    # remove only the known repair-instruction prefix before prose boundaries
    # can mistake that prefix for the entire useful answer.
    if result_contract == "transcript_repair" and not _is_tint:
        cleaned = clean_repair_prompt_echo(answer)
        if cleaned["changed"]:
            pipeline_log("speakbox", "Removed exact echoed repair instructions before draft handling",
                         extra=json.dumps({"original": answer, "removed": cleaned["removed"]}, ensure_ascii=False))
            answer = cleaned["text"]
    control_answer = (result_contract == "track_reception" and not _is_tint
                      and answer.strip() == "NONE")
    # A finished rap response may use bars or numbered lines without a
    # sentence-ending full stop. Preserve its shape for the crystal parser
    # and grader instead of throwing away unpunctuated bars as prose scraps.
    kept = answer.strip() if _is_tint or control_answer else whole_sentences(" ".join(answer.split())[:limit])
    if _is_tint and (len(kept) > limit or result.get("done_reason") == "length"):
        line_review_capture("tint_output", str((mark or {}).get("tint_before") or ""), kept,
            reasons=["the model exhausted its token budget" if result.get("done_reason") == "length"
                     else f"the complete rewrite exceeded its {limit}-character output budget"],
            context={"kind": str(_review_kind or ""), "stage": "model_output", "limit": limit,
                     "prompt": prompt, "model": settings["model"], "finish_reason": result.get("done_reason")},
            technical=True, disposition="rewrite_rejected")
        kept = ""  # An incomplete/over-budget response is retained, never silently clipped into a passing bar.
    if not _is_tint and " ".join(answer.split()) != kept and answer.strip():
        reason = "draft exceeded the character limit or ended with an unfinished sentence"
        context = {"kind": "model_draft", "who": "", "limit": limit,
                   "script": answer, "retained": kept,
                   "model": str(settings.get("model") or "")}
        if line_review_permits("draft_trimming", answer, kept, [reason], context,
                               record=True, disposition="trimmed"):
            kept = answer.strip()
    # A reply without ONE finished sentence in it is a fragment the token
    # or character ceiling made — read aloud, it stops mid-thought in
    # someone's ear (#264, #265). Empty hands the line to the caller's
    # fallback, and every caller of this function has one that speaks in
    # whole sentences. A clipped line does not beat silence when silence
    # is never what actually airs.
    took = int((time.monotonic() - started) * 1000)
    # 2026-09-08 (the rejections census): a transcript repair has no sentence
    # punctuation by nature - the operator's documents are spoken transcripts
    # - and a JSON-shaped contract reply has none either. 302 of 974 pending
    # cuts were whole transcript repairs binned as "no finished sentence",
    # each a 5,000-character ask thrown away. A long repair with no full stop
    # is the repair; a short one that stops mid-word is still a fragment.
    _unpunctuated_by_nature = bool(kept) and not _is_tint and (
        (result_contract == "transcript_repair" and len(kept) >= 400)
        or kept.lstrip().startswith(("{", "[")))
    if (kept and not _is_tint and not control_answer and not _unpunctuated_by_nature
            and not _SENTENCE_END.search(kept)):
        if not line_review_permits("draft_fragment", kept,
                                   reasons=["no finished sentence"],
                                   context={"kind": "model_draft", "who": "",
                                            "script": answer}, record=True):
            pipeline_log("model", f"fragment binned after {took} ms — "
                                  "the fallback speaks instead (#264)")
            return ""
    # #1079: and it SAYS how much of that was waiting.
    _wait = ""
    try:
        if _spent.get("service"):
            _q = max(0.0, took / 1000.0 - float(_spent["service"]))
            _wait = (f" · {int(_spent['service'] * 1000)} ms working, "
                     f"{int(_q * 1000)} ms waiting")
    except Exception:  # noqa: BLE001
        _wait = ""
    pipeline_log("model", f"{settings['model']} answered · {took} ms · "
                          f"{len(kept)} chars{_wait}",
                 extra=f"RESULT:\n{kept}")
    # #782: the writing half of a line's story. A spoken line knows which
    # model made it but never how long it waited to be written, and "why was
    # there a gap there" is usually answered here rather than in the render.
    # #861: and the PAPERWORK. What was asked never survived the call,
    # so "what did we actually send it?" — the one question worth asking
    # of a bad round — could not be answered.
    try:
        _armed = ""
        try:
            _s = load_settings()
            _armed = str((_s["prompts"][_s["active_prompt"]] or {}).get(
                "name") or "")
        except Exception:  # noqa: BLE001
            _armed = ""
        _ctx = model_ctx()                                       # #1045
    except Exception:  # noqa: BLE001
        _armed, _ctx = "", 0
    # #1019: WAS THE CRYSTAL IN THIS PROMPT, AND HOW.
    #
    # Detected from the prompt rather than declared at each site, so
    # every road that tints - the two-pass rewrite, the SFX guy's warps
    # and news takes, the memo from upstairs, and the clause that rides
    # ordinary rounds when the second pass is off - lights up in the desk
    # listing without any of them having to be told to. `mark` is the
    # richer half: crystal_tint hands over the world, the passages and
    # the text going in, because a tint you can see but not inspect is
    # only half of what was asked for.
    _tinted = ""
    try:
        _p = str(prompt or "")
        if TINT_MARK_LINES in _p:
            _tinted = "lines"          # the crystal's own words went too
        elif TINT_MARK_FLAVOUR in _p or "CRYSTAL IS ON" in _p:
            _tinted = "flavour"        # the description only
    except Exception:  # noqa: BLE001
        _tinted = ""
    _row = {"at": time.time(), "model": settings["model"],
            "tinted": _tinted,
            "ms": took, "chars": len(kept),
            "temp": round(temperature, 2),
            "budget": limit, "text": kept[:400],
            # #861 — the whole exchange
            "prompt": str(prompt)[:6000],
            "script": kept[:6000],
            "kind": str(_RADIO.get("sched_kind") or ""),
            "armed": _armed,
            "sched": str(_RADIO.get("sched_prompt") or "")[:900],
            "num_ctx": _ctx}
    # #1022: A CALL THAT KNOWS WHAT IT IS FOR SAYS SO, and the schedule's
    # instruction is DROPPED rather than borrowed - it did not govern
    # this prompt, and GOVERNED BY is a claim, not a decoration. The
    # ambient stamp is right for the round the clock asked for and wrong
    # for every background brew that happens to run while it is on air.
    try:
        _mark = dict(mark or {})
        if _mark.get("kind"):
            _row["sched"] = ""
            _row["ambient_kind"] = str(_RADIO.get("sched_kind") or "")
        _row.update(_mark)
    except Exception:  # noqa: BLE001
        pass
    _MODEL_CALLS.append(_row)
    try:                                                    # #1020 (G1)
        airlog_model_call(_row, {**_spent, "prompt_eval_count":
                                 result.get("prompt_eval_count") or 0},
                          took)
    except Exception:  # noqa: BLE001
        pass
    # #1022: a per-turn tint (#1021) writes one row per turn, so a single
    # sixteen-turn round used to push every other call off a forty-row
    # ring - the desk would show nothing but the tint. Eighty rows costs
    # about a megabyte and keeps the rest of the evening visible.
    del _MODEL_CALLS[:-80]
    # #872: what a MODEL VISIT costs, into the task-cost ledger. Every
    # written task on the board pays for at least one of these, so this
    # is the floor under every estimate the scheduler makes.
    try:
        task_note("write", float(took) / 1000.0, 0.0, bool(kept))
    except Exception:  # noqa: BLE001
        pass
    return kept


def _ollama_category(purpose: str) -> tuple[str, int]:
    """Bound each background category; a denied tint retains its progress."""
    purpose = str(purpose or "")
    if purpose == "interactive":
        return "interactive", 0
    if purpose == "response_bank":
        return "repertoire", 1
    if purpose == "sfx_tint_reserve":
        return "sfx_reserve", 1
    if "tint" in purpose:
        return "tint", _ollama_category_cap("tint", purpose)
    return "station", _ollama_category_cap("station", purpose)


async def _tint_turn_yields(model: str, purpose: str,
                            most: float = 180.0, beat: float = 1.5) -> float:
    """2026-09-07: ROUNDS FIRST ON THE TINT LANE.

    The lane is one FIFO permit per model. Measured with the operator
    hearing records only: five single-line asks (an advert, a gallery
    line, a memo, the SFX guy, a station ID) sat in front of the one ask
    that would have put a whole round on air, and the round waited 163s
    before the model saw it. A single-line ask now waits while a
    whole-round ask for the same model is waiting or active, up to
    `most` seconds, then goes. Returns the seconds it yielded."""
    purpose = str(purpose or "")
    if "tint" not in purpose or "tint round" in purpose:
        return 0.0
    began = time.monotonic()
    try:
        while time.monotonic() - began < most:
            if not any(str(row.get("model")) == str(model)
                       and "tint round" in str(row.get("purpose") or "")
                       and row.get("state") in ("waiting", "active")
                       for row in list(_OLLAMA_JOBS.values())):
                break
            await asyncio.sleep(beat)
    except Exception:  # noqa: BLE001
        pass
    return time.monotonic() - began


@_LAB_RUNTIME.model_call
async def call_ollama(
    *,
    model: str,
    messages: list[dict[str, str]],
    temperature: float,
    max_tokens: int,
    top_p: float = 0.9,
    num_ctx: int = 8192,
    seed: int | None = None,
    repeat_penalty: float = 0.0,
    purpose: str = "interactive",
    thinking: bool = False,
) -> dict[str, Any]:
    # #no-repeats: the options here carried temperature, top_p, num_predict and
    # num_ctx and nothing else — no seed and no repeat penalty anywhere in the
    # file — so the same prompt reliably reproduced the same phrasing and the
    # model had no push at all against repeating itself inside one answer.
    options: dict[str, Any] = {
        "temperature": temperature,
        "top_p": top_p,
        "num_predict": max_tokens,
        "num_ctx": num_ctx,
    }
    if seed is not None:
        options["seed"] = int(seed)
    if repeat_penalty and repeat_penalty > 0:
        options["repeat_penalty"] = float(repeat_penalty)
    # ponytail: two in flight, ollama 0.30.6's chat queue wedged solid when
    # the show's clocks stacked unbounded 300s calls on top of each other.
    # #1079: ITS OWN LANE FIRST, then the global cap. Every runner
    # is launched -np 1 so ollama serialises per model - two 31b
    # calls at once measured 35.24s span against 31.5s of summed
    # compute, the second spending 18.35s purely queued. Overlap
    # across DIFFERENT models is free and is what this preserves.
    category, _cap = _ollama_category(purpose)
    admitted = sum(row["model"] == model and row["category"] == category
                   for row in _OLLAMA_JOBS.values())
    if _cap and admitted >= _cap:
        _OLLAMA_DEFERRED[model] = _OLLAMA_DEFERRED.get(model, 0) + 1
        _category_key = str(model) + ":" + category
        _OLLAMA_DEFERRED_CATEGORIES[_category_key] = _OLLAMA_DEFERRED_CATEGORIES.get(_category_key, 0) + 1
        _WRITING_DEFERRED.set(_WRITING_DEFERRED.get() + 1)
        return {"message": {"content": ""}, "deferred": True,
                "reason": f"{model} already has its admitted {category} writers; this job remains owed"}
    # Every admitted job joins the same visible FIFO. Parking single-line
    # work before registration hid waiters and let new rounds overtake it.
    identity = uuid.uuid4().hex[:12]
    _OLLAMA_JOBS[identity] = {"model": model, "purpose": str(purpose)[:100],
                            "category": category, "state": "waiting", "at": time.time()}
    try:
        async with _ollama_lane(model), _OLLAMA_GATE, \
                httpx.AsyncClient(timeout=180) as client:
            _OLLAMA_JOBS[identity]["state"] = "active"
            wire_body = {"model": model, "messages": messages, "stream": False,
                         "think": bool(thinking), "keep_alive": "30m", "options": options}
            _LAB_RUNTIME.record("model_wire_request", {"call_id": _LAB_RUNTIME.call.get(),
                                                      "body": wire_body})
            if globals().get("system2_capture_model"):
                system2_capture_model(messages, options, model, purpose)
            response = await client.post(
                f"{OLLAMA_URL}/api/chat",
                json=wire_body,
            )
            response.raise_for_status()
            result = response.json()
            if globals().get("system2_current_work"):
                _s2_work = system2_current_work()
                if _s2_work and _s2_work.get("calls"):
                    _s2_work["calls"][-1].update(response=copy.deepcopy(result), finished=time.time())
            return result
    finally:
        _OLLAMA_JOBS.pop(identity, None)


async def generate_answer(
    incoming_messages: list[dict[str, Any]],
    requested_model: str | None = None,
    requested_max_tokens: int | None = None,
) -> tuple[str, dict[str, Any]]:
    settings = load_settings()
    user_text = latest_user_text(incoming_messages)

    if not user_text:
        raise HTTPException(
            status_code=400,
            detail="No user message was supplied.",
        )

    prompt_entry = settings["prompts"][settings["active_prompt"]]
    # Applies to what the client sent us, not only to our own stitching.
    incoming_messages = drop_stale_history(
        incoming_messages, prompt_entry["name"])

    feature_meta = {
        "web_search_used": False,
        "weather_used": False,
        "tv_lookup_used": False,
        "game_lookup_used": False,
        "gear_manual_used": False,
        "gear_device": "",
        "library_used": False,      # #1158
        "library_docs": [],
        "from_library": False,
        "system_status_used": False,
        "image_requested": False,
        "video_requested": False,
        "tune_requested": False,
        "openwebui_used": False,
        "memory_used": False,
        "memory_saved": False,
        # Present on EVERY return path (#476) — the early returns (image,
        # video, tune, music) skip the tail where this used to be added, so
        # chat_completions' metadata["active_prompt"] would KeyError.
        "active_prompt": (settings.get("prompts") or [{}])[
            settings.get("active_prompt", 0)
            % max(1, len(settings.get("prompts") or [1]))].get("name", ""),
    }

    # Explicit "open web ui ..." routes the question to Open WebUI and returns.
    if is_openwebui_request(user_text):
        ow_model = requested_model or settings["model"]
        answer = await ask_openwebui(user_text, ow_model)
        feature_meta["openwebui_used"] = True
        return answer, {
            **feature_meta,
            "active_prompt": prompt_entry["name"],
            "model": ow_model,
            "prompt_tokens": 0,
            "completion_tokens": 0,
        }

    # #827: the rescue words. "Where is the radio station?" IS the
    # order: run the whole tree, fix everything fixable, and call the
    # verdict on this same speaker. The answer returns immediately; the
    # work rides behind it, and the tree itself resumes the show, climbs
    # the link ladder, revives engines and routes around a dark device.
    if is_radio_rescue(user_text):
        async def _rescue() -> None:
            try:
                got = await _deep_repair("spoken rescue (#827)")
                if got.get("busy"):
                    line = ("a repair is already running — give it a "
                            "minute and ask again")
                else:
                    verdict = str(_REPAIR_LIVE.get("verdict") or "done")
                    fixes = [s for s in (_REPAIR_LIVE.get("steps") or [])
                             if s.get("did")]
                    line = verdict if not fixes else (
                        verdict + " — " + "; ".join(
                            f"{s['name']}: {s['did']}"
                            for s in fixes[:4]))
                await home_assistant_say(line[:400], plain=True)
            except Exception:  # noqa: BLE001
                pass
        fire_and_forget(_rescue())
        feature_meta["system_status_used"] = True
        return ("On it. Running the full triage — the show, Home "
                "Assistant, the satellite, the music player, the wire, "
                "the voice director and both engines — and fixing every "
                "branch that needs it. The verdict follows on this "
                "speaker in a moment."), {
            **feature_meta,
            "active_prompt": prompt_entry["name"],
            "model": "triage",
            "prompt_tokens": 0,
            "completion_tokens": 0,
        }

    # #827: "play the music and the DJs out of the device" — a routing
    # order in plain words. 'both' keeps the page alive alongside the
    # box, so nothing the operator was hearing goes away.
    if is_play_on_device(user_text):
        _RADIO["music_to"] = "both"
        _RADIO["voice_to"] = "both"
        _routing_save()
        _operator_routing_stamp({"music": "both", "voice": "both"})
        fire_and_forget(box_route_wake())
        feature_meta["system_status_used"] = True
        return ("Done — the music and the DJs now play out of the box "
                "as well as the page."), {
            **feature_meta,
            "active_prompt": prompt_entry["name"],
            "model": "routing",
            "prompt_tokens": 0,
            "completion_tokens": 0,
        }

    # #1025: "save out the last five minutes of rhetoric" / "export
    # directory is ..." - a spoken export order. #1027: a standing
    # instruction about the station's behaviour. #1026: "show me the
    # sidekick manual" - a display order. All three are COMMANDS, each
    # gated on an imperative shape and the #1154 residue rule, and they
    # outrank every detector below - the memory road included, because
    # "remember that I like more callers" is an order to the station, not
    # a fact for the agent to file.
    export_cmd = parse_export_command(user_text)
    directive_cmd = None if export_cmd else parse_directive(user_text)
    manual_cmd = (None if (export_cmd or directive_cmd
                           or not settings.get("gear_manuals", True))
                  else te_manual_intent(user_text))
    _s5_cmd = bool(export_cmd or directive_cmd or manual_cmd)

    memory_command = (
        is_memory_command(user_text)
        if settings.get("long_term_memory", True) and not _s5_cmd
        else None
    )

    system_used = ((not memory_command) and not _s5_cmd
                   and is_system_query(user_text))
    # #1153: "restart <service>" is a COMMAND - it outranks every status
    # question, including the comfy one ("restart comfyui" must act, not
    # diagnose). And "how are the services doing" is the census question.
    service_command_name = ("" if memory_command
                            else parse_service_command(user_text))
    # #1153b: "broadcast to the Nabu" / "broadcast locally to the app" -
    # the routing selectors, spoken. A command, so it outranks status.
    broadcast_cmd = (None if (memory_command or service_command_name)
                     else parse_broadcast_command(user_text))
    # #1019: "print the paper" / "read me the front page" - the Gazette,
    # by name. A command, so it outranks the tune, video and image roads
    # below ("make a newspaper" is not a render request).
    paper_cmd = ("" if (memory_command or service_command_name
                        or broadcast_cmd)
                 else parse_paper_command(user_text))
    services_query = (
        not memory_command
        and not system_used
        and not service_command_name
        and not _s5_cmd                          # #1025/#1026/#1027
        and is_services_query(user_text)
    )
    # #1152: "what's going on with ComfyUI" outranks "render an image" -
    # a question about the engine must never be handed TO the engine.
    comfy_status = (
        not memory_command
        and not system_used
        and not service_command_name
        and not services_query
        and not _s5_cmd                          # #1025/#1026/#1027
        and is_comfy_status_query(user_text)
    )
    tune_requested = (
        not is_music_request(user_text)
        and not _s5_cmd                          # #1025/#1026/#1027
        and
        not memory_command and not system_used and not comfy_status
        and is_tune_request(user_text)
    )
    video_requested = (
        not memory_command
        and not system_used
        and not comfy_status
        and not tune_requested
        and is_video_request(user_text)
    )
    image_requested = (
        not memory_command
        and not system_used
        and not comfy_status
        and not tune_requested
        and not video_requested
        and is_image_request(user_text)
    )
    weather_used = (
        not memory_command
        and not system_used
        and not tune_requested
        and not video_requested
        and not image_requested
        and is_weather_query(user_text)
    )
    # While the show is on, "request X" is aimed at the DJ, not at the box.
    dj_used = (
        not memory_command
        and not system_used
        and not _s5_cmd                          # #1025/#1026/#1027
        and is_dj_request(user_text)
    )
    # Anything that sounds like asking for a song, that the library can
    # actually fill. DJ_REQUEST above misses "request X" and "I want to hear
    # X" outright, which is most of how a request gets phrased — so typing one
    # into the panel went nowhere while saying it to the box worked (#187).
    # Off air it still wants the station named, so "play X" keeps behaving
    # like "play X" rather than starting a whole show.
    station_request = (
        not memory_command
        and not system_used
        and not _s5_cmd                          # #1025/#1026/#1027
        and bool(DJ_ASKED.search(user_text or ""))
        and (bool(_RADIO["on"]) or bool(re.search(
            r"\b(pine ?box ?fm|the (station|radio|dj)|dj)\b",
            user_text or "", re.I)))
        and dj_request_match(dj_request_terms(user_text)) is not None
    )
    # "play <thing>" that the library can satisfy beats the YouTube path —
    # your own files should win over a music video of the same song.
    music_used = (
        not station_request
        and not dj_used
        and not memory_command
        and not system_used
        and not _s5_cmd                          # #1025/#1026/#1027
        and is_music_request(user_text)
    )
    # A named song beats every other lookup: the crystal is already local
    # and nobody asks about "Square One" hoping for a gear manual.
    song_used = (
        not music_used
        and not memory_command
        and not system_used
        and not tune_requested
        and not video_requested
        and not image_requested
        and not weather_used
        and is_song_query(user_text)
    )
    # #1158: ...unless the question names a document on the shelf outright.
    library_named = library_named_document(user_text)
    te_used = (
        not memory_command
        and not system_used
        and not tune_requested
        and not video_requested
        and not image_requested
        and not weather_used
        and not song_used
        and settings.get("gear_manuals", True)
        and not library_named
        and is_te_query(user_text)
    )
    # #1158: the shelf. After the gear manuals by design - an OP-XY question
    # keeps answering exactly the way it always has - and before the web,
    # because the box should read its own documents before it reaches out.
    library_used = (
        not memory_command
        and not system_used
        and not tune_requested
        and not video_requested
        and not image_requested
        and not weather_used
        and not song_used
        and not te_used
        and (bool(library_named) or is_library_query(user_text))
    )
    # One named episode goes to the discussion threads; anything vaguer about
    # the show goes down the ordinary TV path.
    episode_used = (
        not memory_command
        and not system_used
        and not tune_requested
        and not video_requested
        and not image_requested
        and not weather_used
        and not song_used
        and not te_used
        and not library_used
        and settings["web_search"]
        and is_episode_talk(user_text)
    )
    tv_used = (
        not memory_command
        and not system_used
        and not tune_requested
        and not video_requested
        and not image_requested
        and not weather_used
        and not song_used
        and not te_used
        and not library_used
        and not episode_used
        and settings["web_search"]
        and is_tv_query(user_text)
    )
    game_used = (
        not memory_command
        and not system_used
        and not tune_requested
        and not video_requested
        and not image_requested
        and not weather_used
        and not song_used
        and not te_used
        and not library_used
        and not episode_used
        and not tv_used
        and settings.get("game_search", True)
        and (is_game_query(user_text) or is_research_query(user_text))
    )
    search_used = (
        not memory_command
        and not system_used
        and not tune_requested
        and not video_requested
        and not image_requested
        and not weather_used
        and not song_used
        and not te_used
        and not library_used
        and not episode_used
        and not tv_used
        and not game_used
        and settings["web_search"]
        and needs_web_search(user_text)
    )

    messages: list[dict[str, str]] = [
        {
            "role": "system",
            "content": prompt_entry["prompt"],
        }
    ]

    # Long-term memories are available to every answer when enabled.
    if settings.get("long_term_memory", True):
        memories = read_memories()
        if memories:
            feature_meta["memory_used"] = True
            messages.append(
                {"role": "system", "content": format_memory_context(memories)}
            )

    # Short-term: stitch in recent conversation when the client sends no history.
    if settings.get("conversation_memory", True) and not has_client_history(
        incoming_messages
    ):
        recent = read_history(limit=MEMORY_TURNS)
        # A prompt switch is a clean slate: replies made under another
        # personality would drown out the new one (#79).
        recent = [
            t for t in recent
            if t.get("prompt") in (None, prompt_entry["name"])
        ]
        if recent:
            messages.append(
                {
                    "role": "system",
                    "content": format_recent_conversation(recent),
                }
            )
            messages.append(
                {
                    "role": "system",
                    "content": (
                        "The current system prompt is authoritative and may "
                        "have just been edited — follow it, not the style of "
                        "earlier replies. Do not reuse stage directions, "
                        "catchphrases or mannerisms that already appear in "
                        "the recent conversation (no repeating the same "
                        "actions, like lighting a cigarette, reply after "
                        "reply). Vary your delivery so each reply feels "
                        "fresh."  # 75/#79
                    ),
                }
            )

    # Votes steer style: downvoted phrasings are banned, upvoted are liked (#76).
    fb = read_feedback()
    if fb:
        downs = [
            f["text"] for f in fb if f.get("vote") == "down" and f.get("text")
        ][-8:]
        ups = [
            f["text"] for f in fb if f.get("vote") == "up" and f.get("text")
        ][-5:]
        parts = []
        if downs:
            parts.append(
                "The user DOWNVOTED these earlier replies — never repeat "
                "their style, phrasing or clichés:\n"
                + "\n".join("- " + d[:200] for d in downs)
            )
        if ups:
            parts.append(
                "The user UPVOTED these replies — build on what works "
                "without copying them:\n"
                + "\n".join("- " + u[:200] for u in ups)
            )
        if parts:
            messages.append(
                {"role": "system", "content": "\n\n".join(parts)}
            )

    if memory_command:
        save_memory(memory_command)
        feature_meta["memory_saved"] = True
        messages.append(
            {
                "role": "system",
                "content": (
                    f"You just saved this to long-term memory: '{memory_command}'. "
                    "Briefly confirm to the user that you'll remember it."
                ),
            }
        )
    elif export_cmd:
        # #1025: say where it goes, cut it behind the reply (#1153 pattern).
        feature_meta["export_command"] = True
        said = await export_command_run(export_cmd, settings)
        return said, {**feature_meta, "model": "cutter"}
    elif directive_cmd:
        # #1027: a standing order in the operator's words - written into
        # the policy file, moved on the dial when it names a road and a
        # direction, and heard by every writing prompt from here.
        feature_meta["directive"] = True
        said = directive_record(directive_cmd, source="spoken")
        return said, {**feature_meta, "model": "orchestrator"}
    elif manual_cmd:
        # #1026: the pages go to the feed (the panel's strip, beacon and
        # doc browser pick them up within a poll); the reply names them.
        feature_meta["gear_manual_used"] = True
        feature_meta["gear_device"] = manual_cmd["slug"]
        feature_meta["gear_icon"] = te_has_icon(manual_cmd["slug"])
        te_feed_push(user_text, manual_cmd)
        return te_manual_words(manual_cmd), {**feature_meta,
                                             "model": "library"}
    elif system_used:
        feature_meta["system_status_used"] = True
        # #1149: system_stats() shells out to nvidia-smi - off the loop,
        # like the pinebox status road already does (the stall hunter
        # caught this frame holding healthz).
        messages.append(
            {"role": "system", "content": format_system_context(
                await asyncio.to_thread(system_stats))}
        )
    elif paper_cmd == "print":
        # #1019: press an extra, say so, done. The press runs in the
        # background; the 📰 on the panel lights while it is on.
        feature_meta["paper_command"] = True
        _already = bool(_PAPER.get("running"))
        if not _already:
            fire_and_forget(paper_print(reason="the operator asked",
                                        kind="extra"))
        return (("The press is already running - give it a minute, then "
                 "ask me to read the front page." if _already else
                 "Printing an extra edition of the Gazette now, on the last "
                 "hour of the show. Give the desks a minute or two, then open "
                 "the paper on the panel or ask me to read the front page."),
                {**feature_meta, "model": "gazette"})
    elif paper_cmd == "read":
        feature_meta["paper_command"] = True
        _front = paper_front_words()
        return ((_front or "There is no edition on the shelf yet. Say print "
                 "the paper and I will press one."),
                {**feature_meta, "model": "gazette"})
    elif tune_requested:
        feature_meta["tune_requested"] = True
        messages.append(
            {"role": "system", "content": await play_tune(user_text)}
        )
    elif video_requested:
        feature_meta["video_requested"] = True
        # While the show is on Ollama is saturated by the DJ system, so a
        # readback through the model can take minutes (#476). The render is
        # already queued — return a finished line directly instead of waiting.
        if _RADIO.get("on") or _OLLAMA_GATE.locked():
            reply = await comfyui_generate(user_text, settings, kind="video",
                                           direct=True)
            return reply, {**feature_meta, "model": "comfyui"}
        outcome = await comfyui_generate(user_text, settings, kind="video")
        messages.append({"role": "system", "content": outcome})
    elif service_command_name:
        # #1153: a spoken wrench. Do it, say what was done, done.
        feature_meta["service_command"] = True
        did, said = await steward_restart_one(service_command_name)
        _steward_say(f"spoken command: {said}")
        return ((said + (" — give it a moment and ask me how the "
                         "services are doing to confirm.") if did
                 else said),
                {**feature_meta, "model": "steward"})
    elif broadcast_cmd:
        # #1153b: drive the very door the panel's selectors use, so
        # every side effect rides along - the record moves NOW, the
        # page feed clears on a hand-to-box, the box wakes.
        feature_meta["broadcast_command"] = True
        _said = str(broadcast_cmd.pop("_said", "the broadcast moved"))
        try:
            async with httpx.AsyncClient(timeout=20) as _c:
                _r = await _c.post(
                    f"http://127.0.0.1:{STATION_PORT}/api/dj/output",
                    json=broadcast_cmd,
                    headers={"Authorization":
                             f"Bearer {SPARK_AGENT_API_KEY}"})
                _r.raise_for_status()
            pipeline_log("air", f"spoken routing: {_said} (#1153b)")
            return (f"Done — {_said}. The switch is immediate; the "
                    "current record and the next lines follow it.",
                    {**feature_meta, "model": "steward"})
        except Exception as exc:  # noqa: BLE001
            return (f"The routing door refused that: {exc}",
                    {**feature_meta, "model": "steward"})
    elif services_query:
        # #1153: the census, taken live, answered in plain words - and if
        # anything is sick the steward starts repairs before the reply
        # is even spoken.
        feature_meta["services_query"] = True
        census = await services_census()
        text, sick = services_text(census)
        fixable = [s for s in sick if service_has_wrench(s)]
        handless = [s for s in sick if not service_has_wrench(s)]
        if fixable:
            fire_and_forget(service_steward(
                reason="the operator asked after the services", fix=True))
        messages.append({"role": "system", "content": (
            "The user asked how the services are doing. A live census "
            "was just taken across the whole DGX Spark stack:\n\n" + text
            + "\n\n"
            + ("Every service is answering. Tell the user plainly that "
               "everything is running fine, with a highlight or two "
               "(the LLM, search, voices, images)."
               if not sick else
               ((("The down ones with a wired wrench ("
                  + ", ".join(SERVICE_LABELS.get(s, s) for s in fixable)
                  + ") are being repaired RIGHT NOW - the steward has "
                  "already begun restarts in the background, and its "
                  "console on the panel (🏥 Services) shows every step "
                  "live; suggest asking again in a minute. ")
                 if fixable else "")
                + (("These need a hand on the host and cannot be "
                    "restarted from here: "
                    + ", ".join(SERVICE_LABELS.get(s, s)
                                for s in handless)
                    + " - say so honestly. ")
                   if handless else "")))
            + " Keep it brief and spoken.")})
    elif comfy_status:
        # #1152: fire the full troubleshooter in the background, answer
        # NOW with what a live knock found, and point at the console.
        feature_meta["comfy_doctor"] = True
        fire_and_forget(comfy_doctor(reason="the operator asked"))
        probe = await _comfy_system_stats()
        state_line = (
            "answering right now (ComfyUI "
            + str((_summarize_system_stats(probe) or {}).get(
                "comfyui_version") or "?") + ")"
            if probe else "NOT answering - it is down")
        messages.append({"role": "system", "content": (
            "The user asked what is going on with ComfyUI, the image "
            f"engine. A live probe this second found it {state_line} at "
            f"{COMFYUI_URL}. The comprehensive troubleshooter is already "
            "running in the background: it knocks on the engine, reads "
            "its memory and queue, and if it is down it restarts the "
            "service through the host bridge and waits out the cold "
            "start, then verifies with a test render. Every step it "
            "takes is streaming live to the Comfy Doctor console on the "
            "Pine Box panel (the \U0001fa7a card - it opens itself while "
            "the doctor works). Tell the user what the probe found and "
            "that the doctor is on it; brief and spoken.")})
    elif image_requested:
        feature_meta["image_requested"] = True
        if _RADIO.get("on") or _OLLAMA_GATE.locked():
            reply = await comfyui_generate(user_text, settings, direct=True)
            return reply, {**feature_meta, "model": "comfyui"}
        outcome = await comfyui_generate(user_text, settings)
        messages.append({"role": "system", "content": outcome})
    elif weather_used:
        feature_meta["weather_used"] = True
        play_search_sound()
        try:
            weather_context = await get_weather_context(user_text)
        except Exception as exc:
            weather_context = (
                "The live weather lookup failed. Tell the user weather "
                f"information is temporarily unavailable. Error: {exc}"
            )
        messages.append({"role": "system", "content": weather_context})
    elif dj_used or station_request:
        feature_meta["dj_request"] = True
        # The station gets first refusal, the same way it does for anything
        # said out loud to the box. It matches generously, starts the show if
        # it is off and cuts straight to the track. This path was wired into
        # the voice pipeline only, so a request typed into the panel fell
        # through to the strict matcher and went nowhere (#187).
        taken = await dj_take_request(user_text)
        if taken:
            return taken["reply"], {**feature_meta, "model": "station"}
        query = dj_request_query(user_text)
        now = bool(re.search(r"\b(now|immediately|right away|next)\b",
                             user_text, re.I))
        result = await dj_request(query, now=now)
        if not result.get("ok"):
            return result["detail"], {**feature_meta,
                                      "model": settings["model"]}
        who = f" by {result['artist']}" if result.get("artist") else ""
        where = "playing next" if now else "in the queue"
        return (
            f"Request taken — {result['title']}{who} is {where} on "
            f"{dj_settings()['station_name']}."
        ), {**feature_meta, "model": settings["model"]}
    elif music_used:
        feature_meta["music_played"] = True
        try:
            spoken = await play_music_request(user_text)
        except Exception as exc:
            spoken = f"Could not play that — {exc}"
        return spoken, {**feature_meta, "model": settings["model"]}
    elif song_used:
        crystal = crystal_match(user_text)
        feature_meta["crystal_used"] = True
        feature_meta["crystal"] = (crystal or {}).get("slug", "library")
        messages.append({
            "role": "system",
            "content": (
                format_crystal_context(crystal, user_text) if crystal
                else format_crystal_library(user_text)
            ),
        })
    elif te_used:
        hit = te_lookup(user_text)
        if hit:
            feature_meta["gear_manual_used"] = True
            feature_meta["gear_device"] = hit["slug"]
            feature_meta["gear_icon"] = te_has_icon(hit["slug"])
            # "how do I…" wants to watch someone do it, not read about it.
            if TE_SHOW_ME.search(user_text) and settings["web_search"]:
                videos = await te_media(hit, user_text)
                if videos:
                    feature_meta["gear_videos"] = videos
                    hit = {**hit, "videos": videos}
            te_feed_push(user_text, hit)
            messages.append(
                {"role": "system", "content": format_te_context(hit)}
            )
            # Manuals document controls; tricks are community knowledge.
            if TE_TIPS.search(user_text) and settings["web_search"]:
                feature_meta["web_search_used"] = True
                play_search_sound()
                try:
                    results = await search_searxng(
                        f"{hit['title']} {clean_search_query(user_text)}"
                    )
                    if results:
                        messages.append(
                            {
                                "role": "system",
                                "content": format_search_context(
                                    user_text, results
                                ),
                            }
                        )
                except Exception:
                    pass  # The manual pages alone still answer the question.
        else:
            # Device recognised but nothing cached. #1158: ask the shelf
            # before the web - the operator's own documents are already on
            # this machine, and one of them may well be the guide for it.
            te_used = False
            shelf = await library_lookup(user_text) if library_on() else []
            if shelf:
                feature_meta["library_used"] = True
                feature_meta["library_docs"] = library_credits(shelf)
                messages.append({"role": "system",
                                 "content": format_library_context(shelf)})
            else:
                feature_meta["web_search_used"] = True
                play_search_sound()
                try:
                    results = await search_searxng(
                        clean_search_query(user_text))
                    context = format_search_context(user_text, results)
                except Exception as exc:
                    context = (
                        "The web search service failed. Tell the user gear "
                        f"documentation is temporarily unavailable. "
                        f"Error: {exc}"
                    )
                messages.append({"role": "system", "content": context})
    elif library_used:
        # #1158: the operator's own shelf. It answers or it says nothing -
        # a passage under the measured floor is not an answer, it is the
        # nearest thing on a shelf that had nothing.
        shelf = await library_lookup(user_text)
        if shelf:
            feature_meta["library_used"] = True
            feature_meta["library_docs"] = library_credits(shelf)
            messages.append({"role": "system",
                             "content": format_library_context(shelf)})
        elif settings["web_search"] and needs_web_search(user_text):
            feature_meta["web_search_used"] = True
            play_search_sound()
            try:
                results = await search_searxng(clean_search_query(user_text))
                messages.append({
                    "role": "system",
                    "content": format_search_context(user_text, results)})
            except Exception:  # noqa: BLE001
                pass       # no shelf and no web is still an honest answer
    elif episode_used:
        feature_meta["episode_talk_used"] = True
        play_search_sound()
        try:
            episode_context = await get_episode_context(user_text)
        except Exception as exc:
            episode_context = (
                "The episode discussion lookup failed. Tell the user you "
                "could not reach the discussion threads. Error: "
                f"{exc}"
            )
        messages.append({"role": "system", "content": episode_context})
    elif tv_used:
        feature_meta["tv_lookup_used"] = True
        play_search_sound()
        try:
            tv_context = await get_tv_context(user_text)
        except Exception as exc:
            tv_context = (
                "The TV show lookup failed. Tell the user TV show info is "
                f"temporarily unavailable. Technical error: {exc}"
            )
        messages.append({"role": "system", "content": tv_context})
    elif game_used:
        try:
            game_context, game_flags = await get_game_context(user_text)
            feature_meta["game_lookup_used"] = game_flags["game_lookup_used"]
            feature_meta["from_library"] = game_flags["from_library"]
        except Exception as exc:
            game_context = (
                "The game lookup service failed. Tell the user game help is "
                f"temporarily unavailable. Technical error: {exc}"
            )

        messages.append(
            {
                "role": "system",
                "content": game_context,
            }
        )
    elif search_used:
        feature_meta["web_search_used"] = True
        play_search_sound()
        query = clean_search_query(user_text)

        try:
            search_results = await search_searxng(query)
            search_context = format_search_context(
                query,
                search_results,
            )
        except Exception as exc:
            search_context = (
                "The web search service failed. Tell the user search is "
                f"temporarily unavailable. Technical error: {exc}"
            )

        messages.append(
            {
                "role": "system",
                "content": search_context,
            }
        )

    # Ignore incoming system messages. The control-panel prompt is authoritative.
    for message in incoming_messages:
        role = message.get("role")
        content = message.get("content")

        if role not in {"user", "assistant"}:
            continue

        if not isinstance(content, str) or not content.strip():
            continue

        messages.append(
            {
                "role": role,
                "content": content.strip(),
            }
        )

    model = requested_model or settings["model"]
    max_tokens = requested_max_tokens or settings["max_tokens"]
    max_tokens = max(20, min(1000, int(max_tokens)))

    t0 = time.monotonic()
    try:
        result = await call_ollama(
            model=model,
            messages=messages,
            temperature=settings["temperature"],
            max_tokens=max_tokens,
            top_p=settings["top_p"],
            num_ctx=settings["num_ctx"],
        )
    except httpx.HTTPStatusError as exc:
        raise HTTPException(
            status_code=502,
            detail={
                "message": "Ollama rejected the request.",
                "status": exc.response.status_code,
                "response": exc.response.text[:1500],
            },
        ) from exc
    except (httpx.RequestError, ValueError) as exc:
        raise HTTPException(
            status_code=502,
            detail=f"Could not obtain an Ollama response: {exc}",
        ) from exc

    answer = result.get("message", {}).get("content")

    if not isinstance(answer, str) or not answer.strip():
        raise HTTPException(
            status_code=502,
            detail="Ollama returned an empty response.",
        )

    metadata = {
        **feature_meta,
        "active_prompt": prompt_entry["name"],
        "model": model,
        "prompt_tokens": int(result.get("prompt_eval_count") or 0),
        "completion_tokens": int(result.get("eval_count") or 0),
        # Per-reply analytics for the conversation popup (#78).
        "stats": {
            "duration_ms": int((time.monotonic() - t0) * 1000),
            "load_ms": int((result.get("load_duration") or 0) / 1e6),
            "prompt_eval_ms": int(
                (result.get("prompt_eval_duration") or 0) / 1e6
            ),
            "eval_ms": int((result.get("eval_duration") or 0) / 1e6),
            "prompt_tokens": int(result.get("prompt_eval_count") or 0),
            "completion_tokens": int(result.get("eval_count") or 0),
        },
    }

    return answer.strip(), metadata


