@app.post("/api/voicelab/upload")
async def voicelab_upload(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Same lab, local file: the raw body is the media."""
    require_auth(authorization)
    blob = await request.body()
    if len(blob) < 32000:
        raise HTTPException(status_code=400, detail="Too little audio")
    name = str(request.query_params.get("name") or "")
    mode = str(request.query_params.get("mode") or "both")
    filename = str(request.query_params.get("filename") or "upload.bin")
    try:
        async with httpx.AsyncClient(timeout=120) as client:
            got = await client.post(
                f"{VOICE_LAB_URL}/ingest",
                params={"filename": filename, "mode": mode},
                content=blob,
                headers={"Content-Type": "application/octet-stream"},
            )
            got.raise_for_status()
    except HTTPException:
        raise
    except Exception as exc:
        raise HTTPException(
            status_code=503,
            detail="voice-lab is down — is the voice-lab container "
                   "running? (docker compose up -d voice-lab)",
        ) from exc
    job_id = str((got.json() or {}).get("job_id") or "")
    with _VOICE_JOBS_LOCK:
        _VOICE_JOBS[job_id] = {"name": name, "caller_id": "",
                               "range": "", "started": time.time()}
    return {"job_id": job_id}


@app.post("/api/voicelab/chapters")
async def voicelab_chapters(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Chapters inside a library file (#287) — an audiobook's table of
    contents, parsed straight out of ffmpeg's banner. Best effort: a file
    without chapter atoms just returns none."""
    require_auth(authorization)
    payload = await request.json()
    track = music_track(str(payload.get("id") or ""))
    if not track:
        raise HTTPException(status_code=404, detail="No such track")

    def probe() -> list[dict[str, Any]]:
        import subprocess
        import imageio_ffmpeg
        exe = imageio_ffmpeg.get_ffmpeg_exe()
        run = subprocess.run(
            [exe, "-nostdin", "-hide_banner", "-i", str(track["path"])],
            capture_output=True, timeout=60)
        text = run.stderr.decode(errors="ignore")
        chapters: list[dict[str, Any]] = []
        pending: dict[str, Any] | None = None
        for line in text.splitlines():
            started = re.search(
                r"Chapter #[\d:.]+: start ([\d.]+), end ([\d.]+)", line)
            if started:
                pending = {"start": float(started.group(1)),
                           "end": float(started.group(2)), "title": ""}
                chapters.append(pending)
            elif pending is not None and not pending["title"]:
                titled = re.search(r"title\s*:\s*(.+)", line)
                if titled:
                    pending["title"] = titled.group(1).strip()[:80]
        return chapters[:200]

    try:
        chapters = await asyncio.to_thread(probe)
    except Exception:
        chapters = []
    return {"chapters": chapters, "title": track.get("title") or "",
            "artist": track.get("artist") or ""}


@app.post("/api/voicelab/from_track")
async def voicelab_from_track(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """A voice out of the music shelf (#287): any track or audiobook in
    the library takes the same lab road as an upload — optionally just a
    chapter of it. DRM'd Audible .aax needs AUDIBLE_ACTIVATION_BYTES in
    the voice-lab environment; DRM-free files just work."""
    require_auth(authorization)
    payload = await request.json()
    track = music_track(str(payload.get("id") or ""))
    if not track:
        raise HTTPException(status_code=404, detail="No such track")
    path = Path(track["path"])
    name = str(payload.get("name") or track.get("title")
               or path.stem)[:80]
    blob = await asyncio.to_thread(path.read_bytes)
    params: dict[str, str] = {"filename": path.name, "mode": "both"}
    for key in ("start", "end"):
        if payload.get(key):
            params[key] = str(payload[key])
    if payload.get("speaker"):
        params["speaker"] = str(payload["speaker"])
    try:
        async with httpx.AsyncClient(timeout=600) as client:
            got = await client.post(
                f"{VOICE_LAB_URL}/ingest", params=params, content=blob,
                headers={"Content-Type": "application/octet-stream"})
            got.raise_for_status()
    except Exception as exc:
        raise HTTPException(
            status_code=503,
            detail="voice-lab is down — is the voice-lab container "
                   "running? (docker compose up -d voice-lab)",
        ) from exc
    job_id = str((got.json() or {}).get("job_id") or "")
    with _VOICE_JOBS_LOCK:
        _VOICE_JOBS[job_id] = {"name": name, "caller_id": "", "range": "",
                               "started": time.time()}
    return {"job_id": job_id, "name": name}


@app.get("/api/voicelab/jobs/{job_id}")
async def voicelab_job(
    job_id: str,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Proxy the lab's status — and the moment a job reads done, harvest
    it into the voice library right here on the poll."""
    require_read_auth(authorization)
    if not VOICE_JOB_SHAPE.match(job_id):
        raise HTTPException(status_code=404, detail="No such job")
    with _VOICE_JOBS_LOCK:
        entry = dict(_VOICE_JOBS.get(job_id) or {})
    if entry.get("harvested"):
        # The remote job is already deleted; answer from what we kept.
        return {"stage": "done", "progress": 1.0, "harvested": True,
                "voice_id": entry.get("voice_id") or "",
                "caller_id": entry.get("caller_id") or ""}
    try:
        async with httpx.AsyncClient(timeout=15) as client:
            got = await client.get(f"{VOICE_LAB_URL}/jobs/{job_id}")
    except Exception as exc:
        raise HTTPException(status_code=503,
                            detail=f"voice-lab unreachable — {exc}") from exc
    if got.status_code != 200:
        # The lab keeps jobs in memory, so a restart loses them while the
        # panel is still watching. That is a different thing from a job
        # that never existed, and it deserves a different answer (#640).
        if entry:
            return {"stage": "error", "progress": 0.0, "harvested": False,
                    "error_kind": "LAB_RESTARTED",
                    "error": "The lab restarted while this was running — "
                             "paste the link again and it will start fresh.",
                    "voice_id": "", "caller_id": entry.get("caller_id") or ""}
        raise HTTPException(status_code=404, detail="No such job")
    status = got.json() or {}
    if status.get("stage") == "done":
        await _voicelab_harvest(job_id, status)
        with _VOICE_JOBS_LOCK:
            entry = dict(_VOICE_JOBS.get(job_id) or {})
    return {
        **status,
        "harvested": bool(entry.get("harvested")),
        "harvest_error": entry.get("harvest_error") or "",
        "voice_id": entry.get("voice_id") or "",
        "caller_id": entry.get("caller_id") or "",
    }


@app.post("/api/dj/callers/{caller_id}/internalize")
async def dj_caller_internalize(
    caller_id: str,
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Feed a caller a video of a real voice: the lab extracts the voice
    and its manner, the source is deleted, and from then on they ring in
    sounding like it — 🧬 instead of 📞 on the popup."""
    require_auth(authorization)
    rows = read_callers()
    caller = next((r for r in rows if r.get("id") == caller_id), None)
    if not caller:
        raise HTTPException(status_code=404, detail="No such caller")
    payload = await request.json()
    body = {
        "url": str(payload.get("url") or "").strip(),
        "start": payload.get("start") or None,
        "end": payload.get("end") or None,
        "speaker": str(payload.get("speaker") or ""),
        "mode": "both",
    }
    if not body["url"].startswith(("http://", "https://")):
        raise HTTPException(status_code=400, detail="Give me a URL")
    job_id = await _voicelab_start(
        body, name=str(caller.get("name") or ""), caller_id=caller_id)
    return {"job_id": job_id, "caller": caller.get("name")}


@app.get("/upstairs-audio/{name}")
async def upstairs_audio(
    name: str,
    request: Request,
    authorization: str | None = Header(default=None),
) -> Response:
    """Serve a stored page from upstairs (#749). Signed ?t= like every other
    durable clip, so a bare <audio> and the box can both fetch it."""
    if not UPSTAIRS_AUDIO_SHAPE.match(name):
        raise HTTPException(status_code=404, detail="No such page")
    sig = str(request.query_params.get("t") or "")
    want = media_sign(name)
    if not (want and hmac.compare_digest(sig, want)):
        require_read_auth(authorization)
    path = UPSTAIRS_AUDIO_DIR / name
    if not path.is_file():
        raise HTTPException(status_code=404, detail="No such page")
    return FileResponse(path, media_type="audio/mpeg",
                        headers={"Cache-Control": "private, max-age=3600"})


@app.get("/ads-audio/{name}")
async def ads_audio(
    name: str,
    request: Request,
    authorization: str | None = Header(default=None),
) -> Response:
    """Serve a produced ad's durable audio (#618) — signed like /media so the
    box and the page <audio> can both fetch it without a bearer header."""
    if not AD_AUDIO_SHAPE.match(name):
        return Response(status_code=404)
    signature = str(request.query_params.get("t") or "")
    expected = media_sign(name)
    if not (expected and hmac.compare_digest(signature, expected)):
        require_auth(authorization)
    try:
        blob = (PRODUCED_ADS_DIR / name).read_bytes()
    except Exception:
        return Response(status_code=404)
    headers = {
        "X-Content-Type-Options": "nosniff",
        "Accept-Ranges": "bytes",
        "Cache-Control": "private, max-age=31536000, immutable",
    }
    window = _range_slice(str(request.headers.get("range") or ""), len(blob))
    if window == (-1, -1):
        headers["Content-Range"] = f"bytes */{len(blob)}"
        return Response(status_code=416, headers=headers)
    if window:
        start, end = window
        headers["Content-Range"] = f"bytes {start}-{end}/{len(blob)}"
        return Response(blob[start:end + 1], status_code=206,
                        headers=headers, media_type="audio/mpeg")
    return Response(blob, headers=headers, media_type="audio/mpeg")


@app.get("/media/{key}/spec")
async def media_spectrogram(
    key: str,
    request: Request,
    authorization: str | None = Header(default=None),
) -> Response:
    """A little spectrogram of ONE aired line (#696).

    The booth hover card wants to show what a line LOOKED like, not just
    what it said. Rendered once per clip and cached beside the strips the
    radio-cache tooltips already use — the same signed ?t= as the audio
    itself, because an <img> can no more send a bearer header than an
    <audio> can."""
    if not MEDIA_KEY_SHAPE.match(key):
        return Response(status_code=404)
    signature = str(request.query_params.get("t") or "")
    expected = media_sign(key)
    if not (expected and hmac.compare_digest(signature, expected)):
        require_read_auth(authorization)
    src = VOICE_MEDIA_DIR / key
    if not src.is_file():
        return Response(status_code=404)
    spec_dir = RADIO_CACHE / "_spec"
    out = spec_dir / f"line_{key}.png"

    def render() -> bool:
        if out.is_file():
            return True
        try:
            import subprocess

            import imageio_ffmpeg
            spec_dir.mkdir(parents=True, exist_ok=True)
            exe = imageio_ffmpeg.get_ffmpeg_exe()
            subprocess.run(
                [exe, "-nostdin", "-hide_banner", "-loglevel", "error", "-y",
                 "-i", str(src),
                 "-lavfi", "showspectrumpic=s=340x90:legend=0:color=intensity:"
                           "scale=log:gain=3",
                 "-frames:v", "1", str(out)],
                capture_output=True, timeout=60)
            keep = sorted(spec_dir.glob("line_*.png"),
                          key=lambda p: p.stat().st_mtime)
            for old in keep[:-400]:
                old.unlink(missing_ok=True)
            return out.is_file()
        except Exception:
            return False

    if not await asyncio.to_thread(render):
        return Response(status_code=404)
    return FileResponse(out, media_type="image/png",
                        headers={"Cache-Control": "private, max-age=86400"})


# #1214: a clip small enough to answer in one body does, because the
# loop it has to cross is frozen 13.6% of the time in blocks of up to
# eight seconds (measured: 26 stalls, 81.7s, in 600s) and a chunked
# response waits in every one of them. Above this, streaming again -
# holding a 40 MB tape in memory per listener trades one fault for worse.
MEDIA_WHOLE_MAX = 12 * 1024 * 1024


async def _media_slice(path: Path, start: int, length: int) -> bytes | None:
    """`length` bytes from `start`, read OFF THE LOOP in one go.

    None when it cannot be read that way, and the caller streams instead.
    The read must stay in a thread: #883 and #999 both had to undo a
    synchronous read_bytes() on this very route, which blocked every
    listener at once. One await, in a thread, then a body."""
    if length <= 0 or length > MEDIA_WHOLE_MAX:
        return None

    def work() -> bytes:
        with path.open("rb") as handle:
            handle.seek(start)
            return handle.read(length)

    try:
        got = await asyncio.to_thread(work)
    except Exception:  # noqa: BLE001
        return None
    return got if len(got) == length else None


@app.get("/media/{key}")
async def media(
    key: str,
    request: Request,
    authorization: str | None = Header(default=None),
) -> Response:
    """Serve a generated clip. Shape-check the key before touching disk."""
    if not MEDIA_KEY_SHAPE.match(key):
        return Response(status_code=404)
    ext = key.rsplit(".", 1)[-1]
    if ext not in MEDIA_TYPES:
        return Response(status_code=404)

    # An <audio> tag sends no headers, so a signature in the query stands in
    # for the bearer token. Either one is enough; neither is optional.
    signature = str(request.query_params.get("t") or "")
    expected = media_sign(key)
    if not (expected and hmac.compare_digest(signature, expected)):
        require_auth(authorization)

    # #999: the listener's chosen rate. media_sign() HMACs the KEY ONLY,
    # and this route reads no query parameter but "t", so &br= can
    # neither alter nor invalidate the signature. Nothing about auth
    # above this line changes.
    rate = low_note_rate(request.query_params.get("br"))
    served = VOICE_MEDIA_DIR / key
    media_type = MEDIA_TYPES[ext]
    missed = False
    if rate:
        small = low_path(key, rate)
        # #1147: A MISS IS STICKY. One URL used to serve WAV bytes on the
        # miss and MP3 bytes seconds later when the encode landed - a
        # playback session spanning the flip (a Range continuation on a
        # slow link) got MP3 frames where it expected PCM: a second of
        # digital garbage. Once a (key, rate) has served the original, it
        # keeps serving the original for a while; the derivative waits
        # for the next clip.
        _mk = f"{key}|{rate}"
        _held = time.time() - float(_LOW_MISSED.get(_mk) or 0) < 900.0
        if small.is_file() and not _held:
            # nosniff is set below, so the browser believes OUR type even
            # though the key still ends .wav.
            served, media_type = small, "audio/mpeg"
        else:
            # Not ready. Start it for next time and send the original
            # NOW - a miss must cost the listener bytes, never delay.
            missed = True
            if not small.is_file():
                _low_encode_soon(VOICE_MEDIA_DIR / key, small, rate)
            # Review: a SLIDING window - refreshed on every held serve,
            # so an active session never crosses the flip moment while
            # it is still pulling bytes.
            _LOW_MISSED[_mk] = time.time()
            if len(_LOW_MISSED) > 4000:
                _now = time.time()
                for _k in [k for k, v in _LOW_MISSED.items()
                           if _now - v > 900.0]:
                    _LOW_MISSED.pop(_k, None)

    try:
        size = await asyncio.to_thread(lambda: served.stat().st_size)
    except Exception:  # noqa: BLE001
        return Response(status_code=404)

    headers = {
        "X-Content-Type-Options": "nosniff",
        "Accept-Ranges": "bytes",
        # A HIT is safe to cache forever: keys are random and never
        # overwritten, and ?br= is part of the URI an HTTP cache keys on,
        # so the wav and each mp3 are separate entries.
        #
        # #999: A MISS MUST NOT BE. On a miss this hands back the
        # original WAV under a URL that promises an mp3 - and marking
        # that `immutable, max-age=31536000` would make the miss
        # PERMANENT for that listener, caching a year of wav against the
        # very URL the encode is being prepared for.
        "Cache-Control": ("private, no-store" if missed
                          else "private, max-age=31536000, immutable"),
    }
    window = _range_slice(str(request.headers.get("range") or ""), size)
    if window == (-1, -1):
        headers["Content-Range"] = f"bytes */{size}"
        return Response(status_code=416, headers=headers)
    if window:
        # #999/#883: stream it off the disk. This route used to do
        # `blob = (VOICE_MEDIA_DIR / key).read_bytes()` - a SYNCHRONOUS
        # whole-file read inside an async def, which blocks the event
        # loop for every listener at once - and then sliced the range out
        # of memory. The music road was fixed for exactly this in #883;
        # the voice road never was.
        start, end = window
        headers["Content-Range"] = f"bytes {start}-{end}/{size}"
        headers["Content-Length"] = str(end - start + 1)
        # #1214: ONE CROSSING OF THE LOOP, NOT ONE PER CHUNK.
        blob = await _media_slice(served, start, end - start + 1)
        if blob is not None:
            return Response(content=blob, status_code=206,
                            headers=headers, media_type=media_type)
        return StreamingResponse(_range_stream(served, start, end),
                                 status_code=206, headers=headers,
                                 media_type=media_type)
    if size <= MEDIA_WHOLE_MAX:
        blob = await _media_slice(served, 0, size)
        if blob is not None:
            headers["Content-Length"] = str(len(blob))
            return Response(content=blob, headers=headers,
                            media_type=media_type)
    return FileResponse(served, media_type=media_type, headers=headers)


# #994: THE SECOND /media/{key}/spec IS GONE.
#
# It was declared twice: media_spectrogram (#696) and, here, media_spec
# (#455). Starlette matches routes in REGISTRATION order and takes the
# first hit, so #696 - declared several hundred lines earlier - served
# every request and this one had never run since the day it was added.
# Both did the same job, so nothing looked broken; the cost was that
# edits made here were edits to nothing.
#
# #696 is the one kept, and it is the better of the two on both counts
# that matter: it PRUNES its cache to the newest 400 pictures, where this
# one grew without limit, and it answers with FileResponse rather than
# reading the whole png into memory to send it.
#
# _render_spectrogram and SPEC_CACHE are NOT removed with it - the tape
# road (see _tape_spec) and the voice-sample road still use both.


def safe_key(key: str) -> str:
    return re.sub(r"[^a-z0-9-]", "", key.lower())[:120]


def crystal_with_track(
    crystal: dict[str, Any],
    stems: dict[str, dict[str, Any]] | None = None,
) -> dict[str, Any]:
    """A crystal plus the library track behind it, signed and ready to play.

    The analysis rig read a real file, so its stem beats a title search —
    same trick as tape_crystal. Signing here is what lets the panel start
    the record on the click itself, with no round trip in between (#637).
    """
    row = dict(crystal)
    stem = Path(str(crystal.get("source") or "")).stem.lower()
    track = None
    if stem:
        if stems is None:
            stems = {Path(t["path"]).stem.lower(): t for t in music_index()}
        track = stems.get(stem)
    if track is None:
        hits = music_search(
            str(crystal.get("title") or crystal.get("slug") or ""), limit=1)
        track = hits[0] if hits else None
    if track:
        row["track"] = {
            **{k: v for k, v in track.items() if k not in ("path", "search")},
            "url": f"/music/{track['id']}?t={media_sign(track['id'])}",
            "art": f"/music/{track['id']}/art?t={media_sign(track['id'])}",
        }
    return row


@app.get("/api/song-crystals")
async def song_crystals_list(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """The SongSight library, newest analysis first."""
    require_read_auth(authorization)
    crystals = sorted(
        read_crystals(), key=lambda c: str(c.get("built") or ""), reverse=True
    )
    # One stem map for the whole list, not one library walk per crystal.
    stems = {Path(t["path"]).stem.lower(): t for t in music_index()}
    rows = [crystal_with_track(c, stems) for c in crystals]
    return {"crystals": rows, "count": len(rows)}


@app.get("/api/song-crystals/{slug}")
async def crystal_get(
    slug: str,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    require_read_auth(authorization)
    path = crystal_file(slug)                                  # #998
    try:
        return crystal_with_track(json.loads(path.read_text()))
    except HTTPException:
        raise
    except Exception:
        raise HTTPException(status_code=404, detail="No such crystal")


@app.post("/api/song-crystals")
async def crystal_put(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Ingest one crystal built by tools/crystal_build.py."""
    require_auth(authorization)
    payload = await request.json()
    if not isinstance(payload, dict):
        raise HTTPException(status_code=400, detail="Send one crystal object")

    slug = safe_key(str(payload.get("slug") or ""))
    if not slug:
        raise HTTPException(status_code=400, detail="Crystal needs a slug")
    body = json.dumps(payload, indent=1)
    if len(body) > 200_000:
        raise HTTPException(status_code=413, detail="Crystal too large")

    # #998: into the topic's own folder, made on demand.
    _home = crystal_home(slug)
    _home.mkdir(parents=True, exist_ok=True)
    (_home / f"{safe_key(slug)}.json").write_text(body + "\n")
    return {"ok": True, "slug": slug, "count": len(read_crystals())}


@app.delete("/api/song-crystals/{slug}")
async def crystal_delete(
    slug: str,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    require_auth(authorization)
    # #998: wherever it actually is - nested, or still flat.
    crystal_file(slug).unlink(missing_ok=True)
    (CRYSTALS_DIR / f"{safe_key(slug)}.json").unlink(missing_ok=True)
    return {"ok": True, "count": len(read_crystals())}


