@app.post("/api/music/play")
async def music_play_api(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Play by id, or by whatever the user typed."""
    require_auth(authorization)
    payload = await request.json()
    track_id = str(payload.get("id") or "")
    track = music_track(track_id) if track_id else None
    if not track and track_id:
        # One of his tapes: playable from the album sheet and the recently
        # played list like anything else (#243).
        tape_path = await asyncio.to_thread(tape_by_id, track_id)
        if tape_path is not None:
            track = {
                "id": track_id, "title": mixtape_title(tape_path),
                "artist": "Ehm Eckx", "album": "the MX tapes",
                "seconds": await asyncio.to_thread(tape_duration, tape_path),
                "tape": True,
                "url": f"/tape/{track_id}?t={media_sign(track_id)}",
            }
            played = ("" if payload.get("here")
                      else await music_play_on_box(track))
            return {**track, "played_on": played}
    if not track:
        hits = music_search(str(payload.get("q") or ""), limit=1)
        track = hits[0] if hits else None
    if not track:
        raise HTTPException(status_code=404, detail="Nothing matches that")

    played = "" if payload.get("here") else await music_play_on_box(track)
    return {
        **{k: v for k, v in track.items() if k not in ("path", "search")},
        "url": f"/music/{track['id']}?t={media_sign(track['id'])}",
        "played_on": played,
    }


