@app.post("/api/radio/pause")
async def radio_pause_api(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """#1108: go off air without stopping the rooms.

    The FM switch stops the station and every service under it. This
    shuts only the door to the air: the writing desk, the recording room
    and the crystal keep working, and everything they make goes into the
    cupboard instead of onto the air."""
    require_auth(authorization)
    try:
        payload = await request.json()
    except Exception:  # noqa: BLE001
        payload = {}
    want = payload.get("paused")
    if want is None:
        want = not radio_paused()               # a plain toggle
    radio_pause_set(bool(want), why="the pause control (panel/API)")
    return {"paused": radio_paused(),
            "for_seconds": round(radio_paused_for(), 1),
            "banked_seconds": round(prepared_seconds(), 1),
            "say": ("off air - the booth keeps recording, and everything "
                    "it makes is banked for when you come back"
                    if radio_paused() else
                    "back on air with "
                    + str(int(prepared_seconds())) + "s standing by")}


@app.get("/api/radio/pause")
async def radio_pause_state_api(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    require_read_auth(authorization)
    return {"paused": radio_paused(),
            "for_seconds": round(radio_paused_for(), 1),
            "banked_seconds": round(prepared_seconds(), 1),
            "larder": len(_LARDER)}


@app.post("/api/radio/unpause")
async def radio_unpause_listener_api(
    t: str = "",
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """#1149: an inert station is not a dead end for a guest.

    Anyone holding a live tune-in link who arrives at a PAUSED broadcast
    can set it playing again - the whole resume road (schedule restore,
    cut_ms stamp, needle drop) runs exactly as if the operator pressed
    the button. Deliberately one-way: a listener can only ever wake the
    station, never silence it, and the FM switch stays the operator's.
    On the public door this rides the allowlist like shout and vote."""
    require_listen_auth(t, authorization)
    was = radio_paused()
    if was:
        radio_pause_set(False, why="a tune-in listener pressed play")
        pipeline_log("air", "unpaused from a tune-in link - a listener "
                            "pressed play on an idle station")
    return {"paused": radio_paused(), "was_paused": was,
            "on": bool(_RADIO.get("on")),
            "say": ("the record is dropping - the booth banked material "
                    "through the pause, so there is something to say"
                    if was else "the broadcast was already rolling")}


@app.post("/api/radio/tune")
async def radio_tune_api(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    require_auth(authorization)
    payload = await request.json()
    station = str(payload.get("station") or "all")
    # Pine Box FM outranks the plain radio. Tune in while the show is live
    # and you join the broadcast; you do not restart it, and the plain
    # radio's stop does not take it off the air. Only the power switch ends
    # the show (#197, #230) — pressing Tune used to kill it stone dead.
    if _RADIO.get("on"):
        if payload.get("stop"):
            return {**radio_state(), "joined": True,
                    "note": "Pine Box FM stays on — use its power switch"}
        return {**dj_state(), "joined": True}
    if payload.get("stop"):
        radio_stop()
        return radio_state()
    known = {s["id"] for s in music_stations()}
    if station not in known:
        raise HTTPException(status_code=400, detail="No such station")
    return radio_tune(station, dj=bool(payload.get("dj", True)))


@app.get("/api/radio/next")
async def radio_next_api(
    station: str = "all",
    solo: int = 0,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """What the panel player pulls when a track ends, so the browser can run
    the same station without the box being involved."""
    require_read_auth(authorization)
    # #1127: the app is fed its music while paused. Only the BOOTH is
    # off - /api/dj/voice is what goes empty, and it still does.
    # While the DJ is on air he owns the running order. A browser asking for
    # "next" here would consume a second track and the show would appear to
    # skip — so hand back what is actually playing instead (#122).
    # The same is true of the plain radio the moment its loop is running:
    # every browser popping the shared queue for itself is exactly why two
    # machines ended up on different records (#631). solo=1 opts out.
    if _RADIO["on"] or (not solo and _RADIO.get("now") and _RADIO_TASK):
        current = _RADIO.get("now")
        if current:
            return {
                **{k: v for k, v in current.items()
                   if k not in ("path", "search")},
                "url": f"/music/{current['id']}?t={media_sign(current['id'])}",
                "art": f"/music/{current['id']}/art"
                       f"?t={media_sign(current['id'])}",
                "following": True,
            }

    if _RADIO["station"] != station:
        _RADIO.update({"station": station, "queue": radio_fill(station)})
    track = radio_next_track()
    if not track:
        raise HTTPException(status_code=404, detail="That station is empty")
    return {**{k: v for k, v in track.items() if k not in ("path", "search")},
            "url": f"/music/{track['id']}?t={media_sign(track['id'])}"}


@app.get("/api/radio/clock")
async def radio_clock_api(
    request: Request,
    listener: str = "",
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """The station clock on its own (#631).

    Small enough to ask for every second and a half, which is what it takes
    for every machine in the house to sit on the same second of the same
    record. The full state stays on its slower round — it signs twenty
    upcoming tracks and nobody needs that to stay in time.
    """
    require_read_auth(authorization)
    listeners = _radio_listeners(listener[:64] if listener else "")
    # #1008: remember enough about each player to tell two of them apart,
    # and hand back who owns the air so the ones that do not can mute
    # themselves. This is polled every second and a half, so it must stay
    # this cheap.
    if listener:
        try:
            listener_note(listener[:64],
                          str(getattr(request.client, "host", "") or ""),
                          str(request.headers.get("user-agent") or ""))
        except Exception:  # noqa: BLE001
            pass
    track = _RADIO.get("now") or {}
    tid = str(track.get("id") or "")
    root = "/tape" if track.get("tape") else "/music"
    return {
        "server_ms": int(time.time() * 1000),
        "started_ms": int(float(_RADIO.get("started") or 0) * 1000),
        "on": bool(_RADIO.get("on")),
        # #1138: a paused radio is a SILENT radio now. Every player in
        # the house follows this clock, so "not playing" here is what
        # stops the page, the app shell and the tune page at once.
        "playing": bool(track) and not radio_paused(),
        "paused": radio_paused(),
        "id": tid,
        # 2026-09-09: ONE DESTINATION, and the clock is where every player
        # in the house learns it. False means the box is carrying the
        # record and this page must not play it as well.
        "music_here": page_carries_music(),
        "title": str(track.get("title") or ""),
        "seconds": float(track.get("seconds") or 0),
        "url": f"{root}/{tid}?t={media_sign(tid)}" if tid else "",
        "art": f"/music/{tid}/art?t={media_sign(tid)}"
               if tid and not track.get("tape") else "",
        "listeners": listeners,
        # #1008: "" means everybody plays, which is the default and the
        # old behaviour exactly. A listener id means only that one plays
        # and every other page mutes itself.
        "audio_owner": audio_owner(),
    }


@app.get("/api/radio/listeners")
async def radio_listeners_api(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """#1008: every player on this broadcast right now.

    Two players on one broadcast, a few hundred milliseconds apart, is
    what "the DJs are overlapping each other" sounds like when nothing is
    wrong with the show at all. This is how you find out that is what is
    happening."""
    require_read_auth(authorization)
    rows = listener_roster()
    owner = audio_owner()
    return {
        "listeners": rows,
        "audio_owner": owner,
        "say": ("nobody is listening" if not rows else
                (f"{len(rows)} players are on this broadcast"
                 + (f" and {owner} owns the air - the rest are muted"
                    if owner else
                    " - if that is one machine, they will be playing over "
                    "each other. Give one of them the air.")
                 ) if len(rows) > 1 else "one player, no overlap possible"),
    }


@app.post("/api/radio/solo")
async def radio_solo_api(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """#1008: give ONE player the air; every other page mutes itself.

    {"listener": "<id>"} to hand it over, {"clear": true} to let everybody
    play again. An owner that stops polling releases it on its own after
    AUDIO_OWNER_LIFE, so this can never leave the house silent."""
    require_auth(authorization)
    try:
        body = await request.json()
    except Exception:  # noqa: BLE001
        body = {}
    body = body if isinstance(body, dict) else {}
    if body.get("clear"):
        _AUDIO_OWNER.clear()
        pipeline_log("air", "every player may sound again (#1008)")
        return {"audio_owner": "", "listeners": listener_roster()}
    who = str(body.get("listener") or "")[:64]
    if not who:
        raise HTTPException(status_code=400,
                            detail="name a listener, or pass clear")
    # #1187: A DEVICE SET NOT TO PLAY OUT LOUD MAY NOT TAKE THE EXCLUSIVE.
    # Holding the air and refusing to sound is the one combination that
    # guarantees silence everywhere: every other page gags itself for a
    # device that then plays nothing. Measured live - the desktop panel
    # re-claimed the air every few seconds while its own row read
    # play=false, so the tablet was gagged and the house heard nothing.
    # `play` is the out-loud switch; the exclusive only decides WHICH
    # out-loud device wins. To give the air to this one, turn its play on.
    _row = terminal_for_listener(who)
    if _row and not _row.get("play"):
        name = str(_row.get("name") or who)
        pipeline_log("air", f"{name} asked for the air but is set not to "
                     "play out loud - refused, so the device that does "
                     "play keeps it (#1187)")
        return {"audio_owner": audio_owner(), "listeners": listener_roster(),
                "refused": who,
                "why": f"{name} is set not to play out loud, so it cannot "
                       "hold the exclusive - turn its play switch on first"}
    _AUDIO_OWNER.clear()
    _AUDIO_OWNER.update({"who": who, "at": time.time()})
    pipeline_log("air", f"{who} has the air - every other player mutes "
                 "itself, so one broadcast is heard once (#1008)")
    return {"audio_owner": who, "listeners": listener_roster()}


@app.get("/api/music/votes")
async def music_votes(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Everything you have voted on, newest first."""
    require_read_auth(authorization)
    votes = read_votes()
    rows = [
        {"id": track_id, **row,
         "url": f"/music/{track_id}?t={media_sign(track_id)}"}
        for track_id, row in votes.items()
    ]
    rows.sort(key=lambda r: r.get("ts", 0), reverse=True)
    return {
        "votes": rows,
        "up": sum(1 for r in rows if r.get("vote", 0) > 0),
        "down": sum(1 for r in rows if r.get("vote", 0) < 0),
    }


@app.post("/api/music/vote")
async def music_vote(
    request: Request,
    t: str = "",
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """1 = play it more, -1 = never again, 0 = forget I said anything."""
    require_listen_auth(t, authorization)
    payload = await request.json()

    track_id = str(payload.get("id") or "")
    track = music_track(track_id) if track_id else None
    if not track:
        hits = music_search(str(payload.get("q") or ""), limit=1)
        track = hits[0] if hits else None
        track_id = track["id"] if track else ""
    if not track_id:
        raise HTTPException(status_code=404, detail="No such track")

    try:
        vote = int(payload.get("vote", 0))
    except (TypeError, ValueError):
        vote = 0
    # WHERE in the record the thumb landed (#683). The page sends its own
    # player position when it has one; when the like comes from somewhere
    # with no player — the chat row, a phone, the tune-in page — the record
    # on air knows its own elapsed, and that is the same moment.
    try:
        at: float | None = float(payload["at"])
    except (KeyError, TypeError, ValueError):
        at = None
    if at is None and (_RADIO.get("now") or {}).get("id") == track_id:
        elapsed = radio_state().get("elapsed") or 0.0
        if elapsed > 0:
            at = float(elapsed)
    result = set_vote(track_id, vote, track, at=at)

    # Banning what is playing means it should stop playing.
    if vote < 0:
        _RADIO["queue"] = [t for t in _RADIO["queue"] if t["id"] != track_id]
        _RADIO["requests"] = [
            t for t in _RADIO["requests"] if t["id"] != track_id]
        if (_RADIO.get("now") or {}).get("id") == track_id and _RADIO["on"]:
            dj_skip()

    return {"id": track_id, "title": (track or {}).get("title", ""), **result}


ROUTING_PATH = data_path("routing.json")


def _routing_voice_device_set(device: str) -> None:
    if device not in ("pine", "nabu"):
        return
    changed = (_RADIO.get("voice_device") or "") != device
    settings = load_settings()
    voice_out = dict(settings.get("voice_out") or {})
    voice_out["media_player"] = (
        NABU_SATELLITE if device == "nabu" else PINEVOICE_SATELLITE
    )
    # #814: the reply player is part of the same switch. Leaving it aimed
    # at the previous device split the station across two speakers —
    # station audio on the Nabu, every reply on the pine.
    if voice_out.get("reply_media_player") in (NABU_SATELLITE,
                                               PINEVOICE_SATELLITE):
        voice_out["reply_media_player"] = ""
    settings["voice_out"] = voice_out
    if device == "nabu":
        settings.setdefault("dj", {})["box_volume_control"] = False
        _MUSIC_LEVEL_SET.clear()
    save_settings(settings)
    _RADIO["voice_device"] = device
    _SAT_ALIVE.update({"checked": 0.0, "entity": ""})
    _SAT_BUSY.update({"at": 0.0, "entity": ""})
    if changed:
        # #786: the breaker, the silent-hold streak and the last-heard clock
        # are ONE global slot shared by both devices — switching speakers
        # used to inherit the OTHER device's open breaker and stale silence,
        # so a healthy Nabu opened to 90 seconds of instant declines and a
        # nervous DJ. A fresh device starts with a clean slate, and the
        # hold shelf wakes for it.
        _BOX_DOWN.update({"fails": 0, "until": 0.0})
        _SILENT_HOLD_STREAK[0] = 0
        _BOX_LAST_OK[0] = time.time()
        fire_and_forget(box_route_wake())


def _routing_save() -> None:
    """Routing is server-authoritative and survives restarts now (#501): a
    reload no longer resets it to box and no stale browser tab can clobber it."""
    try:
        ROUTING_PATH.parent.mkdir(parents=True, exist_ok=True)
        tmp = ROUTING_PATH.with_suffix(".tmp")
        tmp.write_text(json.dumps({k: _RADIO.get(k)
                                   for k in ("music_to", "voice_to",
                                             "voice_device", "reply_to",
                                             "box_talk")}))
        tmp.replace(ROUTING_PATH)
    except Exception:
        pass


def _routing_load() -> None:
    try:
        data = json.loads(ROUTING_PATH.read_text())
    except Exception:
        return
    for k in ("music_to", "voice_to", "reply_to"):
        v = data.get(k)
        if v in ("box", "here", "both", "off", "nabu"):
            _RADIO[k] = "box" if v == "nabu" else v
            if v == "nabu":
                _RADIO["voice_device"] = "nabu"
    if data.get("voice_device") in ("pine", "nabu"):
        _RADIO["voice_device"] = data["voice_device"]
    if isinstance(data.get("box_talk"), bool):
        _RADIO["box_talk"] = data["box_talk"]     # the switch survives too
    if (_RADIO.get("music_to") == "here" and _RADIO.get("voice_to") == "box"
            and _RADIO.get("reply_to") == "box"
            and _RADIO.get("voice_device") != "nabu"):
        _routing_voice_device_set("nabu")
        _routing_save()


@app.on_event("startup")
async def _startup_routing() -> None:
    _routing_load()
    if _RADIO.get("voice_device") == "nabu":
        _routing_voice_device_set("nabu")


ROUTING_OPERATOR_PATH = data_path("routing_operator.json")


def _operator_routing_read() -> dict[str, Any]:
    """#818: what the OPERATOR chose, as distinct from what a repair
    temporarily forced. This is the default everything returns to."""
    try:
        d = json.loads(ROUTING_OPERATOR_PATH.read_text())
        return d if isinstance(d, dict) else {}
    except Exception:  # noqa: BLE001
        return {}


def _operator_routing_stamp(fields: dict[str, Any]) -> None:
    try:
        d = _operator_routing_read()
        d.update({k: v for k, v in fields.items() if v})
        ROUTING_OPERATOR_PATH.write_text(json.dumps(d, indent=1))
    except Exception:  # noqa: BLE001
        pass


async def music_box_stop_now() -> None:
    """#818: switching music OFF the box silences the box NOW — not at
    whatever moment the current record happens to end."""
    token, _pl = _ha_creds()
    if not token:
        return
    try:
        async with httpx.AsyncClient(timeout=10) as client:
            await client.post(
                f"{HA_URL}/api/services/media_player/media_stop",
                headers={"Authorization": f"Bearer {token}"},
                json={"entity_id": NABU_MEDIA_PLAYER})
        _NABU_MUSIC_ON.update(ok=False, track="", at=time.time())
        pipeline_log("air", "music routed off the box — box media "
                     "stopped immediately (#818)")
    except Exception:  # noqa: BLE001
        pass


@app.post("/api/dj/output")
async def dj_output_api(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Send the show to the box speaker, the browser, both, or off — per type:
    music, DJ voice, and the reply/response system independently (#112, #501).
    Persisted so it is stable across restarts and shared between clients."""
    require_auth(authorization)
    payload = await request.json()
    if "nabu_mute" in payload:
        if not isinstance(payload["nabu_mute"], bool) or set(payload) != {"nabu_mute"}:
            raise HTTPException(status_code=400,
                detail="nabu_mute must be true or false and sent as a separate explicit device action")
        result = dj_state()
        result["nabu_mute"] = await nabu_output_mute(payload["nabu_mute"])
        return result
    valid = ("box", "here", "both", "off", "nabu")

    # `output` alone still means the music, which is what it controlled.
    music = str(payload.get("music") or payload.get("output") or "").strip()
    voice = str(payload.get("voice") or "").strip()
    reply = str(payload.get("reply") or "").strip()
    voice_device = str(payload.get("voice_device") or "").strip()
    nabu_levels = (voice_device == "nabu" or "nabu" in (music, voice, reply)
                   or (not voice_device and _RADIO.get("voice_device") == "nabu"))
    mix_changes: list[str] = []
    for value in (music, voice, reply):
        if value and value not in valid:
            raise HTTPException(status_code=400, detail="box, here, both, nabu or off")
    if voice_device and voice_device not in ("pine", "nabu"):
        raise HTTPException(status_code=400, detail="pine or nabu")
    if not payload.get("system"):
        for level_key in ("music_level", "voice_level", "reply_level"):
            if payload.get(level_key) is not None:
                try:
                    value = float(payload[level_key])
                    if isinstance(payload[level_key], bool) or not math.isfinite(value):
                        raise ValueError("not finite")
                    payload[level_key] = max(0.0, min(1.0, value))
                except (TypeError, ValueError):
                    raise HTTPException(status_code=400, detail=level_key + " must be a finite number")
    # #971: the Music slider, when the music is going to the box. The
    # operator pulled it down to a quarter and the Nabu kept playing at
    # full, because until now those sliders only scaled audio playing in
    # THIS app - see music_box_level().
    # #1007: and whether we are allowed to send it at all.
    if payload.get("music_control") is not None:
        try:
            _on = bool(payload.get("music_control")) and not (
                nabu_volume_owned() or voice_device == "nabu"
                or "nabu" in (music, voice, reply))
            _s = load_settings()
            _s.setdefault("dj", {})["box_volume_control"] = _on
            save_settings(_s)
            _MUSIC_LEVEL_SET.clear()      # a fresh decision, freshly sent
            pipeline_log(
                "voice",
                "the station "
                + ("may set the box's own volume again (#1007)" if _on else
                   "will not touch the box's volume - the dial on the "
                   "device owns it now (#1007)"))
        except Exception:  # noqa: BLE001
            pass
    if payload.get("music_level") is not None and not payload.get("system"):
        try:
            _lvl = max(0.0, min(1.0, float(payload.get("music_level"))))
            _s = load_settings()
            _s.setdefault("dj", {})["music_box_level"] = _lvl
            if nabu_levels:
                _s["dj"]["nabu_music_level"] = _lvl
                mix_changes.append("music")
            save_settings(_s)
            # #1014: "Make sure that these settings are affecting the box
            # in real time as I'm adjusting them." This IS the operator
            # moving the slider, so it goes to the device NOW - whether or
            # not the station has standing permission to set that number
            # on its own. #1007 refused the station ASSERTING a level
            # nobody asked for; an explicit move of the control is the
            # opposite of that, and refusing it would make the slider a
            # control that visibly does nothing.
            if not nabu_levels and str(_RADIO.get("music_to") or "") in ("box", "both"):
                _sent = await box_level_send(_lvl, operator=True)
                if _sent.get("ok"):
                    pipeline_log("voice", f"records set to {int(_lvl * 100)}%"
                                 " on the box now - you moved the slider "
                                 "(#1014)")
                elif _sent.get("why"):
                    pipeline_log("drop", "could not set the record level on "
                                 f"the box: {_sent.get('why')} (#1014)")
        except Exception:  # noqa: BLE001
            pass
    # Nabu scales saved speech at delivery, independently of its music.
    # Other speakers retain the existing rendering gain control.
    if payload.get("voice_level") is not None and not payload.get("system"):
        try:
            _v = max(0.0, min(1.0, float(payload.get("voice_level"))))
            # 0..1 across the slider maps onto the 0.3..1.6 the amplitude
            # multiplier is clamped to, so the ends of the control are the
            # ends of what the station can actually do.
            _gain = round(0.3 + _v * 1.3, 3)
            _s2 = load_settings()
            _s2.setdefault("dj", {})["nabu_voice_level" if nabu_levels else "box_volume"] = (
                _v if nabu_levels else _gain)
            save_settings(_s2)
            if nabu_levels:
                mix_changes.append("voice")
                pipeline_log("voice", f"Nabu DJ level set to {int(_v * 100)}%; "
                             "applies to the next spoken clip, including saved takes")
            else:
                pipeline_log("voice", f"the DJs are rendered at {_gain}x from here")
        except Exception:  # noqa: BLE001
            pass
    if nabu_levels and payload.get("reply_level") is not None and not payload.get("system"):
        _reply_level = max(0.0, min(1.0, float(payload["reply_level"])))
        _reply_settings = load_settings()
        _reply_settings.setdefault("dj", {})["nabu_reply_level"] = _reply_level
        save_settings(_reply_settings)
        mix_changes.append("reply")
    was = str(_RADIO.get("voice_to") or "box")
    # #1029: WHO IS MOVING THE BROADCAST. Recorded before anything is
    # applied, and only said out loud when something actually changes -
    # every open surface polls and re-posts, so logging no-ops would bury
    # the one that matters.
    try:
        _before = {k: str(_RADIO.get(k) or "") for k in
                   ("music_to", "voice_to", "reply_to")}
        _who = str(getattr(request.client, "host", "") or "?")
        _agent = str(request.headers.get("user-agent") or "")
        _what = ("the desktop app" if "Electron" in _agent
                 else "a browser tab" if _agent else "something unnamed")
        _asked = {"music_to": music, "voice_to": voice, "reply_to": reply}
        _moves = [f"{k.replace('_to', '')} {_before[k]} -> {v}"
                  for k, v in _asked.items() if v and v != _before[k]]
        if _moves:
            pipeline_log("air", f"{_what} at {_who} moved the broadcast: "
                         + ", ".join(_moves) + " (#1029)")
            _ROUTING_MOVES.append({
                "at": time.time(), "addr": _who, "what": _what,
                "agent": _agent[:120], "moves": _moves})
            del _ROUTING_MOVES[:-40]
    except Exception:  # noqa: BLE001
        pass
    for value in (music, voice, reply):
        if value and value not in valid:
            raise HTTPException(status_code=400,
                                detail="box, here, both, nabu or off")
    if voice_device and voice_device not in ("pine", "nabu"):
        raise HTTPException(status_code=400, detail="pine or nabu")
    if any(value == "nabu" for value in (music, voice, reply)):
        voice_device = "nabu"
        music = "box" if music == "nabu" else music
        voice = "box" if voice == "nabu" else voice
        reply = "box" if reply == "nabu" else reply

    # 2026-09-09: ONE BROADCAST, ONE DESTINATION.
    #
    # #1118 gave the VOICE this rule and said exactly why: "'both' used to
    # mean SIMULTANEOUSLY, and that is two broadcasts... Two clocks, one
    # source... an operator hearing two different voices talking about two
    # different things in the same room." The music was never given it, and
    # a split route is not a split show - it is two of them. The voice
    # picker names the destination; the music follows it there.
    #
    # "off" is a mute, not a place, so it is left alone on either road: an
    # operator silencing the DJs is not asking to be sent the records
    # somewhere else.
    _dest = str(voice or was or "box")
    if _dest in ("box", "here", "both") and music != "off":
        _had = str(music or _RADIO.get("music_to") or "here")
        if _had != _dest and _had != "off":
            pipeline_log("air", "the broadcast has ONE destination: music "
                         f"{_had} against voice {_dest} would be two of "
                         f"them - the music follows the voice to {_dest}")
            music = _dest
        elif not music and _had == _dest:
            pass                        # already agreed; nothing to move

    _was_music = str(_RADIO.get("music_to") or "here")
    if music:
        _RADIO["music_to"] = music
    if voice:
        _RADIO["voice_to"] = voice
        # #741: "I switched over to the Pine Box and it didn't move the audio
        # over." Routing was only ever read when the NEXT line was written, so
        # the page kept playing everything already rendered — sometimes a
        # minute of it — while the box sat silent. Taking the show off the
        # page means taking it off the page NOW: the browser feed is emptied
        # so no client can pick another clip out of it, and the page hands
        # back whatever it had not played yet (see /api/dj/handoff) for the
        # box to carry instead.
        if voice in ("box", "off") and was != voice:
            _RADIO["voice_clips"].clear()
    if voice_device:
        _routing_voice_device_set(voice_device)
    if reply:
        _RADIO["reply_to"] = reply
    # The master switch rides the same endpoint and the same save (#638).
    # Absent means unchanged, so older clients keep working untouched.
    talk = payload.get("box_talk")
    if (talk is None and not payload.get("system")
            and voice in ("box", "both")):
        # Choosing a DJ speaker is also asking to hear it. A remembered off
        # switch otherwise silently overrules the selector. Explicit off and
        # automatic routing restores retain their own switch state.
        talk = True
    if talk is not None:
        _RADIO["box_talk"] = bool(talk)
        if not _RADIO["box_talk"]:
            # Turning this output off pauses recovery; it does not cancel
            # dialogue that the station still owes. The shelf resumes when
            # the output returns, in its original order.
            _box_hold_save()
            # #690: switching the box off ends any repair in progress. The
            # breaker, the failure count and the "The DJs are on it" banner
            # all describe a speaker the station is no longer calling —
            # leaving them up meant flipping the switch off and then
            # watching a repair run for another three minutes.
            _BOX_DOWN["until"] = 0.0
            _BOX_DOWN["fails"] = 0
            _RADIO.pop("repairing", None)
            pipeline_log("air", "Pine Box switched off — the station stops "
                                "calling it, and stops repairing it (#690)")
    _routing_save()
    # The selected destination should take effect now, not on the next
    # twenty-second shelf pass. The probe is bounded and self-heal is already
    # cooldown-protected, so moving the selector cannot create a repair loop.
    if ((voice in ("box", "both") and (voice != was or not payload.get("system")))
            or (talk is True and (_RADIO.get("voice_to") or "box") in ("box", "both"))):
        request_box_route_wake()
    # #818: what YOU set here is the remembered default. Repair roads
    # pass "system": true and never touch the ledger — and when the
    # box returns, the vigil restores exactly this.
    if not payload.get("system"):
        _operator_routing_stamp({"music": music, "voice": voice,
                                 "reply": reply,
                                 "voice_device": voice_device})
    # #818: the MUSIC switch is immediate too. Onto the box: the record
    # now playing starts there at once (the next track realigns both
    # outputs). Off the box: its media stops mid-note.
    if music and music != _was_music:
        if music in ("box", "both") \
                and _was_music not in ("box", "both") \
                and _RADIO.get("on") and _RADIO.get("now"):
            fire_and_forget(
                music_play_on_box(dict(_RADIO.get("now") or {})))
            pipeline_log("air", "music routed onto the box — the "
                         "current record starts there NOW (#818)")
        if _was_music in ("box", "both") \
                and music not in ("box", "both"):
            fire_and_forget(music_box_stop_now())
    result = dj_state()
    if mix_changes:
        result["mix_applied"] = {stream: await nabu_mix_changed(stream) for stream in mix_changes}
    return result


@app.post("/api/dj/handoff")
async def dj_handoff_api(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Move the narrative that was playing in the page onto the box (#741).

    Only the browser knows which of the clips it was handed have actually
    come out of its speakers yet, so it hands the rest back here when the
    routing changes to the Pine Box. They go on the hold shelf in order and
    drain straight into the box — so switching over picks the conversation
    up where the page left it instead of starting at the next line."""
    require_auth(authorization)
    payload = await request.json()
    moved = 0
    for clip in (payload.get("clips") or [])[:12]:
        if not isinstance(clip, dict):
            continue
        url = str(clip.get("url") or "")
        path, _, query = url.partition("?")
        sig = ""
        for bit in query.split("&"):
            if bit.startswith("t="):
                sig = bit[2:]
        # Only the station's own media doors — never an arbitrary path.
        if not path.startswith(("/media/", "/ads-audio/", "/sfx/")):
            continue
        key = path.rsplit("/", 1)[-1]
        if not sig or not hmac.compare_digest(sig, media_sign(key)):
            continue
        _BOX_HOLD.append({
            "path": path, "sig": sig,
            "text": str(clip.get("text") or "")[:400],
            "who": str(clip.get("who") or "dj"),
            "ts": int(time.time()), "bytes": 0,
        })
        moved += 1
    if not moved:
        return {"moved": 0, "held": len(_BOX_HOLD)}
    _hold_trim()
    _box_hold_save()
    pipeline_log("air", f"routing moved to the Pine Box — {moved} line(s) the "
                        "page had not played yet handed over to it (#741)")

    async def _carry() -> None:
        n = 0
        while _BOX_HOLD and n < 12:
            if not await box_hold_drain_one():
                break
            n += 1

    asyncio.create_task(_carry())
    return {"moved": moved, "held": len(_BOX_HOLD)}


@app.post("/api/dj/drain")
async def dj_drain_api(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Play the held dialogue through the box NOW (#500) — the "the Pine Box
    is back, click to send it" prompt. The hold-shelf watcher drains on its
    own too; this just does it immediately, in order, playout-confirmed."""
    require_auth(authorization)

    async def _drain() -> None:
        n = 0
        while _BOX_HOLD and n < 12:
            if not await box_hold_drain_one():
                break                       # box not carrying it yet
            n += 1

    asyncio.create_task(_drain())
    return {"draining": len(_BOX_HOLD)}


@app.get("/api/dj/voice")
async def dj_voice_api(
    since: int = 0,
    br: str = "",
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """DJ lines as audio, for the browser to play over the track. In box
    mode the feed used to be empty by definition — now it carries the
    diverted lines the box declined (#314), so speech never vanishes.

    #999: `br` is the listener's chosen bitrate, and naming it HERE is
    what keeps the encoder off the hot path. This is the moment a clip
    becomes known to that listener, and its broadcast instant is
    VOICE_BROADCAST_LEAD_MS in the future — so the encode gets the whole
    lead to finish in, and the fetch that follows finds a file already
    written. A rate we do not recognise, or an encoder that is missing,
    simply means the original is served."""
    require_read_auth(authorization)
    # #1117: OFF AIR, THE PAGE IS HANDED NOTHING TO PLAY. This is the
    # feed the desktop app and the public listener page pull station
    # voice from, and it is a second broadcast path entirely - gating
    # _play_on_box silences the Nabu and does nothing about the app,
    # which is exactly what the operator heard.
    #
    # The clips are NOT discarded: they stay in _RADIO["voice_clips"]
    # with their timestamps, so a listener who tunes in after the
    # broadcast resumes picks up from there. Off air simply means
    # nothing new is offered.
    if radio_paused():
        # #1151: the cut rides the paused answer too. Without it an open
        # page kept draining clips announced up to 45s ahead INTO the
        # pause (the record was pause-honest since #1145; the voice
        # queue was not), and the resume flush then landed mid-word.
        return {"clips": [], "server_ms": int(time.time() * 1000),
                "cut_ms": int(_RADIO.get("voice_cut_ms") or 0),
                "paused": True, "off_air": True,
                "say": "the broadcast is paused - the booth is still "
                       "recording and this picks up when it returns"}
    reservation_updates = page_reservation_repair()
    server_ms = int(time.time() * 1000)
    clips = []
    # #1146: everything appended before the last unpause is history, not
    # programme - see radio_pause_set's resume branch. #1147: and a boot
    # stamps the same cut, so a reboot cannot straddle two schedules.
    _cut_ms = int(_RADIO.get("voice_cut_ms") or 0)
    for clip in _RADIO["voice_clips"]:
        if int(clip.get("ts") or 0) <= int(since):
            continue
        if int(clip.get("ts") or 0) <= _cut_ms:
            continue
        _bm = int(clip.get("broadcast_ms")
                  or int(clip["ts"]) + VOICE_BROADCAST_LEAD_MS)
        # #1147: never OFFER a clip that can no longer be played sanely.
        # The server knows each clip's honest air moment and, for a
        # stream, its exact length; handing a client a run of past-due
        # clips is the cascade its players then garble. They stay in the
        # list for the booth's history, exactly as the pause road (#1117)
        # keeps them - off the air simply means nothing is offered.
        try:
            _slen = float((clip.get("stream") or {}).get("length") or 0)
        except Exception:  # noqa: BLE001
            _slen = 0.0
        # #1147 review: a sting is punctuation (5s of grace), a stream
        # gets its own length, and a plain line gets 20s - matching the
        # clients' own staleness rules with room to spare.
        _grace = (int(_slen * 1000) if _slen > 0
                  else 5000 if clip.get("sting") else 20000)
        if server_ms > _bm + _grace:
            continue
        clips.append({**clip, "broadcast_ms": _bm})
    # #999: `br` is declared a STRING and validated by low_rate, not by
    # FastAPI. Typed `int`, a junk or empty value is a 422 on the
    # listener's only route - and low_rate's whole job is to be the one
    # place a client number becomes a bitrate.
    #
    # This no longer STARTS the encode (low_ready_soon does that, when
    # the audio is made). It only records that somebody is listening at
    # this rate, which is what tells the store-time hook what to make.
    low_note_rate(br)
    # #1147: the cut rides the response so an OPEN page can flush what it
    # banked from a dead process - the server-side filter alone cannot
    # reach clips already sitting in a browser's queue.
    return {"server_ms": server_ms, "cut_ms": _cut_ms, "clips": clips,
            "reservation_updates": reservation_updates}


@app.post("/api/dj/voice/ack")
async def dj_voice_ack_api(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """End-to-end browser playout acknowledgments for one page clip."""
    require_read_auth(authorization)
    try:
        body = await request.json()
        return page_playback_ack(
            body,
            str(getattr(request.client, "host", "") or ""),
            str(request.headers.get("user-agent") or ""))
    except KeyError as exc:
        raise HTTPException(status_code=404, detail=str(exc)) from exc
    except (TypeError, ValueError) as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc


