@app.post("/api/dj/start")
async def dj_start_api(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    require_auth(authorization)
    payload = await request.json()
    station = str(payload.get("station") or "")
    # force=true is the one-button path (#108): it will not refuse.
    if payload.get("force"):
        return await dj_go(station)
    station = station or "all"
