@app.post("/api/dj/ad")
async def dj_ad_api(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Commercials and shout-outs on demand (#103)."""
    require_auth(authorization)
    payload = await request.json()
    product = str(payload.get("product") or "").strip()
    note_action("🛎 you called a commercial"
                + (f": {product[:40]}" if product else ""))
    if not product and payload.get("gallery"):
        # The gallery press is a whole ROUND now (#346): several
        # paintings actually looked at, described, priced absurdly and
        # hawked — with speakbox rhetoric stitched through. Looking takes
        # the vision model minutes, so the round runs behind the reply —
        # the booth windows carry it as it airs. If the model's eyes fail
        # the old single-painting ad read goes out instead.
        if not gallery_product():
            raise HTTPException(
                status_code=404, detail="No generated images to advertise yet")

        async def _gallery_press() -> None:
            try:
                if not await dj_gallery_round():
                    fallback = gallery_product()
                    if fallback:
                        await dj_ad(fallback)
            except Exception as exc:
                pipeline_log("drop", f"gallery round died: {exc}"[:200])

        asyncio.create_task(_gallery_press())
        return {"ok": True, "gallery_round": True}
    if not product:
        raise HTTPException(status_code=400, detail="Name what to plug")
    # A PRODUCED spot on demand (#618): the read vocoded, mixed over a bed of
    # the station's own music with a sound effect punched in — the "MP3 + their
    # voices + vocoding + SFX" ad, stored and rerun like any other.
    if payload.get("music"):
        return await dj_music_ad(
            product, remember=bool(payload.get("remember", True)))
    # Made on demand from the panel = a CUSTOM ad: gets an SFX and a week on
    # the shelf (#464).
    return await dj_ad(product, remember=bool(payload.get("remember", True)),
                       custom=True)


