    product = str(payload.get("product") or "").strip()
    text = str(payload.get("text") or "").strip()

    if ad_id:
        updated = ad_update(ad_id, product=product, text=text)
        if not updated:
            raise HTTPException(status_code=404, detail="No such ad read")
