@app.get("/guide/pinebox", response_class=HTMLResponse)
async def pinebox_guide() -> str:
    """The full recovery guide, with this box's own diagnosis at the top.

    It is a page rather than only a PDF so the numbers in it are live; the
    print stylesheet makes Ctrl-P produce the same document."""
    try:
        state = await pinebox_diagnose()
    except Exception:
        state = {"cause": "Could not run the diagnosis.", "checks": [],
                 "steps": [], "host": SATELLITE_HOST, "mac": SATELLITE_MAC,
                 "ssid": SATELLITE_SSID, "online": False}

    rows = "".join(
        f"<tr><td>{'✅' if c['ok'] else ('—' if c['ok'] is None else '❌')}</td>"
        f"<td>{c['name']}</td><td class=d>{c['detail']}</td></tr>"
        for c in state["checks"]
    )
    steps = "".join(f"<li>{s}</li>" for s in state["steps"])
    return (GUIDE_HTML
            .replace("__ROWS__", rows)
            .replace("__STEPS__", steps)
            .replace("__CAUSE__", state["cause"])
            .replace("__HOST__", state["host"] or "unset")
            .replace("__MAC__", state["mac"])
            .replace("__SSID__", state["ssid"])
            .replace("__WHEN__", time.strftime("%A %d %B %Y, %H:%M")))


