@app.get("/api/tint")
async def api_tint_state(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """#1006: THE WHOLE PROCESS, said in order.

    "I want to be able to see this process in full that takes the pine
    box FM settings and utilizes them to build the foundation that we
    inject with speakerbox text to generate, that we then generate using
    the tinting of the crystal to then get the desired result."

    So: the stages, in the order they happen, with what each one is
    drawing on right now and the dials that govern it."""
    require_read_auth(authorization)
    dj = dj_settings()
    ons = crystal_active()
    two = crystal_tint_two_pass()
    try:
        armed = load_settings()
        armed_name = str((armed["prompts"][armed["active_prompt"]]
                          or {}).get("name") or "")
    except Exception:  # noqa: BLE001
        armed_name = ""
    return {
        "two_pass": two,
        # #1063: whether an unproved tint holds dialogue off the air.
        "hold": crystal_tint_holds(),
        # #1064: how a bar is graded - meaning (default) or strict.
        "grade": "strict" if crystal_grade_strict() else "meaning",
        # 2026-09-09: the one revision pass - the dial, and, for each road it
        # is allowed on, whether it would run right now or the words it would
        # stand down with. A reader asking "is the crystal polishing bars, and
        # if not why not" is answered here rather than from the log.
        "revision": {"mode": crystal_revision_mode(),
                     "deep_roads": list(TINT_DEEP_ROADS),
                     "standing_down": {road: crystal_revision_skip(road)
                                       for road in TINT_DEEP_ROADS},
                     "asks": "exactly one self-edit of a bar the evaluator has "
                             "already accepted, for unexpected phrasing and "
                             "specific words; a revision that fails the same "
                             "grade is discarded and the accepted bar stands"},
        # #1053: the dial, and what share of the hour's lines it reached.
        "force": round(crystal_force(), 2),
        "coverage": tint_coverage(),
        "coverage_target": crystal_coverage_target(),
        "coverage_contract": (
            "minimum share of eligible dialogue that must pass the tint "
            "evaluator before recording"
            if crystal_tint_holds() else
            "share of eligible dialogue the tint tries to rewrite; a "
            "rewrite that fails airs as written (crystal_tint_hold is off)"),
        "evaluator": {"checks": ["semantic preservation",
                                   "internal, multisyllabic or chained rhyme",
                                   "rhetorical transformation", "source phrase copying",
                                   "crystal lexicon (shown passages or the pool)"],
                      "source_phrase_limit_words": 6,
                      "method": "deterministic content, entity and spelling-rhyme checks"},
        "crystals_on": [{"name": str(c.get("name") or ""),
                         "strength": int(c.get("strength") or 0),
                         "tint": str(c.get("tint") or ""),
                         "minds": list(c.get("minds") or []),
                         "sources_words": crystal_sources(c)}
                        for c in ons],
        "chunks": int(dj.get("crystal_tint_chunks") or 0),
        "chars": int(dj.get("crystal_tint_chars") or 0),
        # #1068: the rhyming dictionary and thesaurus behind the word
        # options - whether its local index is built and how much of the
        # neural layer has been embedded. Before this the status function
        # had no route at all.
        "rhyme_assistance": crystal_rhyme_status(),
        "fault_memo": tint_fault_memo_status(),                # #1082
        "strikes_most": TINT_STRIKES_MOST,                     # #1082
        "lanes_per_model": OLLAMA_LANES,                       # #1080
        "material": crystal_material_status(),                 # #1081
        "stanzas": crystal_stanza_status(),                    # #1081
        # #1018: what every OTHER tint site is now sending - the crystal's
        # own lines, not just its description. Shown here because the
        # operator's complaint was that the tint had a label in it and
        # nothing to imitate, and the only way to know that is fixed is
        # to look at what actually goes.
        "style_note": crystal_style_note(),
        "style_lines": [str(r.get("text") or "")[:200]
                        for r in crystal_lines(4)],
        "pool": len(_CRYSTAL_POOL.get("rows") or []),
        "stages": [
            {"n": 1, "name": "the foundation",
             "what": "the station's own system prompt and radio prompts, "
                     "plus the segment's standing instruction",
             "now": armed_name or "the armed prompt",
             "dials": ["the prompt desk", "the schedule's per-entry prompt"]},
            {"n": 2, "name": "the speakbox injection",
             "what": "passages out of your own documents, folded into the "
                     "prompt as material rather than instruction",
             "now": f"{int(float(dj.get('speakbox_rate') or 0) * 100)}% "
                    "grounding, prepend "
                    f"{int(float(dj.get('speakbox_prepend_rate') or 0) * 100)}"
                    "%, full swath "
                    f"{int(float(dj.get('speakbox_full_swath_rate') or 0) * 100)}"
                    f"% up to {int(dj.get('speakbox_full_swath_chars') or 0)} "
                    "chars",
             "dials": ["speakbox_rate", "speakbox_prepend_rate",
                       "speakbox_append_rate", "speakbox_full_swath_rate",
                       "speakbox_full_swath_chars"]},
            {"n": 3, "name": "the conversation",
             "what": "the model writes the round from 1 and 2. With the "
                     "second pass on, this is written UNTINTED and is what "
                     "the reserve keeps as the original",
             "now": "untinted" if two else "tinted in this same pass",
             "dials": ["talk_radio", "the segment's line count",
                       "temperature and spice"]},
            {"n": 4, "name": "the tinting pass",
             "what": "the finished conversation is sent back through the "
                     "model with the crystal's world prompt and passages "
                     "of the crystal's OWN material as the system prompt, "
                     "and told to move it into that world without changing "
                     "the structure or the facts",
             "now": (f"{len(ons)} crystal(s) on, "
                     f"{int(dj.get('crystal_tint_chunks') or 0)} passage(s) "
                     f"of up to {int(dj.get('crystal_tint_chars') or 0)} "
                     "chars injected" if two else
                     "off - the tint rides in stage 1 as a clause instead"),
             "dials": ["crystal_tint_pass", "crystal_tint_chunks",
                       "crystal_tint_chars", "crystal_coverage", "each crystal's strength"]},
            {"n": 5, "name": "evaluation and recording readiness",
             "what": "both versions are kept. Selected lines must preserve "
                     "meaning, transform rhetoric and pass rhyme and source-copying "
                     "checks. Rejected lines return to repair; unmet coverage holds recording",
             "now": ((f"{crystal_coverage_target()}% eligible dialogue "
                      + ("required - unproved dialogue is HELD off the air"
                         if crystal_tint_holds() else
                         "attempted - unproved dialogue airs as written "
                         "(#1063)"))
                     if two else "one version only"),
             "dials": ["the two thumbs on a reserve round (#1016)"]},
        ],
        "say": (("the tint is a second pass: rounds are written plain, then "
                 "rewritten through " + crystal_world_prompt())
                if two else
                ("no crystal is on, so nothing is tinted"
                 if not ons else
                 "the tint rides in the first prompt as a clause")),
    }


@app.post("/api/tint/try")
async def api_tint_try(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """#1006/#1018: run the tinting pass on a piece of text, right now,
    and hand back the before, the after, and everything that was sent.

    "I want to be able to see the influence and adjust how we inject
    chunks for reference in the 2nd LLM prompting to get the desired
    results." You cannot tune a dial whose effect you can only observe
    twenty minutes later on a round that happened to be banked. This is
    the same code path the real pass takes - crystal_tint, the same
    passages, the same system prompt - on text you choose.

    With no text it uses the most recent round in the reserve, which is
    usually what you want to ask about anyway."""
    require_auth(authorization)
    try:
        body = await request.json()
    except Exception:  # noqa: BLE001
        body = {}
    body = body if isinstance(body, dict) else {}
    text = str(body.get("script") or "").strip()
    keep: Any = body.get("verbatim")
    if not text:
        for entry in reversed(list(_LARDER)):
            got = str((entry or {}).get("script_plain")
                      or (entry or {}).get("script") or "").strip()
            if got:
                text = got
                keep = entry.get("verbatim")
                break
    if not text:
        raise HTTPException(status_code=400,
                            detail="give me a script, or bank a round first")
    # #1036: try a model WITHOUT committing to it. Comparing two
    # candidates on the same script is the only honest way to pick one,
    # and doing that by editing the setting between attempts would mean
    # the live show ran on whichever was being tried at the time.
    _was_model = None
    if body.get("model"):
        _s = load_settings()
        _was_model = str((_s.get("dj") or {}).get("crystal_tint_model")
                         or "")
        _s.setdefault("dj", {})["crystal_tint_model"] = str(
            body.get("model"))[:80]
        save_settings(_s)
    began = time.monotonic()
    try:
        got = await crystal_tint(text, str(body.get("kind") or ""), keep)
    finally:
        if _was_model is not None:
            _s2 = load_settings()
            _s2.setdefault("dj", {})["crystal_tint_model"] = _was_model
            save_settings(_s2)
    # How much of it actually moved - the only honest measure of whether
    # a dial did anything.
    plain = " ".join(text.split())
    made = " ".join(str(got.get("script") or "").split())
    same = 0
    for a, b in zip(plain, made):
        if a != b:
            break
        same += 1
    return {
        "ok": bool(got.get("ok")),
        "why": str(got.get("why") or ""),
        "world": str(got.get("world") or ""),
        "ms": int(got.get("ms") or 0),
        "took": round(time.monotonic() - began, 2),
        "before": text,
        "after": str(got.get("script") or ""),
        "passages": list(got.get("chunks") or []),
        "kept_verbatim": list(got.get("keep") or []),
        "speakerbox_sources": list(got.get("speakerbox_sources") or []),
        "coverage": dict(got.get("coverage") or {}),
        "evaluation": dict(got.get("evaluation") or {}),
        "armed": str(got.get("armed") or ""),
        # #1037: THE PROMPT AS SENT. `armed` is the whole-round prompt,
        # and the whole-round path is only taken for rounds over 22
        # turns - which is almost none of them. So the tuning tool was
        # showing a prompt the station does not send and omitting the one
        # it does.
        "prompt": str(got.get("prompt") or ""),
        "per_turn": bool(got.get("per_turn")),
        "identical_for": same,
        "model": str(body.get("model")
                     or dj_settings().get("crystal_tint_model")
                     or load_settings().get("model") or ""),       # #1036
        "say": (f"{len(plain)} chars in, {len(made)} out, identical for the "
                f"first {same} - {round(100.0 * same / max(1, len(plain)))}%"
                if got.get("ok") else str(got.get("why") or "it did not take")),
    }


@app.post("/api/prefs/tint")
async def api_tint_prefs(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """#1006: the dials on the tinting pass - whether it happens at all,
    how many passages of the crystal's own material go into the second
    system prompt, and how long each of them may be."""
    require_auth(authorization)
    try:
        body = await request.json()
    except Exception:  # noqa: BLE001
        body = {}
    body = body if isinstance(body, dict) else {}
    store = load_settings()
    seat = store.setdefault("dj", {})
    if body.get("two_pass") is not None:
        seat["crystal_tint_pass"] = bool(body.get("two_pass"))
    if body.get("hold") is not None:                                # #1063
        seat["crystal_tint_hold"] = bool(body.get("hold"))
    if body.get("grade_rhyme") is not None:                         # #1064
        seat["crystal_grade_rhyme"] = bool(body.get("grade_rhyme"))
    if body.get("coverage") is not None or body.get("crystal_coverage") is not None:
        try:
            requested = body.get("crystal_coverage", body.get("coverage"))
            seat["crystal_coverage"] = max(0, min(100, int(float(requested))))
        except (TypeError, ValueError, OverflowError):
            raise HTTPException(status_code=400, detail="crystal coverage must be 0 to 100")
    if body.get("chunks") is not None:
        try:
            seat["crystal_tint_chunks"] = max(0, min(12, int(
                float(body.get("chunks") or 0))))
        except (TypeError, ValueError):
            pass
    if body.get("model") is not None:
        # #1036: which model the tinting pass uses. Empty = the station's.
        seat["crystal_tint_model"] = str(body.get("model") or "")[:80]
    if body.get("chars") is not None:
        try:
            seat["crystal_tint_chars"] = max(120, min(4000, int(
                float(body.get("chars") or 700))))
        except (TypeError, ValueError):
            pass
    save_settings(store)
    dj = dj_settings()
    return {"two_pass": bool(dj.get("crystal_tint_pass")),
            "hold": bool(dj.get("crystal_tint_hold")),              # #1063
            "grade": "strict" if dj.get("crystal_grade_rhyme") else "meaning",
            "coverage": crystal_coverage_target(),
            "crystal_coverage": crystal_coverage_target(),
            "chunks": int(dj.get("crystal_tint_chunks") or 0),
            "chars": int(dj.get("crystal_tint_chars") or 0),
            "model": str(dj.get("crystal_tint_model") or ""),      # #1036
            "say": ("the tint is a second pass over the finished round, with "
                    f"{int(dj.get('crystal_tint_chunks') or 0)} passage(s) of "
                    f"up to {int(dj.get('crystal_tint_chars') or 0)} chars "
                    "of the crystal's own material in the system prompt"
                    if dj.get("crystal_tint_pass") else
                    "the tint rides in the first prompt as a clause")}


@app.post("/api/prefs/tip-delay")
async def api_tip_delay(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """#1012: how long you have to rest on something before it explains
    itself, in milliseconds. 0 switches tooltips off; under 400 hands
    them back to the browser's own timing."""
    require_auth(authorization)
    try:
        body = await request.json()
    except Exception:  # noqa: BLE001
        body = {}
    body = body if isinstance(body, dict) else {}
    try:
        ms = max(0, min(10000, int(float(body.get("ms", 3000) or 0))))
    except (TypeError, ValueError):
        ms = 3000
    store = load_settings()
    store.setdefault("dj", {})["tip_delay_ms"] = ms
    save_settings(store)
    return {"tip_delay_ms": ms,
            "say": ("tooltips are off" if ms <= 0 else
                    "tooltips use the browser's own timing" if ms < 400 else
                    f"tooltips appear after {ms / 1000:g}s of resting on "
                    "something")}


@app.get("/api/rooms/sitting")
async def api_rooms_sitting(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """#1010: the sitting as it would run right now - which actors are
    wanted across the scripts waiting, in the order they will be called,
    and how many rounds each of them finishes on the way out.

    Reads only; it does not start one. The preparer runs a sitting on its
    own whenever more than one script is waiting."""
    require_read_auth(authorization)
    pool: list[dict[str, Any]] = []
    try:
        for rows in _SHELF.values():
            for row in (rows or []):
                ent = (row or {}).get("entry")
                if isinstance(ent, dict) and not ent.get("prepared"):
                    pool.append(ent)
        for ent in _LARDER:
            if isinstance(ent, dict) and not ent.get("prepared"):
                pool.append(ent)
    except Exception:  # noqa: BLE001
        pass
    del pool[RECORDING_POOL_MOST:]
    try:
        cast = dict(await session_voices())
    except Exception:  # noqa: BLE001
        cast = {}
    wanted: dict[str, int] = {}
    closes: dict[str, int] = {}
    for entry in pool:
        try:
            turns = banter_turns(str(entry.get("script") or ""),
                                 str(entry.get("caller_name") or ""),
                                 str(entry.get("caller2_name") or ""))
            seats = dict(cast)
            for _s, _k in (("caller", "caller_voice"),
                           ("caller2", "caller2_voice")):
                _cv = str(entry.get(_k) or "")
                if _cv:
                    seats[_s] = _cv
            plan = _round_chunks(turns, seats,
                                 str(entry.get("caller_name") or ""))
        except Exception:  # noqa: BLE001
            continue
        here: set[str] = set()
        for _t, _v, _w in plan:
            if not _v:
                continue
            wanted[_v] = wanted.get(_v, 0) + 1
            here.add(str(_v))
        if len(here) == 1:
            only = next(iter(here))
            closes[only] = closes.get(only, 0) + 1
    order = sorted(wanted, key=lambda v: (-closes.get(v, 0), -wanted[v]))
    rows = []
    for voice in order:
        try:
            name = str((voice_meta(voice) or {}).get("name") or voice)
        except Exception:  # noqa: BLE001
            name = voice
        rows.append({"voice": voice, "name": name,
                     "lines": int(wanted.get(voice, 0)),
                     "finishes": int(closes.get(voice, 0))})
    return {
        "scripts": len(pool),
        "pool_cap": RECORDING_POOL_MOST,
        "actors": rows,
        "say": (f"{len(rows)} actor(s) for {len(pool)} script(s) - "
                + ", ".join(f"{r['name']} ({r['lines']})" for r in rows[:4])
                if rows else "nothing is waiting to be recorded"),
    }


@app.post("/api/rooms/sitting")
async def api_rooms_sitting_run(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """#1010: call a sitting NOW on whatever is waiting.

    The preparer runs one on its own whenever more than one script is
    waiting; this is the door for calling one by hand - and for proving
    the road works on a station whose rooms are, at that moment, clear."""
    require_auth(authorization)
    try:
        body = await request.json()
    except Exception:  # noqa: BLE001
        body = {}
    body = body if isinstance(body, dict) else {}
    try:
        secs = max(10.0, min(300.0, float(body.get("seconds", 60) or 60)))
    except (TypeError, ValueError):
        secs = 60.0
    pool: list[dict[str, Any]] = []
    wanted = committed_stock_ids(ready=False)
    for kind, rows in _SHELF.items():
        for row in (rows or []):
            ent = (row or {}).get("entry")
            if (isinstance(ent, dict) and not ent.get("prepared")
                    and alt_sid(str(kind), row) in wanted
                    and dialogue_tint_ready(str(kind), row)):
                pool.append(ent)
    for ent in _LARDER:
        if (isinstance(ent, dict) and not ent.get("prepared")
                and alt_sid("banter", ent) in wanted
                and dialogue_tint_ready("banter", ent)):
            pool.append(ent)
    if not pool:
        return {"rounds": 0, "actors": [], "finished": 0,
                "say": "nothing is waiting to be recorded - the rooms are "
                       "clear and only the writing desk can make more"}
    return await recording_sitting(pool, secs)


