@app.get("/api/chunks")
async def api_chunks(
    shelf: str = "",
    cooling: int = 0,
    limit: int = 200,
) -> dict[str, Any]:
    """#1042: THE CHUNK LEDGER, for reading.

    "i want to see what chunks are cooling down and how long are left
    and see how much was used and how it was responded to."

    Four facts per row and they are the four that were asked for: what
    it is and which shelf it came off, how many seconds of rest are
    left, how many times it has been used, and the lines the cast
    actually made of it. `shelf` narrows to "crystal" or "speakbox";
    `cooling=1` shows only what is still resting."""
    rows = chunk_rows(most=max(1, min(1000, int(limit or 200))),
                      shelf=str(shelf or ""),
                      cooling_only=bool(int(cooling or 0)))
    cool = chunk_cool_seconds()
    resting = [r for r in rows if r.get("cooling")]
    by_shelf: dict[str, int] = {}
    for r in rows:
        k = str(r.get("shelf") or "?")
        by_shelf[k] = by_shelf.get(k, 0) + 1
    return {
        "at": time.time(),
        "cool_seconds": cool,
        "rows": rows,
        "held": len(rows),
        "resting": len(resting),
        "free": len(rows) - len(resting),
        "by_shelf": by_shelf,
        # The longest rest left, so the panel can say when the shelf
        # next opens up without walking every row.
        "next_free": round(min([r["left"] for r in resting] or [0.0]), 1),
        "answered": sum(1 for r in rows if r.get("answers")),
    }


@app.get("/api/orchestrator/asks")
async def api_orch_asks(all: int = 0) -> dict[str, Any]:
    """#1056: what the orchestrator wants decided.

    The badge reads `open`; the popup reads `rows`. Every option names
    the action it takes, because a multiple choice whose answers do
    nothing is a survey, not an orchestrator."""
    orch_load()
    rows = list(_ORCH["asks"]) if int(all or 0) else orch_open()
    return {
        "at": time.time(),
        "open": len(orch_open()),
        "rows": rows[:12],
        "policy": dict(_ORCH.get("policy") or {}),
        "every_hours": round(ORCH_ASK_EVERY / 3600.0, 1),
        "next_due": max(0.0, round(float(_ORCH.get("last") or 0)
                                   + ORCH_ASK_EVERY - time.time(), 1)),
        "cupboard": cupboard_short(),
        # #1081: how long each urgency waits before the station decides
        # for itself, so the operator can see the clock they are on.
        "decides_after": {k: int(v / 60)
                          for k, v in ORCH_DECIDE_AFTER.items()},
        "decided_alone": sum(
            1 for r in _ORCH["asks"]
            if isinstance(r.get("answered"), dict)
            and r["answered"].get("alone")),
        "cast": cast_signature(),
        "horizon_hours": round(cupboard_horizon() / 3600.0, 1),
    }


