@app.get("/api/orchestrator/logic")
async def api_orch_logic(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """#1150: the orchestrator's whole reasoning, composed for the graph.

    Pure composition of state that already exists - demand, stock,
    learning, the operator's judgments, the plan, the execution order
    and the last closed hour - so the panel can draw the logic as a
    directed flow and the operator can see exactly how the station
    keeps ahead of demand, and turn the dials that steer it."""
    require_read_auth(authorization)
    _judgment_load()
    orch_load()
    needs = _hour_needs_with_cover()
    tasks = {str(t.get("road")): t
             for t in (_COORD_PLAN.get("tasks") or [])}
    roads: dict[str, Any] = {}
    for road, row in needs.items():
        judged = _JUDGMENT["roads"].get(road) or {}
        roads[road] = {
            "label": SHELF_LABEL.get(road, road),
            "owed": round(float(row.get("owed") or 0), 1),
            "held": round(float(row.get("held") or 0), 1),
            "uncovered": round(float(row.get("uncovered") or 0), 1),
            "cost": round(float(task_cost(road) or 0), 1),
            "learning": dict(_HOUR_LEARNING.get(road) or {}),
            "judgment": {
                "factor": coord_judgment_factor(road),
                "lesson": str(judged.get("lesson") or ""),
                "at": float(judged.get("at") or 0),
                "alone": bool(judged.get("alone")),
            },
            "task": ({k: tasks[road].get(k) for k in
                      ("want_seconds", "held_seconds", "due_in", "bare",
                       "learning_factor", "judgment_factor", "why")}
                     if road in tasks else None),
        }
    board = slot_board(2)
    hour = dict(_HOURS[-1]) if _HOURS else {}
    return {
        "at": time.time(),
        "on": bool(_RADIO.get("on")), "paused": radio_paused(),
        "hours_ready": round(prepared_seconds() / 3600.0, 2),
        "target_hours": round(prepare_target_seconds() / 3600.0, 2),
        "roads": roads,
        "order": coord_order(),
        "policy": dict(_ORCH.get("policy") or {}),
        "ask": (orch_open() or [None])[0],
        "book": _JUDGMENT["rows"][:12],
        "alone_count": sum(1 for r in _JUDGMENT["rows"] if r.get("alone")),
        "slots": {"behind": bool(board.get("behind")),
                  "verdicts": [{"face": s.get("face"),
                                "verdict": s.get("verdict"),
                                "cost": s.get("cost")}
                               for s in (board.get("slots") or [])]},
        "hour": {"score": hour.get("score"),
                 "closed_at": hour.get("closed_at"),
                 "roads": {k: {"attainment": (v or {}).get("attainment"),
                               "met": (v or {}).get("met")}
                           for k, v in (hour.get("roads") or {}).items()}},
        "workshop": {"last": _WORKSHOP_LAST[0],
                     "paused_for": round(radio_paused_for(), 1)},
        "plan_why": str(_COORD_PLAN.get("why") or ""),
        "pipeline": orchestrator_pipeline_state(),
    }


@app.post("/api/orchestrator/policy")
async def api_orch_policy(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """#1178: revise a standing answer.

    `{"does": "drive:none"}` - the same vocabulary `orch_apply` already
    accepts when an ask is answered, and nothing beyond it. Until now
    that function was reachable from one place, which needed an OPEN ask
    to answer, so a policy could be set and never taken back: a drive
    given when a road was genuinely empty outlived the emptiness and kept
    the preparer on the deepest shelf on the station.

    Returns what was done in the station's own words, and the whole
    policy book after it, so the change is visible rather than implied."""
    require_auth(authorization)
    payload = await request.json()
    does = str((payload or {}).get("does") or "").strip()
    if not does:
        raise HTTPException(
            status_code=400,
            detail='a policy change needs a "does", e.g. "drive:none"')
    verb = does.partition(":")[0]
    # The same small vocabulary, named here so a typo is a 400 rather than
    # a silent no-op that reads as success.
    # #1183: READ OFF orch_apply ITSELF. Restated by hand, this list had
    # drifted two verbs short - `thin` and `judgment` are implemented and
    # were refused here, which is exactly the asymmetry #1178 exists to
    # remove. ORCH_VERBS is derived from the function that does the work,
    # so the door and the action cannot disagree again.
    known = orch_verbs()
    if verb not in known:
        raise HTTPException(
            status_code=400,
            detail="%s is not something the orchestrator knows how to do "
                   "(%s)" % (verb, ", ".join(known)))
    before = copy.deepcopy(_ORCH.get("policy") or {})
    try:
        said = orch_apply(does)
    except Exception as exc:  # noqa: BLE001
        raise HTTPException(status_code=400, detail=str(exc)[:200]) from exc
    try:
        orch_save()
    except Exception:  # noqa: BLE001
        pass
    note_action("the policy book was revised by hand: %s" % (said or does))
    pipeline_log("action", "standing policy revised - %s (#1178)"
                 % (said or does))
    return {"ok": True, "said": said or "left as it is", "does": does,
            "was": {k: (v or {}).get("value") for k, v in before.items()},
            "policy": {k: (v or {}).get("value")
                       for k, v in (_ORCH.get("policy") or {}).items()}}


