@app.post("/api/trail/{row_id}/like")
async def api_trail_like(
    row_id: str,
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """#1072: mark a moment good, or clear it. {"liked": true}

    A like is not a bookmark: the material behind it goes to the FRONT
    of the draw and stops resting, so what worked once is reached for
    again."""
    require_auth(authorization)
    try:
        payload = await request.json()
    except Exception:  # noqa: BLE001
        payload = {}
    liked = bool((payload if isinstance(payload, dict) else {})
                 .get("liked", True))
    return trail_like(str(row_id), liked)


@app.get("/api/surplus")
async def api_surplus() -> dict[str, Any]:
    """#1083: what being ahead is currently buying the show.

    Zero until the reserve passes 60% of its own target, so this can
    never be the reason anything falls behind - the whole lever lives
    above the safe line."""
    return surplus_state()


@app.get("/api/stopgap")
async def api_stopgap() -> dict[str, Any]:
    """#1080: the stop-gap - piper on the non-cast seats when the show
    is losing.

    `level` is what is in force; `manual` is the operator's switch and
    `auto` the station's own reading. It is a ratchet - the higher of
    the two wins - so turning the switch off never overrules the
    station's judgement that it is drowning."""
    return speed_state()


@app.post("/api/stopgap")
async def api_stopgap_set(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """#1080: {"mode": "off"|"brisk"|"fast"|"emergency"}"""
    require_auth(authorization)
    payload = await request.json()
    want = str((payload if isinstance(payload, dict) else {})
               .get("mode") or "").lower()
    if want not in SPEED_LEVELS:
        raise HTTPException(status_code=400,
                            detail="off, brisk, fast or emergency")
    got = load_settings()
    got.setdefault("dj", {})["speed_mode"] = want
    save_settings(got)
    pipeline_log("lookahead",
                 f"(#1080) the operator set the stop-gap to {want}")
    return speed_state()


@app.get("/api/hour-owes")
async def api_hour_owes() -> dict[str, Any]:
    """#1085: what this hour still owes, worst first, as a share of what
    each road owns - which is what the preparer now builds against."""
    rows = hour_owes()
    return {
        "at": time.time(), "rows": rows, "acting_on": len(rows),
        "horizon_minutes": int(PREP_DEADLINE_WINDOW / 60),
        "say": ((f"{len(rows)} road(s) have entries with nothing written: "
                 + ", ".join(f"{r['label']} {r['entries']}/{r['owns']}"
                             for r in rows[:5]))
                if rows else "every entry this hour has something behind "
                             "it"),
    }


# --- 2026-09-10: THE DIRECTOR'S ROOM ------------------------------------
#
# "I need an hourly script of each segment able to be reviewed where I can
#  give notes and pointers that dictate how the next segment is generated of
#  that type. I want full directorial capabilities with assisting the
#  scripting process and see how a segment is planned in advance."
#
# One read that answers, for every entry of an hour, the four questions a
# director actually asks:
#
#   WHAT IS THIS SEGMENT   - the entry, its minutes, its standing prompt
#   WHAT IS IT GOING TO BE - the script System2 has bound to it, if any,
#                            or the drafts standing behind it, or nothing
#   WHAT DID IT TURN OUT   - what actually aired inside its window
#   WHAT HAVE I SAID ABOUT IT - the direction in force, standing and one-shot
#
# The hour is read from System2's own plan when System2 owns the clock, so
# the room shows the plan the station is actually going to run rather than
# the sheet it was configured from - those two have been different all night
# and the difference is the thing worth seeing.
#
# Every read is defensive: an hour that cannot be built comes back as an
# empty running order with the reason in `why`, because a director's room
# that 500s is a director's room nobody opens.

# The measured cost of turning text into audio on this box, from the
# station's own render ledger: seconds_of_engine = 2.97 + 1.05 * seconds
# of finished audio. The marginal term is ABOVE ONE, which is why an hour
# scheduled at 56 minutes of talk cannot be voiced inside the hour and why
# the longest-round road starves first.
DIRECTOR_RENDER_FIXED = 2.97
DIRECTOR_RENDER_RATE = 1.05


def _director_aired(start: float, deadline: float) -> list[dict[str, Any]]:
    """What actually went out inside one entry's window."""
    rows: list[dict[str, Any]] = []
    try:
        with _AIRLOG_LOCK:
            live = list(_AIRLOG_INDEX.values())
    except Exception:  # noqa: BLE001
        live = []
    for row in live:
        at = float(row.get("air_at") or 0)
        if not at or not start <= at < deadline:
            continue
        # 2026-09-10: AN AIR TIME IS NOT AN AIRING. A staged burst writes an
        # ESTIMATED air_at for every turn the moment it is prepared, so a
        # window read on air_at alone counts rows that never sounded -
        # measured here on the first read of this endpoint: 359 rows and
        # 2,442 seconds of "air" inside a 240-second entry, five different
        # speakers stamped inside the same second. That is the same two-
        # clocks mistake the booth feed was making, in a room built to
        # explain the booth feed. `aired` is the station's own answer to
        # "did this sound": box, stream or both. Anything else is a plan.
        if str(row.get("aired") or "") not in AIRLOG_AIRED:
            continue
        rows.append({"at": at, "who": str(row.get("who") or ""),
                     "name": str(row.get("name") or ""),
                     "kind": str(row.get("kind") or ""),
                     "round": str(row.get("round") or ""),
                     "seconds": float(row.get("seconds") or 0),
                     "source": str(row.get("source") or ""),
                     "line": str(row.get("id") or ""),
                     "text": str(row.get("text") or "")[:600]})
    rows.sort(key=lambda r: r["at"])
    return rows


def _director_script(slot: dict[str, Any]) -> dict[str, Any]:
    """The words this entry is going to say, and where they came from.

    An ALLOCATION is a decision - this candidate, in this slot - so it is
    the script the room shows. A DRAFT is only a thing that exists and
    might be chosen, so it is counted and its opening quoted, never
    presented as the plan."""
    out: dict[str, Any] = {"turns": [], "seconds": 0.0, "state": "nothing",
                           "candidate": "", "source": "", "drafts": 0,
                           "draft_head": "", "tint": {}}
    try:
        allocations = list(slot.get("allocations") or [])
        drafts = list(slot.get("drafts") or [])
        out["drafts"] = len(drafts)
        if drafts and not allocations:
            head = str((drafts[0] or {}).get("script") or "")
            out["draft_head"] = " ".join(head.split())[:240]
        if not allocations:
            # An edited segment is still THIS segment while it re-records
            # the line that was changed. Show its words and say why it is
            # not bound rather than reporting it as empty.
            try:
                kept = director_segment_row(str(slot.get("id") or ""))
                if kept:
                    kept_entry = dialogue_entry(kept[1]) or {}
                    said = str(kept_entry.get("script") or "")
                    if said.strip():
                        out["state"] = "re-recording an edited line"
                        out["live"] = True
                        out["candidate"] = kept[2]
                        for marker, turn in banter_turns(said):
                            out["turns"].append(
                                {"seat": str(marker or ""),
                                 "who": _director_seat(str(marker or "")),
                                 "text": str(turn or "")[:900]})
                        return out
            except Exception:  # noqa: BLE001
                pass
            out["state"] = "drafts waiting" if drafts else "nothing"
            return out
        picked = (allocations[0] or {}).get("candidate") or {}
        out["candidate"] = str(picked.get("id") or "")
        out["seconds"] = float(picked.get("seconds") or 0)
        out["state"] = "bound"
        src = picked.get("source") or {}
        if isinstance(src, dict):
            out["source"] = str(src.get("caller_name")
                                or src.get("prep_name") or "")
        # 2026-09-10: THE LIVE ENTRY, NOT THE CANDIDATE'S SNAPSHOT.
        #
        # A candidate carries the script as it stood when the candidate was
        # written; the row on the shelf is what actually gets rendered and
        # dispatched. Normally identical - but the moment the operator
        # rewrites a turn they diverge, and reading the snapshot here meant
        # the room showed the OLD words back to the person who had just
        # changed them, and then refused their next edit on that turn
        # because the `was` it handed back no longer matched. Measured on
        # the first live edit. The room is meant to be one-to-one with what
        # is going to air, so it reads what is going to air.
        script = str(picked.get("script") or "")
        try:
            live_row = director_segment_row(str(slot.get("id") or ""))
            if live_row:
                live_entry = dialogue_entry(live_row[1]) or {}
                if str(live_entry.get("script") or "").strip():
                    script = str(live_entry["script"])
                    out["live"] = True
                # 2026-09-10: WHAT THE CRYSTAL DID, for the second gate.
                # "I want to perfect the script before we even get to the
                # tinting phase, and then we start perfecting the tint as
                # well" - so the room has to be able to say whether the
                # words on screen are the tinted ones or the plain ones,
                # and how much of the round the crystal actually reached.
                tinted = str(live_entry.get("script_tinted") or "").strip()
                report = live_entry.get("tint")
                cov = (report or {}).get("coverage") if isinstance(
                    report, dict) else {}
                out["tint"] = {
                    "is_tinted": bool(tinted and tinted == script.strip()),
                    "has_tinted_take": bool(tinted),
                    "covered": int((cov or {}).get("covered") or 0),
                    "eligible": int((cov or {}).get("eligible") or 0),
                    "target": int((cov or {}).get("target") or 0),
                    "met": bool((cov or {}).get("met")),
                    "must_flow": bool(tint_must_flow(str(slot.get("kind")
                                                        or ""))),
                }
        except Exception:  # noqa: BLE001
            pass
        for marker, said in banter_turns(script):
            out["turns"].append({"seat": str(marker or ""),
                                 "who": _director_seat(str(marker or "")),
                                 "text": str(said or "")[:900]})
    except Exception:  # noqa: BLE001
        pass
    return out


def _director_seat(marker: str) -> str:
    """The same mapping speak_turns uses, so the room names the seat the
    listener is going to hear rather than the letter the model wrote."""
    one = str(marker or "").strip().upper()[:1]
    try:
        if one == "C":
            return "the caller"
        if one == "E":
            return "the second caller"
        if one == "D":
            return str(dj_settings().get("third_name") or "the third chair")
        if one == "B":
            return booth_actor_name("cohost") or "the co-host"
        return booth_actor_name("dj") or "the host"
    except Exception:  # noqa: BLE001
        return one or "?"


def director_room(which: int = 0) -> dict[str, Any]:
    """The hourly script, entry by entry. `which` is 0 for the hour on air
    and 1 for the one after it."""
    now = time.time()
    out: dict[str, Any] = {"at": now, "hour": "", "entries": [],
                           "sheet": {}, "why": "", "engine": {},
                           "hours_available": 0}
    try:
        out["sheet"] = director_sheet()
    except Exception:  # noqa: BLE001
        out["sheet"] = {"kinds": {}}
    plan_hours: list[dict[str, Any]] = []
    try:
        runtime = globals().get("_system2")
        if runtime and runtime().enabled:
            plan_hours = list(runtime().status().get("hours") or [])
    except Exception:  # noqa: BLE001
        plan_hours = []
    out["hours_available"] = len(plan_hours)
    if not plan_hours:
        # System2 is off, or has not planned yet. Fall back to the sheet
        # itself so the room still shows the running order and its notes -
        # it simply cannot say what is bound to each entry, because with
        # System2 off nothing is bound in advance.
        try:
            store = schedule_read()
            name = schedule_preset_now(store)
            rows = [s for s in ((store.get("presets") or {}).get(name) or [])
                    if s.get("enabled", True)]
            out["hour"] = _sched_hour_key()
            out["why"] = ("System2 has not planned an hour, so this is the "
                          "configured running order rather than the plan "
                          "the station is going to run")
            at = 0.0
            for ordinal, slot in enumerate(rows):
                owns = max(0.25, float(slot.get("minutes") or 3)) * 60.0
                kind = str(slot.get("kind") or "")
                out["entries"].append({
                    "ordinal": ordinal, "kind": kind,
                    "label": str(slot.get("label") or kind),
                    "slot_id": str(slot.get("id") or ""),
                    "occurrence": "", "minutes": owns / 60.0,
                    "start": 0.0, "deadline": 0.0, "state": "unplanned",
                    "notes": str(slot.get("notes") or ""),
                    "prompt": str(schedule_prompt_for(store, slot) or "")[:1200],
                    "script": {"turns": [], "state": "nothing", "drafts": 0},
                    "aired": [], "aired_seconds": 0.0,
                    "direction": _director_direction(
                        kind, str(slot.get("id") or ""), ""),
                    # Same shape as the planned path, so the room never has
                    # to ask which branch built a row.
                    "review": {"approved": False, "edits": 0,
                               "tint_approved": False,
                               "aired_unapproved": False,
                               "state": "unplanned"},
                    "beats": director_beats(kind, str(slot.get("id") or "")),
                })
                at += owns
        except Exception as exc:  # noqa: BLE001
            out["why"] = f"the running order could not be read: {exc}"[:200]
        return out
    # #1179: THE HOUR ON AIR IS THE ONE THE CLOCK IS IN, not the first
    # one still sitting in the plan. A finished hour stays in that list,
    # so after the rollover `hour=0` was answering about the hour that had
    # just ended - and every coverage check taken through this room was
    # quietly about the past. See the note in the patch.
    def _hour_span(row: Any) -> tuple[float, float]:
        """When this planned hour opens and closes, off its own slots."""
        try:
            slots = list((row or {}).get("slots") or [])
            opens = min(float(x.get("start") or 0) for x in slots
                        if float(x.get("start") or 0) > 0)
            shuts = max(float(x.get("deadline") or 0) for x in slots)
            return opens, shuts
        except Exception:  # noqa: BLE001
            return 0.0, 0.0

    _base = 0
    try:
        _spans = [(_hour_span(h), i) for i, h in enumerate(plan_hours)]
        _live = [i for (opens, shuts), i in _spans
                 if opens and opens <= now <= shuts]
        if _live:
            _base = _live[0]
        else:
            # Between plans, or ahead of one: the soonest hour that has
            # not already ended.
            _ahead = sorted(((shuts, i) for (opens, shuts), i in _spans
                             if shuts and shuts > now))
            if _ahead:
                _base = _ahead[0][1]
    except Exception:  # noqa: BLE001
        _base = 0
    which = max(0, min(len(plan_hours) - 1, _base + int(which or 0)))
    plan = plan_hours[which]
    out["hour"] = str(plan.get("id") or "")
    talk_seconds = 0.0
    for slot in list(plan.get("slots") or []):
        kind = str(slot.get("kind") or "")
        start = float(slot.get("start") or 0)
        deadline = float(slot.get("deadline") or 0)
        aired = _director_aired(start, deadline)
        heard = sum(r["seconds"] for r in aired)
        # #1184: WHOSE AIR WAS IT. _director_aired filters on time and on
        # the aired state, never on the road, so "heard" counts the
        # previous segment running long just as readily as this entry's
        # own material - and one second of anything marked the entry
        # aired. See the patch note: the manager window took 92s of
        # track talk and ad tail, reported "aired", and put out none of
        # its own 25 bindable rounds.
        own = sum(r["seconds"] for r in aired
                  if kind in (str(r.get("round") or ""), str(r.get("kind") or "")))
        # A record window airs MUSIC, which carries no round in the air
        # log, so the per-road test cannot speak for it - it keeps the
        # old verdict.
        _own_counts = kind not in ("record",)
        script = _director_script(slot)
        if start <= now < deadline:
            state = "on air"
        elif deadline <= now:
            if not _own_counts:
                state = "aired" if heard > 1.0 else "went by with nothing"
            elif own > 1.0:
                state = "aired"
            elif heard > 1.0:
                _took: dict[str, float] = {}
                for _r in aired:
                    _rd = str(_r.get("round") or _r.get("kind") or "")
                    if _rd and _rd != kind:
                        _took[_rd] = _took.get(_rd, 0.0) + float(
                            _r.get("seconds") or 0)
                if _took:
                    _worst = max(_took, key=lambda k: _took[k])
                    state = ("went by - %s aired instead"
                             % SHELF_LABEL.get(_worst, _worst))
                else:
                    state = "went by with nothing of its own"
            else:
                # EVERY branch must leave `state` set: `state` is reused
                # across loop iterations, so falling through here does not
                # raise on the second slot - it silently reports the
                # PREVIOUS entry's verdict, which is worse than a crash.
                state = "went by with nothing"
        elif script["state"] == "bound":
            state = "planned"
        elif script["state"] == "re-recording an edited line":
            # Not "nothing behind it": there IS something behind it, it is
            # the operator's own rewrite, and it is being recorded.
            state = "re-recording your edit"
        elif script["drafts"]:
            state = "drafts waiting"
        else:
            state = "nothing behind it"
        if kind != "record":
            talk_seconds += max(0.0, deadline - start)
        out["entries"].append({
            "ordinal": int(slot.get("ordinal") or 0),
            "kind": kind,
            # #1184: what this entry ITSELF put on the air, beside the
            # aired_seconds that counts everything overlapping it.
            "own_seconds": round(own, 1),
            "label": str(slot.get("label") or kind),
            "slot_id": str(slot.get("template_id") or slot.get("id") or ""),
            "occurrence": str(slot.get("id") or ""),
            "minutes": max(0.0, deadline - start) / 60.0,
            "start": start, "deadline": deadline,
            "state": state,
            "notes": str(slot.get("notes") or ""),
            "prompt": str(slot.get("prompt") or "")[:1600],
            "script": script,
            "aired": aired,
            "aired_seconds": round(heard, 1),
            "direction": _director_direction(
                kind, str(slot.get("template_id") or ""),
                str(slot.get("id") or "")),
            "review": script_state(str(slot.get("id") or "")),
            "beats": director_beats(kind, str(slot.get("id") or "")),
        })
    # WHAT THE HOUR COSTS TO VOICE. The room says this out loud because it
    # is the reason the long-round roads starve: the marginal render term
    # is above one, so an hour scheduled wall-to-wall with talk cannot be
    # rendered inside the hour however the work is ordered.
    entries = len(out["entries"]) or 1
    engine = DIRECTOR_RENDER_FIXED * entries + DIRECTOR_RENDER_RATE * talk_seconds
    out["engine"] = {
        "talk_seconds": round(talk_seconds, 1),
        "engine_seconds": round(engine, 1),
        "hour_seconds": 3600.0,
        "load": round(engine / 3600.0, 3),
        "say": ("this hour asks for %.0f min of voiced talk, which costs "
                "about %.0f min of engine on one lane against 60 min of "
                "clock" % (talk_seconds / 60.0, engine / 60.0)),
    }
    return out


def _director_direction(kind: str, slot_id: str,
                        occurrence: str) -> dict[str, Any]:
    """The direction in force on one entry, and what it will look like."""
    try:
        standing = director_notes(kind, "standing")
        one_shot = [r for r in director_notes(kind, "next")
                    if not r.get("occurrence")
                    or str(r.get("occurrence")) == str(occurrence)]
        return {"standing": [{"id": r["id"], "text": r["text"],
                              "used": int(r.get("used") or 0),
                              "at": r.get("at")} for r in standing],
                "next": [{"id": r["id"], "text": r["text"],
                          "slot_id": r.get("slot_id"),
                          "occurrence": r.get("occurrence"),
                          "at": r.get("at")} for r in one_shot],
                "clause": director_clause(kind, slot_id, occurrence)}
    except Exception:  # noqa: BLE001
        return {"standing": [], "next": [], "clause": ""}


# #1167: the most of the ledger's tail that is ever read, and how long an
# answer is kept. Both exist to make this cost the same on a log of any
# size - see the note in the patch that added them.
AIRED_TAIL_BYTES = 4 * 1024 * 1024
_AIRED_MEMO: dict[str, Any] = {"key": "", "at": 0.0, "value": []}


def airlog_tail_rows(path: Any, since: float) -> list[dict[str, Any]]:
    """Rows at or after `since`, read backwards from the end of a ledger.

    The file is append-ordered by time, so a window ending at now is
    always at the end of it: this reads a bounded tail and parses only
    that. The first line of the tail is dropped - a byte offset lands
    mid-line and half a row is not a row."""
    out: list[dict[str, Any]] = []
    try:
        size = path.stat().st_size
        with path.open("rb") as handle:
            if size > AIRED_TAIL_BYTES:
                handle.seek(size - AIRED_TAIL_BYTES)
                handle.readline()          # the partial line at the seam
            blob = handle.read()
    except Exception:  # noqa: BLE001
        return out
    for line in blob.decode("utf-8", "ignore").splitlines():
        if not line.startswith("{"):
            continue
        try:
            row = json.loads(line)
        except Exception:  # noqa: BLE001
            continue
        if not isinstance(row, dict):
            continue
        if float(row.get("air_at") or row.get("at") or 0) >= since:
            out.append(row)
    return out


def director_aired_hours(back: int = 4, most: int = 1400
                         ) -> list[dict[str, Any]]:
    """#1167: what actually went out, as far back as `back` hours, grouped
    into hours and ordered as spoken.

    The live index is the tail and the file is the rest; rows are keyed by
    line id so a line that is in both is counted once. Disk - call from a
    thread."""
    horizon = max(0.0, float(back)) * 3600.0
    now = time.time()
    since = now - horizon
    rows: dict[str, dict[str, Any]] = {}

    def take(row: Any) -> None:
        if not isinstance(row, dict):
            return
        at = float(row.get("air_at") or row.get("at") or 0)
        if not at or at < since or at > now + 60:
            return
        # See the note in the patch: a plan is not an airing.
        if str(row.get("aired") or "") not in AIRLOG_AIRED:
            return
        text = str(row.get("text") or "").strip()
        if not text:
            return
        key = str(row.get("id") or "") or ("%.3f|%s" % (at, text[:40]))
        rows[key] = {
            "at": at, "who": str(row.get("who") or ""),
            "name": str(row.get("name") or ""),
            "kind": str(row.get("kind") or ""),
            "round": str(row.get("round") or ""),
            "seconds": round(float(row.get("seconds") or 0), 2),
            "line": str(row.get("id") or ""),
            "text": text[:700],
        }

    try:
        # #1167: the tail, not the whole ledger. `airlog_jsonl_read` walks
        # every line and json.loads holds the GIL; measured on this log it
        # cost 18.8 seconds and a 9-second stall on a poll that repeats
        # every twelve. The ledger's own time key is `air_at`.
        for row in airlog_tail_rows(AIR_LOG_PATH, since):
            take(row)
    except Exception:  # noqa: BLE001
        pass                    # the live tail alone is still a script
    try:
        with _AIRLOG_LOCK:
            live = list(_AIRLOG_INDEX.values())
        for row in live:
            take(row)
    except Exception:  # noqa: BLE001
        pass
    ordered = sorted(rows.values(), key=lambda r: r["at"])[-int(most or 1400):]
    del rows
    hours: list[dict[str, Any]] = []
    for row in ordered:
        stamp = time.strftime("%Y-%m-%d %H:00", time.localtime(row["at"]))
        if not hours or hours[-1]["hour"] != stamp:
            hours.append({"hour": stamp,
                          "at": row["at"] - (row["at"] % 3600),
                          "lines": []})
        hours[-1]["lines"].append(row)
    for hour in hours:
        hour["seconds"] = round(
            sum(float(r.get("seconds") or 0) for r in hour["lines"]), 1)
        hour["count"] = len(hour["lines"])
    return hours


@app.get("/api/director/order")
async def api_director_order(
    hours: float = 2.0,
    most: int = 40,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """#1201: did each conversation go out in the order it was written?

    Groups the air log by SCRIPT (`sid`) and reads the turn numbers in
    the order they actually sounded. A round is in order when its turns
    ascend; anything else is named - a JUMP (a turn out of sequence), a
    REPEAT (one heard twice) and a HOLE (one that never sounded at all).

    Rounds written before #1201 carry no sid or turn and are reported as
    `unmeasurable` rather than counted as healthy, because a surface that
    silently scores missing data as a pass is how "everything aired" got
    believed for a fortnight."""
    require_read_auth(authorization)

    def work() -> dict[str, Any]:
        now = time.time()
        since = now - max(0.1, float(hours or 2.0)) * 3600.0
        try:
            with _AIRLOG_LOCK:
                live = list(_AIRLOG_INDEX.values())
        except Exception:  # noqa: BLE001
            live = []
        rows = [r for r in live
                if float(r.get("air_at") or 0) >= since
                and str(r.get("aired") or "") in AIRLOG_AIRED]
        rows.sort(key=lambda r: float(r.get("air_at") or 0))
        by_sid: dict[str, list[dict[str, Any]]] = {}
        loose = 0
        for r in rows:
            sid = str(r.get("sid") or "")
            if not sid or r.get("turn") is None:
                loose += 1
                continue
            by_sid.setdefault(sid, []).append(r)
        out: list[dict[str, Any]] = []
        tally = {"in_order": 0, "jumped": 0, "repeated": 0, "holed": 0}
        for sid, got in by_sid.items():
            turns = [int(r.get("turn") or 0) for r in got]
            total = max([int(r.get("turns") or 0) for r in got] + [0])
            jumps = [(turns[i - 1], turns[i]) for i in range(1, len(turns))
                     if turns[i] <= turns[i - 1]]
            repeats = sorted({t for t in turns if turns.count(t) > 1})
            holes = ([t for t in range(total) if t not in set(turns)]
                     if total else [])
            if jumps:
                tally["jumped"] += 1
            elif repeats:
                tally["repeated"] += 1
            elif holes:
                tally["holed"] += 1
            else:
                tally["in_order"] += 1
            out.append({
                "sid": sid, "road": str(got[0].get("round") or ""),
                "at": round(float(got[0].get("air_at") or 0), 1),
                "heard": len(got), "of": total,
                "order": turns[:40],
                "jumps": [{"after": a, "then": b} for a, b in jumps][:8],
                "repeated": repeats[:8], "holes": holes[:12],
                "verdict": ("jumped" if jumps else "repeated" if repeats
                            else "holes" if holes else "in order"),
            })
        out.sort(key=lambda r: -float(r.get("at") or 0))
        rounds = sum(tally.values())
        return {
            "at": now, "hours": hours, "rounds": rounds,
            "tally": tally, "unmeasurable_lines": loose,
            "rows": out[:max(0, int(most))],
            "say": (("%d conversation(s) measured: %d in order, %d jumped, "
                     "%d repeated a turn, %d had holes."
                     % (rounds, tally["in_order"], tally["jumped"],
                        tally["repeated"], tally["holed"]))
                    + ((" %d aired line(s) carry no script position - they "
                        "were written before #1201 and cannot be judged."
                        % loose) if loose else "")),
        }

    return await asyncio.to_thread(work)


@app.get("/api/director/aired")
async def api_director_aired(back: int = 4, most: int = 1400
                             ) -> dict[str, Any]:
    """#1167: the broadcast as a script - what actually sounded, in order,
    grouped by hour, as far back as the air log goes.

    Off the loop: the file read and the index fold both hold the GIL."""
    span = max(1, min(72, int(back or 4)))
    cap = max(50, min(6000, int(most or 1400)))
    key = "%d|%d" % (span, cap)
    now = time.time()
    if _AIRED_MEMO["key"] == key and now - float(_AIRED_MEMO["at"]) < 10.0:
        hours = _AIRED_MEMO["value"]
    else:
        hours = await asyncio.to_thread(director_aired_hours, span, cap)
        _AIRED_MEMO.update({"key": key, "at": now, "value": hours})
    return {"at": time.time(), "hours": hours,
            "back_hours": span,
            "say": ("%d hour(s) of broadcast, %d line(s) that actually "
                    "sounded" % (len(hours),
                                 sum(h["count"] for h in hours)))}


@app.get("/api/director")
async def api_director(hour: int = 0) -> dict[str, Any]:
    """The hourly script. Off the loop: it folds the air-log index and
    serialises a whole System2 plan, both of which hold the GIL."""
    return await asyncio.to_thread(director_room, int(hour or 0))


DIRECTOR_ENGINES = ("piper", "xtts", "f5", "voxtral")


def director_segment_row(occurrence: str) -> tuple[str, Any, str] | None:
    """The (kind, shelf row, candidate id) a System2 occurrence is bound to."""
    try:
        runtime = globals().get("_system2")
        if not runtime:
            return None
        live = runtime()
        for hour in list(live._plans) + list(live._event_plans):
            for slot in hour.get("slots") or []:
                if str(slot.get("id") or "") != str(occurrence):
                    continue
                for allocation in slot.get("allocations") or []:
                    picked = (allocation or {}).get("candidate") or {}
                    row = live._rows.get(str(picked.get("id") or ""))
                    if row:
                        return (row[0], row[1], str(picked.get("id") or ""))
                break
        # No allocation standing. An EDITED segment is the ordinary reason:
        # re-keying a take makes the round a pantry miss, so it leaves the
        # ready set until that one line is recorded and System2 drops the
        # allocation meanwhile. The desk remembers which candidate the
        # occurrence was bound to, so the segment can still be found - and
        # edited again - while it is away being finished. Without this the
        # room goes blank on the segment the moment you change it, which
        # reads as the edit having destroyed it.
        remembered = script_candidate(str(occurrence))
        if remembered:
            row = live._rows.get(remembered)
            if row:
                return (row[0], row[1], remembered)
    except Exception:                              # noqa: BLE001
        return None
    return None


def director_fork_kept(kind: str, row: dict[str, Any],
                       entry: dict[str, Any]) -> tuple[dict[str, Any],
                                                       dict[str, Any]]:
    """Copy a kept round into a fresh, writable one.

    A frozen or already-aired round is SHARED material - the retirement
    desk's standing rule is that finished work is not destroyed - and a
    frozen row is restored from its kept copy, so an edit written into one
    is accepted and then silently thrown away. That was measured: the
    first live rewrite this desk ever took vanished within the hour.

    So the kept round is left exactly as it is and the operator's rewrite
    becomes a NEW take standing beside it. What the fork drops is every
    mark that says "this one is finished": its identity, its innings, its
    freeze and its keep. What it carries is the script, the cast, the
    voices and the takes - so only the line that was actually changed has
    to be recorded, which is the whole economy of editing here.

    The fork does NOT capture the occurrence that was being looked at.
    That airing is already rendered and bound; System2 picks the fork up
    on its next sync and it stands for the next one. Saying so plainly is
    better than pretending an edit can reach a segment that is already on
    its way out of the door."""
    fork_row = copy.deepcopy(row)
    fork_entry = dialogue_entry(fork_row)
    if fork_entry is None:                  # a row shape with no entry
        fork_entry = fork_row
    parent = alt_sid_of(kind, row)
    now = time.time()
    # Not the kept item any more: a new identity, no innings, no freeze.
    for key in ("sid", "aired", "aired_at", "tinted_seen_at", "keep_until",
                "carried", "stock_used_by", "review_ids",
                "review_shelf_before", "review_shelf_pending"):
        fork_row.pop(key, None)
        fork_entry.pop(key, None)
    fork_entry.pop("frozen", None)
    fork_row["at"] = now
    fork_entry["at"] = now
    # The writing room has already been paid for - this is the operator's
    # own wording, and nothing may hand it back to the model to reword.
    fork_entry["freshened"] = True
    fork_entry["director_fork_of"] = parent
    fork_entry["director_forked_at"] = now
    try:
        fork_row["expires_at"] = stock_expires_at(kind, fork_row)
    except Exception:                              # noqa: BLE001
        fork_row.pop("expires_at", None)
    _SHELF.setdefault(str(kind), []).append(fork_row)
    try:
        alt_sid(str(kind), fork_row)               # stamp its new identity
    except Exception:                              # noqa: BLE001
        pass
    return fork_row, fork_entry


def director_edit_turn(occurrence: str, index: int, said: str,
                       expect: str = "", sid: str = "") -> dict[str, Any]:
    """Rewrite one turn of a bound segment, and its take with it.

    THE TAKE IS THE HARD PART. `_ready_round_takes` refuses a round whose
    saved performances do not agree with its script, word for word - so
    rewriting `entry["script"]` alone does not edit a segment, it DELETES
    one: the round silently leaves the ready set and never comes back,
    and the operator would see their edit accepted and the segment quietly
    stop appearing. The take has to be re-keyed beside it.

    Takes are content-addressed on `pantry_key(text, voice, engine)`, so
    the new key is a pantry MISS and the round leaves the ready set until
    the keeper's finishing pass re-records that one line - which it already
    does for half-rendered rounds. One line of engine, not a round.

    Matched on TEXT rather than position: `entry["chunks"]` counts padded
    speech chunks and the turn list is not one-to-one with it, so trusting
    an index here would re-key the wrong line's audio. If no take matches,
    the edit is REFUSED and says why - a corrupted round is a worse answer
    than a rejected edit."""
    said = " ".join(str(said or "").split())
    if not said:
        raise HTTPException(400, "an empty turn is a deletion, not an edit")
    kind, row, candidate = director_resolve(occurrence, sid)
    entry = dialogue_entry(row)
    if not entry or not str(entry.get("script") or "").strip():
        raise HTTPException(409, "that segment has no script to edit")
    # 2026-09-10: DO NOT WRITE INTO KEPT MATERIAL.
    #
    # Measured the first time this ran against the live station: the edit
    # was applied, persisted, read back off the shelf - and an hour later
    # the row held its ORIGINAL words again and the rewrite had never
    # aired. The round was `frozen` and had already gone out at 20:51 the
    # night before; it was a KEPT round on its second innings, and a
    # frozen row is restored from the kept copy. So the operator's rewrite
    # was accepted, acknowledged, and silently thrown away - the worst
    # possible outcome, and exactly what an edit surface must never do.
    #
    # A frozen or already-aired round is shared material - the retirement
    # desk's whole rule is that a finished round is not destroyed - so it
    # is FORKED rather than mutated. The kept round stays exactly as it is
    # and the rewrite becomes a new take standing beside it, which is the
    # only way an edit can be both safe and always available: refusing
    # here meant most bound segments could not be edited at all, because
    # most of what the station airs is kept material on a second innings.
    #
    # The fork happens BEFORE the turn is located, so everything below -
    # the turn list, the take match, the re-key - operates on the copy and
    # the kept round is never touched at all.
    forked = False
    if (entry.get("frozen") or row.get("aired") or row.get("aired_at")
            or entry.get("aired_at")):
        row, entry = director_fork_kept(kind, row, entry)
        forked = True
    caller_name = str(entry.get("caller_name") or "")
    turns = banter_turns(str(entry["script"]), caller_name)
    index = int(index)
    if not 0 <= index < len(turns):
        raise HTTPException(400, "there is no turn %d in a %d turn script"
                            % (index, len(turns)))
    marker, was = turns[index]
    was = " ".join(str(was or "").split())
    # The room draws its turns from the CANDIDATE's script, which is a
    # snapshot taken when the candidate was written; this edits the LIVE
    # entry. Normally the same string, but they are two objects and an
    # index that has drifted would re-key a turn the operator never looked
    # at. `expect` is the text the operator actually had in front of them,
    # so a drifted index is refused instead of silently rewriting the
    # wrong line.
    expect = " ".join(str(expect or "").split())
    if expect and expect != was:
        raise HTTPException(
            409, "that segment has changed since you opened it - the turn "
                 "there now reads differently. Re-read the hour and edit "
                 "it again.")
    if was == said:
        return {"ok": True, "changed": False,
                "say": "that is what it already said"}
    spoken_was = " ".join(spoken_text(was).split())
    takes = list(entry.get("takes") or [])
    hit = None
    for take in takes:
        text = " ".join(str(take.get("text") or "").split())
        if text and (text == spoken_was or text == was):
            hit = take
            break
    if hit is None:
        raise HTTPException(
            409, "that turn has no matching recording, so editing it would "
                 "leave the round unusable rather than changed. It can be "
                 "edited once the segment has been recorded.")
    voice = str(hit.get("voice") or "")
    engine = next((e for e in DIRECTOR_ENGINES
                   if pantry_key(str(hit.get("text") or ""), voice, e)
                   == str(hit.get("key") or "")), "")
    if not engine:
        raise HTTPException(409, "that recording's engine cannot be "
                                 "identified, so its replacement could not "
                                 "be keyed")
    spoken_now = " ".join(spoken_text(said).split())
    # The script, rebuilt with this one turn replaced and every other turn
    # exactly as it was.
    rebuilt = []
    for at, (mark, text) in enumerate(turns):
        rebuilt.append("%s: %s" % (mark, said if at == index
                                   else " ".join(str(text).split())))
    entry["script"] = "\n".join(rebuilt)
    hit["text"] = spoken_now
    hit["key"] = pantry_key(spoken_now, voice, engine)
    # `freshened` is a FLAG - "the model visit has been paid for" - not a
    # stamp. Set truthy so nothing hands this rewritten round back to the
    # writing room to be reworded; a float would have worked by accident.
    entry["freshened"] = True
    # Both stores keep this entry by reference, so the mutation above is
    # already live; these only ask for it to be written down. The shelf is
    # a 13.5 MB dump (#1156) - _pantry_save asks the flusher THREAD rather
    # than serialising it here, which is the whole point of that change and
    # must not be undone by a panel action doing it inline.
    try:
        _larder_save()
    except Exception:                              # noqa: BLE001
        pass
    try:
        _pantry_save()
    except Exception:                              # noqa: BLE001
        pass
    edit = script_note_edit(script_key(sid) if sid else occurrence,
                            kind, index, was, said,
                            seat=str(marker or ""), candidate=candidate)
    pipeline_log("action", "the director rewrote a %s turn - that line "
                           "re-records, the rest of the round stands" % kind,
                 extra="was: %s\nnow: %s" % (was[:300], said[:300]))
    return {"ok": True, "changed": True, "edit": edit,
            "kind": kind, "seat": marker, "forked": forked,
            "state": script_state(script_key(sid) if sid else occurrence),
            "say": ("that round had already aired, so your rewrite is a NEW "
                    "take standing beside it - the kept one is untouched. "
                    "One line records and it joins the rotation."
                    if forked else
                    "rewritten - that one line re-records, the round comes "
                    "back as soon as it has")}


@app.post("/api/director/segment/{occurrence}/turn")
async def api_director_edit(occurrence: str,
                            payload: dict[str, Any]) -> dict[str, Any]:
    """Rewrite one turn of a bound segment."""
    return await asyncio.to_thread(
        director_edit_turn, occurrence,
        int((payload or {}).get("index") or 0),
        str((payload or {}).get("text") or ""),
        str((payload or {}).get("was") or ""))


@app.post("/api/director/segment/{occurrence}/approve")
async def api_director_approve(occurrence: str,
                               payload: dict[str, Any] | None = None
                               ) -> dict[str, Any]:
    """Approve the script, or the tint, for one segment.

    Approval UPGRADES a segment; it never holds one. At an engine load of
    0.997 a gate that made segments wait for a person would produce silence
    rather than better radio, so an unapproved segment airs exactly as it
    does now and is stamped as having gone out unreviewed."""
    tint = bool((payload or {}).get("tint"))
    state = script_approve(occurrence, str((payload or {}).get("who")
                                           or "operator"), tint=tint)
    return {"ok": True, "state": state,
            "say": "tint approved" if tint else "script approved"}


@app.get("/api/director/lessons")
async def api_director_lessons(kind: str = "", most: int = 40
                               ) -> dict[str, Any]:
    """Every rewrite the operator has made, newest first.

    `was` is what the station wrote unprompted and `now` is what the person
    who owns it wanted said, in the same seat of the same kind of segment.
    That pair is the highest-signal thing the station can be told about how
    it is meant to sound, and it is a by-product of the work rather than a
    thing anybody has to sit down and author."""
    rows = await asyncio.to_thread(script_lessons, kind, int(most or 40))
    return {"at": time.time(), "kind": kind, "rows": rows,
            "say": "%d rewrite(s) on the book" % len(rows)}


# --- 2026-09-10: MAKING THE HOUR FIT THE ENGINE --------------------------
#
#    "you have the right to experiment with however you have to in order to
#     make sure all of the segments take place over the course of the entire
#     hour."
#
# THE ARITHMETIC THAT DECIDES THIS. Rendering costs 2.97s of engine plus
# 1.05x the finished audio, on one lane, measured on this box. The marginal
# term is ABOVE ONE, so a minute of talk costs slightly more than a minute
# to make. The canonical hour asks for 56 minutes of voiced talk out of 60,
# which is ~60 minutes of engine against 60 minutes of clock: load 0.997,
# no margin at all. At that load the hour cannot absorb a slow render, a
# refused tint or a restart, and what actually happens is that the road with
# the LONGEST rounds loses - measured, callers: 256 live candidates and
# three ready, 251 of them written but never recorded.
#
# So the hour was not failing to run its segments because of a scheduling
# fault. It was over-subscribed, and a plan that cannot be made is not a
# plan. Every segment KIND stays - the ask is that they all happen, not that
# there are fewer of them - and the minutes come down until the hour fits,
# with the reclaimed time going to records, which cost no engine at all.
#
# Nothing here edits the running order in place. It writes a NEW preset and
# leaves the original untouched, so the whole change is one click to undo.

HEADROOM_TARGET = 0.78          # of the hour's engine; ~13 min of slack
HEADROOM_FLOOR = 2.0            # minutes: shorter than this is not a segment
# Roads whose minutes are not scaled. Ads are largely produced spots and
# cached reads, so their airtime is not a fresh render; the memos from
# upstairs are two minutes twice an hour and are the thing the operator
# most wants to hear.
HEADROOM_KEEP = ("ad", "manager", "station_id")


def headroom_cost(slots: list[dict[str, Any]]) -> float:
    """Engine seconds to voice one pass of this running order."""
    talk = sum(max(0.0, float(s.get("minutes") or 0)) * 60.0
               for s in slots
               if s.get("enabled", True) and str(s.get("kind")) != "record")
    return DIRECTOR_RENDER_FIXED * max(1, len(slots)) + DIRECTOR_RENDER_RATE * talk


def headroom_plan(slots: list[dict[str, Any]],
                  target: float = HEADROOM_TARGET) -> dict[str, Any]:
    """Thin a running order until it can actually be voiced.

    Proportional, not surgical: every scalable road gives up the same share
    of its minutes, so the hour keeps its shape and its balance. Floors stop
    a road being scaled into meaninglessness, and everything reclaimed goes
    to the record entries."""
    rows = [dict(s) for s in slots]
    live = [s for s in rows if s.get("enabled", True)]
    was = headroom_cost(live)
    want = max(0.05, float(target)) * 3600.0
    out = {"was_seconds": round(was, 1), "was_load": round(was / 3600.0, 3),
           "target": target, "changed": [], "gave_back": 0.0}
    if was <= want:
        out["say"] = ("the hour already fits - %.0f min of engine against "
                      "60 min of clock" % (was / 60.0))
        out["slots"] = rows
        return out
    scalable = [s for s in live
                if str(s.get("kind")) not in HEADROOM_KEEP
                and str(s.get("kind")) != "record"
                and float(s.get("minutes") or 0) > HEADROOM_FLOOR]
    fixed = was - DIRECTOR_RENDER_RATE * sum(
        float(s.get("minutes") or 0) * 60.0 for s in scalable)
    room = max(0.0, want - fixed)
    have = sum(float(s.get("minutes") or 0) * 60.0 for s in scalable)
    if not scalable or have <= 0:
        out["say"] = ("the hour is over-subscribed and nothing on it can be "
                      "shortened without going under the floor")
        out["slots"] = rows
        return out
    share = max(0.2, min(1.0, room / (DIRECTOR_RENDER_RATE * have)))
    reclaimed = 0.0
    for slot in scalable:
        before = float(slot.get("minutes") or 0)
        after = max(HEADROOM_FLOOR, round(before * share * 2) / 2.0)
        if after >= before:
            continue
        slot["minutes"] = after
        reclaimed += before - after
        out["changed"].append({"id": slot.get("id"), "kind": slot.get("kind"),
                               "label": slot.get("label"),
                               "was": before, "now": after})
    # Everything given up goes to the records, which cost no engine.
    records = [s for s in live if str(s.get("kind")) == "record"]
    if records and reclaimed > 0:
        each = reclaimed / len(records)
        for slot in records:
            slot["minutes"] = round((float(slot.get("minutes") or 0) + each)
                                    * 2) / 2.0
    out["gave_back"] = round(reclaimed, 1)
    now = headroom_cost(live)
    out.update(now_seconds=round(now, 1), now_load=round(now / 3600.0, 3),
               slots=rows)
    out["say"] = ("%.0f min of talk moved to the records: the hour goes from "
                  "%.0f to %.0f min of engine against 60 min of clock, "
                  "load %.2f to %.2f"
                  % (reclaimed, was / 60.0, now / 60.0,
                     was / 3600.0, now / 3600.0))
    return out


DIRECTOR_QUEUE_KINDS = ("caller", "manager", "gallery", "news", "banter",
                        "recap", "track_talk")
DIRECTOR_QUEUE_MOST = 60


def director_resolve(occurrence: str = "",
                     sid: str = "") -> tuple[str, Any, str]:
    """(road, row, candidate) for a segment named either way.

    A script has two names and they are not the same thing. Its SHELF ID
    exists from the moment it is written; its OCCURRENCE only exists once
    an hour has chosen it. Reviewing before the hour chooses is the whole
    point of the queue, so both names reach the same machinery."""
    want = str(sid or "").strip()
    if want:
        kind, row = alt_find(want)
        if row is None:
            raise HTTPException(404, "no script answers to that id - it may "
                                     "have aired and been retired since the "
                                     "list was drawn")
        return str(kind), row, ""
    got = director_segment_row(occurrence)
    if not got:
        raise HTTPException(404, "nothing is bound to that occurrence yet - "
                                 "a segment can be edited once the hour has "
                                 "chosen what fills it")
    return got


def _director_turns(entry: dict[str, Any]) -> list[dict[str, Any]]:
    """One script's turns, with the seat the listener will actually hear
    and whether the crystal has been through each of them."""
    out: list[dict[str, Any]] = []
    caller_name = str(entry.get("caller_name") or "")
    tinted = str(entry.get("script_tinted") or "")
    tinted_turns = {}
    if tinted:
        for at, (mark, said) in enumerate(banter_turns(tinted, caller_name)):
            tinted_turns[at] = " ".join(str(said or "").split())
    for at, (marker, said) in enumerate(
            banter_turns(str(entry.get("script") or ""), caller_name)):
        plain = " ".join(str(said or "").split())
        alt = tinted_turns.get(at, "")
        out.append({"index": at, "seat": str(marker or ""),
                    "who": _director_seat(str(marker or "")),
                    "text": plain,
                    "tinted": alt if alt and alt != plain else "",
                    "is_tinted": bool(alt and alt == plain)})
    return out


def director_prepared(most: int = DIRECTOR_QUEUE_MOST) -> dict[str, Any]:
    """Every script standing on the shelf, newest first, with its state.

    This is what the notification counts. A script is offered for review
    the moment it EXISTS - written and on the shelf - rather than when an
    hour picks it, because the point of reviewing is to change it while
    changing it is still cheap."""
    rows: list[dict[str, Any]] = []
    now = time.time()
    for kind in DIRECTOR_QUEUE_KINDS:
        for row in list(_SHELF.get(kind) or []):
            entry = dialogue_entry(row)
            if not entry or not str(entry.get("script") or "").strip():
                continue
            try:
                sid = alt_sid_of(kind, row)
            except Exception:  # noqa: BLE001
                continue
            if not sid:
                continue
            state = script_queue_state(sid)
            turns = banter_turns(str(entry.get("script") or ""),
                                 str(entry.get("caller_name") or ""))
            tinted = str(entry.get("script_tinted") or "").strip()
            rows.append({
                "sid": sid, "kind": kind,
                "at": float(row.get("at") or entry.get("at") or 0),
                "age": round(now - float(row.get("at")
                                         or entry.get("at") or now), 1),
                "turns": len(turns),
                "seconds": round(float(row.get("seconds") or 0), 1),
                "chars": len(str(entry.get("script") or "")),
                "head": " ".join(str(entry.get("script") or "").split())[:150],
                "is_tinted": bool(tinted
                                  and tinted == str(entry["script"]).strip()),
                "kept": bool(entry.get("frozen")),
                "aired": int(row.get("aired") or 0),
                "review": state,
            })
    rows.sort(key=lambda r: -float(r.get("at") or 0))
    rows = rows[:max(1, int(most))]
    waiting = [r for r in rows
               if not r["review"]["seen"] and not r["kept"] and not r["aired"]]
    return {"at": now, "rows": rows, "waiting": len(waiting),
            "waiting_ids": [r["sid"] for r in waiting],
            "say": ("%d script(s) written and never looked at" % len(waiting)
                    if waiting else "every script on the shelf has been seen")}


def director_road_stock(kind: str) -> dict[str, Any]:
    """What this road is actually holding, counted the way air counts it.

    Written is not recorded and recorded is not available: a round with
    nine of its twenty-two lines cut is no use to an entry that starts in
    four minutes, and a round that aired an hour ago on a road that does
    not reuse is spent whatever its audio says. Those three numbers are
    the whole answer to "why is this segment empty", and until now they
    lived in three different endpoints that disagreed."""
    out = {"kind": str(kind), "rows": 0, "written": 0, "recorded": 0,
           "part": 0, "resting": 0, "spent": 0, "seconds_ready": 0.0,
           "soonest_free": None, "reusable": False}
    try:
        out["reusable"] = str(kind) in SHELF_REUSABLE
        rest = float(shelf_reuse_rest() or 0)
        allowed = int(shelf_innings(str(kind)))
        now = time.time()
        soonest: float | None = None
        def _on_disk(key: Any) -> bool:
            """#1169: is this pantry key's clip really there?"""
            saved = _PANTRY.get(str(key or "")) or {}
            clip = saved.get("clip") or {}
            name = str(clip.get("path") or "").rsplit("/", 1)[-1]
            name = name.split("?", 1)[0]
            return bool(name and (VOICE_MEDIA_DIR / name).is_file())

        for row in road_source(kind):          # #1165: banter is the larder
            entry = dialogue_entry(row)
            # #1169: AN ADVERT READ AND A STATION ID ARE ONE LINE. Neither
            # keeps a dialogue entry - there is no cast and no turns, just
            # words, a voice and a pantry key - so `if entry is None:
            # continue` skipped every row on both roads and the desk
            # reported them empty. Measured on the same shelf in the same
            # breath: this reader said the advert road had 0 rows while
            # the census counted 37 finished ones.
            if entry is None:
                words = str(row.get("text_plain") or row.get("text") or "")
                if not words.strip():
                    continue
                out["rows"] += 1
                out["written"] += 1
                if _on_disk(row.get("key")) or row.get("produced"):
                    out["recorded"] += 1
                    whole = True
                else:
                    whole = False
            else:
                script = str(entry.get("script") or "")
                if not script.strip():
                    continue
                out["rows"] += 1
                out["written"] += 1
                takes = list(entry.get("takes") or [])
                want = int(entry.get("chunks") or 0) or len(takes)
                have = sum(1 for take in takes if _on_disk(take.get("key")))
                whole = bool(want) and have >= want
            if entry is not None:
                if whole:
                    out["recorded"] += 1
                elif have:
                    out["part"] += 1
            aired = int(row.get("aired") or 0)
            since = (now - float(row.get("aired_at") or 0)
                     if row.get("aired_at") else None)
            if aired and not out["reusable"]:
                out["spent"] += 1
                continue
            if aired >= allowed:
                out["spent"] += 1
                continue
            if since is not None and since < rest:
                out["resting"] += 1
                free = now + (rest - since)
                soonest = free if soonest is None else min(soonest, free)
                continue
            if whole:
                out["seconds_ready"] += float(row.get("seconds") or 0)
        out["soonest_free"] = soonest
        out["seconds_ready"] = round(out["seconds_ready"], 1)
    except Exception:                              # noqa: BLE001
        pass
    return out


def director_why(kind: str) -> dict[str, Any]:
    """Why this segment has nothing behind it - in one read.

        "I need to get explanations from the orchestrator of why there
         isn't recordings for these sections."

    The station already decides this, hours early and in daylight - the
    call sheet commits every coming entry to a way of being filled and
    writes down its reasoning. What it did NOT do was put that reasoning
    next to the shelf it was reasoning about, so a `cut` verdict read as
    a shrug. This joins the two: the entry's own verdict, the arithmetic
    behind it, and what the road is actually holding."""
    kind = str(kind or "")
    out: dict[str, Any] = {"kind": kind, "at": time.time()}
    stock = director_road_stock(kind)
    out["stock"] = stock
    # THE PLANNER'S OWN POOL, not a re-derivation of it. Chasing why a road
    # with sixty-four finished recordings bound nothing to its entries cost
    # an hour of reading `_viable`, `_tinted`, `_audio`, the cast profile
    # and the innings cap one at a time and guessing which had said no. The
    # binder itself can be asked, so ask it: this is the exact list
    # commitment_inventory_plan walks, with the exact reason each row is or
    # is not in it.
    try:
        pool = dialogue_stock_items(kind, True, _larder_profile_signature(),
                                    dialogue_tint_required())
        ready_now = [x for x in pool
                     if x.get("ready") and float(x.get("available") or 0) <= 0]
        later = [x for x in pool
                 if x.get("ready") and float(x.get("available") or 0) > 0]
        unready = [x for x in pool if not x.get("ready")]
        out["pool"] = {
            "in_pool": len(pool),
            "ready_now": len(ready_now),
            "ready_now_seconds": round(
                sum(float(x.get("seconds") or 0) for x in ready_now), 1),
            "ready_later": len(later),
            "soonest_available_in": (round(min(
                float(x.get("available") or 0) for x in later), 1)
                if later else None),
            "unready_in_pool": len(unready),
            "dropped": max(0, int(stock.get("written") or 0) - len(pool)),
        }
    except Exception as exc:                       # noqa: BLE001
        out["pool"] = {"error": type(exc).__name__}
    # #1160: and when the pool is EMPTY while the shelf is full, which of
    # the binder's tests is saying no. One number that meant eight things
    # now says which one.
    try:
        out["census"] = dialogue_stock_census(kind)
    except Exception as exc:                       # noqa: BLE001
        out["census"] = {"error": type(exc).__name__}
    try:
        board = commit_board(ahead=24)
    except Exception:                              # noqa: BLE001
        board = []
    mine = [r for r in board if str(r.get("prep") or "") == kind]
    out["entries"] = [{
        "label": r.get("label"), "commit": r.get("commit"),
        "owns_seconds": r.get("owns_seconds"),
        "ready_seconds": r.get("ready_seconds"),
        "short_seconds": r.get("short_seconds"),
        "in_seconds": r.get("in_seconds"),
        "cost": r.get("cost"), "room": r.get("room"),
        "why": r.get("why"),
    } for r in mine[:6]]
    try:
        ledger = {row.get("kind"): row for row in
                  ((prep_state() or {}).get("ledger") or {}).get("tasks") or []}
        task = ledger.get(kind) or {}
        out["task"] = {"count": task.get("count"), "fail": task.get("fail"),
                       "p90_seconds": task.get("p90"),
                       "gain_seconds": task.get("gain_mean"),
                       "rate": task.get("rate")}
    except Exception:                              # noqa: BLE001
        out["task"] = {}
    # THE SENTENCE. Every branch below is a different fault with a
    # different cure, and saying which one it is IS the feature.
    said: list[str] = []
    first = (out["entries"] or [{}])[0]
    if not stock["rows"]:
        said.append("nothing has been written for this road at all")
    else:
        said.append("%d written, %d fully recorded, %d part-recorded"
                    % (stock["written"], stock["recorded"], stock["part"]))
        if stock["spent"]:
            said.append("%d spent (%s)" % (
                stock["spent"],
                "this road does not reuse" if not stock["reusable"]
                else "past %d airings" % shelf_innings(kind)))
        if stock["resting"]:
            when = stock.get("soonest_free")
            said.append("%d resting%s" % (
                stock["resting"],
                (", soonest free in %d min"
                 % max(0, int((when - time.time()) / 60))) if when else ""))
        if not stock["seconds_ready"]:
            said.append("so NOTHING on this road can be bound to an entry "
                        "right now")
        else:
            said.append("%.0fs is free to bind" % stock["seconds_ready"])
    if first.get("commit") == "cut":
        said.append("the next one is CUT: " + str(first.get("why") or ""))
    elif first.get("commit") in ("fresh", "recording"):
        said.append("the next one is being made: " + str(first.get("why") or ""))
    elif first.get("commit") == "ready":
        said.append("the next one is covered")
    task = out.get("task") or {}
    if task.get("p90_seconds"):
        said.append("one of these costs about %ds of studio work at p90, "
                    "and %d of the last %d attempts failed"
                    % (int(task["p90_seconds"] or 0),
                       int(task.get("fail") or 0), int(task.get("count") or 0)))
    pool = out.get("pool") or {}
    if pool and not pool.get("error"):
        said.append("the binder's pool holds %d of them, %d bindable right "
                    "now (%.0fs)%s%s"
                    % (pool.get("in_pool") or 0, pool.get("ready_now") or 0,
                       pool.get("ready_now_seconds") or 0,
                       (", %d waiting on a rest" % pool["ready_later"])
                       if pool.get("ready_later") else "",
                       (", %d written but unfinished" % pool["unready_in_pool"])
                       if pool.get("unready_in_pool") else ""))
        if pool.get("dropped"):
            said.append("%d never reach the pool at all (spent, resting, "
                        "untinted, unrecorded or written for another cast)"
                        % pool["dropped"])
    out["say"] = "; ".join(said)
    return out


@app.post("/api/director/air-now/{kind}")
async def api_director_air_now(
    kind: str,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """#1190: put a finished round of this road on the air, now.

    The operator asking for the thing he has not heard in four hours. It
    goes through the SAME door the rescue uses - `_ready_shelf_air(...,
    rescue=True)` - so it airs only a finished, recorded, intact round,
    out of turn, and every guard that road already has still applies. No
    new powers: this is the existing cupboard road with a handle on it.

    Answers with the lines that went out, so "did it work" is a fact
    rather than an inference."""
    require_auth(authorization)
    kind = str(kind or "")[:32]
    if kind not in RESCUE_ROADS_OPEN:
        raise HTTPException(
            status_code=400,
            detail="the cupboard road is open for %s"
                   % ", ".join(RESCUE_ROADS_OPEN))
    if radio_paused() or not _RADIO.get("on"):
        raise HTTPException(status_code=409,
                            detail="the station is not on air")
    try:
        said = await _ready_shelf_air(kind, _RADIO.get("now"), rescue=True)
    except Exception as exc:  # noqa: BLE001
        raise HTTPException(status_code=500,
                            detail="%s: %s" % (type(exc).__name__,
                                               str(exc)[:160])) from exc
    if said:
        note_action("you put a finished %s round on the air" % kind)
        pipeline_log("air", "OPERATOR: a finished %s round was put on the "
                     "air by hand - %d line(s) (#1190)" % (kind, len(said)))
    return {"kind": kind, "aired": bool(said), "lines": said,
            "say": ("%d line(s) of a ready %s round went out" % (len(said), kind)
                    if said else
                    "the cupboard would not hand one over - ask "
                    "/api/director/why-not/%s" % kind)}


@app.get("/api/director/why-not/{kind}")
async def api_director_why_not(
    kind: str,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """#1188: why this road is not on the air, asked through the REAL door.

    Peek only - nothing is reserved, nothing airs. Every other surface
    counts the cupboard its own way; this one runs the selection the
    rescue runs and says where it stops."""
    require_read_auth(authorization)
    kind = str(kind or "")[:32]
    out: dict[str, Any] = {"kind": kind, "at": time.time()}
    try:
        src = list(road_source(kind) or [])
    except Exception as exc:  # noqa: BLE001
        src = []
        out["source_error"] = str(exc)[:120]
    try:
        pile = list(shelf_rows(kind) or [])
    except Exception:  # noqa: BLE001
        pile = []
    out["source_rows"] = len(src)
    out["shelf_rows"] = len(pile)
    # #1165/#1169: the two halves of the station disagreeing about which
    # pile a road lives on is its own fault class, and one line finds it.
    out["same_pile"] = len(src) == len(pile)
    stops: dict[str, int] = {}
    busy = withtakes = 0
    for row in src:
        try:
            if id(row) in _READY_SHELF_BUSY:
                busy += 1
                stops["already in hand"] = stops.get("already in hand", 0) + 1
                continue
            if not _ready_round_takes(kind, row):
                stops["no recorded takes"] = stops.get(
                    "no recorded takes", 0) + 1
                continue
            withtakes += 1
        except Exception as exc:  # noqa: BLE001
            stops["errored: " + type(exc).__name__] = stops.get(
                "errored: " + type(exc).__name__, 0) + 1
    out["busy"] = busy
    out["with_takes"] = withtakes
    out["stops"] = stops
    # THE ANSWER: what the air itself would get, right now.
    try:
        got = _ready_shelf_row(kind, True)
        out["rescue_row"] = got is not None
        if got is not None:
            _t = _ready_round_takes(kind, got) or []
            out["rescue_takes"] = len(_t)
            out["rescue_seconds"] = round(
                sum(float(t.get("seconds") or 0) for t in _t), 1)
    except Exception as exc:  # noqa: BLE001
        out["rescue_row"] = False
        out["rescue_error"] = "%s: %s" % (type(exc).__name__, str(exc)[:140])
    try:
        out["in_dead_air_stock"] = int((dead_air_stock() or {}).get(kind) or 0)
        out["rescue_road_open"] = kind in RESCUE_ROADS_OPEN
    except Exception:  # noqa: BLE001
        pass
    bits = ["%d row(s) on the %s pile" % (len(src), kind)]
    if not out.get("same_pile"):
        bits.append("BUT shelf_rows sees %d - the two halves of the station "
                    "disagree about which pile this road lives on" % len(pile))
    bits.append("%d carry recorded audio" % withtakes)
    if not out.get("rescue_road_open"):
        bits.append("this road is NOT one the rescue may open "
                    "(RESCUE_ROADS_OPEN)")
    bits.append("the air's own door would %s right now"
                % ("take one" if out.get("rescue_row") else "take NOTHING"))
    if out.get("rescue_error"):
        bits.append("it raised " + str(out["rescue_error"]))
    out["say"] = "; ".join(bits)
    return out


@app.get("/api/director/why/{kind}")
async def api_director_why(kind: str) -> dict[str, Any]:
    """The orchestrator's account of why a road is not filling its entries."""
    return await asyncio.to_thread(director_why, kind)


@app.get("/api/director/scripts/{kind}")
async def api_director_scripts(kind: str, most: int = 40) -> dict[str, Any]:
    """Every script this road is holding, for the segment's own review list.

        "For each section listed, I want to be able to analyze the script
         and load up the script for that particular segment."

    Addressed by ROAD rather than by occurrence, because that is how the
    operator is looking at it - they clicked a Call on the running order
    and want the calls, not the one call an hour happens to have bound."""
    def work() -> dict[str, Any]:
        rows: list[dict[str, Any]] = []
        for row in list(_SHELF.get(str(kind)) or []):
            entry = dialogue_entry(row)
            if entry is None:
                continue
            script = str(entry.get("script") or "")
            if not script.strip():
                continue
            try:
                sid = alt_sid_of(str(kind), row)
            except Exception:  # noqa: BLE001
                continue
            takes = list(entry.get("takes") or [])
            want = int(entry.get("chunks") or 0) or len(takes)
            have = 0
            for take in takes:
                saved = _PANTRY.get(str(take.get("key") or "")) or {}
                clip = saved.get("clip") or {}
                name = str(clip.get("path") or "").rsplit("/", 1)[-1]
                if name.split("?", 1)[0] and (
                        VOICE_MEDIA_DIR / name.split("?", 1)[0]).is_file():
                    have += 1
            tinted = str(entry.get("script_tinted") or "").strip()
            rows.append({
                "sid": sid, "kind": str(kind),
                "at": float(row.get("at") or entry.get("at") or 0),
                "turns": len(banter_turns(
                    script, str(entry.get("caller_name") or ""))),
                "seconds": round(float(row.get("seconds") or 0), 1),
                "recorded": have, "takes": want,
                "is_tinted": bool(tinted and tinted == script.strip()),
                "aired": int(row.get("aired") or 0),
                "kept": bool(entry.get("frozen")),
                "head": " ".join(script.split())[:160],
                "review": script_queue_state(sid),
            })
        rows.sort(key=lambda r: -float(r.get("at") or 0))
        return {"kind": str(kind), "rows": rows[:max(1, int(most))],
                "held": len(rows),
                "why": director_why(str(kind)).get("say") or "",
                "say": "%d script(s) on the %s road" % (len(rows), kind)}
    return await asyncio.to_thread(work)


def _trace_flat(text: Any) -> str:
    """The comparison form for 'is this the same line' - words only."""
    return " ".join(re.sub(r"[^a-z0-9' ]+", " ",
                           str(text or "").lower()).split())


def director_find_script(text: str) -> tuple[str, Any, Any]:
    """The shelf row whose script contains this line. ('', None, None) if none.

    Matched on the WORDS, because what aired went through spoken_text and
    may have lost punctuation the script still has."""
    want = _trace_flat(text)
    if len(want) < 12:
        return "", None, None
    for kind in list(DIRECTOR_QUEUE_KINDS) + ["ad", "station_id"]:
        for row in list(_SHELF.get(kind) or []):
            entry = dialogue_entry(row)
            if entry is None:
                continue
            if want in _trace_flat(entry.get("script")):
                return str(kind), row, entry
    for entry in list(_LARDER):
        if isinstance(entry, dict) and want in _trace_flat(entry.get("script")):
            return str(entry.get("prep_kind") or "banter"), entry, entry
    return "", None, None


def director_line_trace(line_id: str = "", text: str = "") -> dict[str, Any]:
    """Everything the station knows about why one line is on the air.

        "I want to be able to trace it back to a script. I want to trace
         that script back to the system that created it and have an
         understanding of how that script came to be, why this line is
         playing, why this line is playing for the X amount of times that
         it has been played and has it been replaced with anything newer."

    None of this is new bookkeeping - the station has recorded all of it
    all along and never put it in one place. `desk` holds the whole
    writing exchange (which model, at what temperature, wearing which
    persona, and the prompt it was given, schedule clause and all);
    `system2_trace_id` ties it to the orchestrator's own job; `tint` says
    what the crystal did and why; `verbatim` names the speakerbox document
    each stapled passage came out of; the air log counts the airings. This
    joins them."""
    out: dict[str, Any] = {"at": time.time(), "line": str(line_id or ""),
                           "found": False}
    row = None
    try:
        with _AIRLOG_LOCK:
            if line_id:
                row = _AIRLOG_INDEX.get(str(line_id))
            if row is None and text:
                want = _trace_flat(text)
                row = next((r for r in _AIRLOG_INDEX.values()
                            if _trace_flat(r.get("text")) == want), None)
    except Exception:                              # noqa: BLE001
        row = None
    said = str((row or {}).get("text") or text or "")
    if not said.strip():
        out["why"] = "no line of that id is in the air log's window"
        return out
    out["found"] = True
    out["said"] = said[:1200]
    if row:
        out["airing"] = {
            "at": row.get("air_at"), "seconds": row.get("seconds"),
            "who": row.get("who"), "name": row.get("name"),
            "kind": row.get("kind"), "round": row.get("round"),
            "voice": row.get("voice"), "engine": row.get("engine"),
            "aired": row.get("aired"), "clip": row.get("clip_media"),
            "speakbox_document": row.get("source") or "",
            "download": ("/api/booth/clip?line=" + str(row.get("id") or ""))
                        if row.get("id") else "",
        }
    # HOW OFTEN, and when. The air log is the only honest count - a line
    # can be re-aired from the cupboard, and each airing is its own row.
    plays: list[float] = []
    try:
        want = _trace_flat(said)
        with _AIRLOG_LOCK:
            for other in _AIRLOG_INDEX.values():
                if str(other.get("aired") or "") not in AIRLOG_AIRED:
                    continue
                if _trace_flat(other.get("text")) == want:
                    plays.append(float(other.get("air_at") or 0))
    except Exception:                              # noqa: BLE001
        pass
    plays = sorted(p for p in plays if p)
    out["plays"] = {
        "in_the_window": len(plays),
        "first": plays[0] if plays else None,
        "last": plays[-1] if plays else None,
        "window_hours": round(AIRLOG_KEEP_S / 3600.0, 1),
    }
    kind, shelf_row, entry = director_find_script(said)
    if entry is None:
        out["script"] = {}
        # Not every line comes from a round. The emergency host's fillers,
        # station IDs and the SFX guy's stings are written elsewhere and
        # have no script to trace - saying THAT is the answer, not a
        # blank. Worth naming loudly: the first line this endpoint was
        # ever pointed at was an emergency_host filler that had aired 44
        # times in 48 hours, which is the dead-air symptom wearing a
        # rhyme.
        heard = out["plays"]["in_the_window"]
        why = ("this is the emergency host covering a hole, not a written "
               "round" if str((row or {}).get("kind") or "") == "emergency_host"
               else "no script on the shelf still holds this line - the round "
                    "it came from has been retired")
        out["why"] = why
        out["say"] = ("%s; heard %d time(s) in the last %.0f hours"
                      % (why, heard, AIRLOG_KEEP_S / 3600.0))
        return out
    sid = ""
    try:
        sid = alt_sid_of(kind, shelf_row) if shelf_row is not None else ""
    except Exception:                              # noqa: BLE001
        sid = ""
    turns = banter_turns(str(entry.get("script") or ""),
                         str(entry.get("caller_name") or ""))
    at = next((i for i, (_m, t) in enumerate(turns)
               if _trace_flat(t) and _trace_flat(t) in _trace_flat(said)
               or _trace_flat(said) in _trace_flat(t)), None)
    desk = entry.get("desk") if isinstance(entry.get("desk"), dict) else {}
    tint = entry.get("tint") if isinstance(entry.get("tint"), dict) else {}
    out["script"] = {
        "sid": sid, "kind": kind, "turns": len(turns), "turn_index": at,
        "aired_times": int((shelf_row or {}).get("aired") or 0),
        "kept": bool(entry.get("frozen")),
        "caller": str(entry.get("caller_name") or ""),
        "written_at": entry.get("at"),
        "seconds": (shelf_row or {}).get("seconds"),
    }
    # THE SYSTEM THAT MADE IT.
    out["written_by"] = {
        "model": str(desk.get("model") or ""),
        "temperature": desk.get("temp"),
        "context": desk.get("num_ctx"),
        "took_ms": desk.get("ms"),
        "persona": str(desk.get("armed") or ""),
        "asked_as": str(desk.get("kind") or kind),
        "matched": str(desk.get("matched") or ""),
        "at": desk.get("at"),
        "schedule_clause": str(desk.get("sched") or "")[:4000],
        "prompt": str(desk.get("prompt") or "")[:12000],
        "answered": str(desk.get("script") or "")[:6000],
    }
    out["orchestrator"] = {
        "job": str(entry.get("system2_job") or ""),
        "slot": str(entry.get("system2_slot") or ""),
        "trace_id": str(entry.get("system2_trace_id") or ""),
        "rule": entry.get("prep_rule") if isinstance(
            entry.get("prep_rule"), dict) else {},
        "brief": entry.get("brief") if isinstance(
            entry.get("brief"), dict) else {},
        "profile": str(entry.get("profile") or "")[:300],
    }
    out["crystal"] = {
        "ok": tint.get("ok"), "why": str(tint.get("why") or "")[:400],
        "world": str(tint.get("world") or "")[:300],
        "coverage": tint.get("coverage"),
        "tried_at": entry.get("tint_tried"),
        "is_tinted": bool(str(entry.get("script_tinted") or "").strip()
                          == str(entry.get("script") or "").strip()
                          and str(entry.get("script_tinted") or "").strip()),
    }
    # THE OPERATOR'S OWN DOCUMENTS, and which file each came out of.
    passages = []
    for one in (entry.get("verbatim") or []):
        try:
            passages.append({"where": str(one[0]), "text": str(one[1])[:400]})
        except Exception:                          # noqa: BLE001
            continue
    for one in (entry.get("dealt") or []):
        try:
            passages.append({"where": str(one[0]), "seat": str(one[1]),
                             "text": str(one[2])[:400]})
        except Exception:                          # noqa: BLE001
            continue
    out["speakerbox"] = {"passages": passages[:12],
                         "document": str(entry.get("source") or "")}
    # WHAT HAS HAPPENED TO IT SINCE - the operator's own hand.
    review = script_queue_state(sid) if sid else {}
    record = script_record(script_key(sid)) if sid else {}
    out["reviewed"] = {
        **review,
        "edits": [{"index": e.get("index"), "seat": e.get("seat"),
                   "at": e.get("at"), "was": str(e.get("was") or "")[:200],
                   "now": str(e.get("now") or "")[:200]}
                  for e in (record or {}).get("edits") or []][-8:],
        "tints": [{"index": t.get("index"), "taken": t.get("taken"),
                   "at": t.get("at")}
                  for t in (record or {}).get("tints") or []][-8:],
    }
    # HAS ANYTHING NEWER REPLACED IT.
    newer = []
    try:
        parent = alt_sid_of(kind, shelf_row) if shelf_row is not None else ""
        for other in list(_SHELF.get(kind) or []):
            oentry = dialogue_entry(other)
            if oentry is None or oentry is entry:
                continue
            if str(oentry.get("director_fork_of") or "") == parent:
                newer.append({"sid": alt_sid_of(kind, other),
                              "forked_at": oentry.get("director_forked_at"),
                              "aired": int(other.get("aired") or 0),
                              "head": " ".join(
                                  str(oentry.get("script") or "").split())[:140]})
    except Exception:                              # noqa: BLE001
        pass
    out["replaced_by"] = newer
    bits = []
    if out["plays"]["in_the_window"] > 1:
        bits.append("heard %d times in the last %.0f hours"
                    % (out["plays"]["in_the_window"], AIRLOG_KEEP_S / 3600.0))
    else:
        bits.append("heard once in the log's window")
    if out["script"]["kept"]:
        bits.append("its round is KEPT material, so it may come round again")
    if out["written_by"]["model"]:
        bits.append("written by %s at temp %s wearing %s"
                    % (out["written_by"]["model"],
                       out["written_by"]["temperature"],
                       out["written_by"]["persona"] or "no persona"))
    if out["crystal"]["is_tinted"]:
        bits.append("the crystal reached it")
    elif out["crystal"].get("why"):
        bits.append("untinted: " + str(out["crystal"]["why"])[:80])
    if passages:
        bits.append("%d passage(s) of your own documents are in this round"
                    % len(passages))
    if newer:
        bits.append("%d newer version(s) of this round exist" % len(newer))
    if (review or {}).get("edits"):
        bits.append("you have rewritten %d line(s) of it" % review["edits"])
    out["say"] = "; ".join(bits)
    return out


@app.get("/api/director/trace")
async def api_director_trace(line: str = "", text: str = "") -> dict[str, Any]:
    """Why is this line on the air, and where did it come from?"""
    if not line and not text:
        raise HTTPException(400, "give a line id or the words to trace")
    return await asyncio.to_thread(director_line_trace, line, text)


@app.get("/api/director/deadair")
async def api_director_deadair() -> dict[str, Any]:
    """What the station could put on the air right now if it went quiet.

    The point of the cupboard is that this question always has an answer.
    When it does not, that is the thing to fix - and it is now visible
    without waiting for a hole to prove it."""
    def work() -> dict[str, Any]:
        stock = dead_air_stock()
        total = sum(stock.values())
        since = time.time() - float(_RESCUE_AT[0] or 0)
        return {
            "at": time.time(),
            "ready_by_road": stock,
            "rounds_ready": total,
            "opens_after_seconds": DEAD_AIR_RESCUE_AFTER,
            "order": list(RESCUE_ROADS_OPEN),   # #1165: what can actually open
            "last_rescue_seconds_ago": round(since, 1)
                                       if _RESCUE_AT[0] else None,
            "say": ("%d finished round(s) could cover a hole right now - %s"
                    % (total, ", ".join("%s %d" % (k, v)
                                        for k, v in stock.items()))
                    if total else
                    "NOTHING is ready on any road - a hole would have to be "
                    "covered by a sting"),
        }
    return await asyncio.to_thread(work)


