@app.post("/api/director/script/{sid}/tint")
async def api_director_script_tint(sid: str,
                                   payload: dict[str, Any]) -> dict[str, Any]:
    """Tint ONE line, on demand, and hand back both versions.

    Nothing is applied. The operator asked to "select lines in the script
    and have them tinted and view them in a tinted format" - so this is a
    view, and taking it is a second, separate decision. The crystal's own
    grader runs and its refusals come back with the offer, because a bar
    the station would have refused is worth seeing before it is accepted.
    """
    index = int((payload or {}).get("index") or 0)
    kind, row, _c = await asyncio.to_thread(director_resolve, "", sid)
    entry = dialogue_entry(row) or {}
    turns = _director_turns(entry)
    if not 0 <= index < len(turns):
        raise HTTPException(400, "there is no turn %d in a %d turn script"
                            % (index, len(turns)))
    plain = str(turns[index]["text"])
    if not plain.strip():
        raise HTTPException(400, "there is nothing in that turn to tint")
    report: dict[str, Any] = {}
    try:
        # 2026-09-10: THE TREATMENT IS FAST, ON THE SMALL MODEL, ONE ASK.
        #
        # This shipped at room=3 on whichever model the road deserves, and
        # the first live press of the button TIMED OUT AT TWO MINUTES.
        # Measured on the station's own model ledger for that hour:
        # gemma4:31b, 58 calls, mean 109s, max 224s - so room=3 is up to
        # five and a half minutes to rhyme ONE line, while the whole hour
        # holds 3,600s of lane. The same ledger shows ~9,000s of model
        # demand asked of a 3,600s hour, which is why the tint reads as a
        # queue of refusals rather than a treatment: the work is deferred,
        # timed out, and then charged as a fault.
        #
        # A line the operator has picked out and is watching does not need
        # the contest. They are the grader - both versions go on screen and
        # they choose - so this asks ONCE, on the throughput model
        # (e2b, mean 22.5s), and hands back whatever comes. The deep lane
        # is left for the bulk road that has no one watching it.
        tinted = await crystal_line(plain, why="the director asked for this "
                                    "line", room=1, kind=str(kind),
                                    model=tint_fast_model(), report=report)
    except Exception as exc:                       # noqa: BLE001
        raise HTTPException(502, "the crystal could not be reached: %s"
                            % type(exc).__name__)
    tinted = " ".join(str(tinted or "").split())
    same = (not tinted) or tinted == plain
    # The grader's objections are ADVISORY on this road. It refuses lines
    # for the bulk lane, where nobody is watching; here the operator sees
    # both versions and is the one deciding, so a fault is shown as an
    # opinion rather than acted on as a veto. That is the whole difference
    # between a treatment and a contest.
    faults = list((report or {}).get("faults") or [])
    return {"ok": True, "sid": sid, "index": index, "kind": kind,
            "was": plain, "tinted": "" if same else tinted,
            "changed": not same,
            "faults": [str(f)[:200] for f in faults][:6],
            "evaluation": {k: v for k, v in (report or {}).items()
                           if k in ("ok", "grade", "meaning", "rhyme",
                                    "transformation", "technical")},
            "say": ("the crystal returned the line unchanged - it could not "
                    "carry a set of bars while keeping what it says"
                    if same else "here is the tinted version; taking it is "
                                 "a separate decision")}


@app.post("/api/director/script/{sid}/tint/accept")
async def api_director_script_tint_accept(sid: str, payload: dict[str, Any]
                                          ) -> dict[str, Any]:
    """Take a tinted line into the script.

    Applied through the ordinary turn edit, so it re-keys that one take
    and re-records one line, exactly as a hand-written rewrite does. A
    tint accepted here is the operator's wording as much as a typed one
    is - the station has no reason to treat them differently."""
    index = int((payload or {}).get("index") or 0)
    tinted = " ".join(str((payload or {}).get("text") or "").split())
    was = " ".join(str((payload or {}).get("was") or "").split())
    if not tinted:
        raise HTTPException(400, "there is no tinted line to take")
    got = await asyncio.to_thread(director_edit_turn, "", index, tinted,
                                  was, sid)
    await asyncio.to_thread(script_tint_note, sid, index, was, tinted, True)
    got["say"] = "taken - that line records in its tinted form"
    return got


@app.post("/api/director/script/{sid}/tint/refuse")
async def api_director_script_tint_refuse(sid: str, payload: dict[str, Any]
                                          ) -> dict[str, Any]:
    """Turn down a tinted line, and keep the fact that it was turned down."""
    await asyncio.to_thread(
        script_tint_note, sid, int((payload or {}).get("index") or 0),
        str((payload or {}).get("was") or ""),
        str((payload or {}).get("text") or ""), False,
        (payload or {}).get("faults"))
    return {"ok": True, "say": "left as it was, and the refusal is on the "
                               "record"}


@app.post("/api/director/script/{sid}/rhyme")
async def api_director_script_rhyme(sid: str,
                                    payload: dict[str, Any] | None = None
                                    ) -> dict[str, Any]:
    """Rhyme a WHOLE script in one ask, and hand back both versions.

    Nothing is applied. This is the treatment the operator described - the
    script goes through the lane once, every line comes back, and taking
    them is a separate decision made line by line on screen."""
    only = [int(x) for x in ((payload or {}).get("indexes") or [])
            if str(x).lstrip("-").isdigit()]
    kind, row, _c = await asyncio.to_thread(director_resolve, "", sid)
    entry = dialogue_entry(row) or {}
    turns = _director_turns(entry)
    if not turns:
        raise HTTPException(409, "that script has no turns to treat")
    want = [t for t in turns if not only or t["index"] in only]
    got = await rhyme_treat([t["text"] for t in want], kind=str(kind),
                            why="the director asked for this script")
    rows = []
    for at, turn in enumerate(want):
        now = str((got.get("lines") or [])[at]
                  if at < len(got.get("lines") or []) else turn["text"])
        lost = (got.get("lost") or {}).get(str(at)) or []
        rows.append({"index": turn["index"], "seat": turn["seat"],
                     "who": turn["who"], "was": turn["text"],
                     "rhymed": now if now != turn["text"] else "",
                     "changed": now != turn["text"],
                     "lost": lost})
    changed = [r for r in rows if r["changed"]]
    risky = [r for r in changed if r.get("lost")]
    return {"ok": True, "sid": sid, "kind": kind, "rows": rows,
            "changed": len(changed), "risky": len(risky),
            "asked": got.get("asked") or 0,
            "ms": got.get("ms") or 0, "why": got.get("why") or "",
            "say": ("%d of %d lines came back with a rhyme in %.1fs - one "
                    "ask for the whole script"
                    % (len(changed), got.get("asked") or 0,
                       float(got.get("ms") or 0) / 1000.0)
                    if changed else (got.get("why")
                                     or "nothing came back changed"))
            + (" - %d dropped a name or a number, marked below"
               % len(risky) if risky else "")}


@app.post("/api/director/script/{sid}/rhyme/accept")
async def api_director_script_rhyme_accept(sid: str, payload: dict[str, Any]
                                           ) -> dict[str, Any]:
    """Take some or all of a treated script into the words that will air.

    Applied line by line through the ordinary turn edit, so each accepted
    bar re-keys its own take and re-records one line. Applied HIGHEST INDEX
    FIRST: every edit rebuilds the script, and working downwards means an
    earlier acceptance cannot shift the position of a later one."""
    rows = [r for r in ((payload or {}).get("rows") or [])
            if isinstance(r, dict) and str(r.get("rhymed") or "").strip()]
    if not rows:
        raise HTTPException(400, "there are no treated lines to take")
    rows.sort(key=lambda r: -int(r.get("index") or 0))
    took, failed = 0, []
    for row in rows:
        at = int(row.get("index") or 0)
        try:
            await asyncio.to_thread(
                director_edit_turn, "", at, str(row.get("rhymed") or ""),
                str(row.get("was") or ""), sid)
            await asyncio.to_thread(script_tint_note, sid, at,
                                    str(row.get("was") or ""),
                                    str(row.get("rhymed") or ""), True)
            took += 1
        except HTTPException as exc:
            failed.append({"index": at, "why": str(exc.detail)[:200]})
        except Exception as exc:                   # noqa: BLE001
            failed.append({"index": at, "why": type(exc).__name__})
    pipeline_log("action", "the director took %d rhymed line(s) into a "
                 "script" % took)
    return {"ok": True, "took": took, "failed": failed,
            "state": script_queue_state(sid),
            "say": ("%d line(s) taken; they re-record and the rest of the "
                    "round stands" % took)
                   + (" - %d could not be applied" % len(failed)
                      if failed else "")}


def _director_seat_key(marker: str) -> str:
    """The same mapping speak_turns uses (`_who_of`), for take matching."""
    one = str(marker or "").strip().upper()[:1]
    return ("caller" if one == "C" else "caller2" if one == "E"
            else "dj" if one == "A" else "third" if one == "D" else "cohost")


def director_seat_voice(entry: dict[str, Any], marker: str) -> tuple[str, str]:
    """The voice and engine this seat is already recorded in.

    Taken from the round's OWN takes rather than from settings: a round cut
    in one cast must stay in that cast, or half of it comes back in a
    different mouth. Falls back to any voice the round has, because a round
    in one voice is still a round."""
    who = _director_seat_key(marker)
    takes = [t for t in (entry.get("takes") or []) if isinstance(t, dict)]
    mine = [t for t in takes if str(t.get("who") or "") == who]
    for take in (mine + takes):
        voice = str(take.get("voice") or "")
        if not voice:
            continue
        engine = next((e for e in DIRECTOR_ENGINES
                       if pantry_key(str(take.get("text") or ""), voice, e)
                       == str(take.get("key") or "")), "xtts")
        return voice, engine
    return "", "xtts"


def director_rewrite_script(kind: str, row: dict[str, Any],
                            entry: dict[str, Any], turns: list[Any],
                            why: str) -> dict[str, Any]:
    """Replace a round's whole script and rebuild its takes to match.

    THE POINT OF DOING IT THIS WAY. Takes are content-addressed on
    `pantry_key(text, voice, engine)`, so a rebuilt take list re-keys every
    turn - and a turn whose words did not change gets back the SAME key it
    had, which is still in the pantry. The round therefore keeps every
    recording it can and pays the engine only for lines that actually
    changed or are new. That is what makes sending a script back to the
    writing room affordable: a rewrite touching three turns of eleven costs
    three lines, not a round.

    `made` is set to what is genuinely recorded, so a round now short of
    audio is honestly not ready and goes back through the recording room
    rather than airing with holes in it."""
    rows: list[dict[str, Any]] = []
    lines: list[str] = []
    have = 0
    for marker, said in turns:
        text = " ".join(str(said or "").split())
        if not text:
            continue
        mark = str(marker or "A").strip().upper()[:1] or "A"
        lines.append("%s: %s" % (mark, text))
        voice, engine = director_seat_voice(entry, mark)
        spoken = " ".join(spoken_text(text).split())
        key = pantry_key(spoken, voice, engine) if voice else ""
        if key and key in _PANTRY:
            have += 1
        rows.append({"i": len(rows), "text": spoken, "voice": voice,
                     "who": _director_seat_key(mark), "key": key})
    if not rows:
        raise HTTPException(409, "the rewrite came back with nothing in it")
    entry["script"] = "\n".join(lines)
    entry["takes"] = rows
    entry["chunks"] = len(rows)
    entry["made"] = have
    entry["keys"] = [r["key"] for r in rows if r["key"]]
    entry["partial"] = have < len(rows)
    # These are the operator's words now: nothing may hand them back to be
    # reworded, and the tinted twin no longer describes them.
    entry["freshened"] = True
    entry.pop("script_tinted", None)
    entry["use"] = "tinted"
    for saver in (_larder_save, _pantry_save):
        try:
            saver()
        except Exception:                          # noqa: BLE001
            pass
    pipeline_log("action", "a %s script went back through the writing room - "
                 "%d of %d lines already have audio (%s)"
                 % (kind, have, len(rows), why))
    return {"turns": len(rows), "recorded": have,
            "to_record": len(rows) - have}


@app.post("/api/director/script/{sid}/revise")
async def api_director_script_revise(sid: str, payload: dict[str, Any]
                                     ) -> dict[str, Any]:
    """Send a script back to the writing room with a note.

    The note does BOTH jobs at once: it rewrites this script now, and it is
    kept as a standing note on the road so the next one of these is written
    knowing it. Having to tell the station the same thing twice is the
    thing this room exists to stop."""
    note = " ".join(str((payload or {}).get("note") or "").split())
    if not note:
        raise HTTPException(400, "a revision needs a note saying what to change")
    keep_note = bool((payload or {}).get("standing", True))
    kind, row, _c = await asyncio.to_thread(director_resolve, "", sid)
    entry = dialogue_entry(row) or {}
    if entry.get("frozen") or row.get("aired") or row.get("aired_at"):
        row, entry = await asyncio.to_thread(director_fork_kept, kind, row,
                                             entry)
    caller_name = str(entry.get("caller_name") or "")
    was = str(entry.get("script") or "")
    turns = banter_turns(was, caller_name)
    if not turns:
        raise HTTPException(409, "that script has no turns to revise")
    seats = sorted({str(m or "A").upper()[:1] for m, _t in turns})
    prompt = (
        "Rewrite this radio script. The person who runs the station has "
        "read it and asked for this:\n\n    " + note[:600] + "\n\n"
        "RULES:\n"
        "1. Do what they asked. That instruction outranks anything the "
        "script is currently doing.\n"
        "2. Keep the SAME speakers in the same order, using the same "
        "labels (" + ", ".join(seats) + "), and the same number of turns.\n"
        "3. Keep every name, number and question the script owes, unless "
        "the note is telling you to change them.\n"
        "4. It is read aloud on a radio show. No stage directions, no "
        "markdown, no commentary, no speaker names other than the "
        "labels.\n\n"
        "OUTPUT: the whole script, one turn per line, each line starting "
        "with its speaker label and a colon. Nothing else.\n\n"
        "THE SCRIPT AS IT STANDS:\n" + was[:6000])
    try:
        said = await ask_model(prompt, limit=max(900, len(was) + 400),
                               mark={"kind": "writers room",
                                     "why": note[:80]})
    except Exception as exc:                       # noqa: BLE001
        raise HTTPException(502, "the writing room could not be reached: %s"
                            % type(exc).__name__)
    fresh = banter_turns(str(said or ""), caller_name)
    if len(fresh) < max(2, len(turns) // 2):
        raise HTTPException(
            502, "the writing room answered with %d turns against the %d it "
                 "was given, so the script is left alone rather than half "
                 "replaced" % (len(fresh), len(turns)))
    got = await asyncio.to_thread(director_rewrite_script, kind, row, entry,
                                  fresh, "note: " + note[:60])
    if keep_note:
        try:
            await asyncio.to_thread(director_add, kind, note, "standing")
        except Exception:                          # noqa: BLE001
            pass
    try:
        await asyncio.to_thread(script_note_edit, script_key(sid), kind, -1,
                                was[:1800],
                                str(entry.get("script") or "")[:1800],
                                seat="*")
    except Exception:                              # noqa: BLE001
        pass
    return {"ok": True, "sid": sid, "kind": kind, **got,
            "standing_note": keep_note,
            "say": ("back from the writing room - %d turns, %d already have "
                    "audio, %d to record%s"
                    % (got["turns"], got["recorded"], got["to_record"],
                       "; the note now governs every future " + kind
                       if keep_note else ""))}


@app.post("/api/director/script/{sid}/reseed")
async def api_director_script_reseed(sid: str,
                                     payload: dict[str, Any] | None = None
                                     ) -> dict[str, Any]:
    """Deal fresh speakerbox passages into a script that has gone flat.

    Drawn the way the writing room draws them and DEALT the way it deals
    them - cut into spoken-length pieces and passed round the seats
    (_swath_deal), never one long turn in one mouth, which is the mistake
    that put 82% of a measured six hours of airtime in the host's. Spread
    through the round rather than stapled to the front, so the documents
    arrive as interruptions rather than as a reading."""
    how_many = max(1, min(4, int((payload or {}).get("passages") or 2)))
    kind, row, _c = await asyncio.to_thread(director_resolve, "", sid)
    entry = dialogue_entry(row) or {}
    if entry.get("frozen") or row.get("aired") or row.get("aired_at"):
        row, entry = await asyncio.to_thread(director_fork_kept, kind, row,
                                             entry)
    caller_name = str(entry.get("caller_name") or "")
    was = str(entry.get("script") or "")
    turns = [[str(m or "A").upper()[:1], str(t or "")]
             for m, t in banter_turns(was, caller_name)]
    if not turns:
        raise HTTPException(409, "that script has no turns to seed into")
    seats = _swath_seats(was, caller_name)
    added, files = 0, []
    for _ in range(how_many):
        try:
            drawn = await speakbox_quote(most=6, cap=420)
        except Exception:                          # noqa: BLE001
            drawn = {}
        text = " ".join(str((drawn or {}).get("text") or "").split())
        if not text:
            continue
        dealt = _swath_deal(text, seats)
        if not dealt:
            continue
        # Somewhere inside the round, never before the first turn or after
        # the last: the open and the close are the round's own job.
        at = random.randint(1, max(1, len(turns) - 1))
        turns[at:at] = [[m, p] for m, p in dealt]
        added += len(dealt)
        files.append(str(drawn.get("file") or ""))
        try:
            speakbox_remember(drawn)
        except Exception:                          # noqa: BLE001
            pass
    if not added:
        raise HTTPException(502, "the speakerbox had nothing to give - the "
                                 "shelf may be empty, or every line on it is "
                                 "inside its repeat window")
    got = await asyncio.to_thread(director_rewrite_script, kind, row, entry,
                                  turns, "reseeded from the speakerbox")
    return {"ok": True, "sid": sid, "kind": kind, "added": added,
            "documents": [f for f in files if f], **got,
            "say": ("%d passage turn(s) dealt in from %s - %d of %d lines "
                    "already have audio, %d to record"
                    % (added, ", ".join(f for f in files if f) or "the shelf",
                       got["recorded"], got["turns"], got["to_record"]))}


@app.post("/api/director/script/{sid}/record")
async def api_director_script_record(sid: str,
                                     payload: dict[str, Any] | None = None
                                     ) -> dict[str, Any]:
    """Send a script to the recording room, optionally straight past the tint.

    "be able to choose to have a script sent directly to the recording room
    to be turned into something that goes on the air bypassing the whole
    tinting process". `bypass` writes a per-round exemption that
    dialogue_tint_ready honours - the same shape as crystal_tint_must_flow,
    but for one script rather than a whole road, and stamped with who
    decided it and when."""
    bypass = bool((payload or {}).get("bypass"))
    who = str((payload or {}).get("who") or "operator")

    def work() -> dict[str, Any]:
        kind, row, _c = director_resolve(sid=sid)
        entry = dialogue_entry(row) or {}
        if bypass:
            entry["director_bypass_tint"] = True
            entry["director_bypass_at"] = time.time()
            try:
                _pantry_save()
            except Exception:  # noqa: BLE001
                pass
        state = script_send_to_record(sid, bypass_tint=bypass, who=who)
        script_seen_mark(sid, kind)
        return {"kind": kind, "state": state}
    got = await asyncio.to_thread(work)
    pipeline_log("action", "the director released a %s script to the "
                 "recording room%s" % (got["kind"],
                                       " - past the tint" if bypass else ""))
    return {"ok": True, "sid": sid, "bypass": bypass, **got,
            "say": ("released - it records as written and the crystal is "
                    "not waited for" if bypass else
                    "released to the recording room")}


@app.get("/api/director/headroom")
async def api_director_headroom(target: float = HEADROOM_TARGET
                                ) -> dict[str, Any]:
    """Can this hour actually be voiced, and what would it take?"""
    def work() -> dict[str, Any]:
        store = schedule_read()
        name = schedule_preset_now(store)
        slots = list((store.get("presets") or {}).get(name) or [])
        got = headroom_plan(slots, float(target))
        got["preset"] = name
        got.pop("slots", None)
        return got
    return await asyncio.to_thread(work)


@app.post("/api/director/headroom/apply")
async def api_director_headroom_apply(payload: dict[str, Any] | None = None
                                      ) -> dict[str, Any]:
    """Write the thinned hour as a NEW preset, and optionally run it.

    The original is never edited, so going back is one click on the
    scheduler - which matters, because how an hour sounds is the
    operator's call and this is only arithmetic about whether it can be
    made at all."""
    target = float((payload or {}).get("target") or HEADROOM_TARGET)
    activate = bool((payload or {}).get("activate", True))
    into = str((payload or {}).get("name") or "").strip()

    def work() -> dict[str, Any]:
        store = schedule_read()
        name = schedule_preset_now(store)
        slots = list((store.get("presets") or {}).get(name) or [])
        got = headroom_plan(slots, target)
        rows = got.pop("slots", None) or []
        if not got.get("changed"):
            got["preset"] = name
            got["applied"] = False
            return got
        made = into or (name + " (fits the engine)")
        store.setdefault("presets", {})[made] = rows
        if activate:
            store["active"] = made
            day = store.get("day")
            if isinstance(day, dict):
                for hour in list(day):
                    if str(day.get(hour) or "") == name:
                        day[hour] = made
        schedule_write(store)
        got.update(preset=made, from_preset=name, applied=True,
                   active=bool(activate))
        return got
    got = await asyncio.to_thread(work)
    if got.get("applied"):
        pipeline_log("action", "the running order was thinned so the hour "
                               "can actually be voiced - " + str(got.get("say")))
    return got


