@app.post("/api/dj/callin/voice")
async def dj_callin_voice(
    request: Request,
    rate: int = 16000,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Raw 16-bit mono PCM recorded in the browser: transcribe it, then put
    the caller on air (#163)."""
    require_auth(authorization)
    pcm = await request.body()
    if len(pcm) < 3200:                    # under a tenth of a second
        raise HTTPException(status_code=400, detail="That recording is empty")
    pcm = pcm[:CALLIN_MAX_BYTES]

    try:
        heard = await asyncio.to_thread(wyoming_transcribe, pcm, rate)
    except Exception as exc:
        raise HTTPException(
            status_code=502,
            detail=f"Speech recognition is not answering: {exc}") from exc

    if not heard:
        return {"heard": "", "lines": [],
                "detail": "Nothing came through — try again, a bit louder."}

    # A caller can ask for a song as easily as raise a topic.
    taken = await dj_take_request(heard)
    if taken:
        return {"heard": heard, "lines": [taken["reply"]],
                "track": taken.get("track"), "kind": "request"}

    result = await dj_callin(
        heard, caller=f"a caller on {call_line_say(call_line_no())}")  # #673
    return {**result, "heard": heard, "kind": "callin"}


@app.post("/api/dj/callin")
async def dj_callin_api(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """A caller rings in with a topic; the pair research it and take it on
    air, each from a different disposition."""
    require_auth(authorization)
    payload = await request.json()
    topic = str(payload.get("topic") or payload.get("text") or "").strip()
    # Instant now (#353): the reply returns while the phone is still
    # ringing, and a blank topic no longer 400s — somebody just calls in
    # about whatever is on their mind. Phone calls are the favourite
    # thing (#352); the button must never do nothing.
    if topic:
        asyncio.create_task(dj_callin(topic,
                                      str(payload.get("caller") or "")))
    else:
        asyncio.create_task(dj_call_generated())
    return {"rolling": True, "topic": topic}


# The button rounds (#348): a format drawn fresh every press, each one
# built to hold tension — reveals withheld, lines cut short, something
# always about to happen.
SUSPENSE_FORMATS = (
    "One of you knows something enormous and refuses to say it outright — "
    "circle it, hint at it, get interrupted at the exact moment of the "
    "reveal. The other grows desperate. NEVER land the reveal.",
    "There is a sound in the building. You both heard it. Talk quieter and "
    "quieter about what it could be, stopping mid-sentence to listen. End "
    "on the sound happening AGAIN, closer.",
    "Live breaking coverage: something is happening RIGHT OUTSIDE the "
    "studio window, and you narrate it as it develops. It keeps getting "
    "stranger. Cut to silence at the worst possible moment.",
    "A countdown is running — to what, neither of you will say on air. "
    "Check the remaining time twice. Speed up as it shrinks. The round "
    "ends with seconds left.",
    "Read a letter that arrived at the station with no return address, one "
    "line at a time, reacting between lines. The last line names one of "
    "you. Stop there.",
    "An interrogation: one of you is CONVINCED the other did something "
    "last night and grills them live. The alibi keeps changing. End on a "
    "slip that admits everything without saying it.",
    "You have reason to believe this is the station's final broadcast. "
    "Don't announce it — let it leak through what you choose to say, "
    "goodbyes disguised as small talk, one thing you always meant to say.",
    "A rumor about a listener you both know is spreading and the phones "
    "are lit. Discuss it without ever saying the name or the rumor — pure "
    "implication. Someone is definitely listening.",
    "An on-air dare that keeps escalating. Each refusal raises the stakes. "
    "The round ends the moment one of you actually starts DOING it.",
    "Something in the studio has been moved. Only slightly. You both "
    "noticed independently. Neither of you moved it. Work out, quietly, "
    "who could have been in here.",
    "One of you had a dream about the other last night and it is clearly "
    "still bothering you. Get it out of them one detail at a time. The "
    "last detail should be genuinely unsettling.",
    "A prophecy: one of you predicts, with total unearned certainty, what "
    "happens in the next hour of the show — specific, strange, checkable. "
    "The other bets against it. Set real stakes.",
    "The lights have started flickering in a pattern. One of you thinks "
    "it's a message and starts decoding it live. The decoded message "
    "should be worse than either of you expected.",
    "Auction a cursed object that is physically on the desk right now. "
    "Describe it too carefully. Bids arrive from callers you never put on "
    "air. Warn the winner as gently as you can.",
)


# The one button round in flight — pressing again while it rolls must not
# stack a second round on top of it (#348).
_BUTTON_ROUND: list[asyncio.Task] = []

# The press answers OUT LOUD immediately (#422): writing plus rendering
# puts the first real line 30-60s out, and that silence read as a dead
# button. One canned beat, rendered once per boot, plays the instant the
# button lands.
_BUTTON_ACK: dict[str, str] = {}


async def _button_ack() -> None:
    try:
        if not _BUTTON_ACK:
            clip = await voice_generate(
                "Hold that thought — getting the two of them talking.",
                "", "piper")
            _BUTTON_ACK.update({"path": clip["path"], "sig": clip["sig"]})
        # Obey the reply routing (#524, #528): don't fire the box ack when
        # replies are pointed at the page or off.
        if (_RADIO.get("reply_to") or "box") in ("box", "both"):
            await _play_on_box(_BUTTON_ACK["path"], _BUTTON_ACK["sig"])
    except Exception:
        pass                            # the round itself is the answer


@app.post("/api/dj/banter")
async def dj_banter_api(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Make the pair talk NOW (#133, #348): the reply comes back before
    the first line airs, the format is drawn fresh every press, and the
    speakbox rhetoric is stitched through it word for word (#199)."""
    require_auth(authorization)
    note_action("🎬 you pushed a banter round")
    if _BUTTON_ROUND and not _BUTTON_ROUND[0].done():
        return {"rolling": True, "format": "still mid-round — hold on",
                "spoke_on_box": True, "why_silent": "",
                "voice_to": _RADIO.get("voice_to") or "box"}
    seed = await speakbox_quote(most=random.randint(2, 6),
                                cap=random.randint(240, 520))
    form = unrepeated(list(SUSPENSE_FORMATS), "button-format")
    angle = form + (
        " Somewhere inside it, one of you delivers this, word for word, "
        f"with total conviction, as though it proves everything: "
        f"\"{seed['text']}\"" if seed else "")
    count = random.randint(7, 14)

    async def _round() -> None:
        try:
            said = await dj_banter(_RADIO.get("now"), angle=angle,
                                   lines=count,
                                   source=(seed or {}).get("file", ""))
            if said and seed:
                speakbox_remember(seed)
        except Exception as exc:
            pipeline_log("drop", f"banter round died: {exc}"[:200])

    _BUTTON_ROUND[:] = [asyncio.create_task(_round())]
    asyncio.create_task(_button_ack())  # the room hears the press (#422)
    health = speak_health()
    return {
        "rolling": True,
        "format": form.split(".")[0][:90],
        "spoke_on_box": not health.get("why"),
        "why_silent": health.get("why") or "",
        "voice_to": _RADIO.get("voice_to") or "box",
    }


CONVERSE_PATH = data_path("converse_seeds.json")
_CONVERSE_LOCK = RLock()


def converse_history() -> list[dict[str, Any]]:
    try:
        rows = json.loads(CONVERSE_PATH.read_text())
        return [r for r in rows if isinstance(r, dict)] if isinstance(
            rows, list) else []
    except Exception:
        return []


def converse_save(text: str) -> None:
    with _CONVERSE_LOCK:
        rows = converse_history()
        rows.append({"text": text[:400], "ts": int(time.time())})
        try:
            CONVERSE_PATH.parent.mkdir(parents=True, exist_ok=True)
            tmp = CONVERSE_PATH.with_suffix(".tmp")
            tmp.write_text(json.dumps(rows[-200:], indent=0))
            tmp.replace(CONVERSE_PATH)
        except OSError:
            pass


@app.post("/api/dj/converse")
async def dj_converse_api(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Seed a conversation between the DJs (#475): the operator types a line
    for one of them to say to the other, and that single remark kicks off a
    whole back-and-forth. The seed is saved to a browsable history."""
    require_auth(authorization)
    payload = await request.json()
    text = str(payload.get("text") or "").strip()
    if not text:
        raise HTTPException(status_code=400, detail="Say something first")
    converse_save(text)
    if _BUTTON_ROUND and not _BUTTON_ROUND[0].done():
        return {"rolling": True, "why_silent": "still mid-round — hold on",
                "voice_to": _RADIO.get("voice_to") or "box"}
    angle = (
        "One of you turns to the other and says this, WORD FOR WORD, to open "
        f"the conversation: \"{text}\". That single remark starts a real "
        "back-and-forth — the other takes it up, reacts to it, agrees or "
        "argues, and it grows into a whole conversation between you. Let it "
        "breathe and develop naturally from that opening line.")

    async def _round() -> None:
        try:
            await dj_banter(_RADIO.get("now"), angle=angle,
                            lines=random.randint(6, 12))
        except Exception as exc:
            pipeline_log("drop", f"converse round died: {exc}"[:200])

    _BUTTON_ROUND[:] = [asyncio.create_task(_round())]
    asyncio.create_task(_button_ack())
    health = speak_health()
    return {"rolling": True, "spoke_on_box": not health.get("why"),
            "why_silent": health.get("why") or "",
            "voice_to": _RADIO.get("voice_to") or "box"}


@app.get("/api/dj/converse")
async def dj_converse_history_api(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """The saved history of conversation seeds, newest first (#475)."""
    require_read_auth(authorization)
    return {"seeds": list(reversed(converse_history()))[:200]}


@app.post("/api/dj/chat/delete")
async def dj_chat_delete_api(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Delete a dialogue line by its code (#485, #484): a line the DJs made
    up — a thing that never actually happened — is struck from the transcript
    AND from their memory so it is never repeated. Also drops any hold-shelf
    or page clip of it so it stops appearing in the backlog."""
    require_auth(authorization)
    payload = await request.json()
    mid = str(payload.get("id") or "").strip()
    if not mid:
        raise HTTPException(status_code=400, detail="Which line? (no id)")
    removed = None
    for entry in list(_RADIO.get("chat") or []):
        if entry.get("id") == mid:
            removed = entry
            break
    if removed is None:
        raise HTTPException(status_code=404, detail="No line with that code")
    text = str(removed.get("text") or "")
    _RADIO["chat"] = [e for e in _RADIO["chat"] if e.get("id") != mid]
    said_forget(text)
    # And out of the backlog/hold shelf if a clip of it is waiting there.
    _RADIO["voice_clips"] = [c for c in (_RADIO.get("voice_clips") or [])
                             if str(c.get("text") or "") != text]
    before = len(_BOX_HOLD)
    _BOX_HOLD[:] = [h for h in _BOX_HOLD if str(h.get("text") or "") != text]
    if len(_BOX_HOLD) != before:
        _box_hold_save()
    return {"deleted": mid, "text": text[:120]}


@app.get("/api/music/played")
async def music_played_api(
    limit: int = 60,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """What has been on air, newest first, with where you stand on each —
    so a song you liked and lost can be found and put on again (#203)."""
    require_read_auth(authorization)
    votes = read_votes()
    rows = []
    for row in read_played()[:max(1, min(300, limit))]:
        track_id = str(row.get("id") or "")
        rows.append({
            **row,
            "url": f"/music/{track_id}?t={media_sign(track_id)}",
            "art": f"/music/{track_id}/art?t={media_sign(track_id)}",
            "vote": int((votes.get(track_id) or {}).get("vote") or 0),
        })
    return {"played": rows}


# #872: the booth's own index. (start, end, path, offset_into_file),
# sorted by start, rebuilt only when the folders change.
_BOOTH_INDEX: list[tuple[float, float, str, float]] = []
_BOOTH_INDEX_SIG = [""]


def _booth_index_sig() -> str:
    """Cheap fingerprint of the two shelves. A new staged clip or a
    freshly sealed episode changes it; nothing else does."""
    try:
        st = _EPISODE_STAGE.stat().st_mtime_ns if _EPISODE_STAGE.is_dir() \
            else 0
    except OSError:
        st = 0
    try:
        eps = (RADIO_CACHE / "episodes")
        ep = eps.stat().st_mtime_ns if eps.is_dir() else 0
    except OSError:
        ep = 0
    return f"{st}:{ep}:{len(_RADIO.get('episode', {}).get('items') or [])}"


def _booth_index_build() -> list[tuple[float, float, str, float]]:
    """Every moment the station can still hand over, as spans."""
    rows: list[tuple[float, float, str, float]] = []
    # the open episode, by its own ledger (exact air times)
    items = sorted(
        [i for i in ((_RADIO.get("episode") or {}).get("items") or [])
         if float(i.get("t") or 0) > 0],
        key=lambda i: float(i["t"]))
    for ix, item in enumerate(items):
        began = float(item["t"])
        path = str(item.get("file") or "")
        if not path or not Path(path).is_file():
            continue
        span = _clip_seconds(path)
        ends = began + span if span else (
            float(items[ix + 1]["t"]) if ix + 1 < len(items)
            else began + 12.0)
        rows.append((began, ends, path, 0.0))
    # …and the staged files on disk, whose mtimes are their air times
    # (this is what survives a restart, when the ledger above is gone)
    try:
        staged = sorted(((f, f.stat().st_mtime)
                         for f in _EPISODE_STAGE.glob("*.mp3")
                         if f.is_file()), key=lambda pair: pair[1])
    except OSError:
        staged = []
    known = {r[2] for r in rows}
    for ix, (path, when) in enumerate(staged):
        if str(path) in known:
            continue
        span = _clip_seconds(str(path))
        ends = when + span if span else (
            staged[ix + 1][1] if ix + 1 < len(staged) else when + 12.0)
        rows.append((when, ends, str(path), 0.0))
    # the sealed episodes, by their marks
    for mark_file in sorted((RADIO_CACHE / "episodes").glob("*.json")):
        source = mark_file.with_suffix(".mp3")
        if not source.is_file():
            continue
        try:
            marks = json.loads(mark_file.read_text())
        except Exception:  # noqa: BLE001
            continue
        for mark in marks:
            began = float(mark.get("t") or 0)
            dur = float(mark.get("dur") or 0)
            if began <= 0 or dur <= 0:
                continue
            rows.append((began, began + dur, str(source),
                         float(mark.get("off") or 0)))
    rows.sort(key=lambda r: r[0])
    return rows


async def booth_index() -> list[tuple[float, float, str, float]]:
    sig = await asyncio.to_thread(_booth_index_sig)
    if sig != _BOOTH_INDEX_SIG[0] or not _BOOTH_INDEX:
        built = await asyncio.to_thread(_booth_index_build)
        _BOOTH_INDEX[:] = built
        _BOOTH_INDEX_SIG[0] = sig
    return _BOOTH_INDEX


# --- #908: THE CUT ---------------------------------------------------
#
# "make sure that the clips that I'm cutting are exactly the things that
#  I'm grabbing from in the booth... I'm seeing it grab a little bit of
#  extra before and after."
#
# What was actually wrong, plainly, because none of it was obvious:
#
#   * THE BURST. Banter and every call take the coalesced road by
#     default (#530/#535): speak_turns welds the whole round into ONE
#     file and stages that ONE file into the episode. Every booth row of
#     that round therefore falls inside a single indexed moment, and
#     #867 wrote the consequence down as if it were a feature - "a row
#     inside a burst hands back the WHOLE moment, because the burst IS
#     the moment". It is not one moment. It is a dozen, plus the ring,
#     the hang-up and any sting that punched in between lines, and the
#     operator clicked exactly one of them.
#   * THE PAD. Every spoken clip leaves _level_voice with BOX_TAIL_MS of
#     silence welded onto it (900 ms) so the box has something harmless
#     to loop at the end. That is the extra AFTER, on every download of
#     a single line.
#   * THE NEAR MISS. When no indexed span covered a row, the old road
#     took the nearest start within SIX SECONDS. At conversational pace
#     that is the line before or the line after, handed over with
#     nothing said about it.
#
# speak_turns already computes each turn's exact window into the welded
# file - it has to, or the booth's marker could not follow the line -
# and then threw it away. It is written onto the row now, and these cut
# to it.
_BOOTH_CUTS: dict[str, str] = {}


def _booth_cut_blocking(src: str, start: float, dur: float,
                        tag: str) -> str:
    """Cut [start, start+dur) out of `src` as an mp3, once.

    Returns the path, or "" when it could not be made. Never raises: a
    download is never worth taking the station off the air."""
    try:
        out = SAMPLE_CACHE_DIR / f"cut_{tag}.mp3"
        if out.is_file() and out.stat().st_size > 600:
            return str(out)
        SAMPLE_CACHE_DIR.mkdir(parents=True, exist_ok=True)
        try:
            import imageio_ffmpeg
            exe = imageio_ffmpeg.get_ffmpeg_exe()
        except Exception:  # noqa: BLE001
            exe = "ffmpeg"
        got = _real_subprocess_run(
            [exe, "-nostdin", "-hide_banner", "-loglevel", "error", "-y",
             # -accurate_seek is ffmpeg's own default and is named here
             # out loud because it is the entire point of this endpoint.
             "-accurate_seek",
             "-ss", f"{max(0.0, float(start)):.3f}",
             "-t", f"{max(0.05, float(dur)):.3f}",
             "-i", str(src),
             "-codec:a", "libmp3lame", "-q:a", "3", str(out)],
            capture_output=True, timeout=120)
        if got.returncode != 0 or not out.is_file() \
                or out.stat().st_size <= 600:
            return ""
        return str(out)
    except Exception:  # noqa: BLE001
        return ""


async def booth_cut(src: str, start: float, dur: float) -> str:
    """One span, cut and remembered.

    Keyed on the source's identity AND the span, so pressing the same
    download twice costs one ffmpeg run rather than two - and so a file
    somehow rewritten under the same name is never served from a stale
    cut. Off the loop, like every other ffmpeg call in this file."""
    try:
        stamp = await asyncio.to_thread(
            lambda: Path(src).stat().st_mtime_ns)
    except Exception:  # noqa: BLE001
        return ""
    tag = hashlib.sha1(
        f"{src}\x00{stamp}\x00{start:.3f}\x00{dur:.3f}".encode(
            "utf-8", "ignore")).hexdigest()[:20]
    held = _BOOTH_CUTS.get(tag)
    if held and Path(held).is_file():
        return held
    made = await asyncio.to_thread(_booth_cut_blocking, src, start, dur,
                                   tag)
    if made:
        if len(_BOOTH_CUTS) > 400:
            _BOOTH_CUTS.clear()
        _BOOTH_CUTS[tag] = made
    return made


def _booth_row(line_id: str) -> dict[str, Any]:
    """The booth entry with this id, or {} - the row is what knows where
    its own audio is (#908)."""
    want = str(line_id or "").strip()
    if not want:
        return {}
    try:
        for row in reversed(_RADIO.get("chat") or []):
            if str(row.get("id") or "") == want:
                return dict(row)
    except Exception:  # noqa: BLE001
        return {}
    return airlog_row(want)     # #1023 (G1): the durable log after the ring


# --- #1206: THE SAMPLER'S LEDGER ------------------------------------
#
# A pad is a moment the operator decided to keep. The station knows what
# that moment was; the sampler only knows which button it landed on. So
# the sampler says the line and the pad, and everything else is written
# here, where the air log, the ring and the deck are all in reach.
SAMPLER_GRABS_PATH = data_path("sampler_grabs.jsonl")
SAMPLER_GRAB_KEEP = 90 * 86400.0      # a kept moment outlives the air log
SAMPLER_GRAB_NEAR = 2                 # lines either side, for context


def sampler_grab_row(line_id: str, body: dict[str, Any]) -> dict[str, Any]:
    """Everything the station knows about the line on this pad, now.

    Blocking-free: the ring and the air-log index are both dicts in
    memory. Anything missing is left empty rather than guessed - a pad
    that cannot be traced should say so, not invent a provenance."""
    row = _booth_row(line_id)
    now = time.time()
    air_at = float(row.get("air_at") or row.get("ts") or 0)
    near: list[dict[str, Any]] = []
    if air_at:
        try:
            with _AIRLOG_LOCK:
                live = list(_AIRLOG_INDEX.values())
        except Exception:  # noqa: BLE001
            live = []
        live = [r for r in live
                if abs(float(r.get("air_at") or 0) - air_at) <= 90
                and str(r.get("id") or "") != str(line_id)]
        live.sort(key=lambda r: float(r.get("air_at") or 0))
        before = [r for r in live if float(r.get("air_at") or 0) < air_at]
        after = [r for r in live if float(r.get("air_at") or 0) >= air_at]
        for r in (before[-SAMPLER_GRAB_NEAR:] + after[:SAMPLER_GRAB_NEAR]):
            near.append({
                "id": str(r.get("id") or ""),
                "at": round(float(r.get("air_at") or 0), 3),
                "gap": round(float(r.get("air_at") or 0) - air_at, 2),
                "who": str(r.get("name") or r.get("who") or ""),
                "turn": r.get("turn"),
                "text": str(r.get("text") or "")[:180],
            })
    track = dict(_RADIO.get("now") or {})
    try:
        said = time.strftime("%Y-%m-%d %H:%M:%S",
                             time.localtime(air_at)) if air_at else ""
    except Exception:  # noqa: BLE001
        said = ""
    return {
        "at": round(now, 3),
        "kept_at": time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(now)),
        # --- which pad
        "bank": int(body.get("bank") or 0),
        "pad": int(body.get("pad") or 0),
        "label": str(body.get("label") or "")[:120],
        # --- where it came from
        "line": str(line_id or ""),
        "who": str(row.get("who") or ""),
        "name": str(row.get("name") or ""),
        "kind": str(row.get("kind") or ""),
        "round": str(row.get("round") or ""),
        "caller": str(row.get("caller") or ""),
        "voice": str(row.get("voice") or ""),
        "engine": str(row.get("engine") or ""),
        "source": str(row.get("source") or ""),
        "text": " ".join(str(row.get("text") or "").split())[:600],
        # --- where it sat in its script (#1201)
        "sid": str(row.get("sid") or ""),
        "turn": row.get("turn"),
        "turns": row.get("turns"),
        # --- the time step
        "air_at": round(air_at, 3) if air_at else None,
        "aired_at_local": said,
        "aired": str(row.get("aired") or ""),
        "ago_seconds": (round(now - air_at, 1) if air_at else None),
        # --- the exact window inside the welded round (#908/#1205)
        "clip_media": str(row.get("clip_media") or ""),
        "clip_from": row.get("clip_from"),
        "clip_until": row.get("clip_until"),
        "clip_tail": row.get("clip_tail"),
        "media": str(row.get("media") or ""),
        "seconds": (round(float(body["seconds"]), 2)
                    if str(body.get("seconds") or "").replace(".", "", 1)
                    .isdigit() else row.get("seconds")),
        # --- and what the cut road said about itself
        "cut": str(body.get("cut") or "")[:200],
        "exact": bool(body.get("exact")),
        "source_kind": str(body.get("kind") or "")[:24],
        # --- what else was going on
        "under": {"title": str(track.get("title") or "")[:140],
                  "id": str(track.get("id") or "")},
        "near": near,
        "traceable": bool(row),
    }


@app.post("/api/sampler/grab")
async def sampler_grab_api(
    body: dict[str, Any], authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """#1206: remember a moment that just went onto a pad."""
    require_auth(authorization)
    line = str(body.get("line") or body.get("srcId") or "").strip()
    if not line:
        raise HTTPException(status_code=400,
                            detail="pass line=<the booth row's id>")
    entry = sampler_grab_row(line, body if isinstance(body, dict) else {})

    def write() -> None:
        SAMPLER_GRABS_PATH.parent.mkdir(parents=True, exist_ok=True)
        with SAMPLER_GRABS_PATH.open("a", encoding="utf-8") as handle:
            handle.write(json.dumps(entry, ensure_ascii=False) + "\n")
        airlog_jsonl_trim(SAMPLER_GRABS_PATH, SAMPLER_GRAB_KEEP, "at")

    await asyncio.to_thread(write)
    return {"ok": True, "grab": entry,
            "say": ("pad %d remembers %s from %s"
                    % (int(entry["pad"]) + 1,
                       (entry["name"] or entry["who"] or "the booth"),
                       entry["aired_at_local"] or "an untraceable moment"))}


@app.get("/api/sampler/grabs")
async def sampler_grabs_api(
    most: int = 60,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """#1206: the pads' provenance, newest first."""
    require_read_auth(authorization)

    def read() -> list[dict[str, Any]]:
        out: list[dict[str, Any]] = []
        try:
            if not SAMPLER_GRABS_PATH.exists():
                return out
            with SAMPLER_GRABS_PATH.open("r", encoding="utf-8") as handle:
                for line in handle:
                    try:
                        got = json.loads(line)
                    except Exception:  # noqa: BLE001
                        continue
                    if isinstance(got, dict):
                        out.append(got)
        except Exception:  # noqa: BLE001
            return out
        return out

    rows = await asyncio.to_thread(read)
    rows.sort(key=lambda r: -float(r.get("at") or 0))
    kept = rows[:max(1, min(500, int(most)))]
    lost = sum(1 for r in rows if not r.get("traceable"))
    return {
        "at": time.time(), "kept": len(rows), "rows": kept,
        "untraceable": lost,
        "say": ("%d moment(s) kept on pads"
                % len(rows)) + (("; %d of them could not be traced back to "
                                 "a line - they were grabbed before #1206 "
                                 "or the row had already left the log"
                                 % lost) if lost else ""),
    }


@app.get("/api/booth/clip")
async def booth_clip_api(
    at: float = 0.0,
    line: str = "",
    whole: int = 0,
    authorization: str | None = Header(default=None),
) -> Response:
    """The audio behind ONE booth row - EXACTLY that row (#840, #908).

    `line` is the booth entry's own id and is the accurate road. `at`
    (epoch seconds) is the old air-time road, kept for rows written
    before the stamping and for anything that only knows a moment.
    `whole=1` deliberately asks for the surrounding moment instead of
    the one line.

    Three roads, in order of how much the row itself knows:

      1. the row says which welded round it lives in and where inside it
         - cut precisely that span. This is banter and every call, so it
         is most of what the station ever says;
      2. the row has its own one-line clip - hand it over with the
         BOX_TAIL_MS loop-pad taken back off the end;
      3. the row knows nothing - fall back to the air-time index, and
         SAY in the reply that what came back is the surrounding moment,
         rather than passing a whole round off as the line that was
         clicked.

    Every reply carries X-Pine-Cut (what was cut, in words) and
    X-Pine-Exact (1 when it is this row and nothing else), so the booth
    can tell the operator what he is holding instead of leaving him to
    find out on playback.
    """
    require_read_auth(authorization)
    row = _booth_row(line)
    if not at:
        at = float(row.get("air_at") or row.get("ts") or 0)
    if not at and not row:
        raise HTTPException(
            status_code=400,
            detail="pass line=<the booth row's id>, or at=<epoch seconds>")

    def _hand(path: str, what: str, exact: bool,
              name: str = "") -> FileResponse:
        ext = str(path).rsplit(".", 1)[-1].lower()
        return FileResponse(
            path,
            media_type=MEDIA_TYPES.get(ext, "audio/mpeg"),
            filename=name or f"booth-{int(at or time.time())}.{ext}",
            headers={"X-Pine-Cut": what[:180],
                     "X-Pine-Exact": "1" if exact else "0",
                     "Access-Control-Expose-Headers":
                         "X-Pine-Cut, X-Pine-Exact"})

    # 1. Inside a welded round: cut this turn out of the stream.
    _key = str(row.get("clip_media") or "")
    if _key and not whole and MEDIA_KEY_SHAPE.match(_key):
        src = VOICE_MEDIA_DIR / _key
        lo = max(0.0, float(row.get("clip_from") or 0.0))
        hi = max(lo, float(row.get("clip_until") or 0.0))
        if src.is_file() and hi - lo > 0.08:
            # Leave the seam beat off - see the note beside where these
            # numbers are written, in speak_turns.
            tail = max(0.0, float(row.get("clip_tail") or 0.0))
            span = hi - lo - tail
            if span < 0.2:
                span = hi - lo         # a very short turn keeps its beat
            cut = await booth_cut(str(src), lo, span)
            if cut:
                return _hand(cut, "this turn only - cut from the welded "
                                  f"round at {lo:.2f}s, {span:.2f}s long"
                                  + (f" ({tail:.2f}s of seam beat left "
                                     "off)" if tail and span < hi - lo
                                     else ""), True)

    # 2. Its own one-line clip, minus the loop-pad.
    _own = str(row.get("media") or "")
    if _own and not whole and MEDIA_KEY_SHAPE.match(_own):
        src = VOICE_MEDIA_DIR / _own
        if src.is_file():
            full = await asyncio.to_thread(_clip_seconds, str(src))
            pad = box_tail_seconds()
            # Keep a sliver of the pad - the same CONCAT_KEEP the mixer
            # leaves at a seam - so the cut can never land on the last
            # syllable. A clip that is MOSTLY pad is a clip something
            # else is wrong with: leave that one alone, because half a
            # word is worse radio than a beat of quiet.
            keep = full - pad + CONCAT_KEEP
            if full > 0.4 and pad > 0.05 and keep > 0.35 \
                    and keep > full * 0.5:
                cut = await booth_cut(str(src), 0.0, keep)
                if cut:
                    return _hand(cut, f"this line only - {keep:.2f}s, the "
                                      f"{pad:.2f}s box loop-pad trimmed",
                                 True)
            return _hand(str(src), "this line's own clip, exactly as it "
                                   "was recorded", True)

    # An advert IS its file, start to finish.
    _ad = str(row.get("ad_audio") or "")
    if _ad and not whole and AD_AUDIO_SHAPE.match(_ad):
        spot = PRODUCED_ADS_DIR / _ad
        if spot.is_file():
            return _hand(str(spot), "the produced spot, whole", True, _ad)

    # 3. Nothing on the row - the air-time index, said honestly.
    if not at:
        raise HTTPException(
            status_code=404,
            detail="that row carries no audio of its own and no air time "
                   "to look one up by - a line that never aired (held, "
                   "or dropped by a gate) has nothing to hand over")

    near = False                    # #908: did the index only get CLOSE?
    rows = await booth_index()
    if not rows:
        raise HTTPException(status_code=404,
                            detail="nothing is shelved yet — a line has "
                                   "to air before it can be downloaded")

    import bisect
    starts = [r[0] for r in rows]
    hit = None
    # the last span that begins at or before this moment, walking back
    # over any that end too early
    ix = bisect.bisect_right(starts, at) - 1
    while ix >= 0 and at - starts[ix] < 3600:
        began, ends, path, off = rows[ix]
        if began <= at < ends and Path(path).is_file():
            hit = rows[ix]
            break
        ix -= 1
    if hit is None:
        # A row can sit a moment before its file's stamp, so a hair of
        # slack is right. SIX seconds is not a hair: at conversational
        # pace it is the line before or the line after, and the old road
        # handed that neighbour over without a word said (#908). Tight
        # enough for clock skew, and whatever it finds is marked as the
        # near miss it is.
        ix = bisect.bisect_left(starts, at)
        for cand in (ix - 1, ix):
            if 0 <= cand < len(rows) and abs(rows[cand][0] - at) < 1.5 \
                    and Path(rows[cand][2]).is_file():
                hit = rows[cand]
                near = True
                break
    if hit is None:
        raise HTTPException(
            status_code=404,
            detail=(f"no audio kept for this row — {len(rows)} moment(s) "
                    "are shelved but none covers it. Lines older than "
                    "the last cache sweep are gone, and a line that "
                    "never aired (held or dropped) has no audio to "
                    "keep."))

    began, ends, path, off = hit
    source = Path(path)
    _near_say = (" - and this is the NEAREST shelved moment, not this "
                 "row's own" if near else "")
    # A staged file is one moment of the episode. When that moment is a
    # welded ROUND, handing it over whole is handing over everybody's
    # turns - so it goes out LABELLED rather than passed off as the line
    # that was clicked (#908). A row stamped by speak_turns never
    # reaches here at all; this is only for rows written before that,
    # and for rows the burst never claimed.
    if off <= 0.01 and source.parent == _EPISODE_STAGE:
        return _hand(str(source),
                     "the whole moment this line aired in, not the line "
                     "on its own" + _near_say, False)
    if off <= 0.01 and (_RADIO.get("episode") or {}).get("items"):
        for item in ((_RADIO.get("episode") or {}).get("items") or []):
            if str(item.get("file") or "") == path:
                return _hand(str(source),
                             "the whole moment this line aired in, not "
                             "the line on its own" + _near_say, False)
    # A sealed episode holds an hour; cut this moment out of it - for the
    # mark's OWN length. #908: max(4.0, ...) padded every short item out
    # to four seconds, so a 1.2 s sting came down as 1.2 s of sting plus
    # 2.8 s of whatever happened next. That is the "extra after" on this
    # road, and it was arithmetic rather than encoding.
    dur = max(0.35, min(900.0, ends - began))
    cut = await booth_cut(str(source), max(0.0, off), dur)
    if not cut:
        raise HTTPException(status_code=404,
                            detail="the cut failed - the episode this "
                                   "moment lives in could not be read")
    return _hand(cut, f"cut from the sealed episode at {off:.2f}s for "
                      f"{dur:.2f}s" + _near_say, False)

@app.post("/api/dj/line/vote")
async def dj_line_vote(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Thumb a line the pair just said up or down (#215).

    Up keeps it: it joins the approved bank and comes back on air in their own
    voices, on its own, the way anything approved does. Down buries it — it is
    dropped if it ever comes round again, and removed from the bank if it was
    in there."""
    require_auth(authorization)
    payload = await request.json()
    text = str(payload.get("text") or "").strip()
    if not text:
        raise HTTPException(status_code=400, detail="Which line?")
    vote = int(payload.get("vote") or 0)
    if vote > 0:
        marker = "B" if str(payload.get("who") or "") == "cohost" else "A"
        row = add_saved_banter(f"{marker}: {text}",
                               str(payload.get("source") or ""))
        return {"kept": row["id"], "vote": 1}
    bin_line(text)
    return {"buried": True, "vote": -1}


@app.get("/tape/{tape_key}")
async def tape_file(
    tape_key: str,
    request: Request,
    authorization: str | None = Header(default=None),
) -> Response:
    """Stream a mixtape (#239). Same contract as a track: shape check,
    signature or bearer, nosniff, ranges — a 100 MB wav must seek, not
    load."""
    if not re.fullmatch(r"[a-f0-9]{16}", tape_key):
        return Response(status_code=404)
    signature = media_sign(tape_key)
    if not (signature and hmac.compare_digest(
            str(request.query_params.get("t") or ""), signature)):
        require_auth(authorization)
    path = await asyncio.to_thread(tape_by_id, tape_key)
    if path is None:
        return Response(status_code=404)
    path = await asyncio.to_thread(tape_media, path)
    media_type = MUSIC_TYPES.get(path.suffix.lower(),
                                 "application/octet-stream")
    try:
        size = await asyncio.to_thread(lambda: path.stat().st_size)
    except Exception:
        return Response(status_code=404)
    headers = {
        "X-Content-Type-Options": "nosniff",
        "Accept-Ranges": "bytes",
        "Cache-Control": "private, max-age=3600",
    }
    window = _range_slice(str(request.headers.get("range") or ""), size)
    if window == (-1, -1):
        headers["Content-Range"] = f"bytes */{size}"
        return Response(status_code=416, headers=headers)
    if window:
        start, end = window
        # #1149: stream it, like /music (#883). This branch read the
        # whole requested window into memory before the first byte
        # moved, and a phone OPENS with `Range: bytes=0-` - on a 100MB
        # tape that is the whole file in RAM and a listener stalled.
        headers["Content-Range"] = f"bytes {start}-{end}/{size}"
        headers["Content-Length"] = str(end - start + 1)
        return StreamingResponse(_range_stream(path, start, end),
                                 status_code=206, headers=headers,
                                 media_type=media_type)
    return FileResponse(path, media_type=media_type, headers=headers)


SPEC_CACHE = VOICE_MEDIA_DIR / "spec"


def _render_spectrogram(source: Path, out: Path) -> bool:
    import subprocess

    import imageio_ffmpeg
    exe = imageio_ffmpeg.get_ffmpeg_exe()
    SPEC_CACHE.mkdir(parents=True, exist_ok=True)
    part = out.with_suffix(".part.png")
    try:
        subprocess.run(
            [exe, "-nostdin", "-loglevel", "error", "-y", "-i", str(source),
             "-lavfi", "showspectrumpic=s=560x140:legend=0", str(part)],
            check=True, timeout=300)
        part.replace(out)
        return True
    except Exception:
        part.unlink(missing_ok=True)
        return False


@app.get("/spec/{tape_key}/{which}")
async def tape_spectrogram(
    tape_key: str,
    which: str,
    request: Request,
    authorization: str | None = Header(default=None),
) -> Response:
    """A tape's spectrogram (#245): `orig` is the file as the recorder wrote
    it, `norm` is the corrected, normalized one actually served — side by
    side they show what had to be done for it to play right. Rendered once,
    kept."""
    if which not in ("orig", "norm") or not re.fullmatch(r"[a-f0-9]{16}",
                                                         tape_key):
        return Response(status_code=404)
    signature = media_sign(tape_key)
    if not (signature and hmac.compare_digest(
            str(request.query_params.get("t") or ""), signature)):
        require_auth(authorization)
    path = await asyncio.to_thread(tape_by_id, tape_key)
    if path is None:
        return Response(status_code=404)
    if which == "norm":
        target = tape_cache_path(path)
        if target is None or not target.exists():
            # Still normalizing — the panel retries until it lands.
            return Response(status_code=404)
    else:
        target = path
    out = SPEC_CACHE / f"{tape_key}-{which}-{target.stat().st_mtime_ns}.png"
    if not out.exists():
        if not await asyncio.to_thread(_render_spectrogram, target, out):
            return Response(status_code=404)
    return FileResponse(out, media_type="image/png", headers={
        "Cache-Control": "private, max-age=86400",
        "X-Content-Type-Options": "nosniff",
    })


def _bundle_name(text: str, fallback: str, at: int = 0) -> str:
    """A file name a human can read in a folder listing."""
    stem = re.sub(r"[^\w -]+", "", str(text or "")).strip()[:60] or fallback
    when = time.strftime("%Y%m%d-%H%M", time.localtime(float(at))) if at else ""
    return (f"{when}-{stem}" if when else stem).strip("-") or fallback


def _bundle_build(tab: str) -> tuple[Path, int]:
    """#781: "allow me to download each and every entry listed in the cache."

    Every tab of the radio cache, written out as one zip: the audio where a
    thing has audio, and the WORDS where it does not — which is most of the
    ad book, and was the real gap. A written spot only ever existed inside a
    textarea in a modal; there was no way to take it off the station at all.
    Names are the product and the date rather than the id hash, so the folder
    reads as a shelf."""
    import zipfile
    KIT_DIR.mkdir(parents=True, exist_ok=True)
    out = KIT_DIR / f"pinebox-cache-{tab}.zip"
    tmp = out.with_suffix(".part")
    want = ("talk", "mix", "ads", "upstairs") if tab == "all" else (tab,)
    seen: set[str] = set()
    count = 0

    def _put(zf: Any, arc: str, data: bytes | None = None,
             path: Path | None = None) -> None:
        nonlocal count
        stem, dot, ext = arc.rpartition(".")
        at = 2
        while arc in seen:              # two spots for the same product
            arc = f"{stem}-{at}{dot}{ext}"
            at += 1
        seen.add(arc)
        try:
            if path is not None:
                zf.write(path, arc)
            else:
                zf.writestr(arc, data or b"")
            count += 1
        except OSError:
            pass                        # a file that vanished mid-zip

    with zipfile.ZipFile(tmp, "w", zipfile.ZIP_DEFLATED) as zf:
        if "talk" in want:
            for kind in ("episodes", "calls"):
                here = RADIO_CACHE / kind
                for p in (sorted(here.glob("*.mp3"))
                          if here.is_dir() else []):
                    _put(zf, f"{kind}/{p.name}", path=p)
                    md = p.with_suffix(".md")
                    if md.is_file():
                        _put(zf, f"{kind}/{md.name}", path=md)
        if "mix" in want and (RADIO_CACHE / "broadcasts").is_dir():
            for p in sorted((RADIO_CACHE / "broadcasts").glob("*.mp3")):
                _put(zf, f"broadcasts/{p.name}", path=p)
        if "ads" in want:
            for row in ad_list():
                rid = str(row.get("id") or "")
                stem = _bundle_name(row.get("product") or "", "ad",
                                    int(row.get("ts") or 0))
                body = (f"# {row.get('product') or 'an ad read'}\n\n"
                        f"*written {time.strftime('%Y-%m-%d %H:%M', time.localtime(float(row.get('ts') or 0)))}"
                        f" · aired {int(row.get('uses') or 0)}x"
                        f"{' · bed: ' + str(row.get('bed')) if row.get('bed') else ''}*\n\n"
                        + str(row.get("text") or "").strip() + "\n")
                _put(zf, f"ads/{stem}.md", body.encode("utf-8"))
                mp3 = PRODUCED_ADS_DIR / f"{rid}.mp3"
                if rid and mp3.is_file():
                    _put(zf, f"ads/{stem}.mp3", path=mp3)
        if "upstairs" in want:
            for row in upstairs_list():
                stem = _bundle_name(row.get("gripe") or "", "page",
                                    int(row.get("ts") or 0))
                body = (f"# {row.get('gripe') or 'a page from upstairs'}\n\n"
                        f"*{time.strftime('%Y-%m-%d %H:%M', time.localtime(float(row.get('ts') or 0)))}"
                        f" · played {int(row.get('uses') or 0)}x*\n\n"
                        + (f"Written against: {row.get('context')}\n\n"
                           if row.get("context") else "")
                        + str(row.get("text") or "").strip() + "\n")
                _put(zf, f"upstairs/{stem}.md", body.encode("utf-8"))
                name = str(row.get("audio") or "")
                if name and (UPSTAIRS_AUDIO_DIR / name).is_file():
                    _put(zf, f"upstairs/{stem}.mp3",
                         path=UPSTAIRS_AUDIO_DIR / name)
    tmp.replace(out)
    return out, count


@app.get("/api/radio-cache/bundle/{tab}")
async def radio_cache_bundle(
    tab: str,
    request: Request,
    authorization: str | None = Header(default=None),
) -> Response:
    """The whole tab as one zip (#781). Signed like /media so the browser's
    own download can fetch it without a bearer header."""
    if tab not in ("talk", "mix", "ads", "upstairs", "all"):
        raise HTTPException(status_code=400, detail="No such shelf")
    _sig = str(request.query_params.get("t") or "")
    _want = media_sign(f"cache-bundle-{tab}")
    if not (_want and hmac.compare_digest(_sig, _want)):
        require_read_auth(authorization)
    path, count = await asyncio.to_thread(_bundle_build, tab)
    if not count:
        raise HTTPException(status_code=404, detail="nothing on that shelf yet")
    return FileResponse(path, media_type="application/zip",
                        filename=path.name)


@app.get("/api/prompts/archive.md", response_class=PlainTextResponse)
async def prompts_archive_md(
    authorization: str | None = Header(default=None),
) -> PlainTextResponse:
    """Every stored system prompt as one markdown file (#780) — grouped, with
    the armed one marked, so the library can be read and edited outside the
    panel and kept anywhere you keep writing."""
    require_read_auth(authorization)
    settings = load_settings()
    rows = list(settings.get("prompts") or [])
    live = int(settings.get("active_prompt") or 0) % max(1, len(rows))
    groups: dict[str, list[tuple[int, dict[str, Any]]]] = {}
    for at, row in enumerate(rows):
        groups.setdefault(str(row.get("group") or ""), []).append((at, row))
    out = [f"# {dj_settings()['station_name']} — system prompts", "",
           f"{len(rows)} stored. The armed one is marked ★.", ""]
    for name in sorted(groups, key=lambda g: (g == "", g.lower())):
        out.append(f"## {name or 'Ungrouped'}")
        out.append("")
        for at, row in groups[name]:
            out.append(f"### {'★ ' if at == live else ''}{row.get('name')}")
            out.append("")
            out.append(str(row.get("prompt") or "").strip())
            out.append("")
    return PlainTextResponse("\n".join(out),
                             headers={"Content-Disposition":
                                      'attachment; filename="pinebox-'
                                      'system-prompts.md"'})


@app.get("/api/radio-cache/bundle-sig")
async def radio_cache_bundle_sig(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """The signatures for the download links above."""
    require_read_auth(authorization)
    return {tab: media_sign(f"cache-bundle-{tab}")
            for tab in ("talk", "mix", "ads", "upstairs", "all")}


@app.get("/api/radio-cache/calls")
async def radio_cache_calls(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Every captured phone call in the radio cache, newest first (#548)."""
    require_read_auth(authorization)
    calls = RADIO_CACHE / "calls"
    out: list[dict[str, Any]] = []
    if calls.exists():
        for p in sorted(calls.glob("*.mp3"),
                        key=lambda q: q.stat().st_mtime, reverse=True)[:120]:
            _secs = 0.0
            try:
                from mutagen.mp3 import MP3
                _secs = float(MP3(str(p)).info.length or 0)
            except Exception:
                pass
            out.append({"name": p.name, "stem": p.stem,
                        "size": p.stat().st_size,
                        "seconds": round(_secs, 1),
                        "when": int(p.stat().st_mtime),
                        # A bare <audio> can't send a bearer header, and only
                        # localhost is trusted for reads — so from another PC
                        # the player got a silent 401 (0:00/0:00). Sign the
                        # URL the way /media does.
                        "sig": media_sign(p.name),
                        "md_sig": media_sign(p.stem + ".md"),
                        "has_transcript": p.with_suffix(".md").exists()})
    return {"calls": out, "folder": str(calls)}


@app.get("/api/radio-cache/calls/{name}")
async def radio_cache_call_file(
    name: str,
    request: Request,
    authorization: str | None = Header(default=None),
) -> Response:
    """Serve a cached call mp3 or its .md transcript for replay/download.
    A signed ?t= stands in for the bearer header (a bare <audio> can't send
    one, and reads are only localhost-trusted) — same contract as /media."""
    _sig = str(request.query_params.get("t") or "")
    _want = media_sign(name)
    if not (_want and hmac.compare_digest(_sig, _want)):
        require_read_auth(authorization)
    if "/" in name or ".." in name or not re.fullmatch(
            r"[\w.\- ]{1,120}", name):
        raise HTTPException(status_code=400, detail="Bad name")
    path = RADIO_CACHE / "calls" / name
    if not path.is_file():
        raise HTTPException(status_code=404, detail="Not in the cache")
    media = "audio/mpeg" if name.endswith(".mp3") else "text/markdown"
    # FileResponse handles Range requests (#589/#590): a bare <audio> in the
    # cache modal needs 206 / Accept-Ranges to play IN-WINDOW — a full-body 200
    # (read_bytes) downloads fine but a lot of browsers won't play it back.
    return FileResponse(path, media_type=media,
                        headers={"Cache-Control": "private, max-age=3600"})


@app.get("/api/radio-cache/episodes")
async def radio_cache_episodes(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Every sealed ~15-minute broadcast episode, newest first — the offline
    replay shelf (#548). The in-progress episode is reported too."""
    require_read_auth(authorization)
    eps = RADIO_CACHE / "episodes"
    out: list[dict[str, Any]] = []
    if eps.exists():
        for p in sorted(eps.glob("*.mp3"),
                        key=lambda q: q.stat().st_mtime, reverse=True)[:120]:
            _secs = 0.0
            try:
                from mutagen.mp3 import MP3
                _secs = float(MP3(str(p)).info.length or 0)
            except Exception:
                pass
            out.append({"name": p.name, "stem": p.stem,
                        "size": p.stat().st_size,
                        "seconds": round(_secs, 1),
                        "when": int(p.stat().st_mtime),
                        # Signed like /media so a bare <audio> plays from any
                        # PC on the network (reads are localhost-trusted only).
                        "sig": media_sign(p.name),
                        "md_sig": media_sign(p.stem + ".md"),
                        "has_transcript": p.with_suffix(".md").exists()})
    ep = _RADIO.get("episode") or {}
    recording = {
        "clips": len(ep.get("items") or []),
        "seconds": round(time.time() - float(ep.get("started") or time.time()))
        if ep.get("items") else 0,
    }
    return {"episodes": out, "recording": recording, "folder": str(eps)}


@app.get("/api/radio-cache/broadcasts")
async def radio_cache_broadcasts(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """The collected FULL MIXES, newest first (#667) — the broadcast as it
    sounded, records mixed back in and ducked under the voices, one per
    sealed episode. Same shape as the talk shelf so the tab that lists them
    can be the same tab."""
    require_read_auth(authorization)
    out: list[dict[str, Any]] = []
    if BROADCASTS_DIR.exists():
        for p in sorted(BROADCASTS_DIR.glob("*.mp3"),
                        key=lambda q: q.stat().st_mtime, reverse=True)[:120]:
            _secs = 0.0
            try:
                from mutagen.mp3 import MP3
                _secs = float(MP3(str(p)).info.length or 0)
            except Exception:
                pass
            out.append({"name": p.name, "stem": p.stem,
                        "size": p.stat().st_size,
                        "seconds": round(_secs, 1),
                        "when": int(p.stat().st_mtime),
                        "sig": media_sign(p.name),
                        "md_sig": media_sign(p.stem + ".md"),
                        "has_transcript": p.with_suffix(".md").exists()})
    ep = _RADIO.get("episode") or {}
    return {
        "broadcasts": out,
        "levels": mix_levels(),
        "folder": str(BROADCASTS_DIR),
        # What the next collected mix will be cut from, so the tab can say
        # "gathering" the way the talk tab says "recording".
        "gathering": {
            "clips": len(ep.get("items") or []),
            "seconds": round(time.time()
                             - float(ep.get("started") or time.time()))
            if ep.get("items") else 0,
            "mixing": bool(_MIX_GATE),
            "on": bool(_RADIO.get("on")),
        },
    }


@app.post("/api/radio-cache/broadcasts/levels")
async def radio_cache_mix_levels(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """The levels every COLLECTED mix is rendered at (#667). The browser's
    own three sliders, kept server-side — the collector runs whether or not
    a browser is open, so it cannot read them off a page."""
    require_auth(authorization)
    payload = await request.json() if await request.body() else {}
    current = mix_levels()

    def pick(key: str) -> float:
        try:
            return float(payload[key])
        except (KeyError, TypeError, ValueError):
            return current[key]

    return {"levels": mix_levels_save(pick("music"), pick("duck"),
                                      pick("voice"))}


@app.post("/api/radio-cache/broadcasts/collect")
async def radio_cache_collect_now(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Seal what is on the shelf right now and collect its full mix (#667)
    — the "keep this stretch" button, for when the last twenty minutes were
    worth keeping and you would rather not wait for the clock."""
    require_auth(authorization)
    if _MIX_GATE:
        return {"collecting": True, "already": True}
    sealed = await asyncio.to_thread(_episode_finalize)
    if not sealed:
        raise HTTPException(
            status_code=404,
            detail="Nothing on the shelf to seal — the pair have to have "
                   "aired something since the last cut.")
    asyncio.create_task(broadcast_collect(sealed))
    return {"collecting": True, "stem": sealed.get("stem", "")}


@app.post("/api/radio-cache/broadcasts/remix")
async def radio_cache_remix(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Rebuild one collected set at different levels (#701).

    The sets are rendered when they are collected, so changing the sliders
    afterwards could not reach them — you had to wait for the next one. This
    re-cuts the same stretch of the night at whatever the sliders say now,
    in place, so playback and the download both follow."""
    require_auth(authorization)
    payload = await request.json() if await request.body() else {}
    name = str(payload.get("name") or "")
    if "/" in name or ".." in name or not re.fullmatch(
            r"[\w.\- ]{1,120}", name):
        raise HTTPException(status_code=400, detail="Bad name")
    target = BROADCASTS_DIR / name
    side = target.with_suffix(".json")
    if not target.is_file() or not side.is_file():
        raise HTTPException(
            status_code=404,
            detail="That set has no timing sidecar — only sets collected "
                   "from this update on can be re-cut.")
    try:
        window = json.loads(side.read_text())
        lo, hi = float(window["lo"]), float(window["hi"])
    except Exception:
        raise HTTPException(status_code=400, detail="Unreadable sidecar")
    levels = mix_levels()
    for key in ("music", "duck", "voice"):
        if key in payload:
            try:
                levels[key] = float(payload[key])
            except (TypeError, ValueError):
                pass
    mix_levels_save(levels["music"], levels["duck"], levels["voice"])
    if _MIX_GATE:
        raise HTTPException(status_code=409,
                            detail="A mix is already rendering — one at a time.")
    _MIX_GATE.append(1)
    try:
        built = await asyncio.to_thread(
            _broadcast_mix, lo, hi,
            max(0.0, min(2.0, levels["music"] / 100)),
            max(0.0, min(0.9, levels["duck"] / 100)),
            max(0.25, min(2.0, levels["voice"] / 100)),
            "_remix")
    finally:
        _MIX_GATE.clear()
    if not built:
        raise HTTPException(status_code=500, detail="The re-cut came out empty")
    built.replace(target)
    try:
        side.write_text(json.dumps({"lo": lo, "hi": hi, "levels": levels}))
    except OSError:
        pass
    return {"remixed": name, "levels": levels,
            "seconds": round(hi - lo, 1),
            "sig": media_sign(name)}


@app.post("/api/radio-cache/span")
async def radio_cache_span(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """#837: cut the broadcast AS IT SOUNDED for an arbitrary window —
    the call-download button. Talk, records, ads, stings — everything
    that aired inside [lo, hi], mixed at the current levels, shelved
    with the collected sets so it also shows in the Broadcast tab."""
    require_auth(authorization)
    payload = await request.json()
    try:
        lo = float(payload["lo"])
        hi = float(payload["hi"])
    except Exception:
        raise HTTPException(status_code=400,
                            detail="lo and hi, epoch seconds")
    if not (0 < hi - lo <= 3600):
        raise HTTPException(status_code=400,
                            detail="a span between 1s and 60 minutes")
    label = (re.sub(r"[^\w\- ]+", "",
                    str(payload.get("label") or "call"))[:40]
             .strip().replace(" ", "-") or "call")
    if _MIX_GATE:
        raise HTTPException(
            status_code=409,
            detail="A mix is already rendering — one at a time.")
    # #837: a call that JUST ended still lives in the open episode — the
    # rebuild only reads sealed ones, so seal first when they overlap.
    ep = _RADIO.get("episode") or {}
    if (ep.get("items") or []) and float(ep.get("started") or 0) < hi:
        sealed = await asyncio.to_thread(_episode_finalize)
        if sealed:
            pipeline_log("air", "sealed the open episode so the span cut "
                                "can include it (#837)")
    levels = mix_levels()
    _MIX_GATE.append(1)
    try:
        built = await asyncio.to_thread(
            _broadcast_mix, lo, hi,
            max(0.0, min(2.0, levels["music"] / 100)),
            max(0.0, min(0.9, levels["duck"] / 100)),
            max(0.25, min(2.0, levels["voice"] / 100)),
            "_span")
    finally:
        _MIX_GATE.clear()
    if not built:
        raise HTTPException(status_code=500,
                            detail="The cut came out empty")
    stamp = time.strftime("%Y%m%d-%H%M%S", time.localtime(lo))
    name = f"{label}-{stamp}.mp3"
    BROADCASTS_DIR.mkdir(parents=True, exist_ok=True)
    target = BROADCASTS_DIR / name
    built.replace(target)
    try:
        target.with_suffix(".json").write_text(
            json.dumps({"lo": lo, "hi": hi, "levels": levels}))
    except OSError:
        pass
    pipeline_log("air", f"a {int(hi - lo)}s call segment was cut from "
                        f"the broadcast rebuild — {name} (#837)")
    return {"name": name, "seconds": round(hi - lo, 1),
            "url": f"/api/radio-cache/broadcasts/{name}"
                   f"?t={media_sign(name)}"}


@app.get("/api/radio-cache/broadcasts/{name}")
async def radio_cache_broadcast_file(
    name: str,
    request: Request,
    authorization: str | None = Header(default=None),
) -> Response:
    """Serve a collected full mix or its transcript (#667). Signed ?t= like
    every other cache file — a bare <audio> cannot send a bearer header."""
    _sig = str(request.query_params.get("t") or "")
    _want = media_sign(name)
    if not (_want and hmac.compare_digest(_sig, _want)):
        require_read_auth(authorization)
    if "/" in name or ".." in name or not re.fullmatch(
            r"[\w.\- ]{1,120}", name):
        raise HTTPException(status_code=400, detail="Bad name")
    path = BROADCASTS_DIR / name
    if not path.is_file():
        raise HTTPException(status_code=404, detail="Not in the cache")
    media = "audio/mpeg" if name.endswith(".mp3") else "text/markdown"
    return FileResponse(path, media_type=media,
                        headers={"Cache-Control": "private, max-age=3600"})


@app.get("/api/radio-cache/episodes/{name}")
async def radio_cache_episode_file(
    name: str,
    request: Request,
    authorization: str | None = Header(default=None),
) -> Response:
    """Serve a sealed episode mp3 or its .md transcript for offline replay.
    A signed ?t= stands in for the bearer header (a bare <audio> can't send
    one, and reads are only localhost-trusted) — same contract as /media."""
    _sig = str(request.query_params.get("t") or "")
    _want = media_sign(name)
    if not (_want and hmac.compare_digest(_sig, _want)):
        require_read_auth(authorization)
    if "/" in name or ".." in name or not re.fullmatch(
            r"[\w.\- ]{1,120}", name):
        raise HTTPException(status_code=400, detail="Bad name")
    path = RADIO_CACHE / "episodes" / name
    if not path.is_file():
        raise HTTPException(status_code=404, detail="Not in the cache")
    media = "audio/mpeg" if name.endswith(".mp3") else "text/markdown"
    # FileResponse handles Range requests (#589/#590): a bare <audio> in the
    # cache modal needs 206 / Accept-Ranges to play IN-WINDOW — a full-body 200
    # (read_bytes) downloads fine but a lot of browsers won't play it back.
    return FileResponse(path, media_type=media,
                        headers={"Cache-Control": "private, max-age=3600"})


def _cache_compile(kind: str, scope: str,
                   lo_override: float | None = None,
                   hi_override: float | None = None) -> Path | None:
    """Concatenate the cached mp3s in a date window into ONE mp3 for offline
    review (#600): the day, the previous day, the week, the month, or the whole
    history — episodes, calls, or "all" (BOTH shelves interleaved in air
    order, the unified file). An explicit lo/hi window overrides the scope,
    so the calendar can ask for any day/week/month in history. Stream-copy
    (no re-encode); re-encodes only if a param mismatch trips the copy."""
    import subprocess
    import imageio_ffmpeg
    if kind == "all":
        files: list[Path] = []
        for sub in ("episodes", "calls"):
            d = RADIO_CACHE / sub
            if d.exists():
                files += list(d.glob("*.mp3"))
        files.sort(key=lambda p: p.stat().st_mtime)
    else:
        folder = _cache_folder(kind)
        if not folder.exists():
            return None
        files = sorted(folder.glob("*.mp3"), key=lambda p: p.stat().st_mtime)
    now = time.time()
    lt = time.localtime(now)
    midnight = now - (lt.tm_hour * 3600 + lt.tm_min * 60 + lt.tm_sec)
    lo, hi = 0.0, now + 1.0
    if scope == "today":
        lo = midnight
    elif scope == "yesterday":
        lo, hi = midnight - 86400, midnight
    elif scope == "week":
        lo = now - 7 * 86400
    elif scope == "month":
        lo = now - 30 * 86400
    if lo_override is not None:
        lo, hi = lo_override, (hi_override
                               if hi_override is not None else now + 1.0)
    picks = [p for p in files if lo <= p.stat().st_mtime < hi]
    if not picks:
        return None
    exe = imageio_ffmpeg.get_ffmpeg_exe()
    RADIO_CACHE.mkdir(parents=True, exist_ok=True)
    listing = RADIO_CACHE / f"_compile_{kind}_{scope}.txt"
    listing.write_text("\n".join(
        "file '" + p.as_posix().replace("'", "'\\''") + "'" for p in picks))
    out = RADIO_CACHE / f"_compile_{kind}_{scope}.mp3"
    base = [exe, "-nostdin", "-hide_banner", "-loglevel", "error", "-y",
            "-f", "concat", "-safe", "0", "-i", str(listing)]
    try:
        r = subprocess.run(base + ["-c", "copy", str(out)],
                           capture_output=True, timeout=900)
        if r.returncode != 0:
            subprocess.run(base + ["-c:a", "libmp3lame", "-b:a", "96k",
                                   "-ar", "24000", "-ac", "1", str(out)],
                           capture_output=True, timeout=1800)
    except Exception:
        return None
    finally:
        listing.unlink(missing_ok=True)
    return out if out.is_file() and out.stat().st_size > 1000 else None


def _cache_export(kind: str, scope: str, max_mb: float,
                  hourly: bool) -> Path | None:
    """Export a span of the broadcast as MULTIPLE mp3s zipped together:
    either continuous chunks capped at max_mb (split at mp3 frame
    boundaries, stream-copy, so a 100 MB cap or 3 MB clips both come out
    continuous), or one clip per wall-clock hour. Parts are named so they
    sort in broadcast order; the zip is the single deliverable."""
    import shutil
    import subprocess
    import zipfile

    import imageio_ffmpeg
    exe = imageio_ffmpeg.get_ffmpeg_exe()
    work = RADIO_CACHE / "_export"
    shutil.rmtree(work, ignore_errors=True)
    work.mkdir(parents=True, exist_ok=True)
    parts: list[Path] = []
    if hourly:
        folder = _cache_folder(kind)
        if not folder.exists():
            return None
        files = sorted(folder.glob("*.mp3"), key=lambda p: p.stat().st_mtime)
        now = time.time()
        lt = time.localtime(now)
        midnight = now - (lt.tm_hour * 3600 + lt.tm_min * 60 + lt.tm_sec)
        lo, hi = 0.0, now + 1.0
        if scope == "today":
            lo = midnight
        elif scope == "yesterday":
            lo, hi = midnight - 86400, midnight
        elif scope == "week":
            lo = now - 7 * 86400
        elif scope == "month":
            lo = now - 30 * 86400
        picks = [p for p in files if lo <= p.stat().st_mtime < hi]
        if not picks:
            return None
        hours: dict[str, list[Path]] = {}
        for p in picks:
            stamp = time.strftime("%Y-%m-%d_%Hh",
                                  time.localtime(p.stat().st_mtime))
            hours.setdefault(stamp, []).append(p)
        for stamp, group in sorted(hours.items()):
            listing = work / f"_{stamp}.txt"
            listing.write_text("\n".join(
                "file '" + q.as_posix().replace("'", "'\\''") + "'"
                for q in group))
            part = work / f"{kind}_{stamp}.mp3"
            base = [exe, "-nostdin", "-hide_banner", "-loglevel", "error",
                    "-y", "-f", "concat", "-safe", "0", "-i", str(listing)]
            try:
                r = subprocess.run(base + ["-c", "copy", str(part)],
                                   capture_output=True, timeout=600)
                if r.returncode != 0:
                    subprocess.run(
                        base + ["-c:a", "libmp3lame", "-b:a", "96k",
                                "-ar", "24000", "-ac", "1", str(part)],
                        capture_output=True, timeout=1200)
            except Exception:
                continue
            finally:
                listing.unlink(missing_ok=True)
            if part.is_file() and part.stat().st_size > 1000:
                parts.append(part)
    else:
        # Continuous chunks under the size cap: build the one big mp3, then
        # segment it by TIME derived from its own measured bitrate (aimed a
        # little under the cap so no part lands over).
        big = _cache_compile(kind, scope)
        if not big:
            return None
        bps = 12000.0                      # 96 kbps fallback
        try:
            from mutagen.mp3 import MP3
            secs = float(MP3(str(big)).info.length or 0)
            if secs > 1:
                bps = big.stat().st_size / secs
        except Exception:
            pass
        seg = max(30, int(max_mb * 1024 * 1024 * 0.95 / bps))
        try:
            subprocess.run(
                [exe, "-nostdin", "-hide_banner", "-loglevel", "error", "-y",
                 "-i", str(big), "-f", "segment",
                 "-segment_time", str(seg), "-c", "copy",
                 str(work / f"{kind}_{scope}_part%03d.mp3")],
                capture_output=True, timeout=900)
        except Exception:
            return None
        parts = sorted(work.glob("*.mp3"))
    if not parts:
        return None
    out = RADIO_CACHE / f"_export_{kind}_{scope}.zip"
    with zipfile.ZipFile(out, "w", zipfile.ZIP_STORED) as z:
        for p in parts:
            z.write(p, p.name)
    shutil.rmtree(work, ignore_errors=True)
    return out


@app.get("/api/radio-cache/export")
async def radio_cache_export_api(
    kind: str = "episodes",
    scope: str = "today",
    max_mb: float = 100.0,
    hourly: int = 0,
    authorization: str | None = Header(default=None),
) -> Response:
    """The chunked export: the span's broadcast as multiple mp3s in one zip —
    continuous parts capped at max_mb (100 MB albums, 3 MB clips), or one
    clip per wall-clock hour."""
    require_read_auth(authorization)
    if kind not in ("episodes", "calls", "broadcasts"):
        raise HTTPException(status_code=400, detail="kind must be episodes|calls")
    if scope not in ("today", "yesterday", "week", "month", "all"):
        raise HTTPException(status_code=400, detail="bad scope")
    max_mb = max(1.0, min(500.0, float(max_mb or 100)))
    if kind == "episodes" and scope in ("today", "all"):
        try:
            await asyncio.to_thread(_episode_finalize)   # up to this moment
        except Exception:
            pass
    path = await asyncio.to_thread(_cache_export, kind, scope, max_mb,
                                   bool(hourly))
    if not path:
        raise HTTPException(status_code=404,
                            detail="Nothing recorded in that range yet")
    stamp = time.strftime("%Y-%m-%d")
    label = "hourly" if hourly else f"{max_mb:g}mb"
    return FileResponse(
        path, media_type="application/zip",
        filename=f"pinebox-{kind}-{scope}-{label}-{stamp}.zip",
        headers={"Cache-Control": "no-store"})


def _cache_tail(seconds: float) -> Path | None:
    """The last N seconds of the broadcast as one mp3, whatever it takes.

    Three things used to break this (#630). The window was read only from
    the live staging, so anything the 15-minute seal had already swept onto
    the shelf was invisible — ask for fifteen minutes just after a seal and
    the answer was nothing. Selection went by file mtime, which is when a
    clip was WRITTEN: sfx stings carry their sample's date and never made
    the cut. And the concat was one multi-branch filtergraph, which this
    static build crashes on (the tape and the vocoder both learned that) —
    unchecked, so a crash served the previous grab's file instead.

    So: reach through the seal onto the episode shelf, select on aired-at,
    join in PCM like /api/dj/tape, and write a fresh file every time.
    """
    import subprocess
    import tempfile

    import imageio_ffmpeg
    now = time.time()
    cutoff = now - seconds
    # sources are (path, head-trim seconds) in air order
    sources: list[tuple[Path, float]] = []

    # The shelf first: an episode sealed inside the window is broadcast that
    # aired inside the window. Its head is trimmed to where the window opens.
    try:
        shelf = []
        for path in (RADIO_CACHE / "episodes").glob("*.mp3"):
            try:
                sealed = path.stat().st_mtime
            except OSError:
                continue
            if sealed >= cutoff:
                shelf.append((sealed, path))
        for sealed, path in sorted(shelf):
            length = 0.0
            try:
                from mutagen.mp3 import MP3
                length = float(MP3(str(path)).info.length or 0)
            except Exception:
                pass
            began = sealed - length if length else sealed
            sources.append((path, max(0.0, cutoff - began)))
    except Exception:
        pass

    # Then everything staged since that seal, in air order.
    items = (_RADIO.get("episode") or {}).get("items") or []
    staged: list[Path] = []
    for item in items:
        path = Path(str(item.get("file") or ""))
        if not path.is_file():
            continue
        aired = float(item.get("t") or 0)
        if not aired:
            try:
                aired = path.stat().st_mtime     # staged before the stamp
            except OSError:
                continue
        if aired >= cutoff:
            staged.append(path)
    if not staged and not sources and items:
        last = Path(str(items[-1].get("file") or ""))
        if last.is_file():
            staged = [last]                      # the latest beats nothing
    sources += [(path, 0.0) for path in staged]
    if not sources:
        return None

    # A fresh name per cut: the old fixed _tail.mp3 meant a failed run served
    # the previous one, and two requests fought over the same file.
    for stale in RADIO_CACHE.glob("_tail*.mp3"):
        try:
            if now - stale.stat().st_mtime > 600:
                stale.unlink()
        except OSError:
            pass
    out = RADIO_CACHE / f"_tail_{int(now * 1000)}.mp3"
    exe = imageio_ffmpeg.get_ffmpeg_exe()
    gap = b"\x00" * int(24000 * 0.25) * 2
    pcm = bytearray()
    try:
        with tempfile.TemporaryDirectory(prefix="tail-") as work:
            for at, (src, trim) in enumerate(sources):
                cut = Path(work) / f"in{at}.wav"
                try:
                    subprocess.run(
                        [exe, "-nostdin", "-loglevel", "error", "-y",
                         "-i", str(src),
                         # after -i: decode-accurate, no bit-reservoir glitch
                         *(["-ss", f"{trim:.2f}"] if trim > 0.05 else []),
                         "-ac", "1", "-ar", "24000", "-sample_fmt", "s16",
                         str(cut)],
                        check=True, timeout=300)
                    with wave.open(str(cut), "rb") as handle:
                        pcm += handle.readframes(handle.getnframes())
                    pcm += gap
                    cut.unlink(missing_ok=True)
                except Exception:
                    continue          # a clip swept up by a seal mid-cut
            if len(pcm) < 24000:
                return None
            joined = Path(work) / "tail.wav"
            with wave.open(str(joined), "wb") as handle:
                handle.setnchannels(1)
                handle.setsampwidth(2)
                handle.setframerate(24000)
                handle.writeframes(bytes(pcm))
            subprocess.run(
                [exe, "-nostdin", "-hide_banner", "-loglevel", "error", "-y",
                 "-i", str(joined), "-codec:a", "libmp3lame", "-b:a", "96k",
                 str(out)],
                check=True, timeout=600)
    except Exception:
        return None
    return out if out.is_file() and out.stat().st_size > 1000 else None


@app.get("/api/radio-cache/tail")
async def radio_cache_tail_api(
    seconds: int = 30,
    authorization: str | None = Header(default=None),
) -> Response:
    """Download the last N seconds of the broadcast (10s–1h) — the live
    staging plus whatever the seal already shelved, no seal required."""
    require_read_auth(authorization)
    seconds = max(10, min(3600, int(seconds or 30)))
    path = await asyncio.to_thread(_cache_tail, float(seconds))
    if not path:
        raise HTTPException(status_code=404,
                            detail="Nothing aired in that window yet")
    stamp = time.strftime("%H%M%S")
    return FileResponse(
        path, media_type="audio/mpeg",
        filename=f"{station_slug()}-last-{seconds}s-{stamp}.mp3",
        headers={"Cache-Control": "no-store"})


# --- The cut tray (#727) ----------------------------------------------------
#
# Cutting a clip used to be: press, wait with the button spinning, get a file
# in Downloads, and if you wanted a second one you waited for the first. The
# cut runs behind you now and lands HERE — named, playable, one link away —
# so you can queue several and take them all at once.
CUTS_DIR = RADIO_CACHE / "cuts"
CUTS_KEEP = 40
# job id -> {state, name, error, at, label}
_CUT_JOBS: dict[str, dict[str, Any]] = {}
# One at a time, genuinely queued: _cache_tail sweeps its own stale output at
# the start of every run, so two cuts in flight would eat each other's file.
_CUT_LOCK = asyncio.Lock()


def _cuts_trim() -> None:
    try:
        made = sorted(CUTS_DIR.glob("*.mp3"), key=lambda p: p.stat().st_mtime)
    except OSError:
        return
    for old in made[:-CUTS_KEEP]:
        old.unlink(missing_ok=True)


def _cut_list() -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []
    try:
        made = sorted(CUTS_DIR.glob("*.mp3"),
                      key=lambda p: p.stat().st_mtime, reverse=True)
    except OSError:
        made = []
    for p in made:
        secs = 0.0
        try:
            from mutagen.mp3 import MP3
            secs = float(MP3(str(p)).info.length or 0)
        except Exception:
            pass
        out.append({"name": p.name, "stem": p.stem,
                    "size": p.stat().st_size, "seconds": round(secs, 1),
                    "when": int(p.stat().st_mtime),
                    "sig": media_sign(p.name)})
    return out


async def _cut_run(job: str, kind: str, seconds: int,
                   levels: dict[str, float], label: str) -> None:
    """One cut, off the request thread, into the tray."""
    async with _CUT_LOCK:
        await _cut_do(job, kind, seconds, levels, label)


async def _cut_do(job: str, kind: str, seconds: int,
                  levels: dict[str, float], label: str) -> None:
    _CUT_JOBS[job] = {"state": "cutting", "at": time.time(), "name": "",
                      "label": label, "error": ""}
    try:
        if kind == "mix":
            # #774: seal the running episode FIRST. The mix is rebuilt from
            # the episode sidecars, and everything said in the last few
            # minutes — which is the entire point of "cut the last stretch"
            # — is still staged with no sidecar to read. Without this the
            # records came through and the pair and the ads did not. The
            # compile road has done this since #624 for the same reason.
            try:
                await asyncio.to_thread(_episode_finalize)
            except Exception:
                pass                    # a cut of the shelf beats no cut
            lo = time.time() - seconds
            built = await asyncio.to_thread(
                _broadcast_mix, lo, time.time() + 1.0,
                max(0.0, min(2.0, levels["music"] / 100)),
                max(0.0, min(0.9, levels["duck"] / 100)),
                max(0.25, min(2.0, levels["voice"] / 100)),
                f"_cut{job}")
        else:
            built = await asyncio.to_thread(_cache_tail, float(seconds))
        if not built:
            _CUT_JOBS[job].update(
                {"state": "empty",
                 "error": "Nothing aired in that window yet"})
            return
        CUTS_DIR.mkdir(parents=True, exist_ok=True)
        name = (f"{station_slug()}-{'broadcast' if kind == 'mix' else 'talk'}"
                f"-{seconds}s-{time.strftime('%H%M%S')}-{job}.mp3")
        target = CUTS_DIR / name
        try:
            built.replace(target)
        except OSError:
            target.write_bytes(built.read_bytes())
        _cuts_trim()
        _CUT_JOBS[job].update({"state": "ready", "name": name})
    except Exception as exc:                  # noqa: BLE001
        _CUT_JOBS[job].update({"state": "failed", "error": str(exc)[:200]})



# --- #1025: the spoken export - where a cut goes besides the tray ----------
# "Remember the export directory." Only /app is writable from the container
# (compose mounts ./spark-agent:/app; /music and /samples are :ro), so a
# directory the operator names is honoured only when it is INSIDE the
# station's data folder - spoken as the host path, the share path, or a
# bare folder name - and refused, out loud, with the places that work.
EXPORT_DEFAULT_DIR = "data/export/broadcasts"
EXPORT_HOST_ROOT = "~/pinevoice-stack/spark-agent/data"
EXPORT_SHARE_ROOT = r"\\10.89.1.246\ehm_eckx\pinevoice-stack\spark-agent\data"
_EXPORT_ROOTS = (
    # (backslashes and doubled slashes are collapsed first, so the share's
    # leading \\ arrives here as one slash)
    r"/10\.89\.1\.246/ehm_eckx/pinevoice-stack/spark-agent/data",
    r"~/pinevoice-stack/spark-agent/data",
    r"/home/[^/]+/pinevoice-stack/spark-agent/data",
    r"/app/data",
    r"data",
    r"\./data",
)


def export_resolve(raw: str) -> Path | None:
    r"""A spoken/typed directory -> a Path under DATA_DIR, or None when the
    container could not write there. Accepts the host form
    (~/pinevoice-stack/spark-agent/data/x), the share form
    (\\10.89.1.246\ehm_eckx\pinevoice-stack\spark-agent\data\x), /app/data/x,
    data/x, and a bare folder name (-> data/export/<name>)."""
    said = str(raw or "").strip().strip("\"'`").strip()
    if not said:
        return None
    flat = re.sub(r"/+", "/", said.replace("\\", "/")).rstrip("/")
    if not flat:
        return None
    for root in _EXPORT_ROOTS:
        got = re.match(r"^(?:" + root + r")(?:/(?P<rest>.+))?$", flat, re.I)
        if got:
            rest = str(got.group("rest") or "").strip("/")
            parts = [p for p in rest.split("/")
                     if p and p not in (".", "..")]
            return (DATA_DIR.joinpath(*parts) if parts
                    else DATA_DIR / "export" / "broadcasts")
    try:
        here = str(DATA_DIR).replace("\\", "/").rstrip("/")
        if flat.lower().startswith(here.lower() + "/") or flat.lower() == here.lower():
            rest = flat[len(here):].strip("/")
            parts = [p for p in rest.split("/") if p and p not in (".", "..")]
            return (DATA_DIR.joinpath(*parts) if parts
                    else DATA_DIR / "export" / "broadcasts")
    except Exception:  # noqa: BLE001
        pass
    if "/" not in flat and re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9 _.'-]{0,60}",
                                        flat):
        # "save broadcasts to my exports folder" -> data/export/my-exports
        name = re.sub(r"\s+(folder|directory|dir)$", "", flat.strip(), flags=re.I)
        name = re.sub(r"[^A-Za-z0-9._-]+", "-", name).strip("-.")
        if name:
            return DATA_DIR / "export" / name
    return None


def export_host_words(path: Path) -> str:
    """The host-visible name of a data path, for saying out loud."""
    try:
        rel = path.relative_to(DATA_DIR)
        return EXPORT_HOST_ROOT + "/" + str(rel).replace("\\", "/")
    except Exception:  # noqa: BLE001
        return str(path)


def export_dir_path() -> Path:
    """Where the spoken export lands, from the setting (#1025)."""
    try:
        raw = str(load_settings().get("export_dir") or EXPORT_DEFAULT_DIR)
    except Exception:  # noqa: BLE001
        raw = EXPORT_DEFAULT_DIR
    return export_resolve(raw) or (DATA_DIR / "export" / "broadcasts")


def export_where_words() -> str:
    """The refusal, naming where the box CAN write."""
    return ("I can only write inside the station's data folder. Say a bare "
            "folder name and I will put it under data/export, or a path "
            f"under {EXPORT_HOST_ROOT} on the host, or under the share "
            f"{EXPORT_SHARE_ROOT}.")


def export_span_words(seconds: int) -> str:
    seconds = int(seconds)
    if seconds == 1800:
        return "half an hour"
    if seconds == 3600:
        return "an hour"
    if seconds % 60 == 0:
        mins = seconds // 60
        return "one minute" if mins == 1 else f"{mins} minutes"
    return f"{seconds} seconds"


def export_tail_lines(count: int) -> Path | None:
    """#1025: the last N SENTENCES of the show as one mp3 - the last N
    staged episode items (one aired line each), and when the staging is
    shorter than that (a seal just swept it) the newest sealed episode's
    marks make up the rest. The same PCM join as _cache_tail."""
    import subprocess
    import tempfile

    import imageio_ffmpeg
    count = max(1, min(40, int(count)))
    now = time.time()
    # sources are (path, -ss seconds, -t seconds or 0) in air order
    sources: list[tuple[Path, float, float]] = []
    items = [it for it in ((_RADIO.get("episode") or {}).get("items") or [])
             if Path(str(it.get("file") or "")).is_file()]
    staged = items[-count:]
    short = count - len(staged)
    if short > 0:
        try:
            shelf = sorted((RADIO_CACHE / "episodes").glob("*.mp3"),
                           key=lambda p: p.stat().st_mtime)
            if shelf:
                newest = shelf[-1]
                marks = json.loads(newest.with_suffix(".json").read_text())
                for mark in (marks if isinstance(marks, list) else [])[-short:]:
                    sources.append((newest, float(mark.get("off") or 0),
                                    float(mark.get("dur") or 0)))
        except Exception:  # noqa: BLE001
            pass
    sources += [(Path(str(it.get("file"))), 0.0, 0.0) for it in staged]
    if not sources:
        return None
    for stale in RADIO_CACHE.glob("_tail*.mp3"):
        try:
            if now - stale.stat().st_mtime > 600:
                stale.unlink()
        except OSError:
            pass
    out = RADIO_CACHE / f"_tail_lines_{int(now * 1000)}.mp3"
    exe = imageio_ffmpeg.get_ffmpeg_exe()
    gap = b"\x00" * int(24000 * 0.25) * 2
    pcm = bytearray()
    try:
        with tempfile.TemporaryDirectory(prefix="lines-") as work:
            for at, (src, off, dur) in enumerate(sources):
                cut = Path(work) / f"in{at}.wav"
                try:
                    subprocess.run(
                        [exe, "-nostdin", "-loglevel", "error", "-y",
                         "-i", str(src),
                         *(["-ss", f"{off:.2f}"] if off > 0.05 else []),
                         *(["-t", f"{dur:.2f}"] if dur > 0.05 else []),
                         "-ac", "1", "-ar", "24000", "-sample_fmt", "s16",
                         str(cut)],
                        check=True, timeout=300)
                    with wave.open(str(cut), "rb") as handle:
                        pcm += handle.readframes(handle.getnframes())
                    pcm += gap
                    cut.unlink(missing_ok=True)
                except Exception:  # noqa: BLE001
                    continue
            if len(pcm) < 24000:
                return None
            joined = Path(work) / "lines.wav"
            with wave.open(str(joined), "wb") as handle:
                handle.setnchannels(1)
                handle.setsampwidth(2)
                handle.setframerate(24000)
                handle.writeframes(bytes(pcm))
            subprocess.run(
                [exe, "-nostdin", "-hide_banner", "-loglevel", "error", "-y",
                 "-i", str(joined), "-codec:a", "libmp3lame", "-b:a", "96k",
                 str(out)],
                check=True, timeout=600)
    except Exception:  # noqa: BLE001
        return None
    return out if out.is_file() and out.stat().st_size > 1000 else None


def export_sweep() -> dict[str, int]:
    """#1025: a frequent spoken cut grows two things nothing sweeps - the
    _bmix_cut<job> scratch dirs (22 present) and _staging orphans (5,058
    files). Scratch older than half an hour goes; a staged clip goes only
    when it is NOT the episode on air and is two days old (the staging
    desk exists to review the rest). Never raises."""
    gone = {"scratch": 0, "staged": 0}
    now = time.time()
    try:
        for d in RADIO_CACHE.glob("_bmix_cut*"):
            try:
                if d.is_dir() and now - d.stat().st_mtime > 1800:
                    shutil.rmtree(d, ignore_errors=True)
                    gone["scratch"] += 1
            except OSError:
                continue
    except Exception:  # noqa: BLE001
        pass
    try:
        live = _staging_live()
        for p in _EPISODE_STAGE.iterdir():
            try:
                if (p.is_file() and str(p) not in live
                        and now - p.stat().st_mtime > 172800):
                    p.unlink()
                    gone["staged"] += 1
            except OSError:
                continue
            if gone["staged"] >= 400:
                break               # a bounded pass; the next cut takes more
    except Exception:  # noqa: BLE001
        pass
    return gone


def export_after_cut(job: str, what: str) -> str:
    """Copy a finished tray cut into the export directory with a dated
    name; record it on the job; sweep. Off the loop (to_thread)."""
    row = _CUT_JOBS.get(job) or {}
    if row.get("state") != "ready" or not row.get("name"):
        return ""
    try:
        dest_dir = export_dir_path()
        dest_dir.mkdir(parents=True, exist_ok=True)
        stamp = time.strftime("%Y-%m-%d_%H%M%S")
        dest = dest_dir / f"{stamp}-{station_slug()}-{what}.mp3"
        shutil.copy2(CUTS_DIR / str(row["name"]), dest)
        row["exported"] = str(dest)
        pipeline_log("air", f"spoken export landed: {export_host_words(dest)} "
                            "(#1025)")
        swept = export_sweep()
        if swept.get("scratch") or swept.get("staged"):
            pipeline_log("air", "the export swept "
                         f"{swept['scratch']} scratch dir(s) and "
                         f"{swept['staged']} staging orphan(s) (#1025)")
        return str(dest)
    except Exception as exc:  # noqa: BLE001
        row["error"] = f"exported to the tray only: {exc}"[:200]
        return ""


async def export_cut_run(job: str, kind: str, seconds: int,
                         label: str) -> None:
    """#1025: the tray's own cut, then the copy out. Serialised with the
    panel's cuts under _CUT_LOCK exactly as _cut_run is."""
    async with _CUT_LOCK:
        await _cut_do(job, kind, seconds, mix_levels(), label)
        await asyncio.to_thread(
            export_after_cut, job,
            f"{'broadcast' if kind == 'mix' else 'talk'}-{int(seconds)}s")


async def export_lines_run(job: str, count: int, label: str) -> None:
    """#1025: 'the last two sentences' - into the tray, then out."""
    async with _CUT_LOCK:
        _CUT_JOBS[job] = {"state": "cutting", "at": time.time(), "name": "",
                          "label": label, "error": ""}
        try:
            built = await asyncio.to_thread(export_tail_lines, int(count))
            if not built:
                _CUT_JOBS[job].update(
                    {"state": "empty",
                     "error": "Nothing has aired to take a sentence from"})
                return
            CUTS_DIR.mkdir(parents=True, exist_ok=True)
            name = (f"{station_slug()}-lines-{int(count)}"
                    f"-{time.strftime('%H%M%S')}-{job}.mp3")
            target = CUTS_DIR / name
            try:
                built.replace(target)
            except OSError:
                target.write_bytes(built.read_bytes())
            _cuts_trim()
            _CUT_JOBS[job].update({"state": "ready", "name": name})
        except Exception as exc:  # noqa: BLE001
            _CUT_JOBS[job].update({"state": "failed",
                                   "error": str(exc)[:200]})
            return
        await asyncio.to_thread(export_after_cut, job,
                                f"lines-{int(count)}")


async def export_command_run(cmd: dict[str, Any],
                             settings: dict[str, Any]) -> str:
    """#1025: act on parse_export_command's verdict and return what the
    box SAYS. The cut runs behind the reply (#1153 pattern)."""
    if cmd.get("dir"):
        raw = str(cmd["dir"])
        dest = export_resolve(raw)
        if dest is None:
            return (f"I can't write to {raw}. " + export_where_words()
                    + " Exports stay at "
                    + export_host_words(export_dir_path()) + " for now.")
        try:
            rel = dest.relative_to(DATA_DIR)
            stored = "data/" + str(rel).replace("\\", "/")
        except Exception:  # noqa: BLE001
            stored = str(dest)
        try:
            await asyncio.to_thread(save_settings, {**settings,
                                                    "export_dir": stored})
        except Exception as exc:  # noqa: BLE001
            return f"The setting would not save: {exc}"
        try:
            await asyncio.to_thread(dest.mkdir, parents=True, exist_ok=True)
        except Exception:  # noqa: BLE001
            pass
        pipeline_log("air", f"spoken: broadcast exports now go to {stored} "
                            "(#1025)")
        return (f"Broadcast exports now go to {export_host_words(dest)}. "
                "Every cut I save out lands there with the date in its "
                "name, and a copy stays in the cut tray.")
    job = uuid.uuid4().hex[:8]
    for old, row in list(_CUT_JOBS.items()):          # bounded
        if time.time() - float(row.get("at") or 0) > 3600:
            _CUT_JOBS.pop(old, None)
    where = export_host_words(export_dir_path())
    if cmd.get("sentences"):
        n = int(cmd["sentences"])
        label = f"the last {n} sentence{'s' if n != 1 else ''} - spoken order"
        _CUT_JOBS[job] = {"state": "queued", "at": time.time(), "name": "",
                          "label": label, "error": "", "export": True}
        asyncio.create_task(export_lines_run(job, n, label))
        pipeline_log("air", f"spoken export queued: {label} (#1025)")
        return (f"Saving the last {n} sentence{'s' if n != 1 else ''} of "
                f"the show now. It lands in the cut tray and a copy goes "
                f"to {where} - give it a moment.")
    seconds = int(cmd.get("seconds") or 0)
    kind = "mix" if cmd.get("kind") == "mix" else "talk"
    span = export_span_words(seconds)
    label = (f"the last {span} - "
             + ("the whole broadcast" if kind == "mix" else "just the talk")
             + " - spoken order")
    _CUT_JOBS[job] = {"state": "queued", "at": time.time(), "name": "",
                      "label": label, "error": "", "export": True}
    asyncio.create_task(export_cut_run(job, kind, seconds, label))
    pipeline_log("air", f"spoken export queued: {label} (#1025)")
    return (f"Cutting the last {span} of "
            + ("the whole broadcast, records and all" if kind == "mix"
               else "the talk")
            + f" now. It lands in the cut tray and a copy goes to {where}"
            + (" - a full mix takes a few minutes." if kind == "mix"
               else " - give it a minute."))


@app.post("/api/radio-cache/cut")
async def radio_cache_cut_api(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Queue a cut and come straight back (#727).

    The cut itself runs behind you, so you can line several up and take them
    together instead of standing over each one."""
    require_auth(authorization)
    payload = await request.json()
    kind = "mix" if str(payload.get("kind") or "mix") == "mix" else "talk"
    seconds = max(10, min(3600, int(payload.get("seconds") or 30)))

    def lvl(key: str, dflt: float) -> float:
        try:
            return float(payload.get(key, dflt))
        except (TypeError, ValueError):
            return dflt

    levels = {"music": lvl("music", 100), "duck": lvl("duck", 70),
              "voice": lvl("voice", 160)}
    job = uuid.uuid4().hex[:8]
    label = (f"the last {seconds}s — "
             + ("the whole broadcast" if kind == "mix" else "just the talk"))
    _CUT_JOBS[job] = {"state": "queued", "at": time.time(), "name": "",
                      "label": label, "error": ""}
    for old, row in list(_CUT_JOBS.items()):          # bounded
        if time.time() - float(row.get("at") or 0) > 3600:
            _CUT_JOBS.pop(old, None)
    asyncio.create_task(_cut_run(job, kind, seconds, levels, label))
    return {"job": job, "state": "queued", "label": label}


@app.get("/api/radio-cache/cuts")
async def radio_cache_cuts_api(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """The tray: the cuts that are ready, and the ones still running."""
    require_read_auth(authorization)
    return {
        "cuts": await asyncio.to_thread(_cut_list),
        "jobs": [{"job": j, **{k: v for k, v in row.items() if k != "at"}}
                 for j, row in sorted(_CUT_JOBS.items(),
                                      key=lambda kv: -float(kv[1].get("at") or 0))
                 if row.get("state") in ("queued", "cutting", "failed",
                                         "empty")][:8],
        "folder": str(CUTS_DIR),
    }


@app.get("/api/radio-cache/cuts/{name}")
async def radio_cache_cut_file(
    name: str,
    request: Request,
    authorization: str | None = Header(default=None),
) -> Response:
    """Serve one cut. Signed ?t= like every other cache file, so the link
    can be pasted into a message and opened anywhere on the network."""
    _sig = str(request.query_params.get("t") or "")
    _want = media_sign(name)
    if not (_want and hmac.compare_digest(_sig, _want)):
        require_read_auth(authorization)
    if "/" in name or ".." in name or not re.fullmatch(
            r"[\w.\- ]{1,120}", name):
        raise HTTPException(status_code=400, detail="Bad name")
    path = CUTS_DIR / name
    if not path.is_file():
        raise HTTPException(status_code=404, detail="Not in the tray")
    return FileResponse(path, media_type="audio/mpeg",
                        headers={"Cache-Control": "private, max-age=3600"})


@app.delete("/api/radio-cache/cuts/{name}")
async def radio_cache_cut_delete(
    name: str,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    require_auth(authorization)
    if "/" in name or ".." in name or not re.fullmatch(
            r"[\w.\- ]{1,120}", name):
        raise HTTPException(status_code=400, detail="Bad name")
    (CUTS_DIR / name).unlink(missing_ok=True)
    return {"deleted": name, "cuts": len(await asyncio.to_thread(_cut_list))}


# --- the staging desk -------------------------------------------------------
# The staging folder had no door: nothing listed it, nothing swept it, and the
# only code that deletes from it walks an in-memory list that does not survive
# a restart. Review it, take it away, empty it.

STAGE_CLEAR_FLOOR = 90.0        # seconds; do not touch anything younger


def _staging_live() -> set[str]:
    """Absolute paths belonging to the episode currently on air. These are
    written as str(dst) from the same _EPISODE_STAGE constant, so plain
    string equality is exact - resolve() would be wrong here, not safer,
    because a bind mount can resolve differently."""
    return {str(it.get("file") or "")
            for it in ((_RADIO.get("episode") or {}).get("items") or [])
            if it.get("file")}


def _staging_rows() -> dict[str, Any]:
    """What is in the staging folder, and what clearing it would really
    free."""
    live = _staging_live()
    rows: list[dict[str, Any]] = []
    total = free = 0
    now = time.time()
    # #1136: ONE walk of the sample folders, not one per sting row.
    # sfx_by_id() walks every sample folder - 3,400+ files on a CIFS
    # mount - per call, and the loop below called it once per staged
    # sting. Measured live: three straight 15-second timeouts on this
    # desk while every sibling endpoint answered, which is the one
    # control an operator experiences as simply broken.
    _sfx_names: dict[str, str] = {}
    try:
        _made = (list(SFX_MADE_DIR.glob("*.wav"))
                 if SFX_MADE_DIR.is_dir() else [])
        for _p in sfx_all() + _made:
            _sfx_names.setdefault(sfx_id(_p), _p.stem)
    except Exception:  # noqa: BLE001
        pass
    try:
        entries = sorted(_EPISODE_STAGE.iterdir())
    except OSError:
        entries = []
    for path in entries:
        try:
            if not path.is_file():
                continue
            info = path.stat()
        except OSError:
            continue
        # <5-digit air index>_<key>. A sting is 16 hex with no extension and
        # its sample name is recoverable; a voice clip is a 32-hex uuid the
        # server minted, whose words lived only in memory.
        stem = path.name.split("_", 1)[-1]
        sting = "." not in stem
        label = ""
        if sting:
            _found = _sfx_names.get(stem)          # #1136: map, not a walk
            label = f"[sfx] {_found}" if _found else "[sfx]"
        # A hardlink shares its bytes with /media: deleting it frees nothing
        # until the original goes too. st_nlink == 1 means this IS the last
        # copy, and those bytes are the honest saving.
        alone = getattr(info, "st_nlink", 1) <= 1
        total += info.st_size
        if alone:
            free += info.st_size
        rows.append({
            "name": path.name,
            "bytes": info.st_size,
            "when": int(getattr(info, "st_ctime", info.st_mtime)),
            "kind": "sting" if sting else "voice",
            "label": label,
            "live": str(path) in live,
            "only_copy": alone,
            "sig": media_sign(path.name),
        })
    rows.sort(key=lambda r: r["name"])
    ep = _RADIO.get("episode") or {}
    return {
        "rows": rows[-400:],                 # the desk shows the tail
        "count": len(rows),
        "shown": min(len(rows), 400),
        "bytes": total,
        "frees": free,
        "live": sum(1 for r in rows if r["live"]),
        "folder": str(_EPISODE_STAGE),
        "now": int(now),
        "recording": {
            "clips": len(ep.get("items") or []),
            "since": int(float(ep.get("started") or now)),
        },
    }


@app.get("/api/radio-cache/staging")
async def radio_cache_staging_api(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Review the staging folder (#774 follow-up)."""
    require_read_auth(authorization)
    return await asyncio.to_thread(_staging_rows)


@app.get("/api/radio-cache/staging/{name}")
async def radio_cache_staging_file(
    name: str,
    request: Request,
    authorization: str | None = Header(default=None),
) -> FileResponse:
    """One staged clip, so it can be listened to before it is thrown away."""
    sig = str(request.query_params.get("t") or "")
    want = media_sign(name)
    if not (want and hmac.compare_digest(sig, want)):
        require_read_auth(authorization)
    if "/" in name or ".." in name or not re.fullmatch(
            r"[\w.\- ]{1,140}", name):
        raise HTTPException(status_code=400, detail="Bad name")
    path = _EPISODE_STAGE / name
    if not path.is_file():
        raise HTTPException(status_code=404, detail="Not in staging")
    kind = "audio/mpeg" if name.endswith(".mp3") else "audio/wav"
    return FileResponse(path, media_type=kind,
                        headers={"Cache-Control": "private, max-age=600"})


def _staging_zip(scope: str, max_mb: float) -> dict[str, Any]:
    """Batch the staging folder into one zip, newest first, under a budget.

    ZIP_STORED like the cache export: the payload is already-compressed
    audio and the box has ffmpeg to run. Written to .part and renamed, so a
    half-built archive is never served."""
    import zipfile
    live = _staging_live()
    picks: list[Path] = []
    took = 0
    budget = max(1.0, float(max_mb)) * 1024 * 1024
    try:
        entries = sorted(_EPISODE_STAGE.iterdir(), reverse=True)
    except OSError:
        entries = []
    for path in entries:
        try:
            if not path.is_file():
                continue
            if scope == "orphans" and str(path) in live:
                continue
            size = path.stat().st_size
        except OSError:
            continue
        if took + size > budget and picks:
            break
        picks.append(path)
        took += size
    if not picks:
        return {"files": 0, "bytes": 0, "url": "", "left": 0}
    out = RADIO_CACHE / "_staging_batch.zip"
    tmp = out.with_suffix(".part")
    try:
        with zipfile.ZipFile(tmp, "w", zipfile.ZIP_STORED) as zf:
            for path in picks:
                try:
                    zf.write(path, path.name)
                except OSError:
                    continue
            zf.writestr(
                "MANIFEST.txt",
                f"Pine Box FM - staging batch\n"
                f"taken {time.strftime('%Y-%m-%d %H:%M:%S')}\n"
                f"scope {scope}\n{len(picks)} clips\n")
        tmp.replace(out)
    except Exception as exc:               # noqa: BLE001
        tmp.unlink(missing_ok=True)
        raise HTTPException(status_code=500,
                            detail=f"Could not build it: {exc}"[:200]) from exc
    return {"files": len(picks), "bytes": out.stat().st_size,
            "url": f"/export/staging.zip?t={media_sign('staging.zip')}",
            "left": max(0, len([e for e in entries if e.is_file()])
                        - len(picks))}


@app.post("/api/radio-cache/staging/export")
async def radio_cache_staging_export(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Build the batch and hand back a signed link (the kit pattern) rather
    than a blob - this folder runs to gigabytes and a tab cannot hold it."""
    require_auth(authorization)
    try:
        payload = await request.json()
    except Exception:
        payload = {}
    scope = "all" if str(payload.get("scope") or "") == "all" else "orphans"
    max_mb = max(1.0, min(4096.0, float(payload.get("max_mb") or 750)))
    got = await asyncio.to_thread(_staging_zip, scope, max_mb)
    if not got["files"]:
        raise HTTPException(status_code=404, detail="Nothing to take away")
    pipeline_log("air", f"staging batched - {got['files']} clips, "
                        f"{got['bytes'] // 1048576} MB")
    return got


@app.get("/export/staging.zip")
async def radio_cache_staging_zip(request: Request) -> FileResponse:
    sig = str(request.query_params.get("t") or "")
    if not hmac.compare_digest(sig, media_sign("staging.zip")):
        raise HTTPException(status_code=403, detail="Bad signature")
    path = RADIO_CACHE / "_staging_batch.zip"
    if not path.is_file():
        raise HTTPException(status_code=404, detail="Build it first")
    return FileResponse(
        path, media_type="application/zip",
        filename=f"pinebox-staging-{time.strftime('%Y%m%d-%H%M%S')}.zip",
        headers={"Cache-Control": "no-store"})


@app.post("/api/radio-cache/staging/clear")
async def radio_cache_staging_clear(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Empty the staging folder - never the episode that is on air.

    Two guards, both necessary. The live set is what the open episode is
    holding; deleting one of those would tear the audio out from under the
    next seal. The age floor closes the window in which _episode_finalize
    has already published its empty item list but is still running ffmpeg
    over the files it is about to unlink itself."""
    require_auth(authorization)
    try:
        payload = await request.json()
    except Exception:
        payload = {}
    if not payload.get("confirm"):
        raise HTTPException(
            status_code=400,
            detail="This deletes staged audio. Pass confirm=true to do it.")
    keep_live = str(payload.get("scope") or "") != "all"

    def _sweep() -> dict[str, Any]:
        live = _staging_live()
        now = time.time()
        gone = freed = held = 0
        try:
            entries = list(_EPISODE_STAGE.iterdir())
        except OSError:
            entries = []
        for path in entries:
            try:
                if not path.is_file():
                    continue
                info = path.stat()
                if keep_live and str(path) in live:
                    held += 1
                    continue
                if now - float(getattr(info, "st_ctime",
                                       info.st_mtime)) < STAGE_CLEAR_FLOOR:
                    held += 1
                    continue
                alone = getattr(info, "st_nlink", 1) <= 1
                size = info.st_size
                path.unlink()
                gone += 1
                if alone:
                    freed += size
            except OSError:
                continue
        return {"deleted": gone, "freed": freed, "held": held}

    got = await asyncio.to_thread(_sweep)
    pipeline_log("air", f"staging cleared - {got['deleted']} clips gone, "
                        f"{got['freed'] // 1048576} MB freed, "
                        f"{got['held']} left alone")
    note_action(f"cleared {got['deleted']} clips out of staging")
    return {**got, **(await asyncio.to_thread(_staging_rows))}


def _cache_meta_read(kind: str, name: str) -> dict[str, Any] | None:
    """Everything the calendar tooltip wants to know about one recording:
    location, length, size, who was present, how many phone calls, and any
    ads/product placement — best-effort, parsed from the mp3 header and the
    transcript beside it."""
    folder = _cache_folder(kind)
    path = folder / name
    if not path.is_file():
        return None
    size = path.stat().st_size
    secs = 0.0
    try:
        from mutagen.mp3 import MP3
        secs = float(MP3(str(path)).info.length or 0)
    except Exception:
        pass
    members: list[str] = []
    calls = ads = 0
    md = path.with_suffix(".md")
    text = ""
    if md.is_file():
        try:
            text = md.read_text(encoding="utf-8", errors="replace")
        except OSError:
            text = ""
    if kind == "calls":
        calls = 1
        members = list(dict.fromkeys(
            m.group(1).strip() for m in
            re.finditer(r"\*\*([^*:]{1,40}):?\*\*", text)))[:8]
    else:
        dj = dj_settings()
        members = [n for n in (dj.get("host_name"), dj.get("cohost_name"),
                               dj.get("third_name")) if n]
        for m in re.finditer(r"☎\s*([^—\n]{1,40})", text):
            calls += 1
            nm = m.group(1).strip()
            if nm and nm not in members:
                members.append(nm)
        ads = len(re.findall(
            r"📣|\b(?:advert|sponsor|commercial|ad break|product)\b",
            text, flags=re.I))
    return {"kind": kind, "name": name, "folder": str(folder),
            "size": size, "seconds": round(secs, 1),
            "members": members[:10], "calls": calls, "ads": ads}


@app.get("/api/radio-cache/meta")
async def radio_cache_meta_api(
    kind: str = "episodes",
    name: str = "",
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """The calendar hover-card: one recording's location, length, size,
    members present, phone-call count and ad mentions."""
    require_read_auth(authorization)
    if kind not in ("episodes", "calls", "broadcasts") \
            or "/" in name or ".." in name \
            or not re.fullmatch(r"[\w.\- ]{1,120}", name):
        raise HTTPException(status_code=400, detail="bad kind or name")
    meta = await asyncio.to_thread(_cache_meta_read, kind, name)
    if not meta:
        raise HTTPException(status_code=404, detail="Not in the cache")
    return meta


@app.get("/api/radio-cache/spec/{kind}/{name}")
async def radio_cache_spec(
    kind: str,
    name: str,
    request: Request,
    authorization: str | None = Header(default=None),
) -> Response:
    """A little waveform-of-levels strip for the hover-card, rendered once
    per recording and cached. Signed like the mp3 itself (same ?t=)."""
    _sig = str(request.query_params.get("t") or "")
    _want = media_sign(name)
    if not (_want and hmac.compare_digest(_sig, _want)):
        require_read_auth(authorization)
    if kind not in ("episodes", "calls", "broadcasts") \
            or "/" in name or ".." in name \
            or not re.fullmatch(r"[\w.\- ]{1,120}", name):
        raise HTTPException(status_code=400, detail="bad kind or name")
    src = RADIO_CACHE / kind / name
    if not src.is_file():
        raise HTTPException(status_code=404, detail="Not in the cache")
    spec_dir = RADIO_CACHE / "_spec"
    out = spec_dir / f"{kind}_{name}.png"

    def render() -> bool:
        if out.is_file():
            return True
        try:
            import subprocess

            import imageio_ffmpeg
            spec_dir.mkdir(parents=True, exist_ok=True)
            exe = imageio_ffmpeg.get_ffmpeg_exe()
            subprocess.run(
                [exe, "-nostdin", "-hide_banner", "-loglevel", "error", "-y",
                 "-i", str(src),
                 "-lavfi", "showwavespic=s=360x56:colors=0x7fd1ff",
                 "-frames:v", "1", str(out)],
                capture_output=True, timeout=120)
            # Bounded: keep the newest ~300 strips.
            keep = sorted(spec_dir.glob("*.png"),
                          key=lambda p: p.stat().st_mtime)
            for old in keep[:-300]:
                old.unlink(missing_ok=True)
            return out.is_file()
        except Exception:
            return False

    if not await asyncio.to_thread(render):
        raise HTTPException(status_code=500, detail="Could not render levels")
    return FileResponse(out, media_type="image/png",
                        headers={"Cache-Control": "private, max-age=86400"})


@app.get("/api/radio-cache/compile")
async def radio_cache_compile_api(
    kind: str = "episodes",
    scope: str = "today",
    day: str = "",
    span: str = "",
    authorization: str | None = Header(default=None),
) -> Response:
    """Download a whole span of the broadcast as one mp3 (#600): kind
    episodes|calls|all, scope today|yesterday|week|month|all — or an explicit
    `day=YYYY-MM-DD` + `span=day|week|month` window, so the calendar can pull
    any day/week/month in history as one unified file."""
    require_read_auth(authorization)
    if kind not in ("episodes", "calls", "broadcasts", "all"):
        raise HTTPException(status_code=400,
                            detail="kind must be episodes|calls|all")
    if scope not in ("today", "yesterday", "week", "month", "all"):
        raise HTTPException(status_code=400, detail="bad scope")
    lo = hi = None
    if day:
        try:
            base = time.mktime(time.strptime(day, "%Y-%m-%d"))
        except ValueError:
            raise HTTPException(status_code=400, detail="day is YYYY-MM-DD")
        want = span if span in ("day", "week", "month") else "day"
        if want == "day":
            lo, hi = base, base + 86400
        elif want == "week":
            wd = time.localtime(base).tm_wday          # Monday = 0
            lo = base - wd * 86400
            hi = lo + 7 * 86400
        else:
            lt0 = time.localtime(base)
            lo = time.mktime(time.strptime(
                f"{lt0.tm_year}-{lt0.tm_mon:02d}-01", "%Y-%m-%d"))
            ny, nm = ((lt0.tm_year + 1, 1) if lt0.tm_mon == 12
                      else (lt0.tm_year, lt0.tm_mon + 1))
            hi = time.mktime(time.strptime(f"{ny}-{nm:02d}-01", "%Y-%m-%d"))
        scope = "range"
    # Capture up to THIS moment (#624): seal the running episode first so the
    # compilation includes everything aired so far, not just the last sealed
    # 15-minute block. (Calls only affect the episode shelf, not the calls one.)
    if kind in ("episodes", "all") and (
            scope in ("today", "all")
            or (lo is not None and lo <= time.time() < (hi or 0))):
        try:
            await asyncio.to_thread(_episode_finalize)
        except Exception:
            pass
    path = await asyncio.to_thread(_cache_compile, kind, scope, lo, hi)
    if not path:
        raise HTTPException(status_code=404,
                            detail="Nothing recorded in that range yet")
    stamp = day or time.strftime("%Y-%m-%d")
    fname = f"{station_slug()}-{kind}-{span or scope}-{stamp}.mp3"
    return FileResponse(path, media_type="audio/mpeg", filename=fname,
                        headers={"Cache-Control": "no-store"})


def _mix_window(scope: str, day: str = "", span: str = "") -> tuple[float,
                                                                   float]:
    """The wall-clock window a scope means, same reckoning the compile uses."""
    now = time.time()
    lt = time.localtime(now)
    midnight = now - (lt.tm_hour * 3600 + lt.tm_min * 60 + lt.tm_sec)
    if day:
        try:
            base = time.mktime(time.strptime(day, "%Y-%m-%d"))
        except ValueError:
            base = midnight
        want = span if span in ("day", "week", "month") else "day"
        if want == "day":
            return base, base + 86400
        if want == "week":
            wd = time.localtime(base).tm_wday
            return base - wd * 86400, base - wd * 86400 + 7 * 86400
        return base, base + 31 * 86400
    if scope == "yesterday":
        return midnight - 86400, midnight
    if scope == "week":
        return midnight - 6 * 86400, now + 1.0
    if scope == "month":
        return midnight - 29 * 86400, now + 1.0
    if scope == "all":
        return now - 8 * 3600, now + 1.0     # capped; see _broadcast_mix
    return midnight, now + 1.0


def _broadcast_mix(lo: float, hi: float, music: float, duck: float,
                   voice: float, tag: str = "") -> Path | None:
    """The show as it SOUNDED, rebuilt (#633).

    The recorder only ever caught talk and stings — a record is a URL the
    page or the box streams, so nothing in this process has heard a note of
    the music. So the mix is reconstructed from two logs: where each aired
    line sits inside its sealed episode, and which record was playing when.
    Talk is laid on a silent bed at its real offsets, the records are cut to
    the moments they actually ran, and the music is ducked under the voices
    by the same sidechain the ad mixer has used all along.

    ponytail: the span cap is CPU, not policy — every second of it is
    decoded and re-encoded.
    """
    import shutil as _shutil
    import subprocess

    import imageio_ffmpeg
    exe = imageio_ffmpeg.get_ffmpeg_exe()
    # #667: the collector renders on its own clock while somebody may be
    # pressing "render & download" — so the scratch space and the output are
    # per-caller, not one shared pair of paths both would write at once.
    work = RADIO_CACHE / f"_bmix{tag}"
    _shutil.rmtree(work, ignore_errors=True)
    work.mkdir(parents=True, exist_ok=True)
    span = max(1.0, hi - lo)

    def run(args: list[str], timeout: int = 900) -> bool:
        try:
            done = subprocess.run(args, capture_output=True, timeout=timeout)
            return done.returncode == 0
        except Exception:
            return False

    # A donor of silence, in exactly the episodes' shape, so the whole
    # timeline can be built with the concat demuxer and stream copy.
    silence = work / "silence.mp3"
    if not run([exe, "-nostdin", "-hide_banner", "-loglevel", "error", "-y",
                "-f", "lavfi", "-i", "anullsrc=r=24000:cl=mono", "-t", "60",
                "-codec:a", "libmp3lame", "-b:a", "96k", str(silence)], 120):
        return None

    def timeline(pieces: list[tuple[float, float, str, float]],
                 out: Path) -> Path | None:
        """pieces = (start, end, source, seek-into-source), in air order."""
        if not pieces:
            return None
        listing = out.with_suffix(".txt")
        rows: list[str] = []
        at = lo
        for begin, end, src, seek in pieces:
            gap = begin - at
            while gap > 0.05:
                take = min(gap, 60.0)
                rows.append(f"file '{silence}'\noutpoint {take:.3f}")
                gap -= take
            rows.append(f"file '{src}'\ninpoint {max(0.0, seek):.3f}\n"
                        f"outpoint {max(0.0, seek) + (end - begin):.3f}")
            at = end
        tail = hi - at
        while tail > 0.05:
            take = min(tail, 60.0)
            rows.append(f"file '{silence}'\noutpoint {take:.3f}")
            tail -= take
        listing.write_text("\n".join(rows) + "\n")
        base = [exe, "-nostdin", "-hide_banner", "-loglevel", "error", "-y",
                "-f", "concat", "-safe", "0", "-i", str(listing)]
        if not run(base + ["-c", "copy", str(out)]):
            if not run(base + ["-c:a", "libmp3lame", "-b:a", "96k",
                               "-ar", "24000", "-ac", "1", str(out)], 1800):
                return None
        return out if out.is_file() and out.stat().st_size > 1000 else None

    # --- the talk, from the episode sidecars -----------------------------
    # #774: anything still staged has no sidecar and is therefore invisible
    # here. Callers are expected to seal first; if one has not, say so rather
    # than handing back a broadcast with nobody talking on it.
    _open = len((_RADIO.get("episode") or {}).get("items") or [])
    if _open:
        pipeline_log("air", f"broadcast mix: {_open} aired clip(s) are still "
                            "in the open episode and will not be in this cut "
                            "— seal it first (#774)")
    said: list[tuple[float, float, str, float]] = []
    for mark_file in sorted((RADIO_CACHE / "episodes").glob("*.json")):
        source = mark_file.with_suffix(".mp3")
        if not source.is_file():
            continue
        try:
            marks = json.loads(mark_file.read_text())
        except Exception:
            continue
        for mark in marks:
            aired = float(mark.get("t") or 0)
            dur = float(mark.get("dur") or 0)
            if not aired or dur <= 0.05 or aired + dur <= lo or aired >= hi:
                continue
            begin, end = max(lo, aired), min(hi, aired + dur)
            if end - begin <= 0.05:
                continue
            said.append((begin, end, str(source),
                         float(mark.get("off") or 0) + (begin - aired)))
    said.sort(key=lambda row: row[0])
    tidy: list[tuple[float, float, str, float]] = []
    for row in said:
        if tidy and row[0] < tidy[-1][1]:
            shift = tidy[-1][1] - row[0]      # a sting riding over a line
            if row[1] - row[0] - shift <= 0.05:
                continue
            row = (tidy[-1][1], row[1], row[2], row[3] + shift)
        tidy.append(row)
    talk = timeline(tidy, work / "voice.mp3")

    # --- the records, from the play log ----------------------------------
    beds: list[tuple[float, float, str, float]] = []
    for at, row in enumerate(_music_log_rows(lo, hi)):
        source = row.get("path") or ""
        if not source:
            found = music_track(str(row.get("id") or "")) or {}
            source = str(found.get("path") or "")
        if not source or not Path(source).is_file():
            continue
        begin, end = max(lo, row["began"]), min(hi, row["ends"])
        if end - begin <= 0.2:
            continue
        piece = work / f"bed{at:04d}.mp3"
        if run([exe, "-nostdin", "-hide_banner", "-loglevel", "error", "-y",
                "-ss", f"{begin - row['began']:.2f}",
                "-t", f"{end - begin:.2f}", "-i", source,
                # #701: no gain here — the level is set in the final graph,
                # against the dialogue. Applying it twice was part of why the
                # music sat so far over the top.
                "-ar", "24000", "-ac", "1",
                "-codec:a", "libmp3lame", "-b:a", "96k", str(piece)], 600):
            beds.append((begin, end, str(piece), 0.0))
    bed = timeline(beds, work / "music.mp3")

    out = RADIO_CACHE / f"_broadcast{tag}.mp3"
    out.unlink(missing_ok=True)
    if talk and not bed:
        talk.replace(out)             # nothing played; the talk IS the mix
        return out if out.is_file() else None
    if bed and not talk:
        bed.replace(out)              # music only; nobody said anything
        return out if out.is_file() else None
    if not talk or not bed:
        return None
    # The records under the voices (#701). Both halves are loudnorm'd to the
    # SAME reference first, so `music` is a share OF THE DIALOGUE rather than
    # a raw gain on whatever the records happened to be mastered at — which
    # is why the music came out over the top of the talk. The sidechain then
    # ducks it further under the words, as before.
    ratio = max(1.5, 1.0 + duck * 16)
    vox_n = f"[0:a]loudnorm=I=-16:LRA=11:TP=-1.5,volume={voice:.3f}"
    bed_n = f"[1:a]loudnorm=I=-16:LRA=11:TP=-2.0,volume={music:.3f}[bed];"
    graph = (
        bed_n + vox_n + ",asplit=2[voxduck][voxmix];"
        f"[bed][voxduck]sidechaincompress=threshold=0.03:ratio={ratio:.1f}:"
        "attack=15:release=350[duck];"
        "[duck][voxmix]amix=inputs=2:duration=longest:normalize=0,"
        "alimiter=limit=0.95[out]"
    ) if duck > 0.02 else (
        bed_n + vox_n + "[vox];"
        "[bed][vox]amix=inputs=2:duration=longest:normalize=0,"
        "alimiter=limit=0.95[out]"
    )
    if not run([exe, "-nostdin", "-hide_banner", "-loglevel", "error", "-y",
                "-i", str(talk), "-i", str(bed), "-filter_complex", graph,
                "-map", "[out]", "-ac", "1", "-ar", "24000",
                "-codec:a", "libmp3lame", "-b:a", "96k", str(out)], 1800):
        return None
    return out if out.is_file() and out.stat().st_size > 1000 else None


@app.get("/api/radio-cache/broadcast")
async def radio_cache_broadcast_api(
    scope: str = "today",
    day: str = "",
    span: str = "",
    tail: float = 0.0,
    music: float = 100.0,
    duck: float = 70.0,
    voice: float = 100.0,
    authorization: str | None = Header(default=None),
) -> Response:
    """The full mix (#633): the talk and the stings with the records they
    played over, at the levels set in the browser.

    #679: `tail` (seconds) asks for the last stretch instead of a named
    scope — that is what the ⬇ in the booth wants. It used to hand back the
    talk alone, which is not the broadcast: the records and the ad reads
    ARE the show, and a rebroadcast without them is a pile of voice clips.
    """
    require_read_auth(authorization)
    if tail > 0:
        hi = time.time() + 1.0
        lo = hi - max(15.0, min(8 * 3600.0, tail))
    else:
        if scope not in ("today", "yesterday", "week", "month", "all"):
            raise HTTPException(status_code=400, detail="bad scope")
        lo, hi = _mix_window(scope, day, span)
    hi = min(hi, time.time() + 1.0)
    if hi - lo > 8 * 3600:
        lo = hi - 8 * 3600           # every second is decoded; cap the work
    # Reach up to this moment, the way the compile does.
    if lo <= time.time() < hi:
        try:
            await asyncio.to_thread(_episode_finalize)
        except Exception:
            pass
    path = await asyncio.to_thread(
        _broadcast_mix, lo, hi,
        max(0.0, min(2.0, music / 100)),
        max(0.0, min(0.9, duck / 100)),
        max(0.25, min(2.0, voice / 100)))
    if not path:
        raise HTTPException(
            status_code=404,
            detail="Nothing to mix in that span. The full mix needs the "
                   "timing logs, which only start from this update — older "
                   "stretches can still be pulled as talk.")
    # #679: a tail cut is not "today" — these get collected, so the name has
    # to say which stretch it is, down to the minute, or a folder of them is
    # unsortable.
    if tail > 0:
        stamp = time.strftime("%Y-%m-%d-%H%M")
        window = f"last-{int(round(hi - lo))}s"
    else:
        stamp = time.strftime("%Y-%m-%d")
        window = span or scope
    return FileResponse(
        path, media_type="audio/mpeg",
        filename=f"{station_slug()}-broadcast-{window}-{stamp}.mp3",
        headers={"Cache-Control": "no-store"})


@app.get("/api/remote")
async def remote_api(
    fresh: int = 0,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Where the station is reachable from (#632). Operator only — a guest
    has no business seeing the topology.

    #659: `fresh=1` skips the cache, so the panel watching someone work
    through the setup sees a stage flip the moment it actually flips."""
    require_auth(authorization)
    return await asyncio.to_thread(remote_access, bool(fresh))


@app.get("/api/share")
async def share_list(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Live tune-in links, with what is left on each, and every address each
    one can be handed out on (#687)."""
    require_auth(authorization)
    rows = read_shares()
    net = await asyncio.to_thread(remote_access)
    now = time.time()
    out = []
    for tag, row in (rows.get("links") or {}).items():
        left = float(row.get("expires") or 0) - now
        if left <= 0:
            continue
        url = row.get("url") or ""
        # The token is not tied to a host — only the prefix differs — so the
        # same pass can be handed out on whichever address the person you
        # are sending it to can actually reach. A link minted on the tailnet
        # is useless to somebody on your wifi, and vice versa; this stops
        # that being a dead end (#687).
        token = url.rsplit("/tune/", 1)[-1] if "/tune/" in url else ""
        out.append({"tag": tag, "label": row.get("label") or "",
                    "expires": int(row.get("expires") or 0),
                    "hours_left": round(left / 3600, 1),
                    # Links minted before scopes existed are listener links.
                    "scope": row.get("scope") or "listen",
                    "url": url,
                    "alts": ([{"label": u["label"], "kind": u["kind"],
                               "url": f"{u['url']}/tune/{token}"}
                              for u in (net.get("urls") or [])]
                             if token else [])})
    return {"links": sorted(out, key=lambda r: -r["expires"])}


@app.post("/api/share")
async def share_make(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Mint a link somebody else can open (#632). It carries a signed,
    expiring token — never the API key.

    Two scopes. "listen" opens the handful of routes a guest needs.
    "full" opens the whole station: the same control panel you are looking
    at, and every route behind it, for when the person on the other end is
    you on another machine. Full links are never the default — they have to
    be asked for."""
    require_auth(authorization)
    if not SPARK_AGENT_API_KEY:
        raise HTTPException(
            status_code=500,
            detail="No API key configured, so nothing can be signed.")
    payload = await request.json()
    hours = max(1.0, min(24 * 90, float(payload.get("hours") or 168)))
    label = str(payload.get("label") or "a listener")[:60]
    scope = str(payload.get("scope") or "listen").lower()
    if scope not in SHARE_SCOPES:
        scope = "listen"
    tag = uuid.uuid4().hex[:8]
    expires = int(time.time() + hours * 3600)
    token = listen_token(expires, tag, scope)
    net = await asyncio.to_thread(remote_access)
    # Which address to build the link on.
    #
    # This used to always prefer the tailnet, which is wrong whenever the
    # tailnet has nobody else on it: a 100.x address is reachable only by
    # machines signed into that tailnet, so the moment the daemon came up
    # every new link started pointing somewhere NOBODY could reach — worse
    # than the LAN address it replaced.
    #
    # The reliable default is the address you are looking at this panel
    # through right now. It is the one host we have proof works from a real
    # device, because your request arrived on it. `base` overrides it when
    # you know better than we do.
    want = str(payload.get("base") or "").strip().lower()
    chosen = ""
    if want:
        chosen = next((u["url"] for u in net["urls"]
                       if u["kind"] == want or u["label"].lower() == want), "")
    # #687: when the public door is up, that is the address to hand out —
    # it is the only one that works for somebody with no Tailscale, no
    # account and no invitation, which is the whole point of a share link.
    # A listener token is all it opens, so this is safe to default to.
    if not chosen:
        chosen = next((u["url"] for u in net["urls"]
                       if u["kind"] == "funnel"), "")
    if not chosen:
        host_hdr = (request.headers.get("host") or "").strip()
        if host_hdr:
            scheme = request.headers.get("x-forwarded-proto") or "http"
            chosen = f"{scheme}://{host_hdr}"
    if not chosen:
        chosen = next((u["url"] for u in net["urls"]), "")
    base = chosen
    url = f"{base}/tune/{token}"
    rows = read_shares()
    rows.setdefault("epoch", 1)
    rows.setdefault("links", {})[tag] = {
        "label": label, "expires": expires, "url": url, "scope": scope,
        "made": int(time.time())}
    write_shares(rows)
    return {"token": token, "url": url, "expires": expires, "label": label,
            "scope": scope, "remote": bool(net["tailscale"]["up"])}


@app.post("/api/share/revoke")
async def share_revoke(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Drop one link, or {"all": true} to kill every outstanding one at
    once by turning the epoch over."""
    require_auth(authorization)
    payload = await request.json()
    rows = read_shares()
    if payload.get("all"):
        rows["epoch"] = int(rows.get("epoch") or 1) + 1
        rows["links"] = {}
        write_shares(rows)
        return {"revoked": "all"}
    tag = str(payload.get("tag") or "")
    (rows.setdefault("links", {})).pop(tag, None)
    write_shares(rows)
    return {"revoked": tag}


# --- The public listener door (#687) ----------------------------------------
# Sharing the broadcast with people who are not on your tailnet means the
# public internet, and port 8096 must NEVER be the thing that gets exposed:
# it serves the control panel with the API key embedded in the page
# (AUTOFILL_KEY), and read endpoints are open by default (LOCK_READS=false).
# Anyone who found that URL would own the station.
#
# So there is a second door on its own port that can only ever do one thing:
# let somebody holding a live tune-in token listen, request a song, vote and
# shout. Every other path is 404 before it reaches a handler, the
# Authorization header is stripped so a leaked key cannot elevate through
# it, and a FULL-scope token is deliberately downgraded here — a
# public-facing door does not open the studio no matter what it is shown.
PUBLIC_PORT = int(os.getenv("SPARK_PUBLIC_PORT", "8097"))
PUBLIC_ENABLED = os.getenv("SPARK_PUBLIC_LISTEN", "true").lower() in (
    "1", "true", "yes", "on")

# Exact paths, or prefixes ending in "/". Nothing is matched loosely: a
# regex over a public surface is how an allowlist quietly grows a hole.
_PUBLIC_GET = {"/healthz", "/api/dj", "/api/dj/voice", "/api/dj/reacts",
               "/api/radio/clock"}
_PUBLIC_GET_PREFIX = ("/tune/", "/media/", "/music/", "/data/vendor/")
_PUBLIC_POST = {"/api/dj/join", "/api/dj/request", "/api/dj/shout",
                "/api/music/vote",
                # #1149: wake-only - the route refuses to pause anything,
                # and it still demands a live listen token inside.
                "/api/radio/unpause"}


def _public_allows(method: str, path: str) -> bool:
    if method in ("GET", "HEAD"):
        return path in _PUBLIC_GET or path.startswith(_PUBLIC_GET_PREFIX)
    if method == "POST":
        return path in _PUBLIC_POST
    return False


class PublicListenerGate:
    """Wraps the whole app and lets almost nothing through.

    Deny-by-default: the allowlist above is the entire public surface, and
    anything outside it never reaches a route handler at all."""

    def __init__(self, inner: Any) -> None:
        self.inner = inner

    async def __call__(self, scope: Any, receive: Any, send: Any) -> None:
        if scope.get("type") != "http":
            return                          # no websockets on the public door
        path = str(scope.get("path") or "")
        if not _public_allows(str(scope.get("method") or ""), path):
            await send({"type": "http.response.start", "status": 404,
                        "headers": [(b"content-type", b"text/plain")]})
            await send({"type": "http.response.body",
                        "body": b"Not found on the listener door."})
            return
        # Strip Authorization, and mark the request so /tune can refuse to
        # serve the control panel through here.
        headers = [(k, v) for (k, v) in scope.get("headers") or []
                   if k.lower() != b"authorization"]
        headers.append((b"x-pinebox-public", b"1"))
        await self.inner(dict(scope, headers=headers), receive, send)


@app.on_event("startup")
async def _startup_public_door() -> None:
    """Bring up the listener door beside the main app, in this process."""
    if not PUBLIC_ENABLED or PUBLIC_PORT == STATION_PORT:
        return
    try:
        import uvicorn
        config = uvicorn.Config(PublicListenerGate(app), host="0.0.0.0",
                                port=PUBLIC_PORT, log_level="warning",
                                access_log=False,
                                # #1149: a car polls every 1.5-3s; the 5s
                                # default dropped the connection between
                                # polls and paid a fresh handshake each.
                                timeout_keep_alive=75)
        server = uvicorn.Server(config)
        server.install_signal_handlers = lambda: None   # the main one owns these
        asyncio.create_task(server.serve())
        print(f"[public] listener door on :{PUBLIC_PORT} — tune-in only",
              flush=True)
    except Exception as exc:
        print(f"[public] listener door did not start: {exc}", flush=True)


@app.get("/tune/{token}")
async def tune_page(token: str, request: Request) -> HTMLResponse:
    """Opened by a shared link. The page is handed the TOKEN, never the key.

    A full-scope link gets the real control panel rather than the listener
    page, so everything this station can do is available over it — the
    studio, the booth, the vector search, the voice work, all of it. It
    still runs on the token, so revoking the link locks that machine out
    without disturbing the key or anybody else's link."""
    scope = token_scope(token)
    if not scope:
        raise HTTPException(
            status_code=403,
            detail="That tune-in link has expired or been revoked.")
    # #687: through the public listener door it is ALWAYS the radio page,
    # whatever the token is worth. A full-scope pass is for a machine you
    # trust on your own network; it is not a thing to honour from the open
    # internet, where the link may have been forwarded to anyone.
    public = request.headers.get("x-pinebox-public") == "1"
    page = (CONTROL_PANEL_HTML if (scope == "full" and not public)
            else RADIO_PAGE_HTML)
    return HTMLResponse(page.replace("__SERVER_KEY__", json.dumps(token)))


@app.post("/api/dj/shout")
async def dj_shout(
    request: Request,
    t: str = "",
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """A listener says something to the booth (#632), or reacts to it. The
    pair actually hear it: a shout lands in the chat and gets worked into
    the next round, and reactions pile up as a mood the show can feel."""
    require_listen_auth(t, authorization)
    payload = await request.json()
    who = " ".join(str(payload.get("who") or "a listener").split())[:32]
    react = str(payload.get("react") or "")[:8]
    text = " ".join(str(payload.get("text") or "").split())[:280]
    if react:
        reacts = _RADIO.setdefault("reacts", [])
        reacts.append({"ts": int(time.time()), "who": who, "react": react})
        del reacts[:-200]
        return {"heard": react, "count": len(reacts)}
    if len(text) < 2:
        raise HTTPException(status_code=400, detail="Say something first")
    _RADIO.setdefault("chat", []).append({
        "ts": int(time.time()), "who": "host", "kind": "callin",
        "text": f"📣 {who}: {text}"})
    del _RADIO["chat"][:-240]
    note_action(f"📣 {who} shouted at the booth")
    # And the pair deal with it on air.
    if _RADIO.get("on"):
        asyncio.create_task(dj_banter(
            _RADIO.get("now"), lines=3,
            angle=(f"A listener called {who} has just said this to the "
                   f"station, live: \"{text}\" Read it out, take it "
                   "personally, and answer them by name on air.")))
    return {"heard": text, "on_air": bool(_RADIO.get("on"))}


@app.get("/api/dj/reacts")
async def dj_reacts(
    t: str = "",
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """What the room is throwing at the show, last few minutes."""
    require_listen_auth(t, authorization)
    now = time.time()
    live = [r for r in (_RADIO.get("reacts") or [])
            if now - float(r.get("ts") or 0) < 300]
    tally: dict[str, int] = {}
    for row in live:
        tally[row["react"]] = tally.get(row["react"], 0) + 1
    return {"reacts": live[-40:], "tally": tally,
            "listeners": _radio_listeners()}


