@app.get("/api/dj/mixtapes")
async def dj_mixtapes_list(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Every mixtape in the folder, newest first, so the library window can
    list them and let one be requested by name (#532)."""
    require_read_auth(authorization)
    out: list[dict[str, Any]] = []
    for p in mixtape_files():
        try:
            when = int(p.stat().st_mtime)
        except OSError:
            when = 0
        out.append({"id": sfx_id(p), "title": mixtape_title(p),
                    "when": when, "ready": tape_ready(p)})
    out.sort(key=lambda t: t["when"], reverse=True)
    return {"tapes": out, "folder": str(mixtape_folder())}


@app.post("/api/dj/mixtape")
async def dj_mixtape_api(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """A mixtape arrives in the mail RIGHT NOW: whatever is happening yields
    — a round mid-flight stops between turns, the current record is skipped,
    the tape's intro is the next thing said and the tape the next thing
    played. Pressing the button with the station off turns it on (#242). An
    explicit {id} plays THAT tape from the library window (#532)."""
    require_auth(authorization)
    try:
        want = str((await request.json()).get("id") or "")
    except Exception:
        want = ""
    if want:
        path = next((p for p in mixtape_files() if sfx_id(p) == want), None)
        if not path:
            raise HTTPException(status_code=404,
                                detail="That tape is not in the folder")
        tape = await asyncio.to_thread(mixtape_as_track, path)
        note_action(f"📼 you queued a mixtape: {tape['title']}")
    else:
        tape = await asyncio.to_thread(mixtape_pick)
    if not tape:
        raise HTTPException(status_code=404,
                            detail="No tapes in the folder yet")
    if not _RADIO.get("on"):
        dj_start(dj_best_station(""))   # the mail turns the station on
    _RADIO["since_tape"] = 0
    _RADIO["requests"].insert(0, tape)
    _TALK_CUT[0] += 1                   # cut any round mid-flight
    dj_skip()                           # the mail does not wait
    return {"tape": tape["title"], "seconds": tape["seconds"]}


