@app.post("/api/sfx/delete")
async def sfx_delete_api(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Take a sample off the shelf for good (#703).

    Banning keeps the file and stops it playing; this removes it. Wanted for
    the ones that simply do not belong in the pack — a ban list hundreds
    long is its own mess."""
    require_auth(authorization)
    payload = await request.json() if await request.body() else {}
    sid = str(payload.get("id") or "")
    path = sfx_by_id(sid)
    if not path or not path.is_file():
        raise HTTPException(status_code=404, detail="No such sample")
    name = path.name
    try:
        path.unlink()
    except OSError as exc:
        raise HTTPException(status_code=500,
                            detail=f"Could not delete it: {exc}")
    sfx_ban_set(sid, True)          # so nothing re-picks it this session
    pipeline_log("air", f"sample deleted from the shelf — {name} (#703)")
    return {"deleted": sid, "name": name}


@app.get("/api/sfx/review")
async def api_sfx_review(
    scan: int = 0,
    most: int = 200,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """#1199: the questionable clips, for the operator to keep or bin.

    SILENT is measured digital black; TOO SHORT is under the #1198 floor,
    a click rather than a sting; UNMEASURABLE is a file nothing could
    read. `scan` measures that many unmeasured files per call so the desk
    fills over a few refreshes instead of walking the whole library in
    one request. Nothing is deleted here - POST /api/sfx/delete (#703)
    is the door, and it is the operator's to open."""
    require_read_auth(authorization)
    # #1199: MEMOISED. Every sfx_seconds() lookup stats its file to key the
    # cache and there are six thousand of them on a CIFS share, so one
    # honest answer costs 45s of SMB round trips. The panel polls.
    memo = _SFX_REVIEW_MEMO
    if (memo.get("value") is not None and not int(scan or 0)
            and time.time() - float(memo.get("at") or 0) < SFX_REVIEW_REST):
        return memo["value"]

    def work() -> dict[str, Any]:
        floor = sfx_floor_seconds()
        pool = sfx_pool_cached()
        done = 0
        for path in pool:
            if done >= max(0, int(scan)):
                break
            if sfx_level(path, measure=False) is None:
                sfx_level(path, measure=True)
                done += 1
        _sfx_level_save()
        rows: list[dict[str, Any]] = []
        counts = {"silent": 0, "short": 0, "unmeasurable": 0,
                  "measured": 0, "pool": len(pool)}
        for path in pool:
            try:
                secs = sfx_seconds(path)
                lvl = sfx_level(path, measure=False)
                if lvl is not None:
                    counts["measured"] += 1
                if lvl is not None and float(lvl) <= SFX_SILENT_DB:
                    why, bucket = "silent", "silent"
                elif 0 < secs < floor:
                    why, bucket = "too short", "short"
                elif secs <= 0 and lvl is None:
                    why, bucket = "unmeasurable", "unmeasurable"
                else:
                    continue
                counts[bucket] += 1
                if len(rows) < max(0, int(most)):
                    _sid = sfx_id(path)
                    # #1204: a SIGNED url, because an <audio> element sends
                    # no Authorization header - the route takes a signature
                    # or a bearer, and a bare /sfx/<id> is a 404 the panel
                    # would show as "it would not play".
                    try:
                        _sig = media_sign(_sid)
                    except Exception:  # noqa: BLE001
                        _sig = ""
                    rows.append({"id": _sid, "name": path.stem,
                                 "url": ("/sfx/%s?t=%s" % (_sid, _sig)
                                         if _sig else ""),
                                 "seconds": round(float(secs), 2),
                                 "peak_db": (None if lvl is None
                                             else round(float(lvl), 1)),
                                 "why": why, "folder": path.parent.name})
            except Exception:  # noqa: BLE001
                continue
        rows.sort(key=lambda r: (r["why"], r["seconds"]))
        flagged = counts["silent"] + counts["short"] + counts["unmeasurable"]
        return {
            "at": time.time(), "rows": rows, "counts": counts,
            "floor_seconds": floor, "silent_db": SFX_SILENT_DB,
            "unmeasured_left": max(0, counts["pool"] - counts["measured"]),
            "delete_with": "POST /api/sfx/delete {\"id\": \"...\"}",
            "say": ("%d clip(s) worth a look: %d silent, %d too short, %d "
                    "unreadable - out of %d in the pool, %d measured so "
                    "far. Nothing is deleted unless you say so."
                    % (flagged, counts["silent"], counts["short"],
                       counts["unmeasurable"], counts["pool"],
                       counts["measured"])),
        }

    got = await asyncio.to_thread(work)
    # #1199: never memoise a COLD answer. _SFX_POOL_CACHE is empty for the
    # first minute after a restart, and caching "0 clips in the pool" for
    # ninety seconds told the operator his library was gone.
    if int((got.get("counts") or {}).get("pool") or 0) > 0:
        _SFX_REVIEW_MEMO.update({"at": time.time(), "value": got})
    return got


@app.get("/api/sfx/history")
async def sfx_history_api(
    limit: int = 200,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """#862: what has actually aired, newest first, each with how often
    it has come round, its weight and whether it is banned — the view
    the operator judges the rotation from."""
    require_read_auth(authorization)
    rows = sfx_history_rows()
    counts: dict[str, int] = {}
    for r in rows:
        sid = str(r.get("id") or "")
        counts[sid] = counts.get(sid, 0) + 1
    banned = sfx_bans()
    weights = sfx_weights()
    out = []
    for r in reversed(rows[-max(1, min(1000, limit)):]):
        sid = str(r.get("id") or "")
        out.append({**r, "plays": counts.get(sid, 0),
                    "weight": float(weights.get(sid, 1.0)),
                    "banned": sid in banned,
                    "url": f"/sfx/{sid}?t={media_sign(sid)}"})
    pool = len(_SFX_POOL_CACHE)
    return {"rows": out, "distinct": len(counts), "total": len(rows),
            "pool": pool, "folders": [str(f) for f in await asyncio.to_thread(sfx_folders)],
            # #1062: what is new, and how the draw favours it.
            "fresh": len(sfx_fresh_paths(list(_SFX_POOL_CACHE))),
            "arrivals_48h": len(sfx_arrivals_recent()),
            "fresh_share": SFX_FRESH_SHARE,
            "walked_at": _SFX_POOL_AT[0],
            "ready_at": _SFX_POOL_READY_AT[0],
            "filling": _SFX_POOL_FILLING[0],
            "note": ("Verified samples are ready while the library scan continues."
                     if pool and _SFX_POOL_FILLING[0] else
                     "The library scan has not found a verified playable sample yet."
                     if not pool else "")}


@app.get("/api/sfx/stats")
async def sfx_stats_api(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """The scoreboard (#300): every sample by play count, and which
    presenter leans on which button."""
    require_read_auth(authorization)
    plays = sfx_plays()
    bans = sfx_bans()
    samples = sorted(
        ({"id": sid, "name": row.get("name") or sid,
          "plays": int(row.get("plays") or 0),
          "last": int(row.get("last") or 0),
          "by": row.get("by") or {},
          "banned": sid in bans,
          "url": f"/sfx/{sid}?t={media_sign(sid)}"}
         for sid, row in plays.items()),
        key=lambda r: -r["plays"])
    djs: dict[str, dict[str, int]] = {}
    for row in samples:
        for who, count in row["by"].items():
            djs.setdefault(who, {})
            djs[who][row["name"]] = djs[who].get(row["name"], 0) + count
    favourites = {
        who: sorted(({"name": name, "plays": count}
                     for name, count in table.items()),
                    key=lambda r: -r["plays"])[:6]
        for who, table in djs.items()
    }
    return {"samples": samples[:200], "djs": favourites,
            "cadence": {**_SFX_CADENCE.state(), **_SFX_CADENCE_STATUS,
                        "enabled": _sfx_cadence_enabled(),
                        "every_units": int(dj_settings().get("sfx_every_units") or 0),
                        "guy_every_units": int(dj_settings().get("sfxguy_every_units", 4) or 0),
                        "unit": "completed recorded host sentence or reply",
                        "omission_window": "current process",
                        "constraint": "optional media omitted when unavailable or outside the programme budget"}}


SFX_SPEC_DIR = data_path("sfx_specs")


@app.get("/api/sfx/info")
async def sfx_info_api(
    id: str = "",
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Everything the hover card wants to know about one sample (#335):
    length, where it lives, how long its last announce took, how many
    plays today and ever, and whose finger it belongs to."""
    require_read_auth(authorization)
    sid = str(id or "")
    sample = sfx_by_id(sid)
    if sample is None:
        raise HTTPException(status_code=404, detail="No such sample")
    seconds = 0.0
    try:
        import mutagen
        info = mutagen.File(sample)
        seconds = float(getattr(getattr(info, "info", None), "length", 0.0)
                        or 0.0)
    except Exception:
        pass
    where = str(sample)
    for root, label in ((SFX_MADE_DIR, "made scratches"),
                        (SFX_ROOT, "samples")):
        try:
            where = f"{label}/{sample.relative_to(root)}"
            break
        except ValueError:
            continue
    row = sfx_plays().get(sid) or {}
    by = row.get("by") or {}
    top = max(by, key=by.get) if by else ""
    return {
        "id": sid,
        "name": sample.stem,
        "seconds": round(seconds, 2),
        "where": where,
        "plays": int(row.get("plays") or 0),
        "today": int((row.get("days") or {}).get(
            time.strftime("%Y-%m-%d")) or 0),
        "last": int(row.get("last") or 0),
        "last_ms": int(row.get("last_ms") or 0),
        "top_dj": top,
        "top_dj_plays": int(by.get(top) or 0) if top else 0,
        # Everyone who has reached for it, and your dial on it (#645).
        "by": by,
        "banned": sid in sfx_bans(),
        "weight": sfx_weights().get(sid, 1.0),
        "url": f"/sfx/{sid}?t={media_sign(sid)}",
        "spec_url": f"/api/sfx/spec/{sid}?t={media_sign(sid)}",
    }


@app.post("/api/sfx/weight")
async def sfx_weight_api(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """How often this one may come up (#645): 0 never, 1 normal, up to 4 for
    one you want leaned on. A ban is still the separate hard no."""
    require_auth(authorization)
    payload = await request.json()
    sid = str(payload.get("id") or "")
    if sfx_by_id(sid) is None:
        raise HTTPException(status_code=404, detail="No such sample")
    rows = sfx_set_weight(sid, float(payload.get("weight") or 1.0))
    return {"id": sid, "weight": rows.get(sid, 1.0)}


@app.get("/api/sfx/spec/{sid}")
async def sfx_spec_api(
    sid: str,
    request: Request,
    authorization: str | None = Header(default=None),
) -> Response:
    """The sample's spectrogram, rendered once and cached — the picture
    half of the hover card (#335)."""
    if not re.match(r"^[a-f0-9]{16}\Z", sid or ""):
        return Response(status_code=404)
    signature = str(request.query_params.get("t") or "")
    expected = media_sign(sid)
    if not (expected and hmac.compare_digest(signature, expected)):
        require_read_auth(authorization)
    sample = sfx_by_id(sid)
    if sample is None:
        return Response(status_code=404)
    out = SFX_SPEC_DIR / f"{sid}.png"
    if not out.exists():
        SFX_SPEC_DIR.mkdir(parents=True, exist_ok=True)
        ok = await asyncio.to_thread(_render_spectrogram, sample, out)
        if not ok:
            return Response(status_code=404)
    return Response(out.read_bytes(), media_type="image/png",
                    headers={"Cache-Control": "private, max-age=86400"})


@app.get("/api/sfx/ring")
async def sfx_ring_get(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """The station's phone bell, as numbers you can move (#714)."""
    require_read_auth(authorization)
    return {"preset": ring_preset(), "default": dict(RING_DEFAULT)}


@app.post("/api/sfx/ring")
async def sfx_ring_set(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Make this the bell the station actually rings (#714). The next call
    rings on it — make_phone_ring rebuilds from the preset every time."""
    require_auth(authorization)
    payload = await request.json()
    if payload.get("reset"):
        preset = ring_save(dict(RING_DEFAULT))
    else:
        preset = ring_save(payload.get("preset") or payload)
    # Rebuild the file now so the change is audible on the very next ring
    # rather than on the one after it.
    await asyncio.to_thread(make_phone_ring)
    note_action("☎ you re-tuned the station's phone bell")
    return {"preset": preset}


@app.get("/api/sfx/ring/preview")
async def sfx_ring_preview(
    request: Request,
    authorization: str | None = Header(default=None),
) -> Response:
    """Render a bell from query parameters and hand it back as a wav (#714)
    — the sound of the sliders where they are RIGHT NOW, without committing
    it to the station or ringing it at anybody."""
    require_read_auth(authorization)
    want = {k: v for k, v in request.query_params.items() if k in RING_DEFAULT}
    preset = ring_clamp({**ring_preset(), **want})
    out = SFX_MADE_DIR / "phone-ring-preview.wav"
    made = await asyncio.to_thread(ring_render, preset, out, 1.0)
    if not made:
        raise HTTPException(status_code=500, detail="The bell came out empty")
    return FileResponse(made, media_type="audio/wav",
                        filename="pinebox-phone-ring.wav",
                        headers={"Cache-Control": "no-store"})


@app.get("/api/sfx/dir")
async def sfx_dir_api(
    of: str = "",
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Every sample in the folder this one came from, each with its
    switch — the ● popup behind a played sting (#269)."""
    require_read_auth(authorization)
    sample = sfx_by_id(str(of or ""))
    if sample is None:
        raise HTTPException(status_code=404, detail="No such sample")
    bans = sfx_bans()
    try:
        kin = sorted((p for p in sample.parent.iterdir()
                      if p.suffix.lower() in (".wav", ".mp3")),
                     key=lambda p: p.name.lower())
    except OSError:
        kin = [sample]
    samples = []
    for path in kin[:400]:
        sid = sfx_id(path)
        samples.append({"id": sid, "name": path.stem,
                        "banned": sid in bans,
                        "url": f"/sfx/{sid}?t={media_sign(sid)}"})
    return {"dir": sample.parent.name or "sfx", "samples": samples,
            "banned_total": len(bans)}


@app.get("/api/dj/reel")
async def dj_reel_api(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Varied, randomized passages for the reel to spin through (#488, #513).
    Drawn from the speakbox DOCUMENTS, not the rendered backlog — the backlog
    can be one line the box looped fifty times, which is why every pocket of
    the wheel read the same. Deduped and shuffled so no two pockets match and
    a fresh spin lands somewhere new every time."""
    require_read_auth(authorization)
    seen: set[str] = set()
    uniq: list[str] = []
    for p in speakbox_all():
        try:
            for ln in speakbox_lines(p.read_text(errors="replace")):
                key = ln.lower()
                if key not in seen:
                    seen.add(key)
                    uniq.append(ln)
        except Exception:
            pass
    random.shuffle(uniq)
    return {"lines": uniq[:24]}


@app.post("/api/dj/flow/repair")
async def dj_flow_repair_api(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Apply the continuity-safe configuration and wake the reserve writer."""
    require_auth(authorization)
    settings = load_settings()
    current = dict(settings.get("dj") or {})
    current.update({
        "dialogue_prefill": True,
        "dialogue_reserve_target": max(5, int(
            current.get("dialogue_reserve_target") or 4)),
        "talk_radio_mode": True,
        "records_first": True,
        "stream_show": True,
        # The watchdog is a last resort, but should not accept a long empty
        # handoff while the reserve writer has work ready to do.
        "dead_air_seconds": min(30, max(15, int(
            current.get("dead_air_seconds") or 30))),
    })
    settings["dj"] = current
    save_settings(settings)
    repair_note("continuity repair armed: torrent, records-first and a five-round dialogue reserve")
    # The keeper's next three-second pass is enough if a live turn owns the
    # model. When it is idle, kick it now rather than waiting for the clock.
    if _RADIO.get("on") and not _LARDER_WRITING[0] \
            and not _OLLAMA_GATE.locked():
        async def _fill_reserve() -> None:
            _LARDER_WRITING[0] = True
            try:
                await dj_banter(None, bank=True, render_stream=True)
            finally:
                _LARDER_WRITING[0] = False
        asyncio.create_task(_fill_reserve())
    return dialogue_flow_state()


@app.post("/api/dj/hold/clear")
async def dj_hold_clear(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """#807: empty the hold shelf without airing it — for a backlog that
    was held by mistake and would replay as repeats. {"older_than": s}
    keeps entries younger than s seconds (default 0 = clear all). The
    transcript keeps every line; only the pending re-air is cancelled."""
    require_auth(authorization)
    payload = await request.json()
    keep_after = time.time() - float(payload.get("older_than") or 0)
    before = len(_BOX_HOLD)
    kept = [h for h in _BOX_HOLD
            if float(h.get("ts") or 0) > keep_after]
    if float(payload.get("older_than") or 0) <= 0:
        kept = []
    cleared = before - len(kept)
    _BOX_HOLD[:] = kept
    _box_hold_save()
    note_action(f"🧹 hold shelf cleared — {cleared} pending replay(s) "
                "cancelled (transcript keeps the words)")
    pipeline_log("air", f"hold shelf purged: {cleared} cancelled, "
                        f"{len(kept)} kept (#807)")
    return {"cleared": cleared, "kept": len(kept)}


@app.get("/api/dj/backlog")
async def dj_backlog_api(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """The dialogue backlog (#434): every rendered line the browser can
    replay — the page-feed clips that have aired or diverted, and the
    hold-shelf clips queued for the box — newest first, each with a
    playable URL so the viewer can audition the whole generated stream."""
    require_read_auth(authorization)
    # What rendered each line, matched from the transcript by text (#455):
    # the chat entry carries the engine/voice/model, the clip does not.
    by_text = {}
    for line in (_RADIO.get("chat") or []):
        t = str(line.get("text") or "")[:80]
        if t:
            by_text[t] = {"engine": line.get("engine") or "",
                          "voice": line.get("voice") or "",
                          "model": line.get("model") or ""}
    engine_names = {"xtts": "XTTS v2 clone server (:8770, CUDA)",
                    "piper": "wyoming-piper (:10200)",
                    "voxtral": "Voxtral 4B (:8000)", "": "the voice engine"}

    def render_info(text: str, clip: dict | None = None) -> dict[str, Any]:
        # Prefer what the clip stamped on itself; fall back to matching the
        # transcript by text for older clips that carry no engine (#455).
        meta = by_text.get(str(text)[:80]) or {}
        clip = clip or {}
        eng = str(clip.get("engine") or meta.get("engine") or "")
        voice = clip.get("voice") or meta.get("voice") or ""
        return {"engine": eng,
                "rendered_by": engine_names.get(eng, eng or "the box"),
                "voice": voice,
                "model": meta.get("model") or ""}

    def spec_url(url: str) -> str:
        # /media/<key>?t=<sig>  →  /media/<key>/spec?t=<sig>  (#455).
        path, _, query = str(url).partition("?")
        if not path.startswith("/media/"):
            return ""
        return f"{path}/spec" + (f"?{query}" if query else "")

    items: list[dict[str, Any]] = []
    for clip in (_RADIO.get("voice_clips") or [])[-60:]:
        if clip.get("url"):
            items.append({
                "ts": clip.get("ts") or 0, "text": clip.get("text") or "",
                "url": clip["url"], "spec": spec_url(clip["url"]),
                "status": "aired", "who": clip.get("who") or "",
                **render_info(clip.get("text") or "", clip)})
    # The shelf can hold thousands now (#473) — show the most recent slice
    # but report the true depth so the backlog reads as the deep store it is.
    hold_bytes = sum(int(r.get("bytes") or 0) for r in _BOX_HOLD)
    for held in _BOX_HOLD[-80:]:
        url = f"{held.get('path')}?t={held.get('sig')}"
        items.append({
            "ts": int((held.get("ts") or 0) * 1000),
            "text": held.get("text") or "",
            "url": url, "spec": spec_url(url),
            "status": "queued", "who": held.get("who") or "",
            **render_info(held.get("text") or "", held)})
    items.sort(key=lambda r: r["ts"], reverse=True)
    return {"items": items[:80], "held": len(_BOX_HOLD),
            "held_mb": round(hold_bytes / 1e6, 1),
            "larder": len(_LARDER)}


@app.get("/api/dj/crystal")
async def dj_crystal_api(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """The data crystal (#350): everything the pair have said — the whole
    remembered ring plus the fresh, speaker-labelled tail — for the 💠
    plexus window to grow its point cloud from."""
    require_read_auth(authorization)
    _ensure_chat_ids()
    said = said_texts(400)
    fresh = [{"who": line.get("who"), "text": line.get("text"),
              "id": line.get("id")}
             for line in (_RADIO.get("chat") or [])
             if line.get("kind") != "sfx" and line.get("who") != "host"
             and line.get("text")]
    # A separate crystal per person in the studio (#484): host, co-host, the
    # third chair and the SFX guy each get their own labelled cloud, and
    # every point carries its code so it can be right-clicked away.
    dj = dj_settings()
    labels = {"dj": dj.get("host_name") or "Host",
              "cohost": dj.get("cohost_name") or "Co-host",
              "third": dj.get("third_name") or "Third",
              "drop": "The SFX Guy", "caller": "Callers"}
    by_who: dict[str, dict[str, Any]] = {}
    for line in (_RADIO.get("chat") or []):
        who = line.get("who") or ""
        if line.get("kind") == "sfx" or who in ("", "host") \
                or not line.get("text"):
            continue
        slot = by_who.setdefault(
            who, {"who": who, "label": labels.get(who, who), "points": []})
        slot["points"].append({"id": line.get("id"),
                               "text": str(line.get("text"))[:300]})
    return {"said": said, "fresh": fresh[-120:],
            "by_who": list(by_who.values()), "larder": len(_LARDER)}


