@app.get("/api/ha/media-players")
async def ha_media_players(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Speakers Home Assistant can play TTS on (incl. HomeKit/AirPlay ones)."""
    require_auth(authorization)
    token, player = _ha_creds()
    _reply_token, reply_player = _ha_creds(reply=True)
    if not token:
        return {"players": [], "configured": player,
                "configured_reply": reply_player, "token_set": False}
    try:
        async with httpx.AsyncClient(timeout=8) as client:
            response = await client.get(
                f"{HA_URL}/api/states",
                headers={"Authorization": f"Bearer {token}"},
            )
            response.raise_for_status()
            states = response.json()
    except Exception as exc:
        raise HTTPException(
            status_code=502, detail=f"Home Assistant: {exc}"
        ) from exc
    players = [
        {
            "entity_id": s["entity_id"],
            "name": (s.get("attributes") or {}).get(
                "friendly_name", s["entity_id"]
            )
            + (
                " · Pine Box speaker"
                if str(s["entity_id"]).startswith("assist_satellite.")
                else ""
            ),
            "state": s.get("state", ""),
            "kind": ("assist_satellite"
                     if str(s["entity_id"]).startswith("assist_satellite.")
                     else "media_player"),
        }
        for s in states
        if str(s.get("entity_id", "")).startswith(
            ("media_player.", "assist_satellite.")
        )
    ]
    return {"players": players, "configured": player,
            "configured_reply": reply_player, "token_set": True}


@app.post("/api/model")
async def switch_model(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Change the active model immediately and warm it in the background."""
    require_auth(authorization)
    payload = await request.json()
    model = str(payload.get("model") or "").strip()
    if not model:
        raise HTTPException(status_code=400, detail="No model given")
    settings = load_settings()
    settings["model"] = model
    save_settings(settings)

    async def _warm() -> None:
        try:
            await call_ollama(
                model=model,
                messages=[{"role": "user", "content": "hi"}],
                temperature=0.0,
                max_tokens=1,
                num_ctx=2048,
            )
        except Exception:
            pass

    fire_and_forget(_warm())
    return {"model": model, "warming": True}


