@app.post("/v1/chat/completions")
async def chat_completions(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    require_auth(authorization)
    incoming = await request.json()
    incoming_messages = incoming.get("messages")

    if not isinstance(incoming_messages, list):
        raise HTTPException(
            status_code=400,
            detail="messages must be an array",
        )

    user_text = latest_user_text(incoming_messages)

    # Inbox dictation outranks station intents: the next sentence may itself
    # describe a radio fault or ask for a song, but here it is the request body.
    pine = await pine_conversation(
        incoming_messages, pine_conversation_session(request, incoming))
    if pine:
        log_turn(user_text, pine["reply"], {"active_prompt": "Pine Chat",
                                            "model": "pine-inbox", "pine_request": True})
        completion = {
            "id": f"chatcmpl-{uuid.uuid4().hex}", "object": "chat.completion",
            "created": int(time.time()), "model": "pine-inbox",
            "choices": [{"index": 0, "message": {
                "role": "assistant", "content": pine["reply"]},
                "finish_reason": "stop"}],
            "usage": {"prompt_tokens": 0, "completion_tokens": 0,
                      "total_tokens": 0}, "spark_agent": {"pine_request": pine}}
        if incoming.get("stream"):
            async def inbox_events():
                base = {key: completion[key] for key in ("id", "created", "model")}
                chunk = {**base, "object": "chat.completion.chunk", "choices": [
                    {"index": 0, "delta": {"role": "assistant", "content": pine["reply"]},
                     "finish_reason": None}]}
                yield "data: " + json.dumps(chunk) + "\n\n"
                chunk["choices"] = [{"index": 0, "delta": {}, "finish_reason": "stop"}]
                yield "data: " + json.dumps(chunk) + "\n\n"
                yield "data: [DONE]\n\n"
            return StreamingResponse(inbox_events(), media_type="text/event-stream")
        return completion

    # #787: "hey DJ …" — straight to the booth: a request if the library
    # can fill it, a phone-in topic otherwise. The model never sees it.
    _dj_woke = _DJ_WAKE.match(user_text or "")
    if _dj_woke:
        _reply = await dj_wake_handle(user_text[_dj_woke.end():].strip())
        note_action(f"🎙 you woke the booth: {user_text[:60]}")
        log_turn(user_text, _reply, {"active_prompt": "Pine Box FM",
                                     "model": "station", "dj_wake": True})
        return {
            "id": f"chatcmpl-{uuid.uuid4().hex}",
            "object": "chat.completion",
            "created": int(time.time()),
            "model": "pine-box-fm",
            "choices": [{
                "index": 0,
                "message": {"role": "assistant", "content": _reply},
                "finish_reason": "stop",
            }],
            "usage": {"prompt_tokens": 0, "completion_tokens": 0,
                      "total_tokens": 0},
            "spark_agent": {"dj_wake": True},
        }

    # "Play Blue Monday on Pine Box FM", said out loud to the box. The
    # station takes this one; the model never sees it.
    taken = await dj_take_request(user_text)
    # #759/#761/#762: …and questions ABOUT the station, said to the box.
    # After the request path, because "play something on the station" is a
    # request and not a fault report; before the model, because the model
    # cannot switch the box on. The string returned here is what the box
    # SAYS — Home Assistant synthesises it — so nothing on this path may
    # speak for itself or it would talk over its own answer.
    if not taken:
        _intent = station_intent(user_text)
        if _intent:
            _reply = await station_intent_reply(_intent, user_text)
            if _reply:
                note_action(f"📻 you asked the box: {user_text[:60]}")
                log_turn(user_text, _reply,
                         {"active_prompt": "Pine Box FM",
                          "model": "station", "station_intent": _intent})
                return {
                    "id": f"chatcmpl-{uuid.uuid4().hex}",
                    "object": "chat.completion",
                    "created": int(time.time()),
                    "model": "pine-box-fm",
                    "choices": [{
                        "index": 0,
                        "message": {"role": "assistant",
                                    "content": _reply},
                        "finish_reason": "stop",
                    }],
                    "usage": {"prompt_tokens": 0, "completion_tokens": 0,
                              "total_tokens": 0},
                    "spark_agent": {"station_intent": _intent},
                }
    if taken:
        log_turn(user_text, taken["reply"],
                 {"active_prompt": "Pine Box FM", "model": "station",
                  "dj_request": taken["query"]})
        return {
            "id": f"chatcmpl-{uuid.uuid4().hex}",
            "object": "chat.completion",
            "created": int(time.time()),
            "model": "pine-box-fm",
            "choices": [{
                "index": 0,
                "message": {"role": "assistant", "content": taken["reply"]},
                "finish_reason": "stop",
            }],
            "usage": {"prompt_tokens": 0, "completion_tokens": 0,
                      "total_tokens": 0},
            "spark_agent": {"dj_request": taken},
        }

    answer, metadata = await generate_answer(
        incoming_messages,
        requested_model=incoming.get("model"),
        requested_max_tokens=(
            incoming.get("max_tokens")
            or incoming.get("max_completion_tokens")
        ),
    )

    log_turn(user_text, answer, metadata)

    if load_settings().get("openwebui_logging", True):
        fire_and_forget(
            mirror_to_openwebui(user_text, answer, metadata["model"])
        )

    return {
        "id": f"chatcmpl-{uuid.uuid4().hex}",
        "object": "chat.completion",
        "created": int(time.time()),
        "model": metadata["model"],
        "choices": [
            {
                "index": 0,
                "message": {
                    "role": "assistant",
                    "content": answer,
                },
                "finish_reason": "stop",
            }
        ],
        # Not every path through generate_answer talks to the model — a
        # request taken by the station never does — so token counts are
        # optional rather than guaranteed.
        "usage": {
            "prompt_tokens": metadata.get("prompt_tokens", 0),
            "completion_tokens": metadata.get("completion_tokens", 0),
            "total_tokens": (
                metadata.get("prompt_tokens", 0)
                + metadata.get("completion_tokens", 0)
            ),
        },
        "spark_agent": {
            "web_search_used": metadata["web_search_used"],
            "game_lookup_used": metadata["game_lookup_used"],
            "from_library": metadata["from_library"],
            "system_status_used": metadata["system_status_used"],
            "image_requested": metadata["image_requested"],
            "openwebui_used": metadata["openwebui_used"],
            "memory_used": metadata["memory_used"],
            "memory_saved": metadata["memory_saved"],
            "active_prompt": metadata["active_prompt"],
        },
    }


