    # Lucene terms are escaped, not quoted — quoting is what returned zero
    # results for records that plainly exist.
    assert _mb_term('Playing the "Orchestra"') == "Playing the Orchestra"
    assert _mb_term("AC/DC: Back!") == "AC DC Back"   # whitespace collapses

    # An ad read survives a rewrite and keeps its id. Pointed at scratch
    # first: this writes through ad_save, and a check that fails between the
    # save and the delete would otherwise leave "test widget" in the real
    # sponsor rotation for the DJ to read out on air.
    _ads_was = ADS_PATH
    globals()["ADS_PATH"] = Path("/tmp/ad-reads-selfcheck.json")
    ADS_PATH.unlink(missing_ok=True)
    try:
        _ad = ad_save("test widget", "Buy a test widget today.")
        assert ad_update(_ad["id"], text="Rewritten.")["text"] == "Rewritten."
        assert any(r["id"] == _ad["id"] for r in ad_list())
        ad_delete(_ad["id"])
        assert not any(r["id"] == _ad["id"] for r in ad_list())
    finally:
        ADS_PATH.unlink(missing_ok=True)
        globals()["ADS_PATH"] = _ads_was

