    assert len(_MUSIC["tracks"]) == 1
    _music_publish([{"id": "new", "title": "new"}], save=False, final=True)
    assert _MUSIC["tracks"][0]["id"] == "new"       # final: swapped in
    _MUSIC.update({"tracks": [], "by_id": {}})
    assert MUSIC_INDEX_TTL >= 3600      # a NAS walk is not a per-request cost

