    # ...and the episode test, because "Severance" also means a payout.
    assert _about_episode(
        {"title": "Severance | Season 2 - Episode 1 | Discussion Thread"}, 2, 1)
    assert _about_episode({"title": "Severance S02E01 reaction"}, 2, 1)
    assert _about_episode({"title": "Severance 2x01 recap"}, 2, 1)
    assert not _about_episode(
        {"title": "Whiting Petroleum Layoffs",
         "snippet": "what did severance packages look like"}, 2, 1)
    assert not _about_episode({"title": "Severance season 2 explained"}, 2, 1)
    # Reddit slugs: underscores must not defeat the match, and the WRONG
    # episode must still be rejected.
    assert _about_episode(
        {"url": "reddit.com/r/x/comments/1i5/helly_r_in_s02e01/"}, 2, 1)
    assert _about_episode(
        {"url": "reddit.com/r/x/severance_season_2_episode_1_discussion/"}, 2, 1)
    assert not _about_episode(
        {"url": "reddit.com/r/x/severance_season_2_episode_3_discussion/"}, 2, 1)

    # The cloud counts words, not noise.
    assert CLOUD_WORD.findall("the OP-XY sounds great".lower()) == [
        "the", "op-xy", "sounds", "great"]     # hyphenated names stay whole
    assert CLOUD_WORD.findall("i am ok") == []            # 1-2 letters dropped
    assert "the" in CLOUD_STOPWORDS and "op-xy" not in CLOUD_STOPWORDS

    # Range parsing: iOS Safari refuses audio it cannot seek within.
    assert _range_slice("", 100) is None
    assert _range_slice("bytes=0-", 100) == (0, 99)
    assert _range_slice("bytes=10-19", 100) == (10, 19)
    assert _range_slice("bytes=-20", 100) == (80, 99)
    assert _range_slice("bytes=90-999", 100) == (90, 99)
    assert _range_slice("bytes=200-", 100) == (-1, -1)

    # The key shape is the whole path-traversal defence.
    assert MEDIA_KEY_SHAPE.match("a" * 32 + ".wav")
    assert not MEDIA_KEY_SHAPE.match("../../etc/passwd")
    assert not MEDIA_KEY_SHAPE.match("/media/" + "a" * 32 + ".wav")
    assert not MEDIA_KEY_SHAPE.match("a" * 32 + ".wav\n")  # $ would allow it
    assert not MEDIA_KEY_SHAPE.match("A" * 32 + ".wav")

    # The cap has to hold, not merely be consulted.
