    assert _vs["render_replies"] == ["Ready!", "7"]
    assert validate_settings(DEFAULT_SETTINGS)["render_replies"]
    _hist = {
        "old": {"outputs": {"9": {"images": [
            {"filename": "old.png", "type": "output"},
            {"filename": "tmp.png", "type": "temp"},
        ]}}},
        "new": {"outputs": {"9": {"images": [
            {"filename": "new.png", "type": "output"},
        ]}}},
    }
    assert _comfy_output_files(_hist) == ["new.png", "old.png"]   # newest first
    assert "tmp.png" not in _comfy_output_files(_hist)            # output only
    _dup = {
        "a": {"outputs": {"9": {"images": [
            {"filename": "x.png", "type": "output"}]}}},
        "b": {"outputs": {"9": {"images": [
            {"filename": "x.png", "type": "output"}]}}},
    }
    assert _comfy_output_files(_dup) == ["x.png"]                 # de-duped
    assert turn_features(
        {"image_requested": True, "memory_used": True}
    ) == ["image generation", "memory recall"]
    assert turn_features({"weather_used": True}) == ["weather"]
    assert turn_features({}) == []
    _items = [
        {"id": 2, "when": "2026-07-19 14:03", "status": "open",
         "text": "second\nline"},
        {"id": 1, "when": "2026-07-19 13:50", "status": "open",
         "text": "first"},
    ]
    _round = _PINE_BLOCK_RE.findall(_pine_render(_items))
    assert [int(r[0]) for r in _round] == [2, 1]          # order preserved
    assert _round[0][3].strip() == "second\nline"          # multiline body
    assert validate_settings(DEFAULT_SETTINGS)["pine_chat"]["submit_phrase"]
    _wf = _comfy_workflow('neon fox, "cyberpunk", back\\slash')
    _texts = [
        n["inputs"].get("text")
        for n in _wf.values()
        if isinstance(n, dict) and isinstance(n.get("inputs"), dict)
    ]
    assert any(
        isinstance(t, str) and 'neon fox, "cyberpunk", back\\slash' in t
        for t in _texts
    ), "prompt substitution must survive quotes/backslashes"
    _seeds = [
        n["inputs"][k]
        for n in _wf.values()
        if isinstance(n, dict) and isinstance(n.get("inputs"), dict)
        for k in ("seed", "noise_seed")
        if k in n["inputs"]
    ]
    assert _seeds and all(isinstance(s, int) for s in _seeds)
    assert _workflow_model_name(_wf) != ""
    assert [t[0] for t in banter_turns("A: One. B: Two. A: Three.")] == [
        "A", "B", "A"]
    # A transcript's timestamps are not dialogue, and neither are its
    # headings — what comes out has to be sayable as it stands.
    _said = speakbox_lines(
        "# A night at the Bowl\n\n"
        "[0:47] I can still feel his head in my hand and it was spongy. "
        "Short.\n\n"
        "![a picture](x.png)\n\n"
        "(1:02:03) Bodyguards should not wear dress shoes to work, is the "
        "thing I learned.")
    assert not any(l.startswith(("#", "[", "(", "!")) for l in _said), _said
    assert any(l.startswith("I can still feel") for l in _said), _said
    assert any(l.startswith("Bodyguards should not") for l in _said), _said
    assert "Short." not in _said        # too short to be worth saying
    # An unpunctuated machine transcript still has to yield sayable lines.
    _asr = speakbox_lines(
        "[0:02] [Music] " + "who decides who gets to be polled and who are "
        "these undecideds nobody is more undecided than me " * 6)
    assert len(_asr) > 3 and all(6 <= len(l.split()) <= 16 for l in _asr), _asr
    assert not any("[" in l for l in _asr), _asr
    # The same angle twice inside a few minutes is what a broken show sounds
    # like, so a draw never lands on what has just been used.
    _RADIO.setdefault("recent", {}).clear()
    _draws = [unrepeated(["a", "b", "c"], "t", keep=2) for _ in range(6)]
    assert all(_draws[i] != _draws[i + 1] for i in range(5)), _draws
    assert set(_draws) == {"a", "b", "c"}, _draws
    assert unrepeated([], "t") == ""    # nothing to draw is not a crash
    _RADIO["recent"].clear()
    # The gem is dropped on the other one, and lands on somebody.
    _gem = speakbox_angle({"file": "x.md", "text": "the thing itself"})
    assert "{other}" not in _gem, _gem            # the drop was formatted
    assert "the thing itself" in _gem and _gem[0] in "AB", _gem
    assert "A" in _gem and "B" in _gem, _gem      # both of them are in it
    assert any(r in _gem for r in SPEAKBOX_REACTIONS), _gem
    _RADIO["recent"].clear()
    # The dice cut a bigger section than an ordinary round (#244). The start
    # is random, so measure the ceiling over many rolls, not one.
    _pool14 = [f"Sentence number {n} of the long passage." for n in range(30)]
    _rolls = [speakbox_swath_lines(_pool14, most=14, cap=1600)
              for _ in range(30)]
    assert max(len(r) for r in _rolls) >= 12, [len(r) for r in _rolls]
    assert all(len(r) <= 14 and len(" ".join(r)) <= 1600 for r in _rolls)
    assert all(len(speakbox_swath_lines(_pool14)) <= 9 for _ in range(10))

    # The whole swath, not one line out of it (#210) — and consecutive, so
    # the thought stays whole instead of two unrelated remarks stapled up.
    _pool = ["One. " * 5, "Two. " * 5, "Three. " * 5, "Four. " * 5]
    _swath = speakbox_swath(_pool, most=3)
    assert _swath in " ".join(_pool), _swath          # a run, not a shuffle
    assert len(_swath.split(".")) > 3, _swath         # more than one sentence
    assert len(speakbox_swath(_pool * 40)) <= SPEAKBOX_SWATH_MAX
    assert speakbox_swath([]) == ""

    # A document nobody has weighted is ordinary, not silent (#209, #221).
    assert speakbox_weight("brand-new.md", {}) == 50
    assert speakbox_weight("loud.md", {"loud.md": 100}) == 100
    assert speakbox_weight("off.md", {"off.md": 0}) == 0
    assert speakbox_weight("silly.md", {"silly.md": 900}) == 100

    # Titles the pair cannot read get chic English and a fun fact (#241).
    assert cjk_title("シーケンサーii") and cjk_title("愛の夢")
    assert cjk_title("東京") and not cjk_title("Blue Monday")
    assert not cjk_title("Tokyo Beach Trip") and not cjk_title("")
    _xlat_was = TITLE_XLAT_PATH
    globals()["TITLE_XLAT_PATH"] = Path("/tmp/xlat-selfcheck.json")
    TITLE_XLAT_PATH.unlink(missing_ok=True)
    _ask_was = globals()["ask_model"]

    async def _stub_xlat(prompt, limit=300):
        return "  \"Sequencer Two\"  "

    globals()["ask_model"] = _stub_xlat
    try:
        assert asyncio.run(translate_title("Blue Monday")) == ""
        assert asyncio.run(
            translate_title("シーケンサーii")) == "Sequencer Two"
        # Cached: the second call must not need the model at all.
        globals()["ask_model"] = None
        assert asyncio.run(
            translate_title("シーケンサーii")) == "Sequencer Two"
        assert spoken_title("シーケンサーii") == "Sequencer Two"
        assert spoken_title("Blue Monday") == "Blue Monday"
        assert "did you know" in title_fact("愛", "Love").lower()
        assert title_fact("愛", "") == ""

        async def _same_script(prompt, limit=300):
            return "愛の夢"

        globals()["ask_model"] = _same_script
        assert asyncio.run(translate_title("愛の夢")) == "", (
            "an answer in the same script is not an answer")
    finally:
        globals()["ask_model"] = _ask_was
        TITLE_XLAT_PATH.unlink(missing_ok=True)
        globals()["TITLE_XLAT_PATH"] = _xlat_was

    # A round mid-flight yields between turns when something urgent takes
    # the floor (#242).
    async def _stub_speak2(kind, track=None, extra="", line="", who="dj",
                           voice=None, source="", by_hand=False, fx=None,
                           name="", source_text=""):
        if line == "Two.":
            _TALK_CUT[0] += 1           # the mail arrives mid-round
        return line or "said"

    _speak_was = globals()["dj_speak"]
    _voices_was = globals()["session_voices"]

    async def _stub_voices2():
        return {"dj": "", "cohost": ""}

    globals()["dj_speak"] = _stub_speak2
    globals()["session_voices"] = _stub_voices2
    try:
        _cut_round = asyncio.run(speak_turns(
            [("A", "One."), ("B", "Two."), ("A", "Three."), ("B", "Four.")],
            None, 9))
        assert len(_cut_round) == 2, _cut_round   # Three. and Four. yielded
    finally:
        globals()["dj_speak"] = _speak_was
        globals()["session_voices"] = _voices_was

    # The MX mixtapes (#239): one tape per recording with the mp3 preferred
    # over its wav twin, a date for a title, and never the same tape twice
    # running.
    _tapedir = Path("/tmp/tapes-selfcheck")
    _tapedir.mkdir(parents=True, exist_ok=True)
    for _name in ("2026-08-04_233946_000.wav", "2026-08-04_233946_000.mp3",
                  "2026-08-09_120224_000.mp3", "2026-08-10_082255_000.wav",
                  "notes.txt"):
        (_tapedir / _name).write_bytes(b"RIFF")
    _real_dj2 = dj_settings
    globals()["dj_settings"] = lambda: {
        **DEFAULT_DJ, "mixtape_folder": "tapes-selfcheck"}
    _sfx_root_was2 = SFX_ROOT
    globals()["SFX_ROOT"] = Path("/tmp")
    # The pick warms a background transcode; on a scratch file that is about
    # to be deleted that is just ffmpeg noise in the check output.
    _transcode_was = globals()["_tape_transcode_soon"]
    globals()["_tape_transcode_soon"] = lambda *a: None
    try:
        _tapes = mixtape_files()
        assert [t.name for t in _tapes] == [
            "2026-08-04_233946_000.mp3", "2026-08-09_120224_000.mp3",
            "2026-08-10_082255_000.wav"], _tapes
        # A raw wav with no transcode yet is not ready; the mp3s are.
        assert not tape_ready(_tapes[2]) and tape_ready(_tapes[0])
        assert mixtape_title(_tapes[0]).startswith("MX tape · August"), (
            mixtape_title(_tapes[0]))
        _RADIO.setdefault("recent", {}).pop("tape", None)
        _one = mixtape_pick()
        assert _one and _one["tape"] and _one["url"].startswith("/tape/")
        assert mixtape_pick()["id"] != _one["id"], "never the same tape twice"
        # ...and the unready wav is never the pick while an mp3 stands ready.
        _wav_id = sfx_id(_tapes[2])
        assert all(mixtape_pick()["id"] != _wav_id for _ in range(6))
    finally:
        for _leftover in _tapedir.iterdir():
            _leftover.unlink()
        _tapedir.rmdir()
        globals()["SFX_ROOT"] = _sfx_root_was2
        globals()["dj_settings"] = _real_dj2
        globals()["_tape_transcode_soon"] = _transcode_was
        _RADIO.setdefault("recent", {}).pop("tape", None)
    # The mail interrupts the queue: with the counter run down, the next
    # pick IS the tape, and an ordinary pick winds the counter back up.
    # #828/#829: eight by default now, and the slider reaches forty — the
    # old clamp of ten was the reason a rarer setting would not save.
    assert DEFAULT_DJ["mixtape_every"] == 8
    assert validate_settings(
        {**DEFAULT_SETTINGS, "dj": {**DEFAULT_DJ, "mixtape_every": 40}}
    )["dj"]["mixtape_every"] == 40

    # #840: the guard that keeps an automatic cut off a turning record.
    # Nothing on the needle → allowed, because dead-air recovery must
    # never be blocked; ten seconds into a five minute record → refused;
    # the run-out groove of the same record → allowed, it was ending.
    _cut_was = (_RADIO.get("on"), _RADIO.get("now"), _RADIO.get("started"))
    try:
        _RADIO["on"] = True
        _RADIO["now"] = None
        assert track_may_cut("selfcheck: nothing on the needle")
        _RADIO["now"] = {"id": "sc", "title": "Selfcheck", "seconds": 300}
        _RADIO["started"] = time.time() - 10.0
        assert not track_may_cut("selfcheck: ten seconds in")
        _RADIO["started"] = time.time() - 296.0
        assert track_may_cut("selfcheck: the run-out groove")
    finally:
        (_RADIO["on"], _RADIO["now"], _RADIO["started"]) = _cut_was

    # The caller vocoder: a stranger's mangle is stable and scaled by the
    # depth, the master switch silences the whole rack, and every character
    # actually runs through the real ffmpeg.
    assert _pitch_chain(0, 22050) == ""
    assert "asetrate" in _pitch_chain(-4, 22050)
    _real_dj3 = dj_settings
    globals()["dj_settings"] = lambda: {
        **DEFAULT_DJ, "caller_fx": True, "caller_fx_depth": 100}
    try:
        _m1 = caller_mangle({"name": "Big Ron"})
        assert _m1 == caller_mangle({"name": "Big Ron"}), "stable per name"
        assert _m1 != caller_mangle({"name": "Doreen"}), "varied across names"
        assert caller_mangle({"name": "x", "character": "child"}) == {
            "character": "child", "pitch": 7}, "a child sounds like one"
        globals()["dj_settings"] = lambda: {
            **DEFAULT_DJ, "caller_fx": False, "caller_fx_depth": 100}
        assert caller_mangle({"name": "Big Ron", "character": "robot",
                              "pitch": 9}) == {
            "character": "plain", "pitch": 0}, "the master switch kills all"
        globals()["dj_settings"] = lambda: {
            **DEFAULT_DJ, "caller_fx": True, "caller_fx_depth": 0}
        _flat = caller_mangle({"name": "Big Ron"})
        assert _flat["character"] == "plain" and abs(_flat["pitch"]) <= 7, (
            "at depth zero the strangers ring in straight")
    finally:
        globals()["dj_settings"] = _real_dj3
    # Every character must actually run: real ffmpeg, real audio out.
    import io as _vio
    import wave as _vw
    _vsrc = _vio.BytesIO()
    with _vw.open(_vsrc, "wb") as _d:
        _d.setnchannels(1); _d.setsampwidth(2); _d.setframerate(22050)
        _d.writeframes(b"\x00\x28" * 11025)
    _vdry = _vsrc.getvalue()
    for _name in VOCODER_CHARACTERS:
        _vwet = vocode_process(_vdry, _name, 3, 22050)
        assert _vwet != _vdry and len(_vwet) > 1000, _name
        with _vw.open(_vio.BytesIO(_vwet)) as _r:
            assert _r.getframerate() == 22050, _name
    assert vocode_process(_vdry, "plain", 0, 22050) == _vdry

    # The call-in desk (#236, #237): the roster survives, the strangers get
    # names, the same caller always gets the same voice, and the split knows
    # a third speaker when it sees one.
    _callers_was = CALLERS_PATH
    globals()["CALLERS_PATH"] = Path("/tmp/callers-selfcheck.json")
    CALLERS_PATH.unlink(missing_ok=True)
    try:
        _reg = add_caller("Big Ron", "shouts", "wants requests played")
        assert read_callers()[0]["name"] == "Big Ron"
        assert conjure_caller()["name"], "the dictionary must always answer"
        _v1 = caller_voice_for("Big Ron", {"en_US-amy-low"})
        assert _v1 and _v1 == caller_voice_for("Big Ron", {"en_US-amy-low"})
        assert _v1 != "en_US-amy-low", "never the pair's own voice"
    finally:
        CALLERS_PATH.unlink(missing_ok=True)
        globals()["CALLERS_PATH"] = _callers_was
    _turns = banter_turns("A: Hello. C: It is me. C: Still me. B: Right.")
    assert [t[0] for t in _turns] == ["A", "C", "C", "B"], _turns
    # The phone line: crushed, hissed, and still a legible wav.
    import io as _pio
    import wave as _pw
    _pdry = _pio.BytesIO()
    with _pw.open(_pdry, "wb") as _d:
        _d.setnchannels(1); _d.setsampwidth(2); _d.setframerate(22050)
        _d.writeframes(b"\x00\x30" * 5000)
    _pdry = _pdry.getvalue()
    _phone = voice_effect_apply(_pdry, ".wav", {"delay": 0.08, "echo": 0.3,
                                                "room": 0.2, "static": 0.8,
                                                "phone": 1})
    assert len(_phone) > len(_pdry) and _phone != _pdry
    with _pw.open(_pio.BytesIO(_phone)) as _r:
        assert _r.getframerate() == 22050
    _ring_was = SFX_MADE_DIR
    globals()["SFX_MADE_DIR"] = Path("/tmp/ring-selfcheck")
    try:
        _ring = make_phone_ring()
        assert _ring is not None and _ring.stat().st_size > 20000
        with _pw.open(str(_ring)) as _r:
            assert 1.5 < _r.getnframes() / _r.getframerate() < 3.0
    finally:
        for _leftover in Path("/tmp/ring-selfcheck").glob("*"):
            _leftover.unlink()
        Path("/tmp/ring-selfcheck").rmdir()
        globals()["SFX_MADE_DIR"] = _ring_was

    # The whole page gets covered, not just the masthead (#248): fresh
    # stories first, the lead keeps its place in the bulletin, and nothing
    # repeats until the page has been worked through.
    _RADIO.setdefault("recent", {})["news"] = []
    _page20 = [{"title": f"STORY NUMBER {n} IN CAPITAL LETTERS TODAY",
                "url": f"https://example.com/{n}"} for n in range(20)]
    _b1 = news_selection(_page20, hourly=True)
    assert _b1[0] == _page20[0] and len(_b1) == 5, _b1
    _b2 = news_selection(_page20, hourly=False)
    _t1 = {h["title"] for h in _b1}
    _t2 = {h["title"] for h in _b2}
    assert len(_b2) == 3 and not (_t1 & _t2), "no repeats yet"
    _seen = _t1 | _t2
    for _ in range(4):
        _seen |= {h["title"] for h in news_selection(_page20, hourly=False)}
    assert len(_seen) == 20, f"the whole page should get covered, saw {len(_seen)}"
    assert news_selection([], hourly=True) == []
    _RADIO["recent"]["news"] = []

    # The news desk reads headlines out of museum-grade HTML (#228, #229).
    _page = """
    <a href="https://x.example/1"><font size=+7>MARKET <b>ROUT</b> DEEPENS AS BANKS WOBBLE</font></a>
    <a href="https://x.example/2">DRUDGE REPORT</a>
    <a href="https://x.example/3">STORM SLAMS COAST; MILLIONS WITHOUT POWER IN THE DARK...</a>
    <a href="mailto:drudge@example.com">A STORY WHOSE LINK GOES NOWHERE USABLE</a>
    <a href="https://x.example/4">SHOCK POLL: EVERYONE TIRED OF POLLS, POLL FINDS</a>
    <a href="https://x.example/5">REUTERS</a>
    """
    _heads = drudge_parse(_page)
    assert _heads[0]["title"].startswith("MARKET ROUT"), _heads
    assert len(_heads) == 3, _heads
    assert all("DRUDGE" not in h["title"] and "<" not in h["title"]
               for h in _heads), _heads
    assert all(h["url"].startswith("http") for h in _heads), (
        "every story keeps its link — the desk goes INTO the article now")
    assert drudge_parse("<html>nothing here</html>") == []

    # #921: the page cap is passed through, the masthead roll is dropped,
    # and the draw is RANDOM across everything rather than off the top.
    _furn = """
    <a href="https://x.example/9">A REAL STORY WITH ENOUGH WORDS IN IT</a>
    <a href="https://wsj.example/">WALL STREET JOURNAL</a>
    <a href="https://afp.example/en/timeline/">AGENCE FRANCE-PRESSE</a>
    """
    _f = drudge_parse(_furn)
    assert len(_f) == 1 and _f[0]["title"].startswith("A REAL"), _f
    _long = "".join(f'<a href="https://e.example/{n}">HEADLINE NUMBER {n} '
                    "ON THE PAGE TODAY</a>" for n in range(40))
    assert len(drudge_parse(_long)) == 24, (
        "the default cap still stands where nobody raises it")
    assert len(drudge_parse(_long, NEWS_PAGE_MOST)) == 40, (
        "#921: drudge_headlines asks for the whole page, and the cap "
        "that silently threw two thirds of it away is passed through")
    # Forty stories that share ONE keyword and no more, so the topic
    # ledger's own two-keyword rule does not call them all the same news.
    _wide = [{"title": (chr(97 + n // 10) * 2
                        + chr(97 + n % 10) * 3).upper() + " STORY",
              "url": f"https://example.com/w{n}"} for n in range(40)]
    _NEWS_COVERED_WAS = NEWS_COVERED_PATH
    globals()["NEWS_COVERED_PATH"] = Path("/tmp/news-covered-selfcheck.json")
    try:
        _avoid: list[str] = []
        _first = news_draw(_wide, 3, _avoid)
        assert len(_first) == 3 and not _avoid, _first
        _avoid.extend(h["title"] for h in _first)
        _second = news_draw(_wide, 3, _avoid)
        assert not ({h["title"] for h in _first}
                    & {h["title"] for h in _second}), (
            "#921: a stretch must never re-tell the one before it")
        assert news_draw([], 3, []) == []
        # It reaches the FAR END of the page, which is the whole
        # complaint — "always leading with the same top story". Eighteen
        # picks out of forty landing entirely in the front half is a
        # one-in-a-billion draw, so this tests random without flaking.
        _reach: set = set()
        for _ in range(6):
            _reach |= {h["title"] for h in news_draw(_wide, 3, [])}
        assert _reach & {h["title"] for h in _wide[20:]}, sorted(_reach)
        # And with the whole page covered it reaches for the coolest
        # rather than going quiet — still never re-telling this segment.
        for _ in range(20):
            news_draw(_wide, 3, [])
        _held = [h["title"] for h in _wide[:37]]
        _last = news_draw(_wide, 3, list(_held))
        assert _last, "an exhausted page must not silence the segment"
        assert not ({h["title"] for h in _last} & set(_held)), (
            "#921: the exhausted-page road must still honour `avoid`")
    finally:
        try:
            Path("/tmp/news-covered-selfcheck.json").unlink()
        except OSError:
            pass
        globals()["NEWS_COVERED_PATH"] = _NEWS_COVERED_WAS

    # #920: the archive's span math is the sheet's own walk. A disabled
    # entry costs the clock nothing and the ones after it do not move.
    _hkey = _sched_hour_key()
    _hview = schedule_hours_view(_hkey, 1)["hours"][0]
    for _tile in _hview["slots"]:
        assert "past" in _tile and "starts_epoch" in _tile, _tile
        if _tile["starts_epoch"]:
            assert _tile["ends_epoch"] > _tile["starts_epoch"], _tile
            _sp = hour_slot_span(_hkey, _tile["id"])
            assert _sp["ok"] and abs(_sp["from"]
                                     - _tile["starts_epoch"]) < 0.01, _sp
    assert not hour_slot_span("not-an-hour", "x")["ok"]
    assert not hour_slot_span(_hkey, "no-such-slot")["ok"]

    # Every settings key the routes read must actually exist: renaming one
    # and missing a use site is a 500 that only shows up when you click it.
    _dj_keys = dj_settings()
    for _needed in ("speakbox_weights", "sfx", "sfx_make", "sfx_folders",
                    "sfx_rate", "sfx_gap", "fx_rate", "fx_min", "fx_max",
                    "banter_min_lines", "banter_max_lines", "speakbox_rate",
                    "saved_rate", "banter_min_minutes", "banter_max_minutes"):
        assert _needed in _dj_keys, _needed
    assert not set(re.findall(r'dj_settings\(\)\["(\w+)"\]',
                              Path(__file__).read_text())) - set(_dj_keys), (
        "a settings key is read somewhere that validate_settings never sets")

    # A document dropped in the folder is in their mouths on the next round,
    # and a line they have already used waits behind one they have not.
    _dir_was, _heard_was = SPEAKBOX_DIR, SPEAKBOX_HEARD
    globals()["SPEAKBOX_DIR"] = Path("/tmp/speakbox-selfcheck")
    globals()["SPEAKBOX_HEARD"] = SPEAKBOX_DIR / "heard.json"
    SPEAKBOX_DIR.mkdir(parents=True, exist_ok=True)
    # Start from empty however the last run ended. A check that fails halfway
    # leaves its scratch behind, and the next run then fails on the leftovers
    # with a different error than the one that broke it.
    for _leftover in SPEAKBOX_DIR.iterdir():
        _leftover.unlink()
    assert asyncio.run(speakbox_quote()) == {}    # empty folder, no invention
    _old = "One line that is quite long enough to be said out loud."
    (SPEAKBOX_DIR / "a.md").write_text(
        _old + " Another line that is also long enough to be worth saying.")
    assert asyncio.run(speakbox_quote()).get("file") == "a.md"  # found without a reload
    speakbox_remember({"file": "a.md", "text": _old})
    speakbox_remember({"file": "a.md", "text": _old})
    assert [r["used"] for r in speakbox_heard()] == [2]
    speakbox_remember({})                          # nothing said, nothing kept
    assert len(speakbox_heard()) == 1
    assert asyncio.run(speakbox_quote())["text"].startswith("Another line")
    # A swath is remembered line by line, or its gems come straight back in
    # the next swath cut one line to either side (#235).
    speakbox_remember({"file": "a.md", "text": "First bit. Second bit.",
                       "lines": ["First bit.", "Second bit."]})
    _texts = [r["text"] for r in speakbox_heard()]
    assert "First bit." in _texts and "Second bit." in _texts, _texts
    assert "First bit. Second bit." not in _texts
    # With one document, excluding it must not silence the draw (#233).
    _q = asyncio.run(speakbox_quote(exclude="a.md"))
    assert _q.get("file") == "a.md", _q
    # Long verbatim turns are read out IN FULL: sentence-safe pieces, never
    # a mid-word slice — the compliant turns were the ones being punished.
    _long = ("First sentence of the passage. " * 6
             + "Second thought, also complete. " * 6).strip()
    _pieces = sentence_chunks(_long)
    assert "".join(_pieces).replace(" ", "") == _long.replace(" ", ""), (
        "every character of a compliant turn must air")
    assert all(len(c) <= 300 for c in _pieces), [len(c) for c in _pieces]
    assert all(c.rstrip()[-1] in ".!?…—" for c in _pieces), _pieces
    assert sentence_chunks("short one.") == ["short one."]
    _endless = "word " * 200
    assert all(len(c) <= 300 for c in sentence_chunks(_endless))
    assert sentence_chunks("") == []

    # A scene carries the moment whole cloth, the struggle arc, the pivot
    # and the last word, with nothing left unfilled (#252, #253).
    _RADIO.setdefault("recent", {}).clear()
    _scene = speakbox_scene_angle(
        {"file": "x.md", "text": "the whole revelation"},
        {"file": "y.md", "text": "the swerve from elsewhere"},
        {"file": "z.md", "text": "the last word"})
    for _needed in ("WHOLE CLOTH", "the whole revelation",
                    "the swerve from elsewhere", "the last word",
                    "coming to terms", "refusing to believe",
                    "managing a real comeback", "soaked"):
        assert _needed in _scene, _needed
    assert "{" not in _scene
    assert "blindsides" in _scene
    _bare = speakbox_scene_angle({"file": "x.md", "text": "just the one"})
    assert "Midway" not in _bare and "last word" not in _bare
    _RADIO["recent"].clear()

    # The comeback rides in the angle, word for word, for the other one.
    _RADIO.setdefault("recent", {}).clear()
    _both = speakbox_angle({"file": "x.md", "text": "the thing itself"},
                           {"file": "y.md", "text": "the other thing"})
    assert "the thing itself" in _both and "the other thing" in _both
    assert "WORD FOR WORD" in _both and "OWN" in _both, _both
    _RADIO["recent"].clear()

    # Run the angle machinery for real, with the model and the voice stubbed
    # out. Every round goes through it, so a missing argument in that chain
    # takes the whole show off air — and nothing else in here would have
    # noticed, because none of these checks used to reach it.
    async def _stub_model(prompt: str, limit: int = 300) -> str:
        assert "\x00" not in prompt
        return "A: First thing. B: Second thing."

    async def _stub_speak(kind, track=None, extra="", line="", who="dj",
                          voice=None, source="", by_hand=False, fx=None,
                          name="", source_text=""):
        return line or "said"

    async def _stub_voices() -> dict[str, str]:
        return {"dj": "en_US-amy-low", "cohost": "en_US-joe-medium"}

    _saved = {n: globals()[n] for n in
              ("ask_model", "dj_speak", "session_voices", "read_bombshells",
               "draw_saved_banter")}
    globals().update(ask_model=_stub_model, dj_speak=_stub_speak,
                     session_voices=_stub_voices, read_bombshells=lambda: [],
                     # The live approved bank must not steer a self-check —
                     # a kept one-liner coming back makes len(round) flap.
                     draw_saved_banter=lambda: {})
    try:
        _rounds = [asyncio.run(dj_banter({"title": "T", "seconds": 100}, lines=2))
                   for _ in range(8)]   # both the seeded and the stock path
        assert all(len(r) == 2 for r in _rounds), _rounds
        assert asyncio.run(dj_banter(None, angle="talk about the weather"))
    finally:
        globals().update(_saved)

    for _leftover in SPEAKBOX_DIR.iterdir():
        _leftover.unlink()
    SPEAKBOX_DIR.rmdir()
    globals()["SPEAKBOX_DIR"], globals()["SPEAKBOX_HEARD"] = _dir_was, _heard_was
    # A file name is a file name; nothing climbs out of the speakbox.
    for _bad in ("../settings.json", "a/b.md", ".md", "notes.txt", ""):
        try:
            speakbox_path(_bad)
            raise AssertionError(f"speakbox_path let {_bad!r} through")
        except HTTPException:
            pass
    assert speakbox_path("chap.md").parent == SPEAKBOX_DIR
    # A reply that ran out of tokens loses its half-finished last line (#168).
    assert banter_turns("A: One. B: Two. A: and then he")[-1][1] == "Two."
    # Two in a row under the same marker is the other one talking (#200) —
    # a DJ answering himself is not a conversation.
    assert [t[0] for t in banter_turns("A: One. A: Two. A: Three.")] == [
        "A", "B", "A"]
    assert [t[1] for t in banter_turns("A: One. A: Two.")] == ["One.", "Two."]
    # Sliders dragged past each other come back sorted, not broken (#202).
    assert _dj_range({"banter_min_minutes": 9, "banter_max_minutes": 2},
                     "banter_min_minutes", "banter_max_minutes", 0, 60) == {
        "banter_min_minutes": 2, "banter_max_minutes": 9}
    assert _dj_range({"banter_min_lines": "x"}, "banter_min_lines",
                     "banter_max_lines", 2, 12)["banter_min_lines"] == (
        DEFAULT_DJ["banter_min_lines"])
    # The 45-second floor survives the wash un-floored (#352).
    assert _dj_range({}, "banter_min_minutes", "banter_max_minutes",
                     0, 60, whole=False)["banter_min_minutes"] == 0.75
    # They open with one, then keep off the metronome (#202).
    _RADIO.pop("banter_due", None)
    _cadence = {"banter": True, "banter_min_minutes": 3,
                "banter_max_minutes": 5, "banter_every": 1}
    assert banter_due(_cadence, 1), "the show should open with a round"
    assert not banter_due(_cadence, 2), "and the next one waits its turn"
    assert _RADIO["banter_due"] - time.time() >= 3 * 60 - 1
    assert not banter_due({**_cadence, "banter": False}, 1)
    _RADIO.pop("banter_due", None)
    # With the minutes switched off, older every-N-tracks settings still work.
    _counted = {**_cadence, "banter_max_minutes": 0, "banter_every": 2}
    assert banter_due(_counted, 2) and not banter_due(_counted, 3)
    _RADIO.pop("banter_due", None)

    # Echo and reverb: a tail is added, the line survives, and it is never
    # the same wash twice (#222).
    import io as _io, wave as _w3
    _dry = _io.BytesIO()
    with _w3.open(_dry, "wb") as _d:
        _d.setnchannels(1); _d.setsampwidth(2); _d.setframerate(22050)
        _d.writeframes(b"\x00\x40" * 6000)
    _dry = _dry.getvalue()
    _wet = voice_effect_apply(_dry, ".wav", {"delay": 0.12, "echo": 0.5,
                                             "room": 0.3})
    assert len(_wet) > len(_dry), "an echo has a tail"
    with _w3.open(_io.BytesIO(_wet)) as _r:
        assert _r.getframerate() == 22050 and _r.getsampwidth() == 2
    assert voice_effect_apply(_dry, ".wav", {}) == _dry      # dry stays dry
    assert voice_effect_apply(b"not audio", ".mp3",
                              {"delay": 0.1, "echo": 0.5, "room": 0.2}) == (
        b"not audio")                    # anything unreadable is left alone
    _fx_real = dj_settings
    globals()["dj_settings"] = lambda: {**DEFAULT_DJ, "fx_rate": 0.0}
    assert voice_effect_pick() == {}     # switched off means dry
    globals()["dj_settings"] = lambda: {**DEFAULT_DJ, "fx_rate": 1.0,
                                        "fx_min": 40, "fx_max": 40}
    _picks = [voice_effect_pick() for _ in range(6)]
    assert all(p and p["echo"] > 0 for p in _picks), _picks
    assert len({round(p["delay"], 4) for p in _picks}) > 1, "never the same"
    globals()["dj_settings"] = _fx_real

    # A scratch made here is a real, short, playable wav, and every one is
    # different from the last (#211).
    _made_was = SFX_MADE_DIR
    globals()["SFX_MADE_DIR"] = Path("/tmp/sfx-made-selfcheck")
    try:
        _one, _two = make_scratch(seed=1), make_scratch(seed=2)
        assert _one and _two and _one.read_bytes() != _two.read_bytes()
        assert make_scratch(seed=1).read_bytes() == _one.read_bytes(), (
            "the same seed must give the same scratch")
        import wave as _w2
        with _w2.open(str(_one)) as _s:
            _secs = _s.getnframes() / _s.getframerate()
            assert 0.2 < _secs < 1.0, _secs      # a scratch, not a drone
            assert _s.getsampwidth() == 2 and _s.getnchannels() == 1
        assert sfx_short(_one), "a made scratch must count as a sting"
        assert len(scratch_stock(want=5)) >= 5
    finally:
        for _leftover in SFX_MADE_DIR.glob("*"):
            _leftover.unlink()
        SFX_MADE_DIR.rmdir()
        globals()["SFX_MADE_DIR"] = _made_was

    # A hot sample is levelled before it goes out, so a scratch does not
    # arrive several times louder than the voice that set it up (#220).
    import audioop
    import wave as _wave
    _loud = Path("/tmp/sfx-level-selfcheck.wav")
    with _wave.open(str(_loud), "wb") as _w:
        _w.setparams((1, 2, 22050, 0, "NONE", "not compressed"))
        _w.writeframes(b"\xff\x7f" * 2000)      # full-scale, as hot as it gets
    _level_root_was = SFX_LEVELLED
    globals()["SFX_LEVELLED"] = Path("/tmp/sfx-level-selfcheck")
    _quieter = sfx_levelled(_loud)
    assert _quieter != _loud, "a full-scale sample must be brought down"
    with _wave.open(str(_quieter)) as _q:
        _frames = _q.readframes(_q.getnframes())
    # Equalized to the SFX loudness target (under the voice's 5200) with the
    # peak inside its cap, so no sting arrives loud and obnoxious.
    assert audioop.rms(_frames, 2) <= SFX_RMS * 1.1, audioop.rms(_frames, 2)
    assert audioop.max(_frames, 2) / 32767 <= SFX_PEAK + 0.02, \
        audioop.max(_frames, 2) / 32767
    assert sfx_levelled(_loud) == _quieter      # cached, not redone
    # The sample packs are mp3, and an mp3 that skips levelling is the
    # loudest thing in the folder (#225). Only checked where the decoder is
    # actually installed — without it the sample still plays, just raw.
    _an_mp3 = next(iter(sorted(
        (SFX_ROOT / "Sample Packs" / "lounge - sfx").glob("*.mp3"))), None)
    if _an_mp3 is not None and _as_wav(_an_mp3) != _an_mp3:
        _levelled = sfx_levelled(_an_mp3)
        assert _levelled.suffix == ".wav" and _levelled != _an_mp3
        with _wave.open(str(_levelled)) as _m:
            _mp = audioop.max(_m.readframes(_m.getnframes()),
                              _m.getsampwidth()) / 32767
        assert 0.0 < _mp <= SFX_PEAK + 0.02, _mp
    assert sfx_levelled(Path("/tmp/not-a-wav-at-all.mp3")) == Path(
        "/tmp/not-a-wav-at-all.mp3")            # unreadable plays as it is
    for _leftover in SFX_LEVELLED.iterdir():
        _leftover.unlink()
    SFX_LEVELLED.rmdir()
    _loud.unlink()
    globals()["SFX_LEVELLED"] = _level_root_was

    # Stingers: nothing outside the sample share, and never two in a row
    # inside the gap (#208).
    _sfx_root_was = SFX_ROOT
    globals()["SFX_ROOT"] = Path("/tmp/sfx-selfcheck")
    (SFX_ROOT / "pack").mkdir(parents=True, exist_ok=True)
    for _name in ("scratch.wav", "LASER.WAV", "notes.txt"):
        (SFX_ROOT / "pack" / _name).write_bytes(b"RIFF")
    _real_dj = dj_settings
    # Made scratches are tested on their own below; here we are checking the
    # folders, so keep the generator out of the pool.
    globals()["dj_settings"] = lambda: {
        **DEFAULT_DJ, "sfx_folders": ["pack"], "sfx_make": False}
    _found = [p.name for p in sfx_all()]
    assert sorted(_found) == ["LASER.WAV", "scratch.wav"], _found
    globals()["dj_settings"] = lambda: {
        **DEFAULT_DJ, "sfx_make": False,
        "sfx_folders": ["../../etc", "/etc", "pack/../pack"]}
    assert all(p.name in ("LASER.WAV", "scratch.wav") for p in sfx_all()), (
        "a folder outside the share must never be reachable")
    globals()["dj_settings"] = lambda: {
        **DEFAULT_DJ, "sfx_folders": ["pack"], "sfx_rate": 1.0, "sfx_gap": 40,
        "sfx_make": False}
    _STING_AT[0] = 0.0
    assert sting_due() is not None      # rate 1.0: the first one always fires
    _STING_AT[0] = time.time()
    assert sting_due() is None          # ...and never twice inside the gap
    _STING_AT[0] = 0.0
    globals()["dj_settings"] = lambda: {**DEFAULT_DJ, "sfx": False,
                                        "sfx_make": False}
    assert sting_due() is None          # switched off means switched off
    globals()["dj_settings"] = _real_dj
    for _leftover in (SFX_ROOT / "pack").iterdir():
        _leftover.unlink()
    (SFX_ROOT / "pack").rmdir()
    SFX_ROOT.rmdir()
    globals()["SFX_ROOT"] = _sfx_root_was
    _RADIO.setdefault("recent", {}).clear()

    # A line you buried stays buried, however it is punctuated next time
    # round, and it leaves the approved bank with it (#215).
    _binned_was, _saved_was2 = BINNED_PATH, SAVED_BANTER_PATH
    globals()["BINNED_PATH"] = Path("/tmp/binned-selfcheck.json")
    globals()["SAVED_BANTER_PATH"] = Path("/tmp/saved-binned-selfcheck.json")
    BINNED_PATH.unlink(missing_ok=True)
    SAVED_BANTER_PATH.unlink(missing_ok=True)
    try:
        _kept = add_saved_banter("A: He buys the pine boxes in bulk!")
        assert not is_binned("something else entirely")
        bin_line("he buys the pine boxes in BULK.")
        assert is_binned("He buys the pine boxes, in bulk!"), read_binned()
        assert not any(r["id"] == _kept["id"] for r in read_saved_banter()), (
            "burying a line must take it out of the approved bank too")
        assert not is_binned("")
    finally:
        BINNED_PATH.unlink(missing_ok=True)
        SAVED_BANTER_PATH.unlink(missing_ok=True)
        globals()["BINNED_PATH"] = _binned_was
        globals()["SAVED_BANTER_PATH"] = _saved_was2

    # Approved banter: written by hand, kept, aired least-used first (#202).
    _saved_was = SAVED_BANTER_PATH
    globals()["SAVED_BANTER_PATH"] = Path("/tmp/banter-saved-selfcheck.json")
    SAVED_BANTER_PATH.unlink(missing_ok=True)
    assert add_saved_banter("he never pays for the coffee")["text"] == (
        "A: he never pays for the coffee")     # a plain line still gets a mouth
    assert add_saved_banter("A: one. B: two.")["text"] == "A: one. B: two."
    _drawn = draw_saved_banter()
    assert _drawn and sum(
        int(r["used"]) for r in read_saved_banter()) == 1
    assert draw_saved_banter()["id"] != _drawn["id"], "the unaired one is next"
    delete_saved_banter(_drawn["id"])
    assert [r["id"] for r in read_saved_banter()] != [_drawn["id"]]
    assert len(read_saved_banter()) == 1
    SAVED_BANTER_PATH.unlink(missing_ok=True)
    globals()["SAVED_BANTER_PATH"] = _saved_was

    # The health popup reports these three, and each dict spells its reason
    # under its own key. Reading the wrong one prints "reached the box"
    # whatever happened, which is worse than no instrument at all (#206).
    assert "why" in speak_health()
    assert "error" in announce_health()
    assert isinstance(satellite_healed_at(), float)

    # The show must not mistake its own voice for a stranger's (#206).
    _SPOKE_AT[0] = time.time()
    assert not _busy_with_someone("responding"), "that is our own patter"
    assert not _busy_with_someone("idle")
    assert _busy_with_someone("listening"), "somebody is at the microphone"
    assert _busy_with_someone("processing")
    _SPOKE_AT[0] = time.time() - 60
    assert _busy_with_someone("responding"), "nobody here spoke; it is theirs"
    _SPOKE_AT[0] = 0.0

    # A line with no letters in it makes Piper hand back zero bytes, and Home
    # Assistant then sits on the speaker reading a RIFF header out of an
    # empty file (#206). These all reduce to nothing sayable.
    for _empty in ("—", "— — —", "...", " -- ", "*", "[pause]"):
        assert not re.search(r"[^\W_]", spoken_text(_empty)), _empty
    assert re.search(r"[^\W_]", spoken_text("—I would never—"))

    # The other one has to deal with the line, not talk past it (#207).
    _RADIO.setdefault("recent", {}).clear()
    _gem = speakbox_angle({"file": "x.md", "text": "the thing itself"})
    assert any(e in _gem for e in SPEAKBOX_ENGAGE), _gem
    assert "does not change the subject" in _gem
    _aside = speakbox_aside({"file": "x.md", "text": "the thing itself"})
    assert any(e in _aside for e in SPEAKBOX_ENGAGE), _aside
    # A drop that tells the other one not to react would fight the line above.
    assert not any("gets no reaction" in d for d in SPEAKBOX_DROPS)
    for _drop in SPEAKBOX_DROPS + SPEAKBOX_MONOLOGUE:
        _filled = _drop.format(first="A", other="B")   # every slot fillable
        assert "{" not in _filled, _drop
    # A speech gives one of them the floor and the other the last word.
    _RADIO.setdefault("recent", {}).clear()
    _speeches = [speakbox_angle({"file": "x.md", "text": "the thing"})
                 for _ in range(40)]
    assert any("does not give it back" in a or "start to finish" in a
               or "holding the best of it back" in a for a in _speeches), (
        "a monologue should come round")
    assert all(a[0] in "AB" for a in _speeches)        # still names a speaker
    _RADIO["recent"].clear()
    _RADIO["recent"].clear()

    # A model stuck in a loop must not read all forty of them out on air.
    _loop = spoken_text("hang on —what " * 18)
    assert _loop.count("what") <= 3, _loop
    assert len(spoken_text("ha " * 40).split()) <= 3
    assert spoken_text("that is that") == "that is that"   # not a stutter
    assert spoken_text("no no, I said no") == "no no, I said no"
    assert spoken_text("It runs three minutes and twenty seconds flat.") == (
        "It runs three minutes and twenty seconds flat.")
    assert banter_turns("A: only line, cut off")[0][1] == "only line, cut off"
    # Nothing half-said reaches the speaker (#168).
    assert whole_sentences("One. Two. And then he") == "One. Two."
    assert whole_sentences('He said "stop it!" So I') == 'He said "stop it!"'
    assert whole_sentences("NONE") == "NONE"          # nothing finished: keep
    # Only the record that is actually playing may be named (#176, #178).
    _ok = ["Knowledge by Iacon"]
    assert names_only('She asked for "Knowledge" three times', _ok)
    assert not names_only('She wanted "Blue Monday" at 3am', _ok)
    assert names_only("No titles in this one at all", _ok)
    assert names_only('Anything goes when "nothing" is on air', [])
    # Quoting a whole sentence back is how the other one answers a line that
    # was dropped on him, and it is not a record title (#207).
    assert names_only(
        'You actually said "I can still feel his head in my hand and it was '
        'spongy"? On air?', _ok)
    assert not names_only('She wanted "Blue Monday" at 3am', _ok)
    # A thumbs up has to reach the queue, or the button is decorative (#181).
    _pool = [{"id": str(i), "station": "all"} for i in range(200)]
    _real_index, _real_votes = music_index, read_votes
    globals()["music_index"] = lambda force=False: _pool
    globals()["read_votes"] = lambda: {"7": {"vote": 1}, "8": {"vote": -1}}
    _fills = [[t["id"] for t in radio_fill("all")] for _ in range(20)]
    globals()["music_index"], globals()["read_votes"] = _real_index, _real_votes
    # Unbiased its mean position would be ~100; the bias puts it around 30.
    _mean = sum(f.index("7") for f in _fills) / len(_fills)
    assert _mean < 60, f"a loved track should come round often, got {_mean}"
    assert all("8" not in f for f in _fills), "a banned track never queues"
    # Two top-level defs sharing a name means the later one silently wins.
    # That is how Piper synthesis ended up calling the blocking transcribe
    # helper and dying on dict("synthesize"), with no voice out of either
    # output and nothing in the log to say why (#182).
    import ast as _ast
    _seen_defs: dict[str, int] = {}
    _shadowed = []
    for _node in _ast.parse(Path(__file__).read_text()).body:
        if isinstance(_node, (_ast.FunctionDef, _ast.AsyncFunctionDef)):
            if _node.name in _seen_defs:
                _shadowed.append(
                    f"{_node.name} (lines {_seen_defs[_node.name]}"
                    f" and {_node.lineno})")
            _seen_defs[_node.name] = _node.lineno
    assert not _shadowed, "shadowed top-level defs: " + ", ".join(_shadowed)
    # A busy box and a dead Wyoming link both answer with a bare 500, so wait
    # before rebuilding the link — rebuilding on a collision is what made the
    # speaker flaky (#182).
    _trouble = "500 Internal Server Error\n\nServer got itself in trouble"
    assert say_retry_plan(0, 500, _trouble) == (True, 2.0, False)
    assert say_retry_plan(1, 500, _trouble) == (True, 4.0, True)
    assert say_retry_plan(0, 500, "satellite is busy") == (True, 2.0, False)
    assert say_retry_plan(2, 500, "satellite is busy") == (True, 4.0, False)
    assert say_retry_plan(3, 500, _trouble) == (False, 0.0, False)
    assert say_retry_plan(0, 404, "unknown entity") == (False, 0.0, False)
    # The pair keep their voices for the whole session, so the same DJ is not
    # a man one round and a woman the next (#184).
    _real_bv, _draws = banter_voices, [0]

    async def _stub_voices() -> tuple[str, str]:
        _draws[0] += 1
        return f"female{_draws[0]}", f"male{_draws[0]}"

    globals()["banter_voices"] = _stub_voices
    _RADIO["voices"] = {}
    _v1 = asyncio.run(session_voices())
    _v2 = asyncio.run(session_voices())
    globals()["banter_voices"] = _real_bv
    _RADIO["voices"] = {}
    assert _v1 == _v2, f"voices must not change mid-session: {_v1} {_v2}"
    assert _draws[0] == 1, "voices must be drawn once, not once per round"
    # Where to play it is not part of the title (#187).
    assert dj_request_query(
        "request the song The Child Inside on Pine Box FM") == "The Child Inside"
    assert music_request_query(
        "play The Child Inside on pine box fm") == "The Child Inside"
    assert music_request_query("play The Child Inside for me") == "The Child Inside"
    # The phrasings the strict matcher used to drop entirely.
    for _asked in ("request The Child Inside",
                   "I want to hear The Child Inside",
                   "let's hear The Child Inside",
                   "put on The Child Inside"):
        assert DJ_ASKED.search(_asked), f"not recognised as a request: {_asked}"
    # Interrupting on purpose survives; running out of tokens does not (#185).
    assert whole_sentences("Wait, but he actually—") == "Wait, but he actually—"
    assert whole_sentences("One. Two. and then he") == "One. Two."
    assert banter_turns("A: One. B: But hang on—")[-1][1] == "But hang on—"
    assert len(banter_turns("A: One. B: but hang on he")) == 1
    assert banter_gap(0) == 0.7 and banter_gap(100) == 0.0
    assert banter_gap(50) < banter_gap(10)
    assert "em dash" in banter_pace(80) and "clean turns" in banter_pace(0)
    # Picture file names are keywords the pair can use (#191).
    assert _generation_files({"files": "['PineBox_00068_.png']"}) == [
        "PineBox_00068_.png"]
    assert _generation_files({"files": ["a.png", "b.webp"]}) == [
        "a.png", "b.webp"]
    assert _generation_files({}) == []
    # Every domestic story is about something of his, never a blank frame.
    for _angle in domestic_angles(2):
        assert "came to you the other day wanting" in _angle
        assert not _angle.rstrip().endswith("wanting ")
    # A running time the pair invented never goes out (#193).
    assert track_length_phrase({"seconds": 252}) == "4:12 (4 minutes)"
    assert track_length_phrase({"seconds": 0}) == ""
    assert minutes_only("This four-minute song is a favourite", 252)
    assert not minutes_only("This 35 minute song is a favourite", 252)
    assert minutes_only("We are back in five minutes with more", 252)
    assert minutes_only("Anything goes when nothing is on air", None)
    # The opener knows what time it is (#194).
    assert any(word in show_open_when()
               for word in ("morning", "afternoon", "evening", "hours",
                            "late"))
    assert ":" in show_open_when()          # an actual clock, not just a part
    # A track is on air when it starts, not when it is picked (#176, #178).
    # Pointed somewhere harmless first: going on air is logged to disk now,
    # and a self-check has no business in your recently-played list (#203).
    _played_was = PLAYED_PATH
    globals()["PLAYED_PATH"] = Path("/tmp/played-selfcheck.json")
    _RADIO.update({"now": None, "history": [], "coming": {"id": "x"}})
    dj_on_air({"id": "a", "title": "A", "seconds": 10})
    assert _RADIO["now"]["id"] == "a" and not _RADIO["history"]
    assert _RADIO["coming"] is None                # picked is not playing
    dj_on_air({"id": "b", "title": "B", "seconds": 10})
    assert [h["id"] for h in _RADIO["history"]] == ["a"]
    dj_on_air({"id": "b", "title": "B", "seconds": 10})
    assert [h["id"] for h in _RADIO["history"]] == ["a"]   # not twice
    # Hearing something again moves it up the list rather than repeating it.
    assert [r["id"] for r in read_played()] == ["b", "a"], read_played()
    PLAYED_PATH.unlink(missing_ok=True)
    globals()["PLAYED_PATH"] = _played_was
    _RADIO.update({"now": None, "history": [], "coming": None})
    # A missed coalesced booth/call stream keeps its per-turn timeline on the
    # replay shelf; clearing the shelf on reconnect was how dialogue vanished.
    _hold_was = list(_BOX_HOLD)
    _hold_path_was = BOX_HOLD_PATH
    globals()["BOX_HOLD_PATH"] = Path("/tmp/box-hold-selfcheck.json")
    _BOX_HOLD.clear()
    _rows = [{"id": "r1", "who": "dj", "text": "one",
              "from": 0.0, "until": 1.0}]
    box_hold({"path": "/media/abc.wav", "sig": "s", "bytes": 10},
             "round", "dj", rows=_rows, length=1.0)
    assert _BOX_HOLD[0]["rows"] == _rows and _BOX_HOLD[0]["length"] == 1.0
    _src = Path(__file__).read_text(encoding="utf-8")
    assert "if last_batch and not missed:" in _src
    assert ("clips." + "slice(-3)") not in _src
    assert "\"stream\": {\"length\": length, \"rows\": rows}" in _src
    assert "if to_box:\\n                    _stream_now_set(rows, length)" in _src
    assert "if (clip.stream && Array.isArray(clip.stream.rows))" in _src
    BOX_HOLD_PATH.unlink(missing_ok=True)
    globals()["BOX_HOLD_PATH"] = _hold_path_was
    _BOX_HOLD[:] = _hold_was
    print("self-check ok")
